using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    // (its own file: it needs MeshAlphaWrap.ForceProjectionFallback, so the other new alpha wrap tests still compile
    // against the library of the base branch in the "New tests on base" job)
    public class AlphaWrapFallbackTests
    {
        [Fact]
        public void Wrap_ProjectionFallback_KeepsTheGuaranteesAndIsCounted()
        {
            // the fallback of rule 2 (the projection of the clamped end of the dual edge, the old placement) is taken
            // for every rule 2 point here: the wrap keeps its guarantees, every use is counted, and on this input the
            // old placement gives near-coincident Steiner points again (what the projection of the own circumcenter fixes)
            DMesh3 m = AlphaWrapTests.Ellipsoid(5, 0.3, 0.45);
            var w = new MeshAlphaWrap(m) { RelativeAlpha = 150, RelativeOffset = 1500, ForceProjectionFallback = true };
            Assert.True(w.Compute(), w.Error);
            AlphaWrapTests.CheckWrap(w, AlphaWrapTests.Vertices(m));
            Assert.Equal(w.Counts["steiner_projection"] + w.Counts["rejected_rule2"], w.Counts["projection_fallbacks"]);
            Assert.True(w.Counts["projection_fallbacks"] > 0);
            Assert.True(AlphaWrapTests.MinSteinerSeparation(w.Triangulation) < 0.01 * w.UsedOffset);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Hard cases for alpha wrapping (MeshAlphaWrap) from the issue trackers of other libraries (docs/QA.md 2.11): only
    /// the failure mode, rebuilt here from simple primitives. CGAL is GPL and MeshLib source-available: only the prose of
    /// their issues was read, no code, test code or meshes. The issue URL is in the comment of each test.
    ///
    /// Every case checks the wrap's guarantees with AlphaWrapTests.CheckWrap (closed, manifold, outward, no
    /// self-intersections, vertices on the offset surface, every sampled point within offset + 2 alpha, the input
    /// enclosed) and case-specific results (components, distances). No case fails today; a failing one would be listed
    /// in KnownFailures with its finding (strict: a listed case that passes fails).
    /// </summary>
    public class AlphaWrapIssueCasesTests
    {
        /// <summary> case name -> finding; a listed case must still fail </summary>
        public static readonly Dictionary<string, string> KnownFailures = new Dictionary<string, string> {
        };

        static void Expect(string name, Action check)
        {
            string failure = "";
            try { check(); } catch (Exception e) when (e is Xunit.Sdk.XunitException) { failure = e.Message; }
            if (KnownFailures.TryGetValue(name, out string finding)) {
                if (!IssueCases.Strict) return;
                Assert.True(failure != "", $"{name} passes now: remove its entry ({finding}) from KnownFailures and docs/QA.md 2.11");
            }
            else
                Assert.True(failure == "", name + ": " + failure);
        }

        static DMesh3 Box(Vector3d lo, Vector3d hi) => MeshRepairIssueCasesTests.Box(lo, hi);

        static DMesh3 Union(params DMesh3[] meshes)
        {
            var m = new DMesh3();
            foreach (DMesh3 x in meshes) new MeshEditor(m).AppendMesh(x);
            return m;
        }

        static int Components(DMesh3 m)
        {
            var c = new MeshConnectedComponents(m);
            c.FindConnectedT();
            return c.Count;
        }

        static MeshAlphaWrap Wrap(DMesh3 mesh, double relAlpha, double relOffset)
        {
            var w = new MeshAlphaWrap(mesh) { RelativeAlpha = relAlpha, RelativeOffset = relOffset };
            w.Compute();
            return w;
        }

        [Fact]
        public void KnownFailures_NameExistingCases()
        {
            var names = new HashSet<string>(typeof(AlphaWrapIssueCasesTests).GetMethods().Select(m => m.Name));
            foreach (var kv in KnownFailures) {
                Assert.Contains(kv.Key, names);
                Assert.False(string.IsNullOrWhiteSpace(kv.Value));
            }
        }

        [Theory]
        [InlineData(4000)]
        [InlineData(4050)]
        public void SeparateComponents_GiveSeparateShells(double relOffset)
        {
            // https://github.com/CGAL/cgal/issues/7625: several separate components wrapped with a relative alpha of
            // 1000 and offset of 4000: the step that makes the result manifold marked outside cells inside, which gave
            // stray triangles bridging the components (offset 4050 worked). Rebuilt with a coarser alpha (100, the same
            // ratio of offset to alpha): 6 small boxes in a row, their gaps many alphas wide. Correct: 6 shells, each
            // around its own box (its vertices at the offset from it).
            var boxes = Enumerable.Range(0, 6).Select(i => Box(new Vector3d(3 * i, 0, 0), new Vector3d(3 * i + 1, 1 + 0.1 * i, 1))).ToArray();
            DMesh3 input = Union(boxes);
            Expect(nameof(SeparateComponents_GiveSeparateShells), () => {
                MeshAlphaWrap w = Wrap(input, 100, relOffset / 10);
                AlphaWrapTests.CheckWrap(w, AlphaWrapTests.Vertices(input));
                Assert.Equal(6, Components(w.Result));
            });
        }

        [Fact]
        public void OverlappingClosedInputs_OneShell()
        {
            // https://github.com/CGAL/cgal/issues/8725: overlapping closed inputs wrapped one by one gave overlapping
            // shells that a mesher downstream hung on. Wrapping them together must give one closed shell around their
            // union: two boxes crossing each other, a sphere through both.
            DMesh3 a = Box(new Vector3d(0, 0, 0), new Vector3d(4, 1, 1)), b = Box(new Vector3d(1.5, -1.5, -0.5), new Vector3d(2.5, 2.5, 1.5));
            DMesh3 s = MeshRepairIssueCasesTests.Sphere(new Vector3d(2, 0.5, 0.5), 0.9);
            DMesh3 input = Union(a, b, s);
            Expect(nameof(OverlappingClosedInputs_OneShell), () => {
                MeshAlphaWrap w = Wrap(input, 40, 1200);
                AlphaWrapTests.CheckWrap(w, AlphaWrapTests.Vertices(input));
                Assert.Equal(1, Components(w.Result));
            });
        }

        [Fact]
        public void NestedShells_OnlyTheOuterOneIsWrapped()
        {
            // https://github.com/CGAL/cgal/issues/8725 (nested shells from wrapping parts separately): a closed sphere
            // inside a closed box, wrapped together. The wrap comes from outside, so the inner shell is not reached:
            // one shell, outside the box.
            DMesh3 outer = Box(new Vector3d(-2, -2, -2), new Vector3d(2, 2, 2)), inner = MeshRepairIssueCasesTests.Sphere(Vector3d.Zero, 1);
            DMesh3 input = Union(outer, inner);
            Expect(nameof(NestedShells_OnlyTheOuterOneIsWrapped), () => {
                MeshAlphaWrap w = Wrap(input, 30, 900);
                AlphaWrapTests.CheckWrap(w, AlphaWrapTests.Vertices(input));
                Assert.Equal(1, Components(w.Result));
                foreach (Vector3d v in w.Result.Vertices())
                    Assert.True(Math.Max(Math.Abs(v.x), Math.Max(Math.Abs(v.y), Math.Abs(v.z))) >= 2, $"vertex {v} inside the box");
            });
        }

        [Fact]
        public void CubeWithLargeAlpha_StaysNearTheCorners()
        {
            // https://github.com/CGAL/cgal/issues/8152: large flat panels and sharp edges at a coarse alpha (relative
            // 600 / offset 1000 there): the edges were rounded off and the flat parts over-refined. Correct, as
            // documented: every point of the result within offset + 2 alpha of the cube, each corner within offset +
            // 2 alpha of the result (not rounded off further), and flat faces with no more triangles than alpha allows.
            DMesh3 cube = Box(new Vector3d(-1, -1, -1), new Vector3d(1, 1, 1));
            foreach (double relAlpha in new[] { 4.0, 15.0 }) {
                Expect(nameof(CubeWithLargeAlpha_StaysNearTheCorners), () => {
                    MeshAlphaWrap w = Wrap(cube, relAlpha, 10 * relAlpha);
                    AlphaWrapTests.CheckWrap(w, AlphaWrapTests.Vertices(cube));
                    // the corners are kept: each within offset + 2 alpha of the result (a rounded-off corner is farther)
                    var tree = new DMeshAABBTree3(w.Result, true);
                    foreach (Vector3d c in AlphaWrapTests.Vertices(cube)) {
                        double d = Math.Sqrt(MeshQueries.TriDistanceSqr(w.Result, tree.FindNearestTriangle(c), c));
                        Assert.True(d <= w.UsedOffset + 2 * w.UsedAlpha, $"corner {c} at {d} from the wrap (offset {w.UsedOffset}, alpha {w.UsedAlpha})");
                    }
                    // flat faces not over-refined: triangles about alpha in size, so their count is bounded by the area
                    // of the offset surface over the area of a triangle with circumradius alpha / 2
                    // (measured: 48 and 732 triangles, bounds 116 and 1450)
                    double area = 6 * Math.Pow(2 + 2 * w.UsedOffset, 2);
                    double small = 3 * Math.Sqrt(3) / 4 * Math.Pow(w.UsedAlpha / 2, 2);
                    Assert.True(w.Result.TriangleCount <= area / small, $"{w.Result.TriangleCount} triangles at alpha {w.UsedAlpha}");
                });
            }
        }

        [Fact]
        public void LatticePointCloud_CosphericalPoints()
        {
            // https://github.com/isl-org/Open3D/issues/1829: point sets with degenerate (zero-volume) Delaunay
            // tetrahedra, eg lattice points (many cospherical quadruples), made the whole alpha shape fail. Rebuilt: a
            // 6 x 6 x 6 lattice and a planar 10 x 10 lattice as point clouds. Correct: a closed wrap around all points.
            var cube = new List<Vector3d>();
            for (int i = 0; i < 6; ++i) for (int j = 0; j < 6; ++j) for (int k = 0; k < 6; ++k) cube.Add(new Vector3d(i, j, k));
            var plane = new List<Vector3d>();
            for (int i = 0; i < 10; ++i) for (int j = 0; j < 10; ++j) plane.Add(new Vector3d(i, j, 0));
            foreach (var pts in new[] { cube, plane }) {
                Expect(nameof(LatticePointCloud_CosphericalPoints), () => {
                    var w = new MeshAlphaWrap(pts) { RelativeAlpha = 10, RelativeOffset = 100 };
                    w.Compute();
                    AlphaWrapTests.CheckWrap(w, pts);
                });
            }
        }

        [Fact]
        public void NearlyCosphericalPoints_FarFromTheOrigin()
        {
            // https://github.com/isl-org/Open3D/issues/1659: about 12000 points voxel-downsampled from a sphere (so
            // nearly cospherical) at coordinates of about 2.8e6: the convex hull / Delaunay step aborted on a precision
            // error. Rebuilt: points of a sphere of radius 5 snapped to a 0.25 grid, at (2.8e6, -1.9e6, 4.1e5), and a
            // copy at the origin; both wraps alike.
            var pts = new List<Vector3d>();
            var seen = new HashSet<Vector3d>();
            var rand = new Random(1659);
            for (int i = 0; i < 4000; ++i) {
                Vector3d d = new Vector3d(rand.NextDouble() - 0.5, rand.NextDouble() - 0.5, rand.NextDouble() - 0.5);
                if (d.Length < 1e-3) continue;
                Vector3d p = 5 * d.Normalized;
                p = new Vector3d(Math.Round(4 * p.x) / 4, Math.Round(4 * p.y) / 4, Math.Round(4 * p.z) / 4);
                if (seen.Add(p)) pts.Add(p);
            }
            var shift = new Vector3d(2.8e6, -1.9e6, 4.1e5);
            var counts = new List<int>();
            foreach (Vector3d t in new[] { Vector3d.Zero, shift }) {
                List<Vector3d> input = pts.Select(p => p + t).ToList();
                Expect(nameof(NearlyCosphericalPoints_FarFromTheOrigin), () => {
                    var w = new MeshAlphaWrap(input) { RelativeAlpha = 15, RelativeOffset = 300 };
                    w.Compute();
                    AlphaWrapTests.CheckWrap(w, input);
                    Assert.Equal(1, Components(w.Result));
                    counts.Add(w.Result.TriangleCount);
                });
            }
            // the same wrap up to rounding: triangle counts within a few percent
            if (counts.Count == 2)
                Assert.True(Math.Abs(counts[0] - counts[1]) <= 0.05 * counts[0], $"{counts[0]} vs {counts[1]} triangles");
        }

        [Fact]
        public void TooSmallAlpha_StopsAtThePointLimit()
        {
            // https://github.com/MeshInspector/MeshLib/issues/5528: with a too fine voxel (here: alpha) for the model
            // size, a rebuild ran for hours instead of minutes. Correct: the point limit stops the refinement in bounded
            // time, with a closed result that still encloses the input (PointLimitReached, documented).
            DMesh3 input = MeshRepairIssueCasesTests.Sphere(Vector3d.Zero, 1, 6);
            Expect(nameof(TooSmallAlpha_StopsAtThePointLimit), () => {
                var sw = Stopwatch.StartNew();
                var w = new MeshAlphaWrap(input) { RelativeAlpha = 1e5, RelativeOffset = 1e6, MaxSteinerPoints = 20000 };
                w.Compute();
                Assert.Equal(MeshAlphaWrap.WrapStatus.PointLimitReached, w.Status);
                Assert.True(sw.Elapsed.TotalSeconds < 60, $"{sw.Elapsed.TotalSeconds} s");
                // (with the limit reached, box corners can be vertices: no distance bound, only the topology and enclosure)
                ResultChecks.AssertClosed(w.Result);
                Assert.Equal(0, MeshRepairMetrics.SelfIntersections(w.Result));
                var tree = new DMeshAABBTree3(w.Result, true);
                foreach (Vector3d p in AlphaWrapTests.Vertices(input))
                    Assert.True(tree.WindingNumber(p) > 0.99, "input point outside of the wrap");
            });
        }

        [Fact]
        public void TwoSidedSheet_ZeroThickness_Wrapped()
        {
            // https://github.com/elalish/manifold/issues/560: a zero-thickness solid (a surface and its flipped copy
            // stitched together) whose cleanup deleted the valid but zero-volume parts. A wrap must enclose such a
            // sheet: a 10 x 10 grid and its reversed copy on the same vertices positions.
            var grid = new DMesh3();
            int n = 10;
            for (int j = 0; j <= n; ++j) for (int i = 0; i <= n; ++i) grid.AppendVertex(new Vector3d(i, j, 0.05 * Math.Sin(i + j)));
            for (int j = 0; j < n; ++j) for (int i = 0; i < n; ++i) {
                int a = j * (n + 1) + i, b = a + 1, c = a + n + 2, d = a + n + 1;
                grid.AppendTriangle(a, b, c); grid.AppendTriangle(a, c, d);
            }
            DMesh3 back = new DMesh3(grid);
            back.ReverseOrientation();
            DMesh3 input = Union(grid, back);
            Expect(nameof(TwoSidedSheet_ZeroThickness_Wrapped), () => {
                MeshAlphaWrap w = Wrap(input, 20, 400);
                AlphaWrapTests.CheckWrap(w, AlphaWrapTests.Vertices(input));
                Assert.Equal(1, Components(w.Result));
                // a thin shell: its volume about twice the offset times the sheet's area
                double vol = ResultChecks.Volume(w.Result);
                Assert.True(vol < 2 * (w.UsedOffset + 2 * w.UsedAlpha) * 1.2 * n * n + 1e-9, $"volume {vol}");
            });
        }

        [Fact]
        public void ComponentsCloserThanAlpha_Bridged()
        {
            // the other side of https://github.com/CGAL/cgal/issues/7625: components closer than about 2 alpha are
            // wrapped together (documented: gaps narrower than about 2 alpha are wrapped over). Two boxes 0.1 alpha apart:
            // one shell.
            DMesh3 a = Box(new Vector3d(0, 0, 0), new Vector3d(1, 1, 1));
            DMesh3 input = null;
            Expect(nameof(ComponentsCloserThanAlpha_Bridged), () => {
                var probe = Wrap(a, 20, 600);
                double gap = 0.1 * probe.UsedAlpha;
                input = Union(a, Box(new Vector3d(1 + gap, 0, 0), new Vector3d(2 + gap, 1, 1)));
                // the same absolute alpha and offset for the pair (relative values follow the larger bounds)
                var w = new MeshAlphaWrap(input) { Alpha = probe.UsedAlpha, Offset = probe.UsedOffset };
                w.Compute();
                AlphaWrapTests.CheckWrap(w, AlphaWrapTests.Vertices(input));
                Assert.Equal(1, Components(w.Result));
            });
        }
    }
}

using System;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    // (its own file: these use MeshAlphaWrap.RefineNonManifold and preferred_flip, so the other new alpha wrap tests
    // still compile against the library of the base branch in the "New tests on base" job)
    public class AlphaWrapNonManifoldTests
    {
        [Fact]
        public void Wrap_RefineNonManifoldOff_ManifoldStepAlone()
        {
            // with the refinement off the manifold step alone makes the surface manifold, as before: closed, manifold, no
            // self-intersections; its moved cells give triangles outside the angle bound on this input (9), and the result
            // even reaches beyond offset + 2 alpha from the input (0.2041 against 0.2032, so CheckWrap's band fails);
            // with it on, neither
            DMesh3 m = AlphaWrapTests.RandomSoup(42);
            var off = new MeshAlphaWrap(m) { RelativeAlpha = 20, RelativeOffset = 200, RefineNonManifold = false };
            Assert.True(off.Compute(), off.Error);
            Assert.Equal("", MeshRobustRepair.NotCleanReason(off.Result));
            Assert.False(off.Counts.ContainsKey("pinch_points"));
            Assert.True(off.Counts["manifold_flips"] > 0);
            Assert.ThrowsAny<Exception>(() => AlphaWrapTests.AssertAngleBoundOnAllTriangles(off, "off"));

            var on = new MeshAlphaWrap(m) { RelativeAlpha = 20, RelativeOffset = 200 };
            Assert.True(on.RefineNonManifold);
            Assert.True(on.Compute(), on.Error);
            Assert.True(on.Counts["pinch_points"] > 0 && on.Counts["pinch_rounds"] > 0);
            Assert.True(on.Counts["manifold_flips"] < off.Counts["manifold_flips"]);
            AlphaWrapTests.AssertAngleBoundOnAllTriangles(on, "on");
        }

        [Fact]
        public void Wrap_RefineNonManifold_PointLimitAndCancel()
        {
            // the extra points count against the point limit: one point above what the wrap needs without the refinement ends
            // in the first round at non-manifold spots, with PointLimitReached and its guarantees (closed, manifold, enclosing)
            DMesh3 m = AlphaWrapTests.RandomSoup(42);
            var plain = new MeshAlphaWrap(m) { RelativeAlpha = 20, RelativeOffset = 200, RefineNonManifold = false };
            Assert.True(plain.Compute(), plain.Error);
            long needed = plain.Counts["steiner_points"];
            var limited = new MeshAlphaWrap(m) { RelativeAlpha = 20, RelativeOffset = 200, MaxSteinerPoints = (int)needed + 1 };
            Assert.False(limited.Compute());
            Assert.Equal(MeshAlphaWrap.WrapStatus.PointLimitReached, limited.Status);
            Assert.Equal(needed + 1, limited.Counts["steiner_points"]);
            Assert.Equal(1, limited.Counts["pinch_points"]);
            Assert.Equal("", MeshRobustRepair.NotCleanReason(limited.Result));

            // cancelled once the first refinement has ended: in the first round of the refinement at non-manifold spots,
            // before it reports its counts
            var cancelled = new MeshAlphaWrap(m) { RelativeAlpha = 20, RelativeOffset = 200 };
            cancelled.CancelF = () => cancelled.PhaseMilliseconds.ContainsKey("wrap");
            Assert.False(cancelled.Compute());
            Assert.Equal(MeshAlphaWrap.WrapStatus.Cancelled, cancelled.Status);
            Assert.False(cancelled.Counts.ContainsKey("pinch_rounds"));
        }

        [Fact]
        public void ManifoldStep_CandidateOrder_ScaleFree()
        {
            // no box corner first, then joining inside components, then the smaller volume; volumes far above 2^53
            // (coordinates of a few hundred thousand) are still ordered (the old score volume / (1 + volume) tied at 1)
            Assert.True(MeshAlphaWrap.preferred_flip(false, false, 5, true, true, 1));
            Assert.True(MeshAlphaWrap.preferred_flip(false, true, 5, false, false, 1));
            Assert.True(MeshAlphaWrap.preferred_flip(false, true, 1e17, false, true, 2e17));
            Assert.False(MeshAlphaWrap.preferred_flip(false, true, 2e17, false, true, 1e17));
            Assert.False(MeshAlphaWrap.preferred_flip(false, true, 1e17, false, true, 1e17));
            Assert.True(MeshAlphaWrap.preferred_flip(false, true, 1e-300, false, true, 1.5e-300));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The triangle quality pass on a simplified alpha wrap (MeshRobustRepair.AlphaWrapQualityPass,
    /// AlphaWrapQualityPass): fewer slivers, every changed triangle within the tolerance of the unsimplified wrap,
    /// no self-intersections, the topology kept; deterministic and scale invariant.
    /// </summary>
    public class AlphaWrapQualityPassTests
    {
        // an alpha wrap of a box (flat faces: the simplification leaves slivers) and its simplification
        static void BoxWrap(Box3d b, out DMesh3 wrap, out DMesh3 simplified, out double tol)
        {
            DMesh3 box = new TrivialBox3Generator() { Box = b, NoSharedVertices = false }.Generate().MakeDMesh();
            var w = new MeshAlphaWrap(box) { RelativeAlpha = 60, RelativeOffset = 600 };
            Assert.True(w.Compute());
            wrap = w.Result;
            tol = 0.5 * w.UsedOffset;
            simplified = MeshRobustRepair.SimplifyWithin(wrap, tol, tol, true, () => false);
            Assert.NotNull(simplified);
        }

        static Box3d DefaultBox => new Box3d(Vector3d.Zero, new Vector3d(1, 0.6, 0.3));

        static double MinAngle(DMesh3 m, int t)
        {
            Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
            m.GetTriVertices(t, ref a, ref b, ref c);
            double A = Vector3d.AngleD((b - a).Normalized, (c - a).Normalized), B = Vector3d.AngleD((a - b).Normalized, (c - b).Normalized);
            return Math.Min(A, Math.Min(B, 180 - A - B));
        }

        // the 1 %-worst minimum angle
        static double P01(DMesh3 m)
        {
            var a = m.TriangleIndices().Select(t => MinAngle(m, t)).OrderBy(x => x).ToArray();
            return a[a.Length / 100];
        }

        static double HausdorffUpper(DMesh3 from, DMesh3 to, double tol)
        {
            var hd = new MeshHausdorffDistance(from, to) { Symmetric = false, Tolerance = 0.01 * tol };
            Assert.True(hd.Compute() && hd.Converged);
            return hd.UpperBound;
        }

        [Fact]
        public void ImproveWrapQuality_FewerSlivers_WithinTolerance_Clean_SameTopology()
        {
            DMesh3 wrap, simp; double tol;
            BoxWrap(DefaultBox, out wrap, out simp, out tol);
            DMesh3 copy = new DMesh3(simp);
            DMesh3 q = MeshRobustRepair.ImproveWrapQuality(simp, wrap, tol, true, () => false);
            Assert.NotNull(q);
            Assert.Equal("", MeshRobustRepair.NotCleanReason(q, true));
            // flips and moves only: the same vertices, triangles and genus
            Assert.Equal(simp.VertexCount, q.VertexCount);
            Assert.Equal(simp.TriangleCount, q.TriangleCount);
            Assert.Equal(MeshTopologySummary.Compute(simp).Genus, MeshTopologySummary.Compute(q).Genus);
            // better: the 1 %-worst and the worst minimum angle
            double before = P01(simp), after = P01(q);
            Assert.True(after > before + 2, $"1 %-worst min angle {before} -> {after}");
            Assert.True(q.TriangleIndices().Min(t => MinAngle(q, t)) >= simp.TriangleIndices().Min(t => MinAngle(simp, t)));
            // within the tolerance of the unsimplified wrap (certified by the bounds without the patch bound)
            Assert.True(HausdorffUpper(q, wrap, tol) <= tol);
            // the input is not changed
            Assert.Equal("", Invariance.Difference(copy, simp));
        }

        [Fact]
        public void Pass_KeepsEveryTriangleWithinItsTolerance_AndCountsOperations()
        {
            DMesh3 wrap, simp; double tol;
            BoxWrap(DefaultBox, out wrap, out simp, out tol);
            // a tolerance below the simplification's own deviation: the pass may only make changes that stay within it
            foreach (double t in new[] { tol, 0.3 * tol }) {
                var pass = new AlphaWrapQualityPass(new DMesh3(simp), wrap, t);
                Assert.True(pass.Compute());
                Assert.True(pass.Flips + pass.Moves > 0);
                Assert.True(pass.RejectedByDeviation > 0, "the tolerance must reject some operations");
                // every triangle that changed is within t; the unchanged ones keep the simplification's deviation
                var tree = new DMeshAABBTree3(wrap, true);
                var bounds = new TriangleDeviationBounds(wrap);
                var before = new HashSet<string>(simp.TriangleIndices().Select(k => key(simp, k)));
                int changed = 0;
                foreach (int k in pass.Mesh.TriangleIndices()) {
                    if (before.Contains(key(pass.Mesh, k))) continue;
                    changed++;
                    Index3i tv = pass.Mesh.GetTriangle(k);
                    Assert.True(bounds.IsWithin(tree, pass.Mesh.GetVertex(tv.a), pass.Mesh.GetVertex(tv.b), pass.Mesh.GetVertex(tv.c), t * 1.000001, 12),
                        $"tolerance {t}: changed triangle {k} not within it");
                }
                Assert.True(changed > 0);
            }
        }

        // a triangle by its corner positions (independent of ids)
        static string key(DMesh3 m, int t)
        {
            Index3i tv = m.GetTriangle(t);
            var p = new[] { m.GetVertex(tv.a), m.GetVertex(tv.b), m.GetVertex(tv.c) }.Select(v => $"{v.x:R},{v.y:R},{v.z:R}").OrderBy(x => x);
            return string.Join(";", p);
        }

        [Fact]
        public void Accept_RejectsIntersectingAndFarTriangles()
        {
            // two parallel grids 0.01 apart; reference = the mesh itself
            DMesh3 m = new DMesh3();
            Func<double, int[,]> grid = (z) => {
                var ids = new int[6, 6];
                for (int j = 0; j < 6; ++j) for (int i = 0; i < 6; ++i) ids[i, j] = m.AppendVertex(new Vector3d(i * 0.2, j * 0.2, z));
                for (int j = 0; j < 5; ++j) for (int i = 0; i < 5; ++i) {
                    m.AppendTriangle(ids[i, j], ids[i + 1, j], ids[i + 1, j + 1]);
                    m.AppendTriangle(ids[i, j], ids[i + 1, j + 1], ids[i, j + 1]);
                }
                return ids;
            };
            grid(0); grid(0.01);
            var pass = new AlphaWrapQualityPass(m, new DMesh3(m), 0.05);
            pass.Prepare();
            // a new triangle through the other sheet: rejected by the intersection check (it is within the tolerance)
            var through = new Triangle3d(new Vector3d(0.3, 0.3, -0.004), new Vector3d(0.5, 0.3, 0.014), new Vector3d(0.4, 0.5, 0.005));
            Assert.False(pass.accept(new List<Index3i> { new Index3i(1000, 1001, 1002) }, new List<Triangle3d> { through }, new HashSet<int>()));
            Assert.Equal(1, pass.RejectedByIntersection);
            // between the sheets, touching neither: accepted
            var between = new Triangle3d(new Vector3d(0.3, 0.3, 0.005), new Vector3d(0.5, 0.3, 0.005), new Vector3d(0.4, 0.5, 0.005));
            Assert.True(pass.accept(new List<Index3i> { new Index3i(1000, 1001, 1002) }, new List<Triangle3d> { between }, new HashSet<int>()));
            // far above: rejected by the tolerance
            var far = new Triangle3d(new Vector3d(0.3, 0.3, 0.2), new Vector3d(0.5, 0.3, 0.2), new Vector3d(0.4, 0.5, 0.2));
            Assert.False(pass.accept(new List<Index3i> { new Index3i(1000, 1001, 1002) }, new List<Triangle3d> { far }, new HashSet<int>()));
            Assert.Equal(1, pass.RejectedByDeviation);
            // two new triangles that cross each other
            var a = new Triangle3d(new Vector3d(0.3, 0.3, 0.003), new Vector3d(0.5, 0.3, 0.003), new Vector3d(0.4, 0.5, 0.003));
            var b = new Triangle3d(new Vector3d(0.4, 0.25, 0.001), new Vector3d(0.4, 0.45, 0.001), new Vector3d(0.42, 0.35, 0.007));
            Assert.False(pass.accept(new List<Index3i> { new Index3i(1000, 1001, 1002), new Index3i(1003, 1004, 1005) },
                new List<Triangle3d> { a, b }, new HashSet<int>()));
            Assert.Equal(2, pass.RejectedByIntersection);
        }

        [Fact]
        public void NormalGuard_NoFlipAcrossASharpEdge()
        {
            // two slivers folded over their shared edge ab at 90 degrees: the flip to cd would give fatter triangles,
            // but they turn by about 45 degrees; the tolerance allows it, only the normal guard rejects it
            Func<double, AlphaWrapQualityPass> run = (turn) => {
                var m = new DMesh3();
                int a = m.AppendVertex(new Vector3d(0, 0, 0)), b = m.AppendVertex(new Vector3d(1, 0, 0)),
                    c = m.AppendVertex(new Vector3d(0.5, 0.06, -0.06)), d = m.AppendVertex(new Vector3d(0.5, -0.06, -0.06));
                m.AppendTriangle(a, b, c); m.AppendTriangle(b, a, d);
                var pass = new AlphaWrapQualityPass(m, new DMesh3(m), 100) { EnableMoves = false, MaxNormalTurnDegrees = turn };
                Assert.True(pass.Compute());
                return pass;
            };
            Assert.Equal(0, run(30).Flips);
            Assert.Equal(1, run(180).Flips);      // without the guard the flip is made
            // the crease switch alone also keeps it (the two triangles meet at 90 degrees)
            var m2 = new DMesh3();
            int a2 = m2.AppendVertex(new Vector3d(0, 0, 0)), b2 = m2.AppendVertex(new Vector3d(1, 0, 0)),
                c2 = m2.AppendVertex(new Vector3d(0.5, 0.06, -0.06)), d2 = m2.AppendVertex(new Vector3d(0.5, -0.06, -0.06));
            m2.AppendTriangle(a2, b2, c2); m2.AppendTriangle(b2, a2, d2);
            var crease = new AlphaWrapQualityPass(m2, new DMesh3(m2), 100) { EnableMoves = false, MaxNormalTurnDegrees = 180, MaxFlipDihedralDegrees = 20 };
            Assert.True(crease.Compute());
            Assert.Equal(0, crease.Flips);
        }

        [Fact]
        public void FollowReference_MovesKeepTheirOffsetFromACurvedReference()
        {
            // a sphere as the reference, the mesh its copy pushed out by 0.01 with jittered vertices: with
            // FollowReference a moved vertex keeps its distance to the reference (to the curvature's second order),
            // without it a tangential move leaves the offset surface
            DMesh3 sphere = new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = 16 }.Generate().MakeDMesh();
            var tree = new DMeshAABBTree3(sphere, true);
            Func<Vector3d, double> dist = (p) => Math.Sqrt(MeshQueries.TriDistanceSqr(sphere, tree.FindNearestTriangle(p), p));
            var rand = new Random(2);
            DMesh3 start = new DMesh3(sphere);
            foreach (int v in start.VertexIndices()) {
                Vector3d p = start.GetVertex(v);
                Vector3d t = new Vector3d(rand.NextDouble() - 0.5, rand.NextDouble() - 0.5, rand.NextDouble() - 0.5) * 0.04;
                start.SetVertex(v, (p + t).Normalized * 1.01);
            }
            Func<bool, double> worst = (follow) => {
                var pass = new AlphaWrapQualityPass(new DMesh3(start), sphere, 0.05) { EnableFlips = false, FollowReference = follow, MaxPasses = 1, TargetAngleDegrees = 60 };
                Assert.True(pass.Compute());
                Assert.True(pass.Moves > 0);
                // the largest change of a vertex's distance to the reference
                return pass.Mesh.VertexIndices().Max(v => Math.Abs(dist(pass.Mesh.GetVertex(v)) - dist(start.GetVertex(v))));
            };
            double with = worst(true), without = worst(false);
            Assert.True(with < 0.5 * without, $"offset error with {with}, without {without}");
        }

        [Fact]
        public void NormalGuard_NoMoveThatTiltsASteepFan()
        {
            // a low pyramid with its apex far off the centre of its base: moving the apex over the centroid would tilt faces by more than
            // 30 degrees
            Func<double, AlphaWrapQualityPass> run = (turn) => {
                var m = new DMesh3();
                int apex = m.AppendVertex(new Vector3d(0.2, 0.2, 0.4));
                var b = new[] { new Vector3d(0, 0, 0), new Vector3d(1.6, 0, 0), new Vector3d(1.6, 1.2, 0), new Vector3d(0, 1.2, 0) }
                    .Select(p => m.AppendVertex(p)).ToArray();
                for (int k = 0; k < 4; ++k) m.AppendTriangle(apex, b[k], b[(k + 1) % 4]);
                // (the base vertices are boundary vertices and stay; the apex is interior)
                var pass = new AlphaWrapQualityPass(m, new DMesh3(m), 100) { EnableFlips = false, MaxNormalTurnDegrees = turn, TargetAngleDegrees = 60 };
                Assert.True(pass.Compute());
                return pass;
            };
            Assert.Equal(0, run(30).Moves);
            Assert.True(run(180).Moves > 0);
        }

        [Fact]
        public void Moves_NeverLowerTheWorstAngle_OnAJitteredGrid()
        {
            // a planar grid with jittered vertices and the boundary fixed: every kept move raises the smallest angle
            // of its one ring (and every flip that of its two triangles), so the worst angle of the mesh cannot drop
            var rand = new Random(5);
            int n = 12;
            var m = new DMesh3();
            var ids = new int[n + 1, n + 1];
            for (int j = 0; j <= n; ++j)
                for (int i = 0; i <= n; ++i) {
                    bool inner = i > 0 && j > 0 && i < n && j < n;
                    ids[i, j] = m.AppendVertex(new Vector3d(i + (inner ? 0.45 * (rand.NextDouble() - 0.5) : 0), j + (inner ? 0.45 * (rand.NextDouble() - 0.5) : 0), 0));
                }
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    m.AppendTriangle(ids[i, j], ids[i + 1, j], ids[i + 1, j + 1]);
                    m.AppendTriangle(ids[i, j], ids[i + 1, j + 1], ids[i, j + 1]);
                }
            DMesh3 before = new DMesh3(m);
            var pass = new AlphaWrapQualityPass(m, new DMesh3(m), 0.01) { MaxPasses = 1, EnableFlips = false };
            Assert.True(pass.Compute());
            Assert.True(pass.Moves > 0);
            Assert.True(pass.Mesh.TriangleIndices().Min(t => MinAngle(pass.Mesh, t)) >= before.TriangleIndices().Min(t => MinAngle(before, t)) - 1e-9);
        }

        [Fact]
        public void NoMoveWithoutGain()
        {
            // a planar fan whose centroid lies close to an edge of its ring: moving the vertex there lowers the
            // smallest angle (6.2 -> 2.8 degrees), so it is not moved
            var ring = new[] { new Vector2d(0.11, 1.44), new Vector2d(-0.04, 1.23), new Vector2d(-1.24, 0.35), new Vector2d(-1.18, -0.11),
                new Vector2d(-0.81, -0.46), new Vector2d(0.78, -0.11) };
            var m = new DMesh3();
            int v = m.AppendVertex(Vector3d.Zero);
            int[] r = ring.Select(p => m.AppendVertex(new Vector3d(p.x, p.y, 0))).ToArray();
