            Assert.True(pass.GridMatchesMesh(), "the self-intersection grid follows the collapses");
            Assert.Equal(simp.TriangleCount - 2 * pass.Collapses, q.TriangleCount);
            Assert.Equal("", MeshRobustRepair.NotCleanReason(q, true));
