        }

        [Fact]
        public void MemoizedRejections_SameResultAsEvaluatingAgain()
        {
            // a rejection by the normals, the tolerance or the protection is remembered until a vertex of its triangles
            // changes: the result is the same, bit for bit, as evaluating every operation in every pass
            DMesh3 wrap, simp; double tol;
            BoxWrap(DefaultBox, out wrap, out simp, out tol);
            var configs = new Action<AlphaWrapQualityPass>[] {
                MeshRobustRepair.DefaultWrapQuality,
                (p) => { p.EnableFlips = false; p.WorstFirst = p.FollowReference = true; p.SplitCapsAboveDegrees = 160; p.PinCreaseVerticesDegrees = 20; },
                (p) => { p.KeepNormalDeviation = true; p.MaxPasses = 3; }
            };
            foreach (double t in new[] { 0.95 * tol, 0.3 * tol })
                foreach (var cfg in configs) {
                    var memo = new AlphaWrapQualityPass(new DMesh3(simp), wrap, t);
                    var plain = new AlphaWrapQualityPass(new DMesh3(simp), wrap, t) { MemoizeRejections = false };
                    cfg(memo); cfg(plain);
                    Assert.True(memo.Compute() && plain.Compute());
                    Assert.True(memo.SkippedRejections > 0);
                    Assert.Equal(0, plain.SkippedRejections);
                    Assert.Equal("", Invariance.Difference(plain.Mesh, memo.Mesh));
                    Assert.Equal(plain.Flips + plain.Moves + plain.Splits, memo.Flips + memo.Moves + memo.Splits);
                    // reuse: a second Compute on the memoizing instance starts with an empty memo, as the plain one
                    Assert.True(memo.Compute() && plain.Compute());
                    Assert.Equal("", Invariance.Difference(plain.Mesh, memo.Mesh));
                }
        }

        [Fact]
        public void MemoizedRejections_NotForIntersections()
        {
            // an intersection depends on triangles outside the operation: rejected while a moved vertex of the grid
            // pokes through the probe, accepted again once it is back, although none of the operation's own triangles changed
            DMesh3 m = new DMesh3();
            var g = new int[6, 6];
            for (int j = 0; j < 6; ++j) for (int i = 0; i < 6; ++i) g[i, j] = m.AppendVertex(new Vector3d(i * 0.2, j * 0.2, 0));
            for (int j = 0; j < 5; ++j) for (int i = 0; i < 5; ++i) {
                m.AppendTriangle(g[i, j], g[i + 1, j], g[i + 1, j + 1]);
                m.AppendTriangle(g[i, j], g[i + 1, j + 1], g[i, j + 1]);
            }
            var pass = new AlphaWrapQualityPass(m, new DMesh3(m), 10);
            pass.Prepare();
            int v = g[2, 2];
            var ring = m.VtxTrianglesItr(v).ToList();
            var probe = new List<Triangle3d> { new Triangle3d(new Vector3d(0.25, 0.4, 2.0), new Vector3d(0.55, 0.4, 2.0), new Vector3d(0.4, 0.6, 2.2)) };
            var ids = new List<Index3i> { new Index3i(1000, 1001, 1002) };
            var removed = new HashSet<int> { m.FindTriangle(g[4, 4], g[5, 4], g[5, 5]) };   // (away from the moved vertex)
            m.SetVertex(v, new Vector3d(0.4, 0.4, 3));
            pass.regrid(ring, ring);
            Assert.False(pass.accept(AlphaWrapQualityPass.FlipOp, 7, ids, probe, removed));
            Assert.Equal(1, pass.RejectedByIntersection);
            m.SetVertex(v, new Vector3d(0.4, 0.4, 0));
            pass.regrid(ring, ring);
            Assert.True(pass.accept(AlphaWrapQualityPass.FlipOp, 7, ids, probe, removed));
            Assert.Equal(0, pass.SkippedRejections);
            // a rejection by the tolerance (a probe far from the reference) is remembered while its triangles stay
            var far = new List<Triangle3d> { new Triangle3d(new Vector3d(0, 0, 50), new Vector3d(1, 0, 50), new Vector3d(0, 1, 50)) };
            Assert.False(pass.accept(AlphaWrapQualityPass.FlipOp, 8, ids, far, removed));
            Assert.False(pass.accept(AlphaWrapQualityPass.FlipOp, 8, ids, far, removed));
            Assert.Equal(1, pass.SkippedRejections);
        }

        static void Invariant(Action<AlphaWrapQualityPass> cfg)
        {
            DMesh3 wrap, simp; double tol;
            BoxWrap(DefaultBox, out wrap, out simp, out tol);
            DMesh3 q0 = MeshRobustRepair.ImproveWrapQuality(simp, wrap, tol, true, () => false, cfg);
            Assert.NotNull(q0);
            double p0 = P01(q0);
            foreach (Similarity s in Similarity.All()) {
                DMesh3 w = new DMesh3(wrap), m = new DMesh3(simp);
                MeshTransforms.PerVertexTransform(w, s.Apply);
                MeshTransforms.PerVertexTransform(m, s.Apply);
                DMesh3 q = MeshRobustRepair.ImproveWrapQuality(m, w, s.ApplyLength(tol), true, () => false, cfg);
                Assert.True(q != null, s.Name);
                Assert.Equal("", MeshRobustRepair.NotCleanReason(q, true));
                if (s.IsExact) {
                    // the same operations: the same mesh, scaled
                    Assert.Equal(q0.TriangleCount, q.TriangleCount);
                    Assert.True(q0.VertexIndices().All(v => q.GetVertex(v) == s.Apply(q0.GetVertex(v))), s.Name);
                    Assert.True(q0.TriangleIndices().All(t => q.GetTriangle(t) == q0.GetTriangle(t)), s.Name);
                } else {
                    Assert.True(Math.Abs(P01(q) - p0) < 3, $"{s.Name}: 1 %-worst min angle {P01(q)} vs {p0}");
                }
            }
        }

        [Fact]
        public void Deterministic_AndComputeTwiceOnOneInstance()
        {
            DMesh3 wrap, simp; double tol;
            BoxWrap(DefaultBox, out wrap, out simp, out tol);
            DMesh3 a = MeshRobustRepair.ImproveWrapQuality(simp, wrap, tol, true, () => false);
            DMesh3 b = MeshRobustRepair.ImproveWrapQuality(simp, wrap, tol, true, () => false);
            Assert.Equal("", Invariance.Difference(a, b));
            // a second Compute on the same instance continues from its result: counters reset, still within the tolerance
            // (0.95 of the tolerance, as ImproveWrapQuality: the final check resolves to 1 % of it)
            var pass = new AlphaWrapQualityPass(new DMesh3(simp), wrap, 0.95 * tol);
            Assert.True(pass.Compute());
            int first = pass.Flips + pass.Moves;
            Assert.True(first > 0);
            Assert.True(pass.Compute());
            Assert.True(pass.Flips + pass.Moves < first, $"{pass.Flips + pass.Moves} after {first}");
            Assert.Equal("", MeshRobustRepair.NotCleanReason(new DMesh3(pass.Mesh, true), true));
            Assert.True(HausdorffUpper(pass.Mesh, wrap, tol) <= tol);
            // cancelled: null
            Assert.Null(MeshRobustRepair.ImproveWrapQuality(simp, wrap, tol, true, () => true));
        }

        [Fact]
        public void RobustRepair_QualityPass_OnByDefault_ImprovesTheWrap_OffSwitch()
        {
            Func<bool, MeshRobustRepair> run = (on) => {
                var r = new MeshRobustRepair(MeshRobustRepairTests.ThinPlates(6)) {
                    RepairF = (m) => new DMesh3(m), ExactResolve = false, SolidifyResolution = 64, AlphaWrapQualityPass = on
                };
                Assert.True(r.Apply());
                Assert.True(r.UsedAlphaWrap && r.AlphaWrapSimplified);
                return r;
            };
            Assert.True(new MeshRobustRepair(new DMesh3()).AlphaWrapQualityPass);
            var off = run(false);
            Assert.False(off.AlphaWrapQualityImproved);
            Assert.False(off.PhaseMilliseconds.ContainsKey("wrap.quality"));
            var on = run(true);
            Assert.True(on.AlphaWrapQualityImproved);
            Assert.True(on.PhaseMilliseconds.ContainsKey("wrap.quality"));
            Assert.Equal("", MeshRobustRepair.NotCleanReason(on.Mesh, true));
            Assert.Equal("", on.ResultReason);
            Assert.True(P01(on.Mesh) > P01(off.Mesh), $"{P01(off.Mesh)} -> {P01(on.Mesh)}");
            Assert.True(HausdorffUpper(on.Mesh, on.AlphaWrap.Result, on.AlphaWrap.UsedOffset) <= 0.5 * on.AlphaWrap.UsedOffset);
            // the simplification is the same with and without the pass; the default settings split caps (at most 5 % more triangles)
            Assert.Equal(off.AlphaWrapTriangles, on.AlphaWrapTriangles);
            Assert.True(on.Mesh.TriangleCount >= off.Mesh.TriangleCount && on.Mesh.TriangleCount <= Math.Floor(off.Mesh.TriangleCount * 1.05),
                $"{off.Mesh.TriangleCount} -> {on.Mesh.TriangleCount}");
            // the angle diagnostics match an independent computation (law of cosines), with and without the pass
            foreach (var r in new[] { off, on }) {
                double mn = double.MaxValue, mx = 0; int above = 0, aboveLo = 0;
                foreach (int t in r.Mesh.TriangleIndices()) {
                    Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
                    r.Mesh.GetTriVertices(t, ref a, ref b, ref c);
                    double la = b.Distance(c), lb = a.Distance(c), lc = a.Distance(b);
                    Func<double, double, double, double> ang = (x, y, z) => Math.Acos(MathUtil.Clamp((y * y + z * z - x * x) / (2 * y * z), -1, 1)) * MathUtil.Rad2Deg;
                    double A = ang(la, lb, lc), B = ang(lb, la, lc), C = ang(lc, la, lb);
                    mn = Math.Min(mn, Math.Min(A, Math.Min(B, C)));
                    double m3 = Math.Max(A, Math.Max(B, C));
                    mx = Math.Max(mx, m3);
                    if (m3 > 170 + 1e-6) above++;
                    if (m3 > 170 - 1e-6) aboveLo++;
                }
                int n = r.Mesh.TriangleCount;
                Assert.True(Math.Abs(r.AlphaWrapMinAngleDegrees - mn) < 1e-6, $"{r.AlphaWrapMinAngleDegrees} vs {mn}");
                Assert.True(Math.Abs(r.AlphaWrapMaxAngleDegrees - mx) < 1e-6, $"{r.AlphaWrapMaxAngleDegrees} vs {mx}");
                Assert.InRange(r.AlphaWrapShareAbove170 * n, above - 1e-9, aboveLo + 1e-9);
            }
            Assert.True(on.AlphaWrapMinAngleDegrees >= off.AlphaWrapMinAngleDegrees);
            // the same values, bit for bit, under the exact similarities (2^k scales)
            foreach (Similarity sim in Similarity.All().Where(x => x.IsExact)) {
                DMesh3 t = new DMesh3(on.Mesh);
                MeshTransforms.PerVertexTransform(t, sim.Apply);
                double a0, a1, a2;
                MeshRobustRepair.angle_stats(t, out a0, out a1, out a2);
                Assert.True(a0 == on.AlphaWrapMinAngleDegrees && a1 == on.AlphaWrapMaxAngleDegrees && a2 == on.AlphaWrapShareAbove170, sim.Name);
            }
            // no wrap: no diagnostics
            var plain = new MeshRobustRepair(new Sphere3Generator_NormalizedCube() { EdgeVertices = 8 }.Generate().MakeDMesh());
            Assert.True(plain.Apply());
            Assert.False(plain.UsedAlphaWrap);
            Assert.True(double.IsNaN(plain.AlphaWrapMinAngleDegrees) && double.IsNaN(plain.AlphaWrapMaxAngleDegrees) && double.IsNaN(plain.AlphaWrapShareAbove170));
            // the default settings: as the pass with DefaultWrapQuality, on the simplified wrap
            DMesh3 direct = MeshRobustRepair.ImproveWrapQuality(off.Mesh, off.AlphaWrap.Result, 0.5 * off.AlphaWrap.UsedOffset, true, () => false, MeshRobustRepair.DefaultWrapQuality);
            Assert.Equal("", Invariance.Difference(direct, on.Mesh));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Alpha wrapping (MeshAlphaWrap) and its building blocks: the exact InSphere predicate, the 3D Delaunay
    /// triangulation (Delaunay3) and the distance queries (AlphaWrapOracle).
    /// </summary>
    public class AlphaWrapTests
    {
        // ---- InSphere ----

        static int InSphereInt(long[][] p)
        {
            // rows (x, y, z, x^2 + y^2 + z^2, 1) relative to e; sign convention as ExactPredicates.InSphere
            BigInteger[,] m = new BigInteger[4, 4];
            for (int i = 0; i < 4; ++i) {
                BigInteger x = new BigInteger(p[i][0]) - p[4][0], y = new BigInteger(p[i][1]) - p[4][1], z = new BigInteger(p[i][2]) - p[4][2];
                m[i, 0] = x; m[i, 1] = y; m[i, 2] = z; m[i, 3] = x * x + y * y + z * z;
            }
            BigInteger det = Det4(m);
            BigInteger[,] o = new BigInteger[3, 3];
            for (int i = 0; i < 3; ++i)
                for (int k = 0; k < 3; ++k) o[i, k] = new BigInteger(p[i + 1][k]) - p[0][k];
            BigInteger orient = o[0, 0] * (o[1, 1] * o[2, 2] - o[1, 2] * o[2, 1]) - o[0, 1] * (o[1, 0] * o[2, 2] - o[1, 2] * o[2, 0])
                + o[0, 2] * (o[1, 0] * o[2, 1] - o[1, 1] * o[2, 0]);
            // for a positively oriented tetrahedron this determinant is positive inside the sphere
            return -det.Sign;
        }

        static BigInteger Det4(BigInteger[,] m)
        {
            BigInteger det = 0;
            for (int c = 0; c < 4; ++c) {
                BigInteger[,] s = new BigInteger[3, 3];
                for (int i = 1; i < 4; ++i) {
                    int cc = 0;
                    for (int k = 0; k < 4; ++k) {
                        if (k == c) continue;
                        s[i - 1, cc++] = m[i, k];
                    }
                }
                BigInteger minor = s[0, 0] * (s[1, 1] * s[2, 2] - s[1, 2] * s[2, 1]) - s[0, 1] * (s[1, 0] * s[2, 2] - s[1, 2] * s[2, 0])
                    + s[0, 2] * (s[1, 0] * s[2, 1] - s[1, 1] * s[2, 0]);
                det += ((c & 1) == 0 ? 1 : -1) * m[0, c] * minor;
            }
            return det;
        }

        [Fact]
        public void InSphere_SignConvention()
        {
            Vector3d a = Vector3d.Zero, b = Vector3d.AxisX, c = Vector3d.AxisY, d = Vector3d.AxisZ;
            Assert.Equal(1, ExactPredicates.Orient3d(a, b, c, d));
            Assert.Equal(1, ExactPredicates.InSphere(a, b, c, d, new Vector3d(0.25, 0.25, 0.25)));
            Assert.Equal(-1, ExactPredicates.InSphere(a, b, c, d, new Vector3d(2, 2, 2)));
            Assert.Equal(0, ExactPredicates.InSphere(a, b, c, d, new Vector3d(1, 1, 1)));     // cube corner: cospherical
            // reversed orientation reverses the sign
            Assert.Equal(-1, ExactPredicates.InSphere(b, a, c, d, new Vector3d(0.25, 0.25, 0.25)));
        }

        [Fact]
        public void InSphere_MatchesExactIntegerArithmetic_NearDegenerate()
        {
            // nearly cospherical integer points far from the origin: the filter fails, the exact path decides
            var rnd = new Random(5);
            long off = 1L << 36;
            int checkedNear = 0;
            for (int it = 0; it < 4000; ++it) {
                // points on a sphere of integer radius around an integer center (Pythagorean quadruples), moved by -1..1
                long[][] sph = { new long[] { 1, 2, 2 }, new long[] { 2, 1, -2 }, new long[] { -2, 2, 1 }, new long[] { 2, -2, 1 }, new long[] { -1, -2, 2 } };
                long scale = rnd.Next(1, 1 << 20);
                long[] center = { off + rnd.Next(1000), off + rnd.Next(1000), off + rnd.Next(1000) };
                long[][] p = new long[5][];
                for (int i = 0; i < 5; ++i)
                    p[i] = new long[] { center[0] + scale * sph[i][0] + rnd.Next(-1, 2), center[1] + scale * sph[i][1], center[2] + scale * sph[i][2] + rnd.Next(-1, 2) };
                Vector3d[] v = p.Select(q => new Vector3d(q[0], q[1], q[2])).ToArray();
                if (ExactPredicates.Orient3d(v[0], v[1], v[2], v[3]) == 0) continue;
                int expect = InSphereInt(p);
                Assert.Equal(expect, ExactPredicates.InSphere(v[0], v[1], v[2], v[3], v[4]));
                Assert.Equal(expect, ExactPredicates.InSphereExact(v[0], v[1], v[2], v[3], v[4]));
                checkedNear++;
            }
            Assert.True(checkedNear > 3000);
            // random (well separated) points: filter path
            for (int it = 0; it < 4000; ++it) {
                long[][] p = Enumerable.Range(0, 5).Select(_ => new long[] { rnd.Next(-1000, 1000), rnd.Next(-1000, 1000), rnd.Next(-1000, 1000) }).ToArray();
                Vector3d[] v = p.Select(q => new Vector3d(q[0], q[1], q[2])).ToArray();
                if (ExactPredicates.Orient3d(v[0], v[1], v[2], v[3]) == 0) continue;
                Assert.Equal(InSphereInt(p), ExactPredicates.InSphere(v[0], v[1], v[2], v[3], v[4]));
            }
        }


        // ---- Delaunay3 ----

        [Fact]
        public void Delaunay3_RandomPoints_ValidAndDelaunay()
        {
            var box = new AxisAlignedBox3d(new Vector3d(-1, -2, -3), new Vector3d(4, 3, 2));
            var dt = new Delaunay3(box);
            Assert.Null(dt.Validate(true));
            var rnd = new Random(2);
            for (int i = 0; i < 400; ++i) {
                Vector3d p = new Vector3d(-1 + 5 * rnd.NextDouble(), -2 + 5 * rnd.NextDouble(), -3 + 5 * rnd.NextDouble());
                Assert.Equal(Delaunay3.InsertResult.Inserted, dt.Insert(p, -1, 0, out int v));
                Assert.Equal(8 + i, v);
            }
            Assert.Null(dt.Validate(true));
            Assert.Equal(box.Volume, dt.CellIndices().Sum(c => dt.CellVolume(c)), 9);
            Assert.True(dt.CellIndices().All(c => dt.CellVolume(c) > 0));
        }

        [Fact]
        public void Delaunay3_GridPoints_CosphericalDegeneracies()
        {
            // a regular grid: every cube of the grid has 8 cospherical points, many coplanar facets
            var dt = new Delaunay3(new AxisAlignedBox3d(Vector3d.Zero, new Vector3d(5, 5, 5)));
            var rnd = new Random(3);
            var pts = new List<Vector3d>();
            for (int i = 1; i < 5; ++i)
                for (int j = 1; j < 5; ++j)
                    for (int k = 1; k < 5; ++k) pts.Add(new Vector3d(i, j, k));
            pts = pts.OrderBy(_ => rnd.Next()).ToList();
            foreach (Vector3d p in pts)
                Assert.Equal(Delaunay3.InsertResult.Inserted, dt.Insert(p, -1, 0, out int v));
