        public void Wrap_SymmetricInput_NoBoxCornersOnTheResult(double relativeAlpha)
        {
            // a sphere centred in a box with the same margin on all sides: two rule 1 points were rejected (at existing
            // vertices) and their cells stayed inside up to the box: two box corners on a Success result. Checked now,
            // and wrapped once more in a box with a different margin on each side
            DMesh3 s = Sphere(1, 12);
            var w = new MeshAlphaWrap(s) { RelativeAlpha = relativeAlpha };
            Assert.True(w.Compute());
            Assert.Equal(0, w.Counts["result_box_corners"]);
            Assert.Equal(0, w.Counts["rejected_rule1"]);
            Assert.Equal(1, w.Counts["box_retries"]);       // the first box (same margin on all sides) failed
            CheckWrap(w, Vertices(s));
            // without the retry: box corners on the result, or (with the refinement at non-manifold spots, which can carve
            // them away) the rejected rule 1 points, which the result check reports as Failed, not Success
            var symmetric = new MeshAlphaWrap(s) { RelativeAlpha = relativeAlpha, RetryWithOtherBox = false };
            Assert.False(symmetric.Compute());
            Assert.Equal(MeshAlphaWrap.WrapStatus.Failed, symmetric.Status);
            Assert.True(symmetric.Error == "result box corners on the result"
                || symmetric.Error == "result rule 1 Steiner points rejected (offset not guaranteed)", symmetric.Error);
            Assert.True(symmetric.Counts["rejected_rule1"] > 0);
        }

        [Fact]
        public void Wrap_CancelledInTheManifoldStep()
        {
            // cancelled once the refinement is done (its phase time is recorded): the manifold step notices, Cancelled
            DMesh3 s = Sphere(1, 12);
            MeshAlphaWrap w = null;
            int callsAfterRefinement = 0;
            w = new MeshAlphaWrap(s) { RelativeAlpha = 100, CancelF = () => w.PhaseMilliseconds.ContainsKey("wrap") && ++callsAfterRefinement > 0 };
            Assert.False(w.Compute());
            Assert.Equal(MeshAlphaWrap.WrapStatus.Cancelled, w.Status);
            Assert.Null(w.Error);
            Assert.True(w.Counts["steiner_points"] > 2048);     // enough vertex checks for the step to ask
            Assert.False(w.PhaseMilliseconds.ContainsKey("manifold"));
        }

        static DMesh3 SphereWithFloatingSpecks()
        {
            // a sphere and 20 valid triangles with edges of 1e-8 floating around it (as in Thingi10K 99911)
            DMesh3 m = Sphere(1, 8);
            var rnd = new Random(2);
            for (int k = 0; k < 20; ++k) {
                Vector3d c = new Vector3d(rnd.NextDouble() - 0.5, rnd.NextDouble() - 0.5, rnd.NextDouble() - 0.5).Normalized * (1.3 + 0.5 * rnd.NextDouble());
                m.AppendTriangle(m.AppendVertex(c), m.AppendVertex(c + new Vector3d(1e-8, 0, 0)), m.AppendVertex(c + new Vector3d(0, 1e-8, 0)));
            }
            return m;
        }

        [Fact]
        public void Wrap_SmallValidTriangles_NoRejectedSteinerPoints()
        {
            // the tiny triangles had no normal in the oracle: dual edges near them "entered the offset volume" at their
            // far end, outside the box, and were rejected (5 here, 1835 in Thingi10K 99911), leaving facets that can be
            // closer to the input than the offset
            DMesh3 m = SphereWithFloatingSpecks();
            var w = new MeshAlphaWrap(m) { RelativeAlpha = 20, RelativeOffset = 300 };
            Assert.True(w.Compute());
            Assert.Equal(0, w.Counts["rejected_rule1"]);
            CheckWrap(w, Vertices(m));
        }

        [Fact]
        public void Wrap_RejectedRule1Points_NotSuccess()
        {
            // a rejected rule 1 point leaves a facet that can come closer to the input than the offset: the result is
            // kept, but not reported as Success (also not after the retry with the other box)
            int calls = 0;
            DMesh3 cube = Box(Vector3d.Zero, Vector3d.One);     // (many rule 1 points, unlike a sphere)
            var w = new MeshAlphaWrap(cube) { RelativeAlpha = 10, RetryWithOtherBox = false,
                RejectInsertF = (rule) => rule == 1 && ++calls > 20 && calls % 3 == 0 };
            Assert.False(w.Compute());
            Assert.Equal(MeshAlphaWrap.WrapStatus.Failed, w.Status);
            Assert.Equal("result rule 1 Steiner points rejected (offset not guaranteed)", w.Error);
            Assert.True(w.Counts["rejected_rule1"] > 0);
            Assert.Equal(0, w.Counts["result_box_corners"]);
            Assert.NotNull(w.Result);
            // with the retry (the default) it is tried once more, rejecting points there too: still Failed
            calls = 0;
            var retried = new MeshAlphaWrap(cube) { RelativeAlpha = 10, RejectInsertF = (rule) => rule == 1 && ++calls > 20 && calls % 3 == 0 };
            Assert.False(retried.Compute());
            Assert.Equal(1, retried.Counts["box_retries"]);
            Assert.Equal(MeshAlphaWrap.WrapStatus.Failed, retried.Status);
            // rejected rule 2 points alone do not (their cells touch the input; caught by the box corner check if they
            // reach the box)
            calls = 0;
            var w2 = new MeshAlphaWrap(Sphere(1, 8)) { RelativeAlpha = 10, RejectInsertF = (rule) => rule == 2 && ++calls % 7 == 0 };
            w2.Compute();
            Assert.True(w2.Counts["rejected_rule2"] > 0);
            Assert.Equal(0, w2.Counts["rejected_rule1"]);
            Assert.NotEqual("result rule 1 Steiner points rejected (offset not guaranteed)", w2.Error);
            // PointLimitReached promises closed, manifold and enclosing only, which a rule 1 rejection keeps: it stays
            // PointLimitReached (no Failed, no retry)
            calls = 0;
            var limited = new MeshAlphaWrap(cube) { RelativeAlpha = 10, MaxSteinerPoints = 60, RejectInsertF = (rule) => rule == 1 && ++calls % 5 == 0 };
            limited.Compute();
            Assert.True(limited.Counts["rejected_rule1"] > 0);
            Assert.Equal(MeshAlphaWrap.WrapStatus.PointLimitReached, limited.Status);
            Assert.False(limited.Counts.ContainsKey("box_retries"));
        }

        [Fact]
        public void Oracle_Unit_NoUnderOrOverflow()
        {
            // the triangle normals (and the projection direction of rule 2) are normalized without an absolute epsilon:
            // unit length also where the squared length underflows or overflows, zero only for a zero vector
            Assert.Equal(1.0, AlphaWrapOracle.Unit(new Vector3d(3e-16, 4e-16, 0)).Length, 15);      // Normalized: zero
            Assert.Equal(1.0, AlphaWrapOracle.Unit(new Vector3d(3e-300, 4e-300, 0)).Length, 15);
            Assert.Equal(1.0, AlphaWrapOracle.Unit(new Vector3d(3e300, 4e300, 0)).Length, 15);
            Assert.Equal(0.6, AlphaWrapOracle.Unit(new Vector3d(3e300, 4e300, 0)).x, 15);
            Assert.Equal(Vector3d.Zero, AlphaWrapOracle.Unit(Vector3d.Zero));
        }

        // random soups of 3 to 42 triangles in the unit cube, the k-th of the sequence from seed 1
        internal static DMesh3 RandomSoup(int k)
        {
            var rnd = new Random(1);
            DMesh3 m = null;
            for (int s = 0; s <= k; ++s) {
                m = new DMesh3();
                int nt = 3 + rnd.Next(40);
                for (int t = 0; t < nt; ++t) {
                    Vector3d c = new Vector3d(rnd.NextDouble(), rnd.NextDouble(), rnd.NextDouble());
                    double sz = 0.05 + 0.4 * rnd.NextDouble();
                    Func<Vector3d> jitter = () => new Vector3d(rnd.NextDouble() - 0.5, rnd.NextDouble() - 0.5, rnd.NextDouble() - 0.5);
                    int a = m.AppendVertex(c + sz * jitter()), b = m.AppendVertex(c + sz * jitter()), d = m.AppendVertex(c + sz * jitter());
                    m.AppendTriangle(a, b, d);
                }
            }
            return m;
        }

        // an ellipsoid: a sphere of radius 0.5 scaled by sx, sy, sz
        internal static DMesh3 Ellipsoid(double sx, double sy, double sz)
        {
            DMesh3 m = Sphere(0.5, 6);
            MeshTransforms.Scale(m, sx, sy, sz);
            return m;
        }

        /// <summary> the smallest distance between two vertices of the triangulation (a nearest neighbour is joined by a
        /// Delaunay edge), without the eight box corners </summary>
        internal static double MinSteinerSeparation(Delaunay3 dt)
        {
            double min = double.MaxValue;
            foreach (int c in dt.CellIndices())
                for (int i = 0; i < 4; ++i)
                    for (int j = i + 1; j < 4; ++j) {
                        int a = dt.CellVertex(c, i), b = dt.CellVertex(c, j);
                        if (a >= 8 && b >= 8) min = Math.Min(min, dt.GetVertex(a).Distance(dt.GetVertex(b)));
                    }
            return min;
        }

        /// <summary> the smallest angle (degrees) of the result triangles with a circumradius of at most alpha </summary>
        internal static double MinAngleOfSmallTriangles(DMesh3 r, double alpha)
        {
            double min = 180;
            foreach (int tid in r.TriangleIndices()) {
                Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
                r.GetTriVertices(tid, ref a, ref b, ref c);
                double ab = a.Distance(b), bc = b.Distance(c), ca = c.Distance(a);
                double area2 = (b - a).Cross(c - a).Length;
                if (!(area2 > 0)) return 0;
                if (ab * bc * ca / (2 * area2) > alpha) continue;       // circumradius abc / (4 area)
                // smallest angle: opposite the shortest edge, sin = area2 / (product of the other two edges)
                double e = Math.Min(ab, Math.Min(bc, ca));
                double sin = e == ab ? area2 / (bc * ca) : e == bc ? area2 / (ab * ca) : area2 / (ab * bc);
                min = Math.Min(min, Math.Asin(Math.Min(1, sin)) * 180 / Math.PI);
            }
            return min;
        }

        [Theory]
        [InlineData(5.0, 0.3, 0.45)]
        [InlineData(5.0, 1.0, 0.45)]
        public void Wrap_FlatBoxCornerCells_SteinerPointsSeparated(double sx, double sy, double sz)
        {
            // At small alpha the first Steiner points lie about 2 alpha inside the box faces, so cells of three box corners
            // and such a point are flat, with circumradii above the 4 box diagonals at which dual_edge clamps the
            // circumcenter. Rule 2 projected the clamped center: points outside the cell's circumsphere, which left the
            // cell, and the points of neighbouring flat cells landed next to each other (3.7e-5 and 0.011 offsets apart
            // here; Thingi10K 59196 and 163738 likewise), with needles of 1e-4 and 0.03 degrees on the result.
            // The projection of the cell's own circumcenter lies deep inside the empty circumsphere: every Steiner point is
            // farther than min(offset, alpha - offset) from the others (MeshAlphaWrap class doc), which bounds the angles
            // of all result triangles with a circumradius of at most alpha.
            DMesh3 m = Ellipsoid(sx, sy, sz);
            var w = new MeshAlphaWrap(m) { RelativeAlpha = 150, RelativeOffset = 1500 };
            Assert.True(w.Compute(), w.Error);
            CheckWrap(w, Vertices(m));
            AssertSeparationBound(w, "");

            // reused instance: the same result and counts
            var vertices = Vertices(w.Result);
            Assert.True(w.Compute(), w.Error);
            Assert.Equal(vertices, Vertices(w.Result));
            Assert.Equal(0, ProjectionFallbacks(w));
        }

        internal static long ProjectionFallbacks(MeshAlphaWrap w)
        {
            return w.Counts.TryGetValue("projection_fallbacks", out long n) ? n : 0;
        }

        /// <summary>
        /// The derived bounds of the MeshAlphaWrap class doc: Steiner points at least min(offset, alpha - offset) apart
        /// (less the contact margin and rounding: 1e-5 of the bound), and the min angle asin(that / (2 alpha)) on every result
        /// triangle with a circumradius of at most alpha; no rule 2 point from the fallback
        /// </summary>
        internal static void AssertSeparationBound(MeshAlphaWrap w, string what)
        {
            double alpha = w.UsedAlpha, off = w.UsedOffset, bound = (1 - 1e-5) * Math.Min(off, alpha - off);
            double sep = MinSteinerSeparation(w.Triangulation);
            Assert.True(sep >= bound, $"{what}: Steiner points {sep / off} offsets apart");
            double angleBound = Math.Asin(bound / (2 * alpha)) * 180 / Math.PI;
            double minAngle = MinAngleOfSmallTriangles(w.Result, alpha);
            Assert.True(minAngle >= angleBound, $"{what}: min angle {minAngle} below {angleBound} degrees");
            Assert.Equal(0, ProjectionFallbacks(w));
        }


        /// <summary> the angle bound of the class doc for every result triangle: min angle at least asin(b / (2 alpha)), max
        /// angle at most 180 degrees minus twice that, b = min(offset, alpha - offset) (less 1e-5 of it) </summary>
        internal static void AssertAngleBoundOnAllTriangles(MeshAlphaWrap w, string what)
        {
            double alpha = w.UsedAlpha, off = w.UsedOffset, bound = (1 - 1e-5) * Math.Min(off, alpha - off);
            double lo = Math.Asin(bound / (2 * alpha)) * 180 / Math.PI;
            DMesh3 r = w.Result;
            foreach (int tid in r.TriangleIndices()) {
                Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
                r.GetTriVertices(tid, ref a, ref b, ref c);
                Func<Vector3d, Vector3d, double> ang = (u, v) => Math.Atan2(u.Cross(v).Length, u.Dot(v)) * 180 / Math.PI;
                double a0 = ang(b - a, c - a), a1 = ang(a - b, c - b), a2 = ang(a - c, b - c);
                double min = Math.Min(a0, Math.Min(a1, a2)), max = Math.Max(a0, Math.Max(a1, a2));
                Assert.True(min >= lo && max <= 180 - 2 * lo, $"{what}: triangle {tid} with angles {min} / {max}, bound {lo}");
            }
        }

        [Theory]
        [InlineData(42)]
        [InlineData(173)]
        public void Wrap_NonManifoldSpots_AngleBoundOnAllTriangles(int k)
        {
            // Random soups with many pinches of the carved surface (63 and 95 cells moved by the manifold step at
            // alpha = 10 offset). The manifold step moved outside cells inside, and their facets, never gates, made 9 and
            // 5 triangles outside the angle bound (min 0.83 and 1.43 degrees against 2.87; caps). The refinement at the
            // non-manifold spots inserts Steiner points there first, so that carving makes the surface manifold: every
            // triangle within the bound, and the result within offset + alpha of the input (before: beyond offset + 2 alpha on soup 42)
            DMesh3 m = RandomSoup(k);
            var w = new MeshAlphaWrap(m) { RelativeAlpha = 20, RelativeOffset = 200 };
            Assert.True(w.Compute(), w.Error);
            CheckWrap(w, Vertices(m));
            AssertAngleBoundOnAllTriangles(w, "soup " + k);
            AssertSeparationBound(w, "soup " + k);
            var oracle = Oracle(w);
            double band = 0;
            foreach (int tid in w.Result.TriangleIndices()) {
                Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
                w.Result.GetTriVertices(tid, ref a, ref b, ref c);
                foreach (Vector3d q in new[] { (a + b + c) / 3, (a + b) / 2, (b + c) / 2, (c + a) / 2 })
                    band = Math.Max(band, oracle(q));
            }
            // (sampled at centroids and edge midpoints: a lower bound of the true band, against offset + alpha)
            Assert.True(band <= w.UsedOffset + w.UsedAlpha, $"sampled result {band} from the input, offset + alpha {w.UsedOffset + w.UsedAlpha}");

            // reused instance: the same result
            var vertices = Vertices(w.Result);
            Assert.True(w.Compute(), w.Error);
            Assert.Equal(vertices, Vertices(w.Result));
        }

        [Fact]
        public void Wrap_ManifoldStep_KeepsBoxCornerCellsOutside()
        {
            // the manifold step kept the largest of several outside components around a vertex and moved the others
            // inside, also one with a box corner: the corner on the result (here with the box of the retry; Thingi10K
            // 286985 likewise). The outside component with a box corner is kept now
            DMesh3 m = RandomSoup(136);
            var w = new MeshAlphaWrap(m) { RelativeAlpha = 10, RelativeOffset = 300, StartWithOtherBox = true };
            Assert.True(w.Compute(), w.Error);
            Assert.Equal(0, w.Counts["result_box_corners"]);
            CheckWrap(w, Vertices(m));
        }

        [Fact]
        public void Wrap_NullCancelF_NeverCancels()
        {
            var w = new MeshAlphaWrap(Sphere(1, 6)) { RelativeAlpha = 10, CancelF = null };
            Assert.True(w.Compute());       // (was a NullReferenceException)
            CheckWrap(w, Vertices(Sphere(1, 6)));
        }

        [Fact]
        public void Wrap_LargeFiniteCoordinates_NotInvalidInput()
        {
            // the finiteness test summed the coordinates, which overflows for large finite values
            var w = new MeshAlphaWrap(new[] { new Vector3d(1e308, 1e308, 1e308), new Vector3d(-1e308, 1e308, 1e308) });
            bool ok = w.Compute();
            Assert.NotEqual(MeshAlphaWrap.WrapStatus.InvalidInput, w.Status);
            // (today this ends in InvalidParameters: the relative alpha of a 1e308 box overflows. If it ever succeeds,
            // the guarantees must hold where the coordinates are this large.)
            if (ok) {
                ResultChecks.AssertClosed(w.Result);
                Assert.Equal(0, MeshRepairMetrics.SelfIntersections(w.Result));
            }
            var nan = new MeshAlphaWrap(new[] { new Vector3d(double.NaN, 0, 0), Vector3d.One });
            Assert.False(nan.Compute());
            Assert.Equal(MeshAlphaWrap.WrapStatus.InvalidInput, nan.Status);
        }

        [Theory]
        [InlineData(1e-4)]
        [InlineData(1e-6)]
        public void Wrap_UtmCoordinates_SmallOffset(double offset)
        {
            // a 10 m sphere at UTM coordinates with an offset far below a millimetre: the floating-point distance
            // tests (absolute coordinates, about 1e-9 rounding) must still keep the result outside the input
            DMesh3 s = Sphere(5, 6);
            MeshTransforms.Translate(s, new Vector3d(512345.678, 5812345.678, 312.5));
            var w = new MeshAlphaWrap(s) { Alpha = 1, Offset = offset };
            Assert.True(w.Compute());
            DMesh3 r = w.Result;
            Assert.True(r.IsClosed());
            Assert.Equal(0, MeshRepairMetrics.SelfIntersections(r));
            // no result triangle crosses the input, and the input is inside
            DMesh3 both = new DMesh3(r);
            MeshEditor.Append(both, s);
            Assert.Equal(0, MeshRepairMetrics.SelfIntersections(both));
            var spatial = new DMeshAABBTree3(r, true);
            Assert.All(Vertices(s), p => Assert.True(spatial.WindingNumber(p) > 0.99));
            var tree = new DMeshAABBTree3(s, true);
            foreach (int vid in r.VertexIndices()) {
                Vector3d p = r.GetVertex(vid);
                double d = Math.Sqrt(MeshQueries.TriangleDistance(s, tree.FindNearestTriangle(p), p).DistanceSquared);
                Assert.True(d > 0.99 * offset, $"vertex at distance {d}, offset {offset}");
            }
        }

        [Fact]
        public void Wrap_MicrometreScale()
        {
            DMesh3 s = Sphere(1e-6, 6);
            var w = new MeshAlphaWrap(s) { RelativeAlpha = 10 };
            Assert.True(w.Compute());
            CheckWrap(w, Vertices(s));
        }

        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        public void Wrap_PointLimitAlmostZero_TheBoxEnclosesTheInput(int limit)
        {
            // no or one Steiner point: the result is the box (corners on the result, which PointLimitReached allows),
            // closed and around the input
            DMesh3 s = Sphere(1, 6);
            var w = new MeshAlphaWrap(s) { RelativeAlpha = 10, MaxSteinerPoints = limit };
            Assert.False(w.Compute());
            Assert.Equal(MeshAlphaWrap.WrapStatus.PointLimitReached, w.Status);
            Assert.True(w.Result.IsClosed());
            Assert.Equal(8, w.Counts["result_box_corners"]);
            var spatial = new DMeshAABBTree3(w.Result, true);
            Assert.All(Vertices(s), p => Assert.True(spatial.WindingNumber(p) > 0.99));
        }

        [Fact]
        public void Delaunay3_DegeneratePointSets_Valid()
        {
            // coplanar, collinear, cospherical (cube corners) and duplicated points: the box corners make every set
            // full-dimensional, the triangulation stays valid and Delaunay
            var box = new AxisAlignedBox3d(new Vector3d(-2, -2, -2), new Vector3d(2, 2, 2));
            var sets = new List<List<Vector3d>>();
            var rnd = new Random(5);
            sets.Add(Enumerable.Range(0, 50).Select(k => new Vector3d(rnd.NextDouble() - 0.5, rnd.NextDouble() - 0.5, 0)).ToList());
            sets.Add(Enumerable.Range(0, 20).Select(k => new Vector3d(0.05 * k - 0.5, 0.1, 0.2)).ToList());
            sets.Add(new List<Vector3d>() { new Vector3d(-1, -1, -1), new Vector3d(1, -1, -1), new Vector3d(-1, 1, -1), new Vector3d(1, 1, -1),
                new Vector3d(-1, -1, 1), new Vector3d(1, -1, 1), new Vector3d(-1, 1, 1), new Vector3d(1, 1, 1), Vector3d.Zero });
            sets.Add(Enumerable.Range(0, 30).Select(k => { double a = 2 * Math.PI * k / 30; return new Vector3d(Math.Cos(a), Math.Sin(a), 0); }).ToList());
            foreach (var pts in sets) {
                var dt = new Delaunay3(box);
                foreach (var p in pts)
                    Assert.Equal(Delaunay3.InsertResult.Inserted, dt.Insert(p, -1, 0, out int v));
                foreach (var p in pts)      // duplicates: rejected
                    Assert.Equal(Delaunay3.InsertResult.TooClose, dt.Insert(p, -1, 0, out int v));
                Assert.Null(dt.Validate(true));
                Assert.Equal(box.Volume, dt.CellIndices().Sum(c => dt.CellVolume(c)), 9);
            }
            // a grid of points at UTM coordinates (10 m across, 0.5 m apart): cospherical everywhere, and the
            // coordinates far from the origin
            Vector3d o = new Vector3d(512345.678, 5812345.678, 312.5);
            var utm = new Delaunay3(new AxisAlignedBox3d(o - 6 * Vector3d.One, o + 6 * Vector3d.One));
            for (int i = 0; i < 6; ++i)
                for (int j = 0; j < 6; ++j)
                    for (int k = 0; k < 6; ++k)
                        Assert.Equal(Delaunay3.InsertResult.Inserted, utm.Insert(o + 0.5 * new Vector3d(i, j, k), -1, 0, out int v));
            Assert.Null(utm.Validate(true));
        }
    }
