            Assert.Equal(18.0 / 6.0, fit.Box.Extent.z, 10);
            Assert.Equal(1.0, Math.Abs(fit.Box.AxisZ.z), 10);
        }

        [Fact]
        public void OrthogonalPlaneFit3_DiagonalCovariance_IsValid()
        {
