        // an arrangement of a few random triangles, so that the predicates can be compared on its points
        static ExactMeshArrangement Arrangement(List<Vector3d> pts, out ExactMeshArrangement.InputTriangle tri)
        {
            DMesh3 mesh = new DMesh3();
            foreach (Vector3d p in pts)
                mesh.AppendVertex(p);
            mesh.AppendTriangle(0, 1, 2);
            var arr = new ExactMeshArrangement(new List<DMesh3>() { mesh });
            arr.Compute();
            tri = arr.Triangles[0];
            return arr;
        }

        /// <summary>
        /// AddPoint from many threads at once (the classification adds the pieces' centroids in parallel, into sharded
        /// indices): one id per distinct point, the same id for every call with that point, and its exact value stored
        /// </summary>
        [Fact]
        public void AddPoint_InParallel_OneIdPerPoint()
        {
            ExactMeshArrangement.InputTriangle tri;
            var arr = Arrangement(new List<Vector3d>() { new Vector3d(0, 0, 0), new Vector3d(1, 0, 0), new Vector3d(0, 1, 0) }, out tri);
            var rand = new Random(3);
            var points = Enumerable.Range(0, 3000).Select(_ => ExactPoint3.Create(rand.Next(-1000, 1000), rand.Next(-1000, 1000),
                rand.Next(-1000, 1000), rand.Next(1, 50))).ToList();
            // and pairs with equal hashes (y + 1, z - 31 gives the same ExactPoint3 hash for small values): equal
            // hashes must not merge different points
            for (int k = 0; k < 200; ++k) {
                int x = rand.Next(-1000, 1000), y = rand.Next(-1000, 1000), z = rand.Next(-1000, 1000);
                var p = ExactPoint3.FromInteger(x, y, z);
                var q = ExactPoint3.FromInteger(x, y + 1, z - 31);
                Assert.Equal(p.GetHashCode(), q.GetHashCode());
                points.Add(p); points.Add(q);
            }
            points = points.Distinct().ToList();
            int before = arr.PointCount;
            // every point added by 8 calls, in a shuffled order, in parallel
            var calls = Enumerable.Range(0, 8 * points.Count).Select(i => i % points.Count).OrderBy(_ => rand.Next()).ToArray();
            var ids = new int[calls.Length];
            System.Threading.Tasks.Parallel.For(0, calls.Length, i => ids[i] = arr.AddPoint(points[calls[i]]));
            var idOf = new Dictionary<int, int>();
            for (int i = 0; i < calls.Length; ++i) {
                if (idOf.TryGetValue(calls[i], out int id))
                    Assert.Equal(id, ids[i]);
                else
                    idOf[calls[i]] = ids[i];
            }
            Assert.Equal(points.Count, idOf.Values.Distinct().Count());
            Assert.Equal(before + points.Count, arr.PointCount);
            foreach (var kv in idOf)
                Assert.Equal(points[kv.Key], arr.Exact(kv.Value));
            // a point added again later gets its id back
            Assert.Equal(idOf[0], arr.AddPoint(points[0]));
        }

        [Fact]
        public void Orient_And_InCircle_MatchExactPredicates()
        {
            var rand = new Random(11);
            for (int iter = 0; iter < 300; ++iter) {
                // points in the plane z = 0 (projection drops z), some on a coarse grid to get exact ties
                Func<Vector3d> next = () => (iter % 2 == 0)
                    ? new Vector3d(rand.Next(-3, 4), rand.Next(-3, 4), 0)
                    : new Vector3d(rand.NextDouble() * 1e6 - 5e5, rand.NextDouble() * 1e-3, 0);
                var pts = new List<Vector3d>() { new Vector3d(0, 0, 0), new Vector3d(1, 0, 0), new Vector3d(0, 1, 0), next(), next(), next(), next() };
                // keep the triangle orientation, swap the winding sometimes
                if (iter % 3 == 0) { var tmp = pts[1]; pts[1] = pts[2]; pts[2] = tmp; }
                ExactMeshArrangement.InputTriangle tri;
                var arr = Arrangement(pts, out tri);
                int sign = ExactPredicates.Orient2d(pts[0].xy, pts[1].xy, pts[2].xy);
                int[] id = Enumerable.Range(0, pts.Count).Select(k => arr.VertexPoints[0][k]).ToArray();
                for (int k = 0; k < 20; ++k) {
                    int a = rand.Next(pts.Count), b = rand.Next(pts.Count), c = rand.Next(pts.Count), d = rand.Next(pts.Count);
                    Assert.Equal(sign * ExactPredicates.Orient2d(pts[a].xy, pts[b].xy, pts[c].xy), arr.Orient(tri, id[a], id[b], id[c]));
                    // both are the determinant sign; the arrangement's is relative to the triangle orientation
                    Assert.Equal(sign * ExactPredicates.InCircle(pts[a].xy, pts[b].xy, pts[c].xy, pts[d].xy), arr.InCircle(tri, id[a], id[b], id[c], id[d]));
                }
            }
        }

        [Fact]
        public void PlanesPoint_LiesOnAllThreePlanes()
        {
            var rand = new Random(5);
            for (int iter = 0; iter < 50; ++iter) {
                var pts = new List<Vector3d>();
                for (int k = 0; k < 9; ++k)
                    pts.Add(new Vector3d(rand.NextDouble(), rand.NextDouble(), rand.NextDouble()) * Math.Pow(10, rand.Next(-5, 6)));
                DMesh3 mesh = new DMesh3();
                foreach (Vector3d p in pts) mesh.AppendVertex(p);
                mesh.AppendTriangle(0, 1, 2); mesh.AppendTriangle(3, 4, 5); mesh.AppendTriangle(6, 7, 8);
                var arr = new ExactMeshArrangement(new List<DMesh3>() { mesh });
                arr.Compute();
                var planes = arr.Triangles.Select(t => t.P).ToArray();
                int id = arr.PlanesPoint(planes[0], planes[1], planes[2]);
                ExactPoint3 x = arr.Exact(id);
                foreach (var pl in planes)
                    Assert.True((pl.A * x.X + pl.B * x.Y + pl.C * x.Z - pl.D * x.W).IsZero);
                // the same point from the planes in another order is the same point id
                Assert.Equal(id, arr.PlanesPoint(planes[2], planes[0], planes[1]));
                // an edge crossing a plane: the direct formula gives the same point as three planes
                var t0 = arr.Triangles[0];
                for (int k = 0; k < 3; ++k) {
                    int p = t0.Corners[k], q = t0.Corners[(k + 1) % 3];
                    var pl = planes[1];
                    var P = arr.Exact(p); var Q = arr.Exact(q);
                    var sp = pl.A * P.X + pl.B * P.Y + pl.C * P.Z - pl.D; var sq = pl.A * Q.X + pl.B * Q.Y + pl.C * Q.Z - pl.D;
                    if (sp.Sign * sq.Sign >= 0) continue;
                    Assert.Equal(arr.PlanesPoint(t0.P, t0.EdgePlanes[k], pl), arr.EdgePlanePoint(p, q, pl));
                }
            }
        }


        [Fact]
        public void Triangulation_PointsAndConstraints()
        {
            var rand = new Random(7);
            for (int iter = 0; iter < 20; ++iter) {
                // grid points (many collinear and cocircular), in an outer triangle
                var pts = new List<Vector3d>() { new Vector3d(0, 0, 0), new Vector3d(16, 0, 0), new Vector3d(0, 16, 0) };
                var seen = new HashSet<Vector2d>(pts.Select(p => p.xy));
                while (pts.Count < 40) {
                    var p = new Vector3d(rand.Next(0, 17), rand.Next(0, 17), 0);
                    if (p.x + p.y <= 16 && seen.Add(p.xy)) pts.Add(p);
                }
                DMesh3 mesh = new DMesh3();
                foreach (Vector3d p in pts) mesh.AppendVertex(p);
                mesh.AppendTriangle(0, 1, 2);
                var arr = new ExactMeshArrangement(new List<DMesh3>() { mesh });
                arr.Compute();
                var tri = arr.Triangles[0];
                int[] id = Enumerable.Range(0, pts.Count).Select(k => arr.VertexPoints[0][k]).ToArray();
                var tr = new ExactTriangulation2(id[0], id[1], id[2], (a, b, c) => arr.Orient(tri, a, b, c), (a, b, c, d) => arr.InCircle(tri, a, b, c, d));
                for (int k = 3; k < pts.Count; ++k)
                    tr.InsertPoint(id[k]);
                // points are found by walking from the last insertion, not by searching all triangles
                Assert.Equal(0, tr.LinearSearches);
                // and the triangulation is kept Delaunay while they are inserted (before MakeDelaunay)
                {
                    var t0 = tr.Triangles().ToList();
                    var opp = new Dictionary<long, int>();
                    foreach (Index3i t in t0)
                        for (int k = 0; k < 3; ++k)
                            opp[((long)t[k] << 32) | (uint)t[(k + 1) % 3]] = t[(k + 2) % 3];
                    foreach (Index3i t in t0)
                        for (int k = 0; k < 3; ++k)
                            if (opp.TryGetValue(((long)t[(k + 1) % 3] << 32) | (uint)t[k], out int d))
                                Assert.True(arr.InCircle(tri, t[k], t[(k + 1) % 3], t[(k + 2) % 3], d) <= 0, "not Delaunay after the insertions");
                }
                tr.MakeDelaunay();
                // non-crossing constraints between random point pairs, without points on them
                var constraints = new List<Tuple<int, int>>();
                for (int tries = 0; tries < 200 && constraints.Count < 6; ++tries) {
                    int a = rand.Next(pts.Count), b = rand.Next(pts.Count);
                    if (a == b) continue;
                    bool ok = true;
                    // (closed box test: AxisAlignedBox2d.Contains is strict)
                    double x0 = Math.Min(pts[a].x, pts[b].x), x1 = Math.Max(pts[a].x, pts[b].x);
                    double y0 = Math.Min(pts[a].y, pts[b].y), y1 = Math.Max(pts[a].y, pts[b].y);
                    for (int k = 0; k < pts.Count && ok; ++k)
                        if (k != a && k != b && ExactPredicates.Orient2d(pts[a].xy, pts[b].xy, pts[k].xy) == 0
                            && pts[k].x >= x0 && pts[k].x <= x1 && pts[k].y >= y0 && pts[k].y <= y1)
                            ok = false;
                    foreach (var c in constraints) {
                        if (!ok) break;
                        int c0 = c.Item1, c1 = c.Item2;
                        if (c0 == a || c0 == b || c1 == a || c1 == b) continue;
                        int o1 = ExactPredicates.Orient2d(pts[a].xy, pts[b].xy, pts[c0].xy), o2 = ExactPredicates.Orient2d(pts[a].xy, pts[b].xy, pts[c1].xy);
                        int o3 = ExactPredicates.Orient2d(pts[c0].xy, pts[c1].xy, pts[a].xy), o4 = ExactPredicates.Orient2d(pts[c0].xy, pts[c1].xy, pts[b].xy);
                        if (o1 * o2 <= 0 && o3 * o4 <= 0) ok = false;
                    }
                    if (ok) constraints.Add(Tuple.Create(a, b));
                }
                foreach (var c in constraints)
                    tr.InsertConstraint(id[c.Item1], id[c.Item2]);
                // the crossed edges are found by walking along the constraint, not by searching all edges
                Assert.Equal(0, tr.LinearSearches);
                tr.MakeDelaunay();

                var tris = tr.Triangles().ToList();
                // Euler: T = 2V - B - 2 with B points on the boundary
                int boundary = pts.Count(p => p.y == 0 || p.x == 0 || p.x + p.y == 16);
                Assert.Equal(2 * pts.Count - boundary - 2, tris.Count);
                double area = 0;
                var edges = new HashSet<long>();
                foreach (Index3i t in tris) {
                    Assert.Equal(1, arr.Orient(tri, t.a, t.b, t.c));
                    Vector2d a = arr.PointToVector(t.a).xy, b = arr.PointToVector(t.b).xy, c = arr.PointToVector(t.c).xy;
                    area += 0.5 * ((b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x));
                    edges.Add(ExactMeshArrangement.EdgeKey(t.a, t.b)); edges.Add(ExactMeshArrangement.EdgeKey(t.b, t.c)); edges.Add(ExactMeshArrangement.EdgeKey(t.c, t.a));
                }
                Assert.Equal(128.0, area, 9);
                foreach (var c in constraints)
                    Assert.Contains(ExactMeshArrangement.EdgeKey(id[c.Item1], id[c.Item2]), edges);
                // constrained Delaunay: across every edge that is not a constraint, the opposite vertex is not inside the circle
                var constrainedKeys = new HashSet<long>(constraints.Select(c => ExactMeshArrangement.EdgeKey(id[c.Item1], id[c.Item2])));
                var opposite = new Dictionary<long, int>();
                foreach (Index3i t in tris)
                    for (int k = 0; k < 3; ++k)
                        opposite[((long)t[k] << 32) | (uint)t[(k + 1) % 3]] = t[(k + 2) % 3];
                foreach (Index3i t in tris)
                    for (int k = 0; k < 3; ++k) {
                        int a = t[k], b = t[(k + 1) % 3];
                        if (constrainedKeys.Contains(ExactMeshArrangement.EdgeKey(a, b))) continue;
                        if (opposite.TryGetValue(((long)b << 32) | (uint)a, out int d))
                            Assert.True(arr.InCircle(tri, a, b, t[(k + 2) % 3], d) <= 0, "not Delaunay");
                    }
            }
        }
        static DMesh3 RotatedBox(Vector3d center, double size, Quaterniond rotation)
        {
            DMesh3 mesh = new TrivialBox3Generator() { Box = new Box3d(center, new Vector3d(size, size, size)) }.Generate().MakeDMesh();
            MeshTransforms.Rotate(mesh, center, rotation);
            return mesh;
        }

        [Theory]
        [InlineData(1)]
        [InlineData(2)]
        [InlineData(3)]
        public void Arrangement_ThreeMeshes_PiecesAreClosedAndCoverTheInput(int seed)
        {
            // three mutually intersecting boxes: triple points, where segments of two meshes cross in a triangle of the third
            var rand = new Random(seed);
            Func<Quaterniond> rot = () => new Quaterniond(new Vector3d(rand.NextDouble() - 0.5, rand.NextDouble() - 0.5, rand.NextDouble() - 0.5).Normalized, rand.NextDouble() * 360);
            var meshes = new List<DMesh3>() {
                RotatedBox(Vector3d.Zero, 1, rot()), RotatedBox(new Vector3d(0.7, 0.2, 0.1), 0.8, rot()), RotatedBox(new Vector3d(0.2, 0.7, -0.3), 0.9, rot())
            };
            var arr = new ExactMeshArrangement(meshes);
            arr.Compute();
            Assert.True(arr.SegmentCrossings > 0);

            for (int m = 0; m < meshes.Count; ++m) {
                // every directed edge of the pieces of one mesh has exactly one opposite
                var directed = new Dictionary<long, int>();
                foreach (var ot in arr.Output.Where(o => o.Mesh == m)) {
                    foreach (var e in new[] { Tuple.Create(ot.A, ot.B), Tuple.Create(ot.B, ot.C), Tuple.Create(ot.C, ot.A) }) {
                        long key = ((long)e.Item1 << 32) | (uint)e.Item2;
                        directed[key] = directed.TryGetValue(key, out int c) ? c + 1 : 1;
                    }
                }
                foreach (var kv in directed) {
                    long rev = ((kv.Key & 0xFFFFFFFF) << 32) | (kv.Key >> 32);
                    Assert.Equal(1, kv.Value);
                    Assert.True(directed.ContainsKey(rev), "open edge in the pieces of mesh " + m);
                }
                // the pieces of each input triangle have its area and orientation
                foreach (int ti in arr.MeshTriangles[m]) {
                    var src = arr.Triangles[ti];
                    Vector3d a = arr.PointToVector(src.Corners[0]), b = arr.PointToVector(src.Corners[1]), c = arr.PointToVector(src.Corners[2]);
                    Vector3d n = (b - a).Cross(c - a);
                    double area = 0;
                    foreach (var ot in arr.Output.Where(o => o.Source == ti)) {
                        Vector3d pa = arr.PointToVector(ot.A), pb = arr.PointToVector(ot.B), pc = arr.PointToVector(ot.C);
                        double signed = 0.5 * (pb - pa).Cross(pc - pa).Dot(n) / n.Length;
                        Assert.True(signed > -1e-12);
                        area += signed;
                    }
                    Assert.Equal(0.5 * n.Length, area, 9);
                }
            }
        }

        [Fact]
        public void Filters_MatchExact_OnRationalPoints()
        {
            // a triangle in the plane z = 0, and rational points whose double approximations are inexact
            foreach (bool filters in new[] { true, false }) {
                ExactMeshArrangement.InputTriangle tri;
                var arr = Arrangement(new List<Vector3d>() { new Vector3d(0, 0, 0), new Vector3d(1, 0, 0), new Vector3d(0, 1, 0) }, out tri);
                arr.DisableFilters = !filters;
                Func<long, long, long, int> pt = (x, y, w) => arr.AddPoint(ExactPoint3.Create(x, y, 0, w));
                // on the circle of radius 5/3: cocircular
                int c0 = pt(5, 0, 3), c1 = pt(3, 4, 3), c2 = pt(0, 5, 3), c3 = pt(-4, 3, 3), c4 = pt(-5, 0, 3);
                Assert.Equal(0, arr.InCircle(tri, c0, c1, c2, c3));
                Assert.Equal(0, arr.InCircle(tri, c1, c2, c3, c4));
                Assert.Equal(1, arr.InCircle(tri, c0, c1, c2, pt(1, 1, 3)));
                Assert.Equal(-1, arr.InCircle(tri, c0, c1, c2, pt(16, 0, 3)));
                // collinear: (1/3, 1/7) + k (2/3, 3/7)
                int l0 = pt(7, 3, 21), l1 = pt(21, 12, 21), l2 = pt(35, 21, 21);
                Assert.Equal(0, arr.Orient(tri, l0, l1, l2));
                Assert.Equal(1, arr.Orient(tri, l0, l1, pt(7, 4, 21)));
                // keys along d = (25, -1, 0): 25 * 7/25 - 7 = 0 for (7/25, 7) and the origin (in doubles 8.9e-16)
                int k0 = pt(7, 175, 25), k1 = pt(0, 0, 1);
                Assert.Equal(0, arr.compare_along(25, -1, 0, k0, k1));
                Assert.Equal(-1, arr.compare_along(25, -1, 0, pt(7, 176, 25), k1));
            }
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using g3;
using Xunit;
using Ops = g3.ExactMeshBoolean.Operations;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The two results of ExactMeshBoolean that are by design and documented as such (docs/OPERATIONS.md, "By design"):
    /// open inputs give open results (generalized winding number), and solids that touch along an edge give a result
    /// that is non-manifold there when welded by position, as in Manifold.
    /// </summary>
    public class ExactBooleanByDesignTests
    {
        static DMesh3 Box(double x0, double y0, double z0, double x1, double y1, double z1)
        {
            var box = new Box3d(new Vector3d((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2), new Vector3d((x1 - x0) / 2, (y1 - y0) / 2, (z1 - z0) / 2));
            DMesh3 mesh = new TrivialBox3Generator() { Box = box }.Generate().MakeDMesh();
            foreach (int vid in mesh.VertexIndices().ToArray()) {
                Vector3d v = mesh.GetVertex(vid);
                mesh.SetVertex(vid, new Vector3d(v.x < box.Center.x ? x0 : x1, v.y < box.Center.y ? y0 : y1, v.z < box.Center.z ? z0 : z1));
            }
            return mesh;
        }

        // vertices of the mesh at a position that another vertex has too
        static int DuplicatedPositions(DMesh3 m)
        {
            var count = new Dictionary<Vector3d, int>();
            foreach (int v in m.VertexIndices()) {
                Vector3d p = m.GetVertex(v);
                count[p] = count.TryGetValue(p, out int c) ? c + 1 : 1;
            }
            return count.Values.Where(c => c > 1).Sum();
        }

        [Fact]
        public void OpenInput_GivesOpenResult()
        {
            // a box without its top face (open) and a closed bar through its side wall y = 0 and out of its open top
            DMesh3 open = Box(0, 0, 0, 1, 1, 1);
            foreach (int t in open.TriangleIndices().ToArray()) {
                Index3i tv = open.GetTriangle(t);
                if (open.GetVertex(tv.a).z == 1 && open.GetVertex(tv.b).z == 1 && open.GetVertex(tv.c).z == 1)
                    open.RemoveTriangle(t);
            }
            Assert.False(open.IsClosed());
            DMesh3 bar = Box(0.25, -0.5, 0.5, 0.75, 0.5, 1.5);
            foreach (Ops op in new[] { Ops.Union, Ops.Intersection, Ops.Difference }) {
                var boolean = new ExactMeshBoolean(open, bar, op);
                Assert.True(boolean.Compute(), boolean.Error);
                Assert.Equal(ExactMeshBoolean.BooleanStatus.Success, boolean.Status);
                Assert.False(boolean.ExactWindingA);
                Assert.True(boolean.ExactWindingB);
                Assert.True(boolean.IntersectingPairs > 0);
                DMesh3 r = boolean.Result;
                ResultChecks.AssertValid(r);
                Assert.True(r.TriangleCount > 0, op + ": empty");
                if (op != Ops.Intersection) {
                    // the open box's solid (generalized winding number above 1/2) is not bounded at its missing face:
                    // union and difference keep the open box's floor and walls, which end at its open boundary
                    Assert.Contains(r.EdgeIndices(), e => r.IsBoundaryEdge(e));
                    Assert.False(ExactMeshBoolean.IsWindingClosed(r), op + ": closed");
                    // the floor is kept whole (the bar does not reach it)
                    Assert.Equal(2, r.TriangleIndices().Count(t => {
                        Index3i tv = r.GetTriangle(t);
                        return r.GetVertex(tv.a).z == 0 && r.GetVertex(tv.b).z == 0 && r.GetVertex(tv.c).z == 0;
                    }));
                }
            }
        }

        [Fact]
        public void OpenInput_RefusedWhenNotAllowed()
        {
            DMesh3 open = Box(0, 0, 0, 1, 1, 1);
            open.RemoveTriangle(open.TriangleIndices().First());
            var boolean = new ExactMeshBoolean(open, Box(0.5, 0.5, 0.5, 2, 2, 2), Ops.Union) { AllowOpenMeshes = false };
            Assert.False(boolean.Compute());
            Assert.Equal(ExactMeshBoolean.BooleanStatus.OpenInput, boolean.Status);
        }

        [Fact]
        public void SolidsTouchingAlongAnEdge_UnionNonManifoldAtTheEdge()
        {
            // unit boxes touching only along the edge x = 1, y = 1
            DMesh3 a = Box(0, 0, 0, 1, 1, 1), b = Box(1, 1, 0, 2, 2, 1);
            var boolean = new ExactMeshBoolean(a, b, Ops.Union);
            Assert.True(boolean.Compute(), boolean.Error);
            DMesh3 r = boolean.Result;
            ResultChecks.AssertValid(r);
            // closed and manifold as a DMesh3: the four triangles at the edge are split into two manifold pairs, with
            // copies of the edge's vertices
            Assert.True(r.IsClosed());
            Assert.Equal(1, boolean.NonManifoldEdges);
            Assert.Equal(0, boolean.NonManifoldTriangles);
            Assert.Equal(2.0, ResultChecks.Volume(r), 12);
            Assert.True(ExactMeshBoolean.IsWindingClosed(r));
            // welded by position, the two solids share the edge: its vertices are duplicated
            Assert.Equal(4, DuplicatedPositions(r));
            // two components, one per box
            var components = new MeshConnectedComponents(r);
            components.FindConnectedT();
            Assert.Equal(2, components.Count);
            // MeshRobustRepair.SeparateTouchingVertices moves the copies apart: no shared positions, still closed
            DMesh3 separated = new DMesh3(r);
            Assert.True(gs.MeshRobustRepair.SeparateTouchingVertices(separated, 1e-4) > 0);
            Assert.Equal(0, DuplicatedPositions(separated));
            Assert.True(separated.IsClosed());
            Assert.Equal(2.0, ResultChecks.Volume(separated), 3);
        }

        [Fact]
        public void SolidsTouchingAlongAnEdge_IntersectionEmpty_DifferenceIsA()
        {
            DMesh3 a = Box(0, 0, 0, 1, 1, 1), b = Box(1, 1, 0, 2, 2, 1);
            var inter = new ExactMeshBoolean(a, b, Ops.Intersection);
            Assert.True(inter.Compute(), inter.Error);
            Assert.Equal(0, inter.Result.TriangleCount);
            var diff = new ExactMeshBoolean(a, b, Ops.Difference);
            Assert.True(diff.Compute(), diff.Error);
            Assert.True(diff.Result.IsClosed());
            Assert.Equal(1.0, ResultChecks.Volume(diff.Result), 12);
            Assert.Equal(0, DuplicatedPositions(diff.Result));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// ExactMeshBoolean gives bit-identical results (vertex and triangle ids, coordinates) in repeated runs. The
    /// arrangement assigns the ids of its implicit points in parallel, so anything after it that orders by point
    /// id depends on the thread schedule: the Lawson flips of ExactPlanarSimplify (edges keyed by the smaller
    /// point id), and the splitting of edges where the result touches itself (edges and their pairs found in the
    /// order of point ids). Each case is run often enough that the old code gave several different results.
    /// </summary>
    public class ExactBooleanDeterminismTests
    {
        const int Runs = 30;

        static DMesh3 Box(Vector3d lo, Vector3d hi)
        {
            return new TrivialBox3Generator() { Box = new Box3d(new AxisAlignedBox3d(lo, hi)) }.Generate().MakeDMesh();
        }

        static DMesh3 Sphere(Vector3d center, double radius, int edgeVertices)
        {
            DMesh3 s = new Sphere3Generator_NormalizedCube() { Radius = radius, EdgeVertices = edgeVertices }.Generate().MakeDMesh();
            MeshTransforms.Translate(s, center);
            return s;
        }

        // every vertex and triangle id with its coordinates (bits) and vertices
        static string Fingerprint(DMesh3 m)
        {
            var sb = new StringBuilder();
            sb.Append(m.MaxVertexID).Append('/').Append(m.MaxTriangleID).Append('|');
            foreach (int v in m.VertexIndices()) {
                Vector3d p = m.GetVertex(v);
                sb.Append(v).Append(':').Append(BitConverter.DoubleToInt64Bits(p.x)).Append(',')
                    .Append(BitConverter.DoubleToInt64Bits(p.y)).Append(',').Append(BitConverter.DoubleToInt64Bits(p.z)).Append(';');
            }
            foreach (int t in m.TriangleIndices()) {
                Index3i f = m.GetTriangle(t);
                sb.Append(t).Append(':').Append(f.a).Append(',').Append(f.b).Append(',').Append(f.c).Append(';');
            }
            return sb.ToString();
        }

        static void AssertRepeatable(Func<ExactMeshBoolean> make, Action<ExactMeshBoolean> check = null)
        {
            string first = null;
            for (int run = 0; run < Runs; ++run) {
                ExactMeshBoolean b = make();
                Assert.True(b.Compute(), b.Error);
                check?.Invoke(b);
                // closed inputs: a closed, manifold result (the runs are identical, so checking the first is enough)
                if (run == 0)
                    ResultChecks.AssertClosed(b.Result);
                string print = Fingerprint(b.Result);
                if (b.ResultExactVertices != null)
                    print += "|" + string.Join(";", b.ResultExactVertices.Select(p => $"{p.X},{p.Y},{p.Z},{p.W}"));
                if (first == null)
                    first = print;
                else
                    Assert.True(first == print, $"run {run} differs from run 0");
            }
        }

        // the fingerprint of the result (with the exact vertices, if computed) of a boolean computed serially
        // (gParallel.ForRange runs its items one after the other on this thread)
        static string SerialFingerprint(Func<ExactMeshBoolean> make)
        {
            gParallel.SerialOnThisThread = true;
            try {
                ExactMeshBoolean b = make();
                Assert.True(b.Compute(), b.Error);
                return Fingerprint(b.Result) + ((b.ResultExactVertices != null) ? "|" + string.Join(";", b.ResultExactVertices.Select(p => $"{p.X},{p.Y},{p.Z},{p.W}")) : "");
            } finally {
                gParallel.SerialOnThisThread = false;
            }
        }

        static void AssertSerialEqualsParallel(Func<ExactMeshBoolean> make)
        {
            string serial = SerialFingerprint(make);
            for (int run = 0; run < 5; ++run) {
                ExactMeshBoolean b = make();
                Assert.True(b.Compute(), b.Error);
                string print = Fingerprint(b.Result) + ((b.ResultExactVertices != null) ? "|" + string.Join(";", b.ResultExactVertices.Select(p => $"{p.X},{p.Y},{p.Z},{p.W}")) : "");
                Assert.True(serial == print, $"parallel run {run} differs from the serial run");
            }
        }

        [Fact]
        public void SerialEqualsParallel_BitIdentical()
        {
            // the parallel phases (pair search, intersections, merge, triangulation, classification of the patches,
            // stacks of coplanar pieces) give the same result on one thread: box and sphere with flat regions,
            // coplanar boxes (n-ary, merged points, stacks), a self-intersecting input, an open input (generalized
            // winding numbers), touching boxes (split edges)
            DMesh3 box = Box(new Vector3d(-1.2, -1.1, -0.9), new Vector3d(0.3, 0.6, 1.1));
            DMesh3 sphere = Sphere(new Vector3d(-0.6, -0.5, 0.2), 0.7, 6);
            AssertSerialEqualsParallel(() => new ExactMeshBoolean(box, sphere, ExactMeshBoolean.Operations.Difference) { ComputeExactVertices = true });
            var boxes = new List<DMesh3>();
            for (int i = 0; i < 2; ++i)
                for (int j = 0; j < 2; ++j)
                    for (int k = 0; k < 2; ++k) {
                        boxes.Add(Box(new Vector3d(0.9 * i, 0.9 * j, 0.9 * k), new Vector3d(0.9 * i + 1, 0.9 * j + 1, 0.9 * k + 1)));
                        boxes.Add(Box(new Vector3d(0.9 * i + 0.25, 0.9 * j + 0.25, 0.9 * k + 0.25), new Vector3d(0.9 * i + 0.75, 0.9 * j + 0.75, 0.9 * k + 0.75)));
                    }
            AssertSerialEqualsParallel(() => new ExactMeshBoolean(boxes, (w) => w.Where((x, m) => m % 2 == 0 && x > 0).Any() && w.Where((x, m) => m % 2 == 1 && x > 0).Any() == false));
            DMesh3 twisted = Sphere(new Vector3d(0, 0, 0), 1, 8);
            MeshEditor.Append(twisted, Sphere(new Vector3d(0.6, 0.2, 0.1), 0.8, 7));
            AssertSerialEqualsParallel(() => new ExactMeshBoolean(twisted, box, ExactMeshBoolean.Operations.Union));
            DMesh3 open = Sphere(new Vector3d(-0.2, 0.1, 0), 0.9, 7);
            open.RemoveTriangle(open.TriangleIndices().First());
            AssertSerialEqualsParallel(() => new ExactMeshBoolean(open, box, ExactMeshBoolean.Operations.Intersection));
            var touching = new List<DMesh3>() { Box(new Vector3d(0, 0, 0), new Vector3d(1, 1, 1)), Box(new Vector3d(1, 1, -0.2), new Vector3d(2, 2, 1.3)),
                Sphere(new Vector3d(1.05, 0.93, 0.5), 0.15, 5) };
            AssertSerialEqualsParallel(() => new ExactMeshBoolean(touching, ExactMeshBoolean.Operations.Union));
        }

        [Theory]
        [InlineData(ExactMeshBoolean.Operations.Intersection)]
        [InlineData(ExactMeshBoolean.Operations.Union)]
        [InlineData(ExactMeshBoolean.Operations.Difference)]
        public void BoxAndSphere_RepeatedRuns_BitIdentical(ExactMeshBoolean.Operations op)
        {
            // flat regions of the box are simplified, with Lawson flips
            DMesh3 box = Box(new Vector3d(-1.2, -1.1, -0.9), new Vector3d(0.3, 0.6, 1.1));
            DMesh3 sphere = Sphere(new Vector3d(-0.6, -0.5, 0.2), 0.7, 6);
            AssertRepeatable(() => new ExactMeshBoolean(box, sphere, op), (b) => Assert.True(b.RemovedVertices > 0));
        }

        [Fact]
        public void SafeRoundingAndExactVertices_RepeatedRuns_BitIdentical()
        {
            DMesh3 box = Box(new Vector3d(-1.2, -1.1, -0.9), new Vector3d(0.3, 0.6, 1.1));
            DMesh3 sphere = Sphere(new Vector3d(-0.6, -0.5, 0.2), 0.7, 6);
            AssertRepeatable(() => new ExactMeshBoolean(box, sphere, ExactMeshBoolean.Operations.Intersection) { SafeRounding = true, ComputeExactVertices = true },
                (b) => {
                    Assert.NotNull(b.ResultExactVertices);
                    // SafeRounding: verified free of self-intersections and degenerate triangles (RoundingClean, the
                    // documented flag), and an independent check of the same
                    Assert.True(b.RoundingClean);
                    ResultChecks.AssertClean(b.Result);
                });
        }

        [Fact]
        public void CoplanarBoxes_RepeatedRuns_BitIdentical()
        {
            // overlapping boxes with coplanar faces: many points inside flat regions to remove
            var meshes = new List<DMesh3>();
            for (int i = 0; i < 2; ++i)
                for (int j = 0; j < 2; ++j)
                    for (int k = 0; k < 2; ++k)
                        meshes.Add(Box(new Vector3d(0.9 * i, 0.9 * j, 0.9 * k), new Vector3d(0.9 * i + 1, 0.9 * j + 1, 0.9 * k + 1)));
            AssertRepeatable(() => new ExactMeshBoolean(meshes, ExactMeshBoolean.Operations.Union), (b) => {
                Assert.True(b.RemovedVertices > 0);
                // the union is the cube [0, 1.9]^3, exactly
                Assert.Equal(1.9 * 1.9 * 1.9, ResultChecks.Volume(b.Result), 12);
            });
        }

        [Theory]
        [InlineData(false)]
        [InlineData(true)]
        public void TouchingAlongEdge_RepeatedRuns_BitIdentical(bool simplify)
        {
            // a box touched along two edges by two other boxes, spheres crossing the edges: each edge (split at
            // implicit points) has pieces with four triangles of the result, split per pair at new vertices
            var meshes = new List<DMesh3>() { Box(new Vector3d(0, 0, 0), new Vector3d(1, 1, 1)), Box(new Vector3d(1, 1, -0.2), new Vector3d(2, 2, 1.3)),
                Box(new Vector3d(-1, -1, -0.3), new Vector3d(0, 0, 1.2)) };
            for (int k = 0; k < 3; ++k) {
                meshes.Add(Sphere(new Vector3d(1.05, 0.93, 0.2 + 0.3 * k), 0.15, 5));
                meshes.Add(Sphere(new Vector3d(-0.04, 0.06, 0.25 + 0.3 * k), 0.13, 5));
            }
            AssertRepeatable(() => new ExactMeshBoolean(meshes, ExactMeshBoolean.Operations.Union) { SimplifyFlatRegions = simplify },
                (b) => Assert.True(b.SplitNonManifoldEdges > 2));
        }
    }
}

using System;
using g3;
using Xunit;
using Ops = g3.ExactMeshBoolean.Operations;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// ExactMeshBoolean pairs the triangles around an edge where solids touch by the order of their half-planes
    /// around the edge. Half-planes that differ by less than the rounding of the points must still be ordered
    /// correctly, or the result is not closed.
    /// </summary>
    public class ExactBooleanEdgeOrderTests
    {
        static double Volume(DMesh3 m) => MeshMeasurements.VolumeArea(m, m.TriangleIndices(), m.GetVertex).x;

        static DMesh3 Tetra(Vector3d a, Vector3d b, Vector3d c, Vector3d d)
        {
            DMesh3 m = new DMesh3();
            foreach (Vector3d v in new[] { a, b, c, d }) m.AppendVertex(v);
            m.AppendTriangle(0, 2, 1); m.AppendTriangle(0, 1, 3); m.AppendTriangle(1, 2, 3); m.AppendTriangle(0, 3, 2);
            if (Volume(m) < 0)
                m.ReverseOrientation();
            return m;
        }

        // the next double towards +infinity (s = 1) or -infinity (s = -1), for x != 0 (Math.BitIncrement is not in net48)
        static double Ulp(double x, int s)
        {
            long bits = BitConverter.DoubleToInt64Bits(x);
            return BitConverter.Int64BitsToDouble(bits + ((x > 0) == (s > 0) ? 1 : -1));
        }

        [Fact]
        public void TetrahedraTouchingAlongAnEdge_NearlyCoincidentFaces()
        {
            // tetrahedra (u, v, a, b) and (u, v, c, d) touching only along the oblique edge u-v, with c a few ulps
            // outside the face (u, v, b): the faces (u, v, b) and (u, v, c) differ by about 1e-16 radians
            var rand = new Random(1);
            int cases = 0;
            for (int it = 0; it < 300; ++it) {
                Vector3d u = new Vector3d(rand.NextDouble(), rand.NextDouble(), rand.NextDouble());
                Vector3d v = u + new Vector3d(1 + rand.NextDouble(), 0.7 + rand.NextDouble(), 0.3 + rand.NextDouble());
                Vector3d a = new Vector3d(3 * rand.NextDouble(), 3 * rand.NextDouble(), 3 * rand.NextDouble());
                Vector3d b = new Vector3d(3 * rand.NextDouble(), 3 * rand.NextDouble(), 3 * rand.NextDouble());
                int sa = ExactPredicates.Orient3d(u, v, b, a);
                if (sa == 0)
                    continue;
                int k = rand.Next(3);
                Vector3d c = b;
                for (int dir = 0; dir < 2 && ExactPredicates.Orient3d(u, v, b, c) != -sa; ++dir) {
                    c = b;
                    for (int step = 0; step < 30 && ExactPredicates.Orient3d(u, v, b, c) != -sa; ++step)
                        c[k] = Ulp(c[k], (dir == 0) ? 1 : -1);
                }
                if (ExactPredicates.Orient3d(u, v, b, c) != -sa)
                    continue;
                // d well on the other side of both planes (u, v, b) and (u, v, c)
                Vector3d n = (v - u).Cross(b - u).Normalized;
                Vector3d d = 0.5 * (u + v) + n * 2.0 * ((ExactPredicates.Orient3d(u, v, b, u + n) == -sa) ? 1 : -1);
                int sc = ExactPredicates.Orient3d(u, v, c, a);
                if (sc == 0 || ExactPredicates.Orient3d(u, v, b, d) != -sa || ExactPredicates.Orient3d(u, v, c, d) != -sc)
                    continue;
                DMesh3 t1 = Tetra(u, v, a, b), t2 = Tetra(u, v, c, d);
                var boolean = new ExactMeshBoolean(t1, t2, Ops.Union);
                Assert.True(boolean.Compute(), boolean.Error);
                DMesh3 r = boolean.Result;
                Assert.True(r.IsClosed(), "case " + it + ": not closed");
                Assert.Equal(0, boolean.NonManifoldTriangles);
                Assert.Equal(1, boolean.NonManifoldEdges);
                Assert.Equal(8, r.TriangleCount);
                Assert.Equal(Volume(t1) + Volume(t2), Volume(r), 12);
                cases++;
            }
            Assert.True(cases > 100, cases + " cases");
        }
    }
}

using System;
using System.Numerics;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The floating-point filters of ExactMeshBoolean (orient3d_filtered, plane_side_filtered), checked against exact
    /// signs: where a filter decides, its sign must be the sign for every exact input within the documented error of
    /// the doubles (relative 2^-52 per coordinate and coefficient), at all corners of the error boxes (the values are
    /// affine in each coordinate, so the corners are the worst case); nearly degenerate inputs, offsets far from the
    /// origin, magnitudes from just above TinyCoordinate to 2^300. And the filters must decide for well separated
    /// input, else they would only cost time. Found with the mutation tests (tests/mutation, stryker-mesh-boolean-2):
    /// mutants of the bounds survived, because no test compared the filters with exact values.
    /// </summary>
    public class ExactBooleanFilterTests
    {
        const int S = 1100;
        const double U = 2.220446049250313e-16;

        static BigInteger Q(double v)
        {
            BigInteger m; int e;
            ExactPoint3.Decompose(v, out m, out e);
            return m.IsZero ? BigInteger.Zero : (m << (e + S));
        }

        // the two ends of the error box of c: lo, hi (scaled by 2^S)
        static BigInteger[] Box(double c)
        {
            BigInteger q = Q(c), e = Q(U * Math.Abs(c));
            return new[] { q - e, q + e };
        }

        static BigInteger Corner(BigInteger[] box, int mask, int bit) => box[(mask >> bit) & 1];

        static double Rnd(Random r, int k) => (r.NextDouble() - 0.5) * Math.Pow(2, k + 1);

        static int[] Exponents = { -295, -200, -40, -3, 0, 10, 52, 60, 300 };

        static void AssertOrient3dAtCorners(Vector3d a, Vector3d b, Vector3d c, Vector3d d, int f, string what)
        {
            Vector3d[] v = { a, b, c, d };
            var boxes = new BigInteger[4, 3][];
            for (int i = 0; i < 4; ++i)
                for (int j = 0; j < 3; ++j)
                    boxes[i, j] = Box(v[i][j]);
            var X = new BigInteger[4, 3];
            for (int mask = 0; mask < 4096; ++mask) {
                for (int i = 0; i < 4; ++i)
                    for (int j = 0; j < 3; ++j)
                        X[i, j] = Corner(boxes[i, j], mask, 3 * i + j);
                BigInteger ux = X[1, 0] - X[0, 0], uy = X[1, 1] - X[0, 1], uz = X[1, 2] - X[0, 2];
                BigInteger vx = X[2, 0] - X[0, 0], vy = X[2, 1] - X[0, 1], vz = X[2, 2] - X[0, 2];
                BigInteger wx = X[3, 0] - X[0, 0], wy = X[3, 1] - X[0, 1], wz = X[3, 2] - X[0, 2];
                BigInteger det = wx * (uy * vz - uz * vy) + wy * (uz * vx - ux * vz) + wz * (ux * vy - uy * vx);
                if (-det.Sign != f)
                    Assert.Fail($"{what} mask={mask}: filter {f}, exact {-det.Sign}");
            }
        }

        // d moved off the plane of a, b, c by growing powers of two: the first offsets where the filter decides are
        // within a factor of about 2 of its error bound, where a bound that is too small gives wrong signs
        [Fact]
        public void Orient3dFiltered_SignHoldsAtAllCornersOfTheErrorBoxes()
        {
            var r = new Random(11);
            int cases = 0;
            foreach (int k in Exponents)
                foreach (int off in new[] { int.MinValue, k + 20, k + 45 })
                    for (int iter = 0; iter < 2; ++iter) {
                        double o = (off == int.MinValue) ? 0 : Math.Pow(2, off);
                        Func<Vector3d> p = () => new Vector3d(o + Rnd(r, k), o + Rnd(r, k), o + Rnd(r, k));
                        Vector3d a = p(), b = p(), c = p();
                        Vector3d n = (b - a).Cross(c - a).Normalized;
                        double s = r.NextDouble(), t = r.NextDouble();
                        Vector3d d0 = a + s * (b - a) + t * (c - a);
                        // (the unmoved point too: undecided, or decided correctly)
                        int f0 = ExactMeshBoolean.orient3d_filtered(ref a, ref b, ref c, ref d0);
                        if (f0 != 2)
                            AssertOrient3dAtCorners(a, b, c, d0, f0, $"orient3d k={k} off={off} iter={iter} unmoved");
                        int found = 0;
                        for (int j = -60; j <= 0 && found < 2; ++j) {
                            double sign = ((j + iter) % 2 == 0) ? 1 : -1;
                            Vector3d d = d0 + sign * Math.Pow(2, Math.Max(k, off == int.MinValue ? k : off) + j) * n;
                            int f = ExactMeshBoolean.orient3d_filtered(ref a, ref b, ref c, ref d);
                            if (f == 2)
                                continue;
                            AssertOrient3dAtCorners(a, b, c, d, f, $"orient3d k={k} off={off} iter={iter} j={j}");
                            found++;
                            cases++;
                        }
                    }
            Assert.True(cases > 40, $"{cases} decided cases");
        }

        [Fact]
        public void Orient3dFiltered_DecidesForSeparatedPoints_AndNotForTinyOnes()
        {
            var r = new Random(12);
            // (the determinant of 2^3k must stay above the permanent's underflow guard of 1e-280 and finite)
            foreach (int k in new[] { -90, -40, -3, 0, 10, 52, 60, 90 })
                for (int iter = 0; iter < 50; ++iter) {
                    double m = Math.Pow(2, k);
                    // (coordinates between 2^k and 2^(k+1) in magnitude: none below TinyCoordinate)
                    Vector3d a = new Vector3d(m * (1 + r.NextDouble()), -m * (1 + r.NextDouble()), m * (1 + r.NextDouble())), b = a + new Vector3d(Math.Pow(2, k), 0, 0),
                        c = a + new Vector3d(0, Math.Pow(2, k), 0), d = a + new Vector3d(0, 0, Math.Pow(2, k) * (iter % 2 == 0 ? 1 : -1));
                    // det3 [b-a; c-a; d-a] = +-2^3k: the sign of det4 is its negative
                    Assert.Equal(iter % 2 == 0 ? -1 : 1, ExactMeshBoolean.orient3d_filtered(ref a, ref b, ref c, ref d));
                }
            Vector3d z = Vector3d.Zero, x = Vector3d.AxisX, y = Vector3d.AxisY, t = new Vector3d(0, 0, 1e-200);
            Assert.Equal(2, ExactMeshBoolean.orient3d_filtered(ref z, ref x, ref y, ref t));
            Vector3d nan = new Vector3d(double.NaN, 0, 1), inf = new Vector3d(double.PositiveInfinity, 0, 1);
            Assert.Equal(2, ExactMeshBoolean.orient3d_filtered(ref z, ref x, ref y, ref nan));
            Assert.Equal(2, ExactMeshBoolean.orient3d_filtered(ref z, ref x, ref y, ref inf));
        }

        [Fact]
        public void PlaneSideFiltered_SignHoldsForRoundedCoefficientsAndPoints()
        {
            var r = new Random(13);
            int decided = 0, cases = 0;
            foreach (int bits in new[] { 10, 53, 54, 80, 200 })
                foreach (int k in new[] { -40, 0, 20, 60 })
                    for (int iter = 0; iter < 20; ++iter) {
                        BigInteger A = new BigInteger(Rnd(r, 50)) << Math.Max(0, bits - 50), B = new BigInteger(Rnd(r, 50)) << r.Next(0, Math.Max(1, bits - 50)),
                            C = new BigInteger(Rnd(r, 30)) + 1;
                        double x = Rnd(r, k), y = Rnd(r, k), z = Rnd(r, k);
                        // D so that the point is nearly on the plane: A x + B y + C z rounded down to an integer;
                        // then moved by growing powers of two until the filter decides (near its bound)
                        BigInteger D0 = (A * Q(x) + B * Q(y) + C * Q(z)) >> S;
                        int found = 0;
                        for (int j = -1; j < 400 && found < 2; ++j) {
                            BigInteger D = (j < 0) ? D0 : D0 + ((iter % 2 == 0 ? BigInteger.One : BigInteger.MinusOne) << j);
                            double[] pa = { (double)A, (double)B, (double)C, (double)D };
                            int f = ExactMeshBoolean.plane_side_filtered(pa, x, y, z);
                            cases++;
                            if (f == 2)
                                continue;
                            decided++;
                            found++;
                            // every exact point in the error box of (x, y, z) is on the side f of every plane whose
                            // coefficients are within 2^-52 of pa (here A, B and C are exact doubles, D is rounded;
                            // the boxes are taken around all four, as the contract allows)
                            BigInteger[][] cb = { Box(x), Box(y), Box(z) }, pb = { Box(pa[0]), Box(pa[1]), Box(pa[2]), Box(pa[3]) };
                            for (int mask = 0; mask < 128; ++mask) {
                                BigInteger v = -Corner(pb[3], mask, 6) * (BigInteger.One << S);
                                for (int i = 0; i < 3; ++i)
                                    v += Corner(pb[i], mask, i + 3) * Corner(cb[i], mask, i);
                                if (v.Sign != f)
                                    Assert.Fail($"plane side bits={bits} k={k} iter={iter} j={j} mask={mask}: filter {f}, exact {v.Sign}");
                            }
                        }
                    }
            Assert.True(decided > 300, $"decided {decided} of {cases}");
            // well off the plane: decides; tiny coordinates and overflow: does not
            Assert.Equal(1, ExactMeshBoolean.plane_side_filtered(new double[] { 1, 2, 3, 4 }, 1, 1, 1));
            Assert.Equal(-1, ExactMeshBoolean.plane_side_filtered(new double[] { 1, 2, 3, 7 }, 1, 1, 1));
            Assert.Equal(2, ExactMeshBoolean.plane_side_filtered(new double[] { 1, 2, 3, 6 }, 1, 1, 1));
            Assert.Equal(2, ExactMeshBoolean.plane_side_filtered(new double[] { 1, 0, 0, 0 }, 1e-200, 1, 1));
            Assert.Equal(2, ExactMeshBoolean.plane_side_filtered(new double[] { 1e300, 1e300, 0, 0 }, 1e300, 1e300, 1));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;
using Ops = g3.ExactMeshBoolean.Operations;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Hard cases for mesh booleans from the issue trackers of other libraries (docs/QA.md 2.11): only the failure
    /// mode, rebuilt here from simple primitives. No code, test code or meshes of these projects are used (CGAL and the
    /// copyleft parts of libigl are GPL: only the prose of their issues was read). The issue URL is in the comment of
    /// each test.
    /// </summary>
    public class ExactBooleanIssueCasesTests
    {
        static DMesh3 Box(double x0, double y0, double z0, double x1, double y1, double z1)
        {
            var box = new Box3d(new Vector3d((x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2), new Vector3d((x1 - x0) / 2, (y1 - y0) / 2, (z1 - z0) / 2));
            DMesh3 mesh = new TrivialBox3Generator() { Box = box }.Generate().MakeDMesh();
            foreach (int vid in mesh.VertexIndices().ToArray()) {
                Vector3d v = mesh.GetVertex(vid);
                mesh.SetVertex(vid, new Vector3d(v.x < box.Center.x ? x0 : x1, v.y < box.Center.y ? y0 : y1, v.z < box.Center.z ? z0 : z1));
            }
            return mesh;
        }

        // a closed prism between two rings of points (each convex and planar, the same count, bottom counter-clockwise
        // seen from the top), caps as fans
        static DMesh3 Prism(IList<Vector3d> bottom, IList<Vector3d> top)
        {
            var m = new DMesh3();
            int n = bottom.Count;
            int[] b = bottom.Select(p => m.AppendVertex(p)).ToArray(), t = top.Select(p => m.AppendVertex(p)).ToArray();
            for (int i = 0; i < n; ++i) {
                int j = (i + 1) % n;
                m.AppendTriangle(b[i], b[j], t[j]);
                m.AppendTriangle(b[i], t[j], t[i]);
            }
            for (int i = 1; i + 1 < n; ++i) {
                m.AppendTriangle(b[0], b[i + 1], b[i]);
                m.AppendTriangle(t[0], t[i], t[i + 1]);
            }
            if (ResultChecks.Volume(m) < 0)
                m.ReverseOrientation();
            return m;
        }

        static DMesh3 Tetra(Vector3d a, Vector3d b, Vector3d c, Vector3d d)
        {
            var m = new DMesh3();
            foreach (Vector3d v in new[] { a, b, c, d }) m.AppendVertex(v);
            m.AppendTriangle(0, 2, 1); m.AppendTriangle(0, 1, 3); m.AppendTriangle(1, 2, 3); m.AppendTriangle(0, 3, 2);
            if (ResultChecks.Volume(m) < 0)
                m.ReverseOrientation();
            return m;
        }

        static DMesh3 Sphere(Vector3d c, double r, int n = 8)
        {
            DMesh3 m = new Sphere3Generator_NormalizedCube() { Radius = r, EdgeVertices = n }.Generate().MakeDMesh();
            MeshTransforms.Translate(m, c);
            return m;
        }

        static ExactMeshBoolean Run(DMesh3 a, DMesh3 b, Ops op, bool safe = true)
        {
            var boolean = new ExactMeshBoolean(a, b, op) { SafeRounding = safe };
            Assert.True(boolean.Compute(), boolean.Error);
            return boolean;
        }

        static void AssertCleanResult(ExactMeshBoolean b, double volume, double tol, string what)
        {
            ResultChecks.AssertClean(b.Result, what);
            Assert.True(b.RoundingClean, what + ": rounding not clean");
            Assert.True(Math.Abs(ResultChecks.Volume(b.Result) - volume) <= tol * Math.Max(1, Math.Abs(volume)),
                $"{what}: volume {ResultChecks.Volume(b.Result)}, expected {volume}");
        }

        static int Components(DMesh3 m)
        {
            var c = new MeshConnectedComponents(m);
            c.FindConnectedT();
            return c.Count;
        }

        [Fact]
        public void TetrahedraSharingAFace_RandomOrientations()
        {
            // https://github.com/elalish/manifold/issues/1656: two tetrahedra on the same base triangle, apexes on both
            // sides (one exactly coincident face, opposite orientations); in a few percent of random orientations the
            // union kept both copies of the shared face (two touching shells instead of one)
            var rand = new Random(1656);
            for (int it = 0; it < 60; ++it) {
                var rot = new Quaterniond(new Vector3d(rand.NextDouble() - 0.5, rand.NextDouble() - 0.5, rand.NextDouble() - 0.5).Normalized, 360 * rand.NextDouble());
                Vector3d a = rot * new Vector3d(1, 0, 0), b = rot * new Vector3d(-0.5, 0.8, 0), c = rot * new Vector3d(-0.4, -0.9, 0.1);
                Vector3d n = (b - a).Cross(c - a).Normalized;
                Vector3d g = (a + b + c) / 3;
                DMesh3 t1 = Tetra(a, b, c, g + 0.7 * n), t2 = Tetra(a, b, c, g - 0.9 * n);
                var u = Run(t1, t2, Ops.Union);
                string what = "case " + it;
                AssertCleanResult(u, ResultChecks.Volume(t1) + ResultChecks.Volume(t2), 1e-12, what);
                Assert.Equal(6, u.Result.TriangleCount);
                Assert.Equal(5, u.Result.VertexCount);
                var i = Run(t1, t2, Ops.Intersection);
                Assert.Equal(0, i.Result.TriangleCount);
            }
        }

        static (DMesh3, DMesh3) TrianglePrisms(Func<Vector3d, Vector3d> R)
        {
            DMesh3 p1 = Prism(new[] { new Vector3d(0, 0, 0), new Vector3d(10, 0, 0), new Vector3d(0, 10, 0) }.Select(R).ToList(),
                new[] { new Vector3d(0, 0, 3), new Vector3d(10, 0, 3), new Vector3d(0, 10, 3) }.Select(R).ToList());
            DMesh3 p2 = Prism(new[] { new Vector3d(10, 0, 0), new Vector3d(10, 10, 0), new Vector3d(0, 10, 0) }.Select(R).ToList(),
                new[] { new Vector3d(10, 0, 3), new Vector3d(10, 10, 3), new Vector3d(0, 10, 3) }.Select(R).ToList());
            return (p1, p2);
        }

        [Fact]
        public void TwoTriangularPrisms_FormABox_RotatedAboutX()
        {
            // https://github.com/elalish/manifold/issues/1430 (case c): two right triangles that form a 10 x 10 square,
            // extruded and rotated by 90 degrees about x, united: only part of the shared hypotenuse face merged and
            // a sliver was left. The two prisms triangulate the shared face with different diagonals. Rotated exactly
            // (90 degrees as a permutation of the coordinates, as Manifold does) the face stays planar
            var cases = new List<(string, Func<Vector3d, Vector3d>)> {
                ("unrotated", p => p),
                ("90 degrees about x, exact", p => new Vector3d(p.x, -p.z, p.y)),
                ("180 degrees about x, exact", p => new Vector3d(p.x, -p.y, -p.z)),
            };
            foreach (var (what, R) in cases) {
                var (p1, p2) = TrianglePrisms(R);
                var u = Run(p1, p2, Ops.Union);
                AssertCleanResult(u, 300, 1e-12, what);
                Assert.Equal(1, Components(u.Result));
                // the shared face is gone completely: every vertex is a corner of the box
                Assert.Equal(8, u.Result.VertexCount);
            }
        }

        [Fact]
        public void KnownLimitation_TwoTriangularPrisms_RotatedInexactly_KeepATinyVoid()
        {
            // Known limitation (pinned: a fix turns this test red, then it moves to the clean cases above), the same case
            // rotated by 90 degrees with a quaternion: the rotated corners are rounded to double (a coordinate of 6.7e-16
            // instead of 0), so the shared face is no longer planar and its two triangulations differ by a tetrahedron of
            // about 3e-15 volume between them, outside both prisms.
            // ExactMeshBoolean computes this input exactly: the union is the box with that tetrahedral void, which
            // touches the outer surface along two edges (a contact at duplicated vertices, as where solids touch,
            // see ExactBooleanByDesignTests). The volume is right; SafeRounding finds nothing to repair (contacts at
            // duplicated vertices are not intersections) and keeps the void, because it removes thin closed components
            // only where the rounding left a defect. Welded by position, the result is non-manifold at the edges.
            // A fix would remove such thin closed components that touch the rest only at duplicated vertices.
            // Pin the rounded input, not runtime-dependent Sin/Cos results: net48 and net10
            // produce different coordinates for the same quaternion and therefore different exact solids.
            var (p1, p2) = TrianglePrisms(p => new Vector3d(p.x,
                p.z == 0 ? (p.y == 0 ? 0 : 2.2204460492503131e-15)
                    : (p.y == 0 ? -3.0 : -2.9999999999999978),
                p.y == 0 ? (p.z == 0 ? 0 : 6.6613381477509392e-16) : 10.0));
            var u = Run(p1, p2, Ops.Union);
            ResultChecks.AssertClosed(u.Result);
            Assert.True(u.RoundingClean);
            Assert.Equal(300, ResultChecks.Volume(u.Result), 9);
            Assert.Equal(2, Components(u.Result));
            Assert.Equal(16, u.Result.TriangleCount);
            Assert.True(u.NonManifoldEdges > 0);
        }

        [Fact]
        public void TwoTriangularPrisms_RoundedRotationWithoutVoid_FormOneClosedSolid()
        {
            // The other observed runtime rounding lies on the opposite side of the shared face.
            var (p1, p2) = TrianglePrisms(p => new Vector3d(p.x,
                p.z == 0 ? (p.y == 0 ? 0 : -2.220446049250313e-15)
                    : (p.y == 0 ? -3.000000000000001 : -3.000000000000003),
                p.y == 0 ? (p.z == 0 ? 0 : -6.661338147750939e-16) : 10.000000000000002));
            var u = Run(p1, p2, Ops.Union);
            AssertCleanResult(u, 300, 1e-12, "pinned rounded rotation without a void");
            Assert.Equal(1, Components(u.Result));
        }

        [Fact]
        public void BoxMinusBarsFlushWithItsFaces_NoShards()
        {
            // https://github.com/elalish/manifold/issues/1430 (case a): a block minus two bars placed exactly flush
            // with its top and bottom faces; the bottom one left a shard
            DMesh3 block = Prism(Enumerable.Range(0, 8).Select(k => new Vector3d(4 * Math.Cos(k * Math.PI / 4), 4 * Math.Sin(k * Math.PI / 4), 0)).ToList(),
                Enumerable.Range(0, 8).Select(k => new Vector3d(4 * Math.Cos(k * Math.PI / 4), 4 * Math.Sin(k * Math.PI / 4), 5)).ToList());
            double v0 = ResultChecks.Volume(block);
            var d1 = Run(block, Box(-0.5, -1.5, 4, 0.5, 1.5, 5), Ops.Difference);
            var d2 = Run(d1.Result, Box(-0.5, -1.5, 0, 0.5, 1.5, 1), Ops.Difference);
            AssertCleanResult(d2, v0 - 6, 1e-12, "two flush bars");
            Assert.Equal(1, Components(d2.Result));
            // the same with the bars rotated 90 degrees about y (the shard moved with the rotation)
            var rot = Quaterniond.AxisAngleD(Vector3d.AxisY, 90);
            DMesh3 rb = new DMesh3(block);
            MeshTransforms.Rotate(rb, Vector3d.Zero, rot);
            DMesh3 bar1 = Box(-0.5, -1.5, 4, 0.5, 1.5, 5), bar2 = Box(-0.5, -1.5, 0, 0.5, 1.5, 1);
            MeshTransforms.Rotate(bar1, Vector3d.Zero, rot);
            MeshTransforms.Rotate(bar2, Vector3d.Zero, rot);
            var r2 = Run(Run(rb, bar1, Ops.Difference).Result, bar2, Ops.Difference);
            Assert.True(r2.RoundingClean);
            ResultChecks.AssertClean(r2.Result, "rotated");
            Assert.Equal(1, Components(r2.Result));
            Assert.Equal(v0 - 6, ResultChecks.Volume(r2.Result), 6);
        }

        [Fact]
        public void PrismAndSkewedPrismSharingAnEndFace()
        {
            // https://github.com/elalish/manifold/issues/1496: an octagonal prism along x, and a second, skewed prism
            // starting at the first one's end octagon; the union had duplicated vertices, interior triangles and
            // self-intersections
            Func<double, double, double, double, List<Vector3d>> ring = (x, dy, dz, turn) => Enumerable.Range(0, 8)
                .Select(k => new Vector3d(x, dy + 2 * Math.Cos(k * Math.PI / 4 + turn), dz + 2 * Math.Sin(k * Math.PI / 4 + turn))).ToList();
            DMesh3 p1 = Prism(ring(0, 0, 0, 0), ring(10, 0, 0, 0));
            DMesh3 p2 = Prism(ring(10, 0, 0, 0), ring(20, 1.3, -0.4, 0.3));
            var u = Run(p1, p2, Ops.Union);
            AssertCleanResult(u, ResultChecks.Volume(p1) + ResultChecks.Volume(p2), 1e-12, "union");
            Assert.Equal(24, u.Result.VertexCount);
            Assert.Equal(1, Components(u.Result));
        }

        [Fact]
        public void SphereMinusItsIntersectionWithAShiftedCopy()
        {
            // https://github.com/elalish/manifold/issues/1706: sphere intersected with the same sphere shifted along x,
            // then the original sphere minus that result (faces that coincide with the input): hundreds of slivers
            // below 1e-9 area
            DMesh3 s = Sphere(Vector3d.Zero, 1, 12), t = Sphere(new Vector3d(0.6, 0, 0), 1, 12);
            var lens = Run(s, t, Ops.Intersection);
            AssertCleanResult(lens, ResultChecks.Volume(Run(s, t, Ops.Intersection, false).Result), 1e-9, "lens");
            var d = Run(s, lens.Result, Ops.Difference);
            ResultChecks.AssertClean(d.Result, "difference");
            Assert.True(d.RoundingClean);
            Assert.Equal(ResultChecks.Volume(s) - ResultChecks.Volume(lens.Result), ResultChecks.Volume(d.Result), 9);
            // and the difference computed directly is the same solid
            var direct = Run(s, t, Ops.Difference);
            Assert.Equal(ResultChecks.Volume(direct.Result), ResultChecks.Volume(d.Result), 9);
        }

        [Fact]
        public void HugeCoordinates_BatchUnion_IndependentOfOrder()
        {
            // https://github.com/elalish/manifold/issues/1883: ten convex integer-coordinate pieces at coordinates up to
            // 3.6e8, united in one batch: volume 0.056 % low and stray vertices; reversing the order or uniting one at
            // a time was correct
            var rand = new Random(1883);
            var pieces = new List<DMesh3>();
            for (int k = 0; k < 10; ++k) {
                double x = 3.6e8 + rand.Next(0, 600), y = -1.2e8 + rand.Next(0, 600), z = 2e8 + rand.Next(0, 200);
                // a chamfered box: an octagonal prism with integer corners
                double w = 200 + rand.Next(0, 200), c = 40;
                var oct = new List<Vector3d> {
                    new Vector3d(x + c, y, 0), new Vector3d(x + w - c, y, 0), new Vector3d(x + w, y + c, 0), new Vector3d(x + w, y + w - c, 0),
                    new Vector3d(x + w - c, y + w, 0), new Vector3d(x + c, y + w, 0), new Vector3d(x, y + w - c, 0), new Vector3d(x, y + c, 0) };
                pieces.Add(Prism(oct.Select(p => new Vector3d(p.x, p.y, z)).ToList(), oct.Select(p => new Vector3d(p.x, p.y, z + 150 + k)).ToList()));
            }
            var batch = new ExactMeshBoolean(pieces, Ops.Union) { SafeRounding = true };
            Assert.True(batch.Compute(), batch.Error);
            var reversed = new ExactMeshBoolean(Enumerable.Reverse(pieces).ToList(), Ops.Union) { SafeRounding = true };
            Assert.True(reversed.Compute(), reversed.Error);
            DMesh3 seq = pieces[0];
            for (int k = 1; k < pieces.Count; ++k)
                seq = Run(seq, pieces[k], Ops.Union).Result;
            ResultChecks.AssertClean(batch.Result, "batch");
            ResultChecks.AssertClean(reversed.Result, "reversed");
            ResultChecks.AssertClean(seq, "sequential");
            // volumes relative to a point of the pieces (far from the origin the plain sum cancels)
            Vector3d o = pieces[0].GetVertex(0);
            Func<DMesh3, double> vol = m => m.TriangleIndices().Sum(t => {
                Index3i tv = m.GetTriangle(t);
                return (m.GetVertex(tv.a) - o).Dot((m.GetVertex(tv.b) - o).Cross(m.GetVertex(tv.c) - o)) / 6;
            });
            double vb = vol(batch.Result);
            Assert.Equal(vb, vol(reversed.Result), 6);
            Assert.Equal(vb, vol(seq), 6);
            Assert.True(batch.IntersectingPairs > 0);
            // every result vertex lies on the boundary of a piece (each a convex prism: the largest signed distance to
            // its face planes is 0), relative to o so that the coordinates are small: no stray vertices
            Func<Vector3d, bool> onSomePiece = v => pieces.Any(p => {
                double worst = double.MinValue;
                foreach (int t in p.TriangleIndices()) {
                    Index3i tv = p.GetTriangle(t);
                    Vector3d a = p.GetVertex(tv.a) - o, n = (p.GetVertex(tv.b) - p.GetVertex(tv.a)).Cross(p.GetVertex(tv.c) - p.GetVertex(tv.a)).Normalized;
                    worst = Math.Max(worst, n.Dot(v - o - a));
                }
                return Math.Abs(worst) < 1e-6;
            });
            foreach (DMesh3 m in new[] { batch.Result, reversed.Result, seq })
                foreach (Vector3d v in m.Vertices())
                    Assert.True(onSomePiece(v), "stray vertex " + v);
        }

        [Fact]
        public void SameBoxTriangulatedTwoWays_UnionMinusABox()
        {
            // https://github.com/elalish/manifold/issues/1857: (a + b) - c where a and b are the same box with different
            // diagonals on its faces and c shares half of its vertices with them: slivers made an edge-swap loop (stack
            // overflow, then an endless loop)
            DMesh3 a = Box(0, 0, 0, 2, 2, 2);
            DMesh3 b = new DMesh3(a);
            // flip every diagonal of b
            foreach (int e in b.EdgeIndices().ToArray()) {
                Index2i ev = b.GetEdgeV(e);
                Vector3d d = b.GetVertex(ev.a) - b.GetVertex(ev.b);
                int nonzero = (d.x != 0 ? 1 : 0) + (d.y != 0 ? 1 : 0) + (d.z != 0 ? 1 : 0);
                if (nonzero == 2 && b.IsEdge(e))
                    Assert.Equal(MeshResult.Ok, b.FlipEdge(e, out DMesh3.EdgeFlipInfo _));
            }
            var ab = Run(a, b, Ops.Union);
            AssertCleanResult(ab, 8, 1e-12, "a + b");
            var abc = Run(ab.Result, Box(1, 0, 0, 2, 2, 2), Ops.Difference);
            AssertCleanResult(abc, 4, 1e-12, "(a + b) - c");
            Assert.Equal(8, abc.Result.VertexCount);
        }

        [Fact]
        public void RotateAndUnionSpiral_ManyLevels()
        {
            // https://github.com/elalish/manifold/issues/634: a spiral, each level the union of a unit cube at radius
            // r with the deeper result rotated about z; the precision estimate grew about 7 % per rotation, and beyond
            // 117 levels all triangles vanished. Exact arithmetic has no tolerance to grow. Here consecutive cubes
            // overlap (1.5 degrees at radius 25 to 33 is 0.65 to 0.86 apart): 130 levels stay clean and give the same solid as one
            // n-ary union of the cubes at their final places
            DMesh3 result = new DMesh3();
            var cubes = new List<DMesh3>();
            int levels = 130;
            double r = 25;
            for (int k = 0; k < levels; ++k) {
                var turn = Quaterniond.AxisAngleD(Vector3d.AxisZ, 1.5);
                MeshTransforms.Rotate(result, Vector3d.Zero, turn);
                foreach (DMesh3 c in cubes)
                    MeshTransforms.Rotate(c, Vector3d.Zero, turn);
                r *= 1.002;
                DMesh3 cube = Box(r, -0.5, -0.5 + 0.01 * k, r + 1, 0.5, 0.5 + 0.01 * k);
                cubes.Add(new DMesh3(cube));
                var u = Run(result, cube, Ops.Union);
                if (k > 0)
                    Assert.True(u.IntersectingPairs > 0, "level " + k + ": no overlap");
                result = u.Result;
            }
            ResultChecks.AssertClean(result, "spiral");
            Assert.Equal(1, Components(result));
            var onePass = new ExactMeshBoolean(cubes, Ops.Union) { SafeRounding = true };
            Assert.True(onePass.Compute(), onePass.Error);
            ResultChecks.AssertClean(onePass.Result, "one pass");
            double v = ResultChecks.Volume(result);
            Assert.True(v > 0.5 * levels && v < levels, "volume " + v);
            Assert.Equal(ResultChecks.Volume(onePass.Result), v, 6);
        }

        [Fact]
        public void TetrahedraRotatedByTinyAngles_Union()
        {
            // https://github.com/elalish/manifold/issues/970 (cases a, b): three tetrahedra, two rotated by tiny angles,
            // united (the triangulator refused a valid nearly degenerate polygon, nondeterministically), and a cube
            // rotated by tiny angles with other cubes (self-intersections)
            DMesh3 t0 = Tetra(new Vector3d(0, 0, 0), new Vector3d(2, 0, 0), new Vector3d(0, 2, 0), new Vector3d(0, 0, 2));
            DMesh3 t1 = new DMesh3(t0), t2 = new DMesh3(t0);
            MeshTransforms.Rotate(t1, new Vector3d(0.3, 0.3, 0.3), Quaterniond.AxisAngleD(new Vector3d(1, 2, 3).Normalized, 1e-7));
            MeshTransforms.Rotate(t2, new Vector3d(0.3, 0.3, 0.3), Quaterniond.AxisAngleD(new Vector3d(-2, 1, 1).Normalized, 3e-9));
            string first = null;
            for (int run = 0; run < 3; ++run) {
                var u = new ExactMeshBoolean(new[] { t0, t1, t2 }, Ops.Union) { SafeRounding = true };
                Assert.True(u.Compute(), u.Error);
                ResultChecks.AssertClean(u.Result, "tetrahedra");
                Assert.Equal(ResultChecks.Volume(t0), ResultChecks.Volume(u.Result), 6);
                string print = string.Join(";", u.Result.Vertices().Select(v => v.ToString("R")));
                first = first ?? print;
                Assert.Equal(first, print);
            }
            DMesh3 c0 = Box(0, 0, 0, 1, 1, 1), c1 = Box(0, 0, 0, 1, 1, 1), c2 = Box(0.5, 0.5, 0.5, 1.5, 1.5, 1.5);
            MeshTransforms.Rotate(c1, new Vector3d(0.5, 0.5, 0.5), Quaterniond.AxisAngleD(new Vector3d(1, 1, 0).Normalized, 1e-8));
            var cu = Run(Run(c0, c1, Ops.Union).Result, c2, Ops.Union);
            ResultChecks.AssertClean(cu.Result, "cubes");
            Assert.True(cu.RoundingClean);
            var cd = Run(Run(c0, c1, Ops.Union).Result, c2, Ops.Difference);
            ResultChecks.AssertClean(cd.Result, "cubes, difference");
            Assert.Equal(1 - 0.125, ResultChecks.Volume(cd.Result), 6);
        }

        [Fact]
        public void MirroredCubes_Difference()
        {
            // https://github.com/elalish/manifold/issues/294: a cube scaled by (1, -1, 1) minus a mirrored small cube;
            // the winding was not flipped with the mirror. Here the mirror is MeshTransforms.Scale with bFixOrientation
            // (which reverses the triangles); without it the mirrored mesh is inside out (winding number -1, an empty
            // solid)
            DMesh3 big = Box(0, 0, 0, 1, 1, 1), small = Box(0.45, 0.45, 0.45, 0.55, 0.55, 1.5);
            MeshTransforms.Scale(big, new Vector3d(1, -1, 1), Vector3d.Zero, true);
            MeshTransforms.Scale(small, new Vector3d(1, -1, 1), Vector3d.Zero, true);
            var d = Run(big, small, Ops.Difference);
            AssertCleanResult(d, 1 - 0.01 * 0.55, 1e-12, "mirrored, fixed orientation");
            // without the orientation fix both are inside out: their solids are empty, so is the difference
            DMesh3 big2 = Box(0, 0, 0, 1, 1, 1), small2 = Box(0.45, 0.45, 0.45, 0.55, 0.55, 1.5);
            MeshTransforms.Scale(big2, new Vector3d(1, -1, 1), Vector3d.Zero, false);
            MeshTransforms.Scale(small2, new Vector3d(1, -1, 1), Vector3d.Zero, false);
            Assert.True(ResultChecks.Volume(big2) < 0);
            var d2 = Run(big2, small2, Ops.Difference);
            Assert.Equal(0, d2.Result.TriangleCount);
        }

        [Fact]
        public void CubeMinusCenteredCube_ShellWithACavity()
        {
            // https://github.com/elalish/manifold/issues/745: a 3-cube minus a centred 1-cube is a shell with a cavity;
            // the cavity is a component of its own with negative volume
            var d = Run(Box(0, 0, 0, 3, 3, 3), Box(1, 1, 1, 2, 2, 2), Ops.Difference);
            AssertCleanResult(d, 26, 1e-12, "shell");
            Assert.Equal(2, Components(d.Result));
            // the inner component is the cavity: inside-out on its own
            var comps = new MeshConnectedComponents(d.Result);
            comps.FindConnectedT();
            var vols = comps.Components.Select(c => c.Indices.Sum(t => {
                Index3i tv = d.Result.GetTriangle(t);
                return d.Result.GetVertex(tv.a).Dot(d.Result.GetVertex(tv.b).Cross(d.Result.GetVertex(tv.c))) / 6;
            })).OrderBy(v => v).ToArray();
            Assert.Equal(-1, vols[0], 12);
            Assert.Equal(27, vols[1], 12);
            // and the shell united with the centred cube is the full cube again
            AssertCleanResult(Run(d.Result, Box(1, 1, 1, 2, 2, 2), Ops.Union), 27, 1e-12, "filled");
        }

        [Fact]
        public void CylinderToolSteppedDown_RepeatedDifference()
        {
            // https://github.com/CGAL/cgal/issues/6481 (prose only): a cylinder tool moved down one unit per step and
            // subtracted from the workpiece again and again; the third step failed on collinear points and the cost
            // grew with each step, which re-cut all earlier layers. https://github.com/CGAL/cgal/issues/2875 and
            // https://github.com/libigl/libigl/issues/1116: results rounded to double between iterated booleans
            // self-intersect. Here every step is rounded (SafeRounding) and used as the input of the next one.
            // From step 2 on, the old repair left one degenerate triangle per step: the flips that would remove it fold
            // two nearly coincident triangles across a sharp edge of the tool and move the surface by 0.1 to 1, beyond the
            // displacement bound (docs/ROBUSTNESS_SWEEP.md R22). The strip zip removes them within the bound in steps 3
            // to 5. Step 2 kept one (a cap on the tool's vertical seam next to a sliver with an edge of 2e-9) until the
            // moves stopped depending on the scale: the cap's apex offset was below MathUtil.Epsilon, so Normalized gave
            // no direction to move it along. Every step is clean now, within the bound.
            DMesh3 work = Box(-3, -3, -10, 3, 3, 0);
            DMesh3 tool = new CappedCylinderGenerator() { BaseRadius = 1.3f, TopRadius = 1.3f, Height = 2.5f, Slices = 24 }.Generate().MakeDMesh();
            // (the generator's axis is y, from 0 to the height): along z, from -1.5 to 1
            MeshTransforms.Rotate(tool, Vector3d.Zero, Quaterniond.AxisAngleD(Vector3d.AxisX, 90));
            MeshTransforms.Translate(tool, new Vector3d(0.17, -0.11, -1.5));
            var counts = new List<int>();
            for (int step = 0; step < 6; ++step) {
                var d = Run(work, tool, Ops.Difference);
                MeshRoundingRepair r = d.Rounding;
                ResultChecks.AssertClean(d.Result, "step " + step);
                Assert.True(d.RoundingClean, "step " + step);
                // the shape within the bound: the drift, and volume and area against the result as the arrangement
                // gives it (SameSolid with the drift as the displacement)
                double diag = gs.MeshRepairMetrics.TriangleBounds(d.Result).DiagonalLength;
                Assert.True(r.MaxDrift <= r.MaxDisplacement * diag, $"step {step}: drift {r.MaxDrift:G3}");
                var raw = Run(work, tool, Ops.Difference, safe: false);
                Assert.True(BooleanOracle.SameSolid(d.Result, raw.Result, 10, r.MaxDrift) == "", "step " + step);
                work = d.Result;
                counts.Add(work.TriangleCount);
                MeshTransforms.Translate(tool, new Vector3d(0, 0, -1));
            }
            // the walls of the hole are re-cut at each step, but its triangles do not multiply: the count grows by a
            // bounded amount per step
            for (int k = 2; k < counts.Count; ++k)
                Assert.True(counts[k] - counts[k - 1] <= 2 * (counts[1] - counts[0]) + 200, string.Join(", ", counts));
            Assert.Equal(1, Components(work));
            // the tool positions cover z from -6.5 to 1, so the hole is 6.5 deep (the tool is a prism: volume / height
            // is its cross-section)
            DMesh3 tool0 = new CappedCylinderGenerator() { BaseRadius = 1.3f, TopRadius = 1.3f, Height = 2.5f, Slices = 24 }.Generate().MakeDMesh();
            // (within the vertex moves of the safe rounding)
            Assert.Equal(360 - ResultChecks.Volume(tool0) / 2.5 * 6.5, ResultChecks.Volume(work), 6);
        }

        [Fact]
        public void InsideOutOperand_HasAnEmptySolid()
        {
            // https://github.com/CGAL/cgal/issues/9467 and https://github.com/libigl/libigl/issues/1998 (prose only):
            // inside-out inputs (unbounded volume, negative winding). ExactMeshBoolean treats a consistently inside-out
            // mesh as winding number -1: its solid is empty (documented at the class)
            DMesh3 a = Box(0, 0, 0, 2, 2, 2), b = Box(1, 1, 1, 3, 3, 3);
            b.ReverseOrientation();
            AssertCleanResult(Run(a, b, Ops.Union), 8, 1e-12, "union");
            Assert.Equal(0, Run(a, b, Ops.Intersection).Result.TriangleCount);
            AssertCleanResult(Run(a, b, Ops.Difference), 8, 1e-12, "difference");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Xunit;
using Ops = g3.ExactMeshBoolean.Operations;
using Rep = geometry3Sharp.Tests.BooleanOracle.Representation;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Metamorphic and oracle tests of ExactMeshBoolean on a fixed corpus of procedural solids (docs/QA.md 4a items
    /// 9 and 10, docs/design/BOOLEAN_PROPERTY_TESTS.md): an analytic reference for boxes, inclusion-exclusion,
    /// (A-B) u (A n B) = A, commutativity, and invariance under triangle order, vertex ids, corner rotation and
    /// conforming subdivision. They run on net48 too; ExactBooleanPropertyTests.CsCheck.cs samples the same
    /// properties with shrinking (net10.0).
    /// </summary>
    public class ExactBooleanMetamorphicTests
    {
        static IntBox Bx(int x0, int y0, int z0, int x1, int y1, int z1) => new IntBox(x0, y0, z0, x1, y1, z1);

        /// <summary> one deterministic case per family, in the integer frame </summary>
        public static readonly Dictionary<string, (IntBox a, IntBox b)> Families = new Dictionary<string, (IntBox, IntBox)> {
            ["overlapping"] = (Bx(0, 0, 0, 2, 2, 2), Bx(1, 1, 1, 3, 3, 3)),
            ["coplanar overlap"] = (Bx(0, 0, 0, 2, 2, 2), Bx(1, 1, 0, 3, 3, 2)),
            ["cross"] = (Bx(0, 1, 1, 4, 2, 2), Bx(1, 0, 1, 2, 4, 2)),
            ["face touching, partial"] = (Bx(0, 0, 0, 2, 2, 2), Bx(2, 0, 0, 4, 1, 1)),
            ["face touching, equal faces"] = (Bx(0, 0, 0, 1, 1, 1), Bx(1, 0, 0, 2, 1, 1)),
            ["edge touching"] = (Bx(0, 0, 0, 2, 2, 2), Bx(2, 2, 0, 3, 3, 2)),
            ["vertex touching"] = (Bx(0, 0, 0, 2, 2, 2), Bx(2, 2, 2, 3, 3, 3)),
            ["nested"] = (Bx(0, 0, 0, 3, 3, 3), Bx(1, 1, 1, 2, 2, 2)),
            ["nested, on the wall"] = (Bx(0, 0, 0, 3, 3, 3), Bx(0, 1, 1, 1, 2, 2)),
            ["nested, in a corner"] = (Bx(0, 0, 0, 3, 3, 3), Bx(0, 0, 0, 1, 1, 1)),
            ["identical"] = (Bx(0, 0, 0, 2, 1, 3), Bx(0, 0, 0, 2, 1, 3)),
            ["disjoint"] = (Bx(0, 0, 0, 1, 1, 1), Bx(3, 0, 0, 4, 1, 1)),
        };

        public static IEnumerable<object[]> FamilyNames() => Families.Keys.Select(k => new object[] { k });

        // the identity, a small and a large power-of-two scale, and a translation on a 1/16 grid (all exact)
        static IEnumerable<BoxCase> Frames(string family)
        {
            var (a, b) = Families[family];
            yield return new BoxCase(a, b);
            yield return new BoxCase(a, b, -6, new Vector3d(1024.5, -3.25, 0.0625));
            yield return new BoxCase(a, b, 7, new Vector3d(-2048, 96, 4095.9375));
        }

        static DMesh3 Run(DMesh3 a, DMesh3 b, Ops op, bool safeRounding = true) => Run(a, b, op, out _, safeRounding);

        static DMesh3 Run(DMesh3 a, DMesh3 b, Ops op, out double maxDrift, bool safeRounding = true)
        {
            DMesh3 r = BooleanOracle.Run(a, b, op, out string error, out maxDrift, safeRounding);
            Assert.True(error == "", error);
            return r;
        }

        static void AssertOk(string reason, string what) => Assert.True(reason == "", what + ": " + reason);

        [Theory, MemberData(nameof(FamilyNames))]
        public void Boxes_MatchAnalyticReference(string family)
        {
            foreach (BoxCase c in Frames(family))
                foreach (Ops op in BooleanOracle.AllOps)
                    AssertOk(BooleanOracle.CheckBoxResult(Run(c.MeshA(), c.MeshB(), op), c, op), $"{family} {op} {c}");
        }

        [Theory, MemberData(nameof(FamilyNames))]
        public void Boxes_InclusionExclusion_PartitionAndCommutativity(string family)
        {
            foreach (BoxCase c in Frames(family)) {
                DMesh3 a = c.MeshA(), b = c.MeshB();
                DMesh3 union = Run(a, b, Ops.Union), inter = Run(a, b, Ops.Intersection), diff = Run(a, b, Ops.Difference);
                // vol(A u B) + vol(A n B) = vol A + vol B, exactly (dyadic coordinates, exact volumes)
                Assert.Equal(BooleanOracle.ExactSixVolume(a) + BooleanOracle.ExactSixVolume(b),
                    BooleanOracle.ExactSixVolume(union) + BooleanOracle.ExactSixVolume(inter));

                // (A - B) u (A n B) = A: computed, not only summed; it is checked against box A itself
                DMesh3 rebuilt = Run(diff, inter, Ops.Union);
                AssertOk(BooleanOracle.CheckBoxResult(rebuilt, new BoxCase(c.A, c.A, c.Exponent, c.Translation), Ops.Union), $"{family} {c}: (A-B) u (AnB)");
                AssertOk(BooleanOracle.SameSolid(rebuilt, a, c.Scale * 4), $"{family} {c}: (A-B) u (AnB) vs A");

                // commutativity of u and n
                foreach (Ops op in new[] { Ops.Union, Ops.Intersection }) {
                    DMesh3 ba = Run(b, a, op);
                    AssertOk(BooleanOracle.CheckBoxResult(ba, new BoxCase(c.B, c.A, c.Exponent, c.Translation), op), $"{family} {op} B,A");
                    AssertOk(BooleanOracle.SameSolid(op == Ops.Union ? union : inter, ba, c.Scale * 4), $"{family} {op}: A,B vs B,A");
                }
            }
        }

        [Theory, MemberData(nameof(FamilyNames))]
        public void Boxes_RepresentationInvariance(string family)
        {
            BoxCase c = Frames(family).ElementAt(1);
            double size = c.Scale * 4;
            foreach (Ops op in BooleanOracle.AllOps) {
                DMesh3 baseline = Run(c.MeshA(), c.MeshB(), op);
                foreach (Rep r in Enum.GetValues(typeof(Rep)).Cast<Rep>())
                    for (int operand = 0; operand < 3; ++operand) {   // A, B or both
                        DMesh3 a = c.MeshA(), b = c.MeshB();
                        if (operand != 1) { DMesh3 x = BooleanOracle.Change(a, r, 17); AssertOk(BooleanOracle.CheckRepresentation(a, x, size), $"{r} of A"); a = x; }
                        if (operand != 0) { DMesh3 x = BooleanOracle.Change(b, r, 29); AssertOk(BooleanOracle.CheckRepresentation(b, x, size), $"{r} of B"); b = x; }
                        DMesh3 result = Run(a, b, op, out double drift);
                        string what = $"{family} {op} {r} operand {"ABX"[operand]}";
                        if (r == Rep.Slivers) {
                            // SafeRounding: clean, and the same solid up to its documented displacement bound; the exact
                            // geometry without it (see Tetrahedra_MetamorphicRelations)
                            AssertOk(BooleanOracle.CleanReason(result), what + " SafeRounding");
                            AssertOk(BooleanOracle.WithinSafeRoundingBound(result, baseline, size, drift), what + $" SafeRounding vs baseline (MaxDrift {drift:G3})");
                            result = Run(a, b, op, safeRounding: false);
                        }
                        AssertOk(BooleanOracle.CheckBoxResult(result, c, op, r == Rep.Slivers), what);
                        AssertOk(BooleanOracle.SameSolid(result, baseline, size), what + " vs baseline");
                    }
            }
        }

        // ---------------------------------------------------------------- non-axis-aligned solids

        static Vector3i V(int x, int y, int z) => new Vector3i(x, y, z);

        public static readonly Dictionary<string, (IntTet a, IntTet b)> TetFamilies = new Dictionary<string, (IntTet, IntTet)> {
            ["overlapping"] = (new IntTet(V(0, 0, 0), V(4, 0, 0), V(0, 4, 0), V(0, 0, 4)), new IntTet(V(1, 1, 1), V(5, 1, 0), V(1, 5, 1), V(2, 2, 5))),
            ["shared vertex"] = (new IntTet(V(0, 0, 0), V(4, 0, 0), V(0, 4, 0), V(0, 0, 4)), new IntTet(V(0, 0, 0), V(3, 3, -1), V(-1, 3, 3), V(3, -1, 3))),
            ["shared edge"] = (new IntTet(V(0, 0, 0), V(4, 0, 0), V(0, 4, 0), V(0, 0, 4)), new IntTet(V(0, 0, 0), V(4, 0, 0), V(1, 3, 3), V(2, -2, 2))),
            ["coplanar faces"] = (new IntTet(V(0, 0, 0), V(4, 0, 0), V(0, 4, 0), V(0, 0, 4)), new IntTet(V(1, 1, 0), V(5, 1, 0), V(1, 5, 0), V(2, 2, 3))),
            ["sliver"] = (new IntTet(V(0, 0, 0), V(6, 0, 0), V(0, 6, 0), V(0, 0, 6)), new IntTet(V(-1, -1, 1), V(7, -1, 2), V(7, 7, 1), V(-1, 7, 2))),
            ["nested"] = (new IntTet(V(0, 0, 0), V(8, 0, 0), V(0, 8, 0), V(0, 0, 8)), new IntTet(V(1, 1, 1), V(3, 1, 1), V(1, 3, 1), V(1, 1, 3))),
        };

        public static IEnumerable<object[]> TetFamilyNames() => TetFamilies.Keys.Select(k => new object[] { k });

        [Theory, MemberData(nameof(TetFamilyNames))]
        public void Tetrahedra_MetamorphicRelations(string family)
        {
            var (ta, tb) = TetFamilies[family];
            foreach (Vector3d shift in new[] { Vector3d.Zero, new Vector3d(632117.25, 5712043.5, 113.75) })
                CheckTetRelations(ta, tb, shift, family);
        }

        internal static void CheckTetRelations(IntTet ta, IntTet tb, Vector3d shift, string what)
        {
            DMesh3 a = ta.Mesh(shift), b = tb.Mesh(shift);
            double size = 8;
            var results = new Dictionary<Ops, DMesh3>();
            foreach (Ops op in BooleanOracle.AllOps) {
                results[op] = Run(a, b, op);
                AssertOk(BooleanOracle.CleanReason(results[op]), $"{what} {op}");
            }
            // inclusion-exclusion within the rounding tolerance of the results (the inputs are exact)
            double lhs = BooleanOracle.Volume(results[Ops.Union]) + BooleanOracle.Volume(results[Ops.Intersection]);
            double rhs = (ta.SixVolume + tb.SixVolume) / 6.0;
            double tol = BooleanOracle.VolumeTolerance(results[Ops.Union], results[Ops.Intersection]) + BooleanOracle.VolumeTolerance(a, b);
            Assert.True(Math.Abs(lhs - rhs) <= tol, $"{what}: vol(AuB) + vol(AnB) = {lhs:R}, vol A + vol B = {rhs:R}, tolerance {tol:G3}");
            // difference and intersection partition A
            double split = BooleanOracle.Volume(results[Ops.Difference]) + BooleanOracle.Volume(results[Ops.Intersection]);
            Assert.True(Math.Abs(split - ta.SixVolume / 6.0) <= tol, $"{what}: vol(A-B) + vol(AnB) = {split:R}, vol A = {ta.SixVolume / 6.0:R}");

            DMesh3 rebuilt = Run(results[Ops.Difference], results[Ops.Intersection], Ops.Union);
            AssertOk(BooleanOracle.CleanReason(rebuilt), what + ": (A-B) u (AnB)");
            // (cracks of rounding thickness between the separately rounded A-B and AnB are allowed: SameRegularizedSolid)
            AssertOk(BooleanOracle.SameRegularizedSolid(rebuilt, a, size), what + ": (A-B) u (AnB) vs A");
            foreach (Ops op in new[] { Ops.Union, Ops.Intersection })
                AssertOk(BooleanOracle.SameSolid(results[op], Run(b, a, op), size), $"{what} {op}: A,B vs B,A");
            foreach (Rep r in Enum.GetValues(typeof(Rep)).Cast<Rep>()) {
                DMesh3 ra = BooleanOracle.Change(a, r, 5), rb = BooleanOracle.Change(b, r, 6);
                AssertOk(BooleanOracle.CheckRepresentation(a, ra, size), $"{r} of A");
                AssertOk(BooleanOracle.CheckRepresentation(b, rb, size), $"{r} of B");
                foreach (Ops op in BooleanOracle.AllOps) {
                    DMesh3 result = Run(ra, rb, op, out double drift);
                    AssertOk(BooleanOracle.CleanReason(result), $"{what} {op} {r}");
                    if (r == Rep.Slivers) {
                        AssertOk(BooleanOracle.WithinSafeRoundingBound(result, results[op], size, drift), $"{what} {op} {r} vs baseline, SafeRounding (MaxDrift {drift:G3})");
                        // where the other solid cuts a sliver, the pieces can fall below the degenerate threshold of
                        // SafeRounding (area 1e-12 diagonal^2; rounded or even exact), which contracts them within its
                        // displacement bound (ExactBooleanPropertyFindings): exactly, the solid is compared without
                        // that repair, as the arrangement gives it
                        DMesh3 plain = Run(ra, rb, op, safeRounding: false);
                        AssertOk(BooleanOracle.SameSolid(plain, Run(a, b, op, safeRounding: false), size), $"{what} {op} {r} vs baseline, plain rounding");
                    }
                    else
                        AssertOk(BooleanOracle.SameSolid(result, results[op], size), $"{what} {op} {r} vs baseline");
                }
            }
        }

        // ---------------------------------------------------------------- similarities, reuse, repeated runs

        [Theory, MemberData(nameof(Similarity.Names), MemberType = typeof(Similarity))]
        public void Partition_Similarities(string name)
        {
            // coplanar overlap: B's faces inside A are shared by A-B and AnB
            Similarity s = Similarity.ByName(name);
            var (ia, ib) = Families["coplanar overlap"];
            var c = new BoxCase(ia, ib);
            DMesh3 a = c.MeshA(), b = c.MeshB();
            DMesh3 d0 = Run(a, b, Ops.Difference), i0 = Run(a, b, Ops.Intersection);
            DMesh3 reference = Run(d0, i0, Ops.Union);
            AssertOk(BooleanOracle.CheckBoxResult(reference, new BoxCase(ia, ia), Ops.Union), "identity");
            DMesh3 ta = Invariance.Transformed(a, s), tb = Invariance.Transformed(b, s);
            DMesh3 d = Run(ta, tb, Ops.Difference), i = Run(ta, tb, Ops.Intersection);
            DMesh3 back = Invariance.MappedBack(Run(d, i, Ops.Union), s);
            AssertOk(BooleanOracle.CleanReason(back), name);
            if (s.IsExact) {
                // 2^k scales: the same result bit for bit
                Assert.Equal("", Invariance.GeometricDifference(reference, back));
                return;
            }
            if (!s.IsRotated && s.Scale == 1) {
                // a dyadic translation of the integer boxes (UTM) is exact too: the analytic reference in that frame
                var moved = new BoxCase(ia, ib, 0, s.Translation);
                AssertOk(BooleanOracle.CheckBoxResult(d, moved, Ops.Difference), name + ": A-B");
                AssertOk(BooleanOracle.CheckBoxResult(i, moved, Ops.Intersection), name + ": AnB");
                AssertOk(BooleanOracle.CheckBoxResult(Run(d, i, Ops.Union), new BoxCase(ia, ia, 0, s.Translation), Ops.Union), name + ": (A-B) u (AnB)");
                return;
            }
            // rotations and translations round the input coordinates: B's faces on A's planes z = 0 and z = 2 are no
            // longer exactly coplanar with them, and A-B can keep slabs of rounding thickness (rotated: area 24
            // instead of 22). A-B and AnB, rounded separately, can also leave cracks of that thickness where they
            // meet, which their union keeps. Both are true for the rounded inputs, so the regularized solids are
            // compared (volume and winding numbers away from the surface), not the boundaries.
            // (a coordinate is off by up to 3.5 rounding units of the transformed coordinates per transform: three
            // products summed in the rotation and the translation; once into the frame and once back, plus half a
            // unit for the rounding of the exact points: 7.5, at most 7.5 sqrt(3) < 16 per vertex; moving the
            // vertices by e changes the volume by at most e times the area)
            double tol = 16 * s.Resolution(3) * Invariance.Area(a);
            AssertOk(BooleanOracle.CheckBoxSolid(Invariance.MappedBack(d, s), c, Ops.Difference, tol), name + ": A-B");
            AssertOk(BooleanOracle.CheckBoxSolid(Invariance.MappedBack(i, s), c, Ops.Intersection, tol), name + ": AnB");
            AssertOk(BooleanOracle.CheckBoxSolid(back, new BoxCase(ia, ia), Ops.Union, tol), name + ": (A-B) u (AnB)");
        }

        [Fact]
        public void ReusedInstance_AndRepeatedRuns_GiveTheSameResult()
        {
            var (ia, ib) = Families["coplanar overlap"];
            var c = new BoxCase(ia, ib, -3, new Vector3d(17.5, 0, -1));
            var boolean = new ExactMeshBoolean(c.MeshA(), c.MeshB(), Ops.Union);
            var first = new Dictionary<Ops, DMesh3>();
            foreach (Ops op in BooleanOracle.AllOps) {
                boolean.Operation = op;
                Assert.True(boolean.Compute(), boolean.Error);
                first[op] = boolean.Result;
            }
            foreach (Ops op in BooleanOracle.AllOps) {
                boolean.Operation = op;
                Assert.True(boolean.Compute(), boolean.Error);
                Assert.Equal("", Invariance.Difference(first[op], boolean.Result));
                for (int run = 0; run < 3; ++run)
                    Assert.Equal("", Invariance.Difference(first[op], Run(c.MeshA(), c.MeshB(), op)));
                AssertOk(BooleanOracle.CheckBoxResult(first[op], c, op), op.ToString());
            }
        }

        // ---------------------------------------------------------------- the oracles themselves

        [Fact]
        public void BoxOracle_AcceptsHandBuiltResults_AndRejectsWrongOnes()
        {
            var c = new BoxCase(Bx(0, 0, 0, 1, 1, 1), Bx(1, 0, 0, 2, 1, 1));
            DMesh3 union = BooleanOracle.BoxMesh(Bx(0, 0, 0, 2, 1, 1), c);
            AssertOk(BooleanOracle.CheckBoxResult(union, c, Ops.Union), "hand-built union");
            AssertOk(BooleanOracle.CheckBoxResult(BooleanOracle.Subdivided(union, 2), c, Ops.Union), "subdivided union");
            AssertOk(BooleanOracle.CheckBoxResult(new DMesh3(), c, Ops.Intersection), "empty intersection");
            AssertOk(BooleanOracle.CheckBoxResult(BooleanOracle.BoxMesh(c.A, c), c, Ops.Difference), "difference");

            // the wrong operation, a non-empty result for an empty one
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(union, c, Ops.Difference));
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(union, c, Ops.Intersection));
            // the same volume and area, but another solid
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(BooleanOracle.BoxMesh(Bx(0, 0, 0, 1, 2, 1), c), c, Ops.Union));
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(BooleanOracle.BoxMesh(Bx(1, 0, 0, 3, 1, 1), c), c, Ops.Union));
            // inside out
            DMesh3 reversed = new DMesh3(union);
            reversed.ReverseOrientation(false);
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(reversed, c, Ops.Union));
            // a missing triangle
            DMesh3 open = new DMesh3(union);
            open.RemoveTriangle(open.TriangleIndices().First(), true, false);
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(open, c, Ops.Union));
            // an extra shell: a cavity (reversed inner box) keeps the area test but not the volume, a second box both
            var big = new BoxCase(Bx(0, 0, 0, 4, 4, 4), Bx(0, 0, 0, 4, 4, 4));
            DMesh3 withCavity = BooleanOracle.BoxMesh(big.A, big);
            DMesh3 cavity = BooleanOracle.BoxMesh(Bx(1, 1, 1, 2, 2, 2), big);
            cavity.ReverseOrientation(false);
            new MeshEditor(withCavity).AppendMesh(cavity);
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(withCavity, big, Ops.Union));
            // two boxes stacked as separate shells with a shared face (equal volume and area; the inner faces are extra)
            DMesh3 twoShells = BooleanOracle.BoxMesh(c.A, c);
            new MeshEditor(twoShells).AppendMesh(BooleanOracle.BoxMesh(c.B, c));
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(twoShells, c, Ops.Union));
            // a shifted result in a scaled frame
            var scaled = new BoxCase(c.A, c.B, -4, new Vector3d(3, 0, 0));
            DMesh3 shifted = BooleanOracle.BoxMesh(Bx(0, 0, 0, 2, 1, 1), new BoxCase(c.A, c.B, -4, new Vector3d(3.0625, 0, 0)));
            Assert.NotEqual("", BooleanOracle.CheckBoxResult(shifted, scaled, Ops.Union));
            AssertOk(BooleanOracle.CheckBoxResult(BooleanOracle.BoxMesh(Bx(0, 0, 0, 2, 1, 1), scaled), scaled, Ops.Union), "scaled union");
        }

        [Theory]
        [InlineData(double.NaN)]
        [InlineData(double.PositiveInfinity)]
        [InlineData(double.NegativeInfinity)]
        public void EmptyResult_StillRequiresFiniteCoordinates(double invalid)
        {
            var pair = Families["disjoint"];
            var c = new BoxCase(pair.a, pair.b);
            Assert.Equal("", BooleanOracle.CleanReason(new DMesh3()));
            Assert.Equal("", BooleanOracle.CheckBoxResult(new DMesh3(), c, Ops.Intersection));
            var malformed = new DMesh3();
            malformed.AppendVertex(new Vector3d(invalid, 0, 0));
            Assert.Equal(0, malformed.TriangleCount);
            Assert.Equal("non-finite coordinates", BooleanOracle.CleanReason(malformed));
            Assert.Equal("non-finite coordinates", BooleanOracle.CheckBoxResult(malformed, c, Ops.Intersection));
        }

        [Fact]
        public void Dyadic_IsExact()
        {
            // 0.1 + 0.2 is 0.30000000000000004 in double; exactly it is neither that nor 0.3
            Dyadic sum = Dyadic.Of(0.1) + Dyadic.Of(0.2);
            Assert.NotEqual(Dyadic.Of(0.1 + 0.2), sum);
            Assert.NotEqual(Dyadic.Of(0.3), sum);
            Assert.Equal(Dyadic.Of(0.2), sum - Dyadic.Of(0.1));
            // a product with more than 53 bits, and subnormal and negative values
            double x = 1 + Math.Pow(2, -30);
            Assert.NotEqual(Dyadic.Of(x * x), Dyadic.Of(x) * Dyadic.Of(x));
            Assert.Equal(Dyadic.Of(1) + Dyadic.Of(Math.Pow(2, -29)) + Dyadic.Of(Math.Pow(2, -60)), Dyadic.Of(x) * Dyadic.Of(x));
            Assert.Equal(Dyadic.Of(-double.Epsilon), Dyadic.Of(0) - Dyadic.Of(double.Epsilon));
            Assert.Equal(-3.5, Dyadic.Of(-3.5).ToDouble());
            // the exact volume of a box with a sliver vertex of 2^-30, where the double sum is not exact
            DMesh3 box = BooleanOracle.SliverSplit(new BoxCase(Bx(0, 0, 0, 3, 5, 7), Bx(0, 0, 0, 1, 1, 1), 0, new Vector3d(1000.25, 0, 0)).MeshA(), 6, 30, 3);
            Assert.Equal(Dyadic.Of(6 * 105), BooleanOracle.ExactSixVolume(box));
        }

        [Fact]
        public void SameSolid_IgnoresTriangulation_AndRejectsOtherSolids()
        {
            var c = new BoxCase(Bx(0, 0, 0, 2, 1, 1), Bx(0, 0, 0, 2, 1, 1));
            DMesh3 box = c.MeshA();
            AssertOk(BooleanOracle.SameSolid(box, BooleanOracle.Subdivided(BooleanOracle.CornersRotated(box, 3), 2), 2), "subdivided");
            // equal volume and area, rotated by 90 degrees
            Assert.NotEqual("", BooleanOracle.SameSolid(box, BooleanOracle.BoxMesh(Bx(0, 0, 0, 1, 2, 1), c), 2));
            // equal volume and area, shifted by a little (2^-10 of the size)
            Assert.NotEqual("", BooleanOracle.SameSolid(box, new BoxCase(c.A, c.A, 0, new Vector3d(1.0 / 512, 0, 0)).MeshA(), 2));
            DMesh3 reversed = new DMesh3(box);
            reversed.ReverseOrientation(false);
            Assert.NotEqual("", BooleanOracle.SameSolid(box, reversed, 2));
            Assert.NotEqual("", BooleanOracle.SameSolid(box, new DMesh3(), 2));
            // a tetrahedron vs one with an extra sliver split: the same solid
            var tet = TetFamilies["overlapping"].a;
            AssertOk(BooleanOracle.SameSolid(tet.Mesh(Vector3d.Zero), BooleanOracle.SliverSplit(tet.Mesh(Vector3d.Zero), 3, 20, 1), 4), "sliver split");
        }

        [Fact]
        public void RepresentationChanges_KeepTheSurface_AndChangeTheRepresentation()
        {
            var c = new BoxCase(Bx(0, 0, 0, 2, 1, 3), Bx(0, 0, 0, 1, 1, 1), -5, new Vector3d(100.5, 0, 0));
            DMesh3 box = c.MeshA(), tet = TetFamilies["sliver"].a.Mesh(Vector3d.Zero);
            foreach (Rep r in Enum.GetValues(typeof(Rep)).Cast<Rep>())
                foreach (DMesh3 m in new[] { box, tet }) {
                    DMesh3 x = BooleanOracle.Change(m, r, 11);
                    AssertOk(BooleanOracle.CheckRepresentation(m, x, 4), r.ToString());
                    // dyadic inputs: the signed volume is kept bit for bit
                    Assert.Equal(BooleanOracle.ExactSixVolume(m), BooleanOracle.ExactSixVolume(x));
                }
            // subdivision against the unsplit procedural box: the analytic oracle of the box itself
            AssertOk(BooleanOracle.CheckBoxResult(BooleanOracle.Subdivided(box, 2), new BoxCase(c.A, c.A, c.Exponent, c.Translation), Ops.Union), "subdivided box");
            Assert.Equal(12 * 16, BooleanOracle.Subdivided(box, 2).TriangleCount);
            Assert.True(BooleanOracle.Subdivided(box, 2).IsClosed());
            // slivers are near-degenerate: the smallest angle is tiny
            DMesh3 slivers = BooleanOracle.SliverSplit(box, 3, 24, 2);
            Assert.True(slivers.TriangleIndices().Min(t => slivers.GetTriArea(t)) < 1e-6 * Invariance.Area(box));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// ExactMeshBoolean with open inputs (generalized winding numbers) where an open boundary of an input lies on an
    /// edge that other pieces meet: there the integer jumps of the winding numbers around the edge do not add up to
    /// zero, no inside/outside choice for the regions around the edge fits all pieces, and the kept pieces can run the
    /// edge the same way. They are not joined there (ConflictEdges), so the result stays consistently oriented.
    /// </summary>
    public class ExactBooleanOpenInputTests
    {
        static DMesh3 Box(Vector3d center, Vector3d extent) =>
            new TrivialBox3Generator() { Box = new Box3d(center, extent) }.Generate().MakeDMesh();

        // the box of DefectInputTests.UnionWithBox
        static DMesh3 TestBox() => Box(new Vector3d(0.5, 0.5, 0.5), new Vector3d(0.6, 0.4, 0.7));

        // interior edges whose two triangles run the same way (by vertex ids)
        static int InconsistentEdges(DMesh3 m)
        {
            int n = 0;
            foreach (int e in m.EdgeIndices()) {
                Index2i et = m.GetEdgeT(e), ev = m.GetEdgeV(e);
                if (et.b == DMesh3.InvalidID) continue;
                bool fa = IndexUtil.find_tri_ordered_edge(ev.a, ev.b, m.GetTriangle(et.a).array) != DMesh3.InvalidID;
                bool fb = IndexUtil.find_tri_ordered_edge(ev.a, ev.b, m.GetTriangle(et.b).array) != DMesh3.InvalidID;
                if (fa == fb) ++n;
            }
            return n;
        }

        static void AssertConsistent(ExactMeshBoolean op, string what, bool conflicts = true)
        {
            Assert.True(op.Status == ExactMeshBoolean.BooleanStatus.Success, what + ": " + op.Error);
            DMesh3 r = op.Result;
            Assert.True(r.TriangleCount > 0, what + ": empty");
            Assert.Equal(0, InconsistentEdges(r));
            // (no bowties either, and every vertex has triangles)
            Assert.True(r.CheckValidity(false, FailMode.ReturnOnly), what + ": invalid DMesh3");
            Assert.True(r.VertexIndices().All(v => r.GetVtxEdgeCount(v) > 0), what + ": vertex without triangles");
            // the edges left open where the pieces do not fit together are counted
            if (conflicts)
                Assert.True(op.ConflictEdges > 0, what + ": no conflict edges");
            Assert.True(r.Vertices().All(v => v.IsFinite), what + ": non-finite coordinates");
        }

        public static IEnumerable<object[]> Cases()
        {
            foreach (var op in new[] { ExactMeshBoolean.Operations.Union, ExactMeshBoolean.Operations.Intersection, ExactMeshBoolean.Operations.Difference }) {
                yield return new object[] { "minimized", op };
                yield return new object[] { "minimized, unrounded", op };
            }
        }

        static DMesh3 Input(string name) =>
            name == "minimized" ? DefectInputTests.MinimizedRandomEdits6() : DefectInputTests.MinimizedRandomEdits6Unrounded();

        [Theory]
        [MemberData(nameof(Cases))]
        public void OpenBoundaryOnEdge_ConsistentResult(string name, ExactMeshBoolean.Operations op)
        {
            foreach (bool simplify in new[] { false, true })
                foreach (bool safe in new[] { false, true }) {
                    var b = new ExactMeshBoolean(Input(name), TestBox(), op) { SimplifyFlatRegions = simplify, SafeRounding = safe };
                    b.Compute();
                    Assert.False(b.ExactWindingA);
                    AssertConsistent(b, $"{name} {op} simplify {simplify} safe rounding {safe}");
                }
        }

        [Fact]
        public void Minimized_Union_PiecesRunningTheSameWayAreNotJoined()
        {
            // the union keeps two pieces that run the edge from the origin along the open edge of the fourth
            // triangle the same way (the edge where that triangle meets the coplanar ones)
            var b = new ExactMeshBoolean(DefectInputTests.MinimizedRandomEdits6(), TestBox(), ExactMeshBoolean.Operations.Union);
            Assert.True(b.Compute(), b.Error);
            AssertConsistent(b, "union");
            Assert.True(b.ConflictEdges > 0);
            // reported as open, not silently: the result is not closed
            Assert.False(b.Result.IsClosed());
            Assert.Equal("not closed", gs.MeshRobustRepair.NotCleanReason(b.Result));
            Assert.Contains(b.Result.BoundaryEdgeIndices(), e => b.Result.GetEdgeV(e) is Index2i ev
                && (b.Result.GetVertex(ev.a).Length == 0 || b.Result.GetVertex(ev.b).Length == 0));
        }

        [Fact]
        public void ClosedInputs_NoConflictEdges()
        {
            // the winding numbers of closed meshes are exact: the pieces at every edge fit together
            DMesh3 a = Box(Vector3d.Zero, Vector3d.One);
            DMesh3 s = new Sphere3Generator_NormalizedCube() { Radius = 0.8, EdgeVertices = 6 }.Generate().MakeDMesh();
            MeshTransforms.Translate(s, new Vector3d(0.9, 0.3, 0.2));
            foreach (var op in new[] { ExactMeshBoolean.Operations.Union, ExactMeshBoolean.Operations.Intersection, ExactMeshBoolean.Operations.Difference }) {
                var b = new ExactMeshBoolean(a, s, op);
                Assert.True(b.Compute(), b.Error);
                Assert.Equal(0, b.ConflictEdges);
                Assert.Equal(0, b.NonManifoldTriangles);
                ResultChecks.AssertClosed(b.Result);
            }
            // solids touching along an edge: more than two pieces there, all paired
            var boxes = new List<DMesh3>() { Box(new Vector3d(0.5, 0.5, 0.5), new Vector3d(0.5, 0.5, 0.5)),
                Box(new Vector3d(1.5, 1.5, 0.5), new Vector3d(0.5, 0.5, 0.6)), Box(new Vector3d(-0.5, 1.5, 0.5), new Vector3d(0.5, 0.5, 0.4)) };
            var touching = new ExactMeshBoolean(boxes, ExactMeshBoolean.Operations.Union);
            Assert.True(touching.Compute(), touching.Error);
            Assert.True(touching.NonManifoldEdges > 0);
            Assert.Equal(0, touching.ConflictEdges);
            Assert.Equal(0, touching.NonManifoldTriangles);
            ResultChecks.AssertClosed(touching.Result);
        }

        public static IEnumerable<object[]> SimilarityCases()
        {
            foreach (object[] c in Cases())
                foreach (object[] s in Similarity.Names())
                    yield return new object[] { c[0], c[1], s[0] };
        }

        [Theory]
        [MemberData(nameof(SimilarityCases))]
        public void OpenBoundaryOnEdge_SameResultUnderSimilarity(string input, ExactMeshBoolean.Operations operation, string name)
        {
            Similarity s = Similarity.ByName(name);
            DMesh3 a = Input(input), b = TestBox();
            var op0 = new ExactMeshBoolean(a, b, operation);
            Assert.True(op0.Compute(), op0.Error);
            var op = new ExactMeshBoolean(Invariance.Transformed(a, s), Invariance.Transformed(b, s), operation);
            Assert.True(op.Compute(), op.Error);
            // a consistent result under every transform; the same one under the exact ones (the others round the
            // coordinates, and the case depends on exact coplanarity and coincidence: another arrangement)
            AssertConsistent(op, s.Name, s.IsExact);
            if (s.IsExact) {
                Assert.Equal(op0.ConflictEdges, op.ConflictEdges);
                Assert.Equal("", Invariance.GeometricDifference(op0.Result, Invariance.MappedBack(op.Result, s)));
            }
        }

        [Fact]
        public void ReusedInstance_ConflictEdgesReset_SameResult()
        {
            var op = new ExactMeshBoolean(DefectInputTests.MinimizedRandomEdits6(), TestBox(), ExactMeshBoolean.Operations.Union);
            Assert.True(op.Compute(), op.Error);
            int conflicts = op.ConflictEdges;
            DMesh3 first = op.Result;
            Assert.True(conflicts > 0);
            Assert.True(op.Compute(), op.Error);
            Assert.Equal(conflicts, op.ConflictEdges);
            Assert.Equal("", Invariance.Difference(first, op.Result));
            // then closed inputs on the same instance: no conflicts, as from a fresh instance
            op.MeshA = Box(Vector3d.Zero, Vector3d.One);
            op.MeshB = Box(new Vector3d(0.5, 0.5, 0.5), new Vector3d(1, 0.3, 0.3));
            Assert.True(op.Compute(), op.Error);
            Assert.Equal(0, op.ConflictEdges);
            var fresh = new ExactMeshBoolean(op.MeshA, op.MeshB, ExactMeshBoolean.Operations.Union);
            Assert.True(fresh.Compute(), fresh.Error);
            Assert.Equal("", Invariance.Difference(fresh.Result, op.Result));
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void OpenBoundaryOnEdge_RepeatedRuns_SameResult(string name, ExactMeshBoolean.Operations operation)
        {
            // the arrangement runs in parallel (point ids depend on the thread schedule); the classification and the
            // pairing at the edges must not
            DMesh3 first = null;
            int conflicts = -1;
            for (int run = 0; run < 20; ++run) {
                var op = new ExactMeshBoolean(Input(name), TestBox(), operation);
                Assert.True(op.Compute(), op.Error);
                if (first == null) {
                    first = op.Result;
                    conflicts = op.ConflictEdges;
                    AssertConsistent(op, name);
                } else {
                    Assert.Equal(conflicts, op.ConflictEdges);
                    Assert.Equal("", Invariance.Difference(first, op.Result));
                }
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Inputs with inconsistently oriented triangles (flipped faces, as from broken files): ExactMeshBoolean
    /// orients each component consistently (the larger part by area keeps its orientation) before classifying,
    /// so the result is the consistently oriented solid, not a surface with edges that two triangles run the
    /// same way.
    /// </summary>
    public class ExactBooleanOrientationTests
    {
        static DMesh3 Box(Vector3d lo, Vector3d hi)
        {
            return new TrivialBox3Generator() { Box = new Box3d(new AxisAlignedBox3d(lo, hi)) }.Generate().MakeDMesh();
        }

        static DMesh3 Sphere(Vector3d center, double radius, int edgeVertices)
        {
            DMesh3 s = new Sphere3Generator_NormalizedCube() { Radius = radius, EdgeVertices = edgeVertices }.Generate().MakeDMesh();
            MeshTransforms.Translate(s, center);
            return s;
        }

        // the mesh with the triangles flipped (b, a, c) for which flip(tid) is true
        static DMesh3 Flipped(DMesh3 m, Func<int, bool> flip)
        {
            var r = new DMesh3();
            foreach (int v in m.VertexIndices())
                r.AppendVertex(m.GetVertex(v));
            foreach (int t in m.TriangleIndices()) {
                Index3i f = m.GetTriangle(t);
                r.AppendTriangle(flip(t) ? new Index3i(f.b, f.a, f.c) : f);
            }
            return r;
        }

        // directed edges (by position) used more than once in the same direction
        static int SameDirectionEdges(DMesh3 m)
        {
            var count = new Dictionary<(Vector3d, Vector3d), int>();
            foreach (int t in m.TriangleIndices()) {
                Index3i f = m.GetTriangle(t);
                for (int k = 0; k < 3; ++k) {
                    var e = (m.GetVertex(f[k]), m.GetVertex(f[(k + 1) % 3]));
                    count.TryGetValue(e, out int c);
                    count[e] = c + 1;
                }
            }
            return count.Values.Count(c => c > 1);
        }

        static double Volume(DMesh3 m)
        {
            return MeshMeasurements.VolumeArea(m, m.TriangleIndices(), m.GetVertex).x;
        }

        static void AssertOriented(DMesh3 r, double volume)
        {
            Assert.Equal(0, SameDirectionEdges(r));
            Assert.True(r.CheckValidity(false, FailMode.ReturnOnly));
            Assert.Equal("", MeshRobustRepair.NotCleanReason(r));
            Assert.Equal(volume, Volume(r), 9);
        }

        [Fact]
        public void Resolve_BoxWithOneFlippedTriangle_IsOrientedBox()
        {
            DMesh3 m = Flipped(Box(Vector3d.Zero, Vector3d.One), (t) => t == 0);
            DMesh3 r = ExactMeshBoolean.Resolve(m);
            Assert.NotNull(r);
            Assert.Equal(12, r.TriangleCount);
            AssertOriented(r, 1);
        }

        // the triangles as a soup: three vertices of their own each
        static DMesh3 Soup(DMesh3 m)
        {
            var r = new DMesh3();
            foreach (int t in m.TriangleIndices()) {
                Index3i f = m.GetTriangle(t);
                r.AppendTriangle(r.AppendVertex(m.GetVertex(f.a)), r.AppendVertex(m.GetVertex(f.b)), r.AppendVertex(m.GetVertex(f.c)));
            }
            return r;
        }

        [Fact]
        public void Resolve_FlippedTriangles_CallersMeshUnchanged()
        {
            DMesh3 m = Flipped(Box(Vector3d.Zero, Vector3d.One), (t) => t == 0 || t == 7);
            var before = m.TriangleIndices().Select(m.GetTriangle).ToList();
            var b = new ExactMeshBoolean(m, new DMesh3(), ExactMeshBoolean.Operations.Union);
            Assert.True(b.Compute(), b.Error);
            Assert.Equal(2, b.ReorientedTriangles);
            Assert.True(b.ExactWindingA);       // oriented, the box is closed in the winding sense: exact winding numbers
            AssertOriented(b.Result, 1);
            Assert.Equal(before, m.TriangleIndices().Select(m.GetTriangle).ToList());
        }

        [Fact]
        public void OpenMeshWithInvertedShell_OnlyFlippedTriangleReoriented()
        {
            // one mesh: an outer box with a flipped triangle and an inverted cavity box (consistent on its own); the
            // mesh is not closed in the winding sense, so it is reoriented: only the flipped triangle, the cavity
            // stays inverted
            DMesh3 m = Flipped(Box(Vector3d.Zero, 3 * Vector3d.One), (t) => t == 4);
            DMesh3 cavity = Box(Vector3d.One, 2 * Vector3d.One);
            cavity.ReverseOrientation();
            MeshEditor.Append(m, cavity);
            var b = new ExactMeshBoolean(m, new DMesh3(), ExactMeshBoolean.Operations.Union);
            Assert.True(b.Compute(), b.Error);
            Assert.Equal(1, b.ReorientedTriangles);
