using System;
using System.Collections.Generic;
using System.Numerics;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The error bounds of the floating-point filters of ExactMeshArrangement, checked against exact values on
    /// adversarial inputs: nearly degenerate configurations (where the filters decide at their bound), large
    /// offsets (cancellation in the differences), huge and subnormal magnitudes, and exact points at the corners
    /// of the error boxes of their approximations (the worst case where the value is affine in each coordinate;
    /// incircle is not, so it also gets points inside the boxes). Every comparison is exact (scaled integers).
    /// </summary>
    public class ExactFilterBoundTests
    {
        // doubles as integers: v * 2^S (exact for every finite double, the smallest is 2^-1074)
        const int S = 1100;
        const double U = 2.220446049250313e-16;

        static BigInteger Q(double v, int scale = S)
        {
            BigInteger m; int e;
            ExactPoint3.Decompose(v, out m, out e);
            return m.IsZero ? BigInteger.Zero : (m << (e + scale));
        }

        // |approx - num / (den 2^scale)| <= err, exactly (den > 0)
        static bool Within(double approx, double err, BigInteger num, BigInteger den, int scale)
        {
            return BigInteger.Abs(Q(approx, scale) * den - num) <= Q(err, scale) * den;
        }

        static void AssertWithin(double approx, double err, BigInteger num, BigInteger den, int scale, string what)
        {
            Assert.True(err >= 0, what + ": negative bound");
            Assert.True(Within(approx, err, num, den, scale),
                $"{what}: approximation {approx:R}, exact {ExactPoint3.ToDouble(num, den << scale, 0):R}, bound {err:R}");
        }

        // the corners of the error box: c + s e for the signs in the bits of mask
        static BigInteger Corner(double c, double e, int mask, int bit)
        {
            return ((mask >> bit) & 1) == 0 ? Q(c) - Q(e) : Q(c) + Q(e);
        }

        // a random double of magnitude about 2^k
        static double Rnd(Random r, int k)
        {
            return (r.NextDouble() - 0.5) * Math.Pow(2, k + 1);
        }

        // the scales of the cases: coordinates around 2^k, with offsets around 2^off (cancellation in the differences)
        static IEnumerable<(int k, int off)> Scales()
        {
            foreach (int k in new[] { -1070, -1060, -900, -40, -3, 0, 10, 52, 60, 300 })
                foreach (int off in new[] { int.MinValue, k + 20, k + 50 })
                    yield return (k, off);
        }

        // an error bound for coordinates of magnitude about 2^k: none, of the order of rounding, larger, subnormal
        static double ErrorOf(Random r, int k, int kind)
        {
            switch (kind) {
                case 0: return 0;
                case 1: return 4 * U * Math.Pow(2, k) * r.NextDouble();
                case 2: return Math.Pow(2, k - 30) * r.NextDouble();
                default: return double.Epsilon * r.Next(1, 8);
            }
        }

        [Fact]
        public void Orient2d_BoundHolds_AtWorstCorners()
        {
            var r = new Random(1);
            int cases = 0;
            foreach (var (k, off) in Scales())
                for (int iter = 0; iter < 30; ++iter) {
                    double o = (off == int.MinValue) ? 0 : Math.Pow(2, off);
                    var a = new Vector3d(o + Rnd(r, k), o + Rnd(r, k), 0);
                    var b = new Vector3d(o + Rnd(r, k), o + Rnd(r, k), 0);
                    // c nearly on the line a-b (on it before rounding, or a few ulps off)
                    double t = r.NextDouble() * 3 - 1;
                    var c = new Vector3d(a.x + t * (b.x - a.x), a.y + t * (b.y - a.y), 0);
                    if (iter % 3 == 1)
                        c.y += Math.Pow(2, k - 50) * (r.NextDouble() - 0.5);
                    if (iter % 5 == 4)
                        c = a;      // repeated point
                    double e = ErrorOf(r, k, iter % 4);
                    double err;
                    double f = ExactMeshArrangement.orient2d_approx(a, b, c, 0, 1, e, out err);
                    for (int mask = 0; mask < 64; ++mask) {
                        BigInteger ax = Corner(a.x, e, mask, 0), ay = Corner(a.y, e, mask, 1), bx = Corner(b.x, e, mask, 2),
                            by = Corner(b.y, e, mask, 3), cx = Corner(c.x, e, mask, 4), cy = Corner(c.y, e, mask, 5);
                        BigInteger det = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax);
                        AssertWithin(f, err, det, BigInteger.One, 2 * S, $"orient2d k={k} off={off} iter={iter} mask={mask}");
                    }
                    cases++;
                }
            Assert.True(cases > 0);
        }

        [Fact]
        public void InCircle_BoundHolds_AtWorstCorners()
        {
            var r = new Random(2);
            foreach (var (k, off) in Scales()) {
                if (k > 200 || k < -1000)
                    continue;       // (degree 4: beyond the double range the filter has no bound; below 2^-1000 the
                                    // bound is the absolute term alone, as at k = -900)
                for (int iter = 0; iter < 12; ++iter) {
                    double o = (off == int.MinValue) ? 0 : Math.Pow(2, off);
                    // four points nearly on a circle (rounded), d sometimes exactly a, b or c
                    double rad = Math.Pow(2, k), cx0 = o + Rnd(r, k), cy0 = o + Rnd(r, k);
                    var p = new Vector3d[4];
                    for (int m = 0; m < 4; ++m) {
                        double ang = r.NextDouble() * 2 * Math.PI;
                        p[m] = new Vector3d(cx0 + rad * Math.Cos(ang), cy0 + rad * Math.Sin(ang), 0);
                    }
                    if (iter % 4 == 3)
                        p[3] = p[1];
                    double e = ErrorOf(r, k, iter % 4);
                    double bound;
                    double f = ExactMeshArrangement.incircle_approx(p[0], p[1], p[2], p[3], 0, 1, e, out bound);
                    // the 256 corners, then random points inside the boxes (the determinant is cubic in each point)
                    for (int mask = 0; mask < 256 + 64; ++mask) {
                        var X = new BigInteger[4];
                        var Y = new BigInteger[4];
                        for (int m = 0; m < 4; ++m) {
                            if (mask < 256) {
                                X[m] = Corner(p[m].x, e, mask, 2 * m);
                                Y[m] = Corner(p[m].y, e, mask, 2 * m + 1);
                            } else {
                                X[m] = Q(p[m].x) + Q(e) * new BigInteger(r.Next(-1000, 1001)) / 1000;
                                Y[m] = Q(p[m].y) + Q(e) * new BigInteger(r.Next(-1000, 1001)) / 1000;
                            }
                        }
                        BigInteger adx = X[0] - X[3], ady = Y[0] - Y[3], bdx = X[1] - X[3], bdy = Y[1] - Y[3], cdx = X[2] - X[3], cdy = Y[2] - Y[3];
                        BigInteger det = (adx * adx + ady * ady) * (bdx * cdy - cdx * bdy) + (bdx * bdx + bdy * bdy) * (cdx * ady - adx * cdy)
                            + (cdx * cdx + cdy * cdy) * (adx * bdy - bdx * ady);
                        AssertWithin(f, bound, det, BigInteger.One, 4 * S, $"incircle k={k} off={off} iter={iter} mask={mask}");
                    }
                }
            }
        }

        [Fact]
        public void CompareAlong_BoundHolds_WithExactDirection()
        {
            // the direction is an exact integer (rounded to double by the filter), the points differ nearly
            // perpendicular to it
            var r = new Random(3);
            foreach (var (k, off) in Scales())
                for (int iter = 0; iter < 30; ++iter) {
                    BigInteger dx = new BigInteger(Rnd(r, 62)) << r.Next(0, 40), dy = new BigInteger(Rnd(r, 62)), dz = new BigInteger(Rnd(r, 20));
                    double fdx = (double)dx, fdy = (double)dy, fdz = (double)dz;
                    double o = (off == int.MinValue) ? 0 : Math.Pow(2, off);
                    var a = new Vector3d(o + Rnd(r, k), o + Rnd(r, k), o + Rnd(r, k));
                    // b - a nearly perpendicular to d
                    var perp = new Vector3d(fdy, -fdx, 0).Normalized * Math.Pow(2, k) * r.NextDouble();
                    var b = a + perp + new Vector3d(Rnd(r, k - 45), Rnd(r, k - 45), Rnd(r, k - 45)) * ((iter % 2 == 0) ? 1 : 0);
                    double e = ErrorOf(r, k, iter % 4);
                    double bound;
                    double f = ExactMeshArrangement.along_approx(fdx, fdy, fdz, a, b, e, out bound);
                    for (int mask = 0; mask < 64; ++mask) {
                        BigInteger v = dx * (Corner(a.x, e, mask, 0) - Corner(b.x, e, mask, 1)) + dy * (Corner(a.y, e, mask, 2) - Corner(b.y, e, mask, 3))
                            + dz * (Corner(a.z, e, mask, 4) - Corner(b.z, e, mask, 5));
                        AssertWithin(f, bound, v, BigInteger.One, S, $"along k={k} off={off} iter={iter} mask={mask}");
                    }
                }
        }

        [Fact]
        public void OrderKey_BoundHolds_AtWorstCorners()
        {
            // the weights are exact doubles; their exact value as integers over 2^53
            double[] alpha = ExactMeshArrangement.Alpha;
            var r = new Random(4);
            foreach (var (k, off) in Scales())
                for (int iter = 0; iter < 30; ++iter) {
                    double o = (off == int.MinValue) ? 0 : Math.Pow(2, off);
                    var a = new Vector3d(o + Rnd(r, k), Rnd(r, k), -o + Rnd(r, k));
                    double e = ErrorOf(r, k, iter % 4);
                    double err;
                    double f = ExactMeshArrangement.order_key(a, e, out err);
                    for (int mask = 0; mask < 8; ++mask) {
                        BigInteger v = Q(alpha[0], 53) * Corner(a.x, e, mask, 0) + Q(alpha[1], 53) * Corner(a.y, e, mask, 1) + Q(alpha[2], 53) * Corner(a.z, e, mask, 2);
                        AssertWithin(f, err, v, BigInteger.One, S + 53, $"order key k={k} off={off} iter={iter} mask={mask}");
                    }
                }
        }

        [Fact]
        public void PlaneValue_BoundHolds_ForRoundedCoefficients()
        {
            // integer plane coefficients beyond 2^53 (rounded to double), points nearly on the plane
            var r = new Random(5);
            foreach (int bits in new[] { 10, 53, 54, 80, 200 })
                for (int iter = 0; iter < 200; ++iter) {
                    BigInteger A = new BigInteger(Rnd(r, 50)) << (bits - 50 > 0 ? bits - 50 : 0), B = new BigInteger(Rnd(r, 50)) << r.Next(0, Math.Max(1, bits - 50)),
                        C = new BigInteger(Rnd(r, 30)) + 1;
                    double x = Rnd(r, 20), y = Rnd(r, 20), z = Rnd(r, 20);
                    // D so that the point is on the plane (up to the rounding of x, y, z), sometimes exactly
                    BigInteger D = (A * Q(x) + B * Q(y) + C * Q(z)) >> S;
                    double[] pa = { (double)A, (double)B, (double)C, (double)D };
                    var p = new Vector3d(x, y, z);
                    double e = ErrorOf(r, 20, iter % 3);
                    double err;
                    double f = ExactMeshArrangement.plane_value(pa, 0, p, e, out err);
                    for (int mask = 0; mask < 8; ++mask) {
                        BigInteger v = A * Corner(x, e, mask, 0) + B * Corner(y, e, mask, 1) + C * Corner(z, e, mask, 2) - (D << S);
                        AssertWithin(f, err, v, BigInteger.One, S, $"plane value bits={bits} iter={iter} mask={mask}");
                    }
                }
        }

        // the exact point P + t (Q - P), t = sp / (sp - sq), for exact P, Q (scaled by 2^S) and values sp, sq of
        // opposite signs: coordinate k as num / (den 2^S)
        static void SegmentExact(BigInteger[] P, BigInteger[] Qe, BigInteger sp, BigInteger sq, int k, out BigInteger num, out BigInteger den)
        {
            den = sp - sq;
            num = P[k] * den + sp * (Qe[k] - P[k]);
            if (den.Sign < 0) { den = -den; num = -num; }
        }

        [Fact]
        public void SegmentPoint_BoundHolds_AtWorstCorners()
        {
            var r = new Random(6);
            int checkedCorners = 0;
            foreach (var (k, off) in Scales())
                for (int iter = 0; iter < 30; ++iter) {
                    double o = (off == int.MinValue) ? 0 : Math.Pow(2, off);
                    var P = new Vector3d(o + Rnd(r, k), o + Rnd(r, k), Rnd(r, k));
                    var Qv = new Vector3d(o + Rnd(r, k), Rnd(r, k), o + Rnd(r, k));
                    double ep = ErrorOf(r, k, iter % 4), eq = ErrorOf(r, k, (iter + 1) % 4);
                    // values of opposite signs: both large, one tiny (the crossing at an end), with errors up to
                    // their size (a poor approximation of t)
                    int sk = r.Next(-300, 300);
                    double sp = Math.Pow(2, sk) * (0.5 + r.NextDouble()), sq = -Math.Pow(2, sk + ((iter % 3 == 0) ? -60 : r.Next(-5, 5))) * (0.5 + r.NextDouble());
                    double esp = Math.Abs(sp) * ((iter % 2 == 0) ? U : 1e-3 * r.NextDouble()), esq = Math.Abs(sq) * ((iter % 5 == 0) ? 0.9 : U);
                    double err;
                    Vector3d a = ExactMeshArrangement.segment_point(P, ep, Qv, eq, sp, esp, sq, esq, out err);
                    for (int mask = 0; mask < 256; ++mask) {
                        var Pe = new[] { Corner(P.x, ep, mask, 0), Corner(P.y, ep, mask, 1), Corner(P.z, ep, mask, 2) };
                        var Qe = new[] { Corner(Qv.x, eq, mask, 3), Corner(Qv.y, eq, mask, 4), Corner(Qv.z, eq, mask, 5) };
                        BigInteger spe = Corner(sp, esp, mask, 6), sqe = Corner(sq, esq, mask, 7);
                        if (spe.Sign * sqe.Sign >= 0)
                            continue;       // (the contract: exactly of opposite signs)
                        for (int c = 0; c < 3; ++c) {
                            BigInteger num, den;
                            SegmentExact(Pe, Qe, spe, sqe, c, out num, out den);
                            AssertWithin(a[c], err, num, den, S, $"segment point k={k} off={off} iter={iter} mask={mask} coordinate {c}");
                        }
                        checkedCorners++;
                    }
                }
            Assert.True(checkedCorners > 10000);
        }

        [Fact]
        public void SegmentPoint_SubnormalResult_BoundIsNotZero()
        {
            // the crossing at 1.5 * 2^-1074 rounds to 2 * 2^-1074; the relative terms of the bound underflow to 0
            var P = Vector3d.Zero;
            var Qv = new Vector3d(3 * double.Epsilon, 0, 0);
            double err;
            Vector3d a = ExactMeshArrangement.segment_point(P, 0, Qv, 0, 1, 0, -1, 0, out err);
            AssertWithin(a.x, err, 3, 2, 1074, "subnormal segment point");
        }

        // the point common to three planes with exact coefficients p (any common scale), by Cramer
        static bool PlanesExact(BigInteger[][] p, out BigInteger[] num, out BigInteger den)
        {
            BigInteger c23x = p[1][1] * p[2][2] - p[1][2] * p[2][1], c23y = p[1][2] * p[2][0] - p[1][0] * p[2][2], c23z = p[1][0] * p[2][1] - p[1][1] * p[2][0];
            BigInteger c31x = p[2][1] * p[0][2] - p[2][2] * p[0][1], c31y = p[2][2] * p[0][0] - p[2][0] * p[0][2], c31z = p[2][0] * p[0][1] - p[2][1] * p[0][0];
            BigInteger c12x = p[0][1] * p[1][2] - p[0][2] * p[1][1], c12y = p[0][2] * p[1][0] - p[0][0] * p[1][2], c12z = p[0][0] * p[1][1] - p[0][1] * p[1][0];
            den = p[0][0] * c23x + p[0][1] * c23y + p[0][2] * c23z;
            num = new[] { p[0][3] * c23x + p[1][3] * c31x + p[2][3] * c12x, p[0][3] * c23y + p[1][3] * c31y + p[2][3] * c12y,
                p[0][3] * c23z + p[1][3] * c31z + p[2][3] * c12z };
            if (den.Sign < 0) {
                den = -den;
                for (int k = 0; k < 3; ++k) num[k] = -num[k];
            }
            // num / den is the point (the scale of the coefficients cancels); scale num by 2^S for the comparison
            for (int k = 0; k < 3; ++k) num[k] <<= S;
            return den.IsZero == false;
        }

        static double[][] Rounded(BigInteger[][] p, int scale)
        {
            var pl = new double[3][];
            for (int m = 0; m < 3; ++m) {
                pl[m] = new double[4];
                for (int c = 0; c < 4; ++c)
                    pl[m][c] = (scale == 0) ? (double)p[m][c] : ExactPoint3.ToDouble(p[m][c], BigInteger.One, -scale);
            }
            return pl;
        }

        // planes_approx of the coefficients rounded to double (relative errors 2^-53) against the exact point of
        // the exact coefficients p / 2^scale
        static void AssertPlanes(BigInteger[][] p, int scale, string what)
        {
            var pl = Rounded(p, scale);
            double err;
            Vector3d x = ExactMeshArrangement.planes_approx(pl[0], 0, pl[1], 0, pl[2], 0, out err);
            BigInteger[] num; BigInteger den;
            if (PlanesExact(p, out num, out den) == false || double.IsInfinity(err))
                return;     // (dependent or nearly dependent: computed exactly, no bound)
            for (int k = 0; k < 3; ++k)
                AssertWithin(x[k], err, num[k], den, S, $"{what} coordinate {k}");
        }

        [Fact]
        public void PlanesPoint_BoundHolds_NearlyDependentAndExtreme()
        {
            var r = new Random(7);
            int bounded = 0;
            foreach (int k in new[] { 0, 20, 52, 100, 300 })
                for (int iter = 0; iter < 200; ++iter) {
                    // three planes through about the same line (nearly dependent), integer coefficients of about
                    // 2^k, with low bits beyond the 53 of a double (rounded for planes_approx)
                    var n0 = new Vector3d(Rnd(r, 0), Rnd(r, 0), Rnd(r, 0)).Normalized;
                    var p = new BigInteger[3][];
                    double eps = Math.Pow(2, -r.Next(1, 50));
                    int extra = (iter % 2 == 0) ? 30 : 0;
                    Func<double, BigInteger> big = (v) => (new BigInteger(Math.Round(v)) << extra) + r.Next(0, 1 << 30) * (extra > 0 ? 1 : 0);
                    for (int m = 0; m < 3; ++m) {
                        Vector3d n = (m == 0) ? n0 : (n0 + new Vector3d(Rnd(r, 0), Rnd(r, 0), Rnd(r, 0)) * eps);
                        double s = Math.Pow(2, k);
                        p[m] = new[] { big(n.x * s), big(n.y * s), big(n.z * s), big(Rnd(r, k + 10)) };
                    }
                    AssertPlanes(p, 0, $"planes k={k} iter={iter}");
                    double err;
                    var pl = Rounded(p, 0);
                    ExactMeshArrangement.planes_approx(pl[0], 0, pl[1], 0, pl[2], 0, out err);
                    if (double.IsInfinity(err) == false)
                        bounded++;
                }
            Assert.True(bounded > 100);
        }

        [Fact]
        public void PlanesPoint_SubnormalResult_BoundIsNotZero()
        {
            // x = 2^-1074 / 3 rounds to 0, the relative terms of the bound underflow (coefficients that are not
            // integers: the contract of the function, not the planes of the arrangement)
            var pl = new[] { new[] { 3.0, 0, 0, double.Epsilon }, new[] { 0, 1.0, 0, 0 }, new[] { 0, 0, 1.0, 0 } };
            var p = new BigInteger[3][];
            for (int m = 0; m < 3; ++m)
                p[m] = new[] { Q(pl[m][0]), Q(pl[m][1]), Q(pl[m][2]), Q(pl[m][3]) };
            AssertPlanes(p, S, "subnormal planes point");
            double err;
            ExactMeshArrangement.planes_approx(pl[0], 0, pl[1], 0, pl[2], 0, out err);
            Assert.True(err > 0);
        }

        [Fact]
        public void AddPoint_TinyRational_BoundCoversTheApproximation()
        {
            // rational points whose coordinates are subnormal or below the double range: the approximation is
            // rounded absolutely (or 0), not relatively
            var arr = new ExactMeshArrangement(new List<DMesh3>());
            var cases = new[] {
                ExactPoint3.Create(1, 0, 0, BigInteger.One << 1100),
                ExactPoint3.Create(1, -5, 7, 3 * (BigInteger.One << 1072)),
                ExactPoint3.Create(BigInteger.One << 2000, 1, 0, 3 * (BigInteger.One << 1070)),
            };
            foreach (ExactPoint3 p in cases) {
                int id = arr.AddPoint(p);
                Vector3d a = arr.Approx(id);
                double e = arr.ApproxError(id);
                for (int k = 0; k < 3; ++k)
                    if (double.IsInfinity(a[k]) == false)
                        AssertWithin(a[k], e, p[k] << S, p.W, S, $"rational point {p} coordinate {k}");
            }
        }

        [Fact]
        public void ExactPoint3_Indexer_RejectsIndicesOutsideXYZ()
        {
            ExactPoint3 p = ExactPoint3.Create(1, 2, 3, 5);
            Assert.Equal(new BigInteger(1), p[0]);
            Assert.Equal(new BigInteger(2), p[1]);
            Assert.Equal(new BigInteger(3), p[2]);
            Assert.Throws<ArgumentOutOfRangeException>(() => p[3]);
            Assert.Throws<ArgumentOutOfRangeException>(() => p[-1]);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The implicit points of ExactMeshArrangement: their approximations are within their error bounds, the
    /// filtered predicates on them agree with the exact ones (also for exactly collinear points, whose
    /// approximations are not), and coincident points from different constructions get one id.
    /// </summary>
    public class ExactImplicitPointTests
    {
        static DMesh3 Box(Vector3d center, double size, Quaterniond rotation)
        {
            DMesh3 mesh = new TrivialBox3Generator() { Box = new Box3d(center, new Vector3d(size, size, size)) }.Generate().MakeDMesh();
            MeshTransforms.Rotate(mesh, center, rotation);
            return mesh;
        }

        static Quaterniond Rotation(Random rand, double maxAngle)
        {
            var axis = new Vector3d(rand.NextDouble() - 0.5, rand.NextDouble() - 0.5, rand.NextDouble() - 0.5).Normalized;
            return new Quaterniond(axis, rand.NextDouble() * maxAngle);
        }

        // arrangements with all kinds of implicit points: three rotated boxes (edge-plane points and triple points),
        // nearly coplanar boxes (ill-conditioned), coplanar boxes (crossing edges), at different scales and offsets
        public static IEnumerable<object[]> Cases()
        {
            for (int seed = 0; seed < 12; ++seed)
                yield return new object[] { seed };
        }

        static ExactMeshArrangement Build(int seed)
        {
            var rand = new Random(seed);
            double scale = Math.Pow(10, rand.Next(-6, 7));
            Vector3d offset = new Vector3d(rand.NextDouble(), rand.NextDouble(), rand.NextDouble()) * scale * ((seed % 3 == 0) ? 1e4 : 1);
            List<DMesh3> meshes;
            switch (seed % 4) {
                case 0:
                case 1:
                    meshes = new List<DMesh3>() { Box(Vector3d.Zero, 1, Rotation(rand, 360)), Box(new Vector3d(0.7, 0.2, 0.1), 0.8, Rotation(rand, 360)),
                        Box(new Vector3d(0.2, 0.7, -0.3), 0.9, Rotation(rand, 360)) };
                    break;
                case 2:
                    // nearly coplanar faces (rotations by tiny angles), and triple points of nearly parallel planes
                    meshes = new List<DMesh3>() { Box(Vector3d.Zero, 1, Rotation(rand, 1e-6)), Box(new Vector3d(0.5, 0.3, 0), 1, Rotation(rand, 1e-9)),
                        Box(new Vector3d(0.2, 0.6, 0.1), 0.9, Rotation(rand, 1e-3)), Box(new Vector3d(0.3, 0.1, 0.2), 1.1, Rotation(rand, 1e-4)) };
                    break;
                default:
                    // coplanar overlapping faces (crossing edges in common planes) and a rotated box through them
                    meshes = new List<DMesh3>() { Box(Vector3d.Zero, 1, Quaterniond.Identity), Box(new Vector3d(0.5, 0.3, 0), 1, new Quaterniond(Vector3d.AxisZ, 30)),
                        Box(new Vector3d(0.2, 0.6, 0.1), 0.9, Rotation(rand, 360)) };
                    break;
            }
            foreach (DMesh3 m in meshes) {
                MeshTransforms.Scale(m, scale);
                MeshTransforms.Translate(m, offset);
            }
            var arr = new ExactMeshArrangement(meshes) { SelfIntersections = true };
            arr.Compute();
            return arr;
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void Approximations_AreWithinTheirErrorBounds(int seed)
        {
            var arr = Build(seed);
            var kinds = new HashSet<ExactMeshArrangement.PointKind>();
            for (int id = 0; id < arr.PointCount; ++id) {
                kinds.Add(arr.KindOf(id));
                AssertWithinBound(arr, id);
            }
            if (seed % 4 < 3)
                Assert.Contains(ExactMeshArrangement.PointKind.Planes, kinds);
            Assert.Contains(ExactMeshArrangement.PointKind.EdgePlane, kinds);
            if (seed % 4 == 3)
                Assert.Contains(ExactMeshArrangement.PointKind.Segments, kinds);
        }

        // v as an exact fraction num / 2^-exp (exp <= 0) with a common exponent for the comparison below
        static BigInteger Scaled(double v, int exp)
        {
            BigInteger m; int e;
            ExactPoint3.Decompose(v, out m, out e);
            return m.IsZero ? BigInteger.Zero : (m << (e - exp));
        }

        // |approximation - exact| <= bound, exactly (no rounding of the comparison)
        static void AssertWithinBound(ExactMeshArrangement arr, int id)
        {
            ExactPoint3 x = arr.Exact(id);
            Vector3d a = arr.Approx(id);
            double e = arr.ApproxError(id);
            Assert.True(e >= 0 && double.IsInfinity(e) == false);
            for (int k = 0; k < 3; ++k) {
                // |a W - X| <= e W, all scaled by 2^1100 to integers
                const int exp = -1100;
                BigInteger lhs = BigInteger.Abs(Scaled(a[k], exp) * x.W - (x[k] << -exp)), rhs = Scaled(e, exp) * x.W;
                Assert.True(lhs <= rhs, $"point {id} ({arr.KindOf(id)}): {a[k]} vs {ExactPoint3.ToDouble(x[k], x.W, 0)}, bound {e}");
            }
        }

        [Fact]
        public void Constructions_IllConditioned_ApproximationsWithinBounds()
        {
            // nearly dependent planes, edges nearly parallel to the plane, nearly parallel crossing segments: the
            // approximations are poor, the bounds must still hold
            var rand = new Random(17);
            Func<double, Vector3d> rnd = (s) => new Vector3d(rand.NextDouble() - 0.5, rand.NextDouble() - 0.5, rand.NextDouble() - 0.5) * s;
            int planes = 0, edges = 0, segments = 0;
            for (int iter = 0; iter < 300; ++iter) {
                double eps = Math.Pow(10, -rand.Next(2, 13));
                Vector3d dir = rnd(1).Normalized, c = rnd(2);
                DMesh3 mesh = new DMesh3();
                // three triangles whose planes nearly contain the direction dir (all through about the same line)
                for (int t = 0; t < 3; ++t) {
                    Vector3d side = dir.Cross(rnd(1)).Normalized;
                    Vector3d p0 = c + rnd(eps), p1 = p0 + dir + rnd(eps), p2 = p0 + side + rnd(eps);
                    int v0 = mesh.AppendVertex(p0), v1 = mesh.AppendVertex(p1), v2 = mesh.AppendVertex(p2);
                    mesh.AppendTriangle(v0, v1, v2);
                }
                // an edge nearly parallel to the first plane, and two nearly parallel segments in the plane z = 0
                Vector3d n0 = (mesh.GetVertex(1) - mesh.GetVertex(0)).Cross(mesh.GetVertex(2) - mesh.GetVertex(0)).Normalized;
                Vector3d along = n0.Cross(rnd(1)).Normalized;
                int e0 = mesh.AppendVertex(c - along + n0 * eps * rand.NextDouble()), e1 = mesh.AppendVertex(c + along - n0 * eps * rand.NextDouble());
                Vector3d s0 = new Vector3d(-1, rnd(eps).y, 0), s1 = new Vector3d(1, rnd(eps).y, 0);
                int q0 = mesh.AppendVertex(s0), q1 = mesh.AppendVertex(s1);
                int r0 = mesh.AppendVertex(new Vector3d(-1, s0.y + eps * (0.5 + rand.NextDouble()), 0)), r1 = mesh.AppendVertex(new Vector3d(1, s1.y - eps * (0.5 + rand.NextDouble()), 0));
                var arr = new ExactMeshArrangement(new List<DMesh3>() { mesh });
                arr.Compute();
                Func<int, int> pt = (v) => arr.VertexPoints[0][v];

                var pl = arr.Triangles.Take(3).Select(t => t.P).ToArray();
                BigInteger det = pl[0].A * (pl[1].B * pl[2].C - pl[1].C * pl[2].B) - pl[0].B * (pl[1].A * pl[2].C - pl[1].C * pl[2].A)
                    + pl[0].C * (pl[1].A * pl[2].B - pl[1].B * pl[2].A);
                if (det.IsZero == false) {
                    AssertWithinBound(arr, arr.PlanesPointImplicit(0, 4, 8));
                    planes++;
                }
                Func<int, BigInteger> side0 = (v) => { var x = arr.Exact(pt(v)); return pl[0].A * x.X + pl[0].B * x.Y + pl[0].C * x.Z - pl[0].D * x.W; };
                if (side0(e0).Sign * side0(e1).Sign < 0) {
                    AssertWithinBound(arr, arr.EdgePlanePointImplicit(pt(e0), pt(e1), 0));
                    edges++;
                }
                // q0-q1 and r0-r1 cross (r starts above q and ends below)
                AssertWithinBound(arr, arr.SegmentsPointImplicit(pt(q0), pt(q1), pt(r0), pt(r1), 2));
                segments++;
            }
            Assert.True(planes > 250 && edges > 100 && segments == 300, $"{planes} {edges} {segments}");
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void FilteredPredicates_MatchExact_OnImplicitPoints(int seed)
        {
            var arr = Build(seed);
            var rand = new Random(seed);
            int collinear = 0;
            foreach (var t in arr.Triangles) {
                if (t.Segments.Count == 0)
                    continue;
                var pts = t.Points.Select(arr.Canonical).Concat(t.Corners.array).Distinct().ToList();
                Func<Func<int>, int> both = (f) => {
                    arr.DisableFilters = false;
                    int filtered = f();
                    arr.DisableFilters = true;
                    int exact = f();
                    arr.DisableFilters = false;
                    Assert.Equal(exact, filtered);
                    return exact;
                };
                // points on the segments: exactly collinear, but their approximations are not
                foreach (var s in t.Segments) {
                    int p = arr.Canonical(s.P), q = arr.Canonical(s.Q);
                    var plane = arr.PlaneOf(s.Line);
                    BigInteger dx = t.NY * plane.C - t.NZ * plane.B, dy = t.NZ * plane.A - t.NX * plane.C, dz = t.NX * plane.B - t.NY * plane.A;
                    foreach (int r in pts) {
                        if (both(() => arr.Orient(t, p, q, r)) == 0)
                            collinear++;
                        both(() => arr.compare_along(dx, dy, dz, p, r));
                    }
                }
                for (int k = 0; k < 40; ++k) {
                    int a = pts[rand.Next(pts.Count)], b = pts[rand.Next(pts.Count)], c = pts[rand.Next(pts.Count)], d = pts[rand.Next(pts.Count)];
                    both(() => arr.Orient(t, a, b, c));
                    both(() => arr.InCircle(t, a, b, c, d));
                    both(() => arr.ComparePoints(a, b));
                }
            }
            Assert.True(collinear > 0);
        }

        // reference: the sign of the 4x4 incircle determinant with rows (x w, y w, x^2 + y^2, w^2) of the exact points,
        // times the sign of the projection (the formula before the 3x3 form and the double path)
        static int ReferenceInCircle(ExactMeshArrangement arr, ExactMeshArrangement.InputTriangle t, int[] ids)
        {
            int i = (t.Axis + 1) % 3, j = (t.Axis + 2) % 3;
            var m = new BigInteger[4, 4];
            for (int k = 0; k < 4; ++k) {
                ExactPoint3 v = arr.Exact(ids[k]);
                m[k, 0] = v[i] * v.W; m[k, 1] = v[j] * v.W; m[k, 2] = v[i] * v[i] + v[j] * v[j]; m[k, 3] = v.W * v.W;
            }
            BigInteger det = BigInteger.Zero;
            for (int c = 0; c < 4; ++c) {
                int c0 = (c == 0) ? 1 : 0, c1 = (c <= 1) ? 2 : 1, c2 = (c <= 2) ? 3 : 2;
                BigInteger minor = ExactPoint3.Det3(m[1, c0], m[1, c1], m[1, c2], m[2, c0], m[2, c1], m[2, c2], m[3, c0], m[3, c1], m[3, c2]);
                det += ((c % 2 == 0) ? m[0, c] : -m[0, c]) * minor;
            }
            return det.Sign * t.Sign;
        }

        static int ReferenceOrient(ExactMeshArrangement arr, ExactMeshArrangement.InputTriangle t, int p, int q, int r)
        {
            int i = (t.Axis + 1) % 3, j = (t.Axis + 2) % 3;
            ExactPoint3 a = arr.Exact(p), b = arr.Exact(q), c = arr.Exact(r);
            return ExactPoint3.Det3(a[i], a[j], a.W, b[i], b[j], b.W, c[i], c[j], c.W).Sign * t.Sign;
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void ExactStages_MatchReferenceDeterminants(int seed)
        {
            // the exact stages of Orient and InCircle (DisableFilters): the adaptive double predicates for integer
            // points with double coordinates, the 3x3 integer determinant for the others, against the 4x4 / 3x3
            // homogeneous determinants; also nearly and exactly cocircular quadruples (four points of one
            // triangle's segments and corners)
            var arr = Build(seed);
            var rand = new Random(seed);
            int doubles = 0, rationals = 0, zeros = 0, candidates = 0;
            arr.DisableFilters = true;
            foreach (var t in arr.Triangles) {
                if (t.Segments.Count == 0)
                    continue;
                var pts = t.Points.Select(arr.Canonical).Concat(t.Corners.array).Distinct().ToList();
                // (and quadruples of integer points with double coordinates, where the triangle has four)
                var dbl = pts.Where(arr.IsExactDouble).ToList();
                if (dbl.Count >= 4)
                    candidates++;
                for (int k = 0; k < 80; ++k) {
                    var from = (k >= 60 && dbl.Count >= 4) ? dbl : pts;
                    int[] ids = { from[rand.Next(from.Count)], from[rand.Next(from.Count)], from[rand.Next(from.Count)], from[rand.Next(from.Count)] };
                    int expected = ReferenceInCircle(arr, t, ids);
                    Assert.Equal(expected, arr.InCircle(t, ids[0], ids[1], ids[2], ids[3]));
                    Assert.Equal(ReferenceOrient(arr, t, ids[0], ids[1], ids[2]), arr.Orient(t, ids[0], ids[1], ids[2]));
                    if (ids.All(arr.IsExactDouble)) doubles++; else rationals++;
                    if (expected == 0) zeros++;
                }
            }
            arr.DisableFilters = false;
            Assert.True((doubles > 0 || candidates == 0) && rationals > 0 && zeros > 0, $"{doubles} {rationals} {zeros}");
        }

        [Fact]
        public void InCircle_CocircularPoints_BothExactStages()
        {
            // points on a circle of the plane z = 0: integer points (corners of the input, double path) and
            // intersection points with W != 1 on the circle x^2 + y^2 = 25 (3x3 integer path), exactly cocircular
            DMesh3 a = new DMesh3();
            foreach (var v in new[] { new Vector3d(-5, 0, 0), new Vector3d(5, 0, 0), new Vector3d(0, 5, 0), new Vector3d(3, -4, 0) })
                a.AppendVertex(v);
            a.AppendTriangle(0, 1, 2);
            a.AppendTriangle(0, 3, 1);
            var arr = new ExactMeshArrangement(new List<DMesh3>() { a });
            arr.Compute();
            var tri = arr.Triangles[0];
            Func<int, int> pt = (v) => arr.VertexPoints[0][v];
            Assert.True(arr.ScaleExp == 0 && arr.Center.All(c => c.IsZero));
            // rational points on the circle (grid coordinates are the input coordinates here): (5 (q^2 - p^2), 10 p q, 0)
            // / (q^2 + p^2) for p / q = 2 / 3 and 1 / 7, and one just off it
            int r1 = arr.AddPoint(ExactPoint3.Create(5 * (9 - 4), 10 * 6, 0, 9 + 4));
            int r2 = arr.AddPoint(ExactPoint3.Create(5 * (49 - 1), 10 * 7, 0, 49 + 1));
            int off = arr.AddPoint(ExactPoint3.Create(5 * (49 - 1) - 1, 10 * 7, 0, 49 + 1));
            Assert.True(arr.IsExactDouble(pt(0)) && arr.IsExactDouble(pt(3)));
            Assert.False(arr.IsExactDouble(r1));
            foreach (bool disable in new[] { false, true }) {
                arr.DisableFilters = disable;
                Assert.Equal(0, arr.InCircle(tri, pt(0), pt(1), pt(2), pt(3)));
                Assert.Equal(0, arr.InCircle(tri, pt(0), pt(1), pt(2), r1));
                Assert.Equal(0, arr.InCircle(tri, r1, pt(1), r2, pt(0)));
                foreach (int[] ids in new[] { new[] { pt(0), pt(1), pt(2), pt(3) }, new[] { pt(0), pt(1), pt(2), off }, new[] { r1, pt(1), off, pt(0) },
                    new[] { pt(0), pt(1), pt(2), arr.AddPoint(ExactPoint3.FromInteger(0, 0, 0)) }, new[] { pt(0), pt(1), pt(2), arr.AddPoint(ExactPoint3.FromInteger(9, 0, 0)) } })
                    Assert.Equal(ReferenceInCircle(arr, tri, ids), arr.InCircle(tri, ids[0], ids[1], ids[2], ids[3]));
            }
            arr.DisableFilters = false;
            Assert.Equal(1, Math.Abs(arr.InCircle(tri, pt(0), pt(1), pt(2), off)));

            // integer points whose coordinates are not doubles take the integer path: p, 3 p and 0 are collinear,
            // their coordinates rounded to double are not (2^53 + 1 rounds to 2^53, 3 2^53 + 3 to 3 2^53 + 4)
            BigInteger big = (BigInteger.One << 53) + 1;
            int o = arr.AddPoint(ExactPoint3.FromInteger(0, 0, 0)), p1 = arr.AddPoint(ExactPoint3.FromInteger(big, 3, 0)),
                p3 = arr.AddPoint(ExactPoint3.FromInteger(3 * big, 9, 0)), p5 = arr.AddPoint(ExactPoint3.FromInteger(5 * big, 15, 0));
            Assert.True(arr.IsExactDouble(o) && arr.IsExactDouble(p1) == false && arr.IsExactDouble(p3) == false);
            foreach (bool disable in new[] { false, true }) {
                arr.DisableFilters = disable;
                Assert.Equal(0, arr.Orient(tri, o, p1, p3));
                Assert.Equal(0, arr.Orient(tri, p1, p3, p5));
            }
            arr.DisableFilters = false;
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void OutputPoints_AreCanonicalAndDistinct(int seed)
