using System;
using System.Collections.Generic;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The 64-bit integer exact stage of ExactPredicates.Orient3d (orient3d_int, docs/design/CHEAPER_CONSTRUCTIONS.md
    /// section 4.2) against the BigInteger determinant: same sign whenever it admits the input, admission exactly for
    /// coordinate differences below 2^62 units of the lowest set bit, and the public predicate unchanged.
    /// </summary>
    public class ExactOrient3dKernelTests
    {
        static int Kernel(Vector3d a, Vector3d b, Vector3d c, Vector3d d, out bool admitted)
        {
            int s;
            admitted = ExactPredicates.orient3d_int(a, b, c, d, out s);
            return s;
        }

        static void AssertAgrees(Vector3d a, Vector3d b, Vector3d c, Vector3d d, ref int admittedCount)
        {
            int expected = ExactPredicates.orient3d_bigint(a, b, c, d);
            bool admitted;
            int s = Kernel(a, b, c, d, out admitted);
            if (admitted) {
                admittedCount++;
                Assert.True(expected == s, $"kernel {s}, BigInteger {expected}: {a} {b} {c} {d}");
            }
            Assert.Equal(expected, ExactPredicates.Orient3d(a, b, c, d));
            Assert.Equal(expected, ExactPredicates.Orient3dExact(a, b, c, d));
        }

        // m 2^e with |m| < 2^bits (bits <= 53)
        static double Coordinate(Random r, int bits, int e)
        {
            long m = (long)(r.NextDouble() * Math.Pow(2, bits));
            return (r.Next(2) == 0 ? -m : m) * Math.Pow(2, e);
        }

        [Fact]
        public void RandomInputs_SameSignAsBigInteger()
        {
            var r = new Random(1);
            int admitted = 0, n = 200000;
            for (int k = 0; k < n; ++k) {
                // coordinates with mantissas of up to 53 bits at exponents spread over 0..20 above a common unit:
                // differences from a few bits up to beyond the admission limit of 2^62
                int e = r.Next(-60, 60), spread = r.Next(0, 22), bits = r.Next(1, 54);
                var v = new Vector3d[4];
                for (int i = 0; i < 4; ++i)
                    v[i] = new Vector3d(Coordinate(r, bits, e + r.Next(spread)), Coordinate(r, bits, e + r.Next(spread)), Coordinate(r, bits, e + r.Next(spread)));
                AssertAgrees(v[0], v[1], v[2], v[3], ref admitted);
            }
            Assert.True(admitted > n / 2, $"admitted {admitted} of {n}");
        }

        [Fact]
        public void CoplanarFloatInputs_Zero()
        {
            // float coordinates (as CAD meshes have them) on planes with exact float relations: the exact stages of
            // these are the 90 % with result 0 on real inputs
            var r = new Random(2);
            int admitted = 0, n = 50000;
            for (int k = 0; k < n; ++k) {
                float ox = (float)(r.NextDouble() * 200 - 100), oy = (float)(r.NextDouble() * 200 - 100), oz = (float)(r.NextDouble() * 200 - 100);
                var v = new Vector3d[4];
                for (int i = 0; i < 4; ++i) {
                    // points o + s (1, 0, 0.5) + t (0, 1, 0.25) with s, t multiples of 2^-8: exact in float and double
                    double s = r.Next(-4096, 4096) / 256.0, t = r.Next(-4096, 4096) / 256.0;
                    v[i] = new Vector3d((double)ox + s, (double)oy + t, (double)oz + 0.5 * s + 0.25 * t);
                }
                AssertAgrees(v[0], v[1], v[2], v[3], ref admitted);
                if (v[0] != v[1] && v[0] != v[2] && v[0] != v[3] && v[1] != v[2] && v[1] != v[3] && v[2] != v[3])
                    Assert.Equal(0, ExactPredicates.orient3d_bigint(v[0], v[1], v[2], v[3]));
            }
            Assert.True(admitted > n * 9 / 10, $"admitted {admitted} of {n}");
        }

        [Fact]
        public void LargestDifferences_AtTheBound()
        {
            // the unit is 1 (a coordinate 1 or 3); differences up to 2^62 - 2^9 + small are admitted, at 2^62 not.
            // The products of the determinant reach about 6 (2^62)^3, the bound of the 192-bit sum.
            double M = Math.Pow(2, 62) - Math.Pow(2, 9);        // a double: 2^9 (2^53 - 1)
            double[] values = { 0, 1, 3, M, -M, M / 2, -M / 2, Math.Pow(2, 61), -Math.Pow(2, 61) + 512, Math.Pow(2, 62), -Math.Pow(2, 62) };
            var r = new Random(3);
            int admitted = 0, rejected = 0;
            for (int k = 0; k < 200000; ++k) {
                var v = new Vector3d[4];
                for (int i = 0; i < 4; ++i)
                    v[i] = new Vector3d(values[r.Next(values.Length)], values[r.Next(values.Length)], values[r.Next(values.Length)]);
                int before = admitted;
                AssertAgrees(v[0], v[1], v[2], v[3], ref admitted);
                if (admitted == before) rejected++;
            }
            Assert.True(admitted > 10000 && rejected > 10000, $"admitted {admitted}, rejected {rejected}");
            // all twelve differences at the largest admitted magnitude, determinant far from 0
            var a = new Vector3d(0, 0, 1);
            bool adm;
            int s = Kernel(a, new Vector3d(M, -M, 1 + M), new Vector3d(-M, -M, 1 - M), new Vector3d(M, M, 1 - M), out adm);
            Assert.True(adm);
            Assert.Equal(ExactPredicates.orient3d_bigint(a, new Vector3d(M, -M, 1 + M), new Vector3d(-M, -M, 1 - M), new Vector3d(M, M, 1 - M)), s);
            // a difference of 2^62 units is not admitted
            Kernel(a, new Vector3d(Math.Pow(2, 62), 0, 1), new Vector3d(0, 1, 1), new Vector3d(1, 1, 1), out adm);
            Assert.False(adm);
            Kernel(a, new Vector3d(Math.Pow(2, 62) - Math.Pow(2, 10), 0, 1), new Vector3d(0, 1, 1), new Vector3d(1, 1, 1), out adm);
            Assert.True(adm);
        }

        [Fact]
        public void DifferencesNotRepresentable_ExactByTwoDiff()
        {
            // x - y needs more than 53 bits (the low part lo of TwoDiff is nonzero): 2^60 + 1 - (-2^60 ...)
            var r = new Random(4);
            int admitted = 0;
            for (int k = 0; k < 100000; ++k) {
                var v = new Vector3d[4];
                for (int i = 0; i < 4; ++i) {
                    double big = Math.Pow(2, r.Next(40, 61)) * (r.Next(2) == 0 ? 1 : -1);
                    v[i] = new Vector3d(big + r.Next(-1000, 1000) * 64, r.Next(-1000, 1000), (i % 2 == 0) ? big : r.Next(-7, 8));
                }
                AssertAgrees(v[0], v[1], v[2], v[3], ref admitted);
            }
            Assert.True(admitted > 50000, $"admitted {admitted}");
        }

        [Fact]
        public void ExtremeExponents_FallBack()
        {
            bool adm;
            // lowest bit below 2^-1022 (subnormal coordinates): not admitted, the public predicate still exact
            var a = new Vector3d(double.Epsilon, 0, 0);
            var b = new Vector3d(0, double.Epsilon * 3, 0);
            var c = new Vector3d(0, 0, double.Epsilon * 5);
            var d = new Vector3d(double.Epsilon * 7, double.Epsilon * 9, double.Epsilon);
            Kernel(a, b, c, d, out adm);
            Assert.False(adm);
            Assert.Equal(ExactPredicates.orient3d_bigint(a, b, c, d), ExactPredicates.Orient3dExact(a, b, c, d));
            // lowest bit 2^-1022: admitted
            double u = Math.Pow(2, -1022);
            Assert.Equal(ExactPredicates.orient3d_bigint(new Vector3d(u, 0, 0), new Vector3d(0, 3 * u, 0), new Vector3d(0, 0, 5 * u), new Vector3d(7 * u, 9 * u, u)),
                Kernel(new Vector3d(u, 0, 0), new Vector3d(0, 3 * u, 0), new Vector3d(0, 0, 5 * u), new Vector3d(7 * u, 9 * u, u), out adm));
            Assert.True(adm);
            // huge coordinates: lowest bit 2^1000, admitted; a difference that overflows is not
            double h = Math.Pow(2, 1000);
            Assert.Equal(ExactPredicates.orient3d_bigint(new Vector3d(h, 0, 0), new Vector3d(0, 3 * h, 0), new Vector3d(0, 0, 5 * h), new Vector3d(7 * h, -9 * h, h)),
                Kernel(new Vector3d(h, 0, 0), new Vector3d(0, 3 * h, 0), new Vector3d(0, 0, 5 * h), new Vector3d(7 * h, -9 * h, h), out adm));
            Assert.True(adm);
            Kernel(new Vector3d(double.MaxValue, 0, 0), new Vector3d(-double.MaxValue, 0, 0), new Vector3d(0, 1, 0), new Vector3d(0, 0, 1), out adm);
            Assert.False(adm);
            // lowest bit 2^1023: 2^-1023 would be subnormal, not admitted
            double g = Math.Pow(2, 1023);
            Kernel(new Vector3d(g, 0, 0), new Vector3d(0, g, 0), new Vector3d(0, 0, g), new Vector3d(-g, -g, g), out adm);
            Assert.False(adm);
            Assert.Equal(ExactPredicates.orient3d_bigint(new Vector3d(g, 0, 0), new Vector3d(0, g, 0), new Vector3d(0, 0, g), new Vector3d(-g, -g, g)),
                ExactPredicates.Orient3dExact(new Vector3d(g, 0, 0), new Vector3d(0, g, 0), new Vector3d(0, 0, g), new Vector3d(-g, -g, g)));
        }

        [Fact]
        public void Invariance_Pow2ScalesGiveTheSameResult()
        {
            // the 2^k scales move only the common exponent: admission and sign are the same bit for bit; the other
            // similarities change the coordinates, so the kernel is compared with the BigInteger determinant there
            var r = new Random(5);
            var inputs = new List<Vector3d[]>();
            for (int k = 0; k < 20000; ++k) {
                float ox = (float)(r.NextDouble() * 200 - 100), oy = (float)(r.NextDouble() * 200 - 100);
                var v = new Vector3d[4];
                for (int i = 0; i < 4; ++i) {
                    double s = r.Next(-4096, 4096) / 256.0, t = r.Next(-4096, 4096) / 256.0;
                    v[i] = new Vector3d(ox + s, oy + t, 0.5 * s + 0.25 * t + ((k % 3 == 0 && i == 3) ? Math.Pow(2, -20) : 0));
                }
                inputs.Add(v);
            }
            foreach (Similarity sim in Similarity.All()) {
                int admittedCount = 0;
                foreach (Vector3d[] v in inputs) {
                    Vector3d a = sim.Apply(v[0]), b = sim.Apply(v[1]), c = sim.Apply(v[2]), d = sim.Apply(v[3]);
                    if (sim.IsExact) {
                        bool adm0, adm1;
                        int s0 = Kernel(v[0], v[1], v[2], v[3], out adm0), s1 = Kernel(a, b, c, d, out adm1);
                        Assert.Equal(adm0, adm1);
                        Assert.Equal(s0, s1);
                        Assert.Equal(ExactPredicates.Orient3d(v[0], v[1], v[2], v[3]), ExactPredicates.Orient3d(a, b, c, d));
                    }
                    AssertAgrees(a, b, c, d, ref admittedCount);
                }
            }
        }

        [Fact]
        public void TrailingZerosPortable_MatchesBitOperations()
        {
            var r = new Random(6);
            for (int k = 0; k < 64; ++k)
                Assert.Equal(k, ExactPredicates.TrailingZerosPortable(1UL << k));
            for (int k = 0; k < 100000; ++k) {
                ulong v = ((ulong)(uint)r.Next() << 32 | (uint)r.Next()) << r.Next(64);
                if (v == 0) continue;
                // the lowest set bit, isolated: v & -v = 2^tz
                ulong low = v & (~v + 1);
                int expected = 0;
                while ((1UL << expected) != low) expected++;
                Assert.Equal(expected, ExactPredicates.TrailingZerosPortable(v));
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;
using Ops = g3.ExactMeshBoolean.Operations;

namespace geometry3Sharp.Tests
{
    // ExactMeshBoolean.SimplifyFlatRegions: new vertices inside flat regions and on straight edges are removed
    public class ExactPlanarSimplifyTests
    {
        static DMesh3 Box(double x0, double y0, double z0, double x1, double y1, double z1)
        {
            var m = new DMesh3();
            for (int i = 0; i < 8; ++i)
                m.AppendVertex(new Vector3d((i & 1) == 0 ? x0 : x1, (i & 2) == 0 ? y0 : y1, (i & 4) == 0 ? z0 : z1));
            int[][] quads = { new[] { 0, 2, 3, 1 }, new[] { 4, 5, 7, 6 }, new[] { 0, 1, 5, 4 }, new[] { 2, 6, 7, 3 }, new[] { 0, 4, 6, 2 }, new[] { 1, 3, 7, 5 } };
            foreach (int[] q in quads) {
                m.AppendTriangle(q[0], q[1], q[2]);
                m.AppendTriangle(q[0], q[2], q[3]);
            }
            return m;
        }

        static double Volume(DMesh3 mesh)
        {
            return MeshMeasurements.VolumeArea(mesh, mesh.TriangleIndices(), mesh.GetVertex).x;
        }

        static DMesh3 Run(DMesh3 a, DMesh3 b, Ops op, bool simplify = true)
        {
            var boolean = new ExactMeshBoolean(a, b, op) { SimplifyFlatRegions = simplify };
            Assert.True(boolean.Compute(), boolean.Error);
            DMesh3 r = boolean.Result;
            Assert.True(r.CheckValidity(true, FailMode.ReturnOnly), "invalid mesh");
            if (r.TriangleCount > 0)
                Assert.True(r.IsClosed(), $"{op}: {MeshIterators.BoundaryEdges(r).Count()} boundary edges");
            Assert.Equal(0, boolean.NonManifoldTriangles);
            return r;
        }

        // every vertex coordinate is one of the input coordinates (no rounded intersection points)
        static void AssertInputCoordinates(DMesh3 m, IEnumerable<double> values)
        {
            var set = new HashSet<double>(values);
            foreach (Vector3d v in m.Vertices())
                for (int k = 0; k < 3; ++k)
                    Assert.True(set.Contains(v[k]), $"vertex {v.x:R} {v.y:R} {v.z:R} is not an input coordinate");
        }

        [Fact]
        public void CubeColumn_CoplanarOverlap_OnlyInputCoordinates()
        {
            // the side faces overlap in the same planes: their diagonals cross at points that are not needed
            DMesh3 cur = Box(0, 0, 0, 1, 1, 1);
            foreach (double z in new[] { 0.9, 1.8 })
                cur = Run(cur, Box(0, 0, z, 1, 1, z + 1), Ops.Union);
            AssertInputCoordinates(cur, new[] { 0, 1, 0.9, 1.9, 1.8, 2.8 });
            Assert.Equal(2.8, Volume(cur), 12);
            Assert.Equal(0, MeshRepairMetrics.SelfIntersections(cur));
            // the box with the input corners on its vertical edges: 4 x 6 vertices on the side edges
            Assert.True(cur.VertexCount <= 24, $"{cur.VertexCount} vertices");
        }

        [Fact]
        public void CubeGrid_IteratedUnions_DoNotGrow()
        {
            // 3 x 3 x 3 overlapping cubes united one after the other: without the simplification the rounded
            // crossing points are split again by every following union and the triangle count explodes
            int n = 3;
            var coords = new List<double>();
            for (int i = 0; i < n; ++i) {
                coords.Add(0.9 * i);
                coords.Add(0.9 * i + 1);
            }
            DMesh3 cur = null;
            var counts = new List<int>();
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j)
                    for (int k = 0; k < n; ++k) {
                        DMesh3 c = Box(0.9 * i, 0.9 * j, 0.9 * k, 0.9 * i + 1, 0.9 * j + 1, 0.9 * k + 1);
                        cur = (cur == null) ? c : Run(cur, c, Ops.Union);
                        counts.Add(cur.TriangleCount);
                    }
            AssertInputCoordinates(cur, coords);
            double side = 0.9 * (n - 1) + 1;
            Assert.Equal(side * side * side, Volume(cur), 9);
            Assert.Equal(0, MeshRepairMetrics.SelfIntersections(cur));
            // at most the input corners on the faces of the box (2n - 1 values per coordinate)
            int perSide = 2 * n;
            Assert.True(cur.VertexCount <= 6 * perSide * perSide, $"{cur.VertexCount} vertices");
            Assert.True(cur.TriangleCount <= 2 * cur.VertexCount, $"{cur.TriangleCount} triangles");
        }

        [Fact]
        public void StraightEdge_CrossingPointRemoved()
        {
            // the boxes' front faces (y = 0) overlap, the diagonal of one crosses the bottom edge region of the
            // other: crossing points on the straight edges of the union are removed, the input corners stay
            DMesh3 a = Box(0, 0, 0, 2, 1, 1), b = Box(1, 0, 0.5, 3, 1, 1.5);
            DMesh3 off = Run(a, b, Ops.Union, simplify: false), on = Run(a, b, Ops.Union);
            Assert.Equal(Volume(off), Volume(on), 12);
            AssertInputCoordinates(on, new[] { 0, 1, 2, 3, 0.5, 1.5 });
            Assert.True(on.TriangleCount < off.TriangleCount);
            Assert.Equal(0, MeshRepairMetrics.SelfIntersections(on));
            Assert.Equal(1 * 2 * 1 + 2 * 1 * 1 - 1 * 1 * 0.5, Volume(on), 12);
        }

        [Fact]
        public void AllOperations_SameVolumeAsWithoutSimplification()
        {
            var rand = new Random(5);
            for (int iter = 0; iter < 20; ++iter) {
                // boxes on a coarse grid: many coplanar faces and collinear edges, some touching
                Func<double> r = () => rand.Next(0, 5) * 0.3;
                DMesh3 a = Box(r(), r(), r(), 1.5 + r(), 1.5 + r(), 1.5 + r());
                DMesh3 b = Box(r(), r(), r(), 1.5 + r(), 1.5 + r(), 1.5 + r());
                foreach (Ops op in new[] { Ops.Union, Ops.Intersection, Ops.Difference }) {
                    var boolean = new ExactMeshBoolean(a, b, op);
                    Assert.True(boolean.Compute());
                    var plain = new ExactMeshBoolean(a, b, op) { SimplifyFlatRegions = false };
                    Assert.True(plain.Compute());
                    Assert.Equal(Volume(plain.Result), Volume(boolean.Result), 9);
                    Assert.True(boolean.Result.TriangleCount <= plain.Result.TriangleCount);
                    if (boolean.Result.TriangleCount > 0)
                        Assert.Equal(plain.Result.IsClosed(), boolean.Result.IsClosed());
                    Assert.Equal(0, MeshRepairMetrics.SelfIntersections(boolean.Result));
                }
            }
        }

        [Fact]
        public void CurvedMeshes_InputVerticesKept()
        {
            // no flat regions with new points: the input vertices that are on the result are all kept
            DMesh3 a = new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = 10 }.Generate().MakeDMesh();
            DMesh3 b = new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = 10 }.Generate().MakeDMesh();
            MeshTransforms.Translate(b, new Vector3d(0.7, 0.2, 0.1));
            DMesh3 off = Run(a, b, Ops.Union, simplify: false), on = Run(a, b, Ops.Union);
            Assert.Equal(Volume(off), Volume(on), 12);
            var verts = new HashSet<Vector3d>(on.Vertices());
            foreach (DMesh3 m in new[] { a, b })
                foreach (Vector3d v in m.Vertices())
                    if (off.Vertices().Contains(v))
                        Assert.Contains(v, verts);
        }

        // A box standing on the top face of a larger one, turned by 45 degrees so that its bottom edges cross the top
        // edges of the larger box: the difference is the larger box, and all the crossing points (on the top face
        // and on its edges between the top and the sides) are removed again. The top face gets triangles from both
        // inputs, whose planes have opposite normals (the bottom of the small box, flipped): one region.
        [Fact]
        public void Difference_BoxStandingOnTheTop_IsTheBox()
        {
            DMesh3 a = Box(0, 0, 0, 2, 2, 1);
            DMesh3 b = Box(-1.2, -1.2, 1, 1.2, 1.2, 2);
            MeshTransforms.Rotate(b, Vector3d.Zero, new Quaterniond(Vector3d.AxisZ, 45));
            MeshTransforms.Translate(b, new Vector3d(1, 1, 0));
            // (the corners of b are outside the top face, its edges cross the face's edges)
            Assert.True(b.Vertices().All(v => v.x < 0 || v.x > 2 || v.y < 0 || v.y > 2));
            var boolean = new ExactMeshBoolean(a, b, Ops.Difference);
            Assert.True(boolean.Compute(), boolean.Error);
            DMesh3 r = boolean.Result;
            var plain = new ExactMeshBoolean(a, b, Ops.Difference) { SimplifyFlatRegions = false };
            Assert.True(plain.Compute());
            Assert.True(plain.Result.VertexCount > 8, "the case has no points to remove");
            Assert.Equal(plain.Result.VertexCount - 8, boolean.RemovedVertices);
            Assert.Equal(8, r.VertexCount);
            Assert.Equal(12, r.TriangleCount);
            Assert.True(r.IsClosed());
            Assert.Equal(4.0, Volume(r), 12);
            AssertInputCoordinates(r, new[] { 0.0, 1, 2 });
        }

        // the triangles of each flat region of the simplified result are (nearly) Delaunay: the point opposite an edge
        // inside a region is not inside the circumcircle of the triangle on the other side (relative margin 1e-9,
        // below which the simplification leaves nearly cocircular cases as they are). Only for results where every
        // region was retriangulated: the flips start at the new triangles, and triangles of the arrangement that no
        // removal touches stay as they are (on random boxes, eg, some are not Delaunay).
        static void AssertFlatRegionsDelaunay(DMesh3 m)
        {
            int checkedEdges = 0;
            foreach (int e in m.EdgeIndices()) {
                Index2i et = m.GetEdgeT(e);
                if (et.b == DMesh3.InvalidID || m.GetTriNormal(et.a).Distance(m.GetTriNormal(et.b)) > 1e-9)
                    continue;
                Index2i ev = m.GetEdgeV(e);
                Index2i ov = m.GetEdgeOpposingV(e);
                Vector3d a = m.GetVertex(ev.a), b = m.GetVertex(ev.b), p = m.GetVertex(ov.a), q = m.GetVertex(ov.b);
                // circumcentre of a, b, p in their plane
                Vector3d ab = b - a, ap = p - a, n = ab.Cross(ap);
                Vector3d ctr = a + (ap.LengthSquared * n.Cross(ab) + ab.LengthSquared * ap.Cross(n)) / (2 * n.LengthSquared);
                double rad = ctr.Distance(a);
                Assert.True(ctr.Distance(q) >= rad * (1 - 1e-9), $"edge {a}-{b} (p {p}, q {q}): opposite point {(rad - ctr.Distance(q)) / rad:E2} inside the circumcircle");
                checkedEdges++;
            }
            Assert.True(checkedEdges > 0);
        }

        [Fact]
        public void Simplified_FlatRegionsAreDelaunay()
        {
            DMesh3 cur = Box(0, 0, 0, 1, 1, 1);
            foreach (double z in new[] { 0.9, 1.8 })
                cur = Run(cur, Box(0, 0, z, 1, 1, z + 1), Ops.Union);
            AssertFlatRegionsDelaunay(cur);
            AssertFlatRegionsDelaunay(Run(Box(0, 0, 0, 2, 1, 1), Box(1, 0, 0.5, 3, 1, 1.5), Ops.Union));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Numerics;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The triangle planes of ExactMeshArrangement in fixed width (FixedArith.TrianglePlanes, docs/design/
    /// CHEAPER_CONSTRUCTIONS.md section 4.5) against the BigInteger code: the same plane, axis, sign and the same 16
    /// approximations, for corners of every size up to the FixedPoint3 limit; the limb -> double conversion against
    /// (double)BigInteger.
    /// </summary>
    public unsafe class ExactPlanesFixedWidthTests
    {
        static BigInteger RandomValue(Random r, int bits)
        {
            if (bits == 0) return BigInteger.Zero;
            var b = new byte[bits / 8 + 2];
            r.NextBytes(b);
            b[b.Length - 1] = 0;
            BigInteger v = new BigInteger(b) >> (8 * b.Length - 8 - bits);
            return (r.Next(2) == 0) ? -v : v;
        }

        static FixedInt Load(BigInteger v, ulong* buf, int limbs)
        {
            int len;
            bool neg;
            Assert.True(FixedPoint3.LoadN(v, buf, limbs, out len, out neg));
            return new FixedInt(buf, len, neg);
        }

        [Fact]
        public void ToDouble_SameAsBigIntegerConversion()
        {
            var r = new Random(1);
            ulong* buf = stackalloc ulong[8];
            for (int k = 0; k < 200000; ++k) {
                BigInteger v = RandomValue(r, r.Next(0, 8 * 64 - 1));
                if (k % 7 == 0) v = (BigInteger.One << r.Next(0, 510)) * (r.Next(2) == 0 ? 1 : -1) - r.Next(-2, 3);
                if (BigInteger.Abs(v) >= BigInteger.One << 511) continue;
                double got = FixedArith.ToDouble(Load(v, buf, 8));
                double expected = (double)v;
#if NET
                Assert.Equal(BitConverter.DoubleToInt64Bits(expected), BitConverter.DoubleToInt64Bits(got));
#else
                // (.NET Framework's conversion may round differently: the filters need a relative error below 2^-52)
                Assert.True(Math.Abs(got - expected) <= Math.Abs(expected) * Math.Pow(2, -52));
#endif
            }
        }

        [Fact]
        public void ToDouble_BeyondTheDoubleRange_Infinite()
        {
            // 17-limb values (the edge planes' F of 4-limb corners reach 1027 bits)
            var r = new Random(2);
            ulong* buf = stackalloc ulong[20];
            foreach (int bits in new[] { 1023, 1024, 1025, 1030, 1087 }) {
                for (int k = 0; k < 100; ++k) {
                    BigInteger v = (BigInteger.One << (bits - 1)) + BigInteger.Abs(RandomValue(r, bits - 2));
                    if (k % 2 == 1) v = -v;
                    int limbs = 17;
                    // (LoadN takes at most 8 limbs: the magnitude by hand)
                    BigInteger m = BigInteger.Abs(v);
                    int n = 0;
                    while (m.IsZero == false) { buf[n++] = (ulong)(m & ulong.MaxValue); m >>= 64; }
                    Assert.True(n <= limbs);
                    double got = FixedArith.ToDouble(new FixedInt(buf, n, v.Sign < 0));
#if NET
                    Assert.Equal(BitConverter.DoubleToInt64Bits((double)v), BitConverter.DoubleToInt64Bits(got));
#else
                    double e = (double)v;
                    Assert.True(double.IsInfinity(e) == double.IsInfinity(got) && (double.IsInfinity(e) || Math.Abs(got - e) <= Math.Abs(e) * Math.Pow(2, -52)));
#endif
                }
            }
        }

        [Fact]
        public void LeadingZerosPortable_Matches()
        {
            var r = new Random(3);
            for (int k = 0; k < 64; ++k)
                Assert.Equal(63 - k, FixedArith.LeadingZerosPortable(1UL << k));
            for (int k = 0; k < 100000; ++k) {
                ulong v = ((ulong)(uint)r.Next() << 32 | (uint)r.Next()) >> r.Next(64);
                if (v == 0) continue;
                int expected = 0;
                while ((v >> (63 - expected)) == 0) expected++;
                Assert.Equal(expected, FixedArith.LeadingZerosPortable(v));
            }
        }

        // compute_planes's BigInteger code (the reference)
        static void Reference(ExactPoint3 a, ExactPoint3 b, ExactPoint3 c, double[] pa, out BigInteger[] plane, out int axis, out int sign)
        {
            BigInteger ux = b.X - a.X, uy = b.Y - a.Y, uz = b.Z - a.Z;
            BigInteger vx = c.X - a.X, vy = c.Y - a.Y, vz = c.Z - a.Z;
            BigInteger nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
            plane = new[] { nx, ny, nz, nx * a.X + ny * a.Y + nz * a.Z };
            BigInteger ax = BigInteger.Abs(nx), ay = BigInteger.Abs(ny), az = BigInteger.Abs(nz);
            axis = (ax >= ay && ax >= az) ? 0 : (ay >= az) ? 1 : 2;
            sign = ((axis == 0) ? nx : (axis == 1) ? ny : nz).Sign;
            var corners = new[] { a, b, c };
            for (int k = 0; k < 4; ++k) pa[k] = (double)plane[k];
            for (int k = 0; k < 3; ++k) {
                ExactPoint3 p = corners[k], q = corners[(k + 1) % 3];
                BigInteger dx = q.X - p.X, dy = q.Y - p.Y, dz = q.Z - p.Z;
                BigInteger ex = dy * nz - dz * ny, ey = dz * nx - dx * nz, ez = dx * ny - dy * nx;
                BigInteger f = ex * p.X + ey * p.Y + ez * p.Z;
                pa[4 * k + 4] = (double)ex; pa[4 * k + 5] = (double)ey; pa[4 * k + 6] = (double)ez; pa[4 * k + 7] = (double)f;
            }
        }

        [Fact]
        public void TrianglePlanes_SameAsBigInteger()
        {
            var r = new Random(4);
            BigInteger max = (BigInteger.One << 255) - 1;
            for (int k = 0; k < 20000; ++k) {
                int bits = (k % 5 == 0) ? 255 : r.Next(0, 256);
                var pts = new ExactPoint3[3];
                for (int i = 0; i < 3; ++i) {
                    if (k % 97 == 0)
                        pts[i] = ExactPoint3.FromInteger(r.Next(2) == 0 ? max : -max, r.Next(2) == 0 ? max : -max, r.Next(2) == 0 ? max : -max);
                    else
                        // (the corners of one triangle with different lengths too: 1-limb next to 4-limb ones)
                        pts[i] = ExactPoint3.FromInteger(RandomValue(r, bits), RandomValue(r, r.Next(0, bits + 1)), RandomValue(r, (k % 3 == 0) ? r.Next(0, 256) : bits));
                }
                if (k % 11 == 0) pts[2] = pts[0];      // a degenerate triple: N = 0
                FixedPoint3 fa, fb, fc;
                Assert.True(FixedPoint3.TryCreate(pts[0], out fa));
                Assert.True(FixedPoint3.TryCreate(pts[1], out fb));
                Assert.True(FixedPoint3.TryCreate(pts[2], out fc));
                var got = new double[16];
                BigInteger nx, ny, nz, d;
                int axis, sign;
                FixedArith.TrianglePlanes(ref fa, ref fb, ref fc, got, out nx, out ny, out nz, out d, out axis, out sign);
                var expected = new double[16];
                BigInteger[] plane;
                int eaxis, esign;
                Reference(pts[0], pts[1], pts[2], expected, out plane, out eaxis, out esign);
                Assert.Equal(plane[0], nx); Assert.Equal(plane[1], ny); Assert.Equal(plane[2], nz); Assert.Equal(plane[3], d);
                Assert.Equal(eaxis, axis); Assert.Equal(esign, sign);
                for (int i = 0; i < 16; ++i) {
#if NET
                    Assert.Equal(BitConverter.DoubleToInt64Bits(expected[i]), BitConverter.DoubleToInt64Bits(got[i]));
#else
                    Assert.True(double.IsInfinity(expected[i]) == double.IsInfinity(got[i]) && (double.IsInfinity(got[i]) || Math.Abs(got[i] - expected[i]) <= Math.Abs(expected[i]) * Math.Pow(2, -52)));
#endif
                }
            }
        }

        static DMesh3 Sphere(Vector3d center, double radius, int edgeVertices)
        {
            DMesh3 s = new Sphere3Generator_NormalizedCube() { Radius = radius, EdgeVertices = edgeVertices }.Generate().MakeDMesh();
            MeshTransforms.Translate(s, center);
            return s;
        }

        // the planes of every triangle of the arrangement of two meshes, as a string (exact plane, axis, sign, approximations)
        static string Planes(List<DMesh3> meshes, bool fixedWidth)
        {
            var arr = new ExactMeshArrangement(meshes) { FixedWidthPoints = fixedWidth };
            arr.Compute();
            var sb = new System.Text.StringBuilder();
            foreach (var t in arr.Triangles) {
                if (t.Degenerate) continue;
                var p = t.P;
                sb.Append(p.A).Append(',').Append(p.B).Append(',').Append(p.C).Append(',').Append(p.D).Append(';').Append(t.Axis).Append(t.Sign);
                foreach (double x in t.PlaneApprox) sb.Append(',').Append(BitConverter.DoubleToInt64Bits(x));
                sb.Append('\n');
            }
            return sb.ToString();
        }

        [Fact]
        public void Arrangement_TakesTheFixedWidthPath()
        {
            // every non-degenerate input triangle (integer corners, all fixed width) gets its plane by FixedArith
            var arr = new ExactMeshArrangement(new List<DMesh3> { Sphere(new Vector3d(0.1, 0.2, 0.3), 1, 5), Sphere(new Vector3d(0.7, 0.4, 0.1), 0.8, 4) });
            arr.Compute();
            int n = 0;
            foreach (var t in arr.Triangles)
                if (t.Degenerate == false) {
                    Assert.NotNull(t.compute_planes_fixed());
                    n++;
                }
            Assert.True(n > 100);
            // and with fixed width off, never
            var off = new ExactMeshArrangement(new List<DMesh3> { Sphere(new Vector3d(0.1, 0.2, 0.3), 1, 5) }) { FixedWidthPoints = false };
            off.Compute();
            foreach (var t in off.Triangles)
                if (t.Degenerate == false)
                    Assert.Null(t.compute_planes_fixed());
        }

        [Fact]
        public void Arrangement_SamePlanesWithoutFixedWidth()
        {
            var meshes = new List<DMesh3> { Sphere(new Vector3d(0.1, 0.2, 0.3), 1, 6), Sphere(new Vector3d(0.7, 0.4, 0.1), 0.8, 5) };
            Assert.Equal(Planes(meshes, false), Planes(meshes, true));
        }

        [Fact]
        public void Invariance_Pow2ScalesGiveTheSamePlanes()
        {
            // the grid integers do not change under 2^k scales, so neither do the planes; under the other
            // similarities the planes are those of the transformed input, compared with the BigInteger code
            var baseMeshes = new List<DMesh3> { Sphere(new Vector3d(0.1, 0.2, 0.3), 1, 5), Sphere(new Vector3d(0.7, 0.4, 0.1), 0.8, 4) };
            string reference = Planes(baseMeshes, true);
            foreach (Similarity sim in Similarity.All()) {
                var meshes = new List<DMesh3>();
                foreach (DMesh3 m0 in baseMeshes) {
                    var m = new DMesh3(m0);
                    foreach (int vid in m.VertexIndices())
                        m.SetVertex(vid, sim.Apply(m.GetVertex(vid)));
                    meshes.Add(m);
                }
                string planes = Planes(meshes, true);
                Assert.Equal(Planes(meshes, false), planes);
                if (sim.IsExact)
                    Assert.Equal(reference, planes);
            }
        }
    }
}

using System;
using System.Numerics;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The conversions of ExactPoint3 to and from doubles, checked exactly in integer arithmetic over the whole double
    /// range (subnormal results, overflow, negative values, quotients of very different sizes). Mutation testing
    /// (tests/mutation) showed that the earlier tests reached ToDouble, ScaleB and ApproxVector3d only with values
    /// near 1.
    /// </summary>
    public class ExactPoint3ConversionTests
    {
        // |r - num / den * 2^s| <= 1 ulp of r (and r has the sign of num), checked exactly
        static void AssertWithinOneUlp(double r, BigInteger num, BigInteger den, int s, string what)
        {
            Assert.False(double.IsNaN(r), what);
            if (double.IsInfinity(r)) {
                // only beyond the double range: |num / den * 2^s| >= 2^1024 - 2^970 (the largest double plus half an
                // ulp, (2^53 - 1) 2^971 + 2^970 = (2^54 - 1) 2^970)
                Assert.Equal(num.Sign, Math.Sign(r));
                Assert.True(Compare(BigInteger.Abs(num), den, s, (BigInteger.One << 54) - 1, 970) >= 0, what + ": infinity below the double range");
                return;
            }
            Assert.True(r == 0 || Math.Sign(r) == num.Sign, what + ": sign");
            BigInteger m; int e;
            ExactPoint3.Decompose(r, out m, out e);
            // ulp of r: 2^(exponent - 52), at least 2^-1074
            int biased = (int)((BitConverter.DoubleToInt64Bits(r) >> 52) & 0x7FF);
            int ulpExp = (biased == 0) ? -1074 : biased - 1023 - 52;
            // |m 2^e den - num 2^s| <= 2^ulpExp den, all at the common exponent k
            int k = Math.Min(Math.Min(e, s), ulpExp);
            BigInteger lhs = BigInteger.Abs((m << (e - k)) * den - (num << (s - k)));
            BigInteger rhs = den << (ulpExp - k);
            Assert.True(lhs <= rhs, what + $": {r:R} is more than 1 ulp from the exact value");
        }

        // sign of |num| / den * 2^s - a * 2^b
        static int Compare(BigInteger num, BigInteger den, int s, BigInteger a, int b)
        {
            int k = Math.Min(s, b);
            return BigInteger.Compare(num << (s - k), (a * den) << (b - k));
        }

        static BigInteger RandomBig(Random rnd, int bits)
        {
            byte[] bytes = new byte[bits / 8 + 2];
            rnd.NextBytes(bytes);
            bytes[bytes.Length - 1] = 0;        // positive
            BigInteger v = new BigInteger(bytes) >> (8 * bytes.Length - 8 - bits);
            return v.IsZero ? BigInteger.One : v;
        }

        [Fact]
        public void ToDouble_WithinOneUlp_OverTheWholeRange()
        {
            var rnd = new Random(5);
            for (int i = 0; i < 20000; ++i) {
                BigInteger num = RandomBig(rnd, 1 + rnd.Next(400));
                BigInteger den = RandomBig(rnd, 1 + rnd.Next(400));
                if (rnd.Next(2) == 0) num = -num;
                // scales that put the result anywhere from below the subnormal range to beyond the double range
                int s = rnd.Next(-1500, 1500);
                double r = ExactPoint3.ToDouble(num, den, s);
                AssertWithinOneUlp(r, num, den, s, $"case {i}: {num} / {den} * 2^{s}");
            }
        }

        [Fact]
        public void ToDouble_SmallAndExactQuotients()
        {
            Assert.Equal(0.0, ExactPoint3.ToDouble(BigInteger.Zero, 7, 100));
            Assert.Equal(0.375, ExactPoint3.ToDouble(3, 8, 0));
            Assert.Equal(-0.375, ExactPoint3.ToDouble(-3, 8, 0));
            Assert.Equal(1.5 * Math.Pow(2, 900), ExactPoint3.ToDouble(3, 2, 900));
            Assert.Equal(double.Epsilon, ExactPoint3.ToDouble(BigInteger.One, BigInteger.One, -1074));
            Assert.Equal(-double.Epsilon, ExactPoint3.ToDouble(BigInteger.MinusOne, BigInteger.One, -1074));
            // the numerator much longer than the denominator (negative shift)
            BigInteger big = BigInteger.Pow(3, 300);
            AssertWithinOneUlp(ExactPoint3.ToDouble(big, 7, -400), big, 7, -400, "3^300 / 7");
        }

        [Fact]
        public void ScaleB_MatchesExactScaling()
        {
            var rnd = new Random(8);
            for (int i = 0; i < 20000; ++i) {
                // normal and subnormal inputs, both signs
                double x = (rnd.NextDouble() + 0.5) * Math.Pow(2, rnd.Next(-1074, 1000));
                if (rnd.Next(2) == 0) x = -x;
                int n = rnd.Next(-2200, 2200);
                double r = ExactPoint3.ScaleB(x, n);
                BigInteger m; int e;
                ExactPoint3.Decompose(x, out m, out e);
                AssertWithinOneUlp(r, m, BigInteger.One, e + n, $"case {i}: {x:R} * 2^{n}");
#if NETCOREAPP
                Assert.Equal(Math.ScaleB(x, n), r);       // correctly rounded, like the runtime
#endif
            }
        }

        [Fact]
        public void ScaleB_SpecialValuesAndSignOfZero()
        {
            Assert.Equal(0.0, ExactPoint3.ScaleB(0.0, 50));
            Assert.True(double.IsNaN(ExactPoint3.ScaleB(double.NaN, 3)));
            Assert.Equal(double.PositiveInfinity, ExactPoint3.ScaleB(double.PositiveInfinity, -3));
            Assert.Equal(double.PositiveInfinity, ExactPoint3.ScaleB(1.5, 1024));
            Assert.Equal(double.NegativeInfinity, ExactPoint3.ScaleB(-1.5, 1024));
            // below half the smallest subnormal: zero with the sign of x
            double negZero = ExactPoint3.ScaleB(-1.0, -1100);
            Assert.Equal(0.0, negZero);
            Assert.True(BitConverter.DoubleToInt64Bits(negZero) < 0, "-0.0 expected");
            Assert.True(BitConverter.DoubleToInt64Bits(ExactPoint3.ScaleB(1.0, -1100)) == 0, "+0.0 expected");
            // a subnormal input scaled up, and down again
            Assert.Equal(1.0, ExactPoint3.ScaleB(double.Epsilon, 1074));
            Assert.Equal(double.Epsilon, ExactPoint3.ScaleB(1.0, -1074));
            Assert.Equal(-4 * double.Epsilon, ExactPoint3.ScaleB(-double.Epsilon, 2));
        }

        [Fact]
        public void BitLength_MatchesTheDefinition()
        {
            var rnd = new Random(9);
            Assert.Equal(0, ExactPoint3.BitLength(BigInteger.Zero));
            Assert.Equal(1, ExactPoint3.BitLength(BigInteger.One));
            Assert.Equal(1, ExactPoint3.BitLength(BigInteger.MinusOne));
            for (int bits = 1; bits < 300; ++bits) {
                BigInteger lo = BigInteger.One << (bits - 1), hi = (BigInteger.One << bits) - 1;
                Assert.Equal(bits, ExactPoint3.BitLength(lo));
                Assert.Equal(bits, ExactPoint3.BitLength(hi));
                Assert.Equal(bits, ExactPoint3.BitLength(-hi));
                Assert.Equal(bits, ExactPoint3.BitLength(RandomBig(rnd, bits) | lo));
            }
        }

        [Fact]
        public void Decompose_IsExactWithAnOddMantissa()
        {
            var rnd = new Random(10);
            for (int i = 0; i < 5000; ++i) {
                double v = (rnd.NextDouble() - 0.5) * Math.Pow(2, rnd.Next(-1074, 1020));
                BigInteger m; int e;
                ExactPoint3.Decompose(v, out m, out e);
                if (v == 0) { Assert.True(m.IsZero && e == 0); continue; }
                Assert.False(m.IsEven, $"{v:R}: mantissa {m} is even");
                Assert.Equal(Math.Sign(v), m.Sign);
                Assert.Equal(v, ExactPoint3.ScaleB((double)m, e));       // m has at most 53 bits: exact
            }
            BigInteger m0; int e0;
            ExactPoint3.Decompose(-0.0, out m0, out e0);
            Assert.True(m0.IsZero && e0 == 0);
            Assert.Throws<ArgumentException>(() => ExactPoint3.Decompose(double.NaN, out m0, out e0));
            Assert.Throws<ArgumentException>(() => ExactPoint3.Decompose(double.NegativeInfinity, out m0, out e0));
        }

        [Fact]
        public void Create_NormalizesTheSignOfW_AndRejectsZero()
        {
            ExactPoint3 p = ExactPoint3.Create(2, -4, 6, -8);
            Assert.Equal(new BigInteger(-1), p.X);
            Assert.Equal(new BigInteger(2), p.Y);
            Assert.Equal(new BigInteger(-3), p.Z);
            Assert.Equal(new BigInteger(4), p.W);
            ExactPoint3 q = ExactPoint3.CreateUnreduced(2, -4, 6, -8);
            Assert.Equal(new BigInteger(-2), q.X);
            Assert.Equal(new BigInteger(8), q.W);
            Assert.Throws<ArgumentException>(() => ExactPoint3.Create(1, 2, 3, BigInteger.Zero));
            Assert.Throws<ArgumentException>(() => ExactPoint3.CreateUnreduced(1, 2, 3, BigInteger.Zero));
            Assert.Equal(ExactPoint3.Create(2, -4, 6, -8), ExactPoint3.Create(-1, 2, -3, 4));
            Assert.Equal(ExactPoint3.Create(2, -4, 6, -8).GetHashCode(), ExactPoint3.Create(-1, 2, -3, 4).GetHashCode());
            Assert.False(ExactPoint3.Create(1, 2, 3, 1).Equals((object)"(1, 2, 3)"));
        }

        [Fact]
        public void ApproxVector3d_BeyondTheDoubleRange_FallsBackToTheExactConversion()
        {
            // W (and X) beyond the double range: the double quotient is inf / inf or x / inf; the coordinates are not
            BigInteger w = BigInteger.One << 1100;
            ExactPoint3 p = ExactPoint3.Create(BigInteger.One << 1090, 3 * (BigInteger.One << 1095), BigInteger.One, w);
            Vector3d v = p.ApproxVector3d();
            Assert.Equal(Math.Pow(2, -10), v.x);
            Assert.Equal(3 * Math.Pow(2, -5), v.y);
            Assert.Equal(0.0, v.z);         // 2^-1100: below the subnormal range
            // quotients in the subnormal range, with W beyond the double range as well: the fallback is taken (the
            // plain division would give 0 here)
            ExactPoint3 s = ExactPoint3.Create(3, 5, 7, BigInteger.One << 1060);
            Vector3d a = s.ApproxVector3d(), e = s.ToVector3d();
            Assert.Equal(e, a);
            // in the normal range both agree within 4 ulps
            ExactPoint3 n = ExactPoint3.Create(1, 2, 3, 7);
            Assert.True(Math.Abs(n.ApproxVector3d().x - 1.0 / 7) <= 4 * Math.Pow(2, -52) / 7);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using System.Text;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The exact points of ExactMeshArrangement in fixed width (FixedPoint3, FixedArith;
    /// docs/design/FIXED_WIDTH_EXACT_POINTS.md): the conversions at every bit length and at the admission limit
    /// 2^255 - 1, the portable paths of netstandard2.0, the predicates against their BigInteger formulas up to the
    /// limit, and whole booleans that must be bit-identical with the fixed width switched off, also where fixed and
    /// BigInteger points are mixed.
    /// </summary>
    public unsafe class ExactPoint3FixedWidthTests
    {
        static readonly BigInteger Limit = (BigInteger.One << 255) - 1;

        static BigInteger RandomBits(Random rand, int bits)
        {
            if (bits <= 0) return BigInteger.Zero;
            var bytes = new byte[(bits + 7) / 8 + 1];
            rand.NextBytes(bytes);
            bytes[bytes.Length - 1] = 0;
            BigInteger v = new BigInteger(bytes) & ((BigInteger.One << bits) - 1);
            return v | (BigInteger.One << (bits - 1));      // exactly `bits` bits
        }

        // a random value of a random bit length up to maxBits, either sign; sometimes an extreme value
        static BigInteger RandomValue(Random rand, int maxBits, bool extremes = true)
        {
            int kind = extremes ? rand.Next(20) : 20;
            BigInteger v;
            if (kind == 0) v = Limit;
            else if (kind == 1) v = BigInteger.Zero;
            else if (kind == 2) v = BigInteger.One;
            else if (kind == 3) v = (BigInteger.One << (64 * rand.Next(1, 4))) - 1;     // full limbs
            else if (kind == 4) v = BigInteger.One << (64 * rand.Next(1, 4));
            else v = RandomBits(rand, rand.Next(1, maxBits + 1));
            if (v > Limit) v = Limit;
            return (rand.Next(2) == 0) ? v : -v;
        }

        static BigInteger RandomPositive(Random rand, int maxBits, bool extremes = true)
        {
            BigInteger w = BigInteger.Abs(RandomValue(rand, maxBits, extremes));
            return w.IsZero ? BigInteger.One : w;
        }

        static FixedPoint3 Fixed(ExactPoint3 p)
        {
            FixedPoint3 f;
            Assert.True(FixedPoint3.TryCreate(p, out f));
            return f;
        }

        [Fact]
        public void RoundTrip_EveryBitLength_AndTheLimit()
        {
            var rand = new Random(1);
            var values = new List<BigInteger> { 0, 1, -1, Limit, -Limit, Limit + 1, -(Limit + 1), BigInteger.One << 256, -(BigInteger.One << 256) };
            for (int bits = 1; bits <= 300; ++bits)
                for (int r = 0; r < 4; ++r) {
                    BigInteger v = RandomBits(rand, bits);
                    values.Add(v); values.Add(-v);
                }
            for (int k = 1; k <= 5; ++k) {
                values.Add(BigInteger.One << (64 * k)); values.Add(-(BigInteger.One << (64 * k)));
                values.Add((BigInteger.One << (64 * k)) - 1); values.Add(-((BigInteger.One << (64 * k)) - 1));
            }
            foreach (BigInteger v in values) {
                bool fits = BigInteger.Abs(v) <= Limit;
                // in each component, W positive
                foreach (int k in new[] { 0, 1, 2, 3 }) {
                    BigInteger x = (k == 0) ? v : 3, y = (k == 1) ? v : -5, z = (k == 2) ? v : 0, w = (k == 3) ? BigInteger.Abs(v) : 7;
                    if (w.IsZero) continue;
                    ExactPoint3 p = ExactPoint3.CreateUnreduced(x, y, z, w);
                    FixedPoint3 f;
                    Assert.Equal(fits, FixedPoint3.TryCreate(p, out f));
                    if (fits) {
                        ExactPoint3 back = f.ToExact();
                        Assert.Equal(p.X, back.X); Assert.Equal(p.Y, back.Y); Assert.Equal(p.Z, back.Z); Assert.Equal(p.W, back.W);
                        Assert.Equal(p.W.IsOne, f.WIsOne);
                    }
                }
                // the portable paths give the same limbs and values
                ulong* a = stackalloc ulong[4], b = stackalloc ulong[4];
                for (int i = 0; i < 4; ++i) a[i] = b[i] = 0;
                byte ma, mb;
                bool fa = FixedPoint3.Load(v, a, out ma), fb = FixedPoint3.LoadPortable(v, b, out mb);
                Assert.Equal(fits, fa);
                Assert.Equal(fits, fb);
                if (fits) {
                    Assert.Equal(ma, mb);
                    for (int i = 0; i < 4; ++i) Assert.Equal(a[i], b[i]);
                    Assert.Equal(v, FixedPoint3.ToBig(a, ma));
                    int len = ma & 7;
                    if (len > 0)
                        Assert.Equal(BigInteger.Abs(v), FixedPoint3.ToBigPortable(a, len));
                    Assert.Equal(v.IsZero ? 0 : (int)((ExactPoint3.BitLength(v) + 63) / 64), len);
                }
            }
        }

        [Fact]
        public void UsedLimbs_AreTheMinimum()
        {
            var rand = new Random(2);
            for (int bits = 0; bits <= 255; ++bits) {
                BigInteger v = RandomBits(rand, bits);
                if (rand.Next(2) == 0) v = -v;
                ulong* a = stackalloc ulong[4];
                for (int i = 0; i < 4; ++i) a[i] = 0;
                byte m;
                Assert.True(FixedPoint3.Load(v, a, out m));
                int len = m & 7;
                Assert.Equal((bits + 63) / 64, len);
                Assert.Equal(v.Sign < 0, (m & 0x80) != 0);
                for (int i = len; i < 4; ++i) Assert.Equal(0UL, a[i]);
            }
        }

        [Fact]
        public void SameValueAndHash_MatchExactPoint3Equality()
        {
            var rand = new Random(3);
            var points = new List<ExactPoint3>();
            for (int k = 0; k < 400; ++k)
                points.Add(ExactPoint3.Create(RandomValue(rand, 254, false), RandomValue(rand, 254, false), RandomValue(rand, 254, false), RandomPositive(rand, 254, false)));
            // and near-equal ones: one component off by one, or the sign
            for (int k = 0; k < 200; ++k) {
                ExactPoint3 p = points[k];
                points.Add(ExactPoint3.CreateUnreduced(p.X, p.Y, p.Z + 1, p.W));
                points.Add(ExactPoint3.CreateUnreduced(-p.X, p.Y, p.Z, p.W));
                points.Add(ExactPoint3.CreateUnreduced(p.X, p.Y, p.Z, p.W));
            }
            var fixeds = points.Select(Fixed).ToArray();
            for (int i = 0; i < points.Count; ++i)
                for (int j = i; j < Math.Min(points.Count, i + 50); ++j) {
                    bool eq = points[i].Equals(points[j]);
                    Assert.Equal(eq, FixedPoint3.SameValue(ref fixeds[i], ref fixeds[j]));
                    if (eq) Assert.Equal(fixeds[i].Hash(), fixeds[j].Hash());
                }
            for (int i = 0; i < 200; ++i) {
                int j = 400 + 3 * i + 2;        // the copy of point i
                Assert.True(FixedPoint3.SameValue(ref fixeds[i], ref fixeds[j]));
                Assert.Equal(fixeds[i].Hash(), fixeds[j].Hash());
            }
        }

        [Fact]
        public void MulHighPortable_MatchesBigInteger()
        {
            var rand = new Random(4);
            var values = new List<ulong> { 0, 1, 2, uint.MaxValue, (ulong)uint.MaxValue + 1, ulong.MaxValue, ulong.MaxValue - 1, 1UL << 63 };
            var buf = new byte[8];
            for (int k = 0; k < 2000; ++k) { rand.NextBytes(buf); values.Add(BitConverter.ToUInt64(buf, 0)); }
            for (int i = 0; i < values.Count; i += (i < 8) ? 1 : 3)
                for (int j = 0; j < values.Count; j += 37) {
                    ulong a = values[i], b = values[j];
                    BigInteger exact = new BigInteger(a) * new BigInteger(b);
                    ulong lo, hi = FixedArith.MulHighPortable(a, b, out lo);
                    Assert.Equal(exact, (new BigInteger(hi) << 64) + new BigInteger(lo));
                    ulong lo2, hi2 = FixedArith.MulHigh(a, b, out lo2);
                    Assert.Equal(hi, hi2);
                    Assert.Equal(lo, lo2);
                }
        }

        // ---- the predicates against their BigInteger formulas (as in ExactMeshArrangement) ----

        static BigInteger Det3(BigInteger a, BigInteger b, BigInteger c, BigInteger d, BigInteger e, BigInteger f, BigInteger g, BigInteger h, BigInteger i)
        {
            return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
        }

        static int OrientBig(ExactPoint3 a, ExactPoint3 b, ExactPoint3 c, int i, int j)
        {
            return Det3(a[i], a[j], a.W, b[i], b[j], b.W, c[i], c[j], c.W).Sign;
        }

        static void Row(ExactPoint3 v, ExactPoint3 d, int i, int j, out BigInteger x, out BigInteger y, out BigInteger l)
        {
            BigInteger A, B;
            if (v.W.IsOne && d.W.IsOne) {
                A = v[i] - d[i]; B = v[j] - d[j];
                x = A; y = B;
            } else {
                A = v[i] * d.W - d[i] * v.W; B = v[j] * d.W - d[j] * v.W;
                BigInteger s = v.W * d.W;
                x = A * s; y = B * s;
            }
            l = A * A + B * B;
        }

        static int InCircleBig(ExactPoint3 a, ExactPoint3 b, ExactPoint3 c, ExactPoint3 d, int i, int j)
        {
            BigInteger ax, ay, al, bx, by, bl, cx, cy, cl;
            Row(a, d, i, j, out ax, out ay, out al);
            Row(b, d, i, j, out bx, out by, out bl);
            Row(c, d, i, j, out cx, out cy, out cl);
            return Det3(ax, ay, al, bx, by, bl, cx, cy, cl).Sign;
        }

        static readonly BigInteger[] AlphaBig = ExactMeshArrangement.Alpha.Select(a => new BigInteger(a * 9007199254740992.0)).ToArray();     // a 2^53

        static int CompareBig(ExactPoint3 pa, ExactPoint3 pb)
        {
            BigInteger fa = (AlphaBig[0] * pa.X + AlphaBig[1] * pa.Y + AlphaBig[2] * pa.Z) * pb.W;
            BigInteger fb = (AlphaBig[0] * pb.X + AlphaBig[1] * pb.Y + AlphaBig[2] * pb.Z) * pa.W;
            int c = fa.CompareTo(fb);
            if (c != 0) return c;
            for (int k = 0; k < 3; ++k) {
                c = (pa[k] * pb.W).CompareTo(pb[k] * pa.W);
                if (c != 0) return c;
            }
            return 0;
        }

        static ulong[] AlphaLimbs { get { return AlphaBig.Select(a => (ulong)a).ToArray(); } }

        static ExactPoint3 RandomPoint(Random rand, int maxBits, bool integer)
        {
            return ExactPoint3.CreateUnreduced(RandomValue(rand, maxBits), RandomValue(rand, maxBits), RandomValue(rand, maxBits),
                integer ? BigInteger.One : RandomPositive(rand, maxBits));
        }

        // the extreme cases: every component at +-(2^255 - 1), which reaches the largest values of the bound table
        static ExactPoint3 ExtremePoint(Random rand)
        {
            Func<BigInteger> c = () => (rand.Next(2) == 0) ? Limit : -Limit;
            return ExactPoint3.CreateUnreduced(c(), c(), c(), Limit);
        }

        [Fact]
        public void Kernels_MatchBigInteger_AtAllSizes()
        {
            var rand = new Random(5);
            ulong[] alpha = AlphaLimbs;
            for (int k = 0; k < 6000; ++k) {
                int maxBits = new[] { 8, 60, 64, 110, 128, 200, 255 }[k % 7];
                bool integer = (k % 5 == 0);
                ExactPoint3 a, b, c, d;
                if (k % 11 == 0) { a = ExtremePoint(rand); b = ExtremePoint(rand); c = ExtremePoint(rand); d = ExtremePoint(rand); }
                else { a = RandomPoint(rand, maxBits, integer); b = RandomPoint(rand, maxBits, integer); c = RandomPoint(rand, maxBits, integer); d = RandomPoint(rand, maxBits, integer); }
                if (k % 13 == 0) c = a;                     // degenerate: zero determinants
                if (k % 17 == 0) d = b;
                int i = k % 3, j = (i + 1 + (k / 3) % 2) % 3;
                if (i == j) j = (i + 1) % 3;
                FixedPoint3 fa = Fixed(a), fb = Fixed(b), fc = Fixed(c), fd = Fixed(d);
                Assert.Equal(OrientBig(a, b, c, i, j), FixedArith.Orient(ref fa, ref fb, ref fc, i, j));
                Assert.Equal(InCircleBig(a, b, c, d, i, j), FixedArith.InCircle(ref fa, ref fb, ref fc, ref fd, i, j));
                Assert.Equal(CompareBig(a, b), FixedArith.ComparePoints(ref fa, ref fb, alpha[0], alpha[1], alpha[2]));
                Assert.Equal(CompareBig(a, c), FixedArith.ComparePoints(ref fa, ref fc, alpha[0], alpha[1], alpha[2]));
            }
        }

        [Fact]
        public void Kernels_ExactZeros_CollinearCocircularEqualKeys()
        {
            var rand = new Random(6);
            ulong[] alpha = AlphaLimbs;
            for (int k = 0; k < 500; ++k) {
                // collinear: c = a + t (b - a) in homogeneous coordinates, with large weights
                BigInteger w = RandomPositive(rand, 60, false);
                ExactPoint3 a = ExactPoint3.CreateUnreduced(RandomValue(rand, 120, false), RandomValue(rand, 120, false), RandomValue(rand, 120, false), w);
                ExactPoint3 b = ExactPoint3.CreateUnreduced(RandomValue(rand, 120, false), RandomValue(rand, 120, false), RandomValue(rand, 120, false), w);
                BigInteger t = RandomValue(rand, 30, false);
                ExactPoint3 c = ExactPoint3.CreateUnreduced(a.X + t * (b.X - a.X), a.Y + t * (b.Y - a.Y), a.Z + t * (b.Z - a.Z), w);
                FixedPoint3 fa = Fixed(a), fb = Fixed(b), fc = Fixed(c);
                for (int i = 0; i < 3; ++i) {
                    int j = (i + 1) % 3;
                    Assert.Equal(0, OrientBig(a, b, c, i, j));
                    Assert.Equal(0, FixedArith.Orient(ref fa, ref fb, ref fc, i, j));
                }
                // cocircular: points of the circle x^2 + y^2 = 25 scaled by s, over a common weight
                var circle = new[] { (3, 4), (5, 0), (0, 5), (-3, -4), (-4, 3), (4, -3) }.OrderBy(_ => rand.Next()).Take(4).ToArray();
                BigInteger s = RandomPositive(rand, 150, false), ww = RandomPositive(rand, 50, false), ox = RandomValue(rand, 150, false), oy = RandomValue(rand, 150, false);
                var pts = circle.Select(q => ExactPoint3.CreateUnreduced(ox + s * q.Item1, oy + s * q.Item2, RandomValue(rand, 100, false), ww)).ToArray();
                var f = pts.Select(Fixed).ToArray();
                Assert.Equal(0, InCircleBig(pts[0], pts[1], pts[2], pts[3], 0, 1));
                Assert.Equal(0, FixedArith.InCircle(ref f[0], ref f[1], ref f[2], ref f[3], 0, 1));
                // equal order keys: alpha . (a - b) = 0 with a != b is impossible for the irrational-like alpha only in
                // the limit; test equal points and points differing in one coordinate
                ExactPoint3 e = ExactPoint3.CreateUnreduced(a.X * 3, a.Y * 3, a.Z * 3, a.W * 3);     // the same point, other weight
                FixedPoint3 fe = Fixed(e);
                Assert.Equal(0, CompareBig(a, e));
                Assert.Equal(0, FixedArith.ComparePoints(ref fa, ref fe, alpha[0], alpha[1], alpha[2]));
            }
        }

        [Fact]
        public void ComparePoints_EqualOrderKeys_DecidedByTheCoordinates()
        {
            // alpha . (b - a) = 0 for b - a = (0, alpha2, -alpha1) / g (and for (alpha1, -alpha0, 0) / g): the order key
            // ties, the coordinates decide, in y (resp. x) after an equal x (resp. none)
            ulong[] alpha = AlphaLimbs;
            BigInteger a0 = AlphaBig[0], a1 = AlphaBig[1], a2 = AlphaBig[2];
            BigInteger g12 = BigInteger.GreatestCommonDivisor(a1, a2), g01 = BigInteger.GreatestCommonDivisor(a0, a1);
            var rand = new Random(8);
            for (int k = 0; k < 200; ++k) {
                BigInteger w = (k % 2 == 0) ? BigInteger.One : RandomPositive(rand, 60, false);
                ExactPoint3 a = ExactPoint3.CreateUnreduced(RandomValue(rand, 150, false), RandomValue(rand, 150, false), RandomValue(rand, 150, false), w);
                BigInteger t = RandomValue(rand, 20, false);
                if (t.IsZero) t = 1;
                var others = new[] {
                    ExactPoint3.CreateUnreduced(a.X, a.Y + t * w * a2 / g12, a.Z - t * w * a1 / g12, w),
                    ExactPoint3.CreateUnreduced(a.X + t * w * a1 / g01, a.Y - t * w * a0 / g01, a.Z, w),
                };
                foreach (ExactPoint3 b in others) {
                    FixedPoint3 fa = Fixed(a), fb = Fixed(b);
                    int expected = CompareBig(a, b);
                    Assert.NotEqual(0, expected);
                    Assert.Equal(expected, FixedArith.ComparePoints(ref fa, ref fb, alpha[0], alpha[1], alpha[2]));
                    Assert.Equal(-expected, FixedArith.ComparePoints(ref fb, ref fa, alpha[0], alpha[1], alpha[2]));
                }
            }
        }

        [Fact]
        public void LoadN_EveryWidth_AndItsLimit()
        {
            var rand = new Random(10);
            for (int limbs = 1; limbs <= 8; ++limbs) {
                BigInteger limit = (BigInteger.One << (64 * limbs - 1)) - 1;
                var values = new List<BigInteger> { 0, 1, limit, limit + 1, BigInteger.One << (64 * limbs), (BigInteger.One << (64 * limbs + 8)) + 5 };
                for (int bits = 1; bits <= 64 * limbs + 70; bits += 3) values.Add(RandomBits(rand, bits));
                foreach (BigInteger u in values)
                    foreach (BigInteger v in new[] { u, -u }) {
                        ulong* l = stackalloc ulong[8];
                        int len; bool neg;
                        bool fits = BigInteger.Abs(v) <= limit;
                        Assert.Equal(fits, FixedPoint3.LoadN(v, l, limbs, out len, out neg));
                        if (fits) {
                            Assert.True(len <= limbs);
                            // (ToBig packs the length into 3 bits, for the 4-limb components)
                            BigInteger mag = (len == 0) ? BigInteger.Zero : FixedPoint3.ToBigPortable(l, len);
                            Assert.Equal(v, (neg && len > 0) ? -mag : mag);
                            if (len > 0) Assert.NotEqual(0UL, l[len - 1]);
                        }
                    }
            }
        }

        [Fact]
        public void CompareAlong_MatchesBigInteger()
        {
            var rand = new Random(11);
            for (int k = 0; k < 3000; ++k) {
                int maxBits = new[] { 30, 120, 255 }[k % 3];
                ExactPoint3 a = RandomPoint(rand, maxBits, k % 4 == 0), b = (k % 7 == 0) ? a : RandomPoint(rand, maxBits, k % 4 == 0);
                int dBits = new[] { 1, 64, 200, 450, 511 }[k % 5];
                BigInteger dx = RandomValue(rand, dBits, false), dy = RandomValue(rand, dBits, false), dz = RandomValue(rand, dBits, false);
                if (k % 11 == 0) {
                    // d . (a - b) = 0 for integer points: d = (a - b) x e
                    dx = (a.Y - b.Y) * 3 - (a.Z - b.Z) * 5; dy = (a.Z - b.Z) * 2 - (a.X - b.X) * 3; dz = (a.X - b.X) * 5 - (a.Y - b.Y) * 2;
                }
                if (k % 13 == 0) { dx = (BigInteger.One << 511) - 1; dy = -dx; }      // at the 8-limb limit
                if (BigInteger.Abs(dx) >= (BigInteger.One << 511) || BigInteger.Abs(dy) >= (BigInteger.One << 511) || BigInteger.Abs(dz) >= (BigInteger.One << 511))
                    continue;
                BigInteger ka = (dx * a.X + dy * a.Y + dz * a.Z) * b.W, kb = (dx * b.X + dy * b.Y + dz * b.Z) * a.W;
                FixedPoint3 fa = Fixed(a), fb = Fixed(b);
                ulong* l = stackalloc ulong[24];
                int nx, ny, nz; bool sx, sy, sz;
                Assert.True(FixedPoint3.LoadN(dx, l, 8, out nx, out sx));
                Assert.True(FixedPoint3.LoadN(dy, l + 8, 8, out ny, out sy));
                Assert.True(FixedPoint3.LoadN(dz, l + 16, 8, out nz, out sz));
                Assert.Equal(ka.CompareTo(kb), FixedArith.CompareAlong(ref fa, ref fb, new FixedInt(l, nx, sx), new FixedInt(l + 8, ny, sy), new FixedInt(l + 16, nz, sz)));
            }
        }

        [Fact]
        public void DoubleOf_OnlyExactlyRepresentableIntegerPoints()
        {
            BigInteger two60 = BigInteger.One << 60;
            var cases = new List<(ExactPoint3 p, bool isDouble)> {
                (ExactPoint3.FromInteger(1, -2, 3), true),
                (ExactPoint3.FromInteger(0, 0, 0), true),
                (ExactPoint3.FromInteger(two60, -two60, (BigInteger.One << 200)), true),      // large, but doubles
                (ExactPoint3.FromInteger(two60 + 1, 0, 0), false),                           // 61 significant bits
                (ExactPoint3.FromInteger(0, -(two60 + 1), 0), false),
                (ExactPoint3.FromInteger(0, 0, two60 + 1), false),
                (ExactPoint3.FromInteger(5, two60 + 1, two60 + 1), false),
                (ExactPoint3.FromInteger(BigInteger.One << 1100, 0, 0), false),              // beyond the double range
                (ExactPoint3.FromInteger(0, -(BigInteger.One << 1100), 0), false),
                (ExactPoint3.FromInteger(0, 0, BigInteger.One << 1100), false),
                (ExactPoint3.Create(1, 2, 3, 2), false),                                     // W != 1
            };
            foreach (var (p, isDouble) in cases) {
                Vector3d d;
                Assert.Equal(isDouble, FixedPoint3.DoubleOf(p, out d));
                if (isDouble) {
                    Assert.Equal(p.X, new BigInteger(d.x)); Assert.Equal(p.Y, new BigInteger(d.y)); Assert.Equal(p.Z, new BigInteger(d.z));
                }
                FixedPoint3 f;
                if (FixedPoint3.TryCreate(p, out f)) {
                    Assert.Equal(isDouble, f.IsDouble);
                    if (isDouble) Assert.Equal(d, f.D);
                }
            }
        }

        [Fact]
        public void Hash_SpreadsDistinctPoints()
        {
            // (a weak hash only costs time, so the other tests cannot see it): distinct points of every size, and points
            // differing in one limb, one sign or one component, rarely share a hash
            var rand = new Random(12);
            var hashes = new HashSet<int>();
            int n = 0;
            for (int k = 0; k < 3000; ++k) {
                ExactPoint3 p = ExactPoint3.CreateUnreduced(RandomValue(rand, 254, false), RandomValue(rand, 254, false), RandomValue(rand, 254, false), RandomPositive(rand, 254, false));
                var variants = new[] { p, ExactPoint3.CreateUnreduced(-p.X, p.Y, p.Z, p.W), ExactPoint3.CreateUnreduced(p.X, p.Y, p.Z + (BigInteger.One << 128), p.W),
                    ExactPoint3.CreateUnreduced(p.Y, p.X, p.Z, p.W) };
                foreach (ExactPoint3 v in variants) {
                    FixedPoint3 f;
                    if (FixedPoint3.TryCreate(v, out f) == false) continue;
                    hashes.Add(f.Hash());
                    n++;
                }
            }
            // small integer points too (one limb, the common case)
            for (int x = -20; x <= 20; ++x)
                for (int y = -20; y <= 20; ++y) {
                    FixedPoint3 f = Fixed(ExactPoint3.FromInteger(x, y, 7));
                    hashes.Add(f.Hash());
                    n++;
                }
            Assert.True(hashes.Count >= n - n / 100, $"{n - hashes.Count} collisions in {n} points");
        }

        [Fact]
        public void Hash_SpreadsOverTheIndexShards()
        {
            // AddPoint picks one of 64 shards by the low bits of the hash: points whose coordinates are all multiples of
            // a large power of two (integer vertices on a fine grid) must not all land in one shard
            var shards = new HashSet<int>();
            for (int k = 1; k <= 400; ++k) {
                BigInteger s = BigInteger.One << 40;
                FixedPoint3 f = Fixed(ExactPoint3.FromInteger(k * s, (k % 7) * s, (k % 11) * s));
                shards.Add((f.Hash() & 0x7FFFFFFF) % 64);
            }
            Assert.True(shards.Count >= 48, $"only {shards.Count} of 64 shards used");
        }

