                long[] v = { rnd.Next(-1 << 12, 1 << 12), rnd.Next(-1 << 12, 1 << 12), rnd.Next(-1 << 12, 1 << 12) };
                long s1 = rnd.Next(-1000, 1000), t1 = rnd.Next(-1000, 1000), s2 = rnd.Next(-1000, 1000), t2 = rnd.Next(-1000, 1000);
                long[] b = { a[0] + u[0], a[1] + u[1], a[2] + u[2] };
