                Assert.Equal(0, ExactPredicates.InCircle(q[0], q[1], q[2], q[3]));
                Assert.Equal(0, AdaptivePredicates.InCircleStageD(q[0].x, q[0].y, q[1].x, q[1].y, q[2].x, q[2].y, q[3].x, q[3].y));

                int j = rnd.Next(4);
