using System;
using System.Collections.Generic;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The coplanar shortcuts of ExactMeshArrangement.touch_only and ExactTriangleIntersection.IntersectsBeyondSharedCoplanar
    /// (docs/design/CHEAPER_CONSTRUCTIONS.md, 4.1) against IntersectsBeyondShared, the code they replace for coplanar
    /// neighbours (shared edge and shared vertex): on generated
    /// planar patches with folds lying flat, collinear corners, slivers and corners on the other triangle's edges,
    /// every pair of triangles sharing corners gives the same answer.
    /// </summary>
    public class ExactTouchOnlyCoplanarTests
    {
        // a planar patch: a grid triangulation of points o + i e1 + j e2 (exact doubles), plus triangles on duplicated
        // (unwelded, so the arrangement shares them by point id) vertices that fold over grid edges and fan around
        // grid vertices, each with a random third corner on the grid: same side (overlap), opposite side, collinear
        static DMesh3 Patch(Random r, Vector3d o, Vector3d e1, Vector3d e2, int n, int extra)
        {
            var m = new DMesh3();
            Func<int, int, Vector3d> P = (i, j) => o + i * e1 + j * e2;
            for (int j = 0; j <= n; ++j)
                for (int i = 0; i <= n; ++i)
                    m.AppendVertex(P(i, j));
            Func<int, int, int> V = (i, j) => j * (n + 1) + i;
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    if (r.Next(2) == 0) {
                        m.AppendTriangle(V(i, j), V(i + 1, j), V(i + 1, j + 1));
                        m.AppendTriangle(V(i, j), V(i + 1, j + 1), V(i, j + 1));
                    } else {
                        m.AppendTriangle(V(i, j), V(i + 1, j), V(i, j + 1));
                        m.AppendTriangle(V(i + 1, j), V(i + 1, j + 1), V(i, j + 1));
                    }
                }
            for (int k = 0; k < extra; ++k) {
                int i0 = r.Next(n + 1), j0 = r.Next(n + 1);
                int i1 = Math.Max(0, Math.Min(n, i0 + r.Next(-1, 2))), j1 = Math.Max(0, Math.Min(n, j0 + r.Next(-1, 2)));
                int i2 = r.Next(n + 1), j2 = r.Next(n + 1);
                if ((i0 == i1 && j0 == j1) || (i0 == i2 && j0 == j2) || (i1 == i2 && j1 == j2))
                    continue;
                // (collinear third corners give degenerate triangles, which the arrangement skips: kept as input)
                int a = m.AppendVertex(P(i0, j0)), b = m.AppendVertex(P(i1, j1)), c = m.AppendVertex(P(i2, j2));
                if (r.Next(2) == 0) m.AppendTriangle(a, b, c); else m.AppendTriangle(b, a, c);
            }
            return m;
        }

        static string CheckAllPairs(DMesh3 mesh, ref int coplanarEdge, ref int coplanarVertex, ref int differ)
        {
            var arr = new ExactMeshArrangement(new List<DMesh3> { mesh }) { SelfIntersections = true };
            arr.Compute();
            var byPoint = new Dictionary<int, List<int>>();
            for (int t = 0; t < arr.Triangles.Count; ++t) {
                var T = arr.Triangles[t];
                for (int k = 0; k < 3; ++k) {
                    List<int> l;
                    if (byPoint.TryGetValue(T.Corners[k], out l) == false)
                        byPoint[T.Corners[k]] = l = new List<int>();
                    if (l.Contains(t) == false) l.Add(t);
                }
            }
            var seen = new HashSet<long>();
            var answers = new System.Text.StringBuilder();
            foreach (List<int> l in byPoint.Values)
                for (int x = 0; x < l.Count; ++x)
                    for (int y = x + 1; y < l.Count; ++y) {
                        int ti = Math.Min(l[x], l[y]), ui = Math.Max(l[x], l[y]);
                        if (seen.Add(((long)ti << 32) | (uint)ui) == false)
                            continue;
                        var T = arr.Triangles[ti]; var U = arr.Triangles[ui];
                        if (T.Degenerate || U.Degenerate)
                            continue;
                        int shared = 0;
                        for (int k = 0; k < 3; ++k)
                            if (U.Corners[k] == T.Corners[0] || U.Corners[k] == T.Corners[1] || U.Corners[k] == T.Corners[2])
                                shared++;
                        if (shared == 3)
                            continue;
                        if (shared == 2) coplanarEdge++; else coplanarVertex++;
                        var pa = new Index3i(T.Corners[0], T.Corners[1], T.Corners[2]);
                        var pb = new Index3i(U.Corners[0], U.Corners[1], U.Corners[2]);
                        var A = new Triangle3d(T.V0, T.V1, T.V2); var B = new Triangle3d(U.V0, U.V1, U.V2);
                        bool expected = ExactTriangleIntersection.IntersectsBeyondShared(pa, ref A, pb, ref B) == false;
                        // the entry point itself, on the coplanar pairs (its precondition): it must give IntersectsBeyondShared's
                        // answer, i.e. the opposite of touch-only (expected)
                        if (coplanar(T, U) && (ExactTriangleIntersection.IntersectsBeyondSharedCoplanar(pa, ref A, pb, ref B) != !expected))
                            differ++;
                        bool got = arr.touch_only(T, U);
                        if (got != expected || arr.touch_only(U, T) != expected)
                            differ++;
                        answers.Append(ti).Append(',').Append(ui).Append(got ? '+' : '-').Append(';');
                    }
            return answers.ToString();
        }

        [Fact]
        public void Invariance_OverSimilarities()
        {
            // every similarity: the answers equal IntersectsBeyondShared's (the rotated and translated copies are no
            // longer exactly coplanar, so they mostly test the dispatch); the 2^k scales give the same answers bit for bit
            var r = new Random(8);
            DMesh3 patch = Patch(r, new Vector3d(0.375, -2.5, 7), new Vector3d(0.25, 0, 0.125), new Vector3d(0, 0.5, 0.25), 5, 40);
            int edge = 0, vertex = 0, differ = 0;
            string reference = CheckAllPairs(patch, ref edge, ref vertex, ref differ);
            foreach (Similarity sim in Similarity.All()) {
                var m = new DMesh3(patch);
                foreach (int vid in m.VertexIndices())
                    m.SetVertex(vid, sim.Apply(m.GetVertex(vid)));
                string answers = CheckAllPairs(m, ref edge, ref vertex, ref differ);
                if (sim.IsExact)
                    Assert.Equal(reference, answers);
            }
            Assert.Equal(0, differ);
        }

        static bool coplanar(ExactMeshArrangement.InputTriangle T, ExactMeshArrangement.InputTriangle U)
        {
            return ExactPredicates.Orient3d(T.V0, T.V1, T.V2, U.V0) == 0 && ExactPredicates.Orient3d(T.V0, T.V1, T.V2, U.V1) == 0
                && ExactPredicates.Orient3d(T.V0, T.V1, T.V2, U.V2) == 0;
        }

        [Fact]
        public void CoplanarPatches_SameAsIntersectsBeyondShared()
        {
            var r = new Random(7);
            int edge = 0, vertex = 0, differ = 0;
            // axis-aligned and tilted planes, float-like and large coordinates, slivers (long thin cells)
            var planes = new[] {
                new[] { new Vector3d(0, 0, 0), new Vector3d(1, 0, 0), new Vector3d(0, 1, 0) },
                new[] { new Vector3d(0.375, -2.5, 7), new Vector3d(0.25, 0, 0.125), new Vector3d(0, 0.5, 0.25) },
                new[] { new Vector3d(1024.5, 333.25, -77), new Vector3d(1.0 / 64, 1.0 / 128, 1.0 / 32), new Vector3d(-1.0 / 16, 1.0 / 64, 0) },
                new[] { new Vector3d(632117.25, 5712043.5, 113.75), new Vector3d(0.5, 0.25, 0), new Vector3d(0, 0, 0.75) },
                new[] { new Vector3d(0, 0, 0), new Vector3d(1, 1.0 / 1024, 0), new Vector3d(1.0 / 1024, 1, 1.0 / 2048) },
                new[] { new Vector3d(-3, 2, 1), new Vector3d(8, 0, 0), new Vector3d(1.0 / 256, 1.0 / 128, 0) },
            };
            foreach (var p in planes)
                for (int rep = 0; rep < 4; ++rep)
                    CheckAllPairs(Patch(r, p[0], p[1], p[2], 5, 40), ref edge, ref vertex, ref differ);
            Assert.Equal(0, differ);
            Assert.True(edge > 1000 && vertex > 1000, $"shared edge {edge}, shared vertex {vertex}");
        }

        static ExactMeshArrangement Arrangement(DMesh3 m)
        {
            var arr = new ExactMeshArrangement(new List<DMesh3> { m }) { SelfIntersections = true };
            arr.Compute();
            return arr;
        }

        [Fact]
        public void SharedVertex_OneCornerInThePlane_TakesTheGeneralPath()
        {
            // T = (s, p, q) in z = 0; U = (s, u, w) with u in T's plane (outside T's corner) and w above it, projecting into
            // T's corner: U meets T's plane only in the segment s-u, so they touch only in s. A pair with one corner in
            // the plane and one not must not be taken for coplanar (the 2D test would see w inside T's corner). Both
            // orders of the corners of U (the corner in the plane first and last).
            foreach (bool zeroFirst in new[] { true, false }) {
                var m = new DMesh3();
                m.AppendVertex(new Vector3d(0, 0, 0)); m.AppendVertex(new Vector3d(1, 0, 0)); m.AppendVertex(new Vector3d(0, 1, 0));
                m.AppendVertex(new Vector3d(-1, -1, 0)); m.AppendVertex(new Vector3d(0.25, 0.25, 1));
                m.AppendTriangle(0, 1, 2);
                if (zeroFirst) m.AppendTriangle(0, 3, 4); else m.AppendTriangle(0, 4, 3);
                ExactMeshArrangement arr = Arrangement(m);
                Assert.True(arr.touch_only(arr.Triangles[0], arr.Triangles[1]));
                Assert.True(arr.touch_only(arr.Triangles[1], arr.Triangles[0]));
                // (and the coplanar entry, fed this pair against its precondition, would answer wrongly: the test is not vacuous)
                var T = arr.Triangles[0]; var U = arr.Triangles[1];
                var A = new Triangle3d(T.V0, T.V1, T.V2); var B = new Triangle3d(U.V0, U.V1, U.V2);
                Assert.True(ExactTriangleIntersection.IntersectsBeyondSharedCoplanar(new Index3i(T.Corners[0], T.Corners[1], T.Corners[2]), ref A,
                    new Index3i(U.Corners[0], U.Corners[1], U.Corners[2]), ref B));
            }
        }

        [Fact]
        public void CoplanarSliver_SameProjectionAsIntersectsBeyondShared()
        {
            // the repro of ExactTriangleIntersectionSliverTests (#249): both triangles in y = 0, A a sliver whose
            // floating-point normal is 0, so the projection axis must be chosen exactly; they touch only in the shared vertex
            Vector3d[] a = { new Vector3d(-0.976127129435447, 0, 0.07347307296897497), new Vector3d(-0.9283813883063483, 0, 0.22041939375248493),
                new Vector3d(-0.9522542588708977, 0, 0.14694623336072996) };
            Vector3d[] b = { new Vector3d(-0.8773141400056257, 0, 0.11681076482628214), new Vector3d(-0.9999999999999962, 0, -8.742278000372475E-08) };
            var A = new Triangle3d(a[0], a[1], a[2]); var B = new Triangle3d(b[0], a[1], b[1]);
            Index3i ia = new Index3i(0, 1, 2), ib = new Index3i(3, 1, 4);
            Assert.Equal(ExactTriangleIntersection.IntersectsBeyondShared(ia, ref A, ib, ref B), ExactTriangleIntersection.IntersectsBeyondSharedCoplanar(ia, ref A, ib, ref B));
            Assert.False(ExactTriangleIntersection.IntersectsBeyondSharedCoplanar(ia, ref A, ib, ref B));
            Assert.False(ExactTriangleIntersection.IntersectsBeyondSharedCoplanar(ib, ref B, ia, ref A));
            // through the arrangement's pair search
            var m = new DMesh3();
            foreach (Vector3d v in new[] { a[0], a[1], a[2], b[0], b[1] }) m.AppendVertex(v);
            m.AppendTriangle(0, 1, 2); m.AppendTriangle(3, 1, 4);
            ExactMeshArrangement arr = Arrangement(m);
            Assert.True(arr.touch_only(arr.Triangles[0], arr.Triangles[1]));
            Assert.True(arr.touch_only(arr.Triangles[1], arr.Triangles[0]));
        }

        [Fact]
        public void FoldOverlappingFlat_IsNotTouchOnly()
        {
            // two triangles on the edge (0,0)-(1,0) with both far corners above it: they overlap
            var m = new DMesh3();
            m.AppendVertex(new Vector3d(0, 0, 0)); m.AppendVertex(new Vector3d(1, 0, 0)); m.AppendVertex(new Vector3d(0.5, 1, 0));
            m.AppendVertex(new Vector3d(0.25, 0.5, 0));
            m.AppendTriangle(0, 1, 2);
            int a = m.AppendVertex(new Vector3d(1, 0, 0)), b = m.AppendVertex(new Vector3d(0, 0, 0));
            m.AppendTriangle(a, b, 3);
            var arr = new ExactMeshArrangement(new List<DMesh3> { m }) { SelfIntersections = true };
            arr.Compute();
            Assert.False(arr.touch_only(arr.Triangles[0], arr.Triangles[1]));
            // and with the far corner below the edge they only touch
            var m2 = new DMesh3();
            m2.AppendVertex(new Vector3d(0, 0, 0)); m2.AppendVertex(new Vector3d(1, 0, 0)); m2.AppendVertex(new Vector3d(0.5, 1, 0));
            m2.AppendVertex(new Vector3d(0.25, -0.5, 0));
            m2.AppendTriangle(0, 1, 2); m2.AppendTriangle(1, 0, 3);
            var arr2 = new ExactMeshArrangement(new List<DMesh3> { m2 }) { SelfIntersections = true };
            arr2.Compute();
            Assert.True(arr2.touch_only(arr2.Triangles[0], arr2.Triangles[1]));
        }
    }
}

using System;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// ExactTriangleIntersection.IsDegenerate: exactly collinear corners, decided exactly. Its floating-point prefilter
    /// (n^2 > 1e-24 s^2) only shortcuts clearly non-degenerate triangles, so near its threshold the answer is the exact one.
    /// </summary>
    public class ExactTriangleIntersectionDegenerateTests
    {
        // collinear in 3D iff collinear in all three axis projections (exact Orient2d), the reference
        static bool Collinear(Vector3d a, Vector3d b, Vector3d c)
        {
            for (int k = 0; k < 3; ++k) {
                Func<Vector3d, Vector2d> drop = v => k == 0 ? new Vector2d(v.y, v.z) : k == 1 ? new Vector2d(v.z, v.x) : new Vector2d(v.x, v.y);
                if (ExactPredicates.Orient2d(drop(a), drop(b), drop(c)) != 0)
                    return false;
            }
            return true;
        }

        static Vector3d RandomUnit(Random r)
        {
            Vector3d v = new Vector3d(r.NextDouble() - 0.5, r.NextDouble() - 0.5, r.NextDouble() - 0.5);
            return v.Normalized;
        }

        [Fact]
        public void IsDegenerate_PrefilterThreshold()
        {
            // slivers whose height puts n^2 / s^2 within a factor 4 of the prefilter's 1e-24, at scales 2^-40..2^40, and
            // exactly collinear triples (dyadic multiples of one direction) at the same scales
            var rand = new Random(41);
            int nearThreshold = 0, below = 0, above = 0, collinear = 0;
            for (int n = 0; n < 40000; ++n) {
                double scale = Math.Pow(2, rand.Next(-40, 41));
                Vector3d p = scale * new Vector3d(rand.NextDouble(), rand.NextDouble(), rand.NextDouble());
                Vector3d d = RandomUnit(rand), perp = d.Cross(RandomUnit(rand)).Normalized;
                Triangle3d t;
                if (n % 4 == 0) {
                    // exactly collinear: p, p + 2^i d', p + 2^j d' with d' a dyadic direction (exact products and sums)
                    Vector3d q = new Vector3d(rand.Next(0, 64), rand.Next(0, 64), rand.Next(0, 64)) * (scale / 64);
                    Vector3d dd = new Vector3d(rand.Next(-8, 9), rand.Next(-8, 9), rand.Next(1, 9)) * (scale / 8);
                    t = new Triangle3d(q, q + dd, q + 2 * dd);
                } else {
                    double len = scale * (0.5 + rand.NextDouble());
                    // n^2 / s^2 = h^2 len^2 / (len^2 + |q - p|^2)^2: about (h / len)^2 / (1 + u^2)^2
                    double u = rand.NextDouble();
                    double ratio = 1e-12 * Math.Pow(2, 4 * rand.NextDouble() - 2) * (1 + u * u);
                    t = new Triangle3d(p, p + len * d, p + u * len * d + ratio * len * perp);
                }
                Vector3d e1 = t.V1 - t.V0, e2 = t.V2 - t.V0;
                double s = e1.LengthSquared + e2.LengthSquared, nn = e1.Cross(e2).LengthSquared;
                bool expected = Collinear(t.V0, t.V1, t.V2);
                Assert.True(expected == ExactTriangleIntersection.IsDegenerate(ref t), $"{t.V0} {t.V1} {t.V2}: expected {expected}");
                // the 2^k scales give the same answer
                Triangle3d t2 = new Triangle3d(t.V0 * 1024, t.V1 * 1024, t.V2 * 1024);
                Assert.Equal(expected, ExactTriangleIntersection.IsDegenerate(ref t2));
                if (expected) collinear++;
                else {
                    double r = nn / (s * s);
                    if (r > 0.25e-24 && r < 4e-24) nearThreshold++;
                    if (nn > 1e-24 * (s * s)) above++; else below++;
                }
            }
            // the family is what it claims: collinear triples, and slivers on both sides of the prefilter's threshold
            Assert.True(collinear > 5000, $"collinear {collinear}");
            Assert.True(nearThreshold > 10000 && below > 5000 && above > 5000, $"near {nearThreshold}, below {below}, above {above}");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// ExactTriangleIntersection.IntersectsBeyondShared on coplanar neighbours where one triangle is a sliver: the
    /// projection axis must be chosen exactly (a floating-point normal of a sliver can round to zero, and dropping
    /// the wrong axis projects the plane onto a line, where every corner looks collinear). Checked against an oracle
    /// that shares no code with the library: exact dyadic orientations (BooleanOracle's Dyadic) in the plane.
    /// </summary>
    public class ExactTriangleIntersectionSliverTests
    {
        // the repro of the remesher session: both triangles in y = 0, vertex ids (0, 1, 2) and (3, 1, 4)
        static readonly Vector3d[] ReproA = {
            new Vector3d(-0.976127129435447, 0, 0.07347307296897497), new Vector3d(-0.9283813883063483, 0, 0.22041939375248493),
            new Vector3d(-0.9522542588708977, 0, 0.14694623336072996) };
        static readonly Vector3d[] ReproB = {
            new Vector3d(-0.8773141400056257, 0, 0.11681076482628214), new Vector3d(-0.9283813883063483, 0, 0.22041939375248493),
            new Vector3d(-0.9999999999999962, 0, -8.742278000372475E-08) };
        static readonly Index3i ReproIdsA = new Index3i(0, 1, 2), ReproIdsB = new Index3i(3, 1, 4);

        [Fact]
        public void Repro_CoplanarSliverAtSharedVertex_DoesNotIntersect()
        {
            var A = new Triangle3d(ReproA[0], ReproA[1], ReproA[2]);
            var B = new Triangle3d(ReproB[0], ReproB[1], ReproB[2]);
            // the case: coplanar, A a sliver (not exactly degenerate) whose floating-point normal is 0
            Assert.False(ExactTriangleIntersection.IsDegenerate(ref A));
            Assert.Equal(Vector3d.Zero, (A.V2 - A.V1).Cross(A.V0 - A.V1));
            Assert.False(ExactTriangleIntersection.SegmentIntersectsTriangle(A.V2, A.V0, ref B));
            Assert.False(ExactTriangleIntersection.SegmentIntersectsTriangle(B.V2, B.V0, ref A));
            Assert.False(Oracle.CornersOverlap(Plane.Y, A.V1, A.V2, A.V0, B.V2, B.V0));
            Assert.False(ExactTriangleIntersection.IntersectsBeyondShared(ReproIdsA, ref A, ReproIdsB, ref B));
            Assert.False(ExactTriangleIntersection.IntersectsBeyondShared(ReproIdsB, ref B, ReproIdsA, ref A));
        }

        [Fact]
        public void Repro_MeshRepairMetrics_FindsNoSelfIntersection()
        {
            var mesh = new DMesh3();
            foreach (Vector3d v in new[] { ReproA[0], ReproA[1], ReproA[2], ReproB[0], ReproB[2] })
                mesh.AppendVertex(v);
            Assert.True(mesh.AppendTriangle(0, 1, 2) >= 0);
            Assert.True(mesh.AppendTriangle(3, 1, 4) >= 0);
            Assert.Equal(0, gs.MeshRepairMetrics.SelfIntersections(mesh));
        }

        // ---------------------------------------------------------------- oracle

        // the plane both triangles lie in: Y = the plane y = const, its 2D coordinates (z, x); etc.; Oblique = the
        // plane y = 2 z (normal (0, 1, -2): exactly 0 in x, but not axis-aligned), its 2D coordinates (x, z)
        enum Plane { X = 0, Y = 1, Z = 2, Oblique = 3 }

        static class Oracle
        {
            static Dyadic[] Uv(Plane plane, Vector3d p)
            {
                switch (plane) {
                    case Plane.X: return new[] { Dyadic.Of(p.y), Dyadic.Of(p.z) };
                    case Plane.Y: return new[] { Dyadic.Of(p.z), Dyadic.Of(p.x) };
                    case Plane.Oblique: return new[] { Dyadic.Of(p.x), Dyadic.Of(p.z) };
                    default: return new[] { Dyadic.Of(p.x), Dyadic.Of(p.y) };
                }
            }

            // sign of the cross product (a - s) x (b - s) in the plane, exact
            public static int Orient(Plane plane, Vector3d s, Vector3d a, Vector3d b)
            {
                Dyadic[] S = Uv(plane, s), A = Uv(plane, a), B = Uv(plane, b);
                return ((A[0] - S[0]) * (B[1] - S[1]) - (A[1] - S[1]) * (B[0] - S[0])).Sign;
            }

            static bool RayInClosedCone(Plane plane, Vector3d s, Vector3d p, Vector3d q, Vector3d x)
            {
                // the cone p-s-q, counter-clockwise, below 180 degrees
                return Orient(plane, s, p, x) >= 0 && Orient(plane, s, x, q) >= 0;
            }

            /// <summary>
            /// Do the closed triangles (s, p, q) and (s, u, w), not degenerate and in the plane, share a point other
            /// than s? Both are convex and have the corner s, so they do iff their closed corners at s share a ray,
            /// which holds iff a boundary ray of one lies in the closed corner of the other.
            /// </summary>
            public static bool CornersOverlap(Plane plane, Vector3d s, Vector3d p, Vector3d q, Vector3d u, Vector3d w)
            {
                if (Orient(plane, s, p, q) < 0) { var t = p; p = q; q = t; }
                if (Orient(plane, s, u, w) < 0) { var t = u; u = w; w = t; }
                return RayInClosedCone(plane, s, p, q, u) || RayInClosedCone(plane, s, p, q, w)
                    || RayInClosedCone(plane, s, u, w, p) || RayInClosedCone(plane, s, u, w, q);
            }

            /// <summary> do the closed triangles (a, b, c) and (b, a, d) in the plane overlap beyond their edge? </summary>
            public static bool FoldOverlaps(Plane plane, Vector3d a, Vector3d b, Vector3d c, Vector3d d)
            {
                return Orient(plane, a, b, c) * Orient(plane, a, b, d) > 0;
            }
        }

        // ---------------------------------------------------------------- generated slivers

        static Vector3d Lift(Plane plane, double u, double v, double c)
        {
            switch (plane) {
                case Plane.X: return new Vector3d(c, u, v);
                case Plane.Y: return new Vector3d(v, c, u);
                case Plane.Oblique: return new Vector3d(u, 2 * v, v);
                default: return new Vector3d(u, v, c);
            }
        }

        sealed class Case
        {
            public Plane Plane;
            public Vector3d S, P, Q, U, W;
            public override string ToString() => string.Format(CultureInfo.InvariantCulture, "{0}: s {1:R} {2:R} {3:R}, p {4:R} {5:R} {6:R}, q {7:R} {8:R} {9:R}, u {10:R} {11:R} {12:R}, w {13:R} {14:R} {15:R}",
                Plane, S.x, S.y, S.z, P.x, P.y, P.z, Q.x, Q.y, Q.z, U.x, U.y, U.z, W.x, W.y, W.z);
        }

        /// <summary>
        /// Coplanar triangle pairs at a shared vertex s, in the three axis planes and the plane y = 2 z: A = (s, p, q) a sliver (q within
        /// 2^-k of the segment s-p, k in 20..57, so its floating-point normal is often 0), B = (s, u, w) with rays
        /// near the rays of A (on either side, or a sliver itself), so that both outcomes occur.
        /// </summary>
        static IEnumerable<Case> Slivers(int count, int seed)
        {
            var rnd = new Random(seed);
            for (int i = 0; i < count; ++i) {
                var plane = (Plane)(i % 4);
                double c = (i % 2 == 0) ? 0 : rnd.NextDouble() * 4 - 2;
                double su = rnd.NextDouble() * 2 - 1, sv = rnd.NextDouble() * 2 - 1;
                double angle = rnd.NextDouble() * 2 * Math.PI, len = 0.05 + rnd.NextDouble() * 0.3;
                double du = Math.Cos(angle), dv = Math.Sin(angle);
                double t = 0.2 + 0.6 * rnd.NextDouble(), h = Math.Pow(2, -(rnd.Next(2) == 0 ? rnd.Next(20, 50) : rnd.Next(50, 58))) * (rnd.Next(2) == 0 ? 1 : -1);
                var s = Lift(plane, su, sv, c);
                var p = Lift(plane, su + len * du, sv + len * dv, c);
                var q = Lift(plane, su + t * len * du - h * dv, sv + t * len * dv + h * du, c);
                // B: its first ray at an angle from A's ray (tiny or larger, either side), its opening small or large
                double off = (rnd.Next(3) == 0 ? Math.Pow(2, -rnd.Next(10, 50)) : rnd.NextDouble() * 0.5) * (rnd.Next(2) == 0 ? 1 : -1);
                double open = (rnd.Next(3) == 0 ? Math.Pow(2, -rnd.Next(20, 50)) : 0.05 + rnd.NextDouble()) * (rnd.Next(2) == 0 ? 1 : -1);
                double a1 = angle + off, a2 = a1 + open, l1 = 0.05 + rnd.NextDouble() * 0.3, l2 = 0.05 + rnd.NextDouble() * 0.3;
                var u = Lift(plane, su + l1 * Math.Cos(a1), sv + l1 * Math.Sin(a1), c);
                var w = Lift(plane, su + l2 * Math.Cos(a2), sv + l2 * Math.Sin(a2), c);
                yield return new Case { Plane = plane, S = s, P = p, Q = q, U = u, W = w };
            }
        }

        static bool Valid(Case k)
        {
            // both triangles not degenerate (the callers skip degenerate triangles), A a sliver
            return Oracle.Orient(k.Plane, k.S, k.P, k.Q) != 0 && Oracle.Orient(k.Plane, k.S, k.U, k.W) != 0;
        }

        static bool Library(Case k)
        {
            var A = new Triangle3d(k.S, k.P, k.Q);
            var B = new Triangle3d(k.U, k.S, k.W);
            return ExactTriangleIntersection.IntersectsBeyondShared(new Index3i(0, 1, 2), ref A, new Index3i(3, 0, 4), ref B);
        }

        [Fact]
        public void Slivers_AtSharedVertex_AgreeWithOracle()
        {
            int n = 0, overlapping = 0, zeroNormal = 0;
            foreach (Case k in Slivers(30000, 11)) {
                if (Valid(k) == false)
                    continue;
                n++;
                bool expected = Oracle.CornersOverlap(k.Plane, k.S, k.P, k.Q, k.U, k.W);
                if (expected) overlapping++;
                if ((k.P - k.S).Cross(k.Q - k.S) == Vector3d.Zero) zeroNormal++;
                Assert.True(expected == Library(k), $"{k}: expected {expected}");
            }
            // the family is what it claims: mostly valid, both outcomes, and many slivers with a zero normal
            Assert.True(n > 25000, $"valid cases {n}");
            Assert.True(overlapping > 2000 && n - overlapping > 2000, $"overlapping {overlapping} of {n}");
            Assert.True(zeroNormal > 300, $"zero floating-point normal {zeroNormal} of {n}");
        }

        [Fact]
        public void Slivers_AtSharedEdge_AgreeWithOracle()
        {
            int n = 0, folded = 0, zeroNormal = 0;
            foreach (Case k in Slivers(30000, 12)) {
                // A = (s, p, q) the sliver, B = (p, s, u) across the edge s-p: d = u on either side
                if (Oracle.Orient(k.Plane, k.S, k.P, k.Q) == 0 || Oracle.Orient(k.Plane, k.S, k.P, k.U) == 0)
                    continue;
                n++;
                bool expected = Oracle.FoldOverlaps(k.Plane, k.S, k.P, k.Q, k.U);
                if (expected) folded++;
                if ((k.P - k.S).Cross(k.Q - k.S) == Vector3d.Zero) zeroNormal++;
                var A = new Triangle3d(k.S, k.P, k.Q);
                var B = new Triangle3d(k.P, k.S, k.U);
                Assert.True(expected == ExactTriangleIntersection.IntersectsBeyondShared(new Index3i(0, 1, 2), ref A, new Index3i(1, 0, 3), ref B), $"{k}: expected {expected}");
            }
            Assert.True(n > 25000, $"valid cases {n}");
            Assert.True(folded > 2000 && n - folded > 2000, $"folded {folded} of {n}");
            Assert.True(zeroNormal > 300, $"zero floating-point normal {zeroNormal} of {n}");
        }

        /// <summary>
        /// Similarity.All(): the 2^k scales give the same answers; translations and other scales keep the triangles in
        /// one axis plane, and the answers match the oracle on the transformed coordinates. A rotation leaves the
        /// plane (the rounded corners are no longer coplanar), so the pair is another case: only checked for a
        /// consistent answer under swapping the triangles.
        /// </summary>
        [Fact]
        public void Slivers_SimilarityInvariance()
        {
            var cases = new List<Case>();
            foreach (Case k in Slivers(3000, 13))
                if (Valid(k)) cases.Add(k);
            foreach (Similarity sim in Similarity.All()) {
                foreach (Case k in cases) {
                    var t = new Case { Plane = k.Plane, S = sim.Apply(k.S), P = sim.Apply(k.P), Q = sim.Apply(k.Q), U = sim.Apply(k.U), W = sim.Apply(k.W) };
                    bool got = Library(t);
                    var A = new Triangle3d(t.S, t.P, t.Q);
                    var B = new Triangle3d(t.U, t.S, t.W);
                    Assert.Equal(got, ExactTriangleIntersection.IntersectsBeyondShared(new Index3i(3, 0, 4), ref B, new Index3i(0, 1, 2), ref A));
                    if (sim.IsExact)
                        Assert.True(Library(k) == got, $"{sim}: {k}");
                    Vector3d[] corners = { t.S, t.P, t.Q, t.U, t.W };
                    // (the oblique plane y = 2 z through the origin, kept by the scales only)
                    bool planar = t.Plane == Plane.Oblique ? Array.TrueForAll(corners, x => x.y == 2 * x.z)
                        : Array.TrueForAll(corners, x => x[(int)t.Plane] == t.S[(int)t.Plane]);
                    if (planar && Valid(t))
                        Assert.True(Oracle.CornersOverlap(t.Plane, t.S, t.P, t.Q, t.U, t.W) == got, $"{sim}: {t}");
                }
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// ExactTriangulation2 on its own, with exact integer predicates: random points (many on the edges of the outer
    /// triangle and on common lines) and non-crossing constraint segments, checked against the definition of a
    /// constrained Delaunay triangulation; and the documented exceptions for input that breaks the preconditions.
    /// Found with the mutation tests (tests/mutation, stryker-mesh-planar.json): the class was only tested through
    /// the boolean, where the arrangement never hands it collinear points or invalid input.
    /// </summary>
    public class ExactTriangulation2Tests
    {
        sealed class Points
        {
            public readonly List<(long x, long y)> P = new List<(long, long)>();
            public int Add(long x, long y) { P.Add((x, y)); return P.Count - 1; }

            public int Orient(int a, int b, int c)
            {
                var (ax, ay) = P[a]; var (bx, by) = P[b]; var (cx, cy) = P[c];
                return Math.Sign((bx - ax) * (cy - ay) - (by - ay) * (cx - ax));
            }

            // +1 if d is inside the circle through counter-clockwise a, b, c
            public int InCircle(int a, int b, int c, int d)
            {
                var (dx, dy) = P[d];
                BigInteger[] r = new[] { a, b, c }.Select(i => {
                    BigInteger x = P[i].x - dx, y = P[i].y - dy;
                    return new[] { x, y, x * x + y * y };
                }).SelectMany(v => v).ToArray();
                BigInteger det = r[0] * (r[4] * r[8] - r[5] * r[7]) - r[1] * (r[3] * r[8] - r[5] * r[6]) + r[2] * (r[3] * r[7] - r[4] * r[6]);
                return det.Sign;
            }

            // p on the closed segment (a, b)
            public bool OnSegment(int p, int a, int b)
            {
                if (Orient(a, b, p) != 0) return false;
                return Math.Min(P[a].x, P[b].x) <= P[p].x && P[p].x <= Math.Max(P[a].x, P[b].x)
                    && Math.Min(P[a].y, P[b].y) <= P[p].y && P[p].y <= Math.Max(P[a].y, P[b].y);
            }

            // the open segments (a, b) and (c, d) cross or overlap
            public bool Intersect(int a, int b, int c, int d)
            {
                if (a == c || a == d || b == c || b == d) {
                    // sharing an end: only an overlap along a common line counts
                    int s = (a == c || a == d) ? a : b, e1 = (s == a) ? b : a, e2 = (s == c) ? d : c;
                    return Orient(s, e1, e2) == 0 && (OnSegment(e1, s, e2) || OnSegment(e2, s, e1));
                }
                int o1 = Orient(a, b, c), o2 = Orient(a, b, d), o3 = Orient(c, d, a), o4 = Orient(c, d, b);
                if (o1 * o2 < 0 && o3 * o4 < 0) return true;
                return OnSegment(c, a, b) || OnSegment(d, a, b) || OnSegment(a, c, d) || OnSegment(b, c, d);
            }

            public ExactTriangulation2 Triangulation(int c0, int c1, int c2) =>
                new ExactTriangulation2(c0, c1, c2, Orient, InCircle);
        }

        static void AssertConstrainedDelaunay(Points pts, ExactTriangulation2 tr, IEnumerable<int> vertices, int[] outer,
            List<(int, int)> constraints, bool delaunay)
        {
            var tris = tr.Triangles().ToList();
            var directed = new Dictionary<(int, int), int>();
            foreach (Index3i t in tris) {
                // counter-clockwise, never flat
                Assert.Equal(1, pts.Orient(t.a, t.b, t.c));
                for (int k = 0; k < 3; ++k) {
                    var e = (t[k], t[(k + 1) % 3]);
                    Assert.False(directed.ContainsKey(e), $"edge {e} twice");
                    directed[e] = t[(k + 2) % 3];
                }
            }
            // the triangles tile the outer triangle: twice the areas add up, and every edge is an inner edge (both
            // directions) or on the outer boundary
            Func<int, int, int, long> area2 = (a, b, c) =>
                (pts.P[b].x - pts.P[a].x) * (pts.P[c].y - pts.P[a].y) - (pts.P[b].y - pts.P[a].y) * (pts.P[c].x - pts.P[a].x);
            Assert.Equal(area2(outer[0], outer[1], outer[2]), tris.Sum(t => area2(t.a, t.b, t.c)));
            foreach (var e in directed.Keys)
                if (directed.ContainsKey((e.Item2, e.Item1)) == false)
                    Assert.True(pts.OnSegment(e.Item1, outer[0], outer[1]) && pts.OnSegment(e.Item2, outer[0], outer[1])
                        || pts.OnSegment(e.Item1, outer[1], outer[2]) && pts.OnSegment(e.Item2, outer[1], outer[2])
                        || pts.OnSegment(e.Item1, outer[2], outer[0]) && pts.OnSegment(e.Item2, outer[2], outer[0]), $"boundary edge {e} inside");
            // exactly the inserted points are vertices
            var used = new HashSet<int>(tris.SelectMany(t => new[] { t.a, t.b, t.c }));
            Assert.True(used.SetEquals(vertices), "vertices");
            // the constraints are edges
            var cset = new HashSet<(int, int)>();
            foreach (var (u, v) in constraints) {
                Assert.True(directed.ContainsKey((u, v)) || directed.ContainsKey((v, u)), $"constraint ({u}, {v}) missing");
                cset.Add((Math.Min(u, v), Math.Max(u, v)));
            }
            if (delaunay == false)
                return;
            // every inner edge that is not a constraint is locally Delaunay
            foreach (var kv in directed) {
                var (a, b) = kv.Key;
                int d;
                if (directed.TryGetValue((b, a), out d) == false || cset.Contains((Math.Min(a, b), Math.Max(a, b))))
                    continue;
                Assert.True(pts.InCircle(a, b, kv.Value, d) <= 0, $"edge ({a}, {b}) not Delaunay");
            }
        }

        // the outer triangle (0, 0), (n, 0), (0, n) and random grid points in it (closed: some on its edges, many on
        // common lines), random non-crossing constraints between them that pass through no other point
        static (Points, int[], List<int>, List<(int, int)>) RandomInput(int seed, int n, int count, int constraintCount)
        {
            var rnd = new Random(seed);
            var pts = new Points();
            int[] outer = { pts.Add(0, 0), pts.Add(n, 0), pts.Add(0, n) };
            var seen = new HashSet<(long, long)> { (0, 0), (n, 0), (0, n) };
            var inner = new List<int>();
            while (inner.Count < count) {
                long x = rnd.Next(n + 1), y = rnd.Next(n + 1 - (int)x);
                // a third on the outer edges
                switch (rnd.Next(9)) {
                    case 0: y = 0; break;
                    case 1: x = 0; break;
                    case 2: y = n - x; break;
                }
                if (seen.Add((x, y)))
                    inner.Add(pts.Add(x, y));
            }
            var all = outer.Concat(inner).ToList();
            var constraints = new List<(int, int)>();
            for (int tries = 0; constraints.Count < constraintCount && tries < 50 * constraintCount; ++tries) {
                int u = inner[rnd.Next(inner.Count)], v = inner[rnd.Next(inner.Count)];
                if (u == v) continue;
                if (all.Any(p => p != u && p != v && pts.OnSegment(p, u, v))) continue;
                if (constraints.Any(c => pts.Intersect(u, v, c.Item1, c.Item2))) continue;
                constraints.Add((u, v));
            }
            return (pts, outer, inner, constraints);
        }

        [Theory]
        [InlineData(1, 12, 20, 6)]
        [InlineData(2, 30, 80, 25)]
        [InlineData(3, 8, 25, 10)]          // dense: most points on common lines
        [InlineData(4, 1000, 200, 40)]
        public void RandomPointsAndConstraints_ConstrainedDelaunay(int seed, int n, int count, int constraintCount)
        {
            var (pts, outer, inner, constraints) = RandomInput(seed, n, count, constraintCount);
            Assert.True(constraints.Count >= constraintCount / 2, "too few constraints generated");
            var tr = pts.Triangulation(outer[0], outer[1], outer[2]);
            foreach (int p in inner)
                tr.InsertPoint(p);
            // inserting a point again changes nothing
            tr.InsertPoint(inner[0]);
            AssertConstrainedDelaunay(pts, tr, outer.Concat(inner), outer, new List<(int, int)>(), true);
            foreach (var (u, v) in constraints)
                tr.InsertConstraint(u, v);
            // a constraint twice, or of length zero, changes nothing
            tr.InsertConstraint(constraints[0].Item1, constraints[0].Item2);
            tr.InsertConstraint(inner[1], inner[1]);
            AssertConstrainedDelaunay(pts, tr, outer.Concat(inner), outer, constraints, false);
            tr.MakeDelaunay();
            AssertConstrainedDelaunay(pts, tr, outer.Concat(inner), outer, constraints, true);
        }

        [Fact]
        public void ConstraintAcrossManyEdges_Inserted()
        {
            // a fan of points above and below a long segment, which crosses all the edges between them
            var pts = new Points();
            int[] outer = { pts.Add(-100, -100), pts.Add(200, -100), pts.Add(-100, 200) };
            int u = pts.Add(-50, 0), v = pts.Add(50, 0);
            var inner = new List<int> { u, v };
            for (int i = -9; i <= 9; i += 2) {
                inner.Add(pts.Add(5 * i, 1 + (i + 9) % 3));
                inner.Add(pts.Add(5 * i + 1, -1 - (i + 9) % 4));
            }
            var tr = pts.Triangulation(outer[0], outer[1], outer[2]);
            foreach (int p in inner)
                tr.InsertPoint(p);
            var c = new List<(int, int)> { (u, v) };
            tr.InsertConstraint(u, v);
            tr.MakeDelaunay();
            AssertConstrainedDelaunay(pts, tr, outer.Concat(inner), outer, c, true);
            Assert.Equal(0, tr.LinearSearches);
        }

        static void AssertThrows(string reason, Action a)
        {
            var ex = Assert.Throws<InvalidOperationException>(a);
            Assert.Contains(reason, ex.Message);
        }

        [Fact]
        public void InvalidInput_Throws()
        {
            var pts = new Points();
            int[] outer = { pts.Add(0, 0), pts.Add(10, 0), pts.Add(0, 10) };
            int p = pts.Add(2, 2), q = pts.Add(6, 2), r = pts.Add(4, 2), s = pts.Add(4, 0), t = pts.Add(4, 5);
            int outside = pts.Add(8, 8), copy = pts.Add(2, 2), notInserted = pts.Add(1, 1);

            var tr = pts.Triangulation(outer[0], outer[1], outer[2]);
            AssertThrows("outside of the outer triangle", () => tr.InsertPoint(outside));
            tr.InsertPoint(p);
            AssertThrows("coincides with a vertex", () => tr.InsertPoint(copy));
            // (a corner of the outer triangle at another index)
            AssertThrows("coincides with a vertex", () => tr.InsertPoint(pts.Add(10, 0)));
            tr.InsertPoint(q); tr.InsertPoint(r); tr.InsertPoint(s); tr.InsertPoint(t);
            AssertThrows("endpoint is not a vertex", () => tr.InsertConstraint(p, notInserted));
            AssertThrows("endpoint is not a vertex", () => tr.InsertConstraint(notInserted, p));
            // through the point r
            AssertThrows("was not inserted", () => tr.InsertConstraint(p, q));
            // crossing a constraint (without r, which (s, t) would pass through)
            var tr2 = pts.Triangulation(outer[0], outer[1], outer[2]);
            foreach (int k in new[] { p, q, s, t }) tr2.InsertPoint(k);
            tr2.InsertConstraint(s, t);
            AssertThrows("constraint segments cross", () => tr2.InsertConstraint(p, q));
        }
    }
}

