#if NET8_0_OR_GREATER
using System;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// What a warmed call allocates on this thread. The runtime can allocate there itself while it optimizes the code (a test failed with
    /// 5456 bytes on one CI run, and passed on the next), so this takes the least of a few runs of at least 1000 calls: code that allocates
    /// at least once in that many does so in each of them.
    /// </summary>
    internal static class Allocations
    {
        internal static long Least(int calls, Action hot)
        {
            for (int i = 0; i < calls; ++i) hot();
            int window = Math.Max(calls, 1000);
            long least = long.MaxValue;
            for (int attempt = 0; attempt < 5 && least != 0; ++attempt) {
                long before = GC.GetAllocatedBytesForCurrentThread();
                for (int i = 0; i < window; ++i) hot();
                least = Math.Min(least, GC.GetAllocatedBytesForCurrentThread() - before);
            }
            return least;
        }
    }
}
#endif

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Numerics;
using g3;
using gs;
using Ops = g3.ExactMeshBoolean.Operations;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// An axis-aligned box with integer corners [X0,X1] x [Y0,Y1] x [Z0,Z1], X0 &lt; X1 etc. An immutable, printable
    /// description of a Boolean operand (docs/design/BOOLEAN_PROPERTY_TESTS.md): meshes are built fresh from it.
    /// </summary>
    public sealed class IntBox
    {
        public readonly int X0, Y0, Z0, X1, Y1, Z1;

        public IntBox(int x0, int y0, int z0, int x1, int y1, int z1)
        {
            if (x0 >= x1 || y0 >= y1 || z0 >= z1) throw new ArgumentException("empty box");
            X0 = x0; Y0 = y0; Z0 = z0; X1 = x1; Y1 = y1; Z1 = z1;
        }

        public int Lo(int axis) => axis == 0 ? X0 : axis == 1 ? Y0 : Z0;
        public int Hi(int axis) => axis == 0 ? X1 : axis == 1 ? Y1 : Z1;

        /// <summary> strictly inside (the oracle only asks at points off every box plane) </summary>
        public bool Contains(Vector3d p) => X0 < p.x && p.x < X1 && Y0 < p.y && p.y < Y1 && Z0 < p.z && p.z < Z1;

        public override string ToString() =>
            string.Format(CultureInfo.InvariantCulture, "[{0},{1}]x[{2},{3}]x[{4},{5}]", X0, X1, Y0, Y1, Z0, Z1);
    }

    /// <summary>
    /// Two boxes and the exact map p -> 2^Exponent * p + Translation into world coordinates. With small integer
    /// corners, |Exponent| &lt;= 8 and a translation on a 1/16 grid below 2^12, every world coordinate, every
    /// difference of two and every axis-aligned cross product is exact in double, so the box results can be
    /// checked bit for bit (BoxOracle).
    /// </summary>
    public sealed class BoxCase
    {
        public readonly IntBox A, B;
        public readonly int Exponent;
        public readonly Vector3d Translation;

        public BoxCase(IntBox a, IntBox b, int exponent = 0, Vector3d translation = default(Vector3d))
        {
            A = a; B = b; Exponent = exponent; Translation = translation;
        }

        public double Scale => Math.Pow(2, Exponent);
        public Vector3d ToWorld(Vector3d p) => Scale * p + Translation;
        public Vector3d FromWorld(Vector3d p) => (p - Translation) / Scale;

        public DMesh3 MeshA() => BooleanOracle.BoxMesh(A, this);
        public DMesh3 MeshB() => BooleanOracle.BoxMesh(B, this);

        public override string ToString() =>
            string.Format(CultureInfo.InvariantCulture, "A={0} B={1} scale=2^{2} t=({3:R},{4:R},{5:R})",
                A, B, Exponent, Translation.x, Translation.y, Translation.z);
    }

    /// <summary> A tetrahedron with integer corners, positively oriented (the corners are swapped if needed). </summary>
    public sealed class IntTet
    {
        public readonly Vector3i P0, P1, P2, P3;

        public IntTet(Vector3i p0, Vector3i p1, Vector3i p2, Vector3i p3)
        {
            long det = Det(p0, p1, p2, p3);
            if (det == 0) throw new ArgumentException("flat tetrahedron");
            P0 = p0; P1 = det > 0 ? p1 : p2; P2 = det > 0 ? p2 : p1; P3 = p3;
        }

        public static long Det(Vector3i a, Vector3i b, Vector3i c, Vector3i d)
        {
            long bx = b.x - a.x, by = b.y - a.y, bz = b.z - a.z;
            long cx = c.x - a.x, cy = c.y - a.y, cz = c.z - a.z;
            long dx = d.x - a.x, dy = d.y - a.y, dz = d.z - a.z;
            return bx * (cy * dz - cz * dy) - by * (cx * dz - cz * dx) + bz * (cx * dy - cy * dx);
        }

        /// <summary> six times the volume (exact) </summary>
        public long SixVolume => Det(P0, P1, P2, P3);

        public DMesh3 Mesh(Vector3d translation)
        {
            var m = new DMesh3();
            foreach (Vector3i p in new[] { P0, P1, P2, P3 })
                m.AppendVertex(new Vector3d(p.x, p.y, p.z) + translation);
            // outward for det(P0,P1,P2,P3) > 0: each face seen from outside is counter-clockwise
            m.AppendTriangle(0, 2, 1);
            m.AppendTriangle(0, 1, 3);
            m.AppendTriangle(1, 2, 3);
            m.AppendTriangle(0, 3, 2);
            return m;
        }

        static string P(Vector3i p) => string.Format(CultureInfo.InvariantCulture, "({0},{1},{2})", p.x, p.y, p.z);
        public override string ToString() => P(P0) + P(P1) + P(P2) + P(P3);
    }

    /// <summary>
    /// An exact dyadic rational M * 2^E: every finite double is one, and sums, differences and products of them
    /// stay exact. For the oracle's volumes and areas, which have more than 53 bits once a coordinate has many
    /// (eg a sliver vertex at a + 2^-25 (b - a)).
    /// </summary>
    public struct Dyadic : IEquatable<Dyadic>
    {
        public readonly BigInteger M;
        public readonly int E;

        public Dyadic(BigInteger m, int e) { M = m; E = e; }

        public static Dyadic Of(double x)
        {
            if (double.IsNaN(x) || double.IsInfinity(x)) throw new ArgumentException("not finite");
            long bits = BitConverter.DoubleToInt64Bits(x);
            int exp = (int)((bits >> 52) & 0x7FF);
            long mant = bits & ((1L << 52) - 1);
            if (exp == 0) exp = 1; else mant |= 1L << 52;
            return new Dyadic(bits < 0 ? -mant : mant, exp - 1075);
        }

        static BigInteger Align(Dyadic x, int e) => x.M << (x.E - e);
        public static Dyadic operator +(Dyadic x, Dyadic y) { int e = Math.Min(x.E, y.E); return new Dyadic(Align(x, e) + Align(y, e), e); }
        public static Dyadic operator -(Dyadic x, Dyadic y) { int e = Math.Min(x.E, y.E); return new Dyadic(Align(x, e) - Align(y, e), e); }
        public static Dyadic operator *(Dyadic x, Dyadic y) => new Dyadic(x.M * y.M, x.E + y.E);
        public Dyadic Abs() => new Dyadic(BigInteger.Abs(M), E);
        public int Sign => M.Sign;

        public bool Equals(Dyadic other) => (this - other).Sign == 0;
        public override bool Equals(object obj) => obj is Dyadic d && Equals(d);
        public override int GetHashCode() => 0;
        /// <summary> the nearest double, up to an ulp (for messages; compare with Equals) </summary>
        public double ToDouble()
        {
            if (M.IsZero) return 0;
            // (keep about 64 bits of M: a huge M with a very negative E would give infinity times 0)
            int k = Math.Max(0, (int)Math.Ceiling(BigInteger.Log(BigInteger.Abs(M), 2)) - 64);
            return (double)(M >> k) * Math.Pow(2, E + k);
        }
        public override string ToString() => ToDouble().ToString("R", System.Globalization.CultureInfo.InvariantCulture);
    }

    /// <summary>
    /// Oracles for ExactMeshBoolean results that share no code with it: an analytic reference for two boxes, a
    /// solid-angle winding number, and a resolution-aware comparison of two solids that does not depend on their
    /// triangulation. Every check returns "" when it holds, otherwise the reason.
    /// </summary>
    public static class BooleanOracle
    {
        public static readonly Ops[] AllOps = { Ops.Union, Ops.Intersection, Ops.Difference };

        public static bool Apply(Ops op, bool a, bool b) =>
            op == Ops.Union ? a || b : op == Ops.Intersection ? a && b : a && !b;

        /// <summary> the Boolean under test, with a fresh instance; null with the error if Compute() fails </summary>
        public static DMesh3 Run(DMesh3 a, DMesh3 b, Ops op, out string error, bool safeRounding = true)
        {
            return Run(a, b, op, out error, out _, safeRounding);
        }

        /// <summary> Run, with the drift SafeRounding measured (MeshRoundingRepair.MaxDrift; 0 without it) </summary>
        public static DMesh3 Run(DMesh3 a, DMesh3 b, Ops op, out string error, out double maxDrift, bool safeRounding = true)
        {
            var boolean = new ExactMeshBoolean(a, b, op) { SafeRounding = safeRounding };
            bool ok = boolean.Compute();
            error = ok && boolean.Status == ExactMeshBoolean.BooleanStatus.Success && boolean.Result != null ? ""
                : "Compute() failed: " + boolean.Status + " " + boolean.Error;
            maxDrift = boolean.Rounding?.MaxDrift ?? 0;
            return error == "" ? boolean.Result : null;
        }

        /// <summary>
        /// The contract of SafeRounding against the result without its repair, as the arrangement gives it: the measured
        /// drift within the documented bound (SafeRoundingBound), and the same solid within that bound; the message
        /// gives both.
        /// </summary>
        public static string WithinSafeRoundingBound(DMesh3 result, DMesh3 baseline, double size, double maxDrift)
        {
            double bound = SafeRoundingBound(result, baseline);
            if (!(maxDrift <= bound))
                return $"MaxDrift {maxDrift:G3} above the documented bound {bound:G3}";
            string r = SameSolid(result, baseline, size, bound);
            return r == "" ? "" : $"{r} (MaxDrift {maxDrift:G3}, documented bound {bound:G3})";
        }

        // ---------------------------------------------------------------- meshes

        public static DMesh3 BoxMesh(IntBox box, BoxCase frame)
        {
            var m = new DMesh3();
            for (int k = 0; k < 8; ++k) {
                var p = new Vector3d((k & 1) == 0 ? box.X0 : box.X1, (k & 2) == 0 ? box.Y0 : box.Y1, (k & 4) == 0 ? box.Z0 : box.Z1);
                m.AppendVertex(frame.ToWorld(p));
            }
            // each quad counter-clockwise seen from outside (corner bit 1 = x, 2 = y, 4 = z)
            int[][] quads = {
                new[] { 0, 4, 6, 2 }, new[] { 1, 3, 7, 5 },   // -x, +x
                new[] { 0, 1, 5, 4 }, new[] { 2, 6, 7, 3 },   // -y, +y
                new[] { 0, 2, 3, 1 }, new[] { 4, 5, 7, 6 } }; // -z, +z
            foreach (int[] q in quads) {
                m.AppendTriangle(q[0], q[1], q[2]);
                m.AppendTriangle(q[0], q[2], q[3]);
            }
            return m;
        }

        /// <summary> six times the signed volume, exactly: the sum of a . (b x c) over the triangles </summary>
        public static Dyadic ExactSixVolume(DMesh3 mesh)
        {
            Dyadic v = Dyadic.Of(0);
            foreach (int t in mesh.TriangleIndices()) {
                Index3i f = mesh.GetTriangle(t);
                Vector3d a = mesh.GetVertex(f.a), b = mesh.GetVertex(f.b), c = mesh.GetVertex(f.c);
                Dyadic ax = Dyadic.Of(a.x), ay = Dyadic.Of(a.y), az = Dyadic.Of(a.z), bx = Dyadic.Of(b.x), by = Dyadic.Of(b.y), bz = Dyadic.Of(b.z);
                Dyadic cx = Dyadic.Of(c.x), cy = Dyadic.Of(c.y), cz = Dyadic.Of(c.z);
                v = v + ax * (by * cz - bz * cy) + ay * (bz * cx - bx * cz) + az * (bx * cy - by * cx);
            }
            return v;
        }

        /// <summary> six times the signed volume in double, relative to the bounds center; absolute: the sum of the absolute terms </summary>
        public static double SixVolume(DMesh3 mesh, out double absolute)
        {
            absolute = 0;
            if (mesh.TriangleCount == 0) return 0;
            Vector3d c = MeshRepairMetrics.TriangleBounds(mesh).Center;
            double v = 0;
            Vector3d a = Vector3d.Zero, b = Vector3d.Zero, d = Vector3d.Zero;
            foreach (int t in mesh.TriangleIndices()) {
                mesh.GetTriVertices(t, ref a, ref b, ref d);
                double term = (a - c).Dot((b - c).Cross(d - c));
                v += term;
                absolute += Math.Abs(term);
            }
            return v;
        }

        public static double Volume(DMesh3 mesh) => SixVolume(mesh, out _) / 6;

        /// <summary>
        /// The documented bound of SafeRounding on how far it moves the surface (MeshRoundingRepair.MaxDrift: at most
        /// MaxDisplacement = 1e-5 times the diagonal of the rounded result), for results of the given size: the larger
        /// triangle-bounds diagonal of the meshes.
        /// </summary>
        public static double SafeRoundingBound(params DMesh3[] meshes)
        {
            double diag = 0;
            foreach (DMesh3 m in meshes)
                if (m.TriangleCount > 0)
                    diag = Math.Max(diag, gs.MeshRepairMetrics.TriangleBounds(m).DiagonalLength);
            return new MeshRoundingRepair(new DMesh3()).MaxDisplacement * diag;
        }

        public static double EdgeLength(DMesh3 mesh) =>
            mesh.EdgeIndices().Sum(e => { Index2i ev = mesh.GetEdgeV(e); return mesh.GetVertex(ev.a).Distance(mesh.GetVertex(ev.b)); });

        /// <summary>
        /// Generalized winding number at p: the sum of the solid angles of all triangles (Van Oosterom and Strackee
        /// 1983) over 4 pi. About 1 inside and 0 outside a closed, outward-oriented mesh; accurate away from it.
        /// </summary>
        public static double Winding(DMesh3 mesh, Vector3d p)
        {
            double sum = 0;
            Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
            foreach (int t in mesh.TriangleIndices()) {
                mesh.GetTriVertices(t, ref a, ref b, ref c);
                Vector3d u = a - p, v = b - p, w = c - p;
                double lu = u.Length, lv = v.Length, lw = w.Length;
                double num = u.Dot(v.Cross(w));
                double den = lu * lv * lw + u.Dot(v) * lw + u.Dot(w) * lv + v.Dot(w) * lu;
                sum += 2 * Math.Atan2(num, den);
            }
            return sum / (4 * Math.PI);
        }

        /// <summary>
        /// Valid DMesh3, finite, closed, manifold, consistently oriented, no inside-out components, no degenerate
        /// triangles (MeshRobustRepair.FindDefects), and no self-intersections other than contact at duplicated
        /// positions: solids that touch along an edge or at a vertex give manifold sheets with copies of the contact
        /// vertices (ExactBooleanByDesignTests), and MeshRepairMetrics counts two triangles that meet at copies with
        /// different ids as intersecting. So each pair it reports is tested again with the vertex ids replaced by
        /// one id per position. allowDegenerate: for inputs that already have sliver triangles, which the result
        /// may keep.
        /// </summary>
        public static string CleanReason(DMesh3 mesh, bool allowDegenerate = false)
        {
            if (mesh == null) return "null mesh";
            if (!mesh.Vertices().All(v => v.IsFinite)) return "non-finite coordinates";
            if (!mesh.CheckValidity(false, FailMode.ReturnOnly)) return "invalid DMesh3";
            if (mesh.TriangleCount == 0) return "";
            var defects = MeshRobustRepair.FindDefects(mesh, false);
            if (allowDegenerate) defects &= ~MeshRobustRepair.Defects.DegenerateTriangles;
            if (defects != MeshRobustRepair.Defects.None) return MeshRobustRepair.DescribeDefects(defects);
            var byPosition = new Dictionary<Vector3d, int>();
            foreach (int v in mesh.VertexIndices())
                if (!byPosition.ContainsKey(mesh.GetVertex(v))) byPosition[mesh.GetVertex(v)] = v;
            Index3i Welded(int t) { Index3i f = mesh.GetTriangle(t); return new Index3i(byPosition[mesh.GetVertex(f.a)], byPosition[mesh.GetVertex(f.b)], byPosition[mesh.GetVertex(f.c)]); }
            foreach (Index2i pair in MeshRepairMetrics.SelfIntersectionPairs(mesh)) {
                Triangle3d x = Triangle(mesh, pair.a), y = Triangle(mesh, pair.b);
                if (ExactTriangleIntersection.IntersectsBeyondShared(Welded(pair.a), ref x, Welded(pair.b), ref y))
                    return $"self-intersections (triangles {pair.a} and {pair.b})";
            }
            return "";
        }

        static Triangle3d Triangle(DMesh3 mesh, int t)
        {
            Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
            mesh.GetTriVertices(t, ref a, ref b, ref c);
            return new Triangle3d(a, b, c);
        }

        // ---------------------------------------------------------------- analytic box reference

        static double[][] Grid(BoxCase c)
        {
            var g = new double[3][];
            for (int axis = 0; axis < 3; ++axis)
                g[axis] = new double[] { c.A.Lo(axis), c.A.Hi(axis), c.B.Lo(axis), c.B.Hi(axis) }.Distinct().OrderBy(x => x).ToArray();
            return g;
        }

        public static bool Inside(BoxCase c, Ops op, Vector3d integerPoint) =>
            Apply(op, c.A.Contains(integerPoint), c.B.Contains(integerPoint));

        /// <summary>
        /// The cells of the grid of all box planes with their centers (integer frame) and volumes: each cell is
        /// entirely inside or outside A and B, so the result's solid is the union of the cells the truth table selects.
        /// </summary>
        static IEnumerable<(Vector3d center, double volume)> Cells(BoxCase c)
        {
            double[][] g = Grid(c);
            for (int i = 0; i + 1 < g[0].Length; ++i)
                for (int j = 0; j + 1 < g[1].Length; ++j)
                    for (int k = 0; k + 1 < g[2].Length; ++k)
                        yield return (new Vector3d((g[0][i] + g[0][i + 1]) / 2, (g[1][j] + g[1][j + 1]) / 2, (g[2][k] + g[2][k + 1]) / 2),
                            (g[0][i + 1] - g[0][i]) * (g[1][j + 1] - g[1][j]) * (g[2][k + 1] - g[2][k]));
        }

        /// <summary> the exact volume of the result, in the integer frame </summary>
        public static double ExpectedVolume(BoxCase c, Ops op) => Cells(c).Where(x => Inside(c, op, x.center)).Sum(x => x.volume);

        /// <summary> the exact boundary area of the result in the integer frame: the cell faces between inside and outside </summary>
        public static double ExpectedArea(BoxCase c, Ops op)
        {
            double area = 0;
            foreach (var cell in Cells(c)) {
                if (!Inside(c, op, cell.center)) continue;
                double[][] g = Grid(c);
                for (int axis = 0; axis < 3; ++axis) {
                    int i = Array.IndexOf(g[axis], g[axis].First(x => x > cell.center[axis])) - 1;
                    double face = cell.volume / (g[axis][i + 1] - g[axis][i]);
                    for (int side = 0; side < 2; ++side) {
                        // the center of the neighbour cell (or a point outside the grid)
                        Vector3d n = cell.center;
                        n[axis] = side == 0 ? (i == 0 ? g[axis][0] - 1 : (g[axis][i - 1] + g[axis][i]) / 2)
                                            : (i + 2 == g[axis].Length ? g[axis][i + 1] + 1 : (g[axis][i + 1] + g[axis][i + 2]) / 2);
                        if (!Inside(c, op, n)) area += face;
                    }
                }
            }
            return area;
        }

        // in-plane sample weights of a triangle; at least one avoids the grid lines of a triangle with grid corners
        static readonly double[][] SampleWeights = {
            new[] { 0.29, 0.33, 0.38 }, new[] { 0.61, 0.23, 0.16 }, new[] { 0.17, 0.62, 0.21 }, new[] { 0.13, 0.19, 0.68 },
            new[] { 0.45, 0.41, 0.14 }, new[] { 0.11, 0.47, 0.42 } };

        /// <summary>
        /// The analytic box oracle: the result must be empty if the expected volume is 0; otherwise clean (valid,
        /// closed, manifold, no self-intersections), with exactly the expected volume and area, every triangle on an
        /// axis plane with the expected solid behind and none in front of it (orientation, no misplaced or extra
        /// patch), and a winding number of 1 at the center of every selected cell and 0 at every other one.
        /// </summary>
        public static string CheckBoxResult(DMesh3 result, BoxCase c, Ops op, bool allowDegenerate = false)
        {
            if (result == null) return "null result";
            string clean = CleanReason(result, allowDegenerate);
            if (clean != "") return clean;
            double s = c.Scale;
            Dyadic s3 = Dyadic.Of(s) * Dyadic.Of(s) * Dyadic.Of(s);
            Dyadic expectedSix = Dyadic.Of(6 * ExpectedVolume(c, op)) * s3;
            if (expectedSix.Sign == 0)
                return result.TriangleCount == 0 ? "" : $"expected an empty result, got {result.TriangleCount} triangles";
            if (result.TriangleCount == 0) return "empty result, expected volume " + expectedSix.ToDouble() / 6;
            Dyadic six = ExactSixVolume(result);
            if (!six.Equals(expectedSix)) return $"volume {six.ToDouble() / 6:R}, expected {expectedSix.ToDouble() / 6:R}";

            Dyadic area2 = Dyadic.Of(0), expectedArea2 = Dyadic.Of(2 * ExpectedArea(c, op)) * Dyadic.Of(s) * Dyadic.Of(s);
            Vector3d a = Vector3d.Zero, b = Vector3d.Zero, d = Vector3d.Zero;
            double[][] g = Grid(c);
            foreach (int t in result.TriangleIndices()) {
                result.GetTriVertices(t, ref a, ref b, ref d);
                // (on an axis plane, the other two components are products with an exact 0)
                Vector3d n = (b - a).Cross(d - a);
                int axis = n.x != 0 ? 0 : n.y != 0 ? 1 : 2;
                if (n[(axis + 1) % 3] != 0 || n[(axis + 2) % 3] != 0 || n[axis] == 0 || a[axis] != b[axis] || a[axis] != d[axis])
                    return $"triangle {t} is not axis-aligned: normal {n}";
                int u = (axis + 1) % 3, v = (axis + 2) % 3;
                Dyadic exactN = (Dyadic.Of(b[u]) - Dyadic.Of(a[u])) * (Dyadic.Of(d[v]) - Dyadic.Of(a[v]))
                              - (Dyadic.Of(b[v]) - Dyadic.Of(a[v])) * (Dyadic.Of(d[u]) - Dyadic.Of(a[u]));
                area2 = area2 + exactN.Abs();
                var dir = Vector3d.Zero;
                dir[axis] = Math.Sign(n[axis]);
                bool probed = false;
                foreach (double[] w in SampleWeights) {
                    Vector3d p = c.FromWorld(w[0] * a + w[1] * b + w[2] * d);
                    bool onLine = false;
                    for (int k = 1; k < 3; ++k) {
                        int other = (axis + k) % 3;
                        onLine |= g[other].Any(x => Math.Abs(x - p[other]) < 1e-6);
                    }
                    if (onLine) continue;
                    probed = true;
                    // grid planes are at least 1 apart in the integer frame
                    if (!Inside(c, op, p - 0.25 * dir) || Inside(c, op, p + 0.25 * dir))
                        return $"triangle {t} (normal {n}) is not on the boundary of the expected solid, or reversed";
                }
                // (every sample of a sliver along a grid line can be on it: its area is still counted above)
                double longest = Math.Max((b - a).Length, Math.Max((d - b).Length, (a - d).Length));
                if (!probed && n.Length / longest >= 1e-5 * s)
                    return $"triangle {t} could not be probed";
            }
            if (!area2.Equals(expectedArea2)) return $"area {area2.ToDouble() / 2:R}, expected {expectedArea2.ToDouble() / 2:R}";
            foreach (var cell in Cells(c)) {
                double w = Winding(result, c.ToWorld(cell.center));
                double want = Inside(c, op, cell.center) ? 1 : 0;
                if (Math.Abs(w - want) > 0.25) return $"winding number {w:G4} at cell {cell.center}, expected {want}";
            }
            return "";
        }

        /// <summary>
        /// The regularized solid of a box result whose coordinates are not exact (eg rotated and mapped back): clean,
        /// the expected volume within volumeTolerance, and the expected winding number at the center of every cell
        /// and at the eight points a quarter of its extents off the center (at least 1/4 from every box plane, so far
        /// from the rounding noise). Faces need not be axis-aligned, and the area is not compared: rounded input
        /// coordinates are no longer exactly coplanar, so a coplanar contact can leave slabs or cracks of rounding
        /// thickness, which have area but no volume.
        /// </summary>
        public static string CheckBoxSolid(DMesh3 result, BoxCase c, Ops op, double volumeTolerance)
        {
            string clean = CleanReason(result);
            if (clean != "") return clean;
            double s = c.Scale, expected = ExpectedVolume(c, op) * s * s * s, v = Volume(result);
            if (Math.Abs(v - expected) > volumeTolerance) return $"volume {v:R}, expected {expected:R} (tolerance {volumeTolerance:G3})";
            double[][] g = Grid(c);
            foreach (var cell in Cells(c))
                for (int k = 0; k < 9; ++k) {
                    Vector3d p = cell.center;
                    if (k > 0)
                        for (int axis = 0; axis < 3; ++axis) {
                            double width = g[axis].First(x => x > cell.center[axis]) - g[axis].Last(x => x < cell.center[axis]);
                            p[axis] += ((((k - 1) >> axis) & 1) == 0 ? -0.25 : 0.25) * width;
                        }
                    double want = Inside(c, op, p) ? 1 : 0, w = result.TriangleCount == 0 ? 0 : Winding(result, c.ToWorld(p));
                    if (Math.Abs(w - want) > 0.25) return $"winding number {w:G4} at {p}, expected {want}";
                }
            return "";
        }

        // ---------------------------------------------------------------- comparison of two solids

        /// <summary>
        /// The rounding unit of the coordinates of the meshes: the largest coordinate magnitude times 2^-52.
        /// A result vertex is an exact point rounded to double, so it is off by at most half of it.
        /// </summary>
        public static double Resolution(params DMesh3[] meshes)
        {
            double m = 0;
            foreach (DMesh3 mesh in meshes)
                foreach (Vector3d v in mesh.Vertices())
                    m = Math.Max(m, Math.Max(Math.Abs(v.x), Math.Max(Math.Abs(v.y), Math.Abs(v.z))));
            return m * MathUtil.Epsilon;
        }

        /// <summary>
        /// Volume tolerance for two results of the same exact solid: moving each vertex by up to e (4 rounding
        /// units: the rounding of the exact points, and of the input's coordinates of a transformed copy) changes
        /// the volume by at most e times the area; the signed volume sum itself is off by about n eps times the sum
        /// of its absolute terms. Units: volume.
        /// </summary>
        public static double VolumeTolerance(DMesh3 x, DMesh3 y, double displacement = 0)
        {
            double e = 4 * Resolution(x, y) + displacement;
            SixVolume(x, out double ax); SixVolume(y, out double ay);
            int n = x.TriangleCount + y.TriangleCount;
            return e * (Invariance.Area(x) + Invariance.Area(y)) + 4 * n * MathUtil.Epsilon * (ax + ay) / 6;
        }

        /// <summary> Area tolerance: a vertex moved by e changes each incident triangle's area by at most e times its perimeter. </summary>
        public static double AreaTolerance(DMesh3 x, DMesh3 y, double displacement = 0)
        {
            double e = 4 * Resolution(x, y) + displacement;
            return 4 * e * (EdgeLength(x) + EdgeLength(y)) + 4 * (x.TriangleCount + y.TriangleCount) * MathUtil.Epsilon * (Invariance.Area(x) + Invariance.Area(y));
        }

        /// <summary>
        /// Whether x and y bound the same solid, independent of their triangulations: volumes and areas agree within
        /// the rounding tolerances, and for every well-shaped triangle of either mesh the other mesh has winding
        /// number 1 just behind and 0 just in front of it (both directions, so a missing or extra patch of either is
        /// found). This is a bounded numerical check, not a proof of equality. size: the extent of the inputs.
        /// displacement: a bound on how far vertices may have moved beyond rounding (SafeRounding on slivers:
        /// SliverWidth); it widens the volume and area tolerances and the probe distance.
        /// </summary>
        public static string SameSolid(DMesh3 x, DMesh3 y, double size, double displacement = 0)
        {
            if (x == null || y == null) return "null mesh";
            if (x.TriangleCount == 0 || y.TriangleCount == 0)
                return x.TriangleCount == y.TriangleCount ? "" : $"triangle count {x.TriangleCount} vs {y.TriangleCount}";
            double vx = Volume(x), vy = Volume(y), tolV = VolumeTolerance(x, y, displacement);
            if (Math.Abs(vx - vy) > tolV) return $"volume {vx:R} vs {vy:R} (tolerance {tolV:G3})";
            double ax = Invariance.Area(x), ay = Invariance.Area(y), tolA = AreaTolerance(x, y, displacement);
            if (Math.Abs(ax - ay) > tolA) return $"area {ax:R} vs {ay:R} (tolerance {tolA:G3})";
            string p = Probe(x, y, size, true, displacement);
            return p != "" ? p : Probe(y, x, size, true, displacement);
        }

        /// <summary>
        /// Whether x bounds the regularized solid of reference, for results of chained Booleans on rounded
        /// intermediate results: A-B and AnB, rounded separately, triangulate their shared faces differently, and with
        /// inexact coordinates the two triangulations leave cracks of rounding thickness, which the union keeps (true
        /// for its rounded inputs). A crack has area and no volume, and the solid on both of its sides. So: the volumes
        /// agree within rounding, every well-shaped triangle of reference has x's solid just behind and none just in
        /// front of it, and every triangle of x has reference's solid just behind it (an extra solid outside the
        /// reference is found, a crack inside it is not). This is broad: it also accepts x with extra inner faces
        /// that are no cracks, eg two face-touching boxes kept as separate shells for their merged box; only the
        /// callers' CleanReason (self-intersections) rejects that. Use it only for chained Booleans on inexact
        /// intermediate results (tetrahedra), never where SameSolid or the box oracle can be used.
        /// </summary>
        public static string SameRegularizedSolid(DMesh3 x, DMesh3 reference, double size)
        {
            if (x == null || reference == null) return "null mesh";
            if (x.TriangleCount == 0 || reference.TriangleCount == 0)
                return x.TriangleCount == reference.TriangleCount ? "" : $"triangle count {x.TriangleCount} vs {reference.TriangleCount}";
            double vx = Volume(x), vr = Volume(reference), tolV = VolumeTolerance(x, reference);
            if (Math.Abs(vx - vr) > tolV) return $"volume {vx:R} vs {vr:R} (tolerance {tolV:G3})";
            string p = Probe(reference, x, size, true);
            return p != "" ? p : Probe(x, reference, size, false);
        }

        // a solid of no well-shaped triangle (all of them thinner than the probe distance) is compared by its
        // volume and area only
        static string Probe(DMesh3 from, DMesh3 to, double size, bool front, double displacement = 0)
        {
            // the probes are delta off the triangle; triangles with an inradius below 4 delta are skipped, so a probe
            // cannot reach through another part of the surface that meets the triangle at an edge
            double delta = Math.Max(1e-5 * size, 4 * displacement);
            Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
            foreach (int t in from.TriangleIndices()) {
                from.GetTriVertices(t, ref a, ref b, ref c);
                Vector3d cross = (b - a).Cross(c - a);
                double perimeter = a.Distance(b) + b.Distance(c) + c.Distance(a);
                if (cross.Length / perimeter < 4 * delta) continue;
                Vector3d n = cross.Normalized, center = (a + b + c) / 3;
                double inside = Winding(to, center - delta * n), outside = Winding(to, center + delta * n);
                if (Math.Abs(inside - 1) > 0.25 || (front && Math.Abs(outside) > 0.25))
                    return $"triangle {t} at {center}: winding {inside:G4} behind and {outside:G4} in front in the other mesh";
            }
            return "";
        }

        // ---------------------------------------------------------------- representation changes

        /// <summary> the same mesh with its triangles in a random order (vertex ids and corners kept) </summary>
        public static DMesh3 TrianglesPermuted(DMesh3 mesh, int seed)
        {
            var rand = new Random(seed);
            var result = new DMesh3();
            var map = new Dictionary<int, int>();
            foreach (int v in mesh.VertexIndices()) map[v] = result.AppendVertex(mesh.GetVertex(v));
            foreach (int t in mesh.TriangleIndices().OrderBy(t => rand.Next()).ToArray()) {
                Index3i tri = mesh.GetTriangle(t);
                result.AppendTriangle(map[tri.a], map[tri.b], map[tri.c]);
            }
            return result;
        }

        /// <summary> the same mesh with its vertex ids permuted (triangle order and corners kept) </summary>
        public static DMesh3 VerticesPermuted(DMesh3 mesh, int seed)
        {
            var rand = new Random(seed);
            var result = new DMesh3();
            var map = new Dictionary<int, int>();
            foreach (int v in mesh.VertexIndices().OrderBy(v => rand.Next()).ToArray()) map[v] = result.AppendVertex(mesh.GetVertex(v));
            foreach (int t in mesh.TriangleIndices()) {
                Index3i tri = mesh.GetTriangle(t);
                result.AppendTriangle(map[tri.a], map[tri.b], map[tri.c]);
            }
            return result;
        }

        /// <summary> each triangle's corners rotated cyclically by 1 or 2 (orientation kept; never a swap) </summary>
        public static DMesh3 CornersRotated(DMesh3 mesh, int seed)
        {
            var rand = new Random(seed);
            var result = new DMesh3();
            var map = new Dictionary<int, int>();
            foreach (int v in mesh.VertexIndices()) map[v] = result.AppendVertex(mesh.GetVertex(v));
            foreach (int t in mesh.TriangleIndices()) {
                Index3i tri = mesh.GetTriangle(t);
                int k = 1 + rand.Next(2);
                result.AppendTriangle(map[tri[k]], map[tri[(k + 1) % 3]], map[tri[(k + 2) % 3]]);
            }
            return result;
        }

        /// <summary>
        /// Each triangle split into four at its edge midpoints, one midpoint per undirected edge, so the mesh stays
        /// conforming (no T-junctions). The mesh is rebuilt per level. The midpoints are exact unless u + w
        /// rounds, which the small dyadic test inputs avoid (CheckRepresentation compares the exact volumes).
        /// </summary>
        public static DMesh3 Subdivided(DMesh3 mesh, int levels)
        {
            for (int level = 0; level < levels; ++level) {
                var result = new DMesh3();
                var map = new Dictionary<int, int>();
                foreach (int v in mesh.VertexIndices()) map[v] = result.AppendVertex(mesh.GetVertex(v));
                var mid = new Dictionary<int, int>();
                int Mid(int u, int w)
                {
                    int e = mesh.FindEdge(u, w);
                    if (!mid.TryGetValue(e, out int m))
                        mid[e] = m = result.AppendVertex(0.5 * (mesh.GetVertex(u) + mesh.GetVertex(w)));
                    return m;
                }
                foreach (int t in mesh.TriangleIndices()) {
                    Index3i f = mesh.GetTriangle(t);
                    int ab = Mid(f.a, f.b), bc = Mid(f.b, f.c), ca = Mid(f.c, f.a);
                    result.AppendTriangle(map[f.a], ab, ca);
                    result.AppendTriangle(ab, map[f.b], bc);
                    result.AppendTriangle(ca, bc, map[f.c]);
                    result.AppendTriangle(ab, bc, ca);
                }
                mesh = result;
            }
            return mesh;
        }

        /// <summary>
        /// Near-degenerate but clean triangles: up to count edges of the input (chosen by seed) split at
        /// a + t (b - a), t = 2^-tExponent, so the new vertex lies exactly on the edge for dyadic coordinates and the
        /// two triangles at the edge's end a become slivers of area t times the triangle's. No triangle gets two
        /// splits: two splits whose near ends meet in one triangle would give a triangle of area about t^2, below the
        /// 1e-12 diagonal^2 that MeshRobustRepair counts as degenerate (a non-clean input, see
        /// ExactBooleanPropertyFindings.Resolve_DegenerateInputTriangle).
        /// </summary>
        public static DMesh3 SliverSplit(DMesh3 mesh, int count, int tExponent, int seed)
        {
            var result = new DMesh3(mesh);
            var rand = new Random(seed);
            double t = Math.Pow(2, -tExponent);
            var used = new HashSet<int>();
            var edges = new List<Index2i>();
            foreach (int e in mesh.EdgeIndices().OrderBy(e => rand.Next()).ToArray()) {
                Index2i et = mesh.GetEdgeT(e);
                if (edges.Count == count || used.Contains(et.a) || used.Contains(et.b)) continue;
                used.Add(et.a); used.Add(et.b);
                edges.Add(mesh.GetEdgeV(e));
            }
            foreach (Index2i ev in edges) {
                int e = result.FindEdge(ev.a, ev.b);
                Vector3d a = result.GetVertex(ev.a), b = result.GetVertex(ev.b);
                if (result.SplitEdge(e, out DMesh3.EdgeSplitInfo info, 0.5) != MeshResult.Ok) throw new InvalidOperationException("split failed");
                result.SetVertex(info.vNew, a + t * (b - a));
            }
            return new DMesh3(result, true);
        }

        /// <summary>
        /// A representation change must keep the oriented surface: clean (no degenerate triangles either), the same
        /// exact signed volume, the same solid (SameSolid), and an actual change of the triangle list.
        /// </summary>
        public static string CheckRepresentation(DMesh3 original, DMesh3 changed, double size)
        {
            string clean = CleanReason(changed);
            if (clean != "") return "changed input: " + clean;
            if (Invariance.Difference(original, changed) == "") return "the representation did not change";
            if (!ExactSixVolume(original).Equals(ExactSixVolume(changed))) return "changed input: the exact volume differs";
            return SameSolid(original, changed, size);
        }

        public enum Representation { TriangleOrder, VertexIds, CornerRotation, Subdivision, Slivers }

        public static DMesh3 Change(DMesh3 mesh, Representation r, int seed) =>
            r == Representation.TriangleOrder ? TrianglesPermuted(mesh, seed)
            : r == Representation.VertexIds ? VerticesPermuted(mesh, seed)
            : r == Representation.CornerRotation ? CornersRotated(mesh, seed)
            : r == Representation.Subdivision ? Subdivided(mesh, 1 + (seed & 1))
            : SliverSplit(mesh, 3, 20 + (seed & 7), seed);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Procedural defect meshes (docs/QA.md 2.1 and 2.5): the awkward inputs of the review checklist, and seeded random
    /// edits of clean meshes. Each case is small (a few hundred triangles), so that every operation can run over all of
    /// them in the normal suite.
    /// </summary>
    public static class Defects
    {
        /// <summary> a triangle soup: positions and index triples, before it becomes a DMesh3 </summary>
        public sealed class Soup
        {
            public List<Vector3d> P = new List<Vector3d>();
            public List<Index3i> T = new List<Index3i>();

            public static Soup From(DMesh3 mesh)
            {
                var s = new Soup();
                var map = new Dictionary<int, int>();
                foreach (int v in mesh.VertexIndices()) { map[v] = s.P.Count; s.P.Add(mesh.GetVertex(v)); }
                foreach (int t in mesh.TriangleIndices()) {
                    Index3i tv = mesh.GetTriangle(t);
                    s.T.Add(new Index3i(map[tv.a], map[tv.b], map[tv.c]));
                }
                return s;
            }

            public int AddVertex(Vector3d p) { P.Add(p); return P.Count - 1; }

            /// <summary> appends another soup (its indices shifted) </summary>
            public Soup Append(Soup other)
            {
                int n = P.Count;
                P.AddRange(other.P);
                foreach (Index3i t in other.T) T.Add(new Index3i(t.a + n, t.b + n, t.c + n));
                return this;
            }

            /// <summary>
            /// The DMesh3 of the soup. A triangle that DMesh3 rejects as non-manifold (a third triangle on an edge, or a
            /// duplicate) gets its own copies of its vertices, as the readers do, so every triangle of the soup is kept,
            /// but only geometrically on that edge (DMesh3 cannot hold a non-manifold edge); triangles with a repeated
            /// index are dropped (DMesh3 cannot hold them). Soup vertices left without a triangle are removed (a case
            /// that wants an unused vertex adds it to the mesh).
            /// </summary>
            public DMesh3 ToMesh()
            {
                var m = new DMesh3();
                foreach (Vector3d p in P) m.AppendVertex(p);
                foreach (Index3i t in T) {
                    if (t.a == t.b || t.b == t.c || t.a == t.c) continue;
                    if (m.AppendTriangle(t) < 0) {
                        int a = m.AppendVertex(P[t.a]), b = m.AppendVertex(P[t.b]), c = m.AppendVertex(P[t.c]);
                        m.AppendTriangle(new Index3i(a, b, c));
                    }
                }
                for (int v = 0; v < P.Count; ++v)
                    if (m.GetVtxEdgeCount(v) == 0) m.RemoveVertex(v);
                return m;
            }
        }

        public static DMesh3 Sphere(Vector3d c, double r, int n = 6)
        {
            DMesh3 m = new Sphere3Generator_NormalizedCube() { Radius = r, EdgeVertices = n }.Generate().MakeDMesh();
            MeshTransforms.Translate(m, c);
            return m;
        }

        static Soup SphereSoup(Vector3d c, double r, int n = 6) => Soup.From(Sphere(c, r, n));

        static Soup BoxSoup(Vector3d min, Vector3d max)
        {
            var s = new Soup();
            for (int i = 0; i < 8; ++i)
                s.AddVertex(new Vector3d((i & 1) == 0 ? min.x : max.x, (i & 2) == 0 ? min.y : max.y, (i & 4) == 0 ? min.z : max.z));
            // outward orientation
            int[][] quads = { new[] { 0, 2, 3, 1 }, new[] { 4, 5, 7, 6 }, new[] { 0, 1, 5, 4 }, new[] { 2, 6, 7, 3 }, new[] { 0, 4, 6, 2 }, new[] { 1, 3, 7, 5 } };
            foreach (int[] q in quads) {
                s.T.Add(new Index3i(q[0], q[1], q[2]));
                s.T.Add(new Index3i(q[0], q[2], q[3]));
            }
            return s;
        }

        /// <summary> a named defect case </summary>
        public sealed class Case
        {
            public string Name;
            /// <summary> builds a fresh mesh on every call (operations may modify their input) </summary>
            public Func<DMesh3> Make;
            public override string ToString() => Name;
        }

        static Case C(string name, Func<DMesh3> make) => new Case() { Name = name, Make = make };

        /// <summary> the fixed cases: one per defect class of the checklist, and a clean sphere as the control </summary>
        public static IEnumerable<Case> Fixed()
        {
            yield return C("clean sphere", () => Sphere(Vector3d.Zero, 1));
            yield return C("empty", () => new DMesh3());
            yield return C("single triangle", () => {
                var s = new Soup(); s.AddVertex(Vector3d.Zero); s.AddVertex(Vector3d.AxisX); s.AddVertex(Vector3d.AxisY);
                s.T.Add(new Index3i(0, 1, 2)); return s.ToMesh();
            });
            yield return C("zero-area ears", () => {
                // an edge split whose new vertex sits on an end of the edge: two needle triangles of zero area
                DMesh3 m = Sphere(Vector3d.Zero, 1);
                int e = m.EdgeIndices().First();
                Index2i ev = m.GetEdgeV(e);
                DMesh3.EdgeSplitInfo info;
                m.SplitEdge(e, out info);
                m.SetVertex(info.vNew, m.GetVertex(ev.a));
                return m;
            });
            yield return C("sliver cap", () => {
                // a poked triangle whose new vertex lies on one of its edges: a cap of zero area
                DMesh3 m = Sphere(Vector3d.Zero, 1);
                int t = m.TriangleIndices().First();
                Index3i tv = m.GetTriangle(t);
                DMesh3.PokeTriangleInfo info;
                m.PokeTriangle(t, out info);
                m.SetVertex(info.new_vid, 0.5 * (m.GetVertex(tv.a) + m.GetVertex(tv.b)));
                return m;
            });
            yield return C("T-junction", () => {
                // one side of an edge split at its midpoint, the other side not: two boundary edges along one edge
                Soup s = SphereSoup(Vector3d.Zero, 1);
                Index3i t = s.T[0];
                int mid = s.AddVertex(0.5 * (s.P[t.a] + s.P[t.b]));
                s.T[0] = new Index3i(t.a, mid, t.c);
                s.T.Add(new Index3i(mid, t.b, t.c));
                return s.ToMesh();
            });
            yield return C("triangle soup", () => {
                // every triangle with its own vertices: coincident vertices everywhere
                Soup s = SphereSoup(Vector3d.Zero, 1), r = new Soup();
                foreach (Index3i t in s.T) {
                    int a = r.AddVertex(s.P[t.a]), b = r.AddVertex(s.P[t.b]), c = r.AddVertex(s.P[t.c]);
                    r.T.Add(new Index3i(a, b, c));
                }
                return r.ToMesh();
            });
            yield return C("interior bowtie", () => {
                // two spheres that share one vertex, at their poles (an odd EdgeVertices puts a vertex at the centre of
                // each cube face: a unique extreme vertex along x)
                Soup a = SphereSoup(Vector3d.Zero, 1, 5);
                int va = Enumerable.Range(0, a.P.Count).OrderByDescending(i => a.P[i].x).First();
                Soup b = SphereSoup(Vector3d.Zero, 1, 5);
                int vb = Enumerable.Range(0, b.P.Count).OrderBy(i => b.P[i].x).First();
                Vector3d shift = a.P[va] - b.P[vb];
                for (int i = 0; i < b.P.Count; ++i) b.P[i] += shift;
                int n = a.P.Count;
                a.Append(b);
                for (int i = 0; i < b.T.Count; ++i) {
                    Index3i t = a.T[a.T.Count - b.T.Count + i];
                    int fix(int v) => (v == vb + n) ? va : v;
                    a.T[a.T.Count - b.T.Count + i] = new Index3i(fix(t.a), fix(t.b), fix(t.c));
                }
                return a.ToMesh();
            });
            yield return C("touching boxes", () => BoxSoup(Vector3d.Zero, Vector3d.One).Append(BoxSoup(new Vector3d(1, 0, 0), new Vector3d(2, 1, 1))).ToMesh());
            yield return C("overlapping spheres", () => SphereSoup(Vector3d.Zero, 1).Append(SphereSoup(new Vector3d(0.8, 0.3, 0.1), 0.9)).ToMesh());
            yield return C("nested and tiny", () => SphereSoup(Vector3d.Zero, 1).Append(SphereSoup(new Vector3d(0.1, 0, 0), 0.4))
                .Append(SphereSoup(new Vector3d(3, 0, 0), 1e-4, 3)).ToMesh());
            yield return C("unused far vertex", () => {
                DMesh3 m = Sphere(Vector3d.Zero, 1);
                m.AppendVertex(new Vector3d(1e6, -2e6, 5e5));
                return m;
            });
            yield return C("open", () => {
                DMesh3 m = Sphere(Vector3d.Zero, 1);
                foreach (int t in m.TriangleIndices().Where(t => m.GetTriCentroid(t).z > 0.8).ToList())
                    m.RemoveTriangle(t);
                return m;
            });
            yield return C("inside-out", () => { DMesh3 m = Sphere(Vector3d.Zero, 1); m.ReverseOrientation(); return m; });
            yield return C("partly flipped", () => {
                Soup s = SphereSoup(Vector3d.Zero, 1);
                for (int i = 0; i < s.T.Count; ++i)
                    if (s.P[s.T[i].a].x > 0.5) s.T[i] = new Index3i(s.T[i].b, s.T[i].a, s.T[i].c);
                return s.ToMesh();
            });
            // (the duplicates get their own vertices: coincident triangles, as the readers produce them)
            yield return C("duplicated triangles", () => {
                Soup s = SphereSoup(Vector3d.Zero, 1);
                int n = s.T.Count;
                for (int i = 0; i < n; i += 7) s.T.Add(s.T[i]);
                return s.ToMesh();
            });
            yield return C("non-manifold fin", () => {
                // a third triangle on an edge of a sphere, pointing outwards (with its own vertices: DMesh3 cannot hold a
                // non-manifold edge, so the fin touches the edge geometrically, as the readers produce it)
                Soup s = SphereSoup(Vector3d.Zero, 1);
                Index3i t = s.T[0];
                int tip = s.AddVertex(2 * (s.P[t.a] + s.P[t.b]));
                s.T.Add(new Index3i(t.a, t.b, tip));
                return s.ToMesh();
            });
            yield return C("flat", () => {
                // a closed mesh of zero volume: a sphere flattened onto z = 0
                DMesh3 m = Sphere(Vector3d.Zero, 1);
                foreach (int v in m.VertexIndices().ToList()) { Vector3d p = m.GetVertex(v); m.SetVertex(v, new Vector3d(p.x, p.y, 0)); }
                return m;
            });
            yield return C("thin slab", () => {
                DMesh3 m = Sphere(Vector3d.Zero, 1);
                MeshTransforms.Scale(m, new Vector3d(1, 1, 1e-6), Vector3d.Zero);
                return m;
            });
            yield return C("open sheet", () => {
                Soup s = new Soup();
                int n = 8;
                for (int j = 0; j <= n; ++j)
                    for (int i = 0; i <= n; ++i) s.AddVertex(new Vector3d(i, j, 0.1 * Math.Sin(i + j)));
                for (int j = 0; j < n; ++j)
                    for (int i = 0; i < n; ++i) {
                        int a = j * (n + 1) + i;
                        s.T.Add(new Index3i(a, a + 1, a + n + 2));
                        s.T.Add(new Index3i(a, a + n + 2, a + n + 1));
                    }
                return s.ToMesh();
            });
        }

        /// <summary>
        /// Seeded random edits of a clean sphere (docs/QA.md 2.5): triangles flipped, removed or duplicated, a vertex moved
        /// onto a neighbour (a zero-length edge) or by a few ulps, a stray triangle across the inside.
        /// </summary>
        public static Case RandomEdits(int seed)
        {
            return C($"random edits {seed}", () => {
                var rnd = new Random(seed);
                Soup s = SphereSoup(Vector3d.Zero, 1);
                int edits = 1 + rnd.Next(12);
                for (int k = 0; k < edits; ++k) {
                    int i = rnd.Next(s.T.Count);
                    Index3i t = s.T[i];
                    switch (rnd.Next(6)) {
                        case 0: s.T[i] = new Index3i(t.b, t.a, t.c); break;
                        case 1: s.T.RemoveAt(i); break;
                        case 2: s.T.Add(t); break;
                        case 3: s.P[t.a] = s.P[t.b]; break;           // a zero-length edge
                        case 4: {
                            Vector3d p = s.P[t.c];
                            s.P[t.c] = new Vector3d(Nudge(p.x, rnd), Nudge(p.y, rnd), Nudge(p.z, rnd));
                            break;
                        }
                        default: {
                            Index3i u = s.T[rnd.Next(s.T.Count)];
                            s.T.Add(new Index3i(t.a, u.b, t.c));    // a triangle through the inside
                            break;
                        }
                    }
                }
                return s.ToMesh();
            });
        }

        // a few ulps (0 stays 0: its bit pattern minus one is a NaN)
        static double Nudge(double x, Random rnd) =>
            (x == 0) ? x : BitConverter.Int64BitsToDouble(BitConverter.DoubleToInt64Bits(x) + rnd.Next(-4, 5));

        public static IEnumerable<Case> All(int randomCases = 12) =>
            Fixed().Concat(Enumerable.Range(1, randomCases).Select(RandomEdits));

        public static IEnumerable<object[]> Names() => All().Select(c => new object[] { c.Name });

        public static Case ByName(string name) => All().First(c => c.Name == name);
    }
}

using System;
using System.Linq;
using g3;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The generated families of degenerate input of docs/design/SAFE_ROUNDING.md section 2 (design question 1b),
    /// shared by SafeRoundingDegenerateInputTests and benchmarks/SnapRoundingExperiment (compiled into both; no xunit
    /// here).
    /// </summary>
    public static class DegenerateFamilies
    {
        public enum Family { Collinear, Sliver, ShortEdge, Coincident, Unwelded, VertexOnFace, SharedFace, Cluster, FoldedCluster }

        public static DMesh3 Sphere(int n) => new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = n }.Generate().MakeDMesh();

        public static DMesh3 Box(Vector3d min, Vector3d max) => new TrivialBox3Generator() {
            Box = new Box3d(new AxisAlignedBox3d(min, max))
        }.Generate().MakeDMesh();

        static void Ok(MeshResult r)
        {
            if (r != MeshResult.Ok) throw new InvalidOperationException(r.ToString());
        }

        // every count-th triangle (from seed on) gets the defect of the family; k is the exponent of the size 2^-k
        public static DMesh3 Make(Family f, int k, int seed, int count = 9)
        {
            double h = Math.Pow(2, -k);
            switch (f) {
                case Family.Collinear:
                case Family.Sliver: {
                    // a vertex poked into a triangle and moved onto (Collinear) or 2^-k inside (Sliver) its edge ab:
                    // the triangle (a, b, p) has zero area or a height of 2^-k
                    DMesh3 m = Sphere(6);
                    foreach (int tid in m.TriangleIndices().Where(t => (t + seed) % count == 0).ToArray()) {
                        Index3i t = m.GetTriangle(tid);
                        Vector3d a = m.GetVertex(t.a), b = m.GetVertex(t.b), c = m.GetVertex(t.c);
                        double s = 0.25 + 0.5 * ((tid * 7 + seed) % 11) / 10.0;
                        Vector3d onEdge = a + s * (b - a);
                        Vector3d p = f == Family.Collinear ? onEdge : onEdge + h * (c - onEdge).Normalized;
                        Ok(m.PokeTriangle(tid, out DMesh3.PokeTriangleInfo info));
                        m.SetVertex(info.new_vid, p);
                    }
                    return m;
                }
                case Family.ShortEdge:
                case Family.Coincident: {
                    // an edge split at 2^-k from its end (ShortEdge) or at its end (Coincident: two welded
                    // vertices at one position, two triangles of zero area)
                    DMesh3 m = Sphere(6);
                    foreach (int eid in m.EdgeIndices().Where(e => (e + seed) % count == 0).ToArray()) {
                        Index2i ev = m.GetEdgeV(eid);
                        Vector3d a = m.GetVertex(ev.a), b = m.GetVertex(ev.b);
                        Ok(m.SplitEdge(eid, out DMesh3.EdgeSplitInfo info));
                        m.SetVertex(info.vNew, f == Family.Coincident ? a : a + h * (b - a).Normalized);
                    }
                    return m;
                }
                case Family.Unwelded: {
                    // a vertex duplicated: some triangles of its fan use a copy at the same position (closed by
                    // position, open by ids)
                    DMesh3 m = Sphere(6);
                    foreach (int vid in m.VertexIndices().Where(v => (v + seed) % count == 0).ToArray()) {
                        int[] fan = m.VtxTrianglesItr(vid).ToArray();
                        int copy = m.AppendVertex(m.GetVertex(vid));
                        for (int i = 0; i < fan.Length / 2; i++) {
                            Index3i t = m.GetTriangle(fan[i]);
                            m.RemoveTriangle(fan[i], false, false);
                            m.AppendTriangle(t.a == vid ? copy : t.a, t.b == vid ? copy : t.b, t.c == vid ? copy : t.c);
                        }
                    }
                    return m;
                }
                case Family.VertexOnFace: {
                    // a box, and an octahedron whose lowest vertex lies on the box's top face (or 2^-k above it)
                    DMesh3 m = Box(Vector3d.Zero, Vector3d.One);
                    double x = 0.3 + 0.05 * (seed % 7), y = 0.35 + 0.04 * (seed % 5), r = 0.2;
                    var o = new Vector3d(x, y, 1 + r + (k > 0 ? h : 0));
                    var oct = new DMesh3();
                    Vector3d[] p = { o + r * Vector3d.AxisX, o + r * Vector3d.AxisY, o - r * Vector3d.AxisX,
                                     o - r * Vector3d.AxisY, o + r * Vector3d.AxisZ, o - r * Vector3d.AxisZ };
                    foreach (Vector3d q in p) oct.AppendVertex(q);
                    for (int i = 0; i < 4; i++) {
                        oct.AppendTriangle(i, (i + 1) % 4, 4);
                        oct.AppendTriangle((i + 1) % 4, i, 5);
                    }
                    MeshEditor.Append(m, oct);
                    return m;
                }
                case Family.Cluster:
                case Family.FoldedCluster: {
                    // dense clusters: a triangle poked count times in a row, each new vertex near an edge of the
                    // triangle it pokes, so fans of slivers and zero-area triangles touch each other. Cluster: 2^-k of
                    // the way from the edge to the opposite corner (inside, the surface does not fold); FoldedCluster:
                    // 2^-k from the edge (outside slivers thinner than that: the surface folds over itself)
                    DMesh3 m = Sphere(6);
                    var rnd = new Random(seed);
                    foreach (int t0 in m.TriangleIndices().Where(t => (t + seed) % 17 == 0).ToArray()) {
                        int tid = t0;
                        for (int i = 0; i < count; i++) {
                            Index3i t = m.GetTriangle(tid);
                            Vector3d a = m.GetVertex(t.a), b = m.GetVertex(t.b), c = m.GetVertex(t.c);
                            Vector3d onEdge = a + (0.2 + 0.6 * rnd.NextDouble()) * (b - a);
                            Vector3d p = k == 0 ? onEdge : f == Family.Cluster ? onEdge + h * (c - onEdge) : onEdge + h * (c - onEdge).Normalized;
                            if (m.PokeTriangle(tid, out DMesh3.PokeTriangleInfo info) != MeshResult.Ok) break;
                            m.SetVertex(info.new_vid, p);
                            tid = rnd.Next(3) == 0 ? info.new_t1 : rnd.Next(2) == 0 ? info.new_t2 : tid;
                        }
                    }
                    return m;
                }
                case Family.SharedFace: {
                    // two boxes in one mesh that share a region of a face (or are 2^-k apart)
                    DMesh3 m = Box(Vector3d.Zero, Vector3d.One);
                    double x = 0.1 * (seed % 5), y = 0.15 * (seed % 3);
                    MeshEditor.Append(m, Box(new Vector3d(x, y, 1 + (k > 0 ? h : 0)), new Vector3d(x + 0.6, y + 0.5, 1.7)));
                    return m;
                }
            }
            throw new ArgumentException(f.ToString());
        }

    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Text;

namespace geometry3Sharp.Tests
{
    /// <summary> options of MeshMinimizer and DeltaDebug.MinimizeBytes (docs/QA.md 2.9) </summary>
    public sealed class MinimizeOptions
    {
        /// <summary>
        /// The whole run stops after this and returns the smallest failing input found so far. It is checked before each
        /// predicate call, so a run can overshoot by one call (at most PredicateTimeout).
        /// </summary>
        public TimeSpan TimeBudget = TimeSpan.FromSeconds(60);
        /// <summary> one predicate call; zero or less runs the predicate on the calling thread without a timeout </summary>
        public TimeSpan PredicateTimeout = TimeSpan.FromSeconds(10);
        /// <summary>
        /// A predicate that throws is a different error, not the one being minimized (false), unless this is set. A
        /// predicate that reproduces a crash should catch it and compare it with the original (see FailureMinimizer).
        /// </summary>
        public bool ExceptionMeansFailure = false;
        /// <summary> a predicate call that does not finish within PredicateTimeout is a different error, unless this is set </summary>
        public bool TimeoutMeansFailure = false;
        /// <summary> a call that times out keeps running (it cannot be cancelled): stop after this many </summary>
        public int MaxTimeouts = 3;
        /// <summary> 0 keeps the input order; another value shuffles the order in which subsets are tried (reproducibly) </summary>
        public int Seed = 0;
        /// <summary> MeshMinimizer: round the coordinates to coarser grids while the error persists </summary>
        public bool SimplifyCoordinates = true;
    }

    /// <summary>
    /// A predicate ("the error is still present") with the policies of MinimizeOptions: time budget, timeout,
    /// exceptions. Counts the calls.
    /// </summary>
    public sealed class Probe<T>
    {
        readonly Func<T, bool> predicate;
        readonly MinimizeOptions options;
        readonly Stopwatch clock = Stopwatch.StartNew();

        public int Evaluations, Exceptions, Timeouts;
        /// <summary> the first exception a predicate threw (for the report) </summary>
        public Exception FirstException;

        public Probe(Func<T, bool> predicate, MinimizeOptions options)
        {
            this.predicate = predicate;
            this.options = options;
        }

        public TimeSpan Elapsed => clock.Elapsed;
        public bool BudgetExhausted => clock.Elapsed >= options.TimeBudget;
        public bool TimeoutLimitReached => Timeouts >= options.MaxTimeouts;
        public bool Stopped => BudgetExhausted || TimeoutLimitReached;

        /// <summary> true if the error is present in input </summary>
        public bool Fails(T input)
        {
            ++Evaluations;
            bool result = false;
            Exception error = null;
            Action run = () => {
                try { result = predicate(input); } catch (Exception e) { error = e; }
            };
            if (options.PredicateTimeout <= TimeSpan.Zero)
                run();
            else if (Timed.Finishes(run, options.PredicateTimeout) == false) {
                ++Timeouts;
                return options.TimeoutMeansFailure;
            }
            if (error != null) {
                ++Exceptions;
                if (FirstException == null) FirstException = error;
                return options.ExceptionMeansFailure;
            }
            return result;
        }
    }

    /// <summary>
    /// Delta debugging: ddmin of Zeller and Hildebrandt, "Simplifying and Isolating Failure-Inducing Input" (IEEE TSE
    /// 28(2), 2002). Implemented from the paper.
    /// </summary>
    public static class DeltaDebug
    {
        /// <summary>
        /// A 1-minimal failing subset of items (removing any single item makes the error disappear), unless stop() ends
        /// the search early: then the smallest failing subset found so far. items itself must fail (not checked). fails
        /// gets the subsets in the order of items. tryEmpty tests the empty subset first.
        /// </summary>
        public static List<T> Minimize<T>(IReadOnlyList<T> items, Func<List<T>, bool> fails, Func<bool> stop, int seed = 0, bool tryEmpty = true)
        {
            var c = Enumerable.Range(0, items.Count).ToList();
            if (seed != 0) {
                var rand = new Random(seed);
                c = c.OrderBy(i => rand.Next()).ToList();
            }
            // every subset is tested once: a failing one becomes c, and later candidates are strict subsets of it, so a
            // subset seen before did not fail. (Keyed by a 64-bit hash, not the index list, which needs O(n^2) memory for
            // byte inputs; a collision only skips a test, the result still fails.)
            var tested = new HashSet<ulong>();
            bool Fails(List<int> s)
            {
                List<int> sorted = s.OrderBy(i => i).ToList();
                if (tested.Add(Hash(sorted)) == false) return false;
                return fails(sorted.Select(i => items[i]).ToList());
            }
            List<T> Result() => c.OrderBy(i => i).Select(i => items[i]).ToList();

            if (tryEmpty && c.Count > 0 && stop() == false && Fails(new List<int>()))
                return new List<T>();
            int n = 2;
            while (c.Count >= 2 && stop() == false) {
                List<List<int>> chunks = Split(c, n);
                bool reduced = false;
                for (int i = 0; i < chunks.Count && reduced == false && stop() == false; ++i)
                    if (Fails(chunks[i])) { c = chunks[i]; n = 2; reduced = true; }
                // (with two chunks the complements are the chunks)
                if (chunks.Count > 2)
                    for (int i = 0; i < chunks.Count && reduced == false && stop() == false; ++i) {
                        List<int> complement = chunks.Where((_, j) => j != i).SelectMany(x => x).ToList();
                        if (Fails(complement)) { c = complement; n = Math.Max(n - 1, 2); reduced = true; }
                    }
                if (reduced == false) {
                    if (n >= c.Count) break;
                    n = Math.Min(2 * n, c.Count);
                }
            }
            return Result();
        }

        // FNV-1a over the indices and the count
        static ulong Hash(List<int> s)
        {
            ulong h = 14695981039346656037UL;
            foreach (int i in s) { h ^= (uint)i; h *= 1099511628211UL; }
            h ^= (uint)s.Count; h *= 1099511628211UL;
            return h;
        }

        /// <summary> c in n contiguous chunks of almost equal size </summary>
        static List<List<int>> Split(List<int> c, int n)
        {
            var chunks = new List<List<int>>();
            int start = 0;
            for (int i = 0; i < n; ++i) {
                int end = (int)((long)c.Count * (i + 1) / n);
                if (end > start) chunks.Add(c.GetRange(start, end - start));
                start = end;
            }
            return chunks;
        }

        /// <summary> the result of MinimizeBytes </summary>
        public sealed class BytesResult
        {
            public bool Reproduced;
            public byte[] Data;
            public int Evaluations, Exceptions, Timeouts;
            public bool BudgetExhausted;
            public TimeSpan Elapsed;
        }

        /// <summary>
        /// A small input for which fails is still true: for text, ddmin over lines first, then over bytes; for binary
        /// input over bytes. fails gets a fresh array on every call.
        /// </summary>
        public static BytesResult MinimizeBytes(byte[] data, Func<byte[], bool> fails, bool text, MinimizeOptions options = null)
        {
            options = options ?? new MinimizeOptions();
            var probe = new Probe<byte[]>(fails, options);
            var result = new BytesResult();
            byte[] current = data;
            if (probe.Fails((byte[])data.Clone())) {
                result.Reproduced = true;
                if (text) {
                    List<byte[]> lines = Lines(data);
                    current = Minimize(lines, s => probe.Fails(s.SelectMany(x => x).ToArray()), () => probe.Stopped, options.Seed)
                        .SelectMany(x => x).ToArray();
                }
                current = Minimize(current, s => probe.Fails(s.ToArray()), () => probe.Stopped, options.Seed).ToArray();
            }
            result.Data = current;
            result.Evaluations = probe.Evaluations;
            result.Exceptions = probe.Exceptions;
            result.Timeouts = probe.Timeouts;
            result.BudgetExhausted = probe.Stopped;
            result.Elapsed = probe.Elapsed;
            return result;
        }

        /// <summary> the lines of data, each with its '\n' </summary>
        static List<byte[]> Lines(byte[] data)
        {
            var lines = new List<byte[]>();
            int start = 0;
            for (int i = 0; i < data.Length; ++i)
                if (data[i] == (byte)'\n') { lines.Add(data.Skip(start).Take(i + 1 - start).ToArray()); start = i + 1; }
            if (start < data.Length) lines.Add(data.Skip(start).ToArray());
            return lines;
        }

        /// <summary> data as a C# expression: a string literal for printable ASCII text, else a byte array </summary>
        public static string ToCSharp(byte[] data)
        {
            bool printable = data.All(b => b == '\n' || b == '\r' || b == '\t' || (b >= 32 && b < 127));
            var sb = new StringBuilder();
            if (printable) {
                sb.Append("System.Text.Encoding.ASCII.GetBytes(\"");
                foreach (byte b in data) {
                    switch ((char)b) {
                        case '\n': sb.Append("\\n"); break;
                        case '\r': sb.Append("\\r"); break;
                        case '\t': sb.Append("\\t"); break;
                        case '"': sb.Append("\\\""); break;
                        case '\\': sb.Append("\\\\"); break;
                        default: sb.Append((char)b); break;
                    }
                }
                sb.Append("\")");
            } else {
                sb.Append("new byte[] {");
                for (int i = 0; i < data.Length; ++i) {
                    if (i % 16 == 0) sb.Append("\n    ");
                    sb.Append("0x").Append(data[i].ToString("X2")).Append(i + 1 < data.Length ? ", " : "");
                }
                sb.Append("\n}");
            }
            return sb.ToString();
        }
    }
}

using System;
using System.IO;
using System.Text.RegularExpressions;
using g3;
using Xunit.Sdk;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Couples MeshMinimizer to the defect and fuzz tests (docs/QA.md 2.9): with G3_MINIMIZE=1, a failing check is
    /// minimized and the failure message gets the minimal case as C# code (also written to MeshMinimizer.ReproDirectory()).
    /// </summary>
    public static class FailureMinimizer
    {
        public static bool Enabled => Environment.GetEnvironmentVariable("G3_MINIMIZE") == "1";

        /// <summary>
        /// the options of one minimization: G3_MINIMIZE_SECONDS the time budget (default 120), G3_MINIMIZE_ROUND=0 keeps
        /// the coordinates (rounding makes a case readable, but can turn it into a degenerate one with the same message)
        /// </summary>
        public static MinimizeOptions Options() => new MinimizeOptions() {
            TimeBudget = TimeSpan.FromSeconds(int.TryParse(Environment.GetEnvironmentVariable("G3_MINIMIZE_SECONDS"), out int s) && s > 0 ? s : 120),
            SimplifyCoordinates = Environment.GetEnvironmentVariable("G3_MINIMIZE_ROUND") != "0"
        };

        /// <summary>
        /// "the same error": the exception type and its message with every number replaced by '#' and the whitespace
        /// collapsed (counts, ids and the column markers of xunit's string comparisons change while the input shrinks).
        /// The whole message, since eg Assert.Equal("", problem) has the problem only in its later lines.
        /// </summary>
        public static string Signature(Exception e) => e.GetType().FullName + ": " + Signature(e.Message);

        public static string Signature(string message)
        {
            string masked = Regex.Replace(message ?? "", @"[-+]?\d+(\.\d+)?([eE][-+]?\d+)?", "#");
            return Regex.Replace(masked, @"\s+", " ").Trim();
        }

        /// <summary>
        /// Runs check on make(). If it throws and minimization is enabled, the mesh is minimized while check throws an
        /// exception with the same Signature, and an XunitException with the original message and the C# repro is thrown.
        /// </summary>
        public static void Check(string name, Func<DMesh3> make, Action<DMesh3> check) => Check(name, make, check, Enabled, null);

        public static void Check(string name, Func<DMesh3> make, Action<DMesh3> check, bool enabled, MinimizeOptions options)
        {
            if (enabled == false) { check(make()); return; }
            Exception failure;
            var clock = System.Diagnostics.Stopwatch.StartNew();
            try { check(make()); return; } catch (Exception e) { failure = e; }
            string signature = Signature(failure);
            string report;
            try {
                options = options ?? Options();
                // a slow check must not time out on the input itself
                if (options.PredicateTimeout > TimeSpan.Zero && options.PredicateTimeout < TimeSpan.FromTicks(3 * clock.Elapsed.Ticks))
                    options.PredicateTimeout = TimeSpan.FromTicks(3 * clock.Elapsed.Ticks);
                MeshMinimizer.Result r = MeshMinimizer.Minimize(make(), m => {
                    try { check(m); return false; } catch (Exception e) { return Signature(e) == signature; }
                }, options);
                string code = MeshMinimizer.ToCSharp(r.Mesh, "Minimized" + MeshMinimizer.Identifier(name),
                    $"\"{name}\" minimized by MeshMinimizer ({r}):\n{failure.GetType().FullName}: {failure.Message.Split('\n')[0]}");
                string path = MeshMinimizer.WriteRepro(name, r.Mesh, code);
                report = $"minimized ({r}), written to {path}:\n{code}";
            } catch (Exception e) {
                // the minimizer must not hide the failure
                report = "minimizing failed: " + e;
            }
            throw new XunitException($"{failure.Message}\n\n{report}\n\noriginal stack trace:\n{failure.StackTrace}");
        }

        /// <summary>
        /// For a failing reader input: data minimized while check returns a failure with the same Signature, as a C#
        /// expression (also written to MeshMinimizer.ReproDirectory() as name.extension). Returns the report text.
        /// </summary>
        public static string BytesReport(string name, string extension, byte[] data, string failure, Func<byte[], string> check, bool text, MinimizeOptions options = null)
        {
            string signature = Signature(failure);
            // (check times itself: no second timeout around it)
            if (options == null) { options = Options(); options.PredicateTimeout = TimeSpan.Zero; }
            DeltaDebug.BytesResult r = DeltaDebug.MinimizeBytes(data, d => Signature(check(d)) == signature, text, options);
            if (r.Reproduced == false)
                return "not reproduced by the minimizer";
            string path = Path.Combine(MeshMinimizer.ReproDirectory(), MeshMinimizer.Identifier(name) + "." + extension);
            File.WriteAllBytes(path, r.Data);
            return $"minimized to {r.Data.Length} of {data.Length} bytes ({r.Evaluations} evaluations{(r.BudgetExhausted ? ", stopped" : "")}), written to {path}: "
                + DeltaDebug.ToCSharp(r.Data);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// A rigid motion plus uniform scale applied to a test input, with the inverse for the results. Invariance tests
    /// run an operation on the original and on transformed copies and compare the results, mapped back, with each
    /// other (not with absolute bounds, which hide scale dependence; see docs/QA.md).
    /// </summary>
    public sealed class Similarity
    {
        public readonly string Name;
        public readonly double Scale;
        public readonly Matrix3d Rotation;
        public readonly Vector3d Translation;

        public Similarity(string name, double scale, Matrix3d rotation, Vector3d translation)
        {
            Name = name; Scale = scale; Rotation = rotation; Translation = translation;
        }

        public Vector3d Apply(Vector3d p) => Scale * (Rotation * p) + Translation;
        public Vector3d Inverse(Vector3d p) => Rotation.Transpose() * ((p - Translation) / Scale);
        public Vector3d ApplyDirection(Vector3d d) => Rotation * d;
        public double ApplyLength(double l) => Scale * l;

        public override string ToString() => Name;

        /// <summary>
        /// True for scaling by a power of two (no rotation, no translation): exact in floating point, so a method
        /// without absolute constants gives the same result, scaled, up to the last bits.
        /// </summary>
        public bool IsExact
        {
            get {
                if (Translation != Vector3d.Zero || Rotation.EpsilonEqual(Matrix3d.Identity, 0) == false) return false;
                double m = Math.Log(Scale, 2);
                return Math.Abs(m - Math.Round(m)) < 1e-12;
            }
        }

        /// <summary>
        /// The rounding unit of a transformed coordinate, mapped back to the input's units, for an input of the given
        /// size around the origin: a comparison of results cannot be tighter than a small multiple of this.
        /// </summary>
        public double Resolution(double size)
        {
            double magnitude = Math.Max(Math.Abs(Translation.x), Math.Max(Math.Abs(Translation.y), Math.Abs(Translation.z))) + Scale * size;
            return magnitude * MathUtil.Epsilon / Scale;
        }

        public static readonly Similarity Identity = new Similarity("identity", 1, Matrix3d.Identity, Vector3d.Zero);

        /// <summary>UTM-like coordinates (zone 32U), where float-precision code loses millimetres.</summary>
        public static readonly Similarity Utm = new Similarity("utm", 1, Matrix3d.Identity, new Vector3d(632117.25, 5712043.5, 113.75));
        /// <summary>Scaling by a power of two is exact in floating point: a scale-invariant method gives the same result, scaled, bit for bit.</summary>
        public static readonly Similarity Pow2Small = new Similarity("scale 2^-10", 1.0 / 1024, Matrix3d.Identity, Vector3d.Zero);
        public static readonly Similarity Pow2Large = new Similarity("scale 2^10", 1024, Matrix3d.Identity, Vector3d.Zero);
        public static readonly Similarity Millimetre = new Similarity("scale 1e-3", 1e-3, Matrix3d.Identity, Vector3d.Zero);
        public static readonly Similarity Kilometre = new Similarity("scale 1e3", 1e3, Matrix3d.Identity, Vector3d.Zero);
        public static readonly Similarity Rotated = new Similarity("rotated",
            1, Matrix3d.AxisAngleD(Vector3d.AxisZ, 31) * Matrix3d.AxisAngleD(Vector3d.AxisX, 17), Vector3d.Zero);
        public static readonly Similarity RotatedUtmMillimetre = new Similarity("rotated, scale 1e-3, utm",
            1e-3, Matrix3d.AxisAngleD(Vector3d.AxisY, 23), new Vector3d(632117.25, 5712043.5, 113.75));

        public static IEnumerable<Similarity> All()
        {
            yield return Identity;
            yield return Utm;
            yield return Pow2Small;
            yield return Pow2Large;
            yield return Millimetre;
            yield return Kilometre;
            yield return Rotated;
            yield return RotatedUtmMillimetre;
        }

        /// <summary>
        /// The resolution of Invariance.VertexDistance for an input of the given size: point-triangle distances come
        /// from squared distances with cancellation, so their rounding noise is the square root of the coordinate
        /// resolution times the size (about 1e-8 * size), not the resolution itself.
        /// </summary>
        public double DistanceResolution(double size) => 8 * Math.Sqrt(Resolution(size) * size);

        public bool IsRotated => Rotation.EpsilonEqual(Matrix3d.Identity, 0) == false;

        /// <summary>For xunit [MemberData]: the names of All().</summary>
        public static IEnumerable<object[]> Names() => All().Select(s => new object[] { s.Name });

        public static Similarity ByName(string name) => All().First(s => s.Name == name);
    }

    public static class Invariance
    {
        /// <summary>A copy of the mesh with transformed vertices (normals rotated); ids and attributes kept.</summary>
        public static DMesh3 Transformed(DMesh3 mesh, Similarity s)
        {
            var copy = new DMesh3(mesh);
            foreach (int vid in copy.VertexIndices()) {
                copy.SetVertex(vid, s.Apply(copy.GetVertex(vid)));
                if (copy.HasVertexNormals)
                    copy.SetVertexNormal(vid, (Vector3f)s.ApplyDirection(copy.GetVertexNormal(vid)));
            }
            return copy;
        }

        /// <summary>A copy of the mesh mapped back with the inverse transform.</summary>
        public static DMesh3 MappedBack(DMesh3 mesh, Similarity s)
        {
            var copy = new DMesh3(mesh);
            foreach (int vid in copy.VertexIndices())
                copy.SetVertex(vid, s.Inverse(copy.GetVertex(vid)));
            return copy;
        }

        /// <summary>
        /// The same surface with vertices and triangles in a random order (compact ids). Each triangle's corners are
        /// rotated cyclically, so orientation is kept. Results must not depend on the input order beyond ties.
        /// </summary>
        public static DMesh3 Permuted(DMesh3 mesh, int seed)
        {
            var rand = new Random(seed);
            int[] vids = mesh.VertexIndices().OrderBy(v => rand.Next()).ToArray();
            var map = new Dictionary<int, int>();
            var result = new DMesh3();
            foreach (int v in vids)
                map[v] = result.AppendVertex(mesh.GetVertex(v));
            foreach (int t in mesh.TriangleIndices().OrderBy(t => rand.Next()).ToArray()) {
                Index3i tri = mesh.GetTriangle(t);
                int k = rand.Next(3);
                result.AppendTriangle(new Index3i(map[tri[k]], map[tri[(k + 1) % 3]], map[tri[(k + 2) % 3]]));
            }
            return result;
        }

        /// <summary>Signed volume (divergence theorem), computed relative to the bounds center so that it stays accurate far from the origin.</summary>
        public static double Volume(DMesh3 mesh)
        {
            Vector3d c = mesh.TriangleCount > 0 ? MeshRepairMetrics.TriangleBounds(mesh).Center : Vector3d.Zero;
            double v = 0;
            Vector3d a = Vector3d.Zero, b = Vector3d.Zero, d = Vector3d.Zero;
            foreach (int t in mesh.TriangleIndices()) {
                mesh.GetTriVertices(t, ref a, ref b, ref d);
                v += (a - c).Dot((b - c).Cross(d - c));
            }
            return v / 6;
        }

        public static double Area(DMesh3 mesh) => mesh.TriangleIndices().Sum(t => mesh.GetTriArea(t));

        /// <summary>Every vertex coordinate is finite.</summary>
        public static bool AllFinite(DMesh3 mesh) => mesh.Vertices().All(v => v.IsFinite);

        /// <summary>
        /// Bit-exact equality of two meshes: same vertex and triangle ids, same coordinates, same triangles.
        /// Used by the determinism tests (repeated runs, parallel vs serial).
        /// </summary>
        public static string Difference(DMesh3 x, DMesh3 y)
        {
            if (x.VertexCount != y.VertexCount) return $"vertex count {x.VertexCount} vs {y.VertexCount}";
            if (x.TriangleCount != y.TriangleCount) return $"triangle count {x.TriangleCount} vs {y.TriangleCount}";
            if (x.MaxVertexID != y.MaxVertexID || x.MaxTriangleID != y.MaxTriangleID) return "id spaces differ";
            for (int v = 0; v < x.MaxVertexID; ++v) {
                if (x.IsVertex(v) != y.IsVertex(v)) return $"vertex {v} exists in one mesh only";
                if (x.IsVertex(v) && x.GetVertex(v) != y.GetVertex(v)) return $"vertex {v}: {x.GetVertex(v)} vs {y.GetVertex(v)}";
            }
            for (int t = 0; t < x.MaxTriangleID; ++t) {
                if (x.IsTriangle(t) != y.IsTriangle(t)) return $"triangle {t} exists in one mesh only";
                if (x.IsTriangle(t) && x.GetTriangle(t) != y.GetTriangle(t)) return $"triangle {t}: {x.GetTriangle(t)} vs {y.GetTriangle(t)}";
            }
            return "";
        }

        /// <summary>
        /// Equality of two meshes as sets of oriented triangles (exact coordinates), independent of vertex and triangle
        /// ids and of the starting corner of each triangle. For outputs whose id order may follow the thread schedule.
        /// </summary>
        public static string GeometricDifference(DMesh3 x, DMesh3 y)
        {
            List<string> a = CanonicalTriangles(x), b = CanonicalTriangles(y);
            if (a.Count != b.Count) return $"triangle count {a.Count} vs {b.Count}";
            for (int i = 0; i < a.Count; ++i)
                if (a[i] != b[i]) return $"triangle {a[i]} vs {b[i]}";
            return "";
        }

        static List<string> CanonicalTriangles(DMesh3 mesh)
        {
            var result = new List<string>();
            Vector3d[] p = new Vector3d[3];
            foreach (int t in mesh.TriangleIndices()) {
                Index3i tri = mesh.GetTriangle(t);
                for (int k = 0; k < 3; ++k) p[k] = mesh.GetVertex(tri[k]);
                int first = 0;
                for (int k = 1; k < 3; ++k)
                    if (Compare(p[k], p[first]) < 0) first = k;
                result.Add(string.Join(" ", Enumerable.Range(0, 3).Select(k => Key(p[(first + k) % 3]))));
            }
            result.Sort(StringComparer.Ordinal);
            return result;
        }

        static int Compare(Vector3d u, Vector3d v)
        {
            int c = u.x.CompareTo(v.x);
            if (c == 0) c = u.y.CompareTo(v.y);
            if (c == 0) c = u.z.CompareTo(v.z);
            return c;
        }

        // (+ 0.0 maps -0.0 to +0.0, which Compare treats as equal: a translation turns -0.0 into +0.0)
        static string Key(Vector3d v) =>
            BitConverter.DoubleToInt64Bits(v.x + 0.0).ToString("X16") + BitConverter.DoubleToInt64Bits(v.y + 0.0).ToString("X16") + BitConverter.DoubleToInt64Bits(v.z + 0.0).ToString("X16");

        /// <summary>
        /// Symmetric Hausdorff-like distance by sampling the vertices of each mesh against the other's triangles.
        /// Rounding noise is about 1e-8 times the size (Similarity.DistanceResolution).
        /// </summary>
        public static double VertexDistance(DMesh3 x, DMesh3 y)
        {
            return Math.Max(OneSided(x, y), OneSided(y, x));
        }

        static double OneSided(DMesh3 from, DMesh3 to)
        {
            var tree = new DMeshAABBTree3(to, true);
            double max = 0;
            foreach (Vector3d p in from.Vertices()) {
                int tid = tree.FindNearestTriangle(p);
                max = Math.Max(max, Math.Sqrt(MeshQueries.TriDistanceSqr(to, tid, p)));
            }
            return max;
        }
    }
}

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Shared rule of the *IssueCasesTests classes (docs/QA.md 2.11): their KnownFailures lists, and the specific wrong
    /// outcomes they pin, are taken on net10. On .NET Framework (the net48 CI job) the last bits of transcendental
    /// functions and some casts differ, so a listed case may fail with other numbers or not at all: there the lists are
    /// not strict, as in RobustnessSweepTests. Unlisted cases are checked on both.
