                double rad = (k % 2 == 0) ? 1 : 0.3;
                ring[k] = mesh.AppendVertex(new Vector3d(rad * Math.Cos(a), rad * Math.Sin(a), (k % 2 == 0) ? 0.6 : -0.2));
            }
