        static DMesh3 SphereAt(double x) { DMesh3 m = Sphere(); MeshTransforms.Translate(m, new Vector3d(x, 0, 0)); return m; }

        static DMesh3 HillTerrain()
        {
            int n = 21;
            var mesh = new DMesh3();
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i)
                    mesh.AppendVertex(new Vector3d(i, j, 0.1 * i));
            for (int j = 0; j + 1 < n; ++j)
