using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// MeshAutoRepair tolerances: relative to the size of the mesh by default (the same model in mm, um, km or far
    /// from the origin is repaired the same way), absolute when set explicitly or with ToleranceModes.Absolute.
    /// </summary>
    public class MeshAutoRepairToleranceTests
    {
        /// <summary>
        /// A unit sphere cut into two halves (x &gt; 0 and the rest) whose seam vertices are moved apart by gap: a
        /// crack that the crack merging closes if gap is below the repair tolerance.
        /// </summary>
        static DMesh3 CrackedSphere(double gap)
        {
            DMesh3 m = Defects.Sphere(Vector3d.Zero, 1);
            var s = new Defects.Soup();
            var map = new Dictionary<int, int>();
            var moved = new Dictionary<int, int>();
            foreach (int v in m.VertexIndices()) map[v] = s.AddVertex(m.GetVertex(v));
            Vector3d dir = new Vector3d(1, 1, 1).Normalized;
            foreach (int t in m.TriangleIndices()) {
                Index3i tv = m.GetTriangle(t);
                bool right = m.GetTriCentroid(t).x > 0;
                int vid(int v)
                {
                    if (right == false) return map[v];
                    // a seam vertex: also used by a triangle of the other half
                    bool seam = m.VtxTrianglesItr(v).Any(o => m.GetTriCentroid(o).x <= 0);
                    if (seam == false) return map[v];
                    if (moved.TryGetValue(v, out int c) == false)
                        moved[v] = c = s.AddVertex(m.GetVertex(v) + gap * dir);
                    return c;
                }
                s.T.Add(new Index3i(vid(tv.a), vid(tv.b), vid(tv.c)));
            }
            return s.ToMesh();
        }

        /// <summary> a unit sphere and a closed speck 1e-4 across next to it (MinEdgeLengthTol of 1.0.324 collapses it) </summary>
        static DMesh3 SphereAndSpeck()
        {
            DMesh3 m = Defects.Sphere(Vector3d.Zero, 1);
            MeshEditor.Append(m, Defects.Sphere(new Vector3d(3, 0, 0), 5e-5, 3));
            return m;
        }

        static IEnumerable<(string name, Func<DMesh3> make)> Cases()
        {
            // a crack of 1e-8 (relative tolerance 1e-8 * diagonal 3.5): merged at every scale; with the absolute 1e-6
            // of 1.0.324 not in km
            yield return ("crack", () => CrackedSphere(1e-8));
            // global orientation: in um the triangles of 1.0.324 were all below the absolute area threshold
            yield return ("inside-out", () => Defects.ByName("inside-out").Make());
            yield return ("sphere and speck", SphereAndSpeck);
            yield return ("T-junction", () => Defects.ByName("T-junction").Make());
            yield return ("triangle soup", () => Defects.ByName("triangle soup").Make());
        }

        public static IEnumerable<object[]> CaseNames() =>
            from s in Similarity.All() from c in Cases() select new object[] { s.Name, c.name };

        static MeshAutoRepair Repair(DMesh3 mesh)
        {
            var r = new MeshAutoRepair(mesh);
            Assert.True(r.Apply());
            return r;
        }

        static void AssertClosedSolid(DMesh3 mesh, string what)
        {
            Assert.True(mesh.TriangleCount > 0, what + ": empty");
            Assert.True(mesh.IsClosed(), what + ": not closed");
            Assert.True(Invariance.AllFinite(mesh), what + ": non-finite coordinates");
            Assert.False(mesh.VertexIndices().Any(v => mesh.IsBowtieVertex(v)), what + ": bowtie");
            Assert.True(Invariance.Volume(mesh) > 0, what + ": not outward oriented");
        }

        [Theory]
        [MemberData(nameof(CaseNames))]
        public void SameResultUnderSimilarity(string sname, string cname)
        {
            Similarity s = Similarity.ByName(sname);
            Func<DMesh3> make = Cases().First(c => c.name == cname).make;
            MeshAutoRepair r0 = Repair(make());
            AssertClosedSolid(r0.Mesh, cname);

            MeshAutoRepair r = Repair(Invariance.Transformed(make(), s));
            AssertClosedSolid(r.Mesh, $"{cname}, {s.Name}");
            Assert.Equal(r0.Mesh.TriangleCount, r.Mesh.TriangleCount);
            Assert.Equal(r0.Mesh.VertexCount, r.Mesh.VertexCount);
            DMesh3 back = Invariance.MappedBack(r.Mesh, s);
            if (s.IsExact) {
                // a power of two: the tolerances scale exactly, so the result is the same bit for bit
                Assert.Equal(s.ApplyLength(r0.EffectiveRepairTolerance), r.EffectiveRepairTolerance);
                Assert.Equal(s.ApplyLength(r0.EffectiveMinEdgeLength), r.EffectiveMinEdgeLength);
                Assert.Equal("", Invariance.GeometricDifference(r0.Mesh, back));
            }
            double dist = Invariance.VertexDistance(r0.Mesh, back);
            Assert.True(dist <= s.DistanceResolution(4), $"{cname}, {s.Name}: results {dist} apart");
        }

        [Fact]
        public void RelativeTolerances_AreFractionsOfTheTriangleDiagonal()
        {
            DMesh3 m = CrackedSphere(1e-8);
            // an unused vertex far away does not count
            m.AppendVertex(new Vector3d(1e6, 0, 0));
            double diag = MeshRepairMetrics.TriangleBounds(m).DiagonalLength;
            MeshAutoRepair r = Repair(m);
            Assert.Equal(1e-8 * diag, r.EffectiveRepairTolerance);
            Assert.Equal(1e-6 * diag, r.EffectiveMinEdgeLength);

            var r2 = new MeshAutoRepair(CrackedSphere(1e-8)) { RelativeRepairTolerance = 1e-9, RelativeMinEdgeLength = 0 };
            Assert.True(r2.Apply());
            Assert.Equal(1e-9 * diag, r2.EffectiveRepairTolerance);
            Assert.Equal(0, r2.EffectiveMinEdgeLength);
        }

        [Fact]
        public void RelativeTolerance_FarFromTheOrigin_AtLeastTheCoordinateResolution()
        {
            // a tiny model in UTM coordinates: 1e-8 of its diagonal is below the rounding unit of its coordinates
            DMesh3 m = CrackedSphere(1e-8);
            MeshTransforms.Scale(m, 1e-3);
            MeshTransforms.Translate(m, new Vector3d(632117.25, 5712043.5, 113.75));
            MeshAutoRepair r = Repair(m);
            Assert.Equal(16 * MathUtil.Epsilon * 5712043.5, r.EffectiveRepairTolerance, 12);
            AssertClosedSolid(r.Mesh, "utm");
        }

        [Fact]
        public void ExplicitAbsoluteTolerances_AreUsedAsGiven()
        {
            // in km the crack is 1e-5 wide: the relative default closes it, the absolute 1e-6 of 1.0.324 does not
            DMesh3 Km() { DMesh3 m = CrackedSphere(1e-8); MeshTransforms.Scale(m, 1e3); return m; }
            MeshAutoRepair rel = Repair(Km());
            Assert.Equal(1e-8 * MeshRepairMetrics.TriangleBounds(Km()).DiagonalLength, rel.EffectiveRepairTolerance);

            // a value other than the 1.0.324 default is absolute
            var abs = new MeshAutoRepair(Km()) { RepairTolerance = 2e-6 };
            Assert.True(abs.Apply());
            Assert.Equal(2e-6, abs.EffectiveRepairTolerance);
            Assert.Equal(1e-6 * MeshRepairMetrics.TriangleBounds(Km()).DiagonalLength, abs.EffectiveMinEdgeLength);

            // exactly the default counts as not set (fields, binary compatible with 1.0.324): relative
            var same = new MeshAutoRepair(Km()) { RepairTolerance = MathUtil.ZeroTolerancef, MinEdgeLengthTol = 1e-4 };
            Assert.True(same.Apply());
            Assert.Equal(rel.EffectiveRepairTolerance, same.EffectiveRepairTolerance);
            Assert.Equal(rel.EffectiveMinEdgeLength, same.EffectiveMinEdgeLength);

            // ToleranceModes.Absolute: the 1.0.324 values
            var mode = new MeshAutoRepair(Km()) { ToleranceMode = MeshAutoRepair.ToleranceModes.Absolute };
            Assert.True(mode.Apply());
            Assert.Equal(MathUtil.ZeroTolerancef, mode.EffectiveRepairTolerance);
            Assert.Equal(1e-4, mode.EffectiveMinEdgeLength);

            // the crack merge welds the seam; without it the crack is filled as holes (more vertices)
            int welded = rel.Mesh.VertexCount, unwelded = abs.Mesh.VertexCount;
            Assert.Equal(Defects.Sphere(Vector3d.Zero, 1).VertexCount, welded);
            Assert.True(unwelded > welded, $"absolute 1e-6: {unwelded} vertices, relative: {welded}");
            Assert.Equal(unwelded, mode.Mesh.VertexCount);

            // MinEdgeLengthTol set explicitly: the speck (edges below 2e-4) is collapsed, the relative
            // default keeps it
            int sphereTris = Defects.Sphere(Vector3d.Zero, 1).TriangleCount;
            MeshAutoRepair keep = Repair(SphereAndSpeck());
            Assert.True(keep.Mesh.TriangleCount > sphereTris);
            var collapse = new MeshAutoRepair(SphereAndSpeck()) { MinEdgeLengthTol = 2e-4 };
            Assert.True(collapse.Apply());
            Assert.Equal(2e-4, collapse.EffectiveMinEdgeLength);
            Assert.Equal(1e-8 * MeshRepairMetrics.TriangleBounds(SphereAndSpeck()).DiagonalLength, collapse.EffectiveRepairTolerance);
            Assert.True(collapse.Mesh.TriangleCount < keep.Mesh.TriangleCount,
                $"MinEdgeLengthTol 2e-4: {collapse.Mesh.TriangleCount} triangles, relative: {keep.Mesh.TriangleCount}");
        }

        [Fact]
        public void ReusedInstance_RecomputesTheTolerances()
        {
            // one instance on a mesh, then on the same mesh in km: equals a fresh instance on the km mesh
            DMesh3 Km() { DMesh3 m = CrackedSphere(1e-8); MeshTransforms.Scale(m, 1e3); return m; }
            var r = new MeshAutoRepair(CrackedSphere(1e-8));
            Assert.True(r.Apply());
            r.Mesh = Km();
            Assert.True(r.Apply());
            MeshAutoRepair fresh = Repair(Km());
            Assert.Equal(fresh.EffectiveRepairTolerance, r.EffectiveRepairTolerance);
            Assert.Equal("", Invariance.Difference(fresh.Mesh, r.Mesh));
        }

        [Theory]
        [InlineData(1e6)]
        [InlineData(double.PositiveInfinity)]
        [InlineData(double.NaN)]
        public void OutlierTriangle_DoesNotInflateTheTolerances(double x)
        {
            // one small triangle far away (or with a non-finite corner) makes the diagonal huge: the cap of 1/100 of the
            // median edge length keeps the tolerances at the scale of the sphere, which survives
            DMesh3 sphere = Defects.Sphere(Vector3d.Zero, 1);
            DMesh3 m = new DMesh3(sphere);
            int a = m.AppendVertex(new Vector3d(x, 0, 0)), b = m.AppendVertex(new Vector3d(x, 1, 0)), c = m.AppendVertex(new Vector3d(x, 0, 1));
            m.AppendTriangle(a, b, c);
            MeshAutoRepair r = Repair(m);
            Assert.True(MathUtil.IsFinite(r.EffectiveRepairTolerance) && MathUtil.IsFinite(r.EffectiveMinEdgeLength));
            Assert.True(r.EffectiveMinEdgeLength <= 0.01, $"min edge length {r.EffectiveMinEdgeLength}");
            Assert.True(r.Mesh.TriangleCount >= sphere.TriangleCount, $"{r.Mesh.TriangleCount} triangles left of {sphere.TriangleCount}");
        }

        [Fact]
        public void RepeatedRuns_BitIdentical()
        {
            // the global orientation sums evidence from parallel ray casts: in a fixed order
            foreach (string name in new[] { "partly flipped", "inside-out", "overlapping spheres" }) {
                DMesh3 first = Repair(Defects.ByName(name).Make()).Mesh;
                for (int i = 0; i < 3; ++i)
                    Assert.Equal("", Invariance.Difference(first, Repair(Defects.ByName(name).Make()).Mesh));
            }
        }

        [Fact]
        public void Orientation_DegenerateAreaIsRelative()
        {
            // an inside-out sphere in um: 1.0.324 skipped every triangle (area below 1e-6) and left it inside out
            DMesh3 m = Defects.Sphere(Vector3d.Zero, 1);
            m.ReverseOrientation();
            MeshTransforms.Scale(m, 1e-3);
            var orient = new MeshRepairOrientation(m);
            orient.OrientComponents();
            orient.SolveGlobalOrientation();
            Assert.True(Invariance.Volume(m) > 0);
        }
    }
}

using System;
using System.Linq;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// MeshBoolean (the mesh-cut union of two closed meshes): the result must come back welded and closed.
    /// (MeshBooleanTests covers MeshWindingNumberBoolean.)
    /// </summary>
    public class MeshBooleanSeamTests
    {
        static DMesh3 Sphere(Vector3d center, int edgeVertices)
        {
            DMesh3 mesh = new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = edgeVertices }.Generate().MakeDMesh();
            MeshTransforms.Translate(mesh, center);
            return mesh;
        }

        static void AssertClosedUnion(int edgeVertices, Vector3d toolCenter)
        {
            var op = new MeshBoolean() { Target = Sphere(Vector3d.Zero, edgeVertices), Tool = Sphere(toolCenter, edgeVertices) };
            bool ok = op.Compute();
            int boundary = MeshIterators.BoundaryEdges(op.Result).Count();
            Assert.True(ok && boundary == 0, $"Compute() = {ok}, {boundary} boundary edges");
            Assert.True(op.Result.CheckValidity(false, FailMode.ReturnOnly));
            var comps = new MeshConnectedComponents(op.Result);
            comps.FindConnectedT();
            Assert.Equal(1, comps.Count);
        }

        // Inputs that left a small seam hole after welding: three with a tiny boundary edge between two seam
        // vertices less than the match tolerance apart, one with a single missing seam triangle.
        [Theory]
        [InlineData(8, 0.7060438090963492, 0.1422092237706339, 0.1314813208912878)]
        [InlineData(8, 0.48356576663608, 0.48208275226973124, 0.04767185824349143)]
        [InlineData(20, 1.4666749242538004, 0.12680896330941885, 0.2533013062799821)]
        [InlineData(32, 0.8737664778594703, 0.05047010423171804, 0.49147923383465003)]
        public void Union_SeamArtifacts_AreClosed(int edgeVertices, double x, double y, double z)
        {
            AssertClosedUnion(edgeVertices, new Vector3d(x, y, z));
        }

        [Fact]
        public void Union_RandomSpherePairs_AreClosed()
        {
            var rand = new Random(17);
            var failures = new System.Collections.Generic.List<string>();
            foreach (int ev in new[] { 8, 12, 20 }) {
                for (int t = 0; t < 10; ++t) {
                    var c = new Vector3d(0.3 + rand.NextDouble() * 1.2, rand.NextDouble() * 0.5, rand.NextDouble() * 0.5);
                    try {
                        AssertClosedUnion(ev, c);
                    } catch (Exception e) {
                        failures.Add($"ev {ev} c ({c.x:R},{c.y:R},{c.z:R}): {e.Message.Split('\n')[0]}");
                    }
                }
            }
            Assert.True(failures.Count == 0, string.Join("\n", failures));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Volumetric booleans: combine the winding numbers of the inputs and extract the result with dual
    /// contouring. Expected volumes are analytic.
    /// </summary>
    public class MeshBooleanTests
    {
        static DMesh3 Box(Vector3d min, Vector3d max)
        {
            var box = new Box3d(0.5 * (min + max), 0.5 * (max - min));
            return new TrivialBox3Generator() { Box = box }.Generate().MakeDMesh();
        }
        static DMesh3 Box(double min, double max) { return Box(min * Vector3d.One, max * Vector3d.One); }

        // cylinder along +y through (cx, *, cz), from y0 to y1
        static DMesh3 CylinderY(double cx, double cz, double r, double y0, double y1)
        {
            DMesh3 m = new CappedCylinderGenerator() { BaseRadius = (float)r, TopRadius = (float)r, Height = (float)(y1 - y0), Slices = 64 }.Generate().MakeDMesh();
            MeshTransforms.Translate(m, new Vector3d(cx, y0, cz));
            return m;
        }

        static double Volume(DMesh3 m) { return MeshMeasurements.VolumeArea(m, m.TriangleIndices(), m.GetVertex).x; }

        static int Components(DMesh3 m)
        {
            var c = new MeshConnectedComponents(m);
            c.FindConnectedT();
            return c.Count;
        }

        static double MinDistance(DMesh3 m, Vector3d p) { return m.VertexIndices().Min(v => m.GetVertex(v).Distance(p)); }

        static DMesh3 Run(DMesh3 a, DMesh3 b, MeshWindingNumberBoolean.Operations op, int resolution = 96)
        {
            var boolean = new MeshWindingNumberBoolean(a, b, op) { GridResolution = resolution };
            Assert.True(boolean.Compute());
            DMesh3 result = boolean.Result;
            Assert.True(result.IsClosed(), "result is not closed");
            Assert.Empty(MeshIterators.BowtieVertices(result));
            Assert.True(result.CheckValidity(false, FailMode.ReturnOnly));
            return result;
        }

        static void AssertClean(DMesh3 m)
        {
            double diag2 = m.CachedBounds.DiagonalLength * m.CachedBounds.DiagonalLength;
            Assert.Equal(0, m.TriangleIndices().Count(t => m.GetTriArea(t) < 1e-12 * diag2));
            double foldCos = Math.Cos(175 * MathUtil.Deg2Rad);
            Assert.Equal(0, m.EdgeIndices().Count(e => {
                Index2i et = m.GetEdgeT(e);
                return et.b >= 0 && m.GetTriNormal(et.a).Dot(m.GetTriNormal(et.b)) < foldCos;
            }));
        }


        [Fact]
        public void Union_OverlappingBoxes_ExactVolumeAndSharpConcaveCorners()
        {
            DMesh3 result = Run(Box(0, 10), Box(5, 15), MeshWindingNumberBoolean.Operations.Union);
            Assert.InRange(Volume(result), 1875 - 0.5, 1875 + 0.5);
            Assert.Equal(1, Components(result));
            foreach (Vector3d c in new[] { new Vector3d(0, 0, 0), new Vector3d(15, 15, 15),
                                           new Vector3d(10, 10, 5), new Vector3d(10, 5, 10), new Vector3d(5, 10, 10) })
                Assert.True(MinDistance(result, c) < 1e-3, $"corner {c} lost");
            AssertClean(result);
        }

        [Fact]
        public void Intersection_OverlappingBoxes_IsTheOverlapBox()
        {
            DMesh3 result = Run(Box(0, 10), Box(5, 15), MeshWindingNumberBoolean.Operations.Intersection);
            Assert.InRange(Volume(result), 125 - 0.1, 125 + 0.1);
            foreach (Vector3d c in new Box3d(7.5 * Vector3d.One, 2.5 * Vector3d.One).ComputeVertices())
                Assert.True(MinDistance(result, c) < 1e-3, $"corner {c} lost");
            AssertClean(result);
        }

        [Fact]
        public void Difference_BoxMinusBox_CutsTheCorner()
        {
            DMesh3 result = Run(Box(0, 10), Box(5, 15), MeshWindingNumberBoolean.Operations.Difference);
            Assert.InRange(Volume(result), 875 - 0.5, 875 + 0.5);
            Assert.True(MinDistance(result, new Vector3d(5, 5, 5)) < 1e-3, "concave corner lost");
            AssertClean(result);
        }

        [Fact]
        public void Difference_DrillHole_ThroughHoleWithRightVolume()
        {
            DMesh3 result = Run(Box(0, 10), CylinderY(5, 5, 2, -1, 11), MeshWindingNumberBoolean.Operations.Difference, 128);
            double expected = 1000 - Math.PI * 4 * 10;
            Assert.InRange(Volume(result), expected * 0.99, expected * 1.01);
            // a through hole: genus 1, Euler characteristic 0
            Assert.Equal(0, result.VertexCount - result.EdgeCount + result.TriangleCount);
            AssertClean(result);
        }

        [Fact]
        public void Union_CoplanarFaces_MergesFlat()
        {
            // classic failure case for mesh booleans: the boxes share their top, bottom, front and back planes
            DMesh3 result = Run(Box(Vector3d.Zero, 10 * Vector3d.One), Box(new Vector3d(5, 0, 0), new Vector3d(15, 10, 10)),
                MeshWindingNumberBoolean.Operations.Union);
            Assert.InRange(Volume(result), 1500 - 0.5, 1500 + 0.5);
            Assert.Equal(1, Components(result));
            // all vertices on the outer box
            var outer = new AxisAlignedBox3d(Vector3d.Zero, new Vector3d(15, 10, 10));
            foreach (int vid in result.VertexIndices()) {
                Vector3d p = result.GetVertex(vid);
                double d = Math.Min(Math.Min(Math.Min(p.x, 15 - p.x), Math.Min(p.y, 10 - p.y)), Math.Min(p.z, 10 - p.z));
                Assert.True(Math.Abs(d) < 1e-3, $"vertex {p} not on the outer box");
            }
            AssertClean(result);
        }

        [Fact]
        public void SmallAngleCreases_AreNotHiddenGaps_NoRefinement()
        {
            // B = A rotated by 20 degrees and shifted: where they meet, the outside wedge between the
            // surfaces is narrower than a cell near the crease at any cell size; refining cannot remove it
            // (a plate 20 x 10 x 2: the faces of A and B meet at 20 degrees; as in the boolean benchmark)
            DMesh3 a = Box(Vector3d.Zero, new Vector3d(20, 10, 2));
            DMesh3 b = new DMesh3(a);
            MeshTransforms.Rotate(b, new Vector3d(10, 5, 1), Quaterniond.AxisAngleD(new Vector3d(1, 1, 0).Normalized, 20));
            MeshTransforms.Translate(b, new Vector3d(5, 2.5, 0.5));
            AxisAlignedBox3d all = a.CachedBounds; all.Contain(b.CachedBounds);
            double cell = all.DiagonalLength / 128;
            foreach (var op in new[] { MeshWindingNumberBoolean.Operations.Union, MeshWindingNumberBoolean.Operations.Difference }) {
                var boolean = new MeshWindingNumberBoolean(a, b, op) { CellSize = cell };
                Assert.True(boolean.Compute());
                Assert.Equal(0, boolean.HiddenGapEdges);
                Assert.Equal(cell, boolean.UsedCellSize);
                Assert.True(boolean.Result.IsClosed());
            }
        }

        [Fact]
        public void Union_DisjointBoxes_TwoParts()
        {
            DMesh3 result = Run(Box(0, 10), Box(20, 30), MeshWindingNumberBoolean.Operations.Union);
            Assert.Equal(2, Components(result));
            Assert.InRange(Volume(result), 2000 - 0.5, 2000 + 0.5);
        }

        [Fact]
        public void Union_BrokenInputs_StillClosedAndRight()
        {
            // A: box without its top face, as an unwelded triangle soup; B: overlapping box
            DMesh3 a = Box(0, 10);
            foreach (int tid in a.TriangleIndices().ToArray())
                if (a.GetTriCentroid(tid).y > 9.99)
                    a.RemoveTriangle(tid, true, false);
            var soup = new DMesh3();
            foreach (int tid in a.TriangleIndices()) {
                Index3i t = a.GetTriangle(tid);
                soup.AppendTriangle(soup.AppendVertex(a.GetVertex(t.a)), soup.AppendVertex(a.GetVertex(t.b)), soup.AppendVertex(a.GetVertex(t.c)));
            }
            Assert.False(soup.IsClosed());

            DMesh3 result = Run(soup, Box(5, 15), MeshWindingNumberBoolean.Operations.Union);
            Assert.InRange(Volume(result), 1875 * 0.99, 1875 * 1.01);
            Assert.Equal(1, Components(result));
        }

        [Fact]
        public void Union_SelfOverlappingInput_CountsOverlapOnce()
        {
            // A is two overlapping boxes in one mesh (not unioned), B a third box
            DMesh3 a = Box(0, 10);
            MeshEditor.Append(a, Box(5, 15));
            DMesh3 result = Run(a, Box(new Vector3d(12, 0, 0), new Vector3d(20, 4, 4)), MeshWindingNumberBoolean.Operations.Union);
            // |A| = 1875, B = 8x4x4 = 128, overlap of B with A: x in [12,15], y in [5,..] -> none (B is y<4, z<4; A's second box starts at 5)
            Assert.InRange(Volume(result), 1875 + 128 - 0.5, 1875 + 128 + 0.5);
        }
    }
