using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    public class MeshBoundaryLoopsTests
    {
        static DMesh3 LoadTestFile(string name)
        {
            string path = Path.Combine(AppContext.BaseDirectory, "test_files", name);
            DMesh3 mesh = StandardMeshReader.ReadMesh(path);
            Assert.NotNull(mesh);
            return mesh;
        }

        // open box: box without its top face
        static DMesh3 OpenBox()
        {
            DMesh3 mesh = new TrivialBox3Generator() { Box = new Box3d(Vector3d.Zero, Vector3d.One) }.Generate().MakeDMesh();
            foreach (int tid in mesh.TriangleIndices().ToArray())
                if (mesh.GetTriCentroid(tid).y > 0.99)
                    mesh.RemoveTriangle(tid, true, false);
            return mesh;
        }

        // 6x6 grid with two cells removed that touch diagonally at one vertex (a bowtie on the boundary)
        static DMesh3 GridWithBowtieHoles()
        {
            DMesh3 mesh = new GriddedRectGenerator() { Width = 6, Height = 6, EdgeVertices = 7 }.Generate().MakeDMesh();
            foreach (int tid in mesh.TriangleIndices().ToArray()) {
                Vector3d c = mesh.GetTriCentroid(tid);
                bool cellA = c.x > -1 && c.x < 0 && c.z > -1 && c.z < 0;
                bool cellB = c.x > 0 && c.x < 1 && c.z > 0 && c.z < 1;
                if (cellA || cellB)
                    mesh.RemoveTriangle(tid, true, false);
            }
            return mesh;
        }

        // checks the invariants every boundary loop decomposition must have
        static void Validate(DMesh3 mesh, MeshBoundaryLoops loops, bool expectOriented)
        {
            Assert.Equal(0, loops.SpanCount);
            var boundaryEdges = new HashSet<int>(MeshIterators.BoundaryEdges(mesh));
            var seen = new HashSet<int>();
            foreach (EdgeLoop loop in loops) {
                int N = loop.Vertices.Length;
                Assert.True(N >= 3, $"loop with {N} vertices");
                Assert.Equal(N, loop.Edges.Length);
                Assert.Equal(N, loop.Vertices.Distinct().Count());     // simple loop
                for (int i = 0; i < N; ++i) {
                    int eid = loop.Edges[i];
                    Assert.Contains(eid, boundaryEdges);
                    Assert.True(seen.Add(eid), $"edge {eid} in more than one loop");
                    Index2i ev = mesh.GetEdgeV(eid);
                    int a = loop.Vertices[i], b = loop.Vertices[(i + 1) % N];
                    Assert.True((ev.a == a && ev.b == b) || (ev.a == b && ev.b == a), "edge does not connect consecutive loop vertices");
                    if (expectOriented) {
                        Index2i oriented = mesh.GetOrientedBoundaryEdgeV(eid);
                        Assert.True(oriented.a == a && oriented.b == b, "loop does not follow boundary orientation");
                    }
                }
            }
            Assert.Equal(boundaryEdges.Count, seen.Count);
        }


        [Fact]
        public void OpenBox_OneOrientedLoop()
        {
            DMesh3 mesh = OpenBox();
            var loops = new MeshBoundaryLoops(mesh);
            Assert.Equal(1, loops.Count);
            Assert.Equal(4, loops[0].VertexCount);
            Validate(mesh, loops, true);
        }

        [Fact]
        public void BowtieHoles_SeparateSimpleLoops_AndFillable()
        {
            DMesh3 mesh = GridWithBowtieHoles();
            Assert.Single(MeshIterators.BoundaryEdges(mesh).Select(e => mesh.GetEdgeV(e)).SelectMany(ev => new[] { ev.a, ev.b })
                .GroupBy(v => v).Where(g => g.Count() > 2));
            var loops = new MeshBoundaryLoops(mesh);
            Assert.Equal(3, loops.Count);       // outer border + two holes
            Validate(mesh, loops, true);

            foreach (EdgeLoop loop in loops.Where(l => l.VertexCount == 4))
                Assert.True(new SimpleHoleFiller(mesh, loop).Fill());
            Assert.Single(new MeshBoundaryLoops(mesh).Loops);   // only the outer border is left
            // the fills close the holes: no bowtie vertex left, and no fan triangle of zero area
            ResultChecks.AssertValid(mesh);
            Assert.True(mesh.TriangleIndices().All(t => mesh.GetTriArea(t) > 0));
        }

        [Fact]
        public void InconsistentOrientation_StillOneLoop()
        {
            DMesh3 mesh = OpenBox();
            // flip one triangle on the opening: its boundary edge now runs against the others
            int tid = MeshIterators.BoundaryEdges(mesh).Select(e => mesh.GetEdgeT(e).a).First();
            mesh.ReverseTriOrientation(tid);
            var loops = new MeshBoundaryLoops(mesh);
            Assert.Equal(1, loops.Count);
            Assert.Equal(4, loops[0].VertexCount);
            Validate(mesh, loops, false);
            Assert.True(loops.SawInconsistentOrientation);
            Assert.False(loops.IsConsistentlyOriented(loops[0]));
        }

        [Fact]
        public void ConsistentLoops_AreReportedAsOriented()
        {
            DMesh3 mesh = GridWithBowtieHoles();
            var loops = new MeshBoundaryLoops(mesh);
            Assert.False(loops.SawInconsistentOrientation);
            Assert.All(loops.Loops, l => Assert.True(loops.IsConsistentlyOriented(l)));
        }

        sealed class BoundaryFixture
        {
            public DMesh3 Mesh;
            public List<string> Partitions = new List<string>();
        }

        static string PointKey(Vector3d p) => string.Join(",", new[] { p.x, p.y, p.z }
            .Select(x => (x + 0.0).ToString("R", CultureInfo.InvariantCulture)));
        static string EdgeKey(Vector3d a, Vector3d b)
        {
            string x = PointKey(a), y = PointKey(b);
            return string.CompareOrdinal(x, y) <= 0 ? x + "/" + y : y + "/" + x;
        }
        static string CycleKey(IEnumerable<string> edges) => string.Join(";", edges.OrderBy(e => e, StringComparer.Ordinal));
        static string CycleKey(params Vector3d[] vertices) => CycleKey(Enumerable.Range(0, vertices.Length)
            .Select(i => EdgeKey(vertices[i], vertices[(i + 1) % vertices.Length])));
        static List<string> PartitionKeys(DMesh3 mesh, MeshBoundaryLoops loops) => loops.Loops
            .Select(l => CycleKey(l.Edges.Select(e => {
                Index2i v = mesh.GetEdgeV(e);
                return EdgeKey(mesh.GetVertex(v.a), mesh.GetVertex(v.b));
            }))).OrderBy(s => s, StringComparer.Ordinal).ToList();

        static BoundaryFixture Fans(int count)
        {
            var f = new BoundaryFixture { Mesh = new DMesh3() };
            int center = f.Mesh.AppendVertex(Vector3d.Zero);
            for (int i = 0; i < count; ++i) {
                double angle = 2 * Math.PI * i / count;
                Func<double, Vector3d> point = t => new Vector3d(2 * Math.Cos(t), 0, 2 * Math.Sin(t));
                Vector3d a = point(angle), b = point(angle + .3), c = point(angle + .6);
                int va = f.Mesh.AppendVertex(a), vb = f.Mesh.AppendVertex(b), vc = f.Mesh.AppendVertex(c);
                Assert.True(f.Mesh.AppendTriangle(center, va, vb) >= 0);
                Assert.True(f.Mesh.AppendTriangle(center, vb, vc) >= 0);
                f.Partitions.Add(CycleKey(Vector3d.Zero, a, b, c));
            }
            Assert.True(f.Mesh.IsBowtieVertex(center));
            f.Partitions.Sort(StringComparer.Ordinal);
            return f;
        }

        // 7x7 grid with three cells removed that touch diagonally: two bowties in a row
        static BoundaryFixture HoleChain()
        {
            const int n = 7;
            var f = new BoundaryFixture { Mesh = new DMesh3() };
            Func<int, int, Vector3d> p = (x, z) => new Vector3d(x, 0, z);
            var ids = new int[n + 1, n + 1];
            for (int z = 0; z <= n; ++z)
                for (int x = 0; x <= n; ++x) ids[x, z] = f.Mesh.AppendVertex(p(x, z));
            for (int z = 0; z < n; ++z)
                for (int x = 0; x < n; ++x) {
                    if (x == z && x >= 2 && x <= 4) continue;
                    Assert.True(f.Mesh.AppendTriangle(ids[x, z], ids[x + 1, z], ids[x + 1, z + 1]) >= 0);
                    Assert.True(f.Mesh.AppendTriangle(ids[x, z], ids[x + 1, z + 1], ids[x, z + 1]) >= 0);
                }
            for (int h = 2; h <= 4; ++h)
                f.Partitions.Add(CycleKey(p(h, h), p(h + 1, h), p(h + 1, h + 1), p(h, h + 1)));
            var outer = new List<Vector3d>();
            for (int x = 0; x < n; ++x) outer.Add(p(x, 0));
            for (int z = 0; z < n; ++z) outer.Add(p(n, z));
            for (int x = n; x > 0; --x) outer.Add(p(x, n));
            for (int z = n; z > 0; --z) outer.Add(p(0, z));
            f.Partitions.Add(CycleKey(outer.ToArray()));
            f.Partitions.Sort(StringComparer.Ordinal);
            Assert.Contains(f.Mesh.VertexIndices(), v => f.Mesh.IsBowtieVertex(v));
            return f;
        }

        // Two discs that share only the bowtie vertices A and B. These coordinates make the left-turn rule of
        // the filtered walk go x B y A z B w A, an interleaving without a simple sub-loop, which is the only way
        // to reach FellBackToSpansOnFailure and FailureBowties without seeding them.
        static void AppendInterleavedBowties(DMesh3 mesh)
        {
            Func<double, double, double, int> add = (x, y, z) => mesh.AppendVertex(new Vector3d(x, y, z));
            int A = add(2, -2, 2), B = add(-1, 2, 3), p = add(0, 2, 1), q = add(-3, 3, 2), r = add(3, -3, 0), s = add(0, -2, 3);
            int c1 = add(1, -1, 0), c2 = add(1, 1, 0);
            foreach (Index3i t in new[] { new Index3i(c1, p, B), new Index3i(c1, B, q), new Index3i(c1, q, A), new Index3i(c1, A, p),
                new Index3i(c2, r, B), new Index3i(c2, B, s), new Index3i(c2, s, A), new Index3i(c2, A, r) })
                Assert.True(mesh.AppendTriangle(t) >= 0);
        }

        static DMesh3 InterleavedBowties()
        {
            var mesh = new DMesh3();
            AppendInterleavedBowties(mesh);
            return mesh;
        }

        static void AssertSnapshot(DMesh3 before, DMesh3 after, int timestamp, int shapeTimestamp)
        {
            Assert.Equal("", Invariance.Difference(before, after));
            Assert.Equal(before.EdgeIndices().ToArray(), after.EdgeIndices().ToArray());
            foreach (int e in before.EdgeIndices()) {
                Assert.Equal(before.GetEdgeV(e), after.GetEdgeV(e));
                Assert.Equal(before.GetEdgeT(e), after.GetEdgeT(e));
            }
            Assert.Equal(timestamp, after.Timestamp);
            Assert.Equal(shapeTimestamp, after.ShapeTimestamp);
        }

        static void AssertSuccessfulCycles(DMesh3 mesh, MeshBoundaryLoops loops)
        {
            Validate(mesh, loops, true);
            Assert.False(loops.SawOpenSpans);
            Assert.False(loops.FellBackToSpansOnFailure);
            Assert.True(loops.FailureBowties == null || loops.FailureBowties.Count == 0);
            Assert.False(loops.SawInconsistentOrientation);
        }

        // Fans(9) has 18 boundary edges at one vertex, more than the walk's initial buffer of 16.
        [Theory]
        [InlineData(9, 19)]
        [InlineData(9, 43)]
        [InlineData(9, 101)]
        [InlineData(0, 19)]
        [InlineData(0, 43)]
        [InlineData(0, 101)]
        public void Bowties_HandBuiltPartition_SurvivesInsertionOrderAndRecompute(int fans, int seed)
        {
            BoundaryFixture f = fans > 0 ? Fans(fans) : HoleChain();
            DMesh3 mesh = Invariance.Permuted(f.Mesh, seed);
            var before = new DMesh3(mesh);
            int stamp = mesh.Timestamp, shape = mesh.ShapeTimestamp;
            var loops = new MeshBoundaryLoops(mesh);
            AssertSuccessfulCycles(mesh, loops);
            Assert.Equal(f.Partitions, PartitionKeys(mesh, loops));
            AssertSnapshot(before, mesh, stamp, shape);
            Assert.True(loops.Compute());
            AssertSuccessfulCycles(mesh, loops);
            Assert.Equal(f.Partitions, PartitionKeys(mesh, loops));
        }

        [Theory]
        [MemberData(nameof(Similarity.Names), MemberType = typeof(Similarity))]
        public void BowtieAndChain_AllSimilaritiesPreserveDiscreteEdgePartition(string name)
        {
            Similarity s = Similarity.ByName(name);
            // Only the interleaved fixture depends on the turn rule; the others have one simple-loop partition.
            foreach (DMesh3 original in new[] { Fans(2).Mesh, HoleChain().Mesh, InterleavedBowties() }) {
                var baseline = new MeshBoundaryLoops(original);
                DMesh3 mesh = Invariance.Transformed(original, s);
                var loops = new MeshBoundaryLoops(mesh);
                AssertSuccessfulCycles(mesh, loops);
                Func<MeshBoundaryLoops, string[]> ids = x => x.Loops.Select(l => string.Join(",", l.Edges.OrderBy(e => e)))
                    .OrderBy(k => k, StringComparer.Ordinal).ToArray();
                Assert.Equal(ids(baseline), ids(loops));
            }
        }

        // A first Compute that really produces the diagnostic; asserts that it did, so the reset test cannot be vacuous.
        static MeshBoundaryLoops ComputedWithDiagnostic(string diagnostic)
        {
            MeshBoundaryLoops loops;
            switch (diagnostic) {
                case nameof(MeshBoundaryLoops.SawOpenSpans):
                    DMesh3 box = OpenBox();
                    int removed = MeshIterators.BoundaryEdges(box).First();
                    loops = new MeshBoundaryLoops(box, false) { EdgeFilterF = e => e != removed };
                    loops.Compute();
                    Assert.True(loops.SawOpenSpans);
                    break;
                case nameof(MeshBoundaryLoops.FellBackToSpansOnFailure):
                    loops = new MeshBoundaryLoops(InterleavedBowties(), false) { EdgeFilterF = e => true };
                    loops.Compute();
                    Assert.True(loops.FellBackToSpansOnFailure);
                    break;
                case nameof(MeshBoundaryLoops.FailureBowties):
                    loops = new MeshBoundaryLoops(InterleavedBowties(), false) {
                        EdgeFilterF = e => true, FailureBehavior = MeshBoundaryLoops.FailureBehaviors.ThrowException };
                    Assert.Throws<MeshBoundaryLoopsException>(() => loops.Compute());
                    Assert.NotEmpty(loops.FailureBowties);
                    break;
                case nameof(MeshBoundaryLoops.SawInconsistentOrientation):
                    DMesh3 flipped = OpenBox();
                    flipped.ReverseTriOrientation(MeshIterators.BoundaryEdges(flipped).Select(e => flipped.GetEdgeT(e).a).First());
                    loops = new MeshBoundaryLoops(flipped);
                    Assert.True(loops.SawInconsistentOrientation);
                    break;
                default: throw new ArgumentOutOfRangeException(nameof(diagnostic));
            }
            return loops;
        }

        public static IEnumerable<object[]> ReuseCases()
        {
            foreach (string diagnostic in new[] { nameof(MeshBoundaryLoops.SawOpenSpans), nameof(MeshBoundaryLoops.FellBackToSpansOnFailure),
                nameof(MeshBoundaryLoops.FailureBowties), nameof(MeshBoundaryLoops.SawInconsistentOrientation) })
                foreach (bool closed in new[] { false, true })
                    foreach (bool filtered in new[] { false, true })
                        yield return new object[] { diagnostic, closed, filtered };
        }

        [Theory]
        [MemberData(nameof(ReuseCases))]
        public void Reuse_RealDiagnosticFromFirstRun_IsClearedOnEveryPathOfTheNextRun(string diagnostic, bool closed, bool filtered)
        {
            MeshBoundaryLoops reused = ComputedWithDiagnostic(diagnostic);
            DMesh3 mesh = closed ? new TrivialBox3Generator().Generate().MakeDMesh() : OpenBox();
            Func<int, bool> filter = filtered ? (Func<int, bool>)(e => true) : null;
            reused.Mesh = mesh;
            reused.EdgeFilterF = filter;
            reused.FailureBehavior = MeshBoundaryLoops.FailureBehaviors.ConvertToOpenSpan;
            Assert.True(reused.Compute());
            AssertSuccessfulCycles(mesh, reused);
            Assert.Null(reused.FailureBowties);
            var fresh = new MeshBoundaryLoops(mesh, false) { EdgeFilterF = filter };
            Assert.True(fresh.Compute());
            Assert.Equal(closed ? 0 : 1, reused.Count);
            Assert.Equal(PartitionKeys(mesh, fresh), PartitionKeys(mesh, reused));
        }

        [Fact]
        public void Reuse_RunThatThrowsBeforeAnyFlag_DoesNotKeepTheFlagOfThePreviousRun()
        {
            MeshBoundaryLoops loops = ComputedWithDiagnostic(nameof(MeshBoundaryLoops.SawOpenSpans));
            loops.SpanBehavior = MeshBoundaryLoops.SpanBehaviors.ThrowException;
            Assert.Throws<MeshBoundaryLoopsException>(() => loops.Compute());
            Assert.False(loops.SawOpenSpans);
        }

        [Fact]
        public void Reuse_AfterExceptionMidWalk_NextRunIsClean()
        {
            // The filter opens the triangle first (SawOpenSpans), then the interleaved bowties throw (FailureBowties).
            var mesh = new DMesh3();
            int a = mesh.AppendVertex(new Vector3d(20, 0, 0)), b = mesh.AppendVertex(new Vector3d(21, 0, 0)), c = mesh.AppendVertex(new Vector3d(20, 0, 1));
            Assert.True(mesh.AppendTriangle(a, b, c) >= 0);
            AppendInterleavedBowties(mesh);
            int filteredOut = mesh.FindEdge(a, b);
            var loops = new MeshBoundaryLoops(mesh, false) {
                EdgeFilterF = e => e != filteredOut, FailureBehavior = MeshBoundaryLoops.FailureBehaviors.ThrowException };
            Assert.Throws<MeshBoundaryLoopsException>(() => loops.Compute());
            Assert.True(loops.SawOpenSpans);
            Assert.NotEmpty(loops.FailureBowties);

            loops.EdgeFilterF = null;
            Assert.True(loops.Compute());
            AssertSuccessfulCycles(mesh, loops);
            Assert.Null(loops.FailureBowties);
            Assert.Equal(3, loops.Count);
            Assert.Equal(PartitionKeys(mesh, new MeshBoundaryLoops(mesh)), PartitionKeys(mesh, loops));
        }

        [Theory]
        [InlineData(MeshBoundaryLoops.SpanBehaviors.Compute)]
        [InlineData(MeshBoundaryLoops.SpanBehaviors.Ignore)]
        public void FilteredRun_SpanPolicy_ReportsTheSpanAndNextRunClearsTheFlag(MeshBoundaryLoops.SpanBehaviors policy)
        {
            DMesh3 mesh = OpenBox();
            int removed = MeshIterators.BoundaryEdges(mesh).OrderBy(e => e).First();
            var loops = new MeshBoundaryLoops(mesh, false) { SpanBehavior = policy, EdgeFilterF = e => e != removed };
            var before = new DMesh3(mesh);
            int stamp = mesh.Timestamp, shape = mesh.ShapeTimestamp;
            Assert.True(loops.Compute());
            Assert.Empty(loops.Loops);
            Assert.True(loops.SawOpenSpans);
            if (policy == MeshBoundaryLoops.SpanBehaviors.Compute) {
                Assert.Single(loops.Spans);
                int[] expected = MeshIterators.BoundaryEdges(mesh).Where(e => e != removed).OrderBy(e => e).ToArray();
                Assert.Equal(expected, loops.Spans.SelectMany(s => s.Edges).OrderBy(e => e).ToArray());
            } else Assert.Empty(loops.Spans);
            AssertSnapshot(before, mesh, stamp, shape);
            loops.EdgeFilterF = null;
            Assert.True(loops.Compute());
            AssertSuccessfulCycles(mesh, loops);
            Assert.Equal(PartitionKeys(mesh, new MeshBoundaryLoops(mesh)), PartitionKeys(mesh, loops));
        }

        [Fact]
        public void EmptyMeshAndSingleTriangle_HaveContractBoundaryCounts()
        {
            var empty = new MeshBoundaryLoops(new DMesh3());
            Assert.Equal(0, empty.Count);
            Assert.Equal(0, empty.SpanCount);
            var mesh = new DMesh3();
            mesh.AppendTriangle(mesh.AppendVertex(Vector3d.Zero), mesh.AppendVertex(Vector3d.AxisX), mesh.AppendVertex(Vector3d.AxisY));
            var loops = new MeshBoundaryLoops(mesh);
            AssertSuccessfulCycles(mesh, loops);
            Assert.Equal(3, loops[0].VertexCount);
        }

        [Theory]
        [InlineData("crazy_boundary.obj")]
        [InlineData("bunny_bowties.obj")]
        [InlineData("crazyhole.obj")]
        public void UpstreamProblemMeshes_DecomposeIntoSimpleLoops(string file)
        {
            DMesh3 mesh = LoadTestFile(file);
            var loops = new MeshBoundaryLoops(mesh);
            Validate(mesh, loops, false);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// MeshCurvature (Meyer et al. 2003): analytic surfaces (sphere, cylinder, plane, torus), convergence under
    /// refinement, Gauss-Bonnet, degenerate triangles, boundaries and bowties, scale invariance.
    /// </summary>
    public class MeshCurvatureTests
    {
        // icosphere: the icosahedron, subdivided sub times (midpoints projected to the sphere)
        internal static DMesh3 Icosphere(double r, int sub)
        {
            double t = (1 + Math.Sqrt(5)) / 2;
            var m = new DMesh3();
            var vs = new[] { new Vector3d(-1, t, 0), new Vector3d(1, t, 0), new Vector3d(-1, -t, 0), new Vector3d(1, -t, 0),
                new Vector3d(0, -1, t), new Vector3d(0, 1, t), new Vector3d(0, -1, -t), new Vector3d(0, 1, -t),
                new Vector3d(t, 0, -1), new Vector3d(t, 0, 1), new Vector3d(-t, 0, -1), new Vector3d(-t, 0, 1) };
            foreach (var v in vs) m.AppendVertex(r * v.Normalized);
            int[] f = { 0, 11, 5, 0, 5, 1, 0, 1, 7, 0, 7, 10, 0, 10, 11, 1, 5, 9, 5, 11, 4, 11, 10, 2, 10, 7, 6, 7, 1, 8,
                3, 9, 4, 3, 4, 2, 3, 2, 6, 3, 6, 8, 3, 8, 9, 4, 9, 5, 2, 4, 11, 6, 2, 10, 8, 6, 7, 9, 8, 1 };
            for (int i = 0; i < f.Length; i += 3) m.AppendTriangle(f[i], f[i + 1], f[i + 2]);
            for (int s = 0; s < sub; ++s) {
                var next = new DMesh3();
                foreach (Vector3d v in m.Vertices()) next.AppendVertex(v);
                var mid = new Dictionary<(int, int), int>();
                Func<int, int, int> M = (a, b) => {
                    var key = a < b ? (a, b) : (b, a);
                    int id;
                    if (mid.TryGetValue(key, out id) == false) {
                        id = next.AppendVertex(r * (0.5 * (m.GetVertex(a) + m.GetVertex(b))).Normalized);
                        mid[key] = id;
                    }
                    return id;
                };
                foreach (int tid in m.TriangleIndices()) {
                    Index3i tt = m.GetTriangle(tid);
                    int ab = M(tt.a, tt.b), bc = M(tt.b, tt.c), ca = M(tt.c, tt.a);
                    next.AppendTriangle(tt.a, ab, ca); next.AppendTriangle(ab, tt.b, bc);
                    next.AppendTriangle(ca, bc, tt.c); next.AppendTriangle(ab, bc, ca);
                }
                m = next;
            }
            return m;
        }

        // open cylinder of radius r and height h, nu vertices per ring, nv strips; every other ring rotated by half a
        // step (antiprism bands, so the triangulation is not aligned with the principal directions)
        internal static DMesh3 Cylinder(double r, double h, int nu, int nv)
        {
            var m = new DMesh3();
            for (int j = 0; j <= nv; ++j)
                for (int i = 0; i < nu; ++i) {
                    double u = 2 * Math.PI * (i + 0.5 * (j % 2)) / nu;
                    m.AppendVertex(new Vector3d(r * Math.Cos(u), r * Math.Sin(u), h * j / nv));
                }
            for (int j = 0; j < nv; ++j)
                for (int i = 0; i < nu; ++i) {
                    int a = j * nu + i, b = j * nu + (i + 1) % nu, c = a + nu, d = b + nu;
                    if (j % 2 == 0) { m.AppendTriangle(a, b, c); m.AppendTriangle(b, d, c); }
                    else { m.AppendTriangle(a, b, d); m.AppendTriangle(a, d, c); }
                }
            return m;
        }

        // n x n grid on the unit square, interior vertices jittered in the plane, then tilted out of the xy plane
        static DMesh3 JitteredPlane(int n, int seed)
        {
            var rnd = new Random(seed);
            var m = new DMesh3();
            Matrix3d rot = Matrix3d.AxisAngleD(new Vector3d(1, 2, 3).Normalized, 37);
            for (int j = 0; j <= n; ++j)
                for (int i = 0; i <= n; ++i) {
                    double x = (double)i / n, y = (double)j / n;
                    if (i > 0 && j > 0 && i < n && j < n) {
                        x += (rnd.NextDouble() - 0.5) * 0.6 / n;
                        y += (rnd.NextDouble() - 0.5) * 0.6 / n;
                    }
                    m.AppendVertex(rot * new Vector3d(x, y, 0) + new Vector3d(0.3, -0.2, 0.1));
                }
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    int a = j * (n + 1) + i, b = a + 1, c = a + n + 1, d = c + 1;
                    m.AppendTriangle(a, b, d);
                    m.AppendTriangle(a, d, c);
                }
            return m;
        }

        static DMesh3 Torus(double R, double r, int nu, int nv)
        {
            var m = new DMesh3();
            for (int i = 0; i < nu; ++i)
                for (int j = 0; j < nv; ++j) {
                    double u = 2 * Math.PI * i / nu, v = 2 * Math.PI * j / nv;
                    m.AppendVertex(new Vector3d((R + r * Math.Cos(v)) * Math.Cos(u), (R + r * Math.Cos(v)) * Math.Sin(u), r * Math.Sin(v)));
                }
            for (int i = 0; i < nu; ++i)
                for (int j = 0; j < nv; ++j) {
                    int a = i * nv + j, b = ((i + 1) % nu) * nv + j, c = ((i + 1) % nu) * nv + (j + 1) % nv, d = i * nv + (j + 1) % nv;
                    m.AppendTriangle(a, b, c);
                    m.AppendTriangle(a, c, d);
                }
            return m;
        }

        static double MaxError(DMesh3 m, MeshCurvature c, double h, double k, out double maxK)
        {
            double maxH = 0;
            maxK = 0;
            foreach (int v in m.VertexIndices()) {
                if (c.Valid[v] == false) continue;
                maxH = Math.Max(maxH, Math.Abs(c.Mean[v] - h));
                maxK = Math.Max(maxK, Math.Abs(c.Gaussian[v] - k));
            }
            return maxH;
        }

        static void AssertFinite(MeshCurvature c)
        {
            for (int v = 0; v < c.Mean.Length; ++v) {
                Assert.True(MathUtil.IsFinite(c.Mean[v]) && MathUtil.IsFinite(c.Gaussian[v]) && MathUtil.IsFinite(c.MixedArea[v])
                    && MathUtil.IsFinite(c.AngleDeficit[v]) && c.MeanCurvatureNormal[v].IsFinite, $"vertex {v}");
            }
        }

        [Fact]
        public void Sphere_MeanAndGaussian_ConvergeUnderRefinement()
        {
            // H = 1 / r, K = 1 / r^2: the largest error over all vertices drops by about 4 per subdivision (second order;
            // from the second subdivision on, the first is exact for H by symmetry)
            double r = 2;
            double prevH = double.MaxValue, prevK = double.MaxValue;
            for (int sub = 2; sub <= 4; ++sub) {
                DMesh3 m = Icosphere(r, sub);
                var c = MeshCurvature.Compute(m);
                AssertFinite(c);
                Assert.Equal(m.VertexCount, c.ValidVertices);
                double maxK;
                double maxH = MaxError(m, c, 1 / r, 1 / (r * r), out maxK);
                if (sub > 2) {
                    Assert.True(maxH < prevH / 3.5, $"sub {sub}: H error {maxH} vs {prevH}");
                    Assert.True(maxK < prevK / 3.5, $"sub {sub}: K error {maxK} vs {prevK}");
                }
                prevH = maxH; prevK = maxK;
                // Gauss-Bonnet: the deficits sum to 2 pi chi = 4 pi; the mixed areas to the mesh's area
                Assert.Equal(4 * Math.PI, m.VertexIndices().Sum(v => c.AngleDeficit[v]), 9);
                double area = m.TriangleIndices().Sum(t => m.GetTriArea(t));
                Assert.Equal(area, m.VertexIndices().Sum(v => c.MixedArea[v]), 9);
            }
            // 2562 vertices: H within 1e-5 / r, K within 2e-3 / r^2 (relative)
            Assert.True(prevH * r < 1e-5, $"{prevH * r}");
            Assert.True(prevK * r * r < 2e-3, $"{prevK * r * r}");
        }

        [Fact]
        public void Cylinder_GaussianZero_MeanHalfInverseRadius()
        {
            // K = 0 (the bands are developable up to rounding), H = 1 / (2 r) converging with second order; the rims
            // are boundary vertices (not Valid)
            double r = 1.5, prev = double.MaxValue;
            foreach (int n in new[] { 8, 16, 32, 64 }) {
                DMesh3 m = Cylinder(r, 3, n, n / 2);
                var c = MeshCurvature.Compute(m);
                AssertFinite(c);
                Assert.Equal(2 * n, c.BoundaryVertices);
                Assert.Equal(m.VertexCount - 2 * n, c.ValidVertices);
                double maxK;
                double maxH = MaxError(m, c, 1 / (2 * r), 0, out maxK);
                Assert.True(maxK * r * r < 1e-11, $"n {n}: K {maxK}");
                Assert.True(maxH < prev / 3.5, $"n {n}: H error {maxH} vs {prev}");
                prev = maxH;
            }
            Assert.True(prev * r < 1e-3, $"{prev * r}");
        }

        [Fact]
        public void Plane_ZeroEverywhere_BoundaryOneSided()
        {
            DMesh3 m = JitteredPlane(12, 3);
            var c = MeshCurvature.Compute(m);
            AssertFinite(c);
            Assert.Equal(11 * 11, c.ValidVertices);
            Assert.Equal(4 * 12, c.BoundaryVertices);
            foreach (int v in m.VertexIndices()) {
                // relative to the inverse edge length (1 / 12)
                Assert.True(Math.Abs(c.Mean[v]) < 1e-12, $"{v}: H {c.Mean[v]}");
                bool corner = m.GetVtxEdgeCount(v) <= 3;
                // boundary: deficit against pi, 0 along a straight edge, pi / 2 at the four corners
                Assert.Equal(corner ? Math.PI / 2 : 0, c.AngleDeficit[v], 12);
                if (corner == false)
                    Assert.True(Math.Abs(c.Gaussian[v]) < 1e-9, $"{v}: K {c.Gaussian[v]}");
            }
        }

        [Fact]
        public void Torus_GaussBonnetAndSigns()
        {
            double R = 2, r = 0.5;
            DMesh3 m = Torus(R, r, 96, 48);
            var c = MeshCurvature.Compute(m);
            AssertFinite(c);
            Assert.Equal(m.VertexCount, c.ValidVertices);
            Assert.Equal(0, m.VertexIndices().Sum(v => c.AngleDeficit[v]), 9);
            foreach (int v in m.VertexIndices()) {
                Vector3d p = m.GetVertex(v);
                double rho = Math.Sqrt(p.x * p.x + p.y * p.y), cosv = (rho - R) / r;
                // K = cos v / (r (R + r cos v)), H = (R + 2 r cos v) / (2 r (R + r cos v))
                double k = cosv / (r * (R + r * cosv)), h = (R + 2 * r * cosv) / (2 * r * (R + r * cosv));
                Assert.True(Math.Abs(c.Gaussian[v] - k) < 0.02 / (r * r), $"{v}: K {c.Gaussian[v]} vs {k}");
                Assert.True(Math.Abs(c.Mean[v] - h) < 0.01 / r, $"{v}: H {c.Mean[v]} vs {h}");
            }
            // orientation: H changes sign, K does not
            foreach (int t in m.TriangleIndices().ToArray()) m.ReverseTriOrientation(t);
            var flipped = MeshCurvature.Compute(m);
            foreach (int v in m.VertexIndices()) {
                Assert.Equal(-c.Mean[v], flipped.Mean[v], 12);
                Assert.Equal(c.Gaussian[v], flipped.Gaussian[v], 12);
            }
        }

        [Fact]
        public void MixedAreaAndDeficit_MatchExistingHelpers()
        {
            // MeshWeights.VoronoiArea is the same mixed area; MeshUtil.DiscreteGaussCurvature the negative deficit
            DMesh3 m = Torus(2, 0.7, 40, 17);
            var c = MeshCurvature.Compute(m);
            foreach (int v in m.VertexIndices()) {
                Assert.Equal(MeshWeights.VoronoiArea(m, v), c.MixedArea[v], 12);
                Assert.Equal(-MeshUtil.DiscreteGaussCurvature(m, v), c.AngleDeficit[v], 12);
            }
        }

        [Fact]
        public void DegenerateTriangles_FiniteAndGaussBonnetKept()
        {
            DMesh3 sphere = Icosphere(1, 2);
            var before = MeshCurvature.Compute(sphere);
            // a collinear sliver: the triangles (a, b, c), (b, a, d) at an edge become (a, m, c), (m, b, c), the sliver
            // (a, b, m) with m the midpoint of a b, and (b, a, d); the surface is the same
            DMesh3 sliver = new DMesh3(sphere);
            int eid = sliver.EdgeIndices().First();
            Index2i ev = sliver.GetEdgeV(eid), et = sliver.GetEdgeT(eid);
            Index3i t0 = sliver.GetTriangle(et.a);
            int a = ev.a, b = ev.b;
            if (IndexUtil.find_tri_ordered_edge(a, b, ref t0) == DMesh3.InvalidID) { a = ev.b; b = ev.a; }
            int tc = IndexUtil.find_tri_ordered_edge(a, b, ref t0) == DMesh3.InvalidID ? et.b : et.a, td = tc == et.a ? et.b : et.a;
            int cv = IndexUtil.find_tri_other_vtx(a, b, sliver.GetTriangle(tc)), dv = IndexUtil.find_tri_other_vtx(a, b, sliver.GetTriangle(td));
            Assert.Equal(MeshResult.Ok, sliver.RemoveTriangle(tc, false, false));
            Assert.Equal(MeshResult.Ok, sliver.RemoveTriangle(td, false, false));
            int mv = sliver.AppendVertex(0.5 * (sliver.GetVertex(a) + sliver.GetVertex(b)));
            Assert.True(sliver.AppendTriangle(a, mv, cv) >= 0);
            Assert.True(sliver.AppendTriangle(mv, b, cv) >= 0);
            Assert.True(sliver.AppendTriangle(a, b, mv) >= 0);
            Assert.True(sliver.AppendTriangle(b, a, dv) >= 0);
            Assert.True(sliver.IsClosed());
            var cs = MeshCurvature.Compute(sliver);
            AssertFinite(cs);
            Assert.Equal(1, cs.DegenerateTriangles);
            Assert.Equal(4 * Math.PI, sliver.VertexIndices().Sum(v => cs.AngleDeficit[v]), 9);
            Assert.Equal(0, cs.AngleDeficit[mv], 12);
            // the sliver's vertices: finite, but not Valid (the midpoint's fan lacks the sliver's side: H 0, in-plane gradient)
            Assert.False(cs.Valid[mv] || cs.Valid[a] || cs.Valid[b]);
            Assert.Equal(sliver.VertexCount - 3, cs.ValidVertices);
            // vertices away from the change keep their values
            foreach (int v in sphere.VertexIndices()) {
                if (v == a || v == b || v == cv || v == dv) continue;
                Assert.Equal(before.Mean[v], cs.Mean[v], 12);
                Assert.Equal(before.Gaussian[v], cs.Gaussian[v], 12);
            }

            // coincident corners: an edge split with the new vertex on an endpoint (two triangles with a zero-length edge)
            DMesh3 coincident = new DMesh3(sphere);
            int e2 = coincident.EdgeIndices().Skip(7).First();
            Index2i ev2 = coincident.GetEdgeV(e2);
            DMesh3.EdgeSplitInfo info;
            Assert.Equal(MeshResult.Ok, coincident.SplitEdge(e2, out info));
            coincident.SetVertex(info.vNew, coincident.GetVertex(ev2.a));
            var cc = MeshCurvature.Compute(coincident);
            AssertFinite(cc);
            Assert.Equal(2, cc.DegenerateTriangles);
            Assert.Equal(4 * Math.PI, coincident.VertexIndices().Sum(v => cc.AngleDeficit[v]), 9);
            // the two coincident vertices share the deficit of the original vertex; neither is Valid
            Assert.Equal(before.AngleDeficit[ev2.a], cc.AngleDeficit[ev2.a] + cc.AngleDeficit[info.vNew], 12);
            Assert.False(cc.Valid[ev2.a] || cc.Valid[info.vNew]);

            // all triangles degenerate (a flat fan), and a single zero-area triangle: no area, nothing Valid, no NaN
            var flat = new DMesh3();
            for (int i = 0; i < 5; ++i) flat.AppendVertex(new Vector3d(i, 0, 0));
            flat.AppendTriangle(0, 1, 2); flat.AppendTriangle(0, 2, 3); flat.AppendTriangle(0, 3, 4);
            var cf = MeshCurvature.Compute(flat);
            AssertFinite(cf);
            Assert.Equal(0, cf.ValidVertices);
            Assert.Equal(3, cf.DegenerateTriangles);
            var point = new DMesh3();
            for (int i = 0; i < 3; ++i) point.AppendVertex(new Vector3d(1, 2, 3));
            point.AppendTriangle(0, 1, 2);
            var cp = MeshCurvature.Compute(point);
            AssertFinite(cp);
            Assert.Equal(0, cp.ValidVertices);
            // pi / 3 per corner
            Assert.Equal(Math.PI - Math.PI / 3, cp.AngleDeficit[0], 12);
        }

        [Fact]
        public void NonFiniteAndHugeCoordinates_NoNaN()
        {
            // a NaN vertex: its triangles add nothing, it and its neighbours are not Valid, the rest is unchanged
            DMesh3 m = Icosphere(1, 1);
            var before = MeshCurvature.Compute(m);
            int bad = m.VertexIndices().First();
            var ring = new HashSet<int>(m.VtxVerticesItr(bad)) { bad };
            DMesh3 nan = new DMesh3(m);
            nan.SetVertex(bad, new Vector3d(double.NaN, 0, 0));
            var cn = MeshCurvature.Compute(nan);
            AssertFinite(cn);
            Assert.Equal(m.GetVtxTriangleCount(bad), cn.DegenerateTriangles);
            foreach (int v in m.VertexIndices()) {
                if (ring.Contains(v)) { Assert.False(cn.Valid[v]); continue; }
                Assert.True(cn.Valid[v]);
                Assert.Equal(before.Mean[v], cn.Mean[v], 12);
            }
            DMesh3 inf = new DMesh3(m);
            inf.SetVertex(bad, new Vector3d(double.PositiveInfinity, 0, 0));
            AssertFinite(MeshCurvature.Compute(inf));
            // finite corners whose edge products leave the double range: degenerate, no NaN (the deficit of the corners is 0)
            var far = new DMesh3();
            far.AppendVertex(Vector3d.Zero); far.AppendVertex(new Vector3d(1e200, 1e200, 0)); far.AppendVertex(new Vector3d(1e200, 1e200, 1));
            far.AppendTriangle(0, 1, 2);
            var cfar = MeshCurvature.Compute(far);
            AssertFinite(cfar);
            Assert.Equal(1, cfar.DegenerateTriangles);
            Assert.Equal(0, cfar.ValidVertices);
            // coordinates near the top of the double range: where the triangle areas still fit, the Voronoi areas do too
            // (they are formed from the cotangents); where they do not, the triangles count as degenerate. No NaN or
            // infinity either way
            foreach (double s in new[] { 1e75, 1e78 }) {
                DMesh3 huge = Icosphere(1, 2);
                MeshTransforms.Scale(huge, new Vector3d(s, s, s * 1e-3), Vector3d.Zero);
                var ch = MeshCurvature.Compute(huge);
                AssertFinite(ch);
                if (s == 1e75)
                    Assert.Equal(huge.VertexCount, ch.ValidVertices);
                else
                    Assert.True(ch.DegenerateTriangles > 0);
            }
        }

        [Fact]
        public void VanishingNormal_NotValid()
        {
            // a closed two-triangle "pillow" (the same triangle twice, opposite orientations): every vertex is interior
            // and manifold, but its normals cancel, so H has no sign
            var m = new DMesh3();
            m.AppendVertex(Vector3d.Zero); m.AppendVertex(new Vector3d(1, 0, 0)); m.AppendVertex(new Vector3d(0, 1, 0));
            Assert.True(m.AppendTriangle(0, 1, 2) >= 0);
            Assert.True(m.AppendTriangle(0, 2, 1) >= 0);
            Assert.True(m.IsClosed());
            var c = MeshCurvature.Compute(m);
            AssertFinite(c);
            Assert.Equal(0, c.ValidVertices);
            Assert.True(c.MixedArea[0] > 0);
        }

        [Fact]
        public void Bowtie_NotValid_Finite()
        {
            // two tetrahedra sharing a vertex; the second one's far face is tilted, so the normals at the shared vertex do
            // not cancel: the vertex is not Valid because it is a bowtie, not for want of a normal
            var m = new DMesh3();
            m.AppendVertex(Vector3d.Zero);
            foreach (double s in new[] { 1.0, -1.0 }) {
                int a = m.AppendVertex(new Vector3d(s, 0, 0)), b = m.AppendVertex(new Vector3d(s, 1, 0)), c = m.AppendVertex(new Vector3d(s > 0 ? s : -0.5, 0, 1));
                int[][] faces = { new[] { 0, b, a }, new[] { 0, a, c }, new[] { 0, c, b }, new[] { a, b, c } };
                foreach (var f in faces) {
                    if (s < 0) Array.Reverse(f);
                    Assert.True(m.AppendTriangle(f[0], f[1], f[2]) >= 0);
                }
            }
            Assert.True(m.IsBowtieVertex(0));
            Assert.True(MeshAnalysisNormals.VertexNormal(m, 0).Length > 0.1);
            var c0 = MeshCurvature.Compute(m);
            AssertFinite(c0);
            Assert.False(c0.Valid[0]);
            Assert.Equal(1, c0.BowtieVertices);
            Assert.Equal(m.VertexCount - 1, c0.ValidVertices);
        }

        [Fact]
        public void Invariance_SimilarityAll()
        {
            DMesh3 m = Torus(2, 0.6, 30, 14);
            MeshEditor.Append(m, Icosphere(0.5, 2));
            var c0 = MeshCurvature.Compute(m);
            foreach (Similarity s in Similarity.All()) {
                var c = MeshCurvature.Compute(Invariance.Transformed(m, s));
                Assert.Equal(c0.ValidVertices, c.ValidVertices);
                foreach (int v in m.VertexIndices()) {
                    double h = c.Mean[v] * s.Scale, k = c.Gaussian[v] * s.Scale * s.Scale, a = c.MixedArea[v] / (s.Scale * s.Scale);
                    if (s.IsExact) {
                        Assert.True(h.Equals(c0.Mean[v]) && k.Equals(c0.Gaussian[v]) && a.Equals(c0.MixedArea[v])
                            && c.AngleDeficit[v].Equals(c0.AngleDeficit[v]), $"{s}: vertex {v}");
                        continue;
                    }
                    // UTM: coordinates of 6e6 with a size of 5 keep about 9 digits of the edge vectors
                    double tol = s.Translation == Vector3d.Zero ? 1e-9 : 1e-4;
                    Assert.True(Math.Abs(h - c0.Mean[v]) < tol * 3, $"{s}: H {h} vs {c0.Mean[v]}");
                    Assert.True(Math.Abs(k - c0.Gaussian[v]) < tol * 30, $"{s}: K {k} vs {c0.Gaussian[v]}");
                    Assert.True(Math.Abs(a - c0.MixedArea[v]) < tol * 0.1, $"{s}: A {a} vs {c0.MixedArea[v]}");
                }
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Low-severity shortcomings in mesh/ and curve/ from the class-by-class review
    /// (docs/Analyse-2026-10.md, "Mängel" of sections 2.2 and 2.3).
    /// </summary>
    public class MeshCurveLowFixesTests
    {
        static DMesh3 Sphere()
        {
            return new Sphere3Generator_NormalizedCube() { EdgeVertices = 6 }.Generate().MakeDMesh();
        }

        // mesh/ -----------------------------------------------------------------------------

        /// <summary> RemesherPro whose projection set is empty, while the smoothing set is all vertices </summary>
        class NoProjectionRemesher : gs.RemesherPro
        {
            public NoProjectionRemesher(DMesh3 m) : base(m) { }
            protected override IEnumerable<int> project_vertices() { return new int[0]; }
        }

        class SphereTarget : IProjectionTarget
        {
            public double Radius;
            public Vector3d Project(Vector3d vPoint, int identifier = -1) { return Radius * vPoint.Normalized; }
        }

        [Theory]
        [InlineData(false)]
        [InlineData(true)]
        public void RemesherPro_TrackedProjectionPass_UsesProjectionVertices(bool bParallel)
        {
            DMesh3 mesh = Sphere();
            var r = new NoProjectionRemesher(mesh) {
                EnableFlips = false, EnableSplits = false, EnableCollapses = false, EnableSmoothing = false,
                EnableParallelProjection = bParallel,
                ProjectionMode = Remesher.TargetProjectionMode.AfterRefinement,
            };
            r.SetProjectionTarget(new SphereTarget() { Radius = 2 });
