            Vector3d p0 = new Vector3d(0, 0, 0), p1 = new Vector3d(0.1, 0.2, 0.3), p2 = new Vector3d(0.3, 0.6, 0.9);
            Vector3d s2 = new Vector3d(0.3, 0.6 + 1e-9, 0.9 - 2e-9);
