                var m = new DMesh3();
                m.AppendTriangle(m.AppendVertex(Vector3d.Zero), m.AppendVertex(new Vector3d(4 * s, 0, 0)), m.AppendVertex(new Vector3d(-1 * s, 0.5 * s, 0)));
