using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    static class MeshFormatTestUtil
    {
        /// <summary>
        /// Sphere with normals, UVs and per-vertex colors, centered at center
        /// </summary>
        public static DMesh3 AttributeSphere(Vector3d center, double radius = 1.0)
        {
            DMesh3 mesh = new Sphere3Generator_NormalizedCube() { Radius = radius, EdgeVertices = 5 }.Generate().MakeDMesh();
            MeshTransforms.Translate(mesh, center);
            mesh.EnableVertexColors(Vector3f.One);
            foreach (int vid in mesh.VertexIndices()) {
                Vector3d n = mesh.GetVertexNormal(vid);
                mesh.SetVertexColor(vid, new Vector3f(0.5 + 0.5 * n.x, 0.5 + 0.5 * n.y, 0.5 + 0.5 * n.z));
            }
            return mesh;
        }

        public static WriteOptions AllAttributes(bool binary)
        {
            WriteOptions options = WriteOptions.Defaults;
            options.bWriteBinary = binary;
            options.bPerVertexNormals = true;
            options.bPerVertexColors = true;
            options.bPerVertexUVs = true;
            return options;
        }

        public static string TempDir()
        {
            string dir = Path.Combine(Path.GetTempPath(), "g3tests_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(dir);
            return dir;
        }

        public static List<DMesh3> ReadAll(string path, out IOReadResult result)
        {
            DMesh3Builder builder = new DMesh3Builder();
            result = StandardMeshReader.ReadFile(path, ReadOptions.Defaults, builder);
            return builder.Meshes;
        }

        public static DMesh3 WriteRead(DMesh3 mesh, string extension, WriteOptions options)
        {
            string dir = TempDir();
            try {
                string path = Path.Combine(dir, "mesh." + extension);
                IOWriteResult w = StandardMeshWriter.WriteMesh(path, mesh, options);
                Assert.Equal(IOCode.Ok, w.code);
                IOReadResult r;
                List<DMesh3> meshes = ReadAll(path, out r);
                Assert.True(r.code == IOCode.Ok, r.message);
                Assert.Single(meshes);
                return meshes[0];
            } finally {
                Directory.Delete(dir, true);
            }
        }

        /// <summary>
        /// Readers write vertices in the order of VertexIndices(), so a compact mesh maps 1:1
        /// </summary>
        public static void AssertSameTopology(DMesh3 expected, DMesh3 actual)
        {
            Assert.Equal(expected.VertexCount, actual.VertexCount);
            Assert.Equal(expected.TriangleCount, actual.TriangleCount);
            int[] ev = expected.VertexIndices().ToArray(), av = actual.VertexIndices().ToArray();
            Dictionary<int, int> map = new Dictionary<int, int>();
            for (int i = 0; i < ev.Length; ++i)
                map[ev[i]] = av[i];
            int[] et = expected.TriangleIndices().ToArray(), at = actual.TriangleIndices().ToArray();
            for (int i = 0; i < et.Length; ++i) {
                Index3i a = expected.GetTriangle(et[i]), b = actual.GetTriangle(at[i]);
                Assert.Equal(new Index3i(map[a.a], map[a.b], map[a.c]), b);
            }
        }

        public static double MaxPositionError(DMesh3 expected, DMesh3 actual)
        {
            int[] ev = expected.VertexIndices().ToArray(), av = actual.VertexIndices().ToArray();
            double err = 0;
            for (int i = 0; i < ev.Length; ++i)
                err = Math.Max(err, expected.GetVertex(ev[i]).Distance(actual.GetVertex(av[i])));
            return err;
        }

        public static double MaxAttributeError(DMesh3 expected, DMesh3 actual, Func<DMesh3, int, Vector3d> attribF)
        {
            int[] ev = expected.VertexIndices().ToArray(), av = actual.VertexIndices().ToArray();
            double err = 0;
            for (int i = 0; i < ev.Length; ++i)
                err = Math.Max(err, attribF(expected, ev[i]).Distance(attribF(actual, av[i])));
            return err;
        }

        public static double MaxUVError(DMesh3 expected, DMesh3 actual)
        {
            int[] ev = expected.VertexIndices().ToArray(), av = actual.VertexIndices().ToArray();
            double err = 0;
            for (int i = 0; i < ev.Length; ++i)
                err = Math.Max(err, expected.GetVertexUV(ev[i]).Distance(actual.GetVertexUV(av[i])));
            return err;
        }

        public static double Volume(DMesh3 mesh)
        {
            return MeshMeasurements.VolumeArea(mesh, mesh.TriangleIndices(), mesh.GetVertex).x;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Geodesic paths and loops by edge flips (MeshGeodesicPath, FlipOut). Developable meshes (plane, cube surface,
    /// polygonal cylinder) have exact geodesics in closed form: the straight line in the unfolding.
    /// </summary>
    public class MeshGeodesicPathTests
    {
        // ---------------------------------------------------------------- meshes

        /// <summary> plane grid of nx x ny cells of size h, interior vertices jittered in the plane, random diagonals </summary>
        static DMesh3 JitteredPlane(int nx, int ny, double h, int seed, out int[,] ids)
        {
            var rand = new Random(seed);
            var m = new DMesh3();
            ids = new int[nx + 1, ny + 1];
            for (int j = 0; j <= ny; ++j)
                for (int i = 0; i <= nx; ++i) {
                    bool inner = i > 0 && j > 0 && i < nx && j < ny;
                    double dx = inner ? 0.3 * h * (rand.NextDouble() - 0.5) : 0;
                    double dy = inner ? 0.3 * h * (rand.NextDouble() - 0.5) : 0;
                    ids[i, j] = m.AppendVertex(new Vector3d(i * h + dx, j * h + dy, 0));
                }
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < nx; ++i) {
                    int a = ids[i, j], b = ids[i + 1, j], c = ids[i + 1, j + 1], d = ids[i, j + 1];
                    if (rand.Next(2) == 0) { m.AppendTriangle(a, b, c); m.AppendTriangle(a, c, d); }
                    else { m.AppendTriangle(a, b, d); m.AppendTriangle(b, c, d); }
                }
            return m;
        }

        /// <summary>
        /// open polygonal cylinder: n slices around (radius 1), rings + 1 rings of height dz; quad (i, j) split by the
        /// diagonal (i, j) - (i + 1, j + 1). Unfolded it is a plane strip: slice i at x = i * chord.
        /// </summary>
        static DMesh3 Cylinder(int n, int rings, double dz, out int[,] ids)
        {
            var m = new DMesh3();
            ids = new int[n, rings + 1];
            for (int j = 0; j <= rings; ++j)
                for (int i = 0; i < n; ++i) {
                    double a = 2 * Math.PI * i / n;
                    ids[i, j] = m.AppendVertex(new Vector3d(Math.Cos(a), Math.Sin(a), j * dz));
                }
            for (int j = 0; j < rings; ++j)
                for (int i = 0; i < n; ++i) {
                    int a = ids[i, j], b = ids[(i + 1) % n, j], c = ids[(i + 1) % n, j + 1], d = ids[i, j + 1];
                    m.AppendTriangle(a, b, c); m.AppendTriangle(a, c, d);
                }
            return m;
        }

        static double Chord(int n) { return 2 * Math.Sin(Math.PI / n); }

        /// <summary> L-shaped plane: [0, 2] x [0, 1] and [0, 1] x [0, 2], cells of 0.1; the reflex corner at (1, 1) </summary>
        static DMesh3 LShape(out Dictionary<(int, int), int> ids)
        {
            var m = new DMesh3();
            var map = new Dictionary<(int, int), int>();
            Func<int, int, int> v = (i, j) => {
                int id;
                if (map.TryGetValue((i, j), out id) == false) map[(i, j)] = id = m.AppendVertex(new Vector3d(0.1 * i, 0.1 * j, 0));
                return id;
            };
            for (int j = 0; j < 20; ++j)
                for (int i = 0; i < 20; ++i) {
                    if (i >= 10 && j >= 10) continue;
                    int a = v(i, j), b = v(i + 1, j), c = v(i + 1, j + 1), d = v(i, j + 1);
                    if ((i + j) % 2 == 0) { m.AppendTriangle(a, b, c); m.AppendTriangle(a, c, d); }
                    else { m.AppendTriangle(a, b, d); m.AppendTriangle(b, c, d); }
                }
            ids = map;
            return m;
        }

        static DMesh3 BumpySphere()
        {
            DMesh3 m = new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = 12 }.Generate().MakeDMesh();
            foreach (int vid in m.VertexIndices()) {
                Vector3d p = m.GetVertex(vid);
                m.SetVertex(vid, p * (1 + 0.2 * Math.Sin(3 * p.x + 1) * Math.Cos(2 * p.y - 0.5) + 0.05 * p.z));
            }
            return m;
        }

        static int Nearest(DMesh3 m, Vector3d p)
        {
            return m.VertexIndices().OrderBy(v => m.GetVertex(v).Distance(p)).First();
        }

        // ---------------------------------------------------------------- checks

        /// <summary> the result is a finite polyline from the source to the target whose length is Length </summary>
        /// (pointResolution: rounding of the path points, which far from the origin limits the polyline length's accuracy)
        static void AssertValidPath(MeshGeodesicPath g, DMesh3 mesh, int source, int target, double pointResolution = 0)
        {
            Assert.True(g.Path.Count >= 2, "path has points");
            Assert.True(g.Path.All(p => p.IsFinite), "finite points");
            Assert.Equal(mesh.GetVertex(source), g.Path[0]);
            Assert.Equal(mesh.GetVertex(target), g.Path[g.Path.Count - 1]);
            Assert.Equal(source, g.PathVertices[0]);
            Assert.Equal(target, g.PathVertices[g.PathVertices.Count - 1]);
            double poly = 0;
            for (int k = 1; k < g.Path.Count; ++k) poly += g.Path[k].Distance(g.Path[k - 1]);
            Assert.True(Math.Abs(poly - g.Length) <= 1e-9 * g.Length + 4 * g.Path.Count * pointResolution,
                $"polyline length {poly} vs Length {g.Length}");
            Assert.True(g.Length <= g.InitialLength * (1 + 1e-15), "not longer than the edge path");
        }

