                    if (ExactPredicates.Orient2d(a, b, c) * ExactPredicates.Orient2d(a, b, d) < 0 && ExactPredicates.Orient2d(c, d, a) * ExactPredicates.Orient2d(c, d, b) < 0) ++crossings;
