            yield return new object[] { new[] { new Vector2d(0, 0), new Vector2d(-0.0, 0), new Vector2d(3, 3), new Vector2d(1, 1), new Vector2d(3, 3) }, new[] { 0, 0, 2, 3, 2 } }; // collinear, -0
