        [Fact]
        public void Execute_WrongUsage_IsExitCode2WithAMessage()
        {
            string dir = TempDir(), output = Path.Combine(dir, "o.txt"), input = Path.Combine(dir, "in.txt");
            File.WriteAllText(input, TextFormat.WriteInput(Reference("f-1/a").Input));
            foreach (var args in new[] {
                new[] { "--output", output },
                new[] { "--case", "f-1/a" },
                new[] { "--case", "f-1/a", "--input", input, "--output", output },
                new[] { "--case", "no/such-case", "--output", output },
                new[] { "--case", "f-1/a", "--milestone", "M3", "--output", output },
                new[] { "--input", input, "--milestone", "7", "--output", output },
                new[] { "--input", input, "--milestone", "M4", "--output", output },
                new[] { "--input", Path.Combine(dir, "missing.txt"), "--output", output },
                new[] { "--case", "f-1/a", "--output", Path.Combine(dir, "no", "dir", "o.txt") },
                new[] { "--case", "f-1/a", "--output" },
            }) {
                var (exit, stdout, stderr) = Execute(args);
                Assert.True(exit == 2, string.Join(" ", args) + " -> " + exit + " " + stderr);
                Assert.False(string.IsNullOrWhiteSpace(stderr), string.Join(" ", args));
            }
            Assert.False(File.Exists(output));
            // a bad input file is a usage error too
            File.WriteAllText(input, "mesh2-input 1\npoints 2\n");
            Assert.Equal(2, Execute("--input", input, "--output", output).exit);
            // the milestone in any case
            File.WriteAllText(input, TextFormat.WriteInput(Reference("f-1/a").Input));
            Assert.Equal(0, Execute("--input", input, "--milestone", "m2", "--output", output).exit);
        }

        [Fact]
        public void InferMilestone_FollowsTheOptions()
        {
            var points = new Mesh2Input { X = new double[] { 0, 1, 0 }, Y = new double[] { 0, 0, 1 } };
            Assert.Equal(Milestone.M1, MeshCommand.InferMilestone(points));
            var segment = new Mesh2Input { X = points.X, Y = points.Y };
            segment.Segments.Add(new SegmentInput(0, 1, 0, false));
            Assert.Equal(Milestone.M2, MeshCommand.InferMilestone(segment));
            Assert.Equal(Milestone.M2, MeshCommand.InferMilestone(new Mesh2Input { X = points.X, Y = points.Y, ResolveCrossings = false }));
            Assert.Equal(Milestone.M3, MeshCommand.InferMilestone(new Mesh2Input { X = points.X, Y = points.Y, MinAngleDeg = 0 }));
            Assert.Equal(Milestone.M3, MeshCommand.InferMilestone(new Mesh2Input { X = points.X, Y = points.Y, MaxArea = 1 }));
            Assert.Equal(Milestone.M3, MeshCommand.InferMilestone(new Mesh2Input { X = points.X, Y = points.Y, SteinerLimit = 5 }));
            Assert.Equal(Milestone.M3, MeshCommand.InferMilestone(new Mesh2Input { X = points.X, Y = points.Y, Conforming = true }));
            Assert.Equal(Milestone.M3, MeshCommand.InferMilestone(new Mesh2Input { X = points.X, Y = points.Y, SizeConstant = 0.5 }));
            var region = new Mesh2Input { X = points.X, Y = points.Y };
            region.Regions.Add(new RegionInput { Label = 1, Seed = new[] { 0.2, 0.2 } });
            Assert.Equal(Milestone.M2, MeshCommand.InferMilestone(region));
            region.Regions[0].MaxArea = 0.01;
            Assert.Equal(Milestone.M3, MeshCommand.InferMilestone(region));
            var ring = new Mesh2Input { X = points.X, Y = points.Y };
            ring.Rings.Add(new RingInput(new[] { 0, 1, 2 }, false));
            Assert.Equal(Milestone.M2, MeshCommand.InferMilestone(ring));
            var hole = new Mesh2Input { X = points.X, Y = points.Y };
            hole.HoleSeeds.Add(new[] { 5.0, 5.0 });
            Assert.Equal(Milestone.M2, MeshCommand.InferMilestone(hole));
            Assert.Equal(Milestone.M2, MeshCommand.InferMilestone(new Mesh2Input { X = points.X, Y = points.Y, SnapTolerance = 0.5 }));
            Assert.Equal(Milestone.M3, MeshCommand.InferMilestone(new Mesh2Input { X = points.X, Y = points.Y, SizeFunction = (x, y) => Q.FromDouble(1) }));
            // an explicit milestone wins
            Assert.Equal(Milestone.M3, MeshCommand.FromInput(points, "p", Milestone.M3).Milestone);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The oracle's test whether a triangle's circumcentre (or its pixel centre on the grid) lies behind an unsplittable subsegment uses
    /// the subsegment grid for the constructed point too (by its interval of doubles), not only for a vertex. An unrefined mesh (M2) of
    /// many short segments and points, judged at M3, sends almost every triangle through the whole exemption chain; with
    /// Oracle.CheckFastPathForTests every grid query is checked to return a superset of the boxes that meet the query, and every answer
    /// against the scan of all subsegments, so a query box that misses the constructed point throws.
    /// </summary>
    public class Meshing2OracleBehindIndexTests
    {
        static string H(double x) => "0x" + BitConverter.DoubleToInt64Bits(x).ToString("x16", CultureInfo.InvariantCulture);

        /// <summary> a square of side 64 with a grid of short disjoint segments and random points (fixed seed) </summary>
        static Mesh2Input Input(int seed, double snap, double length)
        {
            var rnd = new Random(seed);
            var pts = new List<(double, double)> { (0, 0), (64, 0), (64, 64), (0, 64) };
            var segs = new List<(int, int)>();
            for (int i = 0; i < 12; ++i)
                for (int j = 0; j < 12; ++j) {
                    double x = 2 + i * 5, y = 2 + j * 5;
                    segs.Add((pts.Count, pts.Count + 1));
                    pts.Add((x, y));
                    pts.Add((x + length * (0.5 + rnd.NextDouble()), y + length * (rnd.NextDouble() - 0.5)));
                }
            for (int k = 0; k < 1200; ++k) pts.Add((1 + 62 * rnd.NextDouble(), 1 + 62 * rnd.NextDouble()));
            var sb = new StringBuilder("mesh2-input 1\npoints " + pts.Count + "\n");
            foreach (var (x, y) in pts) sb.Append(H(x)).Append(' ').Append(H(y)).Append('\n');
            sb.Append("segments " + segs.Count + "\n");
            foreach (var (a, b) in segs) sb.Append(a).Append(' ').Append(b).Append(" 0 0\n");
            sb.Append("rings 1\nouter 0 4 0 1 2 3\nholeseeds 0\nregions 0\nmin_angle_deg ").Append(H(20)).Append("\nmax_area -\nsteiner_limit -\n");
            sb.Append("snap_tolerance ").Append(H(snap)).Append("\nsize_constant -\nresolve_crossings 1\nconforming 0\nend\n");
            return TextFormat.ReadInput(sb.ToString());
        }

        [Theory]
        [InlineData(5, 0.0, 2.0)]
        [InlineData(6, 0.0, 2.0)]
        [InlineData(7, 0.25, 0.4)]
        [InlineData(8, 0.25, 0.4)]
        [InlineData(9, 0.125, 0.2)]
        public void UnrefinedMesh_AtM3_CircumcentreQueriesAreSupersets(int seed, double snap, double length)
        {
            var input = Input(seed, snap, length);
            var output = CandidateRegistry.For(Milestone.M2).Run(input);
            Assert.Equal(Mesh2Status.Success, output.Status);
            Oracle.CheckFastPathForTests = true;
            OracleReport report;
            try { report = Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 }); }
            finally { Oracle.CheckFastPathForTests = false; }
            // the unrefined mesh has triangles below the bound, so the exemption chain ran on them
            Assert.False(report.Ok);
            Assert.True(report.Has(Violation.AngleBelowBound) || report.Violations.Count == 200, report.ToString());
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The conformity check's candidate pairs (<see cref="BoxPairs.Overlaps"/>): a sweep over x with two segment trees over y,
    /// in place of the plain sweep whose active list long boxes kept long. The pairs must be exactly those of a brute-force test,
    /// each once. The conformity report must not depend on the order in which the pairs come: it names the first 8 violations in
    /// index order.
    /// </summary>
    public class Meshing2OracleBoxPairsTests
    {
        static int[][] RandomBoxes(Random random, int n, int range, int maxSize)
        {
            var boxes = new int[n][];
            for (int i = 0; i < n; ++i) {
                int x = random.Next(range), y = random.Next(range);
                boxes[i] = new[] { x, Math.Min(range - 1, x + random.Next(maxSize + 1)), y, Math.Min(range - 1, y + random.Next(maxSize + 1)) };
            }
            return boxes;
        }

        static bool Overlap(int[] p, int[] q) => p[0] <= q[1] && q[0] <= p[1] && p[2] <= q[3] && q[2] <= p[3];

        static HashSet<(int, int)> BruteForce(int[][] a, int[][] b, bool same)
        {
            var pairs = new HashSet<(int, int)>();
            if (same) {
                for (int i = 0; i < a.Length; ++i) for (int j = i + 1; j < a.Length; ++j) if (Overlap(a[i], a[j])) pairs.Add((i, j));
            } else {
                for (int i = 0; i < a.Length; ++i) for (int j = 0; j < b.Length; ++j) if (Overlap(a[i], b[j])) pairs.Add((i, j));
            }
            return pairs;
        }

        static List<(int, int)> Found(Action<int[][], int[][], bool, Action<int, int>> pairsOf, int[][] a, int[][] b, bool same)
        {
            var found = new List<(int, int)>();
            pairsOf(a, b, same, (i, j) => found.Add(same ? (Math.Min(i, j), Math.Max(i, j)) : (i, j)));
            return found;
        }

        /// <summary> random boxes, from many ties on a small range (points, shared ends) to long boxes in either direction: the pairs are
        /// those of the brute-force test, each once, and the same as the plain sweep's </summary>
        [Theory]
        [InlineData(1, 8, 2, false)]
        [InlineData(2, 8, 2, true)]
        [InlineData(3, 40, 10, false)]
        [InlineData(4, 40, 10, true)]
        [InlineData(5, 1000, 3, false)]
        [InlineData(6, 1000, 3, true)]
        [InlineData(7, 1000, 1000, false)]
        [InlineData(8, 1000, 1000, true)]
        [InlineData(9, 3, 0, false)]
        [InlineData(10, 1, 0, true)]
        public void Pairs_AreThoseOfTheBruteForceTest_EachOnce(int seed, int range, int maxSize, bool same)
        {
            var random = new Random(seed);
            for (int round = 0; round < 20; ++round) {
                var a = RandomBoxes(random, random.Next(0, 120), range, maxSize);
                var b = same ? a : RandomBoxes(random, random.Next(0, 120), range, maxSize);
                var expected = BruteForce(a, b, same);
                var found = Found(BoxPairs.Overlaps, a, b, same);
                Assert.Equal(found.Count, found.Distinct().Count());
                Assert.True(expected.SetEquals(found), $"round {round}: {expected.Count} expected, {found.Count} found");
                Assert.True(expected.SetEquals(Found(BoxPairs.OverlapsBySweep, a, b, same)));
            }
        }

        /// <summary> long thin boxes in x, as Delaunay triangles between points on a few vertical lines give them (the case that kept the
        /// plain sweep's active list long), crossed by short boxes </summary>
        [Fact]
        public void LongBoxes_InX_AndShortOnes()
        {
            var boxes = new List<int[]>();
            for (int i = 0; i < 300; ++i) boxes.Add(new[] { 0, 999, i, i + 1 });
            for (int i = 0; i < 300; ++i) boxes.Add(new[] { 3 * i, 3 * i, (7 * i) % 301, (7 * i) % 301 });
            var a = boxes.ToArray();
            var expected = BruteForce(a, a, true);
            var found = Found(BoxPairs.Overlaps, a, a, true);
            Assert.Equal(found.Count, found.Distinct().Count());
            Assert.True(expected.SetEquals(found));
            var points = boxes.Skip(300).ToArray();
            var lines = boxes.Take(300).ToArray();
            Assert.True(BruteForce(lines, points, false).SetEquals(Found(BoxPairs.Overlaps, lines, points, false)));
        }

        static long Key(int a, int b) => a < b ? ((long)a << 32) | (uint)b : ((long)b << 32) | (uint)a;

        static OracleReport Judge(List<double> vx, List<double> vy, List<int[]> tris, bool check)
        {
            var input = new Mesh2Input { X = vx.ToArray(), Y = vy.ToArray() };
            var output = new Mesh2Output {
                Status = Mesh2Status.Success, VX = vx.ToArray(), VY = vy.ToArray(), InputToVertex = Enumerable.Range(0, input.Count).ToArray(),
                Triangles = tris.ToArray(), BadTriangles = new int[0], Subsegments = new List<SubsegmentOutput>() };
            Oracle.CheckFastPathForTests = check;
            try { return Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M1 }); }
            finally { Oracle.CheckFastPathForTests = false; }
        }

        /// <summary> the grid points (i, j) for 0 &lt;= i, j &lt;= n (shifted by dx, dy), numbered in a shuffled order: the index order
        /// then differs from the order in which a sweep meets them </summary>
        static int[,] ShuffledGrid(int n, double dx, double dy, Random random, List<double> vx, List<double> vy)
        {
            int start = vx.Count, count = (n + 1) * (n + 1);
            var slots = Enumerable.Range(start, count).OrderBy(_ => random.Next()).ToArray();
            var index = new int[n + 1, n + 1];
            for (int k = 0; k < count; ++k) { vx.Add(0); vy.Add(0); }
            int s = 0;
            for (int i = 0; i <= n; ++i) for (int j = 0; j <= n; ++j) {
                index[i, j] = slots[s++];
                vx[index[i, j]] = i + dx; vy[index[i, j]] = j + dy;
            }
            return index;
        }

        /// <summary>
        /// Two triangulations of an n x n grid laid over each other, one with the diagonals / and one with \: the two diagonals of every
        /// cell cross. Vertices and triangles are numbered in a shuffled order. The report names the first 8 crossings by their edges in
        /// index order, whatever order the pairs came in, with and without the check mode.
        /// </summary>
        [Theory]
        [InlineData(1)]
        [InlineData(2)]
        [InlineData(3)]
        public void Crossings_AreReportedInIndexOrder(int seed)
        {
            const int n = 5;
            var random = new Random(seed);
            var vx = new List<double>(); var vy = new List<double>();
            var V = ShuffledGrid(n, 0, 0, random, vx, vy);
            var tris = new List<int[]>();
            var expected = new List<(long, long)>();
            for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
                int v00 = V[i, j], v10 = V[i + 1, j], v01 = V[i, j + 1], v11 = V[i + 1, j + 1];
                tris.Add(new[] { v00, v10, v11 }); tris.Add(new[] { v00, v11, v01 });
                tris.Add(new[] { v00, v10, v01 }); tris.Add(new[] { v10, v11, v01 });
                long k1 = Key(v00, v11), k2 = Key(v10, v01);
                expected.Add((Math.Min(k1, k2), Math.Max(k1, k2)));
            }
            tris = tris.OrderBy(_ => random.Next()).ToList();
            expected.Sort();
            var names = expected.Take(8).Select(p => "edges " + (int)(p.Item1 >> 32) + "-" + (int)(uint)p.Item1 + " and "
                + (int)(p.Item2 >> 32) + "-" + (int)(uint)p.Item2 + " cross").ToList();
            foreach (bool check in new[] { false, true }) {
                var report = Judge(vx, vy, tris, check);
                Assert.Equal(names, report.Violations.Where(x => x.Kind == Violation.EdgesCross).Select(x => x.Detail).ToList());
            }
        }

        /// <summary>
        /// Two grid triangulations, the second shifted by (0.5, 0.25) so that its vertices lie inside triangles of the first and the
        /// other way round, numbered and ordered in a shuffled way: the report names the first 8 (triangle, vertex) pairs in index
        /// order, found by a brute-force test here.
        /// </summary>
        [Theory]
        [InlineData(1)]
        [InlineData(2)]
        public void TouchingVertices_AreReportedInIndexOrder(int seed)
        {
            const int n = 4;
            var random = new Random(seed);
            var vx = new List<double>(); var vy = new List<double>();
            var A = ShuffledGrid(n, 0, 0, random, vx, vy);
            var B = ShuffledGrid(n, 0.5, 0.25, random, vx, vy);
            var tris = new List<int[]>();
            foreach (var V in new[] { A, B })
                for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
                    tris.Add(new[] { V[i, j], V[i + 1, j], V[i + 1, j + 1] });
                    tris.Add(new[] { V[i, j], V[i + 1, j + 1], V[i, j + 1] });
                }
            tris = tris.OrderBy(_ => random.Next()).ToList();
            double Orient(int a, int b, int c) => (vx[b] - vx[a]) * (vy[c] - vy[a]) - (vy[b] - vy[a]) * (vx[c] - vx[a]);
            var expected = new List<(int, int)>();
            for (int ti = 0; ti < tris.Count; ++ti)
                for (int id = 0; id < vx.Count; ++id) {
                    var t = tris[ti];
                    if (id == t[0] || id == t[1] || id == t[2]) continue;
                    if (Orient(t[0], t[1], id) >= 0 && Orient(t[1], t[2], id) >= 0 && Orient(t[2], t[0], id) >= 0) expected.Add((ti, id));
                }
            Assert.True(expected.Count > 8);
            expected.Sort();
            var names = expected.Take(8).Select(p => "vertex " + p.Item2 + " / touches triangle " + string.Join(" ", tris[p.Item1])).ToList();
            foreach (bool check in new[] { false, true }) {
                var report = Judge(vx, vy, tris, check);
                var found = report.Violations.Where(x => x.Kind == Violation.VertexInTriangle && x.Detail.Contains(" touches triangle "))
                    .Select(x => {
                        var d = x.Detail;
                        string id = d.Substring(0, d.IndexOf(' ', "vertex ".Length));
                        return id + " / " + d.Substring(d.IndexOf("touches triangle "));
                    }).ToList();
                Assert.Equal(names, found);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The witness of the oracle's global Delaunay pass (MESHING2D_FAST_ORACLE.md section 6): the oracle's own Delaunay triangulation of
    /// the used vertices, certified, so that the pass runs only on the output triangles that are not its triangles. A witness that is
    /// wrong in any way the certificate tests is refused, and the pass runs in full with the same verdicts; the reduction gives the
    /// full pass's reports and counts (also compared in check mode by every run of Meshing2OracleFastPathCheckTests).
    /// </summary>
    public class Meshing2OracleDelaunayWitnessTests
    {
        static readonly OracleExpect M1 = new OracleExpect { Milestone = Milestone.M1 };
        static readonly OracleExpect M3 = new OracleExpect { Milestone = Milestone.M3 };

        static Mesh2Input Points(IList<(double x, double y)> p) =>
            new Mesh2Input { X = p.Select(q => q.x).ToArray(), Y = p.Select(q => q.y).ToArray() };

        static Mesh2Input RandomPoints(int seed, int n)
        {
            var rnd = new Random(seed);
            var p = new List<(double, double)>();
            for (int i = 0; i < n; ++i) p.Add((rnd.Next(0, 1 << 20) / 1024.0, rnd.Next(0, 1 << 20) / 1024.0));
            return Points(p.Distinct().ToList());
        }

        static (OracleReport report, string pass) Run(Mesh2Input input, Mesh2Output o, OracleExpect e, Func<List<int[]>, List<int[]>> corrupt = null,
            bool skipCertificate = false, bool failWitness = false)
        {
            Oracle.CorruptWitnessForTests = corrupt;
            Oracle.SkipWitnessCertificateForTests = skipCertificate;
            Oracle.FailWitnessForTests = failWitness;
            Oracle.LastGlobalPassForTests = null;
            try {
                var report = Oracle.Check(input, o, e);
                return (report, Oracle.LastGlobalPassForTests);
            } finally {
                Oracle.CorruptWitnessForTests = null;
                Oracle.SkipWitnessCertificateForTests = false;
                Oracle.FailWitnessForTests = false;
            }
        }

        static string Summary(OracleReport r) => r + " | " + r.MergeZoneExcused + " " + r.O11GlobalExcused + " " + r.O11LocalExcused + " " + r.TieEdges;

        static Mesh2Output WithTriangles(Mesh2Output o, int[][] tris) => new Mesh2Output {
            Status = o.Status, VX = o.VX, VY = o.VY, InputToVertex = o.InputToVertex, Triangles = tris, Neighbours = SelfCheck.NeighboursOf(tris),
            BadTriangles = o.BadTriangles, Subsegments = o.Subsegments };

        /// <summary> an interior edge whose flip gives two positive triangles, not a tie: the flipped triangulation is not Delaunay </summary>
        static int[][] Flip(Mesh2Output o)
        {
            var t = o.Triangles;
            Q X(int i) => Q.FromDouble(o.VX[i]);
            Q Y(int i) => Q.FromDouble(o.VY[i]);
            int Orient(int a, int b, int c) => ((X(b) - X(a)) * (Y(c) - Y(a)) - (Y(b) - Y(a)) * (X(c) - X(a))).Sign;
            int InCircle(int a, int b, int c, int d)
            {
                Q ax = X(a) - X(d), ay = Y(a) - Y(d), bx = X(b) - X(d), by = Y(b) - Y(d), cx = X(c) - X(d), cy = Y(c) - Y(d);
                return ((ax * ax + ay * ay) * (bx * cy - cx * by) + (bx * bx + by * by) * (cx * ay - ax * cy) + (cx * cx + cy * cy) * (ax * by - bx * ay)).Sign;
            }
            for (int i = 0; i < t.Length; ++i)
                for (int k = 0; k < 3; ++k) {
                    int a = t[i][k], b = t[i][(k + 1) % 3], c = t[i][(k + 2) % 3];
                    for (int j = i + 1; j < t.Length; ++j)
                        for (int m = 0; m < 3; ++m) {
                            if (t[j][m] != b || t[j][(m + 1) % 3] != a) continue;
                            int d = t[j][(m + 2) % 3];
                            if (Orient(c, a, d) <= 0 || Orient(d, b, c) <= 0) continue;
                            var copy = t.Select(x => (int[])x.Clone()).ToArray();
                            copy[i] = new[] { c, a, d };
                            copy[j] = new[] { d, b, c };
                            // the flipped edge c-d is not locally Delaunay: b strictly inside the circumcircle of (c, a, d)
                            if (InCircle(c, a, d, b) > 0) return copy;
                        }
                }
            throw new InvalidOperationException("no edge to flip");
        }

        /// <summary> on random points (Delaunay and with a flipped edge) and the lens fuzz in the conforming mode (holes, merge zones)
        /// the witness is certified and used whenever the global pass runs (no fallback), and the full pass (the witness failed) gives the same reports and counts </summary>
        [Fact]
        public void Witness_IsUsed_AndTheFallbackGivesTheSameReports()
        {
            int used = 0;
            void Compare(Mesh2Input input, Mesh2Output o, OracleExpect e, string what)
            {
                var (withWitness, pass) = Run(input, o, e);
                if (!withWitness.GlobalDelaunayChecked) return;
                Assert.True(pass == "witness", what + ": " + pass);
                ++used;
                var (full, fallback) = Run(input, o, e, failWitness: true);
                Assert.Equal("fallback: failed for tests", fallback);
                Assert.Equal(Summary(full), Summary(withWitness));
            }
            for (int seed = 0; seed < 10; ++seed) {
                var input = RandomPoints(seed, 50 + 40 * seed);
                var o = CandidateRegistry.For(Milestone.M1).Run(input);
                Compare(input, o, M1, "points " + seed);
                Compare(input, WithTriangles(o, Flip(o)), M1, "flipped points " + seed);
            }
            for (int seed = 0; seed < 12; ++seed) {
                var input = QualityMesh2LensDeletionTests.Fuzz(7000 + seed, new[] { 20.0, 25, 30 }[seed % 3], new[] { 0, 0.25, 0.125 }[seed % 3]);
                input.ConstrainedQuality = false;   // (the conforming mode: the global pass runs, with its excuses)
                var o = new QualityMesh2Candidate().Run(input);
                Compare(input, o, M3, "fuzz " + seed);
            }
            Assert.True(used >= 25, "the witness was used " + used + " times");
        }

        /// <summary> a non-Delaunay output (one flipped edge in a Delaunay triangulation of random points) is still found: the two
        /// flipped triangles are not triangles of the witness, and the pass runs on them </summary>
        [Fact]
        public void FlippedEdge_IsReported_WithTheWitness()
        {
            for (int seed = 0; seed < 5; ++seed) {
                var input = RandomPoints(100 + seed, 200);
                var o = CandidateRegistry.For(Milestone.M1).Run(input);
                var (good, gp) = Run(input, o, M1);
                Assert.True(good.Ok && gp == "witness", good + " " + gp);
                var (bad, bp) = Run(input, WithTriangles(o, Flip(o)), M1);
                Assert.Equal("witness", bp);
                Assert.Equal(2, bad.Violations.Count(v => v.Kind == Violation.NotDelaunayGlobal));
            }
        }

        /// <summary>
        /// The case the local test alone misses: a thin hole [2,8] x [1,1.01] in [0,10] x [-1,2] with a vertex E (5,0) below it. The
        /// constrained Delaunay triangulation (the mesher without conforming) has the triangle P Q E under the hole's lower side, and the
        /// hole's upper corners lie inside its circumcircle (centre (5,5), radius 5), across the hole: every edge is locally (constrained)
        /// Delaunay, the mesh is not conforming Delaunay. Judged as conforming, the global pass with the witness reports it, as the
        /// reference path does
        /// </summary>
        [Fact]
        public void AcrossAHole_TheGlobalPassReports_WithTheWitness()
        {
            var input = Points(new List<(double, double)> { (0, -1), (10, -1), (10, 2), (0, 2), (2, 1), (8, 1), (8, 1.01), (2, 1.01), (5, 0) });
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            input.Rings.Add(new RingInput(new[] { 4, 5, 6, 7 }, true));
            var o = CandidateRegistry.For(Milestone.M2).Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            Assert.Equal(9, o.VX.Length);
            int e = 8;
            Assert.Contains(o.Triangles, t => t.Contains(4) && t.Contains(5) && t.Contains(e));
            var m2 = new OracleExpect { Milestone = Milestone.M2 };
            var (cdt, _) = Run(input, o, m2);
            Assert.True(cdt.Ok, cdt.ToString());
            input.Conforming = true;
            var (fast, pass) = Run(input, o, m2);
            Assert.Equal("witness", pass);
            Assert.True(fast.Has(Violation.NotDelaunayGlobal), fast.ToString());
            Assert.False(fast.Has(Violation.NotDelaunayLocal), fast.ToString());
            var reference = Oracle.Check(input, o, m2.WithReference());
            Assert.Equal(fast.ToString(), reference.ToString());
        }

        /// <summary>
        /// The global test's hidden vertex (HiddenByO11Unsplittable, through Behind) on the fast path asks the subsegment grid for the
        /// pieces near the box of the triangle and the vertex. The layout of the oracle's self-check 7b: legs A (4, 8)-(12, 8) and
        /// B (4, 8)-(12, 8.375) at a small angle, B's first piece ending 3/64 from A, the flat triangle (4.25, 8.125), (4.75, 8.125),
        /// (4.5, 8.25) above it, and the vertex (4.5, 8) inside its circumcircle, hidden by the piece, which lies below the triangle's
        /// box. With 10000 short subsegments elsewhere the grid's cells are 0.08 wide, so a query box of the triangle alone misses the
        /// piece: the vertex is then reported. With the vertex in the box it is excused, as on the reference path (and the check mode
        /// compares the grid's answer with the scan of all subsegments)
        /// </summary>
        [Fact]
        public void HiddenVertex_BelowTheTrianglesBox_IsFoundThroughTheGrid()
        {
            var xy = new List<double> { 0, 0, 16, 0, 16, 16, 0, 16, 4, 8, 12, 8, 12, 8.375, 5, 8.046875, 4.25, 8.125, 4.75, 8.125, 4.5, 8.25, 4.5, 8, 4, 7.5, 5, 7.5 };
            var input = new Mesh2Input { X = xy.Where((_, i) => i % 2 == 0).ToArray(), Y = xy.Where((_, i) => i % 2 == 1).ToArray() };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            input.Segments.Add(new SegmentInput(4, 5));
            input.Segments.Add(new SegmentInput(4, 6));
            input.MinAngleDeg = 20;
            var vx = input.X.ToList(); var vy = input.Y.ToList();
            var subs = new List<SubsegmentOutput> { new SubsegmentOutput(4, 7), new SubsegmentOutput(7, 6), new SubsegmentOutput(4, 11), new SubsegmentOutput(11, 5) };
            // 10000 short pieces on a lattice over [4, 12] x [9, 16]: they only make the grid fine
            for (int i = 0; i < 100; ++i)
                for (int j = 0; j < 100; ++j) {
                    vx.Add(4 + 0.08 * i); vy.Add(9 + 0.07 * j); vx.Add(4 + 0.08 * i + 0.01); vy.Add(9 + 0.07 * j);
                    subs.Add(new SubsegmentOutput(vx.Count - 2, vx.Count - 1));
                }
            var tris = new[] { new[] { 8, 9, 10 }, new[] { 11, 12, 13 } };
            var o = new Mesh2Output { Status = Mesh2Status.Success, VX = vx.ToArray(), VY = vy.ToArray(), InputToVertex = Enumerable.Range(0, input.Count).ToArray(),
                Triangles = tris, Neighbours = SelfCheck.NeighboursOf(tris), BadTriangles = new int[0], Subsegments = subs };
            var e = new OracleExpect { Milestone = Milestone.M3, Tube = new Q(1, 16) };
            Oracle.CheckFastPathForTests = true;
            OracleReport fast;
            try { fast = Oracle.Check(input, o, e); } finally { Oracle.CheckFastPathForTests = false; }
            Assert.True(fast.GlobalDelaunayChecked, fast.ToString());
            Assert.False(fast.ToString().Contains("vertex 11 inside the circumcircle of 8 9 10"), fast.ToString());
            Assert.True(fast.O11GlobalExcused > 0, fast.ToString());
            var reference = Oracle.Check(input, o, e.WithReference());
            Assert.Equal(fast.O11GlobalExcused, reference.O11GlobalExcused);
        }

        /// <summary> two used vertices at the same point (different ids): no witness, the full pass, with its verdicts </summary>
        [Fact]
        public void DuplicateCoordinates_FallBackToTheFullPass()
        {
            var input = Points(new List<(double, double)> { (0, 0), (4, 0), (4, 4), (0, 4), (1, 1) });
            var vx = new[] { 0.0, 4, 4, 0, 1, 0 }; var vy = new[] { 0.0, 0, 4, 4, 1, 0 };
            var tris = new[] { new[] { 0, 1, 4 }, new[] { 1, 2, 4 }, new[] { 2, 3, 4 }, new[] { 3, 5, 4 } };
            var o = new Mesh2Output { Status = Mesh2Status.Success, VX = vx, VY = vy, InputToVertex = Enumerable.Range(0, 5).ToArray(),
                Triangles = tris, Neighbours = SelfCheck.NeighboursOf(tris), BadTriangles = new int[0], Subsegments = new List<SubsegmentOutput>() };
            input.Conforming = true;
            var m2 = new OracleExpect { Milestone = Milestone.M2 };
            var (got, pass) = Run(input, o, m2);
            Assert.True(pass == "fallback: two vertices coincide", got + " | " + pass);
            var (full, _) = Run(input, o, m2, failWitness: true);
            Assert.Equal(Summary(full), Summary(got));
        }

        /// <summary> a 7 x 7 lattice: every hull side has five points between its corners (the ghosts' on-the-edge case of the
        /// conflict test, boundary edges between points that are no hull corners), every cell four cocircular points; and the same
        /// lattice with every second point of the bottom row dropped </summary>
        [Fact]
        public void Lattice_CollinearHullPoints_GiveACertifiedWitness()
        {
            for (int variant = 0; variant < 2; ++variant) {
                var p = new List<(double, double)>();
                for (int i = 0; i < 7; ++i)
                    for (int j = 0; j < 7; ++j)
                        if (variant == 0 || j != 0 || i % 2 == 0) p.Add((i, j));
                var input = Points(p);
                var o = CandidateRegistry.For(Milestone.M1).Run(input);
                var (r, pass) = Run(input, o, M1);
                Assert.Equal("witness", pass);
                Assert.True(r.Ok, r.ToString());
                var (full, _) = Run(input, o, M1, failWitness: true);
                Assert.Equal(Summary(full), Summary(r));
            }
        }

        /// <summary> an exception while building or certifying the witness (here thrown by the corruption hook, which runs between
        /// the two; and a witness triangle with a vertex id out of range) is a failed witness: the full pass runs, with its verdicts </summary>
        [Fact]
        public void WitnessThatThrows_FallsBackToTheFullPass()
        {
            var input = RandomPoints(9, 150);
            var o = CandidateRegistry.For(Milestone.M1).Run(input);
            var bad = WithTriangles(o, Flip(o));
            var (full, _) = Run(input, bad, M1, failWitness: true);
            Assert.True(full.Has(Violation.NotDelaunayGlobal), full.ToString());
            var (thrown, tp) = Run(input, bad, M1, w => throw new InvalidOperationException("broken"));
            Assert.Equal("fallback: the witness threw InvalidOperationException", tp);
            Assert.Equal(Summary(full), Summary(thrown));
            var (outOfRange, op) = Run(input, bad, M1, w => w.Concat(new[] { new[] { 0, 1, input.Count + 5 } }).ToList());
            Assert.StartsWith("fallback: ", op);
            Assert.Equal(Summary(full), Summary(outOfRange));
        }

        /// <summary>
        /// Invariance (CLAUDE.md): random points under every similarity of Similarity.All() and the scales 2^-500 and 2^200 (the mesher takes coordinates up to 1e70), meshed in
        /// that frame: the witness is used and the verdicts and details are those of the full pass; under a power of two (exact) the
        /// report is the identity's, bit for bit
        /// </summary>
        [Fact]
        public void Invariance_WitnessEqualsTheFullPass_UnderSimilarities()
        {
            var baseInput = RandomPoints(31, 200);
            string identity = null;
            var frames = Similarity.All().Select(s => (s.Name, s.IsExact, (Func<double, double, (double, double)>)((x, y) => { var p = s.Apply(new g3.Vector3d(x, y, 0)); return (p.x, p.y); })))
                .Concat(new[] { -500, 200 }.Select(k => ("scale 2^" + k, true, (Func<double, double, (double, double)>)((x, y) => (x * Math.Pow(2, k), y * Math.Pow(2, k))))));
            foreach (var (name, exact, map) in frames) {
                var pts = baseInput.X.Select((x, i) => map(x, baseInput.Y[i])).ToList();
                var input = Points(pts);
                var o = CandidateRegistry.For(Milestone.M1).Run(input);
                var (r, pass) = Run(input, o, M1);
                Assert.True(pass == "witness", name + ": " + pass);
                var (full, _) = Run(input, o, M1, failWitness: true);
                Assert.Equal(Summary(full), Summary(r));
                Assert.True(r.Ok, name + ": " + r);
                if (identity == null) identity = Summary(r);
                else if (exact) Assert.Equal(identity, Summary(r));
            }
        }

        static int[][] Reversed(int[][] w, int i) => w.Select((t, j) => j == i ? new[] { t[0], t[2], t[1] } : t).ToArray();

        public static IEnumerable<object[]> Corruptions() => new[] {
            new object[] { "reversed", "a witness triangle is not positive" },
            new object[] { "duplicated", "a directed edge in two witness triangles" },
            new object[] { "vertex dropped", "a used vertex is not in the witness" },
            new object[] { "triangle dropped", "a witness boundary edge is not on the hull" },
            new object[] { "ear dropped", "a witness boundary edge is not on the hull" },
            new object[] { "edge flipped", "a witness edge is not locally Delaunay" },
        };

        /// <summary> a witness made wrong in each way the certificate tests is refused for that reason, and the verdicts stay those of
        /// the full pass (on a Delaunay output and on one with a flipped edge) </summary>
        [Theory]
        [MemberData(nameof(Corruptions))]
        public void CorruptWitness_IsRefused(string how, string why)
        {
            var input = RandomPoints(77, 300);
            var o = CandidateRegistry.For(Milestone.M1).Run(input);
            var flipped = WithTriangles(o, Flip(o));
            List<int[]> Corrupt(List<int[]> w)
            {
                switch (how) {
                    case "reversed": return Reversed(w.ToArray(), w.Count / 2).ToList();
                    case "duplicated": return w.Concat(new[] { w[w.Count / 2] }).ToList();
                    case "vertex dropped": {
                        // an interior vertex: all triangles around it removed
                        var count = new Dictionary<int, int>();
                        foreach (var t in w) foreach (int x in t) count[x] = count.TryGetValue(x, out int c) ? c + 1 : 1;
                        var hull = new HashSet<int>(BoundaryVertices(w));
                        int v = count.Keys.Where(x => !hull.Contains(x)).OrderBy(x => x).First();
                        return w.Where(t => !t.Contains(v)).ToList();
                    }
                    case "triangle dropped": {
                        // a triangle with no boundary vertex
                        var hull = new HashSet<int>(BoundaryVertices(w));
                        int i = w.FindIndex(t => t.All(x => !hull.Contains(x)));
                        return w.Where((t, j) => j != i).ToList();
                    }
                    case "ear dropped": {
                        // a triangle with one boundary edge and its third vertex inside: the boundary then dents in at that vertex, one
                        // cycle still, every edge reached, the vertex still in W (its other triangles)
                        var directed = new HashSet<(int, int)>();
                        foreach (var t in w) for (int k = 0; k < 3; ++k) directed.Add((t[k], t[(k + 1) % 3]));
                        var hull = new HashSet<int>(BoundaryVertices(w));
                        int i = w.FindIndex(t => Enumerable.Range(0, 3).Count(k => !directed.Contains((t[(k + 1) % 3], t[k]))) == 1
                            && Enumerable.Range(0, 3).Any(k => !directed.Contains((t[(k + 1) % 3], t[k])) && !hull.Contains(t[(k + 2) % 3])));
                        return w.Where((t, j) => j != i).ToList();
                    }
                    case "edge flipped": {
                        var fo = new Mesh2Output { VX = o.VX, VY = o.VY, Triangles = w.ToArray() };
                        return Flip(fo).ToList();
                    }
                }
                throw new ArgumentException(how);
            }
            foreach (var output in new[] { o, flipped }) {
                var (full, _) = Run(input, output, M1, failWitness: true);
                var (got, pass) = Run(input, output, M1, Corrupt);
                Assert.Equal("fallback: " + why, pass);
                Assert.Equal(Summary(full), Summary(got));
            }
        }

        static IEnumerable<int> BoundaryVertices(List<int[]> w)
        {
            var directed = new HashSet<(int, int)>();
            foreach (var t in w) for (int k = 0; k < 3; ++k) directed.Add((t[k], t[(k + 1) % 3]));
            foreach (var (a, b) in directed) if (!directed.Contains((b, a))) { yield return a; yield return b; }
        }

        /// <summary>
        /// A double cover: the square [0,4]^2 with the midpoints of its sides and its centre, triangulated as a fan around the
        /// centre (Delaunay, all ties), and a witness that is that fan plus a second layer, the square's two triangles over the corners
        /// only. Every triangle is positive, no directed edge repeats (the fan's boundary edges are the half sides, the second layer's the
        /// whole sides), every vertex is in it, every boundary edge on the hull, every interior edge a tie: only the boundary walk sees
        /// it, as two boundary edges leaving one corner (the boundary does not run once around the hull)
        /// </summary>
        [Fact]
        public void DoubleCover_IsRefusedByTheWinding()
        {
            // 0 A(0,0) 1 E(2,0) 2 B(4,0) 3 F(4,2) 4 C(4,4) 5 G(2,4) 6 D(0,4) 7 H(0,2) 8 M(2,2)
            var input = Points(new List<(double, double)> { (0, 0), (2, 0), (4, 0), (4, 2), (4, 4), (2, 4), (0, 4), (0, 2), (2, 2) });
            var fan = Enumerable.Range(0, 8).Select(i => new[] { i, (i + 1) % 8, 8 }).ToArray();
            var o = new Mesh2Output { Status = Mesh2Status.Success, VX = input.X, VY = input.Y, InputToVertex = Enumerable.Range(0, 9).ToArray(),
                Triangles = fan, Neighbours = SelfCheck.NeighboursOf(fan), BadTriangles = new int[0], Subsegments = new List<SubsegmentOutput>() };
            var (plain, plainPass) = Run(input, o, M1);
            Assert.True(plain.Ok, plain.ToString());
            var (got, pass) = Run(input, o, M1, w => fan.Concat(new[] { new[] { 0, 2, 4 }, new[] { 0, 4, 6 } }).ToList());
            Assert.Equal("fallback: the witness boundary does not wind once around the hull", pass);
            Assert.True(got.Ok, got.ToString());
        }

        /// <summary> the certificate is what the reduction rests on: with it skipped, a witness that holds the output's flipped
        /// triangles hides their violation; with it, the witness is refused and the violation found </summary>
        [Fact]
        public void WithoutTheCertificate_AWrongWitnessHidesAViolation()
        {
            var input = RandomPoints(5, 120);
            var o = CandidateRegistry.For(Milestone.M1).Run(input);
            var bad = WithTriangles(o, Flip(o));
            List<int[]> Output(List<int[]> w) => bad.Triangles.ToList();
            var (hidden, hp) = Run(input, bad, M1, Output, skipCertificate: true);
            Assert.Equal("witness", hp);
            Assert.False(hidden.Has(Violation.NotDelaunayGlobal), hidden.ToString());
            var (found, fp) = Run(input, bad, M1, Output);
            Assert.Equal("fallback: a witness edge is not locally Delaunay", fp);
            Assert.True(found.Has(Violation.NotDelaunayGlobal), found.ToString());
        }

        /// <summary> many cocircular points (ties everywhere, the walk and the cavity meet in-circle signs of 0) still give a
        /// certified witness </summary>
        [Fact]
        public void CocircularPoints_GiveACertifiedWitness()
        {
            var p = new List<(double, double)>();
            // the points of a circle of radius 5 at integer coordinates (12 of them), and the centre
            foreach (var (x, y) in new[] { (5, 0), (4, 3), (3, 4), (0, 5) })
                foreach (var (sx, sy) in new[] { (1, 1), (-1, 1), (-1, -1), (1, -1) }) p.Add((sx * x, sy * y));
            p.Add((0, 0));
            var input = Points(p.Distinct().ToList());
            var o = CandidateRegistry.For(Milestone.M1).Run(input);
            var (r, pass) = Run(input, o, M1);
            Assert.Equal("witness", pass);
            Assert.True(r.Ok, r.ToString());
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The oracle's fast path with Oracle.CheckFastPathForTests on: every index and filter that replaces a scan or an exact test is
    /// checked against it as it runs (the domain edges near a point; the sources near a triangle in the merge zone and those covering a
    /// subsegment; the vertices and subsegments of a pixel on the snap grid; the zone filters at their call sites), and a difference
    /// throws. Run over meshes that reach each of them: the catalogue, the grid fuzz in both modes, hull domains (no rings), and the star
    /// polygons on the snap grid. The verdicts themselves are compared with the reference path in Meshing2OracleModesTests.
    /// </summary>
    public class Meshing2OracleFastPathCheckTests
    {
        static OracleReport Checked(Mesh2Input input, Mesh2Output output, OracleExpect e)
        {
            Oracle.CheckFastPathForTests = true;
            try { return Oracle.Check(input, output, e); }
            finally { Oracle.CheckFastPathForTests = false; }
        }

        static readonly OracleExpect M3 = new OracleExpect { Milestone = Milestone.M3 };

        public static IEnumerable<object[]> RowIds() => Catalogue.Rows()
            .Where(r => r.State == CaseState.Covered && r.Test == null && r.Case != null && !r.Slow && CandidateRegistry.For(r.Case.Milestone) != null)
            .Select(r => new object[] { r.Id });

        public static IEnumerable<object[]> SelfCheckNames() => SelfCheck.Run().Select(i => new object[] { i.Name });

        /// <summary> the oracle's own hand-built cases (a grid pixel crossed by a constraint, a vertex at a circumcentre's pixel, merge
        /// zones, hull tips, ...) with the checks on: each still passes, and no index or filter differs from its scan </summary>
        [Theory]
        [MemberData(nameof(SelfCheckNames))]
        public void SelfCheckItem(string name)
        {
            Oracle.CheckFastPathForTests = true;
            try {
                var item = SelfCheck.Run().First(i => i.Name == name);
                Assert.True(item.Passed, item.Detail);
            } finally { Oracle.CheckFastPathForTests = false; }
        }

        [Theory]
        [MemberData(nameof(RowIds))]
        public void CatalogueRow(string id)
        {
            var row = Catalogue.Rows().First(r => r.Id == id);
            var output = CandidateRegistry.For(row.Case.Milestone).Run(row.Case.Input);
            Checked(row.Case.Input, output, row.Case.Expect);
        }

        static Mesh2Output Out(Mesh2Input input, double[] vx, double[] vy, int[][] tris) => new Mesh2Output {
            Status = Mesh2Status.Success, VX = vx, VY = vy, InputToVertex = Enumerable.Range(0, input.Count).ToArray(),
            Triangles = tris, Neighbours = SelfCheck.NeighboursOf(tris), BadTriangles = new int[0], Subsegments = new List<SubsegmentOutput>() };

        /// <summary>
        /// GridBlocked's subsegments: the skinny triangle of the oracle's self-check 5b on the grid (pixel 1/4), with a short subsegment
        /// across the upper right part of its circumcentre's pixel, from a quarter pixel left of the centre one pixel up to one pixel
        /// right and a quarter pixel down: it crosses the pixel's interior, and its box misses the pixel's lower left corner (a query of
        /// less than the pixel's box would miss it). The check compares the grid's answer with the scan of all subsegments
        /// </summary>
        [Fact]
        public void GridBlocked_SubsegmentAcrossACornerOfThePixel()
        {
            double w = 0.25;
            double[] pts = { 5.0, 5, 9, 5.5, 5.5, 5.25 };
            // the circumcentre, exactly, and its pixel's centre
            Pt a = Pt.FromDoubles(pts[0], pts[1]), b = Pt.FromDoubles(pts[2], pts[3]), c = Pt.FromDoubles(pts[4], pts[5]);
            Q bx = b.Qx - a.Qx, by = b.Qy - a.Qy, cx = c.Qx - a.Qx, cy = c.Qy - a.Qy, d = (bx * cy - by * cx) * 2, b2 = bx * bx + by * by, c2 = cx * cx + cy * cy;
            double ux = double.Parse((a.Qx + (cy * b2 - by * c2) / d).ToDecimal(20), System.Globalization.CultureInfo.InvariantCulture);
            double uy = double.Parse((a.Qy + (bx * c2 - cx * b2) / d).ToDecimal(20), System.Globalization.CultureInfo.InvariantCulture);
            double px = Math.Floor(ux / w + 0.5) * w, py = Math.Floor(uy / w + 0.5) * w;
            var input = new Mesh2Input {
                X = new[] { 0, 16, 16, 0, pts[0], pts[2], pts[4], px, px + w, px - 3 * w, px - 2 * w },
                Y = new[] { 0, 0, 16, 16, pts[1], pts[3], pts[5], py + 2 * w, py - 2 * w, py + 5 * w, py + 5 * w },
                SnapTolerance = w, MinAngleDeg = 20,
            };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            input.Segments.Add(new SegmentInput(7, 8));
            var o = Out(input, (double[])input.X.Clone(), (double[])input.Y.Clone(), new[] { new[] { 4, 5, 6 } });
            o.BadTriangles = new[] { 0 };
            o.Subsegments.Add(new SubsegmentOutput(7, 8));
            // a short subsegment left of and above the pixel, many times over: the grid over the subsegments' boxes then has cells of
            // about a quarter pixel and starts left of the pixel (a grid of one cell, or one clamped to its border, returns every box)
            input.Segments.Add(new SegmentInput(9, 10));
            for (int i = 0; i < 900; ++i) o.Subsegments.Add(new SubsegmentOutput(9, 10));
            // (other violations do not matter here: the check of the fast path throws if the grid of subsegments misses the crossing)
            var report = Checked(input, o, M3);
            Assert.False(report.Has(Violation.AngleBelowBound), "the triangle should be grid-blocked: " + report);
            // the negative control: without the subsegment across the pixel the triangle is judged, so GridBlocked decided above
            o.Subsegments.RemoveAt(0);
            input.Segments.RemoveAt(0);
            Assert.True(Checked(input, o, M3).Has(Violation.AngleBelowBound), "without the subsegment the triangle should be judged");
        }

        /// <summary>
        /// The hull edge nearest to a boundary vertex on a hull domain (D13), where the grid over the hull edges is fine: 400 input points
        /// on a circle of radius 1/2 around (1/2, 1/2), no rings, and an output vertex 0.09 outside the hull edge at 45 degrees (within a
        /// stated tube of 0.1, so it counts as moved by its distance). Its box is several cells of the grid away from the edge's box: only
        /// the query widened by the tube finds the edge. The check compares the nearest edge found with the minimum over all hull edges;
        /// 0.11 outside (beyond the tube) is the control
        /// </summary>
        [Theory]
        [InlineData(0.09, true)]
        [InlineData(0.11, false)]
        public void HullDomain_BoundaryVertexOffTheHullEdge(double offset, bool withinTube)
        {
            const int n = 400;
            var x = new double[n]; var y = new double[n];
            for (int i = 0; i < n; ++i) { double a = 2 * Math.PI * i / n; x[i] = 0.5 + 0.5 * Math.Cos(a); y[i] = 0.5 + 0.5 * Math.Sin(a); }
            var input = new Mesh2Input { X = x, Y = y };
            input.Segments.Add(new SegmentInput(0, n / 2));
            // the output: the input points, the centre (n) and the vertex outside the edge from point 50 to 51 (n + 1); a fan from the centre
            int k = n / 8;
            double am = 2 * Math.PI * (k + 0.5) / n, r = 0.5 * Math.Cos(Math.PI / n) + offset;
            var vx = x.Concat(new[] { 0.5, 0.5 + r * Math.Cos(am) }).ToArray();
            var vy = y.Concat(new[] { 0.5, 0.5 + r * Math.Sin(am) }).ToArray();
            var tris = new List<int[]>();
            for (int i = 0; i < n; ++i) {
                int j = (i + 1) % n;
                if (i == k) { tris.Add(new[] { n, i, n + 1 }); tris.Add(new[] { n, n + 1, j }); }
                else tris.Add(new[] { n, i, j });
            }
            var o = Out(input, vx, vy, tris.ToArray());
            o.Subsegments.Add(new SubsegmentOutput(0, n / 2));
            // (the check of the fast path throws if the index misses the nearest hull edge). The control: within the tube the edges to
            // the vertex count as on the hull (DomainEdgesNear found the edge); beyond it they are boundary edges on nothing
            var report = Checked(input, o, new OracleExpect { Milestone = Milestone.M2, Tube = Q.FromDouble(0.1) });
            Assert.Equal(!withinTube, report.Has(Violation.HullBoundary) || report.Has(Violation.BoundaryNotConstrained));
        }

        /// <summary>
        /// The one intended output difference of the fast path's indexes: a hull domain without any hull edge (all input points the same)
        /// whose output has triangles. The scan's minimum over no hull edges threw out of Oracle.Check; now the boundary vertices count as
        /// not moved, and the degenerate domain is reported as such (TrianglesOnDegenerate), on both paths and with the checks on
        /// </summary>
        [Fact]
        public void HullDomain_WithoutHullEdges_IsReportedNotThrown()
        {
            var input = new Mesh2Input { X = new double[] { 1, 1, 1 }, Y = new double[] { 1, 1, 1 } };
            var o = new Mesh2Output {
                Status = Mesh2Status.Success, VX = new double[] { 1, 0, 2, 1 }, VY = new double[] { 1, 0, 0, 2 }, InputToVertex = new[] { 0, 0, 0 },
                Triangles = new[] { new[] { 0, 1, 2 }, new[] { 0, 2, 3 }, new[] { 0, 3, 1 } }, BadTriangles = new int[0], Subsegments = new List<SubsegmentOutput>() };
            o.Neighbours = SelfCheck.NeighboursOf(o.Triangles);
            var e = new OracleExpect { Milestone = Milestone.M2 };
            Assert.True(Checked(input, o, e).Has(Violation.TrianglesOnDegenerate));
            Assert.True(Oracle.Check(input, o, e.WithReference()).Has(Violation.TrianglesOnDegenerate));
        }

        /// <summary> the lens tests' fuzz (a square, a hole, random segments) with and without the snap grid, both modes, 20 to 30 degrees:
        /// the merge zone (small angles between segments), GridBlocked and the marks </summary>
        [Fact]
        public void Fuzz()
        {
            for (int seed = 0; seed < 30; ++seed) {
                double snap = new[] { 0, 0.25, 0.125 }[seed % 3];
                var input = QualityMesh2LensDeletionTests.Fuzz(7000 + seed, new[] { 20.0, 25, 30 }[seed % 3], snap);
                input.ConstrainedQuality = seed % 2 == 0;
                var o = new QualityMesh2Candidate().Run(input);
                Assert.True(Checked(input, o, M3).Ok, "seed " + seed);
            }
        }

        /// <summary> hull domains (segments only, no rings: D13), where the boundary is the hull and the coverage checks ask for the domain
        /// edges near a point </summary>
        [Fact]
        public void HullDomains()
        {
            for (int seed = 0; seed < 20; ++seed) {
                var r = new Random(seed);
                var x = new List<double>(); var y = new List<double>();
                var input = new Mesh2Input();
                for (int i = 0; i < 5; ++i) {
                    x.Add(r.Next(0, 40) / 4.0); y.Add(r.Next(0, 40) / 4.0);
                    x.Add(r.Next(0, 40) / 4.0 + 0.01 * r.Next(3)); y.Add(r.Next(0, 40) / 4.0);
                    input.Segments.Add(new SegmentInput(x.Count - 2, x.Count - 1));
                }
                input.X = x.ToArray(); input.Y = y.ToArray();
                input.MinAngleDeg = 20 + 5 * (seed % 3);
                if (seed % 2 == 1) input.SnapTolerance = 0.125;
                var o = new QualityMesh2Candidate().Run(input);
                if (o.Status != Mesh2Status.Success) continue;
                Checked(input, o, M3);
            }
        }

        /// <summary> the star polygons of the Q17 fuzz on the snap grid (pixel 1): GridBlocked and the marks on chains </summary>
        [Fact]
        public void StarPolygons()
        {
            for (int seed = 0; seed < 60; ++seed) {
                var input = StarPolygonFuzz.Make(seed);
                input.ConstrainedQuality = seed % 3 == 0;
                var o = new QualityMesh2Candidate().Run(input);
                if (o.Status != Mesh2Status.Success) continue;
                Checked(input, o, M3);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The oracle's fast path (floating-point filters, spatial indexes, the indexed global Delaunay pass) against its reference path
    /// (every test exact, OracleExpect.Reference): the same verdicts on the catalogue, on corrupted meshes, and on the self-checks.
    /// </summary>
    public class Meshing2OracleModesTests
    {
        static readonly List<CatalogueRow> Rows = Catalogue.Rows()
            .Where(r => r.State == CaseState.Covered && r.Test == null && r.Case != null && !r.Slow && CandidateRegistry.For(r.Case.Milestone) != null).ToList();

        public static IEnumerable<object[]> RowIds() => Rows.Select(r => new object[] { r.Id });

        /// <summary> what a verdict consists of: the kinds with their counts, and the measured values </summary>
        static string Verdict(OracleReport r) =>
            string.Join(",", r.Violations.GroupBy(v => v.Kind).OrderBy(g => g.Key).Select(g => g.Key + "x" + g.Count()))
            + " | area2 " + r.Area2 + " | minsin2 " + r.MinSin2 + " | below " + r.BelowAngle + " | ties " + r.TieEdges + " | unique " + r.Unique
            + " | constructed " + r.ConstructedVertices + " | zone " + r.MergeZoneExcused
            + " | o11 " + r.O11LocalExcused + "/" + r.O11GlobalExcused + "/" + r.O11AngleExcused;

        static void Same(Mesh2Input input, Mesh2Output output, OracleExpect e, string what)
        {
            var reference = Oracle.Check(input, output, e.WithReference());
            // The reference path runs the global empty-circumcircle pass only up to GlobalDelaunayLimit triangle-vertex pairs, by design
            // (all pairs, exactly); above it the fast path is compared without that pass too, and the pass itself is compared on the rows
            // below the limit. (Found when F-4/a, F-4/b and F-5 left the slow rows: the fast path found the global violations of a
            // corrupted F-5 and counted the merge-zone excusals of its global pass, the limited reference path neither; with no limit the
            // reference path agrees with the fast one, in 200 s instead of 0.9 s.)
            var fast = Oracle.Check(input, output, reference.GlobalDelaunayChecked ? e : e.WithGlobalDelaunayLimit(0));
            Assert.Equal(reference.GlobalDelaunayChecked, fast.GlobalDelaunayChecked);
            Assert.True(Verdict(fast) == Verdict(reference), what + ": fast " + Verdict(fast) + " / reference " + Verdict(reference));
        }

        // The expensive theories sit in nested classes (ExtremeScales split in two): xUnit runs classes in parallel but the rows of one class
        // one after another, and in one class they took 14 minutes (841 s on net10.0, 4 cores), the second longest stretch of the suite.
        public class CatalogueRows
        {
            [Theory]
            [MemberData(nameof(RowIds), MemberType = typeof(Meshing2OracleModesTests))]
            public void CatalogueRow_SameVerdictOnBothPaths(string id) => CatalogueRow(id);
        }

        static void CatalogueRow(string id)
        {
            var row = Rows.First(r => r.Id == id);
            var output = CandidateRegistry.For(row.Case.Milestone).Run(row.Case.Input);
            Same(row.Case.Input, output, row.Case.Expect, id);
        }

        /// <summary>
        /// The fast path's filters in doubles hold at extreme magnitudes: the catalogue rows with small angles, holes and seeds, scaled by
        /// 2^k (exact; inputs, seeds and the mesher's output alike), give the same verdict and the same reported details on both paths
        /// (review of the oracle speed-up: a distance overflowed at 2^512, a product of squared lengths underflowed at 2^-270)
        /// </summary>
        public class ExtremeScalesSmall
        {
            [Theory]
            [InlineData("F-38/a", -270)]
            [InlineData("F-38/d", -270)]
            [InlineData("F-44", -270)]
            [InlineData("spike-0.84", -300)]
            public void ExtremeScales_SameVerdictAndDetailsOnBothPaths(string id, int exponent) => ExtremeScales(id, exponent);
        }

        public class ExtremeScalesLarge
        {
            [Theory]
            [InlineData("F-38/a", 450)]
            [InlineData("F-38/a", 512)]
            [InlineData("F-38/d", 512)]
            [InlineData("F-44", 512)]
            [InlineData("spike-0.84", 512)]
            public void ExtremeScales_SameVerdictAndDetailsOnBothPaths(string id, int exponent) => ExtremeScales(id, exponent);
        }

        static void ExtremeScales(string id, int exponent)
        {
            // spike-0.84: earcut's water-huge reduced to five points (QualityMesh2Tests.SpikeOf084Degrees) at 25 degrees, whose merge zone and
            // O11-unsplittable piece the oracle excuses; at 2^-300 the leg pieces' directions are below 1e-81
            Mesh2Case c;
            if (id == "spike-0.84") {
                var spike = new Mesh2Input { X = new double[] { 4097, 4097, 4098, 4183, 4050 }, Y = new double[] { 2989, 3013, 2945, 4096, 3675 }, MinAngleDeg = 25 };
                spike.Rings.Add(new RingInput(new[] { 0, 1, 2, 3, 4 }, false));
                c = new Mesh2Case { Id = id, Milestone = Milestone.M3, Input = spike, Expect = new OracleExpect { Milestone = Milestone.M3 } };
            } else c = Catalogue.Rows().First(r => r.Id == id).Case;
            var row = new { Case = c };
            var input = TextFormat.ReadInput(TextFormat.WriteInput(row.Case.Input));
            double f = Math.Pow(2, exponent);
            for (int i = 0; i < input.Count; ++i) { input.X[i] *= f; input.Y[i] *= f; }
            foreach (var seed in input.HoleSeeds) { seed[0] *= f; seed[1] *= f; }
            Assert.Null(input.MaxArea);
            var output = CandidateRegistry.For(row.Case.Milestone).Run(row.Case.Input);
            for (int i = 0; i < output.VX.Length; ++i) { output.VX[i] *= f; output.VY[i] *= f; }
            output.ExactVertices = null; output.Locate = null;   // (the candidate's location belongs to the unscaled mesh)
            var e = new OracleExpect { Milestone = row.Case.Milestone };
            Same(input, output, e, id + " at 2^" + exponent);
            string Details(OracleReport r) => string.Join("; ", r.Violations.Select(v => v.ToString()).OrderBy(x => x, StringComparer.Ordinal));
            var reference = Oracle.Check(input, output, e.WithReference());
            var fast = Oracle.Check(input, output, reference.GlobalDelaunayChecked ? e : e.WithGlobalDelaunayLimit(0));
            Assert.Equal(Details(reference), Details(fast));
        }

        /// <summary>
        /// The evidence for the comparison above the limit: on F-4/b and F-5 (tens of millions of triangle-vertex pairs) the reference path
        /// without its limit gives the fast path's verdict on the mesh and on every corrupted copy, the merge-zone excusals and the
        /// global violations included. Takes about half an hour, so it runs with G3_MESH2_SLOW set, like the slow catalogue rows.
        /// </summary>
        [Theory]
        [InlineData("F-4/b")]
        [InlineData("F-5")]
        public void AboveTheLimit_ReferenceWithoutLimit_SameVerdictAsFast(string id)
        {
            if (Environment.GetEnvironmentVariable("G3_MESH2_SLOW") == null) return;
            var row = Catalogue.Rows().First(r => r.Id == id);
            var output = CandidateRegistry.For(row.Case.Milestone).Run(row.Case.Input);
            Assert.True((long)output.Triangles.Length * output.VX.Length > row.Case.Expect.GlobalDelaunayLimit, id + " is no longer above the limit");
            foreach (var (name, mesh) in new[] { ("valid", output) }.Concat(Corrupted(output))) {
                var fast = Oracle.Check(row.Case.Input, mesh, row.Case.Expect);
                var reference = Oracle.Check(row.Case.Input, mesh, row.Case.Expect.WithReference().WithGlobalDelaunayLimit(long.MaxValue));
                // a corrupted copy may stop both paths before the global pass; the valid mesh must reach it
                Assert.True(fast.GlobalDelaunayChecked == reference.GlobalDelaunayChecked && (fast.GlobalDelaunayChecked || name != "valid"),
                    id + " " + name + ": global pass fast " + fast.GlobalDelaunayChecked + " / reference " + reference.GlobalDelaunayChecked);
                Assert.True(Verdict(fast) == Verdict(reference), id + " " + name + ": fast " + Verdict(fast) + " / reference " + Verdict(reference));
            }
        }

        /// <summary> corruptions a mesher could produce: a vertex moved, a triangle missing, a triangle turned over, two vertices swapped </summary>
        static IEnumerable<(string, Mesh2Output)> Corrupted(Mesh2Output o)
        {
            if (o.Triangles.Length < 4) yield break;
            Mesh2Output Copy() => new Mesh2Output {
                Status = o.Status, FailureKind = o.FailureKind, VX = (double[])o.VX.Clone(), VY = (double[])o.VY.Clone(), InputToVertex = o.InputToVertex,
                Triangles = o.Triangles.Select(t => (int[])t.Clone()).ToArray(), Neighbours = null, Subsegments = o.Subsegments, TriangleLabels = o.TriangleLabels,
                BadTriangles = o.BadTriangles, SteinerLimitReached = o.SteinerLimitReached };
            double extent = Math.Max(o.VX.Max() - o.VX.Min(), o.VY.Max() - o.VY.Min());
            int mid = o.Triangles.Length / 2, v = o.Triangles[mid][0];
            var moved = Copy(); moved.VX[v] += extent * 1e-3; moved.VY[v] -= extent * 7e-4;
            yield return ("vertex moved", moved);
            var missing = Copy(); missing.Triangles = missing.Triangles.Where((t, i) => i != mid).ToArray();
            if (missing.TriangleLabels != null) missing.TriangleLabels = missing.TriangleLabels.Where((l, i) => i != mid).ToArray();
            missing.BadTriangles = null;
            yield return ("triangle missing", missing);
            var flipped = Copy(); var f = flipped.Triangles[mid]; (f[1], f[2]) = (f[2], f[1]);
            yield return ("triangle turned over", flipped);
            var swapped = Copy(); int w = o.Triangles[0][1];
            (swapped.VX[v], swapped.VX[w]) = (swapped.VX[w], swapped.VX[v]); (swapped.VY[v], swapped.VY[w]) = (swapped.VY[w], swapped.VY[v]);
            yield return ("two vertices swapped", swapped);
        }

        public class CorruptedRows
        {
            [Theory]
            [MemberData(nameof(RowIds), MemberType = typeof(Meshing2OracleModesTests))]
            public void CorruptedRow_RejectedOnBothPaths(string id) => CorruptedRow(id);
        }

        static void CorruptedRow(string id)
        {
            var row = Rows.First(r => r.Id == id);
            var output = CandidateRegistry.For(row.Case.Milestone).Run(row.Case.Input);
            if (output.Status != Mesh2Status.Success || row.Case.Expect.ExpectFailure) return;
            foreach (var (name, bad) in Corrupted(output)) {
                Same(row.Case.Input, bad, row.Case.Expect, id + " " + name);
                // a moved vertex can stay within what the case allows (a large tube, a free point); the others always break the mesh
                if (name != "vertex moved") Assert.False(Oracle.Check(row.Case.Input, bad, row.Case.Expect).Ok, id + " " + name + " was accepted");
            }
        }

        [Fact]
        public void RingBucket_PointOnTheTopEdge_IsOnTheBoundary()
        {
            // bounds review: a ring of more than 16 vertices spanning y in [-1, 0]; the rounded bucket index of a point on the top edge
            // ran past the last bucket and the filter said outside
            var pts = new List<Pt> { Pt.FromDoubles(0, 0), Pt.FromDoubles(1, 0) };
            for (int i = 1; i <= 10; ++i) pts.Add(Pt.FromDoubles(1, -0.1 * i));
            pts.Add(Pt.FromDoubles(0, -1));
            for (int i = 9; i >= 1; --i) pts.Add(Pt.FromDoubles(0, -0.1 * i));
            var ring = pts.ToArray();
            var p = Pt.FromDoubles(0.5, 0);
            Assert.Equal(Where.Boundary, Domain.InRing(ring, p, false));
            Assert.Equal(Where.Boundary, Domain.InRing(ring, p, true));
            var inside = Pt.FromDoubles(0.5, -0.5);
            Assert.Equal(Where.Inside, Domain.InRing(ring, inside, true));
        }

        [Theory]
        [InlineData(0, 0, 1.2750220907015703e77, -3.416411395353274e76, 1.2750220907015703e77, 3.416411395353274e76)]
        [InlineData(0, 0, 1e-5, 0, 5e-6, 1.2345e-155)]
        public void SmallestAngle_AtTheEndsOfTheRange_SameVerdict(double ax, double ay, double bx, double by, double cx, double cy)
        {
            // bounds review: an overflowing product made the filtered sine 0 (a 30-75-75 triangle judged below 20 degrees); a subnormal
            // cross product gave an interval that missed the exact value
            var input = new Mesh2Input { X = new[] { ax, bx, cx }, Y = new[] { ay, by, cy }, MinAngleDeg = 20 };
            var output = new Mesh2Output { Status = Mesh2Status.Success, VX = input.X, VY = input.Y, InputToVertex = new[] { 0, 1, 2 },
                Triangles = new[] { new[] { 0, 1, 2 } }, Neighbours = new[] { new[] { -1, -1, -1 } }, Subsegments = new List<SubsegmentOutput>(), BadTriangles = new int[0] };
            Same(input, output, new OracleExpect { Milestone = Milestone.M3 }, "triangle");
        }

        [Fact]
        public void SelfChecks_PassOnTheReferencePath()
        {
            Oracle.ForceReference = true;
            try {
                var failed = SelfCheck.Run().Where(i => !i.Passed).Select(i => i.Name + ": " + i.Detail).ToList();
                Assert.True(failed.Count == 0, string.Join("\n", failed));
            } finally { Oracle.ForceReference = false; }
        }
    }
}

using System;
using System.Linq;
using System.Numerics;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The automatic tube has a floor of one subnormal step, 2^-1074 (decision D3 of 2026-11-05). Below about 2^-1034 the relative
    /// tube (2^-40 of the magnitude) is finer than any double can resolve: a crossing of two constraints, which the mesher must make,
    /// has in general no double within it, so no mesh could pass (found with this procedural input of three nearly concurrent
    /// segments while fixing #388).
    /// </summary>
    public class Meshing2OracleSubnormalTubeTests
    {
        /// <summary> three segments that cross nearly in one point, with integer coordinates times 2^exponent </summary>
        static Mesh2Input Crossings(int exponent)
        {
            double s = Math.Pow(2, exponent);
            var input = Generators.Literal(new[] { 0.0, 0, 1000003, 700001, 0, 700001, 1000003, 0, 300007, -100003, 700001, 800011 }.Select(v => v * s).ToArray());
            input.Segments.Add(new SegmentInput(0, 1)); input.Segments.Add(new SegmentInput(2, 3)); input.Segments.Add(new SegmentInput(4, 5));
            return input;
        }

        [Theory]
        [InlineData(-1074)]
        [InlineData(-1060)]
        [InlineData(-1040)]
        [InlineData(-1000)]
        [InlineData(0)]
        [InlineData(200)]
        public void CrossingsAtEveryScale_AreValid(int exponent)
        {
            var input = Crossings(exponent);
            var output = CandidateRegistry.For(Milestone.M2).Run(input);
            var report = Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(report.Ok, "2^" + exponent + ": " + report);
        }

        [Theory]
        [InlineData(2)]
        [InlineData(4)]
        [InlineData(64)]
        public void ACrossingMovedBySteps_IsStillRejected(int steps)
        {
            // the floor admits the rounding of a crossing (half a step per coordinate), not a crossing moved by more than a step
            var input = Crossings(-1074);
            var output = CandidateRegistry.For(Milestone.M2).Run(input);
            Assert.True(Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M2 }).Ok);
            var inputVertices = new System.Collections.Generic.HashSet<int>(output.InputToVertex);
            int crossing = Enumerable.Range(0, output.VX.Length).Single(v => !inputVertices.Contains(v));
            output.VX[crossing] += steps * double.Epsilon;
            output.ExactVertices = null;
            var report = Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(report.Has(Violation.SteinerNotAllowed), steps + " steps: " + report);
        }

        [Fact]
        public void O11_KeepsTheMeshersRelativeTolerance()
        {
            // the O11 rule models the mesher's tolerance, half the relative tube: no floor there, as the mesher's own has none
            var tiny = Crossings(-1074); tiny.MinAngleDeg = 20;
            var output = new QualityMesh2Candidate().Run(tiny);
            var report = Oracle.Check(tiny, output, new OracleExpect { Milestone = Milestone.M3 });
            var relative = new Q(1000003, BigInteger.One << (1074 + 40));
            Assert.True(report.O11Tolerance2 == relative * relative / 4, report.O11Tolerance2.ToString());
            var normal = Crossings(0); normal.MinAngleDeg = 20;
            report = Oracle.Check(normal, new QualityMesh2Candidate().Run(normal), new OracleExpect { Milestone = Milestone.M3 });
            var tube = Oracle.AutoTolerance(normal);
            Assert.True(report.O11Tolerance2 == tube * tube / 4);
        }

        [Fact]
        public void AutoTolerance_HasTheSubnormalStepAsItsFloor_AndIsRelativeAbove()
        {
            var step = new Q(1, BigInteger.One << 1074);
            // subnormal: the floor
            Assert.True(Oracle.AutoTolerance(Crossings(-1074)) == step);
            // normal: 2^-40 of the larger of the largest coordinate and the extent, as before
            var normal = Crossings(0);
            Assert.True(Oracle.AutoTolerance(normal) == new Q(1000003, BigInteger.One << 40));
            // at the boundary: the relative tube is 2^-1074 when the magnitude is 2^-1034
            var edge = Generators.Literal(0, 0, Math.Pow(2, -1034), 0, 0, Math.Pow(2, -1034));
            Assert.True(Oracle.AutoTolerance(edge) == step);
            var above = Generators.Literal(0, 0, Math.Pow(2, -1030), 0, 0, Math.Pow(2, -1030));
            Assert.True(Oracle.AutoTolerance(above) == new Q(16, BigInteger.One << 1074));
            // no input: no tube
            Assert.True(Oracle.AutoTolerance(new Mesh2Input()) == Q.Zero);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>The oracle of the 2D mesher judges itself first. A weak oracle is the main risk of the acceptance process.</summary>
    public class Meshing2OracleTests
    {
        public static IEnumerable<object[]> SelfCheckNames() => SelfCheck.Run().Select(i => new object[] { i.Name });

        [Theory]
        [MemberData(nameof(SelfCheckNames))]
        public void SelfCheck_Item_Passes(string name)
        {
            var item = SelfCheck.Run().First(i => i.Name == name);
            Assert.True(item.Passed, item.Detail);
        }

        [Fact]
        public void SelfCheck_CoversEveryKindOfViolation_Except_TheListedOnes()
        {
            // a kind nothing provokes cannot be known to work; the listed ones need an input the self-check cannot build
            var notProvoked = new[] { Violation.CountOutOfRange }; // Fact below
            var names = SelfCheck.Run().Select(i => i.Name).ToList();
            foreach (Violation kind in Enum.GetValues(typeof(Violation))) {
                if (notProvoked.Contains(kind)) continue;
                Assert.True(names.Any(n => n.EndsWith(" as " + kind)), "no broken result is rejected as " + kind);
            }
        }

        [Fact]
        public void Oracle_ReferencesNothingOfTheLibrary()
        {
            var references = typeof(Oracle).Assembly.GetReferencedAssemblies().Select(a => a.Name).ToList();
            Assert.DoesNotContain("geometry3Sharp", references);
            Assert.Contains("netstandard", references);
        }

        static Mesh2Output Triangle(Mesh2Input input) => new Mesh2Output {
            Status = Mesh2Status.Success, VX = input.X, VY = input.Y, InputToVertex = Enumerable.Range(0, input.Count).ToArray(),
            Triangles = new[] { new[] { 0, 1, 2 } }
        };

        [Fact]
        public void InputInvalid_NonFiniteInput_IsNotJudged()
        {
            var input = Generators.Literal(0, 0, double.NaN, 0, 0, 1);
            var report = Oracle.Check(input, new Mesh2Output { Status = Mesh2Status.Empty }, new OracleExpect());
            Assert.True(report.Has(Violation.InputInvalid));
        }

        [Fact]
        public void CountOutOfRange_IsReported()
        {
            var input = Generators.Literal(0, 0, 8, 0, 0, 8);
            var low = Oracle.Check(input, Triangle(input), new OracleExpect { Milestone = Milestone.M1, MinTriangles = 2 });
            Assert.True(low.Has(Violation.CountOutOfRange));
            var high = Oracle.Check(input, Triangle(input), new OracleExpect { Milestone = Milestone.M1, MaxVertices = 2 });
            Assert.True(high.Has(Violation.CountOutOfRange));
            Assert.True(Oracle.Check(input, Triangle(input), new OracleExpect { Milestone = Milestone.M1, MinTriangles = 1, MaxVertices = 3 }).Ok);
        }

        [Fact]
        public void AutoTolerance_IsAbout5MicrometresAtUtm()
        {
            var input = Generators.Literal(632117.25, 5712043.5, 0, 0);
            double tolerance = (double)Oracle.AutoTolerance(input).N / (double)Oracle.AutoTolerance(input).D;
            Assert.InRange(tolerance, 4e-6, 6e-6);
        }

        [Fact]
        public void Fingerprint_DoesNotDependOnOrder_NumberingOrRotation()
        {
            var input = Generators.Literal(0, 0, 8, 0, 8, 8, 0, 8);
            var a = new Mesh2Output { VX = input.X, VY = input.Y, Triangles = new[] { new[] { 0, 1, 2 }, new[] { 0, 2, 3 } } };
            var b = new Mesh2Output {
                VX = new double[] { 0, 8, 8, 0 }, VY = new double[] { 8, 8, 0, 0 },
                Triangles = new[] { new[] { 3, 1, 0 }, new[] { 1, 3, 2 } } // renumbered, rotated, other order
            };
            Assert.Equal(Fingerprint.Triangles(a), Fingerprint.Triangles(b));
            var other = new Mesh2Output { VX = input.X, VY = input.Y, Triangles = new[] { new[] { 0, 1, 3 }, new[] { 1, 2, 3 } } };
            Assert.NotEqual(Fingerprint.Triangles(a), Fingerprint.Triangles(other));
            var flipped = new Mesh2Output { VX = input.X, VY = input.Y, Triangles = new[] { new[] { 0, 2, 1 }, new[] { 0, 2, 3 } } };
            Assert.NotEqual(Fingerprint.Triangles(a), Fingerprint.Triangles(flipped));
        }

        [Fact]
        public void Fingerprint_CoordinateTokens_FollowTheFormat()
        {
            Assert.Equal("3ff0000000000000", Fingerprint.Coordinate(1.0));
            Assert.Equal("0000000000000000", Fingerprint.Coordinate(-0.0));
            Assert.Equal("c000000000000000", Fingerprint.Coordinate(-2.0));
            Assert.Equal("0000000000000001", Fingerprint.Coordinate(double.Epsilon));
        }

        [Fact]
        public void Fingerprint_Subsegments_IgnoreDirectionAndDuplicates()
        {
            var o = new Mesh2Output { VX = new double[] { 0, 1, 2 }, VY = new double[] { 0, 0, 0 }, Subsegments = new List<SubsegmentOutput> { new SubsegmentOutput(0, 1), new SubsegmentOutput(1, 2) } };
            var p = new Mesh2Output { VX = o.VX, VY = o.VY, Subsegments = new List<SubsegmentOutput> { new SubsegmentOutput(2, 1), new SubsegmentOutput(1, 0), new SubsegmentOutput(0, 1) } };
            Assert.Equal(Fingerprint.Subsegments(o), Fingerprint.Subsegments(p));
            Assert.NotEqual(Fingerprint.Subsegments(o), Fingerprint.Subsegments(new Mesh2Output { VX = o.VX, VY = o.VY, Subsegments = new List<SubsegmentOutput> { new SubsegmentOutput(0, 1) } }));
        }

        [Fact]
        public void TextFormat_RoundTrips_AnInput()
        {
            var b = new B().Square().Seg(1, 1, 9, 2, 4, true).Hole(2, 5, 3, 5, 3, 6).HoleSeed(2.5, 5.25).RegionSeed(1, 1, 7, 0.5).RegionRing(8, null, 6, 6, 7, 6, 7, 7).Min(20).Area(2).Limit(99).Snap(0.25).NoNoding().Conforming();
            var input = b.Build();
            string text = TextFormat.WriteInput(input);
            Assert.Equal(text, TextFormat.WriteInput(TextFormat.ReadInput(text)));
            var parsed = TextFormat.ReadInput(text);
            Assert.Equal(input.X, parsed.X);
            Assert.False(parsed.ResolveCrossings);
            Assert.True(parsed.Conforming);
            Assert.Equal(99, parsed.SteinerLimit);
            Assert.True(parsed.Rings[1].Hole);
            Assert.Equal(7, parsed.Regions[0].Label);
            Assert.Equal(0.5, parsed.Regions[0].MaxArea);
            Assert.Null(parsed.Regions[1].MaxArea);
        }

        [Fact]
        public void TextFormat_KeepsTheBitsOfSignedZeroAndSubnormals()
        {
            var input = Generators.Literal(-0.0, double.Epsilon, 1e70, -1e-300);
            var parsed = TextFormat.ReadInput(TextFormat.WriteInput(input));
            Assert.Equal(BitConverter.DoubleToInt64Bits(input.X[0]), BitConverter.DoubleToInt64Bits(parsed.X[0]));
            Assert.Equal(BitConverter.DoubleToInt64Bits(input.Y[0]), BitConverter.DoubleToInt64Bits(parsed.Y[0]));
            Assert.Equal(1e70, parsed.X[1]);
        }

        [Fact]
        public void TextFormat_AcceptsDecimalsAndComments_InForeignFiles()
        {
            string text = "mesh2-output 1 # a comment\nproducer other\nstatus Success\nvertices 3\n0 0\n8.5 0\n0 2e0\ntriangles 1\n0 1 2\nsubsegments -\nmap -\nlabels -\nbad -\nsteiner_limit_reached 0\nend\n";
            var o = TextFormat.ReadOutput(text, out string producer);
            Assert.Equal("other", producer);
            Assert.Equal(8.5, o.VX[1]);
            Assert.Equal(2.0, o.VY[2]);
            Assert.False(o.IdentityRules);
            Assert.Null(o.Subsegments);
        }

        [Fact]
        public void TextFormat_RejectsWrongCounts()
        {
            Assert.Throws<FormatException>(() => TextFormat.ReadOutput("mesh2-output 2\n", out _));
            Assert.Throws<FormatException>(() => TextFormat.ReadOutput("mesh2-output 1\nproducer x\nstatus Success\nvertices 0\ntriangles 0\nsubsegments -\nmap 2 0\nlabels -\nbad -\nsteiner_limit_reached 0\nend\n", out _));
            Assert.Throws<FormatException>(() => TextFormat.ParseCoordinate("0x123"));
        }

        [Fact]
        public void ForeignOutput_IsJudged_ThroughTheTextFormat()
        {
            var input = Generators.Literal(0, 0, 8, 0, 0, 8, 2, 2);
            // a foreign producer: its own numbering, no map, the interior point at index 0
            string good = "mesh2-output 1\nproducer other\nstatus Success\nvertices 4\n2 2\n0 0\n8 0\n0 8\ntriangles 3\n0 1 2\n0 2 3\n0 3 1\nsubsegments -\nmap -\nlabels -\nbad -\nsteiner_limit_reached 0\nend\n";
            var report = Oracle.Check(input, TextFormat.ReadOutput(good, out _), new OracleExpect { Milestone = Milestone.M1 });
            Assert.True(report.Ok, report.ToString());
            string lost = "mesh2-output 1\nproducer other\nstatus Success\nvertices 3\n0 0\n8 0\n0 8\ntriangles 1\n0 1 2\nsubsegments -\nmap -\nlabels -\nbad -\nsteiner_limit_reached 0\nend\n";
            Assert.True(Oracle.Check(input, TextFormat.ReadOutput(lost, out _), new OracleExpect { Milestone = Milestone.M1 }).Has(Violation.VertexUnused));
            string constructed = "mesh2-output 1\nproducer other\nstatus Success\nvertices 5\n2 2\n0 0\n8 0\n0 8\n1 1\ntriangles 3\n0 1 2\n0 2 3\n0 3 1\nsubsegments -\nmap -\nlabels -\nbad -\nsteiner_limit_reached 0\nend\n";
            Assert.True(Oracle.Check(input, TextFormat.ReadOutput(constructed, out _), new OracleExpect { Milestone = Milestone.M1 }).Has(Violation.SteinerNotAllowed));
        }
    }
}

using System;
using System.Numerics;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The oracle's double filter of "vertex within the tube of a source" (Oracle.TubeFilter, used by InventedVertices and Marks on the
    /// fast path) against the exact distance: wherever it decides, it agrees with Exact.Dist2ToSegment, on points placed at the tube's
    /// boundary (relative offsets 1e-3 to 1e-12), near and beyond the source's ends, exactly on axis-parallel lines, and in the frames
    /// 2^k from 2^-300 to 2^512 (scaling by a power of two keeps every double and the exact answer).
    /// </summary>
    public class Meshing2OracleTubeFilterTests
    {
        static readonly int[] Frames = { -300, -200, -150, -60, 0, 60, 150, 200, 300, 512 };

        [Fact]
        public void NearTheBoundary_AgreesWithTheExactDistance_InEveryFrame()
        {
            var rnd = new Random(20261103);
            int decided = 0, decidedNormal = 0, normalCases = 0;
            for (int n = 0; n < 3000; ++n) {
                // a source: diagonal, axis-parallel or short, at magnitudes 1e-3 to 1e7 around an offset origin
                double mag = Math.Pow(10, rnd.Next(-3, 8)), ox = (rnd.NextDouble() - 0.5) * mag * 10, oy = (rnd.NextDouble() - 0.5) * mag * 10;
                double ax = ox + (rnd.NextDouble() - 0.5) * mag, ay = oy + (rnd.NextDouble() - 0.5) * mag;
                double bx = ox + (rnd.NextDouble() - 0.5) * mag, by = oy + (rnd.NextDouble() - 0.5) * mag;
                int kind = rnd.Next(4);
                if (kind == 1) by = ay;            // horizontal
                else if (kind == 2) bx = ax;       // vertical
                double len = Math.Sqrt((bx - ax) * (bx - ax) + (by - ay) * (by - ay));
                if (!(len > 0)) continue;
                // the tube: 1e-14 to 1e-2 of the source's length
                double tube = len * Math.Pow(10, -rnd.Next(2, 15));
                // the point: along the source (beyond its ends too), off it by the tube times 1 + rel, rel of either sign and
                // 1e-3 to 1e-12; or exactly on the line
                double t = rnd.Next(5) == 0 ? (rnd.Next(2) == 0 ? -1 : 1) * rnd.NextDouble() * 3 * tube / len + (rnd.Next(2) == 0 ? 0 : 1) : rnd.NextDouble() * 1.2 - 0.1;
                double rel = (rnd.Next(2) == 0 ? -1 : 1) * Math.Pow(10, -rnd.Next(3, 13));
                double off = rnd.Next(6) == 0 ? 0 : tube * (1 + rel);
                double nx = -(by - ay) / len, ny = (bx - ax) / len;
                double px = ax + t * (bx - ax) + off * nx, py = ay + t * (by - ay) + off * ny;
                if (kind == 1 && off == 0) py = ay;
                if (kind == 2 && off == 0) px = ax;
                Q tube2 = Q.FromDouble(tube) * Q.FromDouble(tube);
                bool exact = Exact.Dist2ToSegment(Pt.FromDoubles(ax, ay), Pt.FromDoubles(bx, by), Pt.FromDoubles(px, py)) <= tube2;
                ++normalCases;
                foreach (int k in Frames) {
                    double f = Math.Pow(2, k);
                    double sax = ax * f, say = ay * f, sbx = bx * f, sby = by * f, spx = px * f, spy = py * f;
                    // a frame that leaves the doubles (overflow, or a coordinate that would round as a subnormal) is no frame of the case
                    if (!Same(ax, sax, f) || !Same(ay, say, f) || !Same(bx, sbx, f) || !Same(by, sby, f) || !Same(px, spx, f) || !Same(py, spy, f)) continue;
                    Q s = Q.FromDouble(f), stube2 = tube2 * s * s;
                    double lo = 0, hi = 0;
                    int got = stube2.Bounds(out lo, out hi) ? Oracle.TubeFilter(sax, say, sbx, sby, spx, spy, lo, hi) : 0;
                    if (got == 0) continue;
                    ++decided;
                    if (k == 0) ++decidedNormal;
                    Assert.True((got > 0) == exact, "case " + n + " at 2^" + k + ": filter " + got + ", exact " + (exact ? "within" : "farther")
                        + " (a " + ax + " " + ay + ", b " + bx + " " + by + ", p " + px + " " + py + ", tube " + tube + ")");
                }
            }
            // the filter is useful: it decides most cases in the unscaled frame (at a relative offset of 1e-12 from the tube it may not)
            Assert.True(decidedNormal > normalCases * 7 / 10, "the filter decided " + decidedNormal + " of " + normalCases);
            Assert.True(decided > decidedNormal, "the scaled frames decided nothing");
        }

        static bool Same(double v, double scaled, double f) => !double.IsInfinity(scaled) && (v == 0 || Math.Abs(scaled) >= 2.2250738585072014E-308) && scaled / f == v;

        [Fact]
        public void TheExactAnswer_DoesNotDependOnTheFrame()
        {
            // the test above compares each frame with the unscaled exact answer; that answer is the frame's own (powers of two scale
            // the distance and the tube alike)
            var a = Pt.FromDoubles(1, 1); var b = Pt.FromDoubles(5, 4); var p = Pt.FromDoubles(3, 2.6);
            Q d = Exact.Dist2ToSegment(a, b, p);
            foreach (int k in Frames) {
                double f = Math.Pow(2, k);
                Q s = Q.FromDouble(f);
                Assert.Equal(d * s * s, Exact.Dist2ToSegment(Pt.FromDoubles(f, f), Pt.FromDoubles(5 * f, 4 * f), Pt.FromDoubles(3 * f, 2.6 * f)));
            }
        }
    }
}

using System;
using System.Numerics;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The oracle's double filter of "within the merge zone" (Oracle.ZoneFilter, used by InMergeZone for the distance to a source and to
    /// the apex) and the radius bounds it is given (Oracle.RadiusBounds), against the exact answer: wherever the filter decides, either
    /// way, it agrees with the exact distance, on points placed at the radius (relative offsets 1e-2 to 1e-15 of either sign), on
    /// segments and on single points, in frames 2^k from 2^-300 to 2^400 (scaling by a power of two keeps every double and the exact
    /// answer). The fast path's verdicts only stay those of the reference path if every decision is right.
    /// </summary>
    public class Meshing2OracleZoneFilterTests
    {
        // (2^-460 and 2^460 reach the ends of the filter's range [1e-140, 1e140] and beyond: there it may only decide rightly or not at all)
        static readonly int[] Frames = { -460, -440, -300, -150, -60, 0, 60, 150, 300, 400, 440, 460 };

        static bool Same(double v, double scaled, double f) => !double.IsInfinity(scaled) && (v == 0 || Math.Abs(scaled) >= 2.2250738585072014E-308) && scaled / f == v;

        /// <summary>Z3Pilot proves that the final +1e-300 in DistanceQueryBox
        /// changes no binary64 result: Q.Bounds already pads d2hi by 1e-300.
        /// Replay the equivalent survivor from #376 through the native code. The points
        /// include the origin and tiny coordinates: at UTM magnitudes (ulp ~1e-10) a pad
        /// changed to 1e-20 or 1e-12 would be absorbed too and the test would not see it;
        /// near zero, with d2 = 0 (reach ~1e-150), it changes the box bits.</summary>
        [Fact]
        public void SmtEquivalentSurvivor_FinalAbsoluteReachPadChangesNoBits()
        {
            var points = new[] {
                Pt.FromDoubles(632117.25, 5712043.5), Pt.FromDoubles(0, 0),
                Pt.FromDoubles(1e-30, -3e-40), Pt.FromDoubles(-0.375, 0.25) };
            foreach (int exponent in new[] { -1000, -500, -100, 0, 500, 1000 }) {
                Q distance2 = Q.FromDouble(Math.Pow(2, exponent));
                foreach (Q d2 in new[] { Q.Zero, distance2, distance2 / new Q(3, 1) })
                foreach (Pt p in points) {
                    Assert.True(Oracle.DistanceQueryBox(p, d2, out double xl, out double xh, out double yl, out double yh));
                    Assert.True(d2.Bounds(out _, out double hi));
                    Assert.True(p.Bounds(false, out double pxl, out double pxh));
                    Assert.True(p.Bounds(true, out double pyl, out double pyh));
                    // The actual survivor: omit only the final +1e-300.
                    double reach = Math.Sqrt(Math.Max(0, hi)) * (1 + 1e-12);
                    Assert.Equal(BitConverter.DoubleToInt64Bits(pxl-reach), BitConverter.DoubleToInt64Bits(xl));
                    Assert.Equal(BitConverter.DoubleToInt64Bits(pxh+reach), BitConverter.DoubleToInt64Bits(xh));
                    Assert.Equal(BitConverter.DoubleToInt64Bits(pyl-reach), BitConverter.DoubleToInt64Bits(yl));
                    Assert.Equal(BitConverter.DoubleToInt64Bits(pyh+reach), BitConverter.DoubleToInt64Bits(yh));
                }
            }
        }

        [Fact]
        public void NearTheRadius_AgreesWithTheExactDistance_BothWays_InEveryFrame()
        {
            var rnd = new Random(20261104);
            int within = 0, farther = 0, cases = 0;
            for (int n = 0; n < 4000; ++n) {
                double mag = Math.Pow(10, rnd.Next(-3, 8)), ox = (rnd.NextDouble() - 0.5) * mag * 10, oy = (rnd.NextDouble() - 0.5) * mag * 10;
                double ax = ox + (rnd.NextDouble() - 0.5) * mag, ay = oy + (rnd.NextDouble() - 0.5) * mag;
                double bx = ax, by = ay;
                bool segment = rnd.Next(3) != 0;
                if (segment) { bx = ox + (rnd.NextDouble() - 0.5) * mag; by = oy + (rnd.NextDouble() - 0.5) * mag; }
                double len = Math.Sqrt((bx - ax) * (bx - ax) + (by - ay) * (by - ay));
                // the radius: 1e-8 to 1 of the magnitude (the zone is the tube over a small sine: larger than the tube)
                double radius = mag * Math.Pow(10, -rnd.Next(0, 9)) * (0.5 + rnd.NextDouble());
                // the point: off the segment (or the point) by the radius times 1 + rel, rel of either sign, 1e-2 to 1e-15
                double rel = (rnd.Next(2) == 0 ? -1 : 1) * Math.Pow(10, -rnd.Next(2, 16));
                double off = radius * (1 + rel);
                double nx, ny, t;
                if (segment && len > 0) { nx = -(by - ay) / len; ny = (bx - ax) / len; t = rnd.NextDouble(); }
                else { double angle = rnd.NextDouble() * 2 * Math.PI; nx = Math.Cos(angle); ny = Math.Sin(angle); t = 0; }
                double px = ax + t * (bx - ax) + off * nx, py = ay + t * (by - ay) + off * ny;
                // the radius as the zone gives it, squared exactly from a double
                Q r2 = Q.FromDouble(radius) * Q.FromDouble(radius);
                bool exact = Exact.Dist2ToSegment(Pt.FromDoubles(ax, ay), Pt.FromDoubles(bx, by), Pt.FromDoubles(px, py)) <= r2;
                ++cases;
                foreach (int k in Frames) {
                    double f = Math.Pow(2, k);
                    double sax = ax * f, say = ay * f, sbx = bx * f, sby = by * f, spx = px * f, spy = py * f;
                    if (!Same(ax, sax, f) || !Same(ay, say, f) || !Same(bx, sbx, f) || !Same(by, sby, f) || !Same(px, spx, f) || !Same(py, spy, f)) continue;
                    Q s = Q.FromDouble(f);
                    Oracle.RadiusBounds(r2 * s * s, out double lo, out double hi);
                    int got = Oracle.ZoneFilter(sax, say, sbx, sby, spx, spy, lo, hi);
                    if (got == 0) continue;
                    if (got > 0) ++within; else ++farther;
                    Assert.True((got > 0) == exact, "case " + n + " at 2^" + k + ": filter " + got + ", exact " + (exact ? "within" : "farther")
                        + " (a " + ax + " " + ay + ", b " + bx + " " + by + ", p " + px + " " + py + ", radius " + radius + ", rel " + rel + ")");
                }
            }
            // the filter is useful both ways (most of the Herne tiles' zone tests are "within")
            Assert.True(within > cases && farther > cases, "decided " + within + " within and " + farther + " farther over " + cases + " cases");
        }

        /// <summary> the call sites' decision: the filter's answer where it decides, the exact test only where it does not (an undecided
        /// filter taken as either answer would differ from the exact test in the band of the slack) </summary>
        [Fact]
        public void WithinZone_TakesTheExactTestOnlyWhenUndecided()
        {
            int calls = 0;
            bool Exact(bool answer) { ++calls; return answer; }
            Assert.True(Oracle.WithinZone(1, () => Exact(false)));
            Assert.False(Oracle.WithinZone(-1, () => Exact(true)));
            Assert.Equal(0, calls);
            Assert.False(Oracle.WithinZone(0, () => Exact(false)));
            Assert.True(Oracle.WithinZone(0, () => Exact(true)));
            Assert.Equal(2, calls);
        }

        /// <summary>
        /// The query box of the domain-edge index (Oracle.DistanceQueryBox): a segment exactly sqrt(d2) from p, d2 its exact squared
        /// distance, has a box (Oracle.SegmentBox, as the grid stores it) that meets the query box, in the frames 2^-500 to 2^500. Where
        /// the squares do not fit doubles (the far frames) DistanceQueryBox refuses and the caller scans every edge. A query box narrower
        /// than the widening by sqrt(d2) misses the segment at the edge of the distance, the case the exact test still accepts
        /// (d &lt;= d2): the widening from d2's lower bound with a factor below 1 fails here. Each margin alone (the factor 1 + 1e-12, the
        /// 1e-300, d2's upper bound) is one of several layers with Bounds' own pads, so dropping a single one changes nothing
        /// </summary>
        [Fact]
        public void DistanceQueryBox_MeetsEverySegmentAtExactlyTheDistance()
        {
            var rnd = new Random(500);
            int[] frames = { -500, -480, -300, 0, 300, 480, 500 };
            int checkedFrames = 0;
            for (int n = 0; n < 3000; ++n) {
                double mag = Math.Pow(10, rnd.Next(-3, 6));
                double ax = (rnd.NextDouble() - 0.5) * mag, ay = (rnd.NextDouble() - 0.5) * mag;
                double bx = ax, by = ay;
                int kind = rnd.Next(3);   // 0 a segment, 1 a horizontal one, 2 a point
                if (kind != 2) { bx = (rnd.NextDouble() - 0.5) * mag; by = kind == 1 ? ay : (rnd.NextDouble() - 0.5) * mag; }
                double px = (rnd.NextDouble() - 0.5) * mag, py = (rnd.NextDouble() - 0.5) * mag;
                foreach (int k in frames) {
                    double f = Math.Pow(2, k);
                    double sax = ax * f, say = ay * f, sbx = bx * f, sby = by * f, spx = px * f, spy = py * f;
                    if (!Same(ax, sax, f) || !Same(ay, say, f) || !Same(bx, sbx, f) || !Same(by, sby, f) || !Same(px, spx, f) || !Same(py, spy, f)) continue;
                    Pt a = Pt.FromDoubles(sax, say), b = Pt.FromDoubles(sbx, sby), p = Pt.FromDoubles(spx, spy);
                    Q d2 = Exact.Dist2ToSegment(a, b, p);
                    if (!Oracle.DistanceQueryBox(p, d2, out double xl, out double xh, out double yl, out double yh)) continue;
                    var box = Oracle.SegmentBox(a, b);
                    if (double.IsNaN(box[0])) continue;
                    ++checkedFrames;
                    Assert.False(box[1] < xl || box[0] > xh || box[3] < yl || box[2] > yh,
                        "case " + n + " at 2^" + k + ": the segment's box misses the query box (a " + sax + " " + say + ", b " + sbx + " " + sby + ", p " + spx + " " + spy + ")");
                }
            }
            Assert.True(checkedFrames > 10000, "only " + checkedFrames + " frames checked");
        }

        [Fact]
        public void RadiusBounds_EncloseTheExactRadius()
        {
            var rnd = new Random(7);
            for (int n = 0; n < 2000; ++n) {
                // a ratio of large integers, as the zone's (tube^2 Z^2 / sin^2) is
                var num = new BigInteger(rnd.NextDouble() * 1e15) * BigInteger.Pow(2, rnd.Next(0, 200)) + 1;
                var den = new BigInteger(rnd.NextDouble() * 1e15) * BigInteger.Pow(2, rnd.Next(0, 200)) + 1;
                var r2 = new Q(num, den);
                Oracle.RadiusBounds(r2, out double lo, out double hi);
                Assert.True(lo > 0 && hi < double.PositiveInfinity, "unknown bounds for " + r2);
                Assert.True(Q.FromDouble(lo) * Q.FromDouble(lo) <= r2, "lo^2 above r2 for " + r2);
                Assert.True(Q.FromDouble(hi) * Q.FromDouble(hi) >= r2, "hi^2 below r2 for " + r2);
                // and tight: within 1e-11 relative (the filter decides near the radius)
                Assert.True(hi / lo < 1 + 1e-11, "bounds too wide: " + lo + " " + hi);
            }
            Oracle.RadiusBounds(Q.Zero, out double zl, out double zh);
            Assert.Equal(0, zl);
            Assert.True(zh >= 0 && zh < 1e-149);   // (Bounds pads by 1e-300 absolute: the radius bound of 0 is about 1e-150)
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The gates of <c>m2.snap</c> (explicit tolerance, O11, D14). With snap rounding built the rows are covered and run through the
    /// oracle in the catalogue tests; here: the sharpened bounds still separate (the same rows without snapping fail them), the oracle
    /// accepts merged results built by hand, and snapped meshes of random inputs, restore pixels included, pass the oracle at M2 and M3.
    /// </summary>
    public class Meshing2SnapGateTests
    {
        static CatalogueRow Row(string id) => Catalogue.Rows().Single(r => r.Case != null && r.Case.Id == id);

        static int SurvivingVertices(Mesh2Input input, Mesh2Output output) =>
            output.VX.Length - Enumerable.Range(0, input.Count).Count(i => output.InputToVertex[i] != i);

        [Theory]
        [InlineData("f-16")]   // without snapping the near-collinear pair does not share S-B: refinement runs to the Steiner limit
        [InlineData("f-17")]   // the hole far below the tolerance stays: 8 vertices
        [InlineData("f-17/b")] // the contour around the hole marker stays
        [InlineData("f-22/b")] // the sliver within 2^-29 stays: the Steiner limit, as without tolerance
        public void SnapRow_MeetsItsBound_OnlyWithSnapping(string id)
        {
            var row = Row(id);
            Assert.Equal(CaseState.Covered, row.State);
            var candidate = CandidateRegistry.For(row.Case.Milestone);
            var snapped = candidate.Run(row.Case.Input);
            Assert.InRange(SurvivingVertices(row.Case.Input, snapped), 1, row.Case.Expect.MaxVertices.Value);
            // the vertex bound alone, as the oracle's CountOutOfRange judges it; the full oracle would take minutes on the unsnapped F-16
            var plain = CloneWithoutSnapping(row.Case.Input);
            var unsnapped = candidate.Run(plain);
            Assert.True(SurvivingVertices(plain, unsnapped) > row.Case.Expect.MaxVertices.Value, id + ": the bound does not separate snapping from none");
        }

        static Mesh2Input CloneWithoutSnapping(Mesh2Input input) => new Mesh2Input {
            X = input.X, Y = input.Y, Segments = input.Segments, Rings = input.Rings, HoleSeeds = input.HoleSeeds, Regions = input.Regions,
            MinAngleDeg = input.MinAngleDeg, MaxArea = input.MaxArea, SteinerLimit = input.SteinerLimit, Conforming = input.Conforming, SnapTolerance = 0 };

        /// <summary>
        /// the merged result of F-17 and F-17/b, built by hand: the outer square, the collapsed contour as one point at (5, 5), its pixel
        /// centre on the grid of the tolerance; the other contour points stay in the list as aliases of it (Q8)
        /// </summary>
        static Mesh2Output CollapsedHole(Mesh2Input input)
        {
            var map = new int[input.Count];
            for (int i = 0; i < input.Count; ++i) map[i] = i < 4 ? i : 4;
            Assert.Equal(5.0, input.X[4]); Assert.Equal(5.0, input.Y[4]);
            var tris = new[] { new[] { 0, 1, 4 }, new[] { 1, 2, 4 }, new[] { 2, 3, 4 }, new[] { 3, 0, 4 } };
            return new Mesh2Output {
                Status = Mesh2Status.Success, VX = (double[])input.X.Clone(), VY = (double[])input.Y.Clone(), InputToVertex = map, Triangles = tris,
                Neighbours = SelfCheck.NeighboursOf(tris),
                Subsegments = new List<SubsegmentOutput> { new SubsegmentOutput(0, 1), new SubsegmentOutput(1, 2), new SubsegmentOutput(2, 3), new SubsegmentOutput(3, 0) },
            };
        }

        [Theory]
        [InlineData("f-17")]
        [InlineData("f-17/b")]
        public void SnapGate_AcceptsTheCollapsedHole(string id)
        {
            var row = Row(id);
            Assert.Equal(5, row.Case.Expect.MaxVertices.Value);   // the bound is tight: one vertex more is rejected
            var report = Oracle.Check(row.Case.Input, CollapsedHole(row.Case.Input), row.Case.Expect);
            Assert.True(report.Ok, report.ToString());
        }

        /// <summary>
        /// Snapped meshes of random inputs through the oracle. At M3 refinement puts every vertex on the grid (owner decision 2026-11-01,
        /// MESHING2D_SNAP.md section 3g); the oracle checks that (OffGrid) and judges the angle with the floor of two pixels and the
        /// grid-blocked exemption.
        /// </summary>
        [Theory]
        [InlineData(Milestone.M2, 0.0)]
        [InlineData(Milestone.M3, 20.0)]
        [InlineData(Milestone.M3, 30.0)]
        public void Fuzz_SnappedMeshes_PassTheOracle(Milestone milestone, double angle)
        {
            // random segments in a square ring, snapped at a coarse tolerance so that crossings, merges and restore pixels occur
            var random = new Random(milestone == Milestone.M2 ? 11 : (int)angle);
            for (int iter = 0; iter < 60; ++iter) {
                var x = new List<double> { 0, 16, 16, 0 }; var y = new List<double> { 0, 0, 16, 16 };
                var input = new Mesh2Input();
                input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
                int m = 4 + random.Next(10);
                for (int i = 0; i < m; ++i) {
                    for (int k = 0; k < 2; ++k) { x.Add(1 + Math.Round(random.NextDouble() * 14 * 64) / 64); y.Add(1 + Math.Round(random.NextDouble() * 14 * 64) / 64); }
                    input.Segments.Add(new SegmentInput(x.Count - 2, x.Count - 1));
                }
                input.X = x.ToArray(); input.Y = y.ToArray();
                input.SnapTolerance = milestone == Milestone.M2 ? new[] { 0.5, 1, 2 }[iter % 3] : new[] { 0.25, 0.5, 1, 0.3 }[iter % 4];
                if (milestone == Milestone.M3) { input.MinAngleDeg = angle; input.SteinerLimit = 50000; }
                var output = CandidateRegistry.For(milestone).Run(input);
                var report = Oracle.Check(input, output, new OracleExpect { Milestone = milestone });
                Assert.True(report.Ok, "iteration " + iter + ": " + report);
            }
        }

        /// <summary> the i-th input of a random stream: up to 24 segments on a 1/64 lattice in a square ring, pixel widths that do not divide it </summary>
        static Mesh2Input GridFuzzInput(int seed, double angle, int which)
        {
            var random = new Random(seed + (int)angle);
            Mesh2Input input = null;
            for (int iter = 0; iter <= which; ++iter) {
                var x = new List<double> { 0, 16, 16, 0 }; var y = new List<double> { 0, 0, 16, 16 };
                input = new Mesh2Input();
                input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
                int m = 4 + random.Next(20);
                for (int i = 0; i < m; ++i) {
                    for (int k = 0; k < 2; ++k) { x.Add(1 + Math.Round(random.NextDouble() * 14 * 64) / 64); y.Add(1 + Math.Round(random.NextDouble() * 14 * 64) / 64); }
                    input.Segments.Add(new SegmentInput(x.Count - 2, x.Count - 1));
                }
                input.X = x.ToArray(); input.Y = y.ToArray();
                input.SnapTolerance = new[] { 0.25, 0.5, 1, 0.3, 1.0 / 3, 0.125 }[iter % 6];
                input.MinAngleDeg = angle; input.SteinerLimit = 50000;
            }
            return input;
        }

        /// <summary>
        /// Inputs of a larger grid fuzz run (12000 meshes) that failed on the way to refinement on the grid, each for its own reason: a
        /// refusal that went stale when a neighbouring chain was split and bent away (the mesher looks again after a sweep with
        /// insertions); a lattice triangle with two equal shortest edges (the oracle tries both for a small input angle); a vertex, or a
        /// triangle's circumcentre, behind a subsegment with no split point on the grid; vertices on a grid of width 0.3 or 1/3, which
        /// doubles do not hold exactly, taken at their pixel centre and matched by their pixel, and pixel corners touched there.
        /// </summary>
        [Theory]
        [InlineData(1000, 20.0, 130)]   // stale refusal
        [InlineData(1000, 20.0, 563)]   // tie of shortest edges
        [InlineData(1000, 30.0, 234)]   // tie of shortest edges
        [InlineData(1000, 30.0, 11)]    // vertex behind an unsplittable piece
        [InlineData(1000, 20.0, 315)]   // vertex behind an unsplittable piece
        [InlineData(7000, 30.0, 866)]   // circumcentre behind an unsplittable piece (outside the domain)
        [InlineData(7000, 20.0, 103)]   // circumcentre behind an unsplittable piece
        [InlineData(7000, 20.0, 736)]   // vertex pixel at w = 1/3
        [InlineData(7000, 30.0, 1353)]  // vertex pixel at w = 0.3
        [InlineData(9100, 20.0, 1281)]  // subsegment end at w = 0.3
        [InlineData(9100, 20.0, 628)]   // pixel corner touched at w = 1/3
        [InlineData(12000, 30.0, 694)]  // circumcentre tried again after its encroached piece proved unsplittable
        public void GridRefinement_FuzzRegressions_PassTheOracle(int seed, double angle, int which)
        {
            var input = GridFuzzInput(seed, angle, which);
            var output = CandidateRegistry.For(Milestone.M3).Run(input);
            Assert.Equal(Mesh2Status.Success, output.Status);
            var report = Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Situations reported against other meshing libraries, rebuilt here from their description only (no code read): each runs as a
    /// constrained Delaunay triangulation (M2) and refined (M3) in the default and the constrained-quality mode, with and without a snap
    /// tolerance where the situation is about tolerances, and must pass the oracle (or fail cleanly where the situation asks for it).
    /// </summary>
    public class Meshing2TrackerCasesTests
    {
        sealed class Builder
        {
            readonly List<double> x = new List<double>(), y = new List<double>();
            public readonly Mesh2Input Input = new Mesh2Input();
            public int P(double px, double py) { x.Add(px); y.Add(py); return x.Count - 1; }
            public int[] Ps(params double[] xy) { var r = new int[xy.Length / 2]; for (int i = 0; i < r.Length; ++i) r[i] = P(xy[2 * i], xy[2 * i + 1]); return r; }
            public void Ring(bool hole, params double[] xy) => Input.Rings.Add(new RingInput(Ps(xy), hole));
            public void RingOf(bool hole, int[] ids) => Input.Rings.Add(new RingInput(ids, hole));
            public void Seg(int a, int b) => Input.Segments.Add(new SegmentInput(a, b));
            public void Seg(double ax, double ay, double bx, double by) => Seg(P(ax, ay), P(bx, by));
            public Mesh2Input Done(double snap = 0) { Input.X = x.ToArray(); Input.Y = y.ToArray(); Input.SnapTolerance = snap; return Input; }
        }

        /// <summary> the situations, by name </summary>
        internal static Mesh2Input Case(string name)
        {
            var b = new Builder();
            switch (name) {
                // a constraint loop given twice (CGAL#3267: non-termination when the same loop is inserted twice)
                case "loop-twice": {
                    b.Ring(false, 0, 0, 10, 0, 10, 10, 0, 10);
                    var loop = b.Ps(3, 3, 7, 3, 7, 7, 3, 7);
                    for (int k = 0; k < 2; ++k) for (int i = 0; i < 4; ++i) b.Seg(loop[i], loop[(i + 1) % 4]);
                    var again = b.Ps(3, 3, 7, 3, 7, 7, 3, 7);
                    for (int i = 0; i < 4; ++i) b.Seg(again[i], again[(i + 1) % 4]);
                    return b.Done();
                }
                // a point 1e-15 off a segment, the orientation decided by an epsilon elsewhere (poly2tri#39)
                case "point-1e-15-off": {
                    b.Ring(false, 0, 0, 10, 0, 10, 10, 0, 10);
                    b.Seg(1, 5, 9, 5);
                    b.P(5, 5 + 1e-15); b.P(3, 5 - 1e-15); b.P(7, 5);
                    return b.Done();
                }
                // a hole vertex collinear with an outer vertex and another hole vertex: a bridge along that line may fill the hole (earcut#219)
                case "collinear-bridge": {
                    b.Ring(false, 0, 0, 10, 0, 10, 10, 0, 10);
                    b.Ring(true, 2, 2, 5, 2, 8, 2, 8, 6, 5, 6, 2, 6);
                    b.P(5, 0.5);
                    return b.Done();
                }
                // holes touching each other and the outer ring at single vertices (earcut#129, poly2tri#55)
                case "holes-touching": {
                    b.Ring(false, 0, 0, 10, 0, 10, 10, 0, 10);
                    b.Ring(true, 0, 5, 3, 3, 3, 7);          // touches the outer ring at (0, 5)
                    b.Ring(true, 3, 7, 6, 5, 6, 9);          // touches the first hole at (3, 7)
                    b.Ring(true, 6, 5, 9, 2, 10, 5);         // touches the second at (6, 5) and the outer ring at (10, 5)
                    return b.Done();
                }
                // constraints that already are Delaunay edges: a regular grid of points whose grid lines are constraints (JTS#1190: Steiner
                // points added to them, no convergence)
                case "delaunay-edges": {
                    b.Ring(false, 0, 0, 8, 0, 8, 8, 0, 8);
                    var id = new int[9, 9];
                    for (int i = 0; i <= 8; ++i) for (int j = 0; j <= 8; ++j) id[i, j] = (i == 0 || j == 0 || i == 8 || j == 8) ? -1 : b.P(i, j);
                    for (int i = 1; i < 8; ++i) for (int j = 1; j < 7; ++j) { b.Seg(id[i, j], id[i, j + 1]); b.Seg(id[j, i], id[j + 1, i]); }
                    return b.Done();
                }
                // short near-collinear constraints crossing at a shallow angle, the crossing 1e-7 off (CDT#229)
                case "shallow-crossing": {
                    b.Ring(false, 0, 0, 10, 0, 10, 10, 0, 10);
                    b.Seg(4, 5, 6, 5 + 1e-7);
                    b.Seg(4, 5 + 1e-7, 6, 5);
                    b.Seg(4.5, 5 - 3e-8, 5.5, 5 + 7e-8);
                    return b.Done();
                }
                // an edge through many collinear connected vertices (CDT#86: recursion depth)
                case "collinear-chain": {
                    b.Ring(false, -1, -1, 2001, -1, 2001, 1, -1, 1);
                    int prev = b.P(0, 0);
                    for (int i = 1; i <= 2000; ++i) { int c = b.P(i, 0); b.Seg(prev, c); prev = c; }
                    b.Seg(b.P(0, 0), b.P(2000, 0));
                    return b.Done();
                }
                // zero-length constraints (CGAL#781)
                case "zero-length": {
                    b.Ring(false, 0, 0, 10, 0, 10, 10, 0, 10);
                    int p = b.P(5, 5); b.Seg(p, p);
                    b.Seg(3, 3, 3, 3);
                    b.Seg(7, 2, 7, 2 + 1e-300);
                    return b.Done();
                }
                // snap rounding a chain that doubles back, at 9e8 (CGAL#4741)
                case "double-back-9e8": {
                    double o = 9e8;
                    b.Ring(false, o, o, o + 64, o, o + 64, o + 64, o, o + 64);
                    var chain = b.Ps(o + 10, o + 10, o + 50, o + 30.0000001, o + 10.0000002, o + 30, o + 50, o + 50.0000003);
                    for (int i = 0; i + 1 < chain.Length; ++i) b.Seg(chain[i], chain[i + 1]);
                    return b.Done(0.5);
                }
                // two vertices 1e-8 apart against a tolerance of 1e-5 (JTS#321): merged
                case "close-pair": {
                    b.Ring(false, 0, 0, 10, 0, 10, 10, 0, 10);
                    b.Seg(2, 5, 8, 5);
                    b.P(5, 5 + 1e-8); b.P(5 + 1e-8, 7); b.P(5, 7);
                    return b.Done(1e-5);
                }
                // a self-crossing comb-shaped hole (GEOS#1283: a clean rejection expected there)
                case "comb-hole": {
                    b.Ring(false, 0, 0, 20, 0, 20, 10, 0, 10);
                    b.Ring(true, 2, 2, 18, 2, 18, 8, 16, 8, 16, 3, 14, 9, 12, 3, 10, 9, 8, 3, 6, 9, 4, 3, 4, 8, 2, 8);
                    return b.Done();
                }
                // a point 2e-11 off a hull edge (delaunator#91); points only, the hull is the boundary
                case "hull-2e-11": {
                    b.Ps(0, 0, 10, 0, 10, 10, 0, 10, 5, -2e-11, 5, 5, 2.5, 1e-11, 7.5, 2e-11);
                    return b.Done();
                }
            }
            throw new ArgumentException(name);
        }

        public static IEnumerable<object[]> Runs()
        {
            var names = new[] { "loop-twice", "point-1e-15-off", "collinear-bridge", "holes-touching", "delaunay-edges", "shallow-crossing",
                "collinear-chain", "zero-length", "double-back-9e8", "close-pair", "comb-hole", "hull-2e-11" };
            foreach (var n in names)
                foreach (var mode in new[] { "M2", "M3@20", "M3@30", "M3c@20", "M3c@30" })
                    yield return new object[] { n, mode };
        }

        [Theory]
        [MemberData(nameof(Runs))]
        public void TrackerCase_PassesTheOracle(string name, string mode)
        {
            var input = Case(name);
            var milestone = mode == "M2" ? Milestone.M2 : Milestone.M3;
            if (milestone == Milestone.M3) {
                input.MinAngleDeg = mode.EndsWith("30") ? 30 : 20;
                // (two segments 1e-7 apart along a length of 2 have a local feature size of 1e-7 all along: a quality mesh needs about
                // length / gap vertices, so refinement stops at the limit, O7, with a valid mesh)
                input.SteinerLimit = name == "shallow-crossing" ? 5000 : 200000;
                input.ConstrainedQuality = mode.StartsWith("M3c");
            }
            var o = CandidateRegistry.For(milestone).Run(input);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = milestone });
            Assert.True(report.Ok, name + " " + mode + " (" + o.Status + "): " + report);
            Assert.Equal(Mesh2Status.Success, o.Status);
            if (name == "shallow-crossing") Assert.Equal(milestone == Milestone.M3, o.SteinerLimitReached);
            else Assert.False(o.SteinerLimitReached, name + " " + mode + " reached the Steiner limit");
            // two vertices 1e-8 apart against a tolerance of 1e-5 are one vertex
            if (name == "close-pair") Assert.Equal(o.InputToVertex[7], o.InputToVertex[8]);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The decisions of the small-angle rule (QualityMesh2.Refiner.ApexExempt; MESHING2D_SMALL_ANGLES.md section 2), read from the
    /// refiner's log of vertex encroachments: which vertices exempt which subsegments, and which do not (Shewchuk 2002 section 6.2
    /// splits for a parent that "is an input vertex or lies on a nonincident segment").
    /// </summary>
    public class QualityMesh2ApexExemptionTests
    {
        static List<(Vector2d U, Vector2d W, Vector2d V, bool Exempt)> Log(Mesh2Input input, out Mesh2Output output, bool? exemption = null)
        {
            var log = new List<(Vector2d U, Vector2d W, Vector2d V, bool Exempt)>();
            QualityMesh2.Refiner.SmallAngleExemptionForTests = exemption;
            QualityMesh2.Refiner.ApexLogForTests = log;
            try { output = new QualityMesh2Candidate().Run(input); }
            finally { QualityMesh2.Refiner.SmallAngleExemptionForTests = null; QualityMesh2.Refiner.ApexLogForTests = null; }
            Assert.True(output.Status == Mesh2Status.Success, output.Status + " " + output.FailureKind);
            Assert.False(output.SteinerLimitReached);
            var report = Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            return log;
        }

        /// <summary>
        /// a = A-B from A = (0, 0) to B = (10, 0), c from A at a small angle, and a top point (8, 6); kind:
        /// 0 c = A-(16, 1) through an input point P = (8, 0.5);
        /// 1 c = A-F with F = (8, 0.5), which a segment to the top continues (c's far endpoint, on two sources);
        /// 2 c = A-(16, 1), and a segment from the top ends on c at Y = (8, 0.5) (an input vertex with a third source);
        /// 3 a = A-(16, 0) through an input point Q = (2, 0), and c = A-(16, 1).
        /// The vertex (8, 0.5) faces a's subsegment from A in kinds 0-2.
        /// </summary>
        internal static Mesh2Input Pair(int kind, double angle = 30)
        {
            var x = new List<double> { 0, kind == 3 ? 16 : 10, 8 };
            var y = new List<double> { 0, 0, 6 };
            var segments = new List<SegmentInput> { new SegmentInput(0, 1) };
            void Add(double px, double py) { x.Add(px); y.Add(py); }
            if (kind == 1) { Add(8, 0.5); segments.Add(new SegmentInput(0, 3)); segments.Add(new SegmentInput(3, 2)); }
            else {
                Add(16, 1); segments.Add(new SegmentInput(0, 3));
                if (kind == 0) Add(8, 0.5);
                if (kind == 2) { Add(8, 0.5); segments.Add(new SegmentInput(4, 2)); }
                if (kind == 3) Add(2, 0);
            }
            var xy = new double[2 * x.Count];
            for (int i = 0; i < x.Count; ++i) { xy[2 * i] = x[i]; xy[2 * i + 1] = y[i]; }
            var input = Generators.Literal(xy);
            input.Segments.AddRange(segments);
            input.MinAngleDeg = angle;
            input.ConstrainedQuality = true;
            return input;
        }

        static readonly Vector2d At = new Vector2d(8, 0.5);

        /// <summary>
        /// a near miss: c = (0.5, 0.05)-(16, 1.05) runs at about 3.7 degrees to a = A-B, but stops short of it; the lines meet at
        /// (-0.275, 0), outside a. The closed segments do not meet (PairOf's exact MeetKind is 0), so no refinement vertex on c exempts a
        /// subsegment of a: this is a nonincident feature in the sense of Shewchuk 2002 section 6.2, and a near contact is its own open
        /// question (MESHING2D_SMALL_ANGLES.md section 7). Kills "pair whenever the lines meet at a small angle".
        /// </summary>
        [Fact]
        public void NearMiss_DoesNotExempt()
        {
            var input = Generators.Literal(0, 0, 10, 0, 8, 6, 0.5, 0.05, 16, 1.05);
            input.Segments.Add(new SegmentInput(0, 1));
            input.Segments.Add(new SegmentInput(3, 4));
            input.MinAngleDeg = 30;
            input.ConstrainedQuality = true;
            var log = Log(input, out _);
            // c's refinement vertices (strictly between its ends, not input points) that encroach a subsegment of a
            bool OnC(Vector2d p) => p.x > 0.5 && p.x < 16 && Math.Abs((p.x - 0.5) * 1.0 - (p.y - 0.05) * 15.5) < 1e-9 * 16;
            var byC = log.Where(l => OnC(l.V) && OnA(l.U) && OnA(l.W)).ToList();
            Assert.NotEmpty(byC);
            Assert.All(byC, l => Assert.False(l.Exempt, l.U + " - " + l.W + " by " + l.V));
        }

        static bool OnA(Vector2d p) => p.y == 0;

        /// <summary> an input point on c, c's far endpoint, an input vertex with a third source: each encroaches a subsegment of a (at
        /// least once) and never exempts it </summary>
        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        [InlineData(2)]
        public void InputVertexOnThePartner_DoesNotExempt(int kind)
        {
            var log = Log(Pair(kind), out _);
            var byIt = log.Where(l => l.V == At && OnA(l.U) && OnA(l.W)).ToList();
            Assert.NotEmpty(byIt);
            Assert.All(byIt, l => Assert.False(l.Exempt, l.U + " - " + l.W));
        }

        /// <summary> a refinement vertex on c encroaching a's subsegment between two input vertices Q = (2, 0) and B = (16, 0): neither end is
        /// on c, and their distances from the apex differ by 8 (more than 1.5 from the vertex's), so it is split as before </summary>
        [Fact]
        public void FarSubsegment_IsSplitAsBefore()
        {
            var log = Log(Pair(3), out _);
            var far = log.Where(l => l.V == At && (l.U == new Vector2d(2, 0) && l.W == new Vector2d(16, 0) || l.U == new Vector2d(16, 0) && l.W == new Vector2d(2, 0))).ToList();
            Assert.NotEmpty(far);
            Assert.All(far, l => Assert.False(l.Exempt));
            // the rule does act elsewhere in this mesh
            Assert.Contains(log, l => l.Exempt);
        }

        /// <summary> the hull wedge: refinement vertices on the segment exempt the hull edge's shell subsegment from A; without the rule
        /// nothing is exempt, and the cascade makes many times the triangles </summary>
        [Fact]
        public void HullWedge_ShellSubsegmentIsExempt()
        {
            var log = Log(QualityMesh2SmallAngleRuleTests.HullWedge(30), out var on);
            Assert.Contains(log, l => l.Exempt && (l.U == Vector2d.Zero || l.W == Vector2d.Zero));
            var off = Log(QualityMesh2SmallAngleRuleTests.HullWedge(30), out var offOutput, exemption: false);
            Assert.DoesNotContain(off, l => l.Exempt);
            Assert.True(on.Triangles.Length * 4 < offOutput.Triangles.Length, on.Triangles.Length + " against " + offOutput.Triangles.Length);
        }

        /// <summary> input angles at or above the bound (also between it and 60 degrees, where Shewchuk's clusters reach), and in the
        /// oracle's window below it (30 degrees - 6e-10 rad): no exemption, and the mesh is the one without the rule, bit for bit </summary>
        [Theory]
        [InlineData(30.0)]
        [InlineData(31.0)]
        [InlineData(30 - 6e-10 * 180 / Math.PI)]
        [InlineData(40.0)]
        public void AngleAtTheBound_IsNotSmall(double degrees)
        {
            var log = Log(QualityMesh2SmallAngleRuleTests.HullWedge(30, degrees), out var on);
            Assert.DoesNotContain(log, l => l.Exempt);
            Log(QualityMesh2SmallAngleRuleTests.HullWedge(30, degrees), out var off, exemption: false);
            Assert.Equal(off.VX, on.VX);
            Assert.Equal(off.VY, on.VY);
            Assert.Equal(off.Triangles.SelectMany(t => t), on.Triangles.SelectMany(t => t));
        }

        /// <summary> in the shell cascade the encroaching partner vertex lies at about half the radius of the shell subsegment's far end:
        /// beyond radius matching (1.5), so the shell rule (i) exempts it (the wedge at 20 degrees, with lenses) </summary>
        [Fact]
        public void ShellSubsegment_AtTwiceTheRadius_IsExempt()
        {
            var log = Log(QualityMesh2SmallAngleRuleTests.HullWedge(20), out _);
            Assert.Contains(log, l => l.Exempt && (l.U == Vector2d.Zero || l.W == Vector2d.Zero)
                && (l.U == Vector2d.Zero ? l.W : l.U).LengthSquared > 2.25 * l.V.LengthSquared);
        }

        /// <summary>
        /// Both sources end at the apex (a segment P-A and a segment B-A): computed in doubles, the parameter of the apex on one of them is
        /// 1 + 2^-52, and the strict test of SpansSmallAngle misses the pair (about a fifth of random such pairs). The exact meeting test
        /// pairs them: the subsegment of B-A from the apex is exempt
        /// </summary>
        [Fact]
        public void BothSourcesEndAtTheApex_ArePaired()
        {
            var input = Generators.Literal(0.207, 0.778, 8.553, 0.778, 6.172, 1.083, 0.2, 6);
            input.Segments.Add(new SegmentInput(2, 0)); input.Segments.Add(new SegmentInput(1, 0));
            input.MinAngleDeg = 30;
            input.ConstrainedQuality = true;
            var apex = new Vector2d(0.207, 0.778);
            var log = Log(input, out _);
            Assert.Contains(log, l => l.Exempt && (l.U == apex || l.W == apex));
        }

        /// <summary> the conforming mode is unchanged: no exemption, the same mesh as without the rule </summary>
        [Fact]
        public void ConformingMode_IsUnchanged()
        {
            var input = QualityMesh2SmallAngleRuleTests.HullWedge(25, 5.0);
            input.ConstrainedQuality = false;
            var log = Log(input, out var on);
            Assert.DoesNotContain(log, l => l.Exempt);
            Log(input, out var off, exemption: false);
            Assert.Equal(off.VX, on.VX);
            Assert.Equal(off.Triangles.SelectMany(t => t), on.Triangles.SelectMany(t => t));
        }

        /// <summary> how two closed segments meet, exactly: a shared endpoint, a T-junction, a crossing, and three that do not meet </summary>
        [Fact]
        public void MeetKind_IsExact()
        {
            int Kind(double ax, double ay, double bx, double by, double cx, double cy, double dx, double dy)
                => QualityMesh2.Refiner.MeetKind(new Vector2d(ax, ay), new Vector2d(bx, by), new Vector2d(cx, cy), new Vector2d(dx, dy));
            Assert.Equal(1, Kind(0, 0, 10, 0, 0, 0, 10, 1));            // shared endpoint
            Assert.Equal(1, Kind(10, 0, 0, 0, 10, 1, 0, 0));            // the same, reversed
            Assert.Equal(2, Kind(0, 0, 10, 0, 5, 0, 10, 1));            // T-junction: c starts on a's interior
            Assert.Equal(2, Kind(0, 0, 10, 0, 1, -1e-3, 9, 1e-3));      // crossing at a small angle
            // a near miss: c ends 2^-30 above a long a (inside a relative window of 1e-9 of a, but not on it)
            Assert.Equal(0, Kind(0, 0, 1e6, 0, 5e5, 1.0 / (1 << 30), 6e5, 1));
            Assert.Equal(0, Kind(0, 0, 10, 0, 10 + 1e-9, 0, 20, 1));    // c starts just past a's end
            Assert.Equal(0, Kind(0, 0, 10, 0, 2, 0, 20, 0));            // collinear, overlapping: no apex
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    [CollectionDefinition("Meshing2OracleTiming", DisableParallelization = true)]
    public class Meshing2OracleTimingCollection { }

    /// <summary>
    /// The parts of <see cref="QualityMesh2CollapsedPartsTests"/> that use the change's own members (the oracle's O-H5 counts, the
    /// mesher's diagnostics), apart so that the cases themselves compile against the library without the change. The library change is
    /// the diagnostics only: of these tests, the mesher's fail on the library without it
    /// </summary>
    // The oracle's wall-clock budget must not include CPU contention from other test collections.
    [Collection("Meshing2OracleTiming")]
    public class QualityMesh2CollapsedPartsReportTests
    {
        /// <summary>
        /// the mesher reports what snapping collapsed (the zigzag's teeth); what refinement pinches is reported on a line of its own,
        /// which depends on where refinement puts its points and is not asked for here
        /// </summary>
        [Fact]
        public void Mesher_ReportsWhatSnappingCollapsed()
        {
            var c = ConstrainedDelaunayMesh2Candidate.Convert(QualityMesh2CollapsedPartsTests.Zigzag(0, 20));
            var r = new QualityMesh2 { MinAngle = 20, SnapTolerance = 0.01, SteinerLimit = 50000, Conforming = true }.Compute(c);
            var lines = r.Diagnostics ?? new string[0];
            Assert.Contains(lines, l => l.StartsWith("snap grid: ") && l.Contains(" input segments with pieces on parts that snapping collapsed"));
        }

        /// <summary>
        /// a 20 square with a corridor 0.25 wide from x 20 to 20 + length, with a ring vertex every pixel along both walls; points and
        /// segments optional (a free point in the corridor, a segment along its middle)
        /// </summary>
        internal static Mesh2Input Corridor(int length, bool freePoint, bool middle)
        {
            var x = new List<double> { 0, 20 }; var y = new List<double> { 0, 0 };
            for (int i = 0; i <= length; ++i) { x.Add(20 + i); y.Add(9.875); }
            for (int i = length; i >= 0; --i) { x.Add(20 + i); y.Add(10.125); }
            x.Add(20); y.Add(20); x.Add(0); y.Add(20);
            var input = new Mesh2Input { SnapTolerance = 1 };
            input.Rings.Add(new RingInput(Enumerable.Range(0, x.Count).ToArray(), false));
            if (freePoint) { x.Add(20 + length / 2 + 0.3); y.Add(10.05); }
            if (middle) { x.Add(10); y.Add(10); x.Add(20 + length); y.Add(10); input.Segments.Add(new SegmentInput(x.Count - 2, x.Count - 1)); }
            input.X = x.ToArray(); input.Y = y.ToArray();
            return input;
        }

        /// <summary>
        /// review 3, S1: what snapping collapses is accepted from the mesher's own output: a free point in a collapsed corridor, a
        /// segment from the square through it (its chain in the square, none in the corridor)
        /// </summary>
        [Theory]
        [InlineData(true, false)]
        [InlineData(false, true)]
        [InlineData(true, true)]
        public void Oracle_AcceptsWhatSnappingCollapsed(bool freePoint, bool middle)
        {
            var input = Corridor(30, freePoint, middle);
            var o = new ConstrainedDelaunayMesh2Candidate().Run(input);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(report.Ok, report.ToString());
            Assert.True(report.CollapsedPoints > 0, report.ExcusedSummary());
            if (middle) Assert.True(report.CollapsedSegments > 0, report.ExcusedSummary());
        }

        /// <summary>
        /// Snapped alone (M2), SRR's restore step (D14) adds hot pixels of its own, part of the rounding of the input, not refinement: they
        /// must not count against rule (ii'). Post-review B2: a star polygon (2.8, 11.4), (7.2, 6.4), (6.2, 3.5), (8.6, 6.9) with the free
        /// points (2.6, 9.6) and (9.6, 6.5); the output edge (3, 11) - (7, 6) crosses the free point's pixel (3, 10), the restore step makes
        /// (4, 10) hot, and both spike edges route through it. Rejected (VertexUnused for input 0) by rule (ii') when the input-only
        /// state lacked the restore pixels; accepted with the oracle's own restore step, which finds (4, 10) itself
        /// </summary>
        [Fact]
        public void Oracle_AcceptsTheRestoreStepOfSnapping()
        {
            var input = new Mesh2Input { X = new[] { 2.8, 7.2, 6.2, 8.6, 2.6, 9.6 }, Y = new[] { 11.4, 6.4, 3.5, 6.9, 9.6, 6.5 }, SnapTolerance = 1 };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            var o = new ConstrainedDelaunayMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            Assert.Equal(input.Count + 1, o.VX.Length);   // the restore pixel
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(report.Ok, report.ToString());
        }

        /// <summary>
        /// the 18 inputs of the post-review's M2 fuzz (star polygons in [0, 16]² at 0.1, pixel 1, 0 to 2 free points, sometimes one
        /// segment; 3000 seeds) that rule (ii') rejected without the restore pixels: each with the last 0, 1 or 2 points free, accepted
        /// snapped alone. Small already (5 to 10 points), taken as found
        /// </summary>
        [Theory]
        [InlineData(688, "2.8,7.2,6.2,8.6,2.6,9.6", "11.4,6.4,3.5,6.9,9.6,6.5", "")]
        [InlineData(696, "13.7,11.7,7.9,1.4,8.3,1.6,2.6", "9.3,11.2,9.2,10.6,7,9.1,11.2", "")]
        [InlineData(812, "12.9,10.2,6,2,7,9.1,8.6,9.4,10.5", "10.4,11.6,10.8,10.6,1,5.1,6.5,6.6,11.6", "")]
        [InlineData(940, "14.8,14.2,10.6,10.2,7.4,2.2,7.2,11.1,2,11.4", "9,9,9.4,14.1,12.1,3.6,7.2,1.1,4.6,7.4", "")]
        [InlineData(972, "9.1,10.2,13.2,9.3,5.5,14.4", "8.1,8.3,9.7,11.1,9.4,7.5", "0-2")]
        [InlineData(1013, "14,6.4,5.3,7.6,8.6,8.2,10.2,11", "10,12.5,6.9,7.4,4,7.1,3.2,3.5", "4-3")]
        [InlineData(1190, "11.1,6,6.8,7.4,4.1,13.5,15.2", "10.1,8.3,8,7.8,6.4,7.5,3.4", "4-5")]
        [InlineData(1334, "8.1,8.1,7.7,4.2,2.6,5,5.8", "8.7,9.9,9.2,14.1,8.4,5.4,2.6", "")]
        [InlineData(1773, "9,11.8,6,6.1,5.5,8.7,10.7,9.7", "8.3,9.9,12.9,11.5,1.7,7.6,7.7,7.9", "")]
        [InlineData(2028, "6.2,2.2,10.8,8.6,10.2,12.5,8.4", "12.2,11.2,1.9,6.8,5.6,8.8,8.9", "1-2")]
        [InlineData(2061, "5.9,2.6,5.6,2.8,5.8,7.2,10,3.6", "10.8,12.9,8.6,6.2,4.4,4.2,2.7,13", "2-3")]
        [InlineData(2124, "12.5,8.4,2.9,7.2,9.1,12.5,11.6", "9.1,8.6,10.9,4,7.3,7.9,8.2", "")]
        [InlineData(2312, "10.9,8.7,14.2,9.5,9.5,8.3", "8.2,8.2,9.6,12.7,4.4,7.4", "5-4")]
        [InlineData(2503, "8.1,7.7,5.4,8.8,10.6,5.2", "11.3,9.7,12.4,5.7,6.7,10.7", "1-0")]
        [InlineData(2530, "10.8,10,6,5.9,2.7,1.8,14.6,5.9", "12.8,15.2,8.5,8.1,7.3,5.2,1.1,9.5", "")]
        [InlineData(2574, "13.4,9,6.2,12.9,8.8,9.5,11.4", "10.8,11.4,11.2,6.8,7.8,7.7,8.8", "")]
        [InlineData(2715, "9.8,4.9,3.8,14.7,8.2", "8.7,9,7.5,7.6,1.7", "3-1")]
        [InlineData(2772, "11.8,11.2,10.2,8.4,4.8,7.6,9.8,9.1,11.5", "8.1,10.7,12.3,10.3,11.7,5.3,7,7.4,10.3", "7-3")]
        public void Oracle_AcceptsTheRestoreStepOfSnapping_Fuzz(int seed, string xs, string ys, string segment)
        {
            var x = xs.Split(',').Select(t => double.Parse(t, System.Globalization.CultureInfo.InvariantCulture)).ToArray();
            var y = ys.Split(',').Select(t => double.Parse(t, System.Globalization.CultureInfo.InvariantCulture)).ToArray();
            for (int free = 0; free <= 2; ++free) {
                var input = new Mesh2Input { X = x, Y = y, SnapTolerance = 1 };
                input.Rings.Add(new RingInput(Enumerable.Range(0, x.Length - free).ToArray(), false));
                if (segment.Length > 0) { var s = segment.Split('-').Select(int.Parse).ToArray(); input.Segments.Add(new SegmentInput(s[0], s[1])); }
                var o = new ConstrainedDelaunayMesh2Candidate().Run(input);
                Assert.Equal(Mesh2Status.Success, o.Status);
                var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2 });
                Assert.True(report.Ok, "seed " + seed + ", " + free + " free: " + report);
            }
        }

        /// <summary>
        /// With refinement (M3), where SRR's restore step (D14) reroutes the input, the collapse belongs to the rounding of the input, not
        /// to refinement: the oracle's own restore step puts its pixels into the input-only state of rule (ii'). Of the 3000 seeds of
        /// <see cref="StarPolygonFuzz"/>, these 10 were rejected without it (pinned as known false rejections in #358 and #360: the
        /// segment pieces and input points in brackets were reported missing and unused) and are accepted now, those pieces and points
        /// excused on collapsed parts
        /// </summary>
        [Theory]
        [InlineData(62, 1, 0)]
        [InlineData(161, 1, 1)]
        [InlineData(787, 0, 1)]
        [InlineData(818, 0, 1)]
        [InlineData(963, 0, 1)]
        [InlineData(1455, 1, 0)]
        [InlineData(2396, 1, 0)]
        [InlineData(2471, 1, 0)]
        [InlineData(2459, 0, 1)]
        [InlineData(2923, 0, 1)]
        public void Oracle_AcceptsTheRestoreStepAtM3(int seed, int segmentsMissingBefore, int verticesUnusedBefore)
        {
            var input = StarPolygonFuzz.Make(seed);
            var o = new QualityMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, "seed " + seed + ": " + report);
            Assert.NotEmpty(report.RestorePixels);
            Assert.True(report.CollapsedSegments >= segmentsMissingBefore && report.CollapsedPoints >= verticesUnusedBefore, "seed " + seed + ": " + report.ExcusedSummary());
        }

        /// <summary>
        /// the refinement of before the fix (the mesher's rule that keeps the input image's chains apart off): its outputs reroute
        /// collapsed parts with output vertices, which the oracle's tests of rule (ii') and of the count (iii) need; with the rule on,
        /// refinement no longer puts a vertex where two chains of the input's image pass apart
        /// </summary>
        static Mesh2Output WithoutTheChainRule(Mesh2Input input)
        {
            QualityMesh2.Refiner.KeepChainsApartForTests = false;
            try { return new QualityMesh2Candidate().Run(input); }
            finally { QualityMesh2.Refiner.KeepChainsApartForTests = null; }
        }

        /// <summary>
        /// (iii) for points: seed 1083 of <see cref="StarPolygonFuzz"/> at M3 is accepted with 2 segment pieces and 1 input point on
        /// collapsed parts, all 3 on stretches or at a pixel where output vertices rerouted the image (rule (ii'): inside parts the
        /// input's own rounding collapses, restore pixels included). Counts exact, so a change shows. (Until the oracle's own restore
        /// step, a star whose spike tip only a restore pixel keeps stood here: the refinement before the chain rule dropped that tip,
        /// and the oracle, without the restore pixel, counted it as collapsed and rerouted; it now rejects that mesh.)
        /// </summary>
        [Fact]
        public void Oracle_CountsExcusesReroutedByOutputVertices()
        {
            var input = StarPolygonFuzz.Make(1083);
            var o = new QualityMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            Assert.Equal(2, report.CollapsedSegments);
            Assert.Equal(1, report.CollapsedPoints);
            Assert.Equal(3, report.CollapsedViaRefinement);
        }

        /// <summary>
        /// the refinement before the chain rule dropped a spike tip that only SRR's restore pixel (16, 11) keeps in the input's rounding:
        /// rejected now (VertexUnused). The mesher with the rule keeps it (accepted, with one input point on a collapsed part)
        /// </summary>
        [Fact]
        public void Oracle_RestorePixelKeepsASpikeTip_RefinementWithoutTheChainRuleIsRejected()
        {
            var x = new[] { 19.5, 18.4, 17.5, 11, 13.5, 3.1, 14.8, 10.8, 11.1, 16.3, 25.1 };
            var y = new[] { 16.3, 19, 28.2, 23.8, 16.5, 10.3, 12.3, -13.5, -13.6, 14.9, 10 };
            var input = new Mesh2Input { X = x, Y = y, SnapTolerance = 1, MinAngleDeg = 20, SteinerLimit = 5000 };
            input.Rings.Add(new RingInput(Enumerable.Range(0, x.Length).ToArray(), false));
            var before = Oracle.Check(input, WithoutTheChainRule(input), new OracleExpect { Milestone = Milestone.M3 });
            // (the tip's dropped point takes its edges' chains past a hot pixel they contact: ChainSkipsHotPixel as well)
            Assert.Equal(new[] { Violation.VertexUnused, Violation.ChainSkipsHotPixel }, before.Violations.Select(v => v.Kind).Distinct().ToArray());
            Assert.Equal(new[] { ((System.Numerics.BigInteger)16, (System.Numerics.BigInteger)11) }, before.RestorePixels.ToArray());
            var now = Oracle.Check(input, new QualityMesh2Candidate().Run(input), new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(now.Ok, now.ToString());
            Assert.Equal(1, now.CollapsedPoints);
        }

        /// <summary>
        /// (iii) counts only pieces that need a rerouted stretch: the star (11, 9.3), (8.4, 14.4), (12.1, 6.9), (11.3, 7.6) at M3 (20°, the
        /// refinement of before the fix)
        /// has a full image of one edge rerouted near (8, 14) and an input-only image (8, 14), (11, 9), (11, 8), (12, 7); its excused
        /// piece is crossed on the identical links (11, 9) - (11, 8) - (12, 7) alone, so it is not counted (post-review of (ii'), S3: the
        /// count was 1 when any stretch of the image differed). The ring collapses entirely in snapping, so the mesher now leaves the
        /// domain empty (QualityMesh2CollapsedRingDomainTests); the mesh the oracle judges here is the one that refinement made of the
        /// ring's hull before that fix, kept as text
        /// </summary>
        [Fact]
        public void Oracle_DoesNotCountExcusesOnStretchesNotRerouted()
        {
            var input = new Mesh2Input { X = new[] { 11, 8.4, 12.1, 11.3 }, Y = new[] { 9.3, 14.4, 6.9, 7.6 }, SnapTolerance = 1, MinAngleDeg = 20, SteinerLimit = 5000 };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            Assert.Equal(Mesh2Status.Empty, WithoutTheChainRule(input).Status);
            var o = TextFormat.ReadOutput(HullMeshOfACollapsedRing, out _);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            Assert.Equal(1, report.CollapsedSegments);
            Assert.Equal(1, report.CollapsedPoints);
            Assert.Equal(0, report.CollapsedViaRefinement);
        }

        /// <summary> the mesh of the star above as refinement made it before an input whose outer rings all collapse had an empty domain
        /// (the refinement of before #360's chain rule) </summary>
        const string HullMeshOfACollapsedRing = ""
            + "mesh2-output 1\n"
            + "producer g3-quality\n"
            + "status Success\n"
            + "vertices 8\n"
            + "0x4026000000000000 0x4022000000000000\n"
            + "0x4020000000000000 0x402c000000000000\n"
            + "0x4028000000000000 0x401c000000000000\n"
            + "0x4026000000000000 0x4020000000000000\n"
            + "0x4024000000000000 0x4022000000000000\n"
            + "0x4024000000000000 0x4028000000000000\n"
            + "0x4022000000000000 0x4028000000000000\n"
            + "0x4022000000000000 0x402c000000000000\n"
            + "triangles 5\n"
            + "0 4 3\n"
            + "0 5 4\n"
            + "5 7 6\n"
            + "4 5 6\n"
            + "1 6 7\n"
            + "subsegments 7\n"
            + "4 3 0\n"
            + "3 0 0\n"
            + "0 5 0\n"
            + "5 7 0\n"
            + "6 4 0\n"
            + "7 1 0\n"
            + "1 6 0\n"
            + "map 4 0 1 2 3\n"
            + "labels 5 0 0 0 0 0\n"
            + "bad 2 1 3\n"
            + "steiner_limit_reached 0\n"
            + "end\n";

        /// <summary>
        /// (iii) for segment pieces: seed 1742 of <see cref="StarPolygonFuzz"/> at M3 (the same mesh with and without the mesher's rule that
        /// keeps chains apart) is accepted with 2 segment pieces and 2 points on
        /// collapsed parts, and 3 excuses that need a stretch output vertices rerouted, so at least one segment piece's (a piece is counted
        /// only when its chain search fails without the rerouted stretches; post-review of (ii'), S2 and S3). Correct by the measurement
        /// with the restore pixels too. Counts exact, so a change shows
        /// </summary>
        [Fact]
        public void Oracle_CountsSegmentExcusesReroutedByOutputVertices()
        {
            var input = StarPolygonFuzz.Make(1742);
            var o = new QualityMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            Assert.Equal(2, report.CollapsedSegments);
            Assert.Equal(2, report.CollapsedPoints);
