using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Q17: a domain narrower than a pixel, which snap rounding collapses. A zigzag polyline 7 mm wide and 10 m long on a grid of 1 cm, its convex hull the domain.
    /// Snapping puts every vertex at a pixel centre, the hull chains and the polyline's chains share them, and parts of the domain
    /// collapse: corners in no triangle, segments with no chain there. Owner decisions (spec Q17): a part that snap rounding of the
    /// input collapses may collapse, and the oracle accepts what is missing only there (O-H5, 2026-11-02); the refinement must not
    /// collapse what the rounding of the input keeps (rule (ii'), 2026-11-03). Snapped alone and refined, the zigzags are accepted: the
    /// refinement puts no vertex where two chains of the input's image pass apart (the mesher's bugfix; before it the refined cases were
    /// pinned as known INVALID, and they fail against the library without it).
    /// </summary>
    public class QualityMesh2CollapsedPartsTests
    {
        /// <summary> the zigzag at slope 0.3 (six points) or 1.1 (eight points), offsets of 3.5 mm to either side, steps of 2 m </summary>
        internal static Mesh2Input Zigzag(int which, double? angle)
        {
            var input = which == 0
                ? new Mesh2Input {
                    X = new[] { 1000.0010343207233, 1001.9096386575279, 1003.8223802772258, 1005.7309846140304, 1007.6437262337281, 1009.5523305705327 },
                    Y = new[] { 499.99665632228806, 500.5943840910346, 501.1787371489334, 501.77646491767996, 502.36081797557875, 502.95854574432536 } }
                : new Mesh2Input {
                    X = new[] { 1000.0031192257602, 1000.9040730170909, 1001.8175037114626, 1002.7184575027933, 1003.6318881971648, 1004.5328419884955, 1005.4462726828672, 1006.3472264741979 },
                    Y = new[] { 499.998412413575, 501.78400230654785, 503.5632418538207, 505.3488317467936, 507.1280712940665, 508.91366118703934, 510.6929007343122, 512.478490627285 } };
            for (int i = 0; i + 1 < input.Count; ++i) input.Segments.Add(new SegmentInput(i, i + 1));
            input.SnapTolerance = 0.01; input.MinAngleDeg = angle; input.SteinerLimit = 50000;
            return input;
        }

        /// <summary> snapping alone (M2): the collapsed parts are accepted (O-H5 on the snap-rounded images) </summary>
        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        public void DomainNarrowerThanAPixel_SnappedCollapseIsAccepted(int which)
        {
            var input = Zigzag(which, null);
            var o = new ConstrainedDelaunayMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(report.Ok, report.ToString());
        }

        /// <summary>
        /// with refinement (M3) the mesher keeps what the rounding of the input keeps (owner decision 2026-11-03): no grid point of
        /// refinement brings together two chains of the input's image that are apart there. Before the fix it pinched 23.5 px² (z0) and
        /// 169 px² (z1) of the band 0.7 pixel wide that the input's rounding keeps (z0: 3 SegmentMissing and 1 VertexUnused, z1: 5
        /// SegmentMissing). Accepted, with exactly the excuses of the input's own collapse
        /// </summary>
        [Theory]
        [InlineData(0, 0.0, 2, 1)]
        [InlineData(0, 20.0, 2, 1)]
        [InlineData(1, 0.0, 1, 0)]
        [InlineData(1, 20.0, 1, 0)]
        public void DomainNarrowerThanAPixel_RefinementKeepsWhatRoundingKeeps(int which, double angle, int segmentsExcused, int pointsExcused)
        {
            var input = Zigzag(which, angle);
            var o = new QualityMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            Assert.Equal(segmentsExcused, report.CollapsedSegments);
            Assert.Equal(pointsExcused, report.CollapsedPoints);
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        /// <summary>
        /// the same under every similarity: snapped alone and refined, the oracle accepts the mesh in every frame; refined, the 2^k scales
        /// give the same mesh bit for bit and the same excuses
        /// </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void DomainNarrowerThanAPixel_Invariance(string name)
        {
            var s = Similarity.ByName(name);
            Mesh2Input Moved(Mesh2Input plain)
            {
                var moved = Zigzag(0, plain.MinAngleDeg);
                for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
                moved.SnapTolerance = plain.SnapTolerance * s.Scale;
                return moved;
            }
            var snapped = Moved(Zigzag(0, null));
            var m2 = new ConstrainedDelaunayMesh2Candidate().Run(snapped);
            Assert.Equal(Mesh2Status.Success, m2.Status);
            var report = Oracle.Check(snapped, m2, new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(report.Ok, name + ": " + report);
            var refined = Moved(Zigzag(0, 20));
            var m3 = new QualityMesh2Candidate().Run(refined);
            Assert.Equal(Mesh2Status.Success, m3.Status);
            var refinedOk = Oracle.Check(refined, m3, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(refinedOk.Ok, name + " (refined): " + refinedOk);
            if (s.IsExact) {
                var plain = Zigzag(0, 20);
                var a = new QualityMesh2Candidate().Run(plain);
                var b = m3;
                // the oracle's verdict too: the same violations and excuses at every 2^k scale
                var plainReport = Oracle.Check(plain, a, new OracleExpect { Milestone = Milestone.M3 });
                var refinedReport = Oracle.Check(refined, m3, new OracleExpect { Milestone = Milestone.M3 });
                Assert.Equal(plainReport.Violations.Select(v => v.Kind), refinedReport.Violations.Select(v => v.Kind));
                Assert.Equal(plainReport.CollapsedSegments, refinedReport.CollapsedSegments);
                Assert.Equal(plainReport.CollapsedPoints, refinedReport.CollapsedPoints);
                Assert.Equal(plainReport.CollapsedViaRefinement, refinedReport.CollapsedViaRefinement);
                Assert.Equal(a.VX.Select(v => v * s.Scale), b.VX);
                Assert.Equal(a.VY.Select(v => v * s.Scale), b.VY);
                Assert.Equal(a.Triangles.SelectMany(t => t), b.Triangles.SelectMany(t => t));
            }
        }

        /// <summary> one mesher, two computes: the same mesh </summary>
        [Fact]
        public void DomainNarrowerThanAPixel_Reuse()
        {
            var c = ConstrainedDelaunayMesh2Candidate.Convert(Zigzag(0, 20));
            var mesher = new QualityMesh2 { MinAngle = 20, SnapTolerance = 0.01, SteinerLimit = 50000, Conforming = true };
            var a = mesher.Compute(c); var b = mesher.Compute(c);
            Assert.Equal(a.Mesh.Vertices, b.Mesh.Vertices);
            Assert.Equal(a.Mesh.Triangles, b.Mesh.Triangles);
            // the collapse diagnostics too (a snapshot left over from the first compute would change the counts)
            Assert.Equal(a.Diagnostics ?? new string[0], b.Diagnostics ?? new string[0]);
            Assert.Contains(a.Diagnostics ?? new string[0], l => l.Contains("parts that snapping collapsed"));
        }
    }
}

using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The library members of the fix for an input whose outer rings all collapse in snapping (QualityMesh2CollapsedRingDomainTests has
    /// the behaviour): SnapRounding2.OuterRingsCollapsed and the diagnostic that says why the domain is empty.
    /// </summary>
    public class QualityMesh2CollapsedRingDomainLibraryTests
    {
        static Mesh2Input ThinRing(bool square, bool squareIsHole = false) => QualityMesh2CollapsedRingDomainTests.ThinRing(square, squareIsHole);

        /// <summary> the flag itself: true only when the input has outer rings and all of them collapse </summary>
        [Theory]
        [InlineData("none", false)]
        [InlineData("holes only", false)]
        [InlineData("one of two", false)]
        [InlineData("all", true)]
        [InlineData("all, a hole survives", true)]
        public void SnapRounding_OuterRingsCollapsed(string which, bool expected)
        {
            var input = which == "one of two" ? ThinRing(true) : which == "all, a hole survives" ? ThinRing(true, true) : ThinRing(false);
            if (which == "none") input.Rings.Clear();
            if (which == "holes only") input.Rings[0] = new RingInput(input.Rings[0].Vertices, true);
            var snap = SnapRounding2.Apply(ConstrainedDelaunayMesh2Candidate.Convert(input), 1, System.Threading.CancellationToken.None);
            Assert.Equal(expected, snap.OuterRingsCollapsed);
            Assert.Equal(expected, snap.Diagnostics.Any(d => d.Contains("every outer ring collapsed")));
        }

        /// <summary> the diagnostics say why: the ring collapsed </summary>
        [Fact]
        public void ThinRing_Collapses_Reported()
        {
            var lib = ConstrainedDelaunayMesh2Candidate.Convert(ThinRing(false));
            var r = new QualityMesh2 { MinAngle = 20, SnapTolerance = 1 }.Compute(lib);
            Assert.Equal(Triangulation2Status.Empty, r.Status);
            Assert.Contains(r.Diagnostics, d => d.Contains("ring 0 collapsed below the tolerance"));
            Assert.Contains(r.Diagnostics, d => d.Contains("every outer ring collapsed below the tolerance; the domain is empty"));
            var c = new ConstrainedDelaunayMesh2 { SnapTolerance = 1 }.Compute(lib);
            Assert.Equal(Triangulation2Status.Empty, c.Status);
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// An input whose outer rings all collapse in snapping (D14) has an empty domain, not the convex hull (D13 is the rule for input
    /// without outer rings): snapping keeps the collapsed rings' pieces as segments, and with no outer ring left the builder took the hull
    /// of all points for the domain and meshed free points outside the rings (star polygon fuzz seeds 37, 41, 1019, 1052, 1331, 2200,
    /// 2248: TriangleOutsideDomain and SubsegmentUnsourced; found again by the lens fuzz of #370). Only the library's existing API
    /// here, so that these tests run against the library before the fix (they fail there); the flag and the diagnostic are tested in
    /// QualityMesh2CollapsedRingDomainLibraryTests.
    /// </summary>
    public class QualityMesh2CollapsedRingDomainTests
    {
        static Mesh2Output Run(Mesh2Input input, string mode)
        {
            if (mode == "M2") { input.MinAngleDeg = null; return new ConstrainedDelaunayMesh2Candidate().Run(input); }
            if (mode == "M3cq") input.ConstrainedQuality = true;
            return new QualityMesh2Candidate().Run(input);
        }

        static OracleReport Judge(Mesh2Input input, Mesh2Output o, string mode)
            => Oracle.Check(input, o, new OracleExpect { Milestone = mode == "M2" ? Milestone.M2 : Milestone.M3 });

        public static IEnumerable<object[]> Seeds()
        {
            foreach (int seed in QualityMesh2KeepsChainsApartTests.EmptyDomain)
                foreach (var mode in new[] { "M2", "M3", "M3cq" }) yield return new object[] { seed, mode };
        }

        /// <summary> the fuzz seeds: empty, accepted by the oracle, in every mode </summary>
        [Theory]
        [MemberData(nameof(Seeds))]
        public void StarFuzz_CollapsedRing_EmptyDomain(int seed, string mode)
        {
            var input = StarPolygonFuzz.Make(seed);
            var o = Run(input, mode);
            Assert.Equal(Mesh2Status.Empty, o.Status);
            Assert.Empty(o.Triangles);
            var report = Judge(input, o, mode);
            Assert.True(report.Ok, report.ToString());
        }

        /// <summary> a ring 0.1 wide along y = 0.4 (snapped to the grid line y = 0 at pixel 1) and a free point well outside it </summary>
        internal static Mesh2Input ThinRing(bool square, bool squareIsHole = false)
        {
            var x = new List<double> { 0.2, 10.2, 20.2, 10.2, 6, 3 }; var y = new List<double> { 0.4, 0.45, 0.4, 0.35, 8, 5 };
            var input = new Mesh2Input { SnapTolerance = 1, MinAngleDeg = 20, SteinerLimit = 5000 };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            if (square) {
                // a second outer ring that survives, the free point (6, 8) inside it and (3, 5) outside both
                x.AddRange(new double[] { 4, 9, 9, 4 }); y.AddRange(new double[] { 6, 6, 11, 11 });
                input.Rings.Add(new RingInput(new[] { 6, 7, 8, 9 }, squareIsHole));
            }
            input.X = x.ToArray(); input.Y = y.ToArray();
            return input;
        }

        [Theory]
        [InlineData("M2")]
        [InlineData("M3")]
        [InlineData("M3cq")]
        public void ThinRing_Collapses_DomainIsEmpty(string mode)
        {
            var input = ThinRing(false);
            var o = Run(input, mode);
            Assert.Equal(Mesh2Status.Empty, o.Status);
            Assert.Empty(o.Triangles);
            var report = Judge(input, o, mode);
            Assert.True(report.Ok, report.ToString());
        }

        /// <summary> the outer ring collapses, a hole ring survives: still empty (a surviving hole is no outer ring) </summary>
        [Theory]
        [InlineData("M2")]
        [InlineData("M3")]
        [InlineData("M3cq")]
        public void OuterCollapses_HoleSurvives_DomainIsEmpty(string mode)
        {
            var input = ThinRing(true, true);
            var o = Run(input, mode);
            Assert.Equal(Mesh2Status.Empty, o.Status);
            Assert.Empty(o.Triangles);
            var report = Judge(input, o, mode);
            Assert.True(report.Ok, report.ToString());
        }

        /// <summary> control: one outer ring collapses, another survives; the domain is the survivor (unchanged by the fix), and a free point
        /// outside both stays outside </summary>
        [Theory]
        [InlineData("M2")]
        [InlineData("M3")]
        [InlineData("M3cq")]
        public void OneOfTwoRingsCollapses_DomainIsTheOther(string mode)
        {
            var input = ThinRing(true);
            var o = Run(input, mode);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Judge(input, o, mode);
            Assert.True(report.Ok, report.ToString());
            Assert.All(o.Triangles, t => Assert.True(t.All(v => o.VX[v] >= 4 && o.VX[v] <= 9 && o.VY[v] >= 6 && o.VY[v] <= 11)));
        }

        /// <summary> control: without rings the domain is still the hull (D13) </summary>
        [Fact]
        public void NoRings_HullDomain()
        {
            var input = ThinRing(false);
            input.Rings.Clear();
            var o = Run(input, "M3");
            Assert.Equal(Mesh2Status.Success, o.Status);
            Assert.NotEmpty(o.Triangles);
            Assert.True(Judge(input, o, "M3").Ok);
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        /// <summary> in every frame the oracle accepts the mesh; at the 2^k scales the ring collapses and the domain is empty there too </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void ThinRing_Invariance(string name)
        {
            var s = Similarity.ByName(name);
            var plain = ThinRing(false);
            var moved = ThinRing(false);
            moved.SnapTolerance = plain.SnapTolerance * s.Scale;
            for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
            var o = Run(moved, "M3");
            Assert.True(Judge(moved, o, "M3").Ok, name);
            if (s.IsExact) {
                Assert.Equal(Mesh2Status.Empty, o.Status);
                Assert.Empty(o.Triangles);
            }
        }

        /// <summary> reuse: one mesher instance twice on the input that collapses, and then on one that does not </summary>
        [Fact]
        public void Reuse_SameInstance()
        {
            var mesher = new QualityMesh2 { MinAngle = 20, SnapTolerance = 1 };
            var collapsing = ConstrainedDelaunayMesh2Candidate.Convert(ThinRing(false));
            var surviving = ConstrainedDelaunayMesh2Candidate.Convert(ThinRing(true));
            Assert.Equal(Triangulation2Status.Empty, mesher.Compute(collapsing).Status);
            var a = mesher.Compute(surviving);
            Assert.Equal(Triangulation2Status.Empty, mesher.Compute(collapsing).Status);
            var b = mesher.Compute(surviving);
            Assert.Equal(Triangulation2Status.Success, a.Status);
            Assert.Equal(a.Mesh.Vertices, b.Mesh.Vertices);
            Assert.Equal(a.Mesh.Triangles, b.Mesh.Triangles);
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Conforming refinement (O2) with a constraint inside a hole: a piece of an input segment that crosses a hole lies between a hole
    /// edge and a vertex on the opposite hole edge. Encroachment counts every triangle with Conforming, but only the domain's
    /// constrained edges were queued, so the piece inside the hole was never looked at; encroached and left as it was, it hid the vertex
    /// across the hole from the hole edge, and the mesh was not Delaunay across the hole (NotDelaunayGlobal). Found with the grid fuzz
    /// with holes in M3 (seeds 551 at 30 degrees and 1051 at 25), reduced to one segment and two loose points.
    /// </summary>
    public class QualityMesh2ConformingHoleTests
    {
        /// <summary> a 16 square with two triangular holes, a segment across the second hole, two loose points, on a grid of 1/4 </summary>
        static Mesh2Input Case(double angle)
        {
            var input = new Mesh2Input {
                X = new[] { 0, 16, 16, 0, 6, 9, 7, 10, 13, 12, 11.453125, 11.78125, 13.921875, 10.921875 },
                Y = new[] { 0, 0, 16, 16, 6, 6.5, 9, 10, 11, 14, 13.234375, 14.375, 5.140625, 6.90625 },
                SnapTolerance = 0.25, MinAngleDeg = angle, SteinerLimit = 50000 };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            input.Rings.Add(new RingInput(new[] { 4, 5, 6 }, true));
            input.Rings.Add(new RingInput(new[] { 7, 8, 9 }, true));
            input.Segments.Add(new SegmentInput(11, 12));
            return input;
        }

        [Theory]
        [InlineData(20.0)]
        [InlineData(25.0)]
        [InlineData(30.0)]
        public void SegmentInsideAHole_IsSplit_TheMeshIsDelaunayAcrossTheHole(double angle)
        {
            var input = Case(angle);
            QualityMesh2.Refiner.CheckTagsForTests = true;
            Mesh2Output o;
            try { o = new QualityMesh2Candidate().Run(input); }
            finally { QualityMesh2.Refiner.CheckTagsForTests = false; }
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        /// <summary> the same under every similarity: 2^k scales give the same mesh bit for bit, the others pass the oracle </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void SegmentInsideAHole_Invariance(string name)
        {
            var s = Similarity.ByName(name);
            var plain = Case(30);
            var moved = Case(30);
            for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
            moved.SnapTolerance = plain.SnapTolerance * s.Scale;
            var b = new QualityMesh2Candidate().Run(moved);
            Assert.Equal(Mesh2Status.Success, b.Status);
            var report = Oracle.Check(moved, b, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, name + ": " + report);
            if (s.IsExact) {
                var a = new QualityMesh2Candidate().Run(plain);
                Assert.Equal(a.VX.Select(v => v * s.Scale), b.VX);
                Assert.Equal(a.VY.Select(v => v * s.Scale), b.VY);
                Assert.Equal(a.Triangles.SelectMany(t => t), b.Triangles.SelectMany(t => t));
            }
        }

        /// <summary> one mesher, two computes: the same mesh </summary>
        [Fact]
        public void SegmentInsideAHole_Reuse()
        {
            var c = ConstrainedDelaunayMesh2Candidate.Convert(Case(30));
            var mesher = new QualityMesh2 { MinAngle = 30, SnapTolerance = 0.25, SteinerLimit = 50000, Conforming = true };
            var first = mesher.Compute(c).Mesh; var second = mesher.Compute(c).Mesh;
            Assert.Equal(first.Vertices, second.Vertices);
            Assert.Equal(first.Triangles, second.Triangles);
        }
    }
}

using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary> QualityMesh2.Refiner.ExactlyWithin, the test a split point of a piece shorter than 2^-1026 must pass (exactly on its
    /// source, strictly between the piece's ends), at subnormal magnitudes where products underflow </summary>
    public class QualityMesh2ExactlyWithinTests
    {
        [Fact]
        public void TinyPieces_AreSplitOnlyExactly()
        {
            // a segment whose midpoint is exact (even integer coordinates) is still split; the refiner's check accepts exactly the
            // points on the piece, strictly between its ends
            double t = double.Epsilon;
            var a = new Vector2d(0, 0); var b = new Vector2d(4 * t, 2 * t);
            Assert.True(QualityMesh2.Refiner.ExactlyWithin(a, b, a, b, new Vector2d(2 * t, t)));
            Assert.False(QualityMesh2.Refiner.ExactlyWithin(a, b, a, b, new Vector2d(2 * t, 2 * t)));
            Assert.False(QualityMesh2.Refiner.ExactlyWithin(a, b, a, b, a));
            Assert.False(QualityMesh2.Refiner.ExactlyWithin(a, b, a, b, new Vector2d(6 * t, 3 * t)));
            var v = new Vector2d(0, 0); var w = new Vector2d(0, 4 * t);
            Assert.True(QualityMesh2.Refiner.ExactlyWithin(v, w, v, w, new Vector2d(0, 3 * t)));
            Assert.False(QualityMesh2.Refiner.ExactlyWithin(v, w, v, w, new Vector2d(0, -t)));
            // ends rounded next to ab (a crossing): p on ab between them counts, p on their line but off ab does not
            var u2 = new Vector2d(t, 0); var w2 = new Vector2d(3 * t, 2 * t);
            Assert.True(QualityMesh2.Refiner.ExactlyWithin(a, b, u2, w2, new Vector2d(2 * t, t)));
            Assert.False(QualityMesh2.Refiner.ExactlyWithin(a, b, u2, w2, new Vector2d(2 * t, 1 * t + t)));
            // a steep piece: compared along y, in which its ends differ most
            var sa = new Vector2d(0, 0); var sb = new Vector2d(t, 8 * t);
            Assert.False(QualityMesh2.Refiner.ExactlyWithin(sa, sb, sa, sb, new Vector2d(t, 8 * t)));
            Assert.True(QualityMesh2.Refiner.ExactlyWithin(new Vector2d(0, 0), new Vector2d(2 * t, 8 * t), new Vector2d(0, 0), new Vector2d(2 * t, 8 * t), new Vector2d(t, 4 * t)));
            // a steep piece with ends next to ab: p is between them along y, not along x (where it shares an end's x)
            Assert.True(QualityMesh2.Refiner.ExactlyWithin(new Vector2d(0, 0), new Vector2d(2 * t, 16 * t), new Vector2d(t, 2 * t), new Vector2d(2 * t, 14 * t), new Vector2d(t, 8 * t)));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The grading levers of <see cref="QualityMesh2"/> (MESHING2D_GRADING.md) through their switches: the worst-first queue and the
    /// choice of the split point among candidates (in the petal of the shortest edge, or step 1's on its bisector), with its floor (no chosen point nearer to the mesh than the default
    /// point); on the snap grid; invariance, reuse and determinism.
    /// </summary>
    public class QualityMesh2GradingLibraryTests
    {
        static Mesh2Output Run(Mesh2Input input, bool? worstFirst = null, bool? best = null, Action<double, double, bool, Vector2d> picked = null)
        {
            QualityMesh2.Refiner.WorstFirstForBenchmarks = worstFirst;
            QualityMesh2.Refiner.BestCandidateForBenchmarks = best;
            QualityMesh2.Refiner.PickedForTests = picked;
            // (the reused angle tests of a choice checked against fresh ones, throws)
            QualityMesh2.Refiner.CheckScoresForTests = true;
            try { return new QualityMesh2Candidate().Run(input); }
            finally {
                QualityMesh2.Refiner.WorstFirstForBenchmarks = null; QualityMesh2.Refiner.BestCandidateForBenchmarks = null; QualityMesh2.Refiner.PickedForTests = null;
                QualityMesh2.Refiner.CheckScoresForTests = false;
            }
        }

        static OracleReport Judge(Mesh2Input input, Mesh2Output output) => Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 });

        static bool Same(Mesh2Output a, Mesh2Output b) => a.VX.SequenceEqual(b.VX) && a.VY.SequenceEqual(b.VY) && a.Triangles.SelectMany(t => t).SequenceEqual(b.Triangles.SelectMany(t => t));

        static Mesh2Input Fuzz(int seed, double angle, bool constrainedQuality, double snap = 0)
        {
            var input = QualityMesh2LensDeletionTests.Fuzz(seed, angle, snap);
            input.ConstrainedQuality = constrainedQuality;
            return input;
        }

        /// <summary>
        /// each lever alone and both: every mesh passes the oracle, and each saves triangles summed over the seeds against neither (the
        /// defaults are both)
        /// </summary>
        [Theory]
        [InlineData(20.0, false)]
        [InlineData(25.0, true)]
        [InlineData(30.0, false)]
        public void Fuzz_EachLeverSavesTriangles_AndEveryMeshPasses(double angle, bool constrainedQuality)
        {
            var totals = new long[4];
            for (int seed = 0; seed < 24; ++seed) {
                var input = Fuzz(6000 + seed, angle, constrainedQuality);
                var variants = new[] { Run(input, false, false), Run(input, true, false), Run(input, false, true), Run(input) };
                for (int i = 0; i < 4; ++i) {
                    Assert.Equal(Mesh2Status.Success, variants[i].Status);
                    Assert.False(variants[i].SteinerLimitReached, "seed " + seed);
                    var report = Judge(input, variants[i]);
                    Assert.True(report.Ok, "seed " + seed + " variant " + i + ": " + report);
                    totals[i] += variants[i].Triangles.Length;
                }
                Assert.True(Same(variants[3], Run(input, true, true)), "the defaults are not both levers");
            }
            Assert.True(totals[1] < totals[0], "worst first: " + totals[1] + " against " + totals[0]);
            Assert.True(totals[2] < totals[0], "best candidate: " + totals[2] + " against " + totals[0]);
            Assert.True(totals[3] < totals[0], "both: " + totals[3] + " against " + totals[0]);
        }

        /// <summary>
        /// the petal's candidates (grading step 2, the default) against step 1's on the bisector: every mesh passes the oracle, in
        /// both modes and on the snap grid, and the petal saves triangles summed over the seeds
        /// </summary>
        [Theory]
        [InlineData(20.0, false, 0.0)]
        [InlineData(30.0, true, 0.0)]
        [InlineData(25.0, false, 0.25)]
        public void Petal_SavesTriangles_AndEveryMeshPasses(double angle, bool constrainedQuality, double snap)
        {
            long bisector = 0, petal = 0;
            for (int seed = 0; seed < 24; ++seed) {
                var input = Fuzz(6300 + seed, angle, constrainedQuality, snap);
                Mesh2Output withPetal = Run(input), onBisector;
                QualityMesh2.Refiner.PetalForBenchmarks = false;
                try { onBisector = Run(input); } finally { QualityMesh2.Refiner.PetalForBenchmarks = null; }
                foreach (var o in new[] { withPetal, onBisector }) {
                    Assert.Equal(Mesh2Status.Success, o.Status);
                    Assert.False(o.SteinerLimitReached, "seed " + seed);
                    var report = Judge(input, o);
                    Assert.True(report.Ok, "seed " + seed + ": " + report);
                }
                bisector += onBisector.Triangles.Length; petal += withPetal.Triangles.Length;
            }
            Assert.True(petal < bisector, "the petal: " + petal + " against " + bisector + " on the bisector");
        }

        /// <summary>
        /// the bound in Score (a candidate that removes fewer bad triangles than the best score so far is refused without its fan) is
        /// exact: with it switched off every mesh and every pick are the same, over the fuzz in both modes and on the grid (a bound
        /// that also refused an equal score would lose the tie to the larger radius: such ties occur in these seeds)
        /// </summary>
        [Theory]
        [InlineData(20.0, false, 0.0)]
        [InlineData(30.0, true, 0.0)]
        [InlineData(25.0, false, 0.25)]
        [InlineData(30.0, false, 0.0)]
        public void ScoreBound_LeavesEveryChoiceUnchanged(double angle, bool constrainedQuality, double snap)
        {
            for (int seed = 0; seed < 24; ++seed) {
                var input = Fuzz(6400 + seed, angle, constrainedQuality, snap);
                var withBound = new List<(double, double, bool, Vector2d)>();
                var o = Run(input, picked: (f, r, other, p) => withBound.Add((f, r, other, p)));
                var withoutBound = new List<(double, double, bool, Vector2d)>();
                QualityMesh2.Refiner.ScoreBoundOffForTests = true;
                Mesh2Output u;
                try { u = Run(input, picked: (f, r, other, p) => withoutBound.Add((f, r, other, p))); }
                finally { QualityMesh2.Refiner.ScoreBoundOffForTests = false; }
                Assert.True(Same(o, u), "seed " + seed + ": the meshes differ");
                Assert.Equal(withoutBound, withBound);
            }
        }

        /// <summary>
        /// the floor: a chosen point is never nearer to the mesh than the default point (its insertion radius at least the default's),
        /// a choice is made only where the default point would be inserted (its radius is positive), points other than the default
        /// are chosen, and the chosen points are the points inserted (on the grid already rounded); on the grid as well
        /// </summary>
        [Theory]
        [InlineData(0.0)]
        [InlineData(0.25)]
        public void Picks_KeepTheFloor(double snap)
        {
            int picks = 0, others = 0, inOutput = 0;
            for (int seed = 0; seed < 40; ++seed) {
                var input = Fuzz(6100 + seed, new[] { 20.0, 25, 30 }[seed % 3], seed % 2 == 0, snap);
                var chosen = new List<Vector2d>();
                var o = Run(input, picked: (floor, radius, other, p) => {
                    Assert.True(floor > 0, "the default point does not count: " + floor);
                    Assert.True(radius >= floor, radius + " below the floor " + floor);
                    ++picks; if (other) ++others;
                    chosen.Add(p);
                });
                Assert.Equal(Mesh2Status.Success, o.Status);
                // the point chosen is the point inserted (on the grid: scored where it is inserted, at its pixel centre, and refused
                // where a constraint crosses its pixel). Without lenses nothing is deleted, so every chosen point is in the output; in
                // the constrained quality mode lens deletion may remove some again
                var vertices = new HashSet<Vector2d>(Enumerable.Range(0, o.VX.Length).Select(i => new Vector2d(o.VX[i], o.VY[i])));
                int found = chosen.Count(vertices.Contains);
                if (!input.ConstrainedQuality) Assert.True(found == chosen.Count, "seed " + seed + ": " + (chosen.Count - found) + " chosen points not inserted");
                inOutput += found;
            }
            Assert.True(picks > 0 && others > 0, picks + " choices, " + others + " not the default point");
            Assert.True(2 * inOutput > picks, inOutput + " of " + picks + " chosen points in the output");
        }

        /// <summary>
        /// on the grid a candidate whose pixel a constraint crosses does not count (the insertion would refuse it and fall back to the
        /// circumcentre): every chosen point is inserted. Found by a search over 27 000 fuzz runs for a choice that is refused; this is
        /// the one input where it happens when the pixel check is left out
        /// </summary>
        [Theory]
        [InlineData(97, 0.25, 30.0)]
        public void Grid_NoChoiceInAConstrainedPixel(int seed, double snap, double angle)
        {
            var input = QualityMesh2LensDeletionTests.Fuzz(seed, angle, snap);
            input.ConstrainedQuality = false;
            var chosen = new List<Vector2d>();
            var o = Run(input, picked: (f, r, other, p) => chosen.Add(p));
            Assert.Equal(Mesh2Status.Success, o.Status);
            var vertices = new HashSet<Vector2d>(Enumerable.Range(0, o.VX.Length).Select(i => new Vector2d(o.VX[i], o.VY[i])));
            Assert.True(chosen.Count > 0);
            Assert.All(chosen, p => Assert.Contains(p, vertices));
            Assert.True(Judge(input, o).Ok);
        }

        /// <summary>
        /// on the snap grid: every mesh passes the oracle (every vertex of refinement on a pixel centre, no chains coinciding or pinched:
        /// the oracle's OffGrid, RefinementCoincidence and RefinementPinch), and the levers change meshes there
        /// </summary>
        [Fact]
        public void GridFuzz_PassesTheOracle()
        {
            int differ = 0;
            for (int seed = 0; seed < 40; ++seed) {
                var input = Fuzz(6200 + seed, new[] { 20.0, 25, 30 }[seed % 3], seed % 2 == 0, new[] { 0.25, 0.5, 0.3, 1.0 / 3, 0.125 }[seed % 5]);
                var o = Run(input);
                Assert.Equal(Mesh2Status.Success, o.Status);
                var report = Judge(input, o);
                Assert.True(report.Ok, "seed " + seed + ": " + report);
                if (!Same(o, Run(input, false, false))) ++differ;
            }
            Assert.True(differ > 0, "the levers changed no mesh on the grid");
        }

        /// <summary> the star polygon fuzz on the grid in both modes at 20 and 25 degrees: no seed rejected that is accepted without the levers </summary>
        [Fact]
        public void StarFuzz_NoNewRejections()
        {
            var worse = new List<int>();
            for (int seed = 0; seed < 300; ++seed) {
                var input = StarPolygonFuzz.Make(seed);
                input.ConstrainedQuality = seed % 3 == 0;
                input.MinAngleDeg = seed % 2 == 0 ? 20 : 25;
                var o = Run(input); var without = Run(input, false, false);
                bool ok = (o.Status == Mesh2Status.Success || o.Status == Mesh2Status.Empty) && Judge(input, o).Ok;
                bool okWithout = (without.Status == Mesh2Status.Success || without.Status == Mesh2Status.Empty) && Judge(input, without).Ok;
                if (okWithout && !ok) worse.Add(seed);
            }
            Assert.Empty(worse);
        }

        /// <summary> without an angle bound (size refinement only) neither lever is used: the meshes are those of the queue in order and the
        /// circumcentres (no triangle is below a bound of 0, so none is ordered or bad by its angle) </summary>
        [Fact]
        public void SizeOnly_Unchanged()
        {
            for (int seed = 0; seed < 12; ++seed) {
                var input = Fuzz(6300 + seed, 0, seed % 2 == 0);
                input.MinAngleDeg = 0; input.MaxArea = 0.5;
                var o = Run(input);
                Assert.Equal(Mesh2Status.Success, o.Status);
                Assert.True(o.Triangles.Length > 200, "seed " + seed + ": no size refinement");
                Assert.True(Same(o, Run(input, false, false)), "seed " + seed);
                Assert.True(Same(o, Run(input, true, true)), "seed " + seed);
            }
        }

        /// <summary> a candidate is rounded to the grid only when its pixel index fits (|coordinate| / W below 2^52, the bound of the exact
        /// circumcentre's pixel): the grid's rounding throws far beyond it (review of #375: a sliver's far bisector point) </summary>
        [Fact]
        public void RoundableOnGrid_GuardsTheRounding()
        {
            var grid = new SnapGrid(0.25);
            Assert.True(QualityMesh2.Refiner.RoundableOnGrid(grid, new Vector2d(1e6, -3)));
            Assert.True(QualityMesh2.Refiner.RoundableOnGrid(null, new Vector2d(1e30, 0)));
            Assert.False(QualityMesh2.Refiner.RoundableOnGrid(grid, new Vector2d(1e30, 0)));
            Assert.False(QualityMesh2.Refiner.RoundableOnGrid(grid, new Vector2d(0, -Math.Pow(2, 51))));   // 2^53 pixels of 1/4
            Assert.True(QualityMesh2.Refiner.RoundableOnGrid(grid, new Vector2d(0, Math.Pow(2, 49))));     // 2^51 pixels
            Assert.False(QualityMesh2.Refiner.RoundableOnGrid(grid, new Vector2d(double.NaN, 0)));
            Assert.False(QualityMesh2.Refiner.RoundableOnGrid(null, new Vector2d(2e70, 0)));
            Assert.ThrowsAny<Exception>(() => grid.Round(new Vector2d(1e30, 0)));   // what the guard keeps away
        }

        /// <summary> the benchmark counts chosen points apart from off-centres and circumcentres: as many as the choices of a point other
        /// than the default </summary>
        [Fact]
        public void Counts_ChosenPointsApart()
        {
            var input = Fuzz(6003, 25, false);
            var counts = new long[8];
            int others = 0;
            QualityMesh2.Refiner.CountsForBenchmarks = counts;
            try { Run(input, picked: (f, r, other, p) => { if (other) ++others; }); }
            finally { QualityMesh2.Refiner.CountsForBenchmarks = null; }
            Assert.True(others > 0);
            Assert.Equal(others, counts[7]);
        }

        // ------------------------------------------------------------ invariance, reuse, determinism

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        static Mesh2Input Scaled(Mesh2Input input, Func<double, double, Vector2d> map, double tolerance)
        {
            var moved = new Mesh2Input {
                X = (double[])input.X.Clone(), Y = (double[])input.Y.Clone(), MinAngleDeg = input.MinAngleDeg, SteinerLimit = input.SteinerLimit,
                ConstrainedQuality = input.ConstrainedQuality, SnapTolerance = tolerance,
            };
            moved.Rings.AddRange(input.Rings); moved.Segments.AddRange(input.Segments);
            for (int i = 0; i < input.Count; ++i) { var q = map(input.X[i], input.Y[i]); moved.X[i] = q.x; moved.Y[i] = q.y; }
            return moved;
        }

        [Theory]
        [MemberData(nameof(Similarities))]
        public void Similarity_WithTheLevers(string name)
        {
            var s = Similarity.ByName(name);
            foreach (bool cq in new[] { false, true }) {
                var plain = Fuzz(6003, 25, cq);
                var moved = Scaled(plain, (x, y) => { var q = s.Apply(new Vector3d(x, y, 0)); return new Vector2d(q.x, q.y); }, 0);
                var b = Run(moved);
                var report = Judge(moved, b);
                Assert.True(report.Ok, name + ": " + report);
                if (s.IsExact) {
                    int others = 0;
                    var a = Run(plain, picked: (f, r, other, p) => { if (other) ++others; });
                    Assert.True(others > 0, "no point other than the default chosen");
                    Assert.Equal(a.VX.Select(v => v * s.Scale), b.VX);
                    Assert.Equal(a.VY.Select(v => v * s.Scale), b.VY);
                    Assert.Equal(a.Triangles.SelectMany(t => t), b.Triangles.SelectMany(t => t));
                }
            }
        }

        /// <summary> scaled by 2^-500 and 2^500, with and without the grid: the same mesh bit for bit (the scores are computed in the
        /// triangle's frame scaled to unit size, so they neither underflow nor overflow) </summary>
        [Theory]
        [InlineData(-500, 0.0, false)]
        [InlineData(200, 0.0, false)]
        [InlineData(-500, 0.25, false)]
        [InlineData(200, 0.25, false)]
        [InlineData(-500, 0.0, true)]
        [InlineData(200, 0.25, true)]
        public void PowerOfTwoScale_IsBitIdentical(int exponent, double snap, bool constrainedQuality)
        {
            double f = Math.Pow(2, exponent);
            var plain = Fuzz(6004, 25, constrainedQuality, snap);
            var moved = Scaled(plain, (x, y) => new Vector2d(x * f, y * f), snap * f);
            var a = Run(plain); var b = Run(moved);
            Assert.Equal(Mesh2Status.Success, a.Status);
            Assert.Equal(a.VX.Select(v => v * f), b.VX);
            Assert.Equal(a.VY.Select(v => v * f), b.VY);
            Assert.Equal(a.Triangles.SelectMany(t => t), b.Triangles.SelectMany(t => t));
        }

        [Fact]
        public void Reuse_And_Parallel_RunsAreIdentical()
        {
            var mesher = new QualityMesh2 { MinAngle = 25, Conforming = false };
            var input = ConstrainedDelaunayMesh2Candidate.Convert(Fuzz(6003, 25, true));
            var first = mesher.Compute(input).Mesh;
            var results = new ConstrainedMesh2[8];
            Parallel.For(0, results.Length, i => results[i] = mesher.Compute(input).Mesh);
            foreach (var m in results.Concat(new[] { mesher.Compute(input).Mesh })) {
                Assert.Equal(first.Vertices, m.Vertices);
                Assert.Equal(first.Triangles, m.Triangles);
                Assert.Equal(first.BadTriangles, m.BadTriangles);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Grading of <see cref="QualityMesh2"/> with an angle bound: bad triangles are split worst first, and a triangle bad by its angle at
    /// the best of a few candidates (step 1: on the bisector of its shortest edge; step 2: in the edge's petal; MESHING2D_GRADING.md). These tests use only the API of before the
    /// change: on it they fail (more triangles), so they show the change. The switches, the floor, invariance and determinism are in
    /// <see cref="QualityMesh2GradingLibraryTests"/>.
    /// </summary>
    public class QualityMesh2GradingTests
    {
        /// <summary>
        /// the unit square with a cluster of three points 2^-20 apart at its centre (the shape of the reference case f-11/a): the mesh
        /// grades from the cluster out to the square over 20 octaves. Before the change 256 triangles (default) and 286 (constrained
        /// quality); with step 1 217 and 222, with step 2 215 and 220; the reference mesher 108
        /// </summary>
        internal static Mesh2Input Cluster(bool constrainedQuality)
        {
            double h = Math.Pow(2, -20);
            var input = new Mesh2Input {
                X = new[] { 0, 1, 1, 0, 0.5, 0.5 + h, 0.5 },
                Y = new[] { 0, 0, 1, 1, 0.5, 0.5, 0.5 + h },
                MinAngleDeg = 20, ConstrainedQuality = constrainedQuality,
            };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            return input;
        }

        [Theory]
        [InlineData(false, 235)]
        [InlineData(true, 235)]
        public void Cluster_GradesWithFewerTriangles(bool constrainedQuality, int most)
        {
            var input = Cluster(constrainedQuality);
            var o = new QualityMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            Assert.True(o.Triangles.Length <= most, o.Triangles.Length + " triangles, at most " + most + " expected");
        }

        /// <summary>
        /// the lens tests' fuzz (a square with a hole and random segments) at 25 and 30 degrees, both modes: every mesh passes the oracle,
        /// and the triangles summed over the seeds stay below the bound (the sums before and with the change next to each bound)
        /// </summary>
        [Theory]
        [InlineData(25.0, false, 6800)]     // before grading 7610, step 1 7126, step 2 (the petal) 6537
        [InlineData(30.0, false, 12000)]    // before 18113, step 1 14951, step 2 11272
        [InlineData(25.0, true, 4900)]      // before 5288, step 1 5053, step 2 4742
        [InlineData(30.0, true, 11800)]     // before 17794, step 1 14690, step 2 11092
        public void Fuzz_FewerTriangles(double angle, bool constrainedQuality, int most)
        {
            long total = 0;
            for (int seed = 0; seed < 24; ++seed) {
                var input = QualityMesh2LensDeletionTests.Fuzz(5000 + seed, angle);
                input.ConstrainedQuality = constrainedQuality;
                var o = new QualityMesh2Candidate().Run(input);
                Assert.Equal(Mesh2Status.Success, o.Status);
                var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
                Assert.True(report.Ok, "seed " + seed + ": " + report);
                total += o.Triangles.Length;
            }
            Assert.True(total <= most, total + " triangles, at most " + most + " expected");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// the parts of <see cref="QualityMesh2GridRerouteTests"/> that use the fix's own members (the sweep and the reroute counter), apart
    /// so that the cases themselves compile against the library without the fix and fail there
    /// </summary>
    public class QualityMesh2GridRerouteSweepTests
    {
        /// <summary>
        /// the reduced cases do take the path of a split onto a vertex already there, with the tag check after every operation (case 30 no
        /// longer does: its target was a vertex of a segment piece inside the hole, which the carve before refinement removes, T15; case
        /// 292 replaced it; 31 and 292 no longer do since a grid split may not reroute a piece onto another chain's edge, Q17: cases 60
        /// and 2384 replace them). Since the pinch rule (a split point is never another chain's vertex of refinement) 60 and 2384 do not
        /// reroute either: their target was such a vertex, a pinch. No reroute was left in 6000 random segments of this kind with the
        /// rule, so the path is checked with the pinch rule off; with it on these cases do not reroute
        /// </summary>
        [Theory]
        [InlineData(60, 20.0)]
        [InlineData(2384, 0.0)]
        public void SplitOntoAVertexAlreadyThere_TakesTheReroutePath(int which, double angle)
        {
            QualityMesh2.Refiner.ReroutesForTests = 0;
            QualityMesh2GridRerouteTests.RunChecked(QualityMesh2GridRerouteTests.Case(which, angle));
            Assert.Equal(0, QualityMesh2.Refiner.ReroutesForTests);
            QualityMesh2.Refiner.KeepPinchFreeForTests = false;
            try { QualityMesh2GridRerouteTests.RunChecked(QualityMesh2GridRerouteTests.Case(which, angle)); }
            finally { QualityMesh2.Refiner.KeepPinchFreeForTests = null; }
            Assert.True(QualityMesh2.Refiner.ReroutesForTests > 0, "the case no longer reroutes a piece through a vertex already there");
        }

        /// <summary>
        /// the behaviour change of Q17's mesher bugfix (no grid split reroutes a piece through a vertex of refinement onto another chain's
        /// edge): cases 31 and 292 took the reroute path onto another chain before; now that reroute is refused and the mesh is still
        /// VALID (the old refinement, with the rule off, reroutes more)
        /// </summary>
        [Theory]
        [InlineData(31, 0.0)]
        [InlineData(31, 20.0)]
        [InlineData(292, 20.0)]
        public void SplitOntoAnotherChain_IsRefused(int which, double angle)
        {
            var input = QualityMesh2GridRerouteTests.Case(which, angle);
            QualityMesh2.Refiner.ReroutesForTests = 0;
            var o = QualityMesh2GridRerouteTests.RunChecked(input);
            long withRule = QualityMesh2.Refiner.ReroutesForTests;
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            QualityMesh2.Refiner.KeepChainsApartForTests = false;
            QualityMesh2.Refiner.ReroutesForTests = 0;
            try { QualityMesh2GridRerouteTests.RunChecked(input); }
            finally { QualityMesh2.Refiner.KeepChainsApartForTests = null; }
            Assert.True(QualityMesh2.Refiner.ReroutesForTests > withRule, "the old refinement rerouted " + QualityMesh2.Refiner.ReroutesForTests + ", now " + withRule);
        }

        /// <summary>
        /// the behaviour change on a hull tip (Q17's mesher bugfix): hull fuzz seed 11 in the rotated frame had a hull corner of about 6
        /// degrees whose tip refinement collapsed by rerouting one hull chain onto the other through a grid point, reported as "vertices of
        /// the hull chains in no triangle"; now the tip stays, unreported, and the mesh is VALID
        /// </summary>
        [Fact]
        public void HullTipOfRefinement_IsKept()
        {
            var input = QualityMesh2HullGridTests.Moved(QualityMesh2HullGridTests.Fuzz(11), Similarity.ByName("rotated"));
            System.Collections.Generic.List<string> Diagnostics()
                => new QualityMesh2 { MinAngle = input.MinAngleDeg.Value, SnapTolerance = input.SnapTolerance, SteinerLimit = input.SteinerLimit, Conforming = true }
                    .Compute(ConstrainedDelaunayMesh2Candidate.Convert(input)).Diagnostics.ToList();
            Assert.DoesNotContain(Diagnostics(), d => d.Contains("vertices of the hull chains in no triangle"));
            var o = new Meshing2Acceptance.QualityMesh2Candidate().Run(input);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            QualityMesh2.Refiner.KeepChainsApartForTests = false;
            try { Assert.Contains(Diagnostics(), d => d.Contains("vertices of the hull chains in no triangle")); }
            finally { QualityMesh2.Refiner.KeepChainsApartForTests = null; }
        }

        /// <summary>
        /// the sweep on a kernel triangulation with a constrained chain from u to w: it marks every triangle between the line u w and
        /// the chain (centroid inside that polygon), and only triangles inside the chain's convex hull. Variant 1 has points inside the
        /// region (triangles with no corner on the chain), variant 2 a chain with a vertex off the triangle u q w (a piece split again
        /// at a nearby vertex), variant 3 a vertex on the line u w
        /// </summary>
        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        [InlineData(2)]
        [InlineData(3)]
        public void MarkSwept_MarksTheRegionBetweenPieceAndChain(int variant)
        {
            // (the sweep alone, on a wide region: in refinement the region is thinner than a pixel, which changes nothing here)
            var chainPts = new List<Vector2d> { new Vector2d(0, 0), new Vector2d(5, 3), new Vector2d(10, 0) };
            var pts = new List<Vector2d> { new Vector2d(5, -9), new Vector2d(5, 14), new Vector2d(19, 1), new Vector2d(-9, 1) };
            if (variant == 1) pts.AddRange(new[] { new Vector2d(3.5, 1), new Vector2d(5, 1.75), new Vector2d(6.5, 1), new Vector2d(5, 0.5) });
            if (variant == 2) chainPts.Insert(1, new Vector2d(2, 2));
            if (variant == 3) pts.Add(new Vector2d(4, 0));
            var all = chainPts.Concat(pts).ToList();
            var k = new DelaunayKernel2(all.Select(p => p.x).ToArray(), all.Select(p => p.y).ToArray(), Enumerable.Range(0, all.Count).ToArray());
            Assert.True(k.Build(System.Threading.CancellationToken.None));
            k.BeginConstraints();
            int Id(Vector2d p) => Enumerable.Range(0, all.Count).Single(v => k.X[v] == p.x && k.Y[v] == p.y);
            var chain = chainPts.Select(Id).ToList();
            var sources = new List<int> { 7 };
            for (int i = 0; i + 1 < chain.Count; ++i) {
                int h = k.FindEdge(chain[i], chain[i + 1]);
                Assert.True(h >= 0, "the chain edge " + i + " is an edge of the triangulation");
                k.SetConstraint(h, k.NewConstraint(new List<int>(sources)));
            }
            k.Dirty = new List<int>();
            Assert.True(QualityMesh2.Refiner.MarkSwept(k, chain[0], chain[chain.Count - 1], sources), "chain found");
            var marked = new HashSet<int>(k.Dirty);
            // the polygon between the line u w and the chain, and the chain's convex hull
            var polygon = chainPts;
            bool InPolygon(Vector2d c)
            {
                bool inside = false;
                for (int i = 0, j = polygon.Count - 1; i < polygon.Count; j = i++)
                    if ((polygon[i].y > c.y) != (polygon[j].y > c.y) && c.x < (polygon[j].x - polygon[i].x) * (c.y - polygon[i].y) / (polygon[j].y - polygon[i].y) + polygon[i].x) inside = !inside;
                return inside;
            }
            int region = 0;
            for (int t = 0; t < k.TriangleSlots; ++t) {
                if (k.IsGhost(t)) continue;
                var c = (k.Point(k.V[3 * t]) + k.Point(k.V[3 * t + 1]) + k.Point(k.V[3 * t + 2])) / 3;
                if (InPolygon(c)) { ++region; Assert.Contains(t, marked); }
            }
            Assert.True(region > 0, "a region: " + string.Join(" ", Enumerable.Range(0, k.TriangleSlots).Where(t => !k.IsGhost(t)).Select(t => k.V[3 * t] + "," + k.V[3 * t + 1] + "," + k.V[3 * t + 2])));
            foreach (int t in marked)
                for (int j = 0; j < 3; ++j) {
                    var x = k.Point(k.V[3 * t + j]);
                    Assert.True(x.y >= 0 && x.y <= chainPts.Max(p => p.y) && x.x >= 0 && x.x <= 10, "marked triangle " + t + " reaches outside the hull");
                }
            if (variant == 1)
                Assert.Contains(marked, t => Enumerable.Range(0, 3).All(j => !chain.Contains(k.V[3 * t + j])));
            // a chain that does not carry the sources is not found: the caller then marks everything
            Assert.False(QualityMesh2.Refiner.MarkSwept(k, chain[0], chain[chain.Count - 1], new List<int> { 99 }));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Refinement on the snap grid: a split point that rounds onto a vertex already there (the vertex of another constraint) reroutes
    /// the piece through that vertex without rewriting the triangles between the old piece and the new chain, and they change sides
    /// of the boundary. Their tags must change with them. Found with the grid fuzz with holes in M3: a hole edge rerouted through a
    /// segment's vertex inside the hole left a domain triangle tagged as hole (SegmentMissing, BoundaryNotConstrained), and the other
    /// way round a hole triangle tagged as domain.
    /// </summary>
    public class QualityMesh2GridRerouteTests
    {
        /// <summary> a 16 square with a triangular hole and the segments of the reduced fuzz cases, on a grid of the pixel </summary>
        internal static Mesh2Input Case(int which, double? minAngle)
        {
            var x = new List<double> { 0, 16, 16, 0, 6, 9, 7 }; var y = new List<double> { 0, 0, 16, 16, 6, 6.5, 9 };
            var input = new Mesh2Input();
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            input.Rings.Add(new RingInput(new[] { 4, 5, 6 }, true));
            // 292: found again after the carve (T15) took case 30's reroute away, whose target vertex lay inside the hole; it fails without
            // the reroute fix as well (oracle INVALID before #337)
            var segments = which == 30 ? new[] { (3.328125, 3.90625, 8.96875, 7.515625) }
                : which == 292 ? new[] { (5.65625, 12.875, 11.765625, 1.15625) }
                // 60 and 2384: a split onto a vertex already there that no other chain's edge leads to (found when the grid split stopped
                // rerouting a piece onto another chain, Q17: 31 and 292 rerouted onto one)
                : which == 60 ? new[] { (6.765625, 11.3125, 5.828125, 4.71875) }
                : which == 2384 ? new[] { (5.234375, 2.484375, 6.5, 8.765625) }
                : new[] { (7.234375, 13.734375, 6.078125, 4.453125), (2.78125, 4.375, 8.75, 11.5) };
            foreach (var (ax, ay, bx, by) in segments) {
                x.Add(ax); y.Add(ay); x.Add(bx); y.Add(by);
                input.Segments.Add(new SegmentInput(x.Count - 2, x.Count - 1));
            }
            input.X = x.ToArray(); input.Y = y.ToArray();
            input.SnapTolerance = which == 31 ? 0.25 : 0.5;
            input.MinAngleDeg = minAngle; input.SteinerLimit = 50000;
            return input;
        }

        internal static Mesh2Output RunChecked(Mesh2Input input)
        {
            QualityMesh2.Refiner.CheckTagsForTests = true;
            try { return new QualityMesh2Candidate().Run(input); }
            finally { QualityMesh2.Refiner.CheckTagsForTests = false; }
        }

        [Theory]
        [InlineData(30, 0.0)]
        [InlineData(30, 20.0)]
        [InlineData(30, 25.0)]
        [InlineData(31, 0.0)]
        [InlineData(31, 20.0)]
        [InlineData(31, 25.0)]
        [InlineData(292, 20.0)]
        public void SplitOntoAVertexAlreadyThere_RetagsTheTrianglesBetween(int which, double angle)
        {
            var input = Case(which, angle);
            // the tags against domain membership from scratch after every operation (throws on the first difference)
            var o = RunChecked(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        /// <summary> the same under every similarity: 2^k scales give the same mesh bit for bit, the others pass the oracle </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void SplitOntoAVertexAlreadyThere_Invariance(string name)
        {
            var s = Similarity.ByName(name);
            foreach (int which in new[] { 30, 31, 292 }) {
                var plain = Case(which, 20);
                var moved = Case(which, 20);
                for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
                moved.SnapTolerance = plain.SnapTolerance * s.Scale;
                var b = new QualityMesh2Candidate().Run(moved);
                Assert.Equal(Mesh2Status.Success, b.Status);
                var report = Oracle.Check(moved, b, new OracleExpect { Milestone = Milestone.M3 });
                Assert.True(report.Ok, name + ", case " + which + ": " + report);
                if (s.IsExact) {
                    var a = new QualityMesh2Candidate().Run(plain);
                    Assert.Equal(a.VX.Select(v => v * s.Scale), b.VX);
                    Assert.Equal(a.VY.Select(v => v * s.Scale), b.VY);
                    Assert.Equal(a.Triangles.SelectMany(t => t), b.Triangles.SelectMany(t => t));
                }
            }
        }

        /// <summary> one mesher, two computes: the same mesh </summary>
        [Fact]
        public void SplitOntoAVertexAlreadyThere_Reuse()
        {
            var c = ConstrainedDelaunayMesh2Candidate.Convert(Case(31, 20));
            var mesher = new QualityMesh2 { MinAngle = 20, SnapTolerance = 0.25, SteinerLimit = 50000 };
            var first = mesher.Compute(c).Mesh; var second = mesher.Compute(c).Mesh;
            Assert.Equal(first.Vertices, second.Vertices);
            Assert.Equal(first.Triangles, second.Triangles);
        }
    }
}

