        // ------------------------------------------------------------ the input key and the oracle mode

        [Fact]
        public void TextFormat_ModeLine_OnlyWhenSet_AndRoundTrips()
        {
            var input = Fuzz(1, 20, false);
            string text = TextFormat.WriteInput(input);
            Assert.DoesNotContain("mode", text);
            input.ConstrainedQuality = true;
            string withMode = TextFormat.WriteInput(input);
            Assert.EndsWith("conforming 0\nmode constrained\nend\n", withMode);
            Assert.NotEqual(TextFormat.InputSha256(Fuzz(1, 20, false)), TextFormat.InputSha256(input));
            var back = TextFormat.ReadInput(withMode);
            Assert.True(back.ConstrainedQuality);
            Assert.Equal(withMode, TextFormat.WriteInput(back));
            Assert.False(TextFormat.ReadInput(text).ConstrainedQuality);
            Assert.Throws<FormatException>(() => TextFormat.ReadInput(withMode.Replace("mode constrained", "mode conforming")));
            Assert.Throws<FormatException>(() => TextFormat.ReadInput(withMode.Replace("conforming 0", "conforming 1")));
            input.Conforming = true;   // the writer refuses what the reader rejects
            Assert.Throws<InvalidOperationException>(() => TextFormat.WriteInput(input));
        }

        /// <summary> the worked example of MESHING2D_GOLDEN_FORMAT.md keeps its hash: inputs without the mode are written as before </summary>
        [Fact]
        public void TextFormat_ExistingHash_Unchanged()
        {
            var input = new Mesh2Input { X = new double[] { 0, 1, 0 }, Y = new double[] { 0, 0, 1 } };
            Assert.Equal("404ba5d0db189586624422cb3610e0f32df60c39288536b41235e964b8d7e3db", TextFormat.InputSha256(input));
        }

        /// <summary>
        /// a constrained Delaunay mesh that is not conforming: a vertex in the diametral circle of a segment, across it. The constrained
        /// quality mode accepts it; the default quality mode (O2) does not.
        /// </summary>
        [Fact]
        public void Oracle_ConstrainedQuality_AcceptsWhatConformingRejects()
        {
            var input = new Mesh2Input { X = new double[] { 0, 10, 10, 0, 2, 8, 5 }, Y = new double[] { 0, 0, 10, 10, 5, 5, 4.5 } };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            input.Segments.Add(new SegmentInput(4, 5));
            input.MinAngleDeg = 0;
            var cdt = new ConstrainedDelaunayMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, cdt.Status);
            cdt.BadTriangles = new int[0];
            var conforming = Judge(input, cdt);
            Assert.False(conforming.Ok);
            Assert.Contains("NotDelaunay", conforming.ToString());
            input.ConstrainedQuality = true;
            var constrained = Judge(input, cdt);
            Assert.True(constrained.Ok, constrained.ToString());
        }
    }
}

using System;
using System.Collections.Generic;
using g3;
using Xunit;
using Xunit.Abstractions;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The refiner's insertions locate their point from the triangle the refiner already found (DelaunayKernel2.LocateHint): the
    /// walk takes a few steps, not O(sqrt n) from the last insertion, which the worst-first order puts anywhere in the mesh.
    /// </summary>
    public class QualityMesh2LocateTests
    {
        readonly ITestOutputHelper output;
        public QualityMesh2LocateTests(ITestOutputHelper output) { this.output = output; }

        /// <summary> a square with clusters of short segments in its corners and centre: refinement grades from each cluster, and the
        /// worst-first queue jumps between them </summary>
        static ConstrainedMesh2Input Clusters()
        {
            var input = new ConstrainedMesh2Input();
            void Add(Vector2d p) => input.Points.Add(p);
            Add(new Vector2d(0, 0)); Add(new Vector2d(1000, 0)); Add(new Vector2d(1000, 1000)); Add(new Vector2d(0, 1000));
            input.Rings.Add(new Mesh2Ring(new[] { 0, 1, 2, 3 }));
            var rnd = new Random(5);
            foreach (var c in new[] { new Vector2d(50, 50), new Vector2d(950, 60), new Vector2d(500, 500), new Vector2d(70, 930), new Vector2d(940, 940) })
                for (int i = 0; i < 6; ++i) {
                    int a = input.Points.Count;
                    var p = c + new Vector2d(rnd.NextDouble() * 20, rnd.NextDouble() * 20);
                    Add(p); Add(p + new Vector2d(rnd.NextDouble() - 0.5, rnd.NextDouble() - 0.5) * 4);
                    input.Segments.Add(new Mesh2Segment(a, a + 1));
                }
            return input;
        }

        [Theory]
        [InlineData(20.0, 0.0)]
        [InlineData(30.0, 0.0)]
        [InlineData(30.0, 0.01)]
        public void RefinerInsertions_WalkAFewSteps(double angle, double snap)
        {
            long steps0 = QualityMesh2.Refiner.WalkStepsForTests, n0 = QualityMesh2.Refiner.LocationsForTests;
            long segSteps0 = QualityMesh2.Refiner.SegmentWalkStepsForTests, segN0 = QualityMesh2.Refiner.SegmentLocationsForTests;
            var result = new QualityMesh2 { MinAngle = angle, MaxArea = 40, SnapTolerance = snap }.Compute(Clusters());
            long steps = QualityMesh2.Refiner.WalkStepsForTests - steps0, n = QualityMesh2.Refiner.LocationsForTests - n0;
            long segSteps = QualityMesh2.Refiner.SegmentWalkStepsForTests - segSteps0, segN = QualityMesh2.Refiner.SegmentLocationsForTests - segN0;
            Assert.True(result.Mesh != null && result.Mesh.Triangles.Count > 20000, "triangles " + result.Mesh?.Triangles.Count);
            output.WriteLine("triangles: " + n + " locations, " + steps + " steps; subsegments: " + segN + " locations, " + segSteps + " steps");
            // the triangle found holds the point: 0.01 steps per location here; from the last insertion instead 15 to 22 (85 on the
            // Herne tiles). A subsegment's point lies on the edge being split (or rounded next to it), and that edge's triangle is the
            // start: 2 to 8 steps in about 500 locations here; 86 to 179 if a hull edge's ghost is not replaced by its real triangle,
            // 12 to 26 per location without the hint
            Assert.True(n > 10000 && steps < n, n + " locations, " + steps + " walk steps");
            Assert.True(segN > 300 && 20 * segSteps < segN, segN + " subsegment locations, " + segSteps + " walk steps");
        }
    }
}

using System;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Off-centres (Ungor 2004) in <see cref="QualityMesh2"/>: a triangle below the angle bound is split on the perpendicular bisector of
    /// its shortest edge pq, where the triangle of pq and the new point has the bound at the point, or at its circumcentre if that is
    /// closer. The meshes themselves run through the oracle in the catalogue, the fuzz and the similarity tests.
    /// </summary>
    public class QualityMesh2OffCentreTests
    {
        static double HalfCotOf(double degrees) { double s = Math.Sin(degrees * Math.PI / 180); return QualityMesh2.Refiner.HalfCot(s * s); }

        static double AngleAt(Vector2d p, Vector2d a, Vector2d b)
        {
            var u = a - p; var w = b - p;
            return Math.Atan2(Math.Abs(u.x * w.y - u.y * w.x), u.x * w.x + u.y * w.y) * 180 / Math.PI;
        }

        [Theory]
        [InlineData(20)]
        [InlineData(25)]
        [InlineData(30)]
        [InlineData(33)]
        public void OffCentre_HasTheAngleBoundAtThePoint(double degrees)
        {
            // a needle: shortest edge (0, 0)-(1, 0), apex angle 2.9 degrees, its circumcentre 10 from the edge
            Vector2d a = new Vector2d(0, 0), b = new Vector2d(1, 0), c = new Vector2d(0.5, 10);
            Assert.True(QualityMesh2.Refiner.OffCentre(a, b, c, HalfCotOf(degrees), out var p));
            Assert.Equal(0.5, p.x, 15);                                   // on the bisector of the shortest edge
            Assert.True(p.y > 0 && p.y < 10);                             // towards the circumcentre, closer than it
            Assert.Equal(degrees, AngleAt(p, a, b), 9);                   // the bound at the new point
            // the same from every corner and orientation: the shortest edge is found, whichever vertex comes first
            foreach (var (x, y, z) in new[] { (b, c, a), (c, a, b), (b, a, c) }) {
                Assert.True(QualityMesh2.Refiner.OffCentre(x, y, z, HalfCotOf(degrees), out var q));
                Assert.Equal(p.x, q.x, 12); Assert.Equal(p.y, q.y, 12);
            }
        }

        [Theory]
        [InlineData(0.0, 0.0, 1.0, 0.0, 0.5, 0.8660254037844386)]     // equilateral
        [InlineData(0.0, 0.0, 1.0, 0.0, 0.5, 1.8660254037844386)]     // smallest angle 30 degrees, above half the bound
        [InlineData(0.0, 0.0, 1.0, 0.0, 0.5, 2.9)]                    // smallest angle 19.4 degrees: below the bound of 20, above its half
        public void OffCentre_IsTheCircumcentre_WhenThatIsCloser(double ax, double ay, double bx, double by, double cx, double cy)
        {
            // the circumcentre lies |pq| cot(alpha) / 2 from the midpoint, alpha the smallest angle; the off-centre |pq| cot(theta / 2) / 2:
            // with alpha at least theta / 2 the circumcentre is not farther
            Assert.False(QualityMesh2.Refiner.OffCentre(new Vector2d(ax, ay), new Vector2d(bx, by), new Vector2d(cx, cy), HalfCotOf(20), out _));
        }

        [Fact]
        public void OffCentre_JustBelowHalfTheBound_IsUsed()
        {
            // smallest angle 9.9 degrees at a bound of 20: the circumcentre is a little farther than the off-centre
            double h = 0.5 / Math.Tan(9.9 / 2 * Math.PI / 180);
            Assert.True(QualityMesh2.Refiner.OffCentre(new Vector2d(0, 0), new Vector2d(1, 0), new Vector2d(0.5, h), HalfCotOf(20), out var p));
            Assert.Equal(20, AngleAt(p, new Vector2d(0, 0), new Vector2d(1, 0)), 9);
        }

        [Fact]
        public void OffCentre_ScalesBitForBitWithPowersOfTwo()
        {
            Vector2d a = new Vector2d(3.25, -1.5), b = new Vector2d(4.125, -1.375), c = new Vector2d(-17.5, 9.0625);
            double hc = HalfCotOf(25);
            Assert.True(QualityMesh2.Refiner.OffCentre(a, b, c, hc, out var p));
            foreach (int k in new[] { -900, -500, -10, 10, 500, 900 }) {
                double f = Math.Pow(2, k);
                Assert.True(QualityMesh2.Refiner.OffCentre(a * f, b * f, c * f, hc, out var q));
                Assert.Equal(p.x * f, q.x);
                Assert.Equal(p.y * f, q.y);
            }
        }

        [Fact]
        public void HalfCot_IsTheCotangentOfHalfTheAngle()
        {
            for (int d = 1; d < 60; ++d) {
                double expected = 1 / Math.Tan(d / 2.0 * Math.PI / 180);
                Assert.Equal(1, HalfCotOf(d) / expected, 14);
            }
            Assert.True(double.IsPositiveInfinity(QualityMesh2.Refiner.HalfCot(0)));
        }

        /// <summary> both ways of splitting pass the oracle on the fuzz inputs, and off-centres change the mesh (they are in use) </summary>
        [Fact]
        public void Fuzz_WithAndWithoutOffCentres_PassTheOracle_AndDiffer()
        {
            int differ = 0;
            for (int seed = 0; seed < 24; ++seed) {
                var r = new Random(seed);
                var input = new Mesh2Input { X = new double[] { 0, 10, 10, 0 }, Y = new double[] { 0, 0, 10, 10 } };
                input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
                var x = input.X.ToList(); var y = input.Y.ToList();
                for (int i = 0; i < 3; ++i) {
                    x.Add(r.Next(1, 10)); y.Add(r.Next(1, 10));
                    x.Add(r.Next(1, 10) + r.NextDouble() * 0.5); y.Add(r.Next(1, 10));
                    input.Segments.Add(new SegmentInput(x.Count - 2, x.Count - 1));
                }
                input.X = x.ToArray(); input.Y = y.ToArray();
                input.MinAngleDeg = new[] { 20.0, 25, 30 }[seed % 3];
                input.SteinerLimit = 20000;
                var outputs = new Mesh2Output[2];
                foreach (bool on in new[] { true, false }) {
                    QualityMesh2.Refiner.OffCentresForBenchmarks = on;
                    try { outputs[on ? 0 : 1] = new QualityMesh2Candidate().Run(input); }
                    finally { QualityMesh2.Refiner.OffCentresForBenchmarks = null; }
                    var report = Oracle.Check(input, outputs[on ? 0 : 1], new OracleExpect { Milestone = Milestone.M3 });
                    Assert.True(report.Ok, "seed " + seed + (on ? " with" : " without") + " off-centres: " + report);
                }
                if (outputs[0].VX.Length != outputs[1].VX.Length || !outputs[0].VX.SequenceEqual(outputs[1].VX)) ++differ;
            }
            Assert.True(differ > 0, "off-centres changed no mesh");
        }

        /// <summary>
        /// the same on the snap grid: off-centres are rounded to the grid, and a refused off-centre (its pixel holds a constraint, or it
        /// adds no vertex) falls back to the circumcentre. Both ways pass the oracle, and off-centres change some meshes.
        /// </summary>
        [Fact]
        public void GridFuzz_WithAndWithoutOffCentres_PassTheOracle_AndDiffer()
        {
            var random = new Random(322);
            int differ = 0;
            for (int iter = 0; iter < 36; ++iter) {
                var x = new System.Collections.Generic.List<double> { 0, 16, 16, 0 }; var y = new System.Collections.Generic.List<double> { 0, 0, 16, 16 };
                var input = new Mesh2Input();
                input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
                int m = 4 + random.Next(12);
                for (int i = 0; i < m; ++i) {
                    for (int k = 0; k < 2; ++k) { x.Add(1 + Math.Round(random.NextDouble() * 14 * 64) / 64); y.Add(1 + Math.Round(random.NextDouble() * 14 * 64) / 64); }
                    input.Segments.Add(new SegmentInput(x.Count - 2, x.Count - 1));
                }
                input.X = x.ToArray(); input.Y = y.ToArray();
                input.SnapTolerance = new[] { 0.25, 0.5, 0.3, 1.0 / 3, 0.125, 1.0 / 16 }[iter % 6];
                input.MinAngleDeg = new[] { 20.0, 25, 30 }[iter % 3];
                input.SteinerLimit = 50000;
                var outputs = new Mesh2Output[2];
                foreach (bool on in new[] { true, false }) {
                    QualityMesh2.Refiner.OffCentresForBenchmarks = on;
                    try { outputs[on ? 0 : 1] = new QualityMesh2Candidate().Run(input); }
                    finally { QualityMesh2.Refiner.OffCentresForBenchmarks = null; }
                    Assert.Equal(Mesh2Status.Success, outputs[on ? 0 : 1].Status);
                    var report = Oracle.Check(input, outputs[on ? 0 : 1], new OracleExpect { Milestone = Milestone.M3 });
                    Assert.True(report.Ok, "iteration " + iter + (on ? " with" : " without") + " off-centres: " + report);
                }
                if (outputs[0].VX.Length != outputs[1].VX.Length || !outputs[0].VX.SequenceEqual(outputs[1].VX)) ++differ;
            }
            Assert.True(differ > 0, "off-centres changed no mesh on the grid");
        }

        /// <summary>
        /// a wedge whose input angle is below half the bound, under an area bound: the triangles at the apex are bad by size only (their
        /// small angle is the input's), so they take circumcentres, which halve them, not off-centres, which only shave them (review of
        /// #322). Every other triangle meets the bound here, so the mesh is the same with and without off-centres; a future change that
        /// leaves some apex triangle bad by its angle may make it differ for a sound reason.
        /// </summary>
        [Theory]
        [InlineData(0.3, 1.0, 0.002)]
        [InlineData(0.5, 2.0, 0.001)]
        [InlineData(2.0, 5.0, 0.01)]
        [InlineData(6.0, 20.0, 0.01)]
        public void SmallInputAngle_UnderAnAreaBound_TakesCircumcentres(double inputDeg, double boundDeg, double maxArea)
        {
            double a = inputDeg * Math.PI / 180;
            var input = new Mesh2Input { X = new double[] { 0, 4, 4 * Math.Cos(a) }, Y = new double[] { 0, 0, 4 * Math.Sin(a) } };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2 }, false));
            input.MinAngleDeg = boundDeg; input.MaxArea = maxArea; input.SteinerLimit = 20000;
            var outputs = new Mesh2Output[2];
            foreach (bool on in new[] { true, false }) {
                QualityMesh2.Refiner.OffCentresForBenchmarks = on;
                try { outputs[on ? 0 : 1] = new QualityMesh2Candidate().Run(input); }
                finally { QualityMesh2.Refiner.OffCentresForBenchmarks = null; }
                Assert.Equal(Mesh2Status.Success, outputs[on ? 0 : 1].Status);
                var report = Oracle.Check(input, outputs[on ? 0 : 1], new OracleExpect { Milestone = Milestone.M3 });
                Assert.True(report.Ok, (on ? "with" : "without") + " off-centres: " + report);
            }
            Assert.Equal(outputs[1].VX, outputs[0].VX);
            Assert.Equal(outputs[1].VY, outputs[0].VY);
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The oracle's rules for what refinement may do to the chains of the input's own rounding (owner decision on Q17, 2026-11-03:
    /// refinement must not collapse what the input's rounding keeps), and for the snapped domain (the hull model, its area):
    /// RefinementCoincidence (two chains share a link from a vertex of refinement on), RefinementPinch (two chains meet in a vertex of
    /// refinement: a known violation, listed, not failing yet), ChainSkipsHotPixel (a chain misses a hot pixel of the input's rounding
    /// its segment contacts), and the mesh area against the snapped domain (a report)
    /// </summary>
    public class QualityMesh2OracleCoincidenceTests
    {
        /// <summary> the refinement without the pinch rule (a split may route a chain through another chain's vertex of refinement) </summary>
        static Mesh2Output WithoutThePinchRule(Mesh2Input input)
        {
            QualityMesh2.Refiner.KeepPinchFreeForTests = false;
            try { return new QualityMesh2Candidate().Run(input); }
            finally { QualityMesh2.Refiner.KeepPinchFreeForTests = null; }
        }

        static Mesh2Output WithoutTheChainRule(Mesh2Input input)
        {
            QualityMesh2.Refiner.KeepChainsApartForTests = false;
            try { return new QualityMesh2Candidate().Run(input); }
            finally { QualityMesh2.Refiner.KeepChainsApartForTests = null; }
        }

        /// <summary>
        /// the refinement before #360's chain rule rerouted a piece onto another chain's edge: two chains then share a link from a vertex of
        /// refinement on (three subsegments there), which the oracle used to accept (the chains exist). Rejected now; the mesher with
        /// the rule gives a mesh without it. Seeds of <see cref="StarPolygonFuzz"/> where the refinement without the rule does that
        /// </summary>
        [Theory]
        [InlineData(12)]
        [InlineData(15)]
        [InlineData(100)]
        public void SharedLinkFromARefinementVertex_IsRejected(int seed)
        {
            var input = StarPolygonFuzz.Make(seed);
            var before = Oracle.Check(input, WithoutTheChainRule(input), new OracleExpect { Milestone = Milestone.M3 });
            Assert.Contains(before.Violations, v => v.Kind == Violation.RefinementCoincidence);
            var now = Oracle.Check(input, new QualityMesh2Candidate().Run(input), new OracleExpect { Milestone = Milestone.M3 });
            Assert.DoesNotContain(now.Violations, v => v.Kind == Violation.RefinementCoincidence);
        }

        /// <summary>
        /// the owner's strict decision on Q17: the spike of seed 527 has two edges whose links in the input's rounding, (9, 8) - (13, 12)
        /// and (13, 12) - (10, 10), both cross pixel (12, 11); refinement without the pinch rule puts a vertex there, and both chains run
        /// through it, the tip then hanging on that point. Rejected as RefinementPinch (a known violation, listed only, until the mesher's
        /// pinch rule; the mesher with the rule: QualityMesh2PinchFreeTests)
        /// </summary>
        [Fact]
        public void PinchAtARefinementVertex_IsRejected()
        {
            var input = StarPolygonFuzz.Make(527);
            var report = Oracle.Check(input, WithoutThePinchRule(input), new OracleExpect { Milestone = Milestone.M3 });
            var pinch = Assert.Single(report.Violations);
            Assert.Equal(Violation.RefinementPinch, pinch.Kind);
            Assert.Contains("(12, 11)", pinch.Detail);
            Assert.Empty(report.KnownViolations);
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        static Mesh2Input Moved(Mesh2Input plain, Similarity s)
        {
            var moved = new Mesh2Input { X = (double[])plain.X.Clone(), Y = (double[])plain.Y.Clone(), SnapTolerance = plain.SnapTolerance * s.Scale,
                MinAngleDeg = plain.MinAngleDeg, SteinerLimit = plain.SteinerLimit };
            for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
            moved.Rings.AddRange(plain.Rings);
            moved.Segments.AddRange(plain.Segments);
            return moved;
        }

        /// <summary>
        /// invariance: at the 2^k scales the pinch of seed 527 without the pinch rule and the coincidence of seed 12 without the chain rule
        /// are judged the same,
        /// violations and known violations alike (scaled); in every frame the new rules do not fire on seed 527's mesh
        /// </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void Rules_Invariance(string name)
        {
            var s = Similarity.ByName(name);
            var pinch = Moved(StarPolygonFuzz.Make(527), s);
            var r527 = Oracle.Check(pinch, WithoutThePinchRule(pinch), new OracleExpect { Milestone = Milestone.M3 });
            // (its free point outside the ring meshes outside the domain in some frames: a class of its own, see
            // QualityMesh2KeepsChainsApartTests; the rules here must not fire in any frame)
            Assert.DoesNotContain(r527.Violations, v => v.Kind == Violation.RefinementCoincidence || v.Kind == Violation.ChainSkipsHotPixel);
            if (!s.IsExact) return;
            var plain527 = StarPolygonFuzz.Make(527);
            var p527 = Oracle.Check(plain527, WithoutThePinchRule(plain527), new OracleExpect { Milestone = Milestone.M3 });
            Assert.Equal(new[] { Violation.RefinementPinch }, p527.Violations.Select(v => v.Kind));
            Assert.Equal(p527.Violations.Select(v => v.Kind), r527.Violations.Select(v => v.Kind));
            var plain12 = StarPolygonFuzz.Make(12);
            var moved12 = Moved(plain12, s);
            var p12 = Oracle.Check(plain12, WithoutTheChainRule(plain12), new OracleExpect { Milestone = Milestone.M3 });
            var m12 = Oracle.Check(moved12, WithoutTheChainRule(moved12), new OracleExpect { Milestone = Milestone.M3 });
            Assert.Equal(p12.Violations.Select(v => v.Kind), m12.Violations.Select(v => v.Kind));
            Assert.Equal(p12.KnownViolations.Count, m12.KnownViolations.Count);
        }

        /// <summary>
        /// the snapped-area report is opt-in (it builds both snapped images on every run): the verdict, the violations and the known
        /// violations do not depend on it, on a pinch case (seed 527) and a restore case (seed 62)
        /// </summary>
        [Theory]
        [InlineData(527)]
        [InlineData(62)]
        public void SnappedAreaReport_ChangesNoVerdict(int seed)
        {
            var input = StarPolygonFuzz.Make(seed);
            // (seed 527 meshed without the pinch rule: a pinch, a failing violation, to carry through)
            var o = seed == 527 ? WithoutThePinchRule(input) : new QualityMesh2Candidate().Run(input);
            var plain = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            var withArea = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3, ReportSnappedArea = true });
            Assert.Null(plain.MeshMinusSnappedArea);
            Assert.NotNull(withArea.MeshMinusSnappedArea);
            Assert.Equal(plain.ToString(), withArea.ToString());
            Assert.Equal(plain.KnownViolations.Select(v => v.ToString()), withArea.KnownViolations.Select(v => v.ToString()));
            Assert.Equal(plain.CollapsedSegments + "/" + plain.CollapsedPoints + "/" + plain.CollapsedViaRefinement,
                withArea.CollapsedSegments + "/" + withArea.CollapsedPoints + "/" + withArea.CollapsedViaRefinement);
        }

        /// <summary>
        /// ratchet (coordinator 2026-11-03): the refinement pinches on seeds 0 to 2999 of <see cref="StarPolygonFuzz"/> at M3, exactly.
        /// More fails; fewer means the limit goes down with the change that removes them (13 in 12 inputs at the rule's introduction; 12 in
        /// 11 since an input whose outer rings all collapse has an empty domain; 0 since the mesher's pinch rule, when they became a
        /// failing violation)
        /// </summary>
        [Fact]
        public void RefinementPinches_Ratchet()
        {
            int inputs = 0, pinches = 0;
            for (int seed = 0; seed < 3000; ++seed) {
                var input = StarPolygonFuzz.Make(seed);
                var report = Oracle.Check(input, new QualityMesh2Candidate().Run(input), new OracleExpect { Milestone = Milestone.M3 });
                int k = report.Violations.Count(v => v.Kind == Violation.RefinementPinch) + report.KnownViolations.Count(v => v.Kind == Violation.RefinementPinch);
                if (k > 0) { ++inputs; pinches += k; }
            }
            Assert.Equal((0, 0), (pinches, inputs));
        }

        /// <summary>
        /// ChainSkipsHotPixel's exception for collapsed links: seed 818's star ring crosses itself, and its thin second lobe collapses in
        /// the input's own rounding; edge 2 - 3 contacts the crossing's pixel (5, 8), but its links there collapse, so its chain need not
        /// run through it (the pixel itself keeps links of the big lobe). Accepted snapped alone and refined
        /// </summary>
        [Fact]
        public void HotPixelOnTheEdgesOwnCollapsedLinks_IsNotDemanded()
        {
            var input = StarPolygonFuzz.Make(818);
            var snapped = new Mesh2Input { X = input.X, Y = input.Y, SnapTolerance = 1 };
            snapped.Rings.AddRange(input.Rings);
            var m2 = Oracle.Check(snapped, new ConstrainedDelaunayMesh2Candidate().Run(snapped), new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(m2.Ok, m2.ToString());
            var m3 = Oracle.Check(input, new QualityMesh2Candidate().Run(input), new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(m3.Ok, m3.ToString());
        }

        /// <summary>
        /// a contacted hot pixel that collapses in both images needs no chain (O-H5; it lies on the edge's own image, whose links there
        /// collapse in both). Seeds of <see cref="StarPolygonFuzz"/> at M3 whose input points on collapsed parts lie in pixels their
        /// neighbours' edges contact
        /// </summary>
        [Theory]
        [InlineData(493)]
        [InlineData(1762)]
        public void HotPixelCollapsedInBothImages_IsNotDemanded(int seed)
        {
            var input = StarPolygonFuzz.Make(seed);
            var report = Oracle.Check(input, new QualityMesh2Candidate().Run(input), new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, report.ToString());
            Assert.True(report.CollapsedPoints > 0, report.ExcusedSummary());
        }

        /// <summary>
        /// at UTM coordinates and a pixel of 0.01 the output vertices are pixel centres rounded to doubles: the segment of Herne 373600
        /// (373662.135, 5709174.775) - (373662.129, 5709174.025), whose start lies exactly on the corner of its pixel, contacts the hot
        /// pixel of the point (373662.13, 5709174.77); its chain through that pixel is judged at the neighbours' exact pixel centres (the
        /// rounded start vertex misses the envelope by an ulp)
        /// </summary>
        [Fact]
        public void ChainAtUtmScale_IsJudgedAtExactPixelCentres()
        {
            var input = new Mesh2Input { X = new[] { 373662.135, 373662.129, 373662.13, 373661.9 }, Y = new[] { 5709174.775, 5709174.025, 5709174.77, 5709174.4 }, SnapTolerance = 0.01 };
            input.Segments.Add(new SegmentInput(0, 1));
            var o = new ConstrainedDelaunayMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(report.Ok, report.ToString());
        }

        /// <summary>
        /// option C only where the mesher refines (review of #36, S3): hull-domain soups at M3 in the constrained-quality mode at angle
        /// 0 are not refined, so their hull is not rounded and gets no restore pixels; judged as M3 they get the same verdict as the
        /// identical mesh judged as M2
        /// </summary>
        [Fact]
        public void HullNotRefined_IsNotRounded()
        {
            var wrong = new List<string>();
            for (int seed = 0; seed < 300; ++seed) {
                var input = Soup(seed);
                input.ConstrainedQuality = true; input.MinAngleDeg = 0;
                var o = new QualityMesh2Candidate().Run(input);
                if (o.Status != Mesh2Status.Success) continue;
                var m3 = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
                var m2 = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2 });
                if (m3.ToString() != m2.ToString()) wrong.Add(seed + ": M3 " + m3 + " | M2 " + m2);
            }
            Assert.True(wrong.Count == 0, wrong.Count + " differ:\n" + string.Join("\n", wrong.Take(10)));
        }

        /// <summary>
        /// each clause of the oracle's refinement test that can change the result (Refining, review of #36): the hull of (0, 0), (10, 1.4), (10, -3), (0, -3) with
        /// (5, 0.4) inside has the restore pixel (4, 1) on its top hull edge, which the oracle computes only where the mesher rounds the hull
        /// (M3 and refining). Each option set is judged on the candidate's mesh, which must be accepted at M3 (M2 judges the unrefined mesh with the angle set for the oracle only)
        /// </summary>
        [Theory]
        [InlineData("angle 20", true)]
        [InlineData("angle 0", true)]
        [InlineData("area 50", true)]
        [InlineData("size 5", true)]
        [InlineData("size function", true)]
        [InlineData("conforming", true)]
        [InlineData("cq angle 20", true)]
        [InlineData("cq area 50", true)]
        [InlineData("cq region area 50", true)]
        [InlineData("cq angle 0", false)]
        [InlineData("cq conforming", false)]
        [InlineData("Steiner limit", false)]
        [InlineData("none", false)]
        [InlineData("M2 angle 20", false)]
        public void Refining_DecidesTheHullModel(string options, bool rounded)
        {
            var input = new Mesh2Input { SnapTolerance = 1, X = new[] { 0.0, 10, 10, 0, 5 }, Y = new[] { 0.0, 1.4, -3, -3, 0.4 } };
            var milestone = Milestone.M3;
            switch (options) {
                case "angle 20": input.MinAngleDeg = 20; break;
                case "angle 0": input.MinAngleDeg = 0; break;
                case "area 50": input.MaxArea = 50; break;
                case "size 5": input.SizeConstant = 5; break;
                case "size function": input.SizeFunction = (x, y) => Q.FromDouble(5); break;
                case "conforming": input.Conforming = true; break;
                case "cq angle 20": input.ConstrainedQuality = true; input.MinAngleDeg = 20; break;
                case "cq area 50": input.ConstrainedQuality = true; input.MaxArea = 50; break;
                case "cq region area 50": input.ConstrainedQuality = true; input.Regions.Add(new RegionInput { Seed = new[] { 5.0, -1 }, Label = 1, MaxArea = 50 }); break;
                case "cq angle 0": input.ConstrainedQuality = true; input.MinAngleDeg = 0; break;
                case "cq conforming": input.ConstrainedQuality = true; input.Conforming = true; break;
                case "Steiner limit": input.SteinerLimit = 5; break;
                case "none": break;
                case "M2 angle 20": milestone = Milestone.M2; break;
            }
            var o = new QualityMesh2Candidate().Run(input);
            if (options == "M2 angle 20") input.MinAngleDeg = 20;
            Assert.Equal(Mesh2Status.Success, o.Status);
            var r = Oracle.Check(input, o, new OracleExpect { Milestone = milestone });
            // (at M2 the oracle also holds the unrefined mesh to the angle: only the hull model is judged there)
            if (milestone == Milestone.M3) Assert.True(r.Ok, options + ": " + r);
            Assert.Equal(rounded, r.RestorePixels.Contains((4, 1)));
        }

        static Mesh2Input Soup(int seed)
        {
            var rnd = new System.Random(seed);
            int n = 3 + rnd.Next(6);
            var xs = new List<double>(); var ys = new List<double>();
            var soup = new Mesh2Input { SnapTolerance = 1 };
            for (int i = 0; i < n; ++i) {
                for (int k = 0; k < 2; ++k) { xs.Add(rnd.Next(25) * 0.25); ys.Add(rnd.Next(25) * 0.25); }
                if (xs[2 * i] != xs[2 * i + 1] || ys[2 * i] != ys[2 * i + 1]) soup.Segments.Add(new SegmentInput(2 * i, 2 * i + 1));
            }
            soup.X = xs.ToArray(); soup.Y = ys.ToArray();
            return soup;
        }

        /// <summary>
        /// the snapped domain's area (it was left 0) and the hull model: snapped alone (M2), the mesh is exactly the snapped domain, for
        /// ring domains and, with the convex hull of the snapped vertices as the boundary, for hull domains (segment soups); with the
        /// exact hull's rounded image (the M3 model) the hull domains differ. Seeds of <see cref="StarPolygonFuzz"/> and soups of 3 to 8
        /// segments in [0, 6] at quarters
        /// </summary>
        [Fact]
        public void SnappedAlone_MeshAreaEqualsTheSnappedDomain()
        {
            var wrong = new List<string>();
            int hullRuns = 0, starRuns = 0;
            for (int seed = 0; seed < 300; ++seed) {
                var star = StarPolygonFuzz.Make(seed);
                var ring = new Mesh2Input { X = star.X, Y = star.Y, SnapTolerance = 1 };
                ring.Rings.AddRange(star.Rings);
                ring.Segments.AddRange(star.Segments);
                var soup = Soup(seed);
                foreach (var (name, input) in new[] { ("star", ring), ("soup", soup) }) {
                    var o = new ConstrainedDelaunayMesh2Candidate().Run(input);
                    if (o.Status != Mesh2Status.Success) continue;
                    var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2, ReportSnappedArea = true });
                    if (!report.Ok) continue;
                    if (name == "soup") ++hullRuns; else ++starRuns;
                    if (report.MeshMinusSnappedArea == null || report.MeshMinusSnappedArea.Value.Sign != 0)
                        wrong.Add(name + " " + seed + ": " + report.MeshMinusSnappedArea);
                }
            }
            Assert.True(wrong.Count == 0, wrong.Count + " differ:\n" + string.Join("\n", wrong.Take(20)));
            Assert.True(hullRuns >= 250 && starRuns >= 250, "hull runs " + hullRuns + ", star runs " + starRuns);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The oracle's own restore step of snap rounding with restore (Belussi, Migliorini, Negri and Pelagatti 2016; Q17, item (a)): the
    /// oracle recomputes SRR's restore pixels from the specification (MESHING2D_SNAP.md section 3b) and counts them in the rounding of
    /// the input (its input-only state of rule (ii')). These tests hold it against the library's snap rounding, which it shares no code
    /// with, and check that the restore pixels are no longer taken as refinement's
    /// </summary>
    public class QualityMesh2OracleRestoreTests
    {
        /// <summary>
        /// the pixels of the proper crossings of the input's edges that hold no input point, exactly (the pixel of x is
        /// floor(x / tol + 1/2)); the generator's star polygons can cross themselves (an angular gap above 180 degrees)
        /// </summary>
        static HashSet<(BigInteger x, BigInteger y)> CrossingPixels(Mesh2Input input)
        {
            var edges = new List<(int a, int b)>();
            foreach (var r in input.Rings) for (int i = 0; i < r.Vertices.Length; ++i) edges.Add((r.Vertices[i], r.Vertices[(i + 1) % r.Vertices.Length]));
            foreach (var s in input.Segments) edges.Add((s.A, s.B));
            var pts = Enumerable.Range(0, input.Count).Select(i => Pt.FromDoubles(input.X[i], input.Y[i])).ToArray();
            Q tol = Q.FromDouble(input.SnapTolerance), half = new Q(1, 2);
            BigInteger Floor(Q v) { var q = BigInteger.DivRem(v.N, v.D, out var rem); return rem.Sign < 0 ? q - 1 : q; }
            (BigInteger, BigInteger) PixelOf(Q x, Q y) => (Floor(x / tol + half), Floor(y / tol + half));
            var inputPixels = new HashSet<(BigInteger, BigInteger)>(pts.Select(p => PixelOf(p.Qx, p.Qy)));
            var result = new HashSet<(BigInteger, BigInteger)>();
            for (int i = 0; i < edges.Count; ++i)
                for (int j = i + 1; j < edges.Count; ++j) {
                    Pt a = pts[edges[i].a], b = pts[edges[i].b], c = pts[edges[j].a], d = pts[edges[j].b];
                    if (Exact.Orient(a, b, c) * Exact.Orient(a, b, d) >= 0 || Exact.Orient(c, d, a) * Exact.Orient(c, d, b) >= 0) continue;
                    Q den = (b.Qx - a.Qx) * (d.Qy - c.Qy) - (b.Qy - a.Qy) * (d.Qx - c.Qx), t = ((c.Qx - a.Qx) * (d.Qy - c.Qy) - (c.Qy - a.Qy) * (d.Qx - c.Qx)) / den;
                    var px = PixelOf(a.Qx + t * (b.Qx - a.Qx), a.Qy + t * (b.Qy - a.Qy));
                    if (!inputPixels.Contains(px)) result.Add(px);
                }
            return result;
        }

        /// <summary> the hot pixels the library's snap rounding adds beyond the input points' (crossings and restore), as indices </summary>
        static List<(BigInteger x, BigInteger y)> LibraryExtraPixels(Mesh2Input input)
        {
            var snap = SnapRounding2.Apply(ConstrainedDelaunayMesh2Candidate.Convert(input), input.SnapTolerance);
            return snap.Result.Points.Skip(snap.InputCount)
                .Select(p => (new BigInteger(Math.Round(p.x / input.SnapTolerance)), new BigInteger(Math.Round(p.y / input.SnapTolerance)))).Distinct().OrderBy(p => p).ToList();
        }

        static List<(BigInteger x, BigInteger y)> OracleExtraPixels(Mesh2Input input, OracleReport report)
            => CrossingPixels(input).Concat(report.RestorePixels).Distinct().OrderBy(p => p).ToList();

        /// <summary>
        /// on seeds 0 to 2999 of <see cref="StarPolygonFuzz"/>, the hot pixels the library's snap rounding adds beyond the input points'
        /// are exactly the crossings' and the oracle's restore pixels; at least the 10 seeds that need them have some
        /// </summary>
        [Fact]
        public void RestorePixels_MatchTheLibrarys_OnTheFuzz()
        {
            var wrong = new List<string>();
            int withRestore = 0;
            for (int seed = 0; seed < 3000; ++seed) {
                var input = StarPolygonFuzz.Make(seed);
                var library = LibraryExtraPixels(input);
                var o = new QualityMesh2Candidate().Run(input);
                // (an input whose ring collapses entirely has an empty domain, and the oracle computes no snapped domain for an empty
                // output: those seeds are skipped here)
                bool empty = QualityMesh2KeepsChainsApartTests.EmptyDomain.Contains(seed);
                Assert.Equal(empty ? Mesh2Status.Empty : Mesh2Status.Success, o.Status);
                if (empty) continue;
                var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
                Assert.NotNull(report.RestorePixels);
                var expected = OracleExtraPixels(input, report);
                if (report.RestorePixels.Count > 0) ++withRestore;
                if (!expected.SequenceEqual(library))
                    wrong.Add(seed + ": library " + string.Join(" ", library) + ", oracle " + string.Join(" ", expected));
            }
            Assert.True(wrong.Count == 0, wrong.Count + " seeds differ:\n" + string.Join("\n", wrong.Take(20)));
            Assert.True(withRestore >= 10, "seeds with restore pixels: " + withRestore);
        }

        /// <summary> a soup of 3 to 8 segments with ends at quarters in [0, 6]², pixel 1: dense, with ties in the nearest pixel </summary>
        static Mesh2Input Soup(int seed)
        {
            var rnd = new Random(seed);
            int n = 3 + rnd.Next(6);
            var xs = new List<double>(); var ys = new List<double>();
            var input = new Mesh2Input { SnapTolerance = 1 };
            for (int i = 0; i < n; ++i) {
                for (int k = 0; k < 2; ++k) { xs.Add(rnd.Next(25) * 0.25); ys.Add(rnd.Next(25) * 0.25); }
                input.Segments.Add(new SegmentInput(2 * i, 2 * i + 1));
            }
            input.X = xs.ToArray(); input.Y = ys.ToArray();
            return input;
        }

        /// <summary>
        /// the same comparison on dense segment soups snapped alone (M2), where the restore step meets ties in the nearest pixel; the
        /// soups of seeds 0 to 1999 use ChoosePixel's rules R1 and R3 (its widened search, the fallback when no neighbour is useful,
        /// was met in none of them, nor in 280 000 other random inputs, by the library or the oracle)
        /// </summary>
        [Fact]
        public void RestorePixels_MatchTheLibrarys_OnSegmentSoups()
        {
            var wrong = new List<string>();
            int spread = 0, forced = 0;
            for (int seed = 0; seed < 2000; ++seed) {
                var input = Soup(seed);
                if (Enumerable.Range(0, input.Segments.Count).Any(i => input.X[2 * i] == input.X[2 * i + 1] && input.Y[2 * i] == input.Y[2 * i + 1])) continue;
                var snap = SnapRounding2.Apply(ConstrainedDelaunayMesh2Candidate.Convert(input), 1);
                spread += snap.Spread; forced += snap.ForcedSpread;
                var library = LibraryExtraPixels(input);
                var o = new ConstrainedDelaunayMesh2Candidate().Run(input);
                if (o.Status != Mesh2Status.Success) { wrong.Add(seed + ": status " + o.Status); continue; }
                var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2 });
                var oracle = OracleExtraPixels(input, report);
                if (!oracle.SequenceEqual(library)) wrong.Add(seed + ": library " + string.Join(" ", library) + ", oracle " + string.Join(" ", oracle));
            }
            Assert.True(wrong.Count == 0, wrong.Count + " seeds differ:\n" + string.Join("\n", wrong.Take(20)));
            Assert.True(spread > 0 && forced > 0, "R1 " + spread + ", R3 " + forced);
        }

        /// <summary>
        /// a hull domain's hull edges are snap-rounded only with refinement (option C), and so restored only then: the top hull edge
        /// (0, 0) - (10, 1.4) is routed (0, 0) - (10, 1), whose link crosses the pixel of the input point (5, 0.4), which the edge
        /// does not contact; the restore step makes (4, 1) hot at M3, as the mesher does (its first vertex beyond the input), and
        /// nothing at M2
        /// </summary>
        [Fact]
        public void HullEdgesAreRestoredOnlyWithRefinement()
        {
            var x = new[] { 0.0, 10, 10, 0, 5 };
            var y = new[] { 0.0, 1.4, -3, -3, 0.4 };
            var snapped = new Mesh2Input { X = x, Y = y, SnapTolerance = 1 };
            var m2 = Oracle.Check(snapped, new ConstrainedDelaunayMesh2Candidate().Run(snapped), new OracleExpect { Milestone = Milestone.M2 });
            Assert.True(m2.Ok, m2.ToString());
            Assert.Empty(m2.RestorePixels);
            var refined = new Mesh2Input { X = x, Y = y, SnapTolerance = 1, MinAngleDeg = 20, SteinerLimit = 5000 };
            var o = new QualityMesh2Candidate().Run(refined);
            var m3 = Oracle.Check(refined, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(m3.Ok, m3.ToString());
            Assert.Equal(new[] { (new BigInteger(4), new BigInteger(1)) }, m3.RestorePixels.ToArray());
            Assert.Equal((4.0, 1.0), (o.VX[refined.Count], o.VY[refined.Count]));
        }

        /// <summary>
        /// a tie in ChoosePixel's nearest pixel: four segments of slope 0 and -1 through half pixels and a free point (found by a search
        /// over such inputs); the candidates (5, 0) and (6, 0) lie equally near the segment, and the tie goes to the smaller x, as the
        /// library breaks it
        /// </summary>
        [Fact]
        public void RestoreTie_GoesToTheSmallerX()
        {
            var input = new Mesh2Input { X = new[] { 0, 5.5, 1.5, 6, 2.5, 8.5, 2, 8, 1 }, Y = new[] { 5, 5, 4.5, 0.5, 2.5, -2.5, 3, -3, 5.25 }, SnapTolerance = 1 };
            for (int i = 0; i < 4; ++i) input.Segments.Add(new SegmentInput(2 * i, 2 * i + 1));
            var report = Oracle.Check(input, new ConstrainedDelaunayMesh2Candidate().Run(input), new OracleExpect { Milestone = Milestone.M2 });
            Assert.Contains((new BigInteger(5), new BigInteger(0)), report.RestorePixels);
            Assert.DoesNotContain((new BigInteger(6), new BigInteger(0)), report.RestorePixels);
            Assert.Equal(LibraryExtraPixels(input), OracleExtraPixels(input, report));
        }

        /// <summary>
        /// the same comparison where the critical search walks along each link (more hot pixels than a link has pixels): 100 to 200 free
        /// points and 5 to 15 segments in [0, 30]², pixel 1, snapped alone (M2) (review S1: the soups and the fuzz have too few hot
        /// pixels for that mode)
        /// </summary>
        [Fact]
        public void RestorePixels_MatchTheLibrarys_WithManyHotPixels()
        {
            var wrong = new List<string>();
            int withRestore = 0;
            for (int seed = 0; seed < 60; ++seed) {
                var rnd = new Random(seed);
                int points = 100 + rnd.Next(101), segments = 5 + rnd.Next(11);
                var xs = new List<double>(); var ys = new List<double>();
                for (int i = 0; i < 2 * segments + points; ++i) { xs.Add(Math.Round(rnd.NextDouble() * 300) / 10); ys.Add(Math.Round(rnd.NextDouble() * 300) / 10); }
                var input = new Mesh2Input { X = xs.ToArray(), Y = ys.ToArray(), SnapTolerance = 1 };
                for (int i = 0; i < segments; ++i) if (xs[2 * i] != xs[2 * i + 1] || ys[2 * i] != ys[2 * i + 1]) input.Segments.Add(new SegmentInput(2 * i, 2 * i + 1));
                var library = LibraryExtraPixels(input);
                var o = new ConstrainedDelaunayMesh2Candidate().Run(input);
                if (o.Status != Mesh2Status.Success) { wrong.Add(seed + ": status " + o.Status); continue; }
                var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M2 });
                if (report.RestorePixels.Count > 0) ++withRestore;
                var oracle = OracleExtraPixels(input, report);
                if (!oracle.SequenceEqual(library)) wrong.Add(seed + ": library " + string.Join(" ", library) + ", oracle " + string.Join(" ", oracle));
            }
            Assert.True(wrong.Count == 0, wrong.Count + " seeds differ:\n" + string.Join("\n", wrong.Take(20)));
            Assert.True(withRestore >= 30, "seeds with restore pixels: " + withRestore);
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        static Mesh2Input Moved(Mesh2Input plain, Similarity s)
        {
            var moved = new Mesh2Input { X = (double[])plain.X.Clone(), Y = (double[])plain.Y.Clone(), SnapTolerance = plain.SnapTolerance * s.Scale,
                MinAngleDeg = plain.MinAngleDeg, SteinerLimit = plain.SteinerLimit };
            for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
            moved.Rings.AddRange(plain.Rings);
            moved.Segments.AddRange(plain.Segments);
            return moved;
        }

        /// <summary>
        /// the restore cases of the fuzz in every similarity frame: the library's extra hot pixels are the crossings' and the oracle's
        /// restore pixels, and the mesh is accepted; at the 2^k scales the restore pixels, the mesh and the excuses are the same bit for bit
        /// </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void RestoreCases_Invariance(string name)
        {
            var s = Similarity.ByName(name);
            foreach (int seed in new[] { 62, 161, 787, 818, 963, 1455, 2396, 2459, 2471, 2923 }) {
                var plain = StarPolygonFuzz.Make(seed);
                var input = Moved(plain, s);
                var library = LibraryExtraPixels(input);
                var o = new QualityMesh2Candidate().Run(input);
                Assert.Equal(Mesh2Status.Success, o.Status);
                var report = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
                var oracle = OracleExtraPixels(input, report);
                Assert.True(library.SequenceEqual(oracle), name + ", seed " + seed + ": library " + string.Join(" ", library) + ", oracle " + string.Join(" ", oracle));
                Assert.True(report.Ok, name + ", seed " + seed + ": " + report);
                if (s.IsExact) {
                    var a = new QualityMesh2Candidate().Run(plain);
                    var plainReport = Oracle.Check(plain, a, new OracleExpect { Milestone = Milestone.M3 });
                    Assert.Equal(plainReport.RestorePixels, report.RestorePixels);
                    Assert.Equal(a.VX.Select(x => x * s.Scale), o.VX);
                    Assert.Equal(a.VY.Select(y => y * s.Scale), o.VY);
                    Assert.Equal(plainReport.ExcusedSummary(), report.ExcusedSummary());
                }
            }
        }

        /// <summary> reuse: one oracle check twice on the same input and output gives the same restore pixels and verdict </summary>
        [Fact]
        public void RestorePixels_SameOnASecondCheck()
        {
            var input = StarPolygonFuzz.Make(62);
            var o = new QualityMesh2Candidate().Run(input);
            var first = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            var second = Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });
            Assert.NotEmpty(first.RestorePixels);
            Assert.Equal(first.RestorePixels, second.RestorePixels);
            Assert.Equal(first.ToString(), second.ToString());
            Assert.Equal(first.ExcusedSummary(), second.ExcusedSummary());
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Inserting the pieces of a split subsegment settles: a vertex within the tolerance of a piece splits it only when both parts are
    /// strictly shorter. Without that, refinement in the constrained-quality mode at high angle bounds (a cascade at a small angle between
    /// a hull edge and a ring, down to pieces about as short as the tolerance) failed with NodingLimit, "a segment split did not settle":
    /// two vertices within the tolerance of each other's piece split it at each other in turn (found with ext/cdt/island at 32 and 34
    /// degrees, a public input; reproduced here with procedural jagged rings).
    /// </summary>
    public class QualityMesh2PieceSettleTests
    {
        /// <summary> a closed polyline of n points at random radii around a circle, coordinates rounded to 8 decimals, as segments
        /// (no ring: the domain is the convex hull, whose edges meet the polyline at small angles) </summary>
        /// (splitmix64, not System.Random, so the inputs are the same on every target framework)
        internal static Mesh2Input JaggedRing(int seed, int n, double angle)
        {
            ulong state = (ulong)seed;
            double Next()
            {
                ulong z = state += 0x9E3779B97F4A7C15UL;
                z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
                z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
                return ((z ^ (z >> 31)) >> 11) * (1.0 / (1UL << 53));
            }
            var xy = new double[2 * n];
            for (int i = 0; i < n; ++i) {
                double t = 2 * Math.PI * i / n, r = 0.5 + 0.35 * Next();
                xy[2 * i] = Math.Round(0.5 + r * Math.Cos(t), 8); xy[2 * i + 1] = Math.Round(0.5 + r * Math.Sin(t), 8);
            }
            var input = Generators.Literal(xy);
            for (int i = 0; i < n; ++i) input.Segments.Add(new SegmentInput(i, (i + 1) % n));
            input.MinAngleDeg = angle;
            input.ConstrainedQuality = true;
            return input;
        }

        public static IEnumerable<object[]> Seeds() => SettleSeeds.Select(s => new object[] { s });
        // (seeds that failed with NodingLimit at 34 degrees before the fix: 7 of the first 300)
        internal static readonly int[] SettleSeeds = { 67, 91, 161 };

        [Theory]
        [MemberData(nameof(Seeds))]
        public void JaggedRing_AtHighBounds_Settles(int seed)
        {
            var input = JaggedRing(seed, 40, 34);
            var output = new QualityMesh2Candidate().Run(input);
            Assert.True(output.Status == Mesh2Status.Success, "seed " + seed + ": " + output.Status + " " + output.FailureKind);
            var report = Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, "seed " + seed + ": " + report);
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        /// <summary> the case under every similarity: the others pass the oracle, the 2^k scales give the same mesh bit for bit </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void JaggedRing_Settles_UnderEverySimilarity(string name)
        {
            var s = Similarity.ByName(name);
            var plain = JaggedRing(SettleSeeds[0], 40, 34);
            var moved = JaggedRing(SettleSeeds[0], 40, 34);
            for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
            var b = new QualityMesh2Candidate().Run(moved);
            Assert.True(b.Status == Mesh2Status.Success, name + ": " + b.Status + " " + b.FailureKind);
            var report = Oracle.Check(moved, b, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, name + ": " + report);
            if (s.IsExact) AssertScaled(new QualityMesh2Candidate().Run(plain), b, s.Scale);
        }

        /// <summary>
        /// scaled by 2^-500 and 2^200: the same mesh bit for bit (the guard's lengths at the extreme exponents: see
        /// ToleranceSplit_OnlyWhenItShortens)
        /// </summary>
        [Theory]
        [InlineData(-500)]
        [InlineData(200)]
        public void JaggedRing_AtExtremeScales_IsBitIdentical(int exponent)
        {
            double f = Math.Pow(2, exponent);
            var plain = JaggedRing(SettleSeeds[0], 40, 34);
            var moved = JaggedRing(SettleSeeds[0], 40, 34);
            for (int i = 0; i < plain.Count; ++i) { moved.X[i] = plain.X[i] * f; moved.Y[i] = plain.Y[i] * f; }
            var a = new QualityMesh2Candidate().Run(plain);
            Assert.Equal(Mesh2Status.Success, a.Status);
            AssertScaled(a, new QualityMesh2Candidate().Run(moved), f);
        }

        static void AssertScaled(Mesh2Output a, Mesh2Output b, double f)
        {
            Assert.Equal(a.Status, b.Status);
            Assert.Equal(a.VX.Select(v => v * f), b.VX);
            Assert.Equal(a.VY.Select(v => v * f), b.VY);
            Assert.Equal(a.Triangles.SelectMany(t => t), b.Triangles.SelectMany(t => t));
        }

        /// <summary>
        /// The guard alone, by hand: u = (0, 0), w = (L, 0) and v = (0.9 L, 0.495 L) with L = 2^-40, and a point (1, 1) that makes the
        /// automatic tolerance 2^-41 = L / 2. v is within the tolerance of the segment u-w (0.495 L), not of u or w (|vw| = 0.505 L), and
        /// |uv| = 1.027 L is longer than u-w: splitting u-w at v would not shorten it, so u-w stays one subsegment. Then a v that does
        /// shorten it (0.5 L, 0.495 L): u-w is split at v, as before. Both also scaled by 2^-900 and 2^200: the guard compares
        /// lengths in scaled units, since at 2^-900 the squares of the raw differences (about 2^-1880) underflow to 0 and the guard
        /// would refuse every split.
        /// </summary>
        [Theory]
        [InlineData(0.9, false, 0)]
        [InlineData(0.5, true, 0)]
        [InlineData(0.9, false, -900)]
        [InlineData(0.5, true, -900)]
        [InlineData(0.9, false, 200)]
        [InlineData(0.5, true, 200)]
        public void ToleranceSplit_OnlyWhenItShortens(double t, bool split, int exponent)
        {
            double f = Math.Pow(2, exponent), l = f / (1L << 40);
            var input = new ConstrainedMesh2Input();
            input.Points.Add(new Vector2d(0, 0));
            input.Points.Add(new Vector2d(l, 0));
            input.Points.Add(new Vector2d(t * l, 0.495 * l));
            input.Points.Add(new Vector2d(f, f));
            input.Segments.Add(new Mesh2Segment(0, 1));
            var result = new ConstrainedDelaunayMesh2().Compute(input);
            Assert.Equal(Triangulation2Status.Success, result.Status);
            var subs = result.Mesh.Subsegments.Select(q => (Math.Min(q.A, q.B), Math.Max(q.A, q.B))).OrderBy(q => q).ToList();
            var expected = split ? new List<(int, int)> { (0, 2), (1, 2) } : new List<(int, int)> { (0, 1) };
            Assert.Equal(expected, subs);
        }

        /// <summary>
        /// The same guard where u-w is not an edge yet: L = 2^-39 (the tolerance is L / 4), u = (0, 0), w = (L, 0),
        /// v = (0.973 L, 0.249 L), and p = (0.5 L, -0.35 L) inside the circle through u, w and v, so the triangulation has p-v instead of
        /// u-w and v is a corner of the triangle at u that holds the direction to w. v is within the tolerance of u-w (0.249 L), not of
        /// w (0.2505 L), and |uv| = 1.004 L: no split, the walk recovers u-w. With q = (0.3 L, 0.45 L) as well, v is met in the walk
        /// beyond the start triangle instead. At 2^0, 2^-900 and 2^200.
        /// </summary>
        [Theory]
        [InlineData(false, 0)]
        [InlineData(false, -900)]
        [InlineData(false, 200)]
        [InlineData(true, 0)]
        [InlineData(true, -900)]
        public void ToleranceSplit_InTheWalk_OnlyWhenItShortens(bool withQ, int exponent)
        {
            double f = Math.Pow(2, exponent), l = f / (1L << 39);
            var input = new ConstrainedMesh2Input();
            input.Points.Add(new Vector2d(0, 0));
            input.Points.Add(new Vector2d(l, 0));
            input.Points.Add(new Vector2d(0.973 * l, 0.249 * l));
            input.Points.Add(new Vector2d(0.5 * l, -0.35 * l));
            input.Points.Add(new Vector2d(f, f));
            if (withQ) input.Points.Add(new Vector2d(0.3 * l, 0.45 * l));
            input.Segments.Add(new Mesh2Segment(0, 1));
            var result = new ConstrainedDelaunayMesh2().Compute(input);
            Assert.Equal(Triangulation2Status.Success, result.Status);
            var subs = result.Mesh.Subsegments.Select(q => (Math.Min(q.A, q.B), Math.Max(q.A, q.B))).ToList();
            Assert.Equal(new List<(int, int)> { (0, 1) }, subs);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The refinement on the snap grid does not pinch two chains (owner decision 2026-11-03 on Q17, strict): a split point may not be a
    /// vertex of refinement that another chain already runs through. Every pinch measured came that way: one chain's split made the
    /// vertex, another chain's split later chose it as "a vertex already there" (the star polygon fuzz: 12 pinches in 11 inputs; Herne:
    /// 11 to 217 per run). Only the library's existing API here, so that these tests run against the library before the fix.
    /// </summary>
    public class QualityMesh2PinchFreeTests
    {
        static OracleReport Judge(Mesh2Input input, Mesh2Output o) => Oracle.Check(input, o, new OracleExpect { Milestone = Milestone.M3 });

        static int Pinches(OracleReport r) => r.Violations.Count(v => v.Kind == Violation.RefinementPinch);

        /// <summary> the inputs of the star polygon fuzz that pinched: no pinch now, and the verdict of their class (2858 drops an input
        /// point, as it did before; QualityMesh2KeepsChainsApartTests) </summary>
        [Theory]
        [InlineData(527)]
        [InlineData(533)]
        [InlineData(555)]
        [InlineData(586)]
        [InlineData(1516)]
        [InlineData(1618)]
        [InlineData(1833)]
        [InlineData(1861)]
        [InlineData(2020)]
        [InlineData(2434)]
        [InlineData(2858)]
        public void StarFuzz_FormerPinches_NoPinch(int seed)
        {
            var input = StarPolygonFuzz.Make(seed);
            var o = new QualityMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var r = Judge(input, o);
            Assert.Equal(0, Pinches(r));
            Assert.True(r.Ok || seed == 2858, r.ToString());
        }

        /// <summary> the same inputs in the constrained quality mode, at 20 and 25 degrees (lenses) </summary>
        [Fact]
        public void StarFuzz_ConstrainedQuality_NoPinch()
        {
            int pinches = 0;
            for (int seed = 0; seed < 3000; ++seed) {
                var input = StarPolygonFuzz.Make(seed);
                input.ConstrainedQuality = true;
                input.MinAngleDeg = seed % 2 == 0 ? 20 : 25;
                var o = new QualityMesh2Candidate().Run(input);
                if (o.Status != Mesh2Status.Success) continue;
                pinches += Pinches(Judge(input, o));
            }
            Assert.Equal(0, pinches);
        }

        /// <summary>
        /// random segments in a square on the grid: refused split points leave more subsegments unsplittable, and the oracle, which
        /// recomputes from the specification which subsegments can be split, accepts the meshes (a subsegment whose only split pixels
        /// hold another chain's vertex of refinement is not demanded conforming Delaunay; these seeds were rejected without that)
        /// </summary>
        [Theory]
        [InlineData(111, 20.0)]
        [InlineData(429, 20.0)]
        [InlineData(1471, 20.0)]
        [InlineData(271, 30.0)]
        public void SegmentFuzz_UnsplittableByThePinchRule_Accepted(int seed, double angle)
        {
            var input = Segments(seed, angle);
            var o = new QualityMesh2Candidate().Run(input);
            Assert.Equal(Mesh2Status.Success, o.Status);
            var r = Judge(input, o);
            Assert.True(r.Ok, r.ToString());
            Assert.Equal(0, Pinches(r));
        }

        internal static Mesh2Input Segments(int seed, double angle)
        {
            var r0 = new Random(seed);
            int n = 6 + r0.Next(14);
            var x = new List<double> { 0, 24, 24, 0 }; var y = new List<double> { 0, 0, 24, 24 };
            var input = new Mesh2Input { SnapTolerance = new[] { 1.0, 0.5, 0.3 }[seed % 3], MinAngleDeg = angle, SteinerLimit = 20000 };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            for (int i = 0; i < n; ++i) {
                x.Add(1 + r0.NextDouble() * 22); y.Add(1 + r0.NextDouble() * 22); x.Add(1 + r0.NextDouble() * 22); y.Add(1 + r0.NextDouble() * 22);
                input.Segments.Add(new SegmentInput(x.Count - 2, x.Count - 1));
            }
            input.X = x.ToArray(); input.Y = y.ToArray();
            return input;
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        static Mesh2Input Moved(Mesh2Input plain, Similarity s)
        {
            var moved = new Mesh2Input { X = (double[])plain.X.Clone(), Y = (double[])plain.Y.Clone(), SnapTolerance = plain.SnapTolerance * s.Scale,
                MinAngleDeg = plain.MinAngleDeg, SteinerLimit = plain.SteinerLimit };
            for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
            moved.Rings.AddRange(plain.Rings);
            moved.Segments.AddRange(plain.Segments);
            return moved;
        }

        /// <summary> invariance: seed 527 has no pinch in any frame (its free point outside the ring meshes outside the domain in some
        /// frames, a class of its own); at the 2^k scales the mesh is the same bit for bit, and accepted </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void Seed527_Invariance(string name)
        {
            var s = Similarity.ByName(name);
            var plain = StarPolygonFuzz.Make(527);
            var moved = Moved(plain, s);
            var o = new QualityMesh2Candidate().Run(moved);
            Assert.Equal(0, Pinches(Judge(moved, o)));
            if (!s.IsExact) return;
            var a = new QualityMesh2Candidate().Run(plain);
            Assert.Equal(a.VX.Select(x => x * s.Scale), o.VX);
            Assert.Equal(a.VY.Select(y => y * s.Scale), o.VY);
            Assert.Equal(a.Triangles.SelectMany(t => t), o.Triangles.SelectMany(t => t));
            Assert.True(Judge(moved, o).Ok, name);
        }

        /// <summary> reuse: one mesher instance twice on seed 527 gives the same mesh </summary>
        [Fact]
        public void Reuse_SameInstance()
        {
            var mesher = new QualityMesh2 { MinAngle = 20, SnapTolerance = 1 };
            var input = ConstrainedDelaunayMesh2Candidate.Convert(StarPolygonFuzz.Make(527));
            var a = mesher.Compute(input);
            var b = mesher.Compute(input);
            Assert.Equal(Triangulation2Status.Success, a.Status);
            Assert.Equal(a.Mesh.Vertices, b.Mesh.Vertices);
            Assert.Equal(a.Mesh.Triangles, b.Mesh.Triangles);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// An input angle counts as small (and a triangle spanning it is not refined, Shewchuk 2002) only where the oracle excuses the
    /// triangle: sin^2 strictly below the bound's by the oracle's slack 2^-30. The refiner used a relative 1e-9 (2.5e-10 at 30
    /// degrees), so for an input angle just below the bound, inside that window, it kept triangles the oracle reports as
    /// AngleBelowBound (found by review of the small-angle design; reproduced with a wedge at 30 degrees - 6e-10 rad and a few points in it).
    /// </summary>
    public class QualityMesh2SmallAngleMarginTests
    {
        /// <summary> a wedge of two segments from the origin at 30 degrees - 6e-10 rad (sin^2 about 0.25 - 5.2e-10, in the window), in a
        /// box ring, with 1 to 4 random points inside the wedge and 0 to 3 next to its first segment; constrained mode at 30 degrees </summary>
        internal static Mesh2Input WindowWedge(int seed)
        {
            var rnd = new Random(seed);
            double phi = 30 * Math.PI / 180 - 6e-10;
            var xy = new List<double> { 0, 0, 1, 0, Math.Cos(phi), Math.Sin(phi), -0.5, -0.5, 1.5, -0.5, 1.5, 1.2, -0.5, 1.2 };
            int inside = rnd.Next(1, 5);
            for (int i = 0; i < inside; ++i) {
                double r = 0.05 + 0.85 * rnd.NextDouble(), a = (0.05 + 0.9 * rnd.NextDouble()) * phi;
                xy.Add(r * Math.Cos(a)); xy.Add(r * Math.Sin(a));
            }
            int along = rnd.Next(0, 4);
            for (int i = 0; i < along; ++i) { xy.Add(0.1 + 0.8 * rnd.NextDouble()); xy.Add(0); }
            var input = Generators.Literal(xy.ToArray());
            input.Segments.Add(new SegmentInput(0, 1)); input.Segments.Add(new SegmentInput(0, 2));
            input.Rings.Add(new RingInput(new[] { 3, 4, 5, 6 }, false));
            input.MinAngleDeg = 30;
            input.ConstrainedQuality = true;
            return input;
        }

        // (seeds that the oracle judged INVALID, AngleBelowBound, before the fix: 2, 5, 6, 10 and 13 of the first 400)
        internal static readonly int[] WindowSeeds = { 2, 5, 6, 10, 13 };
        public static IEnumerable<object[]> Seeds() => WindowSeeds.Select(s => new object[] { s });

        [Theory]
        [MemberData(nameof(Seeds))]
        public void InputAngleInTheWindow_IsNotTreatedAsSmall(int seed)
        {
            var input = WindowWedge(seed);
            var output = new QualityMesh2Candidate().Run(input);
            var report = Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, "seed " + seed + ": " + report);
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        [Theory]
        [MemberData(nameof(Similarities))]
        public void WindowWedge_IsValid_UnderEverySimilarity(string name)
        {
            var s = Similarity.ByName(name);
            var input = WindowWedge(2);
            for (int i = 0; i < input.Count; ++i) { var q = s.Apply(new Vector3d(input.X[i], input.Y[i], 0)); input.X[i] = q.x; input.Y[i] = q.y; }
            var output = new QualityMesh2Candidate().Run(input);
            var report = Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(output.Status == Mesh2Status.Success && report.Ok, name + ": " + report);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The small-angle rule of the constrained-quality mode, through the public API (MESHING2D_SMALL_ANGLES.md, owner decision
    /// 2026-11-06): a subsegment is not split for a vertex that refinement made on exactly one partner source of a small input angle,
    /// at the apex region. Without it a hull edge at a small angle to a segment drove a cascade of splits towards the apex: ext/cdt/island
    /// gave 8 879 triangles at 30 degrees, 2 971 with the rule; the wedge below about 30 times as many as with it. Intentional behaviour
    /// change: the output of QualityMesh2 with Conforming = false and MinAngle &gt; 0.
    /// </summary>
    public class QualityMesh2SmallAngleRuleTests
    {
        /// <summary> island-like: a segment from the hull corner A = (0, 0) to P = (8, 8 tan(degrees)), at that angle to the hull edge A-B
        /// (B = (10, 0); the third hull point (0, 6) makes the other angles 59 degrees and more, but 31 at B); no ring, so the domain is the
        /// hull and its edges are constraints (D13) </summary>
        internal static Mesh2Input HullWedge(double angle, double degrees = 2.6, double snap = 0)
        {
            double t = Math.Tan(degrees * Math.PI / 180);
            var input = Generators.Literal(0, 0, 10, 0, 0, 6, 8, Math.Round(8 * t, 12));
            input.Segments.Add(new SegmentInput(0, 3));
            input.MinAngleDeg = angle;
            input.ConstrainedQuality = true;
            input.SnapTolerance = snap;
            return input;
        }

        static void AssertValid(Mesh2Input input, Mesh2Output output, string what, OracleExpect expect = null)
        {
            Assert.True(output.Status == Mesh2Status.Success, what + ": " + output.Status + " " + output.FailureKind);
            Assert.False(output.SteinerLimitReached, what + ": the Steiner limit was reached (the angle check would be skipped)");
            var report = Oracle.Check(input, output, expect ?? new OracleExpect { Milestone = Milestone.M3 });
            Assert.True(report.Ok, what + ": " + report);
        }

        /// <summary> the wedge at 2.6 and 1 degrees, 20 (lenses) and 30 degrees: valid, and a few dozen triangles at most (master: 59 to
        /// 430, the cascade towards the apex; with the rule 11 to 22) </summary>
        [Theory]
        [InlineData(2.6, 20)]
        [InlineData(2.6, 30)]
        [InlineData(1.0, 20)]
        [InlineData(1.0, 30)]
        public void HullWedge_HasNoCascade(double degrees, double angle)
        {
            var input = HullWedge(angle, degrees);
            var output = new QualityMesh2Candidate().Run(input);
            AssertValid(input, output, degrees + " at " + angle);
            Assert.True(output.Triangles.Length <= 30, degrees + " at " + angle + ": " + output.Triangles.Length + " triangles");
        }

        /// <summary> the wedge on a snap grid (a pixel of 2^-8), where its chains share pixels near the apex: valid (no pinch, no
        /// off-grid vertex), and still no cascade (master: 57 and 178 triangles) </summary>
        [Theory]
        [InlineData(20)]
        [InlineData(30)]
        public void HullWedge_OnTheGrid_IsValid(double angle)
        {
            var input = HullWedge(angle, 2.6, 1.0 / 256);
            var output = new QualityMesh2Candidate().Run(input);
            AssertValid(input, output, "grid at " + angle);
            Assert.True(output.Triangles.Length <= 40, "grid at " + angle + ": " + output.Triangles.Length + " triangles");
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        /// <summary> the wedge under every similarity: the others pass the oracle, the 2^k scales give the same mesh bit for bit </summary>
        [Theory]
        [MemberData(nameof(Similarities))]
        public void HullWedge_UnderEverySimilarity(string name)
        {
            var s = Similarity.ByName(name);
            var plain = HullWedge(30);
            var moved = HullWedge(30);
            for (int i = 0; i < plain.Count; ++i) { var q = s.Apply(new Vector3d(plain.X[i], plain.Y[i], 0)); moved.X[i] = q.x; moved.Y[i] = q.y; }
            var b = new QualityMesh2Candidate().Run(moved);
            AssertValid(moved, b, name);
            if (s.IsExact) {
                var a = new QualityMesh2Candidate().Run(plain);
                Assert.Equal(a.VX.Select(v => v * s.Scale), b.VX);
                Assert.Equal(a.VY.Select(v => v * s.Scale), b.VY);
                Assert.Equal(a.Triangles.SelectMany(t => t), b.Triangles.SelectMany(t => t));
            }
        }

        /// <summary> the wedge scaled by 2^-500 and 2^200: the same mesh bit for bit (the pair's angle, apex and radii are computed in a
        /// scale by a power of two; the meeting test is exact) </summary>
        [Theory]
        [InlineData(-500)]
        [InlineData(200)]
        public void HullWedge_AtExtremeScales_IsBitIdentical(int exponent)
        {
            double f = Math.Pow(2, exponent);
            var plain = HullWedge(30, 1.0);
            var moved = HullWedge(30, 1.0);
            for (int i = 0; i < plain.Count; ++i) { moved.X[i] = plain.X[i] * f; moved.Y[i] = plain.Y[i] * f; }
            var a = new QualityMesh2Candidate().Run(plain);
            var b = new QualityMesh2Candidate().Run(moved);
            Assert.Equal(Mesh2Status.Success, a.Status);
            Assert.False(b.SteinerLimitReached);
            Assert.Equal(a.VX.Select(v => v * f), b.VX);
            Assert.Equal(a.VY.Select(v => v * f), b.VY);
            Assert.Equal(a.Triangles.SelectMany(t => t), b.Triangles.SelectMany(t => t));
        }

        /// <summary> one mesher, computed twice, in parallel and serially: the same mesh </summary>
        [Fact]
        public void HullWedge_IsDeterministic()
        {
            var input = ConstrainedDelaunayMesh2Candidate.Convert(HullWedge(30, 1.0));
            var mesher = new QualityMesh2 { MinAngle = 30, Conforming = false };
            var first = mesher.Compute(input).Mesh;
            Assert.False(first.SteinerLimitReached);
            var results = new ConstrainedMesh2[8];
            Parallel.For(0, results.Length, i => results[i] = mesher.Compute(input).Mesh);
            foreach (var m in results.Concat(new[] { mesher.Compute(input).Mesh })) {
                Assert.Equal(first.Vertices, m.Vertices);
                Assert.Equal(first.Triangles, m.Triangles);
                Assert.Equal(first.BadTriangles, m.BadTriangles);
            }
        }

        public static IEnumerable<object[]> SmallAngleRows() => new[] { "F-38/a", "F-38/b", "F-38/c", "F-38/d", "F-38/e" }.Select(id => new object[] { id });

        /// <summary>
        /// The catalogue's small-angle rows in the constrained mode, with the angle check on (their rows have AngleGuaranteed = false, so
        /// the golden rows check nothing about the excuses): every triangle meets the bound or is excused by the oracle. Master passes
        /// these too; the fan (d) drops from 22 384 triangles to 3 165
        /// </summary>
        [Theory]
        [MemberData(nameof(SmallAngleRows))]
        public void CatalogueSmallAngleRows_ConstrainedMode_AngleChecked(string id)
        {
            var row = Catalogue.Rows().Single(r => r.Id == id);
            var input = row.Case.Input;
            input.ConstrainedQuality = true;
            var output = new QualityMesh2Candidate().Run(input);
            var expect = row.Case.Expect;
            expect.AngleGuaranteed = true;
            AssertValid(input, output, id, expect);
            if (id == "F-38/d") Assert.True(output.Triangles.Length <= 5000, id + ": " + output.Triangles.Length + " triangles");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Refinement of inputs scaled into the subnormal range. A split point of a piece shorter than 2^-1026 rounds to the subnormal step
    /// (2^-1074), which is no small fraction of the piece: on the hull it rounded outside the domain, on a constraint off its source
    /// (found with the reference comparison: m1/subnormal-32 with an angle bound; BoundaryNotConstrained, SubsegmentUnsourced,
    /// TriangleOutsideDomain, AreaMismatch). Such a piece is now split only at a point exactly on it.
    /// </summary>
    public class QualityMesh2SubnormalTests
    {
        /// <summary> the constructed vertices on the boundary of a mesh of points only (its subsegments are pieces of hull edges):
        /// exactly on an edge of the input's hull, or off every hull edge (a split point rounded next to its edge) </summary>
        static void HullSplits(Mesh2Input input, Mesh2Output output, out int exact, out int rounded)
        {
            var pts = Enumerable.Range(0, input.Count).Select(i => new Vector2d(input.X[i], input.Y[i])).OrderBy(p => p.x).ThenBy(p => p.y).ToList();
            var hull = new List<Vector2d>();
            for (int pass = 0; pass < 2; ++pass) {
                int start = hull.Count;
                for (int j = 0; j < pts.Count; ++j) {
                    var p = pass == 0 ? pts[j] : pts[pts.Count - 1 - j];
                    while (hull.Count >= start + 2 && ExactPredicates.Orient2d(hull[hull.Count - 2], hull[hull.Count - 1], p) <= 0) hull.RemoveAt(hull.Count - 1);
                    hull.Add(p);
                }
                hull.RemoveAt(hull.Count - 1);
            }
            var inputVertices = new HashSet<int>(output.InputToVertex);
            var onBoundary = new HashSet<int>(output.Subsegments.SelectMany(s => new[] { s.A, s.B }).Where(v => !inputVertices.Contains(v)));
            exact = rounded = 0;
            foreach (int v in onBoundary) {
                var q = new Vector2d(output.VX[v], output.VY[v]);
                bool on = false;
                for (int i = 0; i < hull.Count && !on; ++i) on = ExactPredicates.Orient2d(hull[i], hull[(i + 1) % hull.Count], q) == 0;
                if (on) ++exact; else ++rounded;
            }
        }

        /// <summary> the case m1/subnormal-32 (32 points with 20-bit integer coordinates) at scale 2^exponent </summary>
        static Mesh2Input Points(int exponent, double angle, bool constrained)
        {
            var input = Generators.Transform(Generators.UniformInt(32, 20, 8), exponent);
            input.MinAngleDeg = angle;
            input.ConstrainedQuality = constrained;
            return input;
        }

        static OracleReport Judge(Mesh2Input input, out Mesh2Output output)
        {
            output = new QualityMesh2Candidate().Run(input);
            return Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 });
        }

        /// <summary> the mesh keeps the domain and its boundary: no violation but angles below the bound (a piece that cannot be split
        /// exactly stays, and its encroaching triangles with it, as with any unsplittable piece) </summary>
        static void AssertDomainKept(OracleReport report, Mesh2Output output, string what)
        {
            Assert.True(output.Status == Mesh2Status.Success && output.Triangles.Length > 0, what + ": " + output.Status);
            var other = report.Violations.Where(v => v.Kind != Violation.AngleBelowBound).ToList();
            Assert.True(other.Count == 0, what + ": " + string.Join("; ", other));
        }

        [Theory]
        [InlineData(20.0, false, 6)]
        [InlineData(25.0, false, 8)]
        [InlineData(30.0, false, 14)]
        [InlineData(20.0, true, 5)]
        [InlineData(25.0, true, 7)]
        [InlineData(30.0, true, 14)]
        public void SubnormalPoints_KeepTheHullAndTheDomain(double angle, bool constrained, int badNow)
        {
            var input = Points(-1074, angle, constrained);
            var report = Judge(input, out var output);
            string what = angle + (constrained ? " constrained" : "");
            AssertDomainKept(report, output, what);
            // refinement still works where it can: Steiner points are added, and the triangles left below the bound stay few (today's
            // count, with a margin; a refiner that refused every tiny piece leaves more)
            Assert.True(output.VX.Length > input.Count, what + ": no Steiner point");
            int bad = report.Violations.Count(v => v.Kind == Violation.AngleBelowBound);
            Assert.True(bad <= badNow + 3, what + ": " + bad + " triangles below the bound");
        }

        [Fact]
        public void TinyPieces_AreSplitExactlyWherePossible_AndTheThresholdHolds()
        {
            // where the piece's split point is exactly on its hull edge (even integer differences) it is used: at 2^-1074 and below the
            // threshold. Above it (pieces of 2^-1026 and longer) a rounded point is used as in the normal range. The 20-bit points span
            // 2^20 steps, their refined hull pieces 2^2 to 2^20: at 2^-1044 one rounded split is still on a piece of 2^-1026, at
            // 2^-1046 none is. This pins the threshold to one exponent (measured: -1028 and below let rounded splits through at 2^-1046,
            // -1025 and above refuse the one at 2^-1044; -1027 passes, and is as safe: half a step is then at most 2^-48 of the piece).
            var tiny = Points(-1074, 30, false);
            var report = Judge(tiny, out var output);
            AssertDomainKept(report, output, "2^-1074");
            HullSplits(tiny, output, out int exact, out int rounded);
            Assert.True(exact > 0 && rounded == 0, "2^-1074: " + exact + " exact, " + rounded + " rounded");
            var below = Points(-1046, 30, false);
            report = Judge(below, out output);
            AssertDomainKept(report, output, "2^-1046");
            HullSplits(below, output, out exact, out rounded);
            Assert.True(exact > 0 && rounded == 0, "2^-1046: " + exact + " exact, " + rounded + " rounded");
            var above = Points(-1044, 30, false);
            report = Judge(above, out output);
            AssertDomainKept(report, output, "2^-1044");
            HullSplits(above, output, out exact, out rounded);
            Assert.True(rounded > 0, "2^-1044: " + exact + " exact, " + rounded + " rounded");
        }

        /// <summary> the points of m1/subnormal-32 rotated (coordinates with full mantissas: split points are then rarely exactly on
        /// their segment), scaled by 2^exponent </summary>
        static Mesh2Input Rotated(int exponent, double angle)
        {
            var input = Points(0, angle, false);
            double c = Math.Cos(0.3), sn = Math.Sin(0.3), f = Math.Pow(2, exponent);
            for (int i = 0; i < input.Count; ++i) {
                double x = input.X[i], y = input.Y[i];
                input.X[i] = (c * x - sn * y) * f; input.Y[i] = (sn * x + c * y) * f;
            }
            return input;
        }

        [Theory]
        [InlineData(false)]
        [InlineData(true)]
        public void EveryScale_KeepsTheDomain_AndNormalScalesGiveTheSameMesh(bool rotated)
        {
            // across the subnormal boundary: below it the domain is kept; where every piece is longer than 2^-1026 nothing changes,
            // and the mesh is the unit-scale mesh scaled by 2^k bit for bit
            Func<int, Mesh2Input> make = e => rotated ? Rotated(e, 30) : Points(e, 30, false);
            var unit = new QualityMesh2Candidate().Run(make(0));
            Assert.True(Oracle.Check(make(0), unit, new OracleExpect { Milestone = Milestone.M3 }).Ok);
            foreach (int e in new[] { -1074, -1070, -1064, -1058, -1052, -1046, -1040, -1034, -1028, -1022, -1016, -1010, -1000, -990, -900, -500, 200 }) {
                // (the rotated points are rounded once more where they are subnormal: another input there, judged on its own)
                var input = make(e);
                var report = Judge(input, out var output);
                AssertDomainKept(report, output, "2^" + e);
                if (e < -1022) continue;
                double s = Math.Pow(2, e);
                Assert.Equal(unit.VX.Length, output.VX.Length);
                for (int i = 0; i < unit.VX.Length; ++i)
                    Assert.True(output.VX[i] == unit.VX[i] * s && output.VY[i] == unit.VY[i] * s, "2^" + e + ", vertex " + i);
                Assert.Equal(unit.Triangles.Select(t => string.Join(",", t)), output.Triangles.Select(t => string.Join(",", t)));
                Assert.True(report.Ok, "2^" + e + ": " + report);
            }
        }

        public static IEnumerable<object[]> Similarities() => Similarity.All().Select(s => new object[] { s.Name });

        [Theory]
        [MemberData(nameof(Similarities))]
        public void Similarity_LeavesTheMeshValid(string name)
        {
            // the change applies below 2^-1026 only: under every similarity of the harness the case meshes as before, valid
            var s = Similarity.ByName(name);
            var input = Points(-10, 30, false);
            for (int i = 0; i < input.Count; ++i) { var q = s.Apply(new Vector3d(input.X[i], input.Y[i], 0)); input.X[i] = q.x; input.Y[i] = q.y; }
            var report = Judge(input, out var output);
            Assert.True(output.Triangles.Length > 0 && report.Ok, name + ": " + report);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The M3 mesher <see cref="QualityMesh2"/>. Its catalogue rows (m3.refine and the M3 rows of the M2 features) run through the
    /// oracle in Meshing2CatalogueTests; these tests add fuzzing, the CLAUDE.md requirements and the API.
    /// </summary>
    public class QualityMesh2Tests
    {
        static OracleReport Judge(Mesh2Input input, out Mesh2Output output)
        {
            output = new QualityMesh2Candidate().Run(input);
            return Oracle.Check(input, output, new OracleExpect { Milestone = Milestone.M3 });
        }

        static int AddPoint(Mesh2Input input, double x, double y)
        {
            input.X = input.X.Concat(new[] { x }).ToArray();
            input.Y = input.Y.Concat(new[] { y }).ToArray();
            return input.Count - 1;
        }

        static Mesh2Input Fuzz(int seed)
        {
            var r = new Random(seed);
            var input = new Mesh2Input { X = new double[] { 0, 10, 10, 0 }, Y = new double[] { 0, 0, 10, 10 } };
            if (seed % 3 != 0) input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false, 1));
            int m = 2 + r.Next(6);
            for (int i = 0; i < m; ++i)
                input.Segments.Add(new SegmentInput(AddPoint(input, r.Next(11), r.Next(11)), AddPoint(input, r.Next(11), r.Next(11)), r.Next(3)));
            for (int i = 0; i < r.Next(5); ++i) AddPoint(input, r.NextDouble() * 10, r.NextDouble() * 10);
            input.MinAngleDeg = new[] { 0, 20, 25, 30 }[seed % 4];
            if (seed % 5 == 0) input.MaxArea = 0.5;
            input.SteinerLimit = 20000;
            return input;
        }

        [Fact]
        public void Fuzz_EveryResultPassesTheOracle()
        {
            for (int seed = 0; seed < 60; ++seed) {
                var input = Fuzz(seed);
                var report = Judge(input, out var output);
                Assert.True(output.Status == Mesh2Status.Success, "seed " + seed + ": " + output.FailureKind);
                Assert.True(report.Ok, "seed " + seed + ": " + report);
            }
        }

        /// <summary> holes, regions with and without an area bound, locked segments: every input class the class doc advertises </summary>
        static Mesh2Input FuzzDomains(int seed)
        {
            var r = new Random(1000 + seed);
            var input = new Mesh2Input { X = new double[] { 0, 10, 10, 0 }, Y = new double[] { 0, 0, 10, 10 } };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false, 1));
            int holes = 1 + r.Next(4);
            for (int h = 0; h < holes; ++h) {
                // small triangles in disjoint cells of a 4 x 4 grid, so the rings neither cross nor touch
                double cx = 1.25 + 2.5 * ((seed + 5 * h) % 4), cy = 1.25 + 2.5 * (((seed + 5 * h) / 4 + h) % 4), s = 0.2 + r.NextDouble();
                int a = AddPoint(input, cx - s, cy - s * r.NextDouble()), b = AddPoint(input, cx + s, cy - s * r.NextDouble()), c = AddPoint(input, cx + s * (r.NextDouble() - 0.5), cy + s);
                switch (r.Next(3)) {
                    case 0: input.Rings.Add(new RingInput(new[] { a, b, c }, true, 2)); break;
                    case 1: input.Regions.Add(new RegionInput { Ring = new[] { a, b, c }, Label = 7 + h }); break;
                    default: input.Regions.Add(new RegionInput { Ring = new[] { a, b, c }, Label = 7 + h, MaxArea = 0.01 }); break;
                }
            }
            input.MinAngleDeg = 20 + r.Next(14);
            input.SteinerLimit = 20000;
            return input;
        }

        [Fact]
        public void Fuzz_HolesAndRegions_PassTheOracle()
        {
            // review of M3: a split lifts the constraint of its piece, the flips around it may cross the boundary, and a small hole or
            // region enclosed by constraints kept the tags of the slots it was rewritten into (filled holes, wrong labels)
            for (int seed = 0; seed < 80; ++seed) {
                var input = FuzzDomains(seed);
                var report = Judge(input, out var output);
                Assert.True(output.Status == Mesh2Status.Success, "seed " + seed + ": " + output.FailureKind);
                Assert.True(report.Ok, "seed " + seed + ": " + report);
            }
        }

        static Mesh2Input SmallHole(bool region)
        {
            var input = new Mesh2Input { X = new double[] { 0, 10, 10, 0, 4, 6, 5, 5 }, Y = new double[] { 0, 0, 10, 10, 5, 5, 5.3, 4.7 } };
            input.Rings.Add(new RingInput(new[] { 0, 1, 2, 3 }, false));
            if (region) input.Regions.Add(new RegionInput { Ring = new[] { 4, 5, 6 }, Label = 7 });
            else input.Rings.Add(new RingInput(new[] { 4, 5, 6 }, true));
            input.Conforming = true;
            return input;
        }

        [Theory]
        [InlineData(false)]
        [InlineData(true)]
        public void Split_NextToASmallHoleOrRegion_KeepsItsTag(bool region)
        {
            // the review's case: the encroached hole edge 4-5 is split, its constraint lifted; the hole stays empty, the region labelled
            var input = SmallHole(region);
            var report = Judge(input, out var o);
            Assert.True(report.Ok, report.ToString());
            double area = 0;
            for (int t = 0; t < o.Triangles.Length; ++t) {
                var a = o.Triangles[t];
                double at = 0.5 * ((o.VX[a[1]] - o.VX[a[0]]) * (o.VY[a[2]] - o.VY[a[0]]) - (o.VY[a[1]] - o.VY[a[0]]) * (o.VX[a[2]] - o.VX[a[0]]));
                area += at;
            }
            Assert.Equal(region ? 100 : 100 - 0.3, area, 9);
            if (region) {
                double labelled = 0;
                for (int t = 0; t < o.Triangles.Length; ++t) {
                    if (o.TriangleLabels[t] != 7) continue;
                    var a = o.Triangles[t];
                    labelled += 0.5 * ((o.VX[a[1]] - o.VX[a[0]]) * (o.VY[a[2]] - o.VY[a[0]]) - (o.VY[a[1]] - o.VY[a[0]]) * (o.VX[a[2]] - o.VX[a[0]]));
                }
                Assert.Equal(0.3, labelled, 9);
            }
        }

        [Theory]
        [InlineData(-560)]
        [InlineData(-540)]
        [InlineData(-500)]
        [InlineData(-200)]
        [InlineData(200)]
        [InlineData(225)]
        public void ExtremeScales_RefineTheSameMesh(int exponent)
        {
            // review of M3: at 2^-500 the squared lengths underflowed and no triangle counted as bad (silent success)
            var input = Sample(); input.MaxArea = null;
            var scaled = Sample(); scaled.MaxArea = null;
            for (int i = 0; i < input.Count; ++i) { scaled.X[i] = ExactPoint3.ScaleB(input.X[i], exponent); scaled.Y[i] = ExactPoint3.ScaleB(input.Y[i], exponent); }
            Assert.True(Judge(input, out var a).Ok);
            var report = Judge(scaled, out var b);
            Assert.True(report.Ok, report.ToString());
            Assert.Equal(Canonical(a), Canonical(b));
            for (int i = 0; i < a.VX.Length; ++i) {
                Assert.Equal(ExactPoint3.ScaleB(a.VX[i], exponent), b.VX[i]);
                Assert.Equal(ExactPoint3.ScaleB(a.VY[i], exponent), b.VY[i]);
            }
        }

        static Mesh2Input FuzzLocked(int seed)
        {
            var input = Fuzz(seed);
            foreach (var s in input.Segments) s.Locked = s.Marker == 1;
            if (input.MinAngleDeg == 0) input.MinAngleDeg = 20;
            return input;
        }

        [Fact]
        public void Fuzz_LockedSegments_StayWholeAndValid()
        {
            // review of M3: near locked segments the bounds are not met yet (m3.locks, documented on QualityMesh2). What holds: the
            // mesh is valid, locked segments keep their vertices, and every triangle left below the angle is in the bad list
            var allowed = new HashSet<Violation> { Violation.AngleBelowBound, Violation.AreaAboveBound };
            for (int seed = 0; seed < 60; ++seed) {
                var input = FuzzLocked(seed);
                var report = Judge(input, out var output);
                Assert.True(output.Status == Mesh2Status.Success, "seed " + seed + ": " + output.FailureKind);
                var other = report.Violations.Where(v => !allowed.Contains(v.Kind)).ToList();
                Assert.True(other.Count == 0, "seed " + seed + ": " + string.Join("; ", other.Select(v => v.Kind + ": " + v.Detail)));
                foreach (var s in input.Segments.Where(s => s.Locked)) {
                    int a = output.InputToVertex[s.A], b = output.InputToVertex[s.B];
                    // whole unless another segment crosses it (then split only at crossings, which are not Steiner points of refinement)
                    bool crossed = output.Subsegments.Count(q => q.Marker == s.Marker) > input.Segments.Count(q => q.Marker == s.Marker);
                    if (!crossed) Assert.Contains(output.Subsegments, q => (q.A == a && q.B == b) || (q.A == b && q.B == a));
                }
            }
        }

        /// <summary>
        /// A polygon with a narrow wedge at a small angle (0.5 to 5 degrees) between two ring edges from one vertex, at coordinates in
        /// the thousands, the wedge inside or outside the domain (corpus run: earcut's water and water-huge)
        /// </summary>
        static Mesh2Input Wedge(int seed)
        {
            var r = new Random(2000 + seed);
            double ax = 4000 + r.Next(200), ay = 3000 + r.Next(200), len = 20 + r.Next(80), angle = (0.5 + 4.5 * r.NextDouble()) * Math.PI / 180;
            double dir = r.NextDouble() * 2 * Math.PI;
            // A, then B along dir, C at the small angle from it; the rest of the ring closes around them
            var pts = new List<double[]> { new[] { ax, ay } };
            pts.Add(new[] { Math.Round(ax + len * Math.Cos(dir)), Math.Round(ay + len * Math.Sin(dir)) });
            pts.Add(new[] { Math.Round(ax + 1.3 * len * Math.Cos(dir + angle)), Math.Round(ay + 1.3 * len * Math.Sin(dir + angle)) });
            double far = 3 * len;
            pts.Add(new[] { Math.Round(ax + far * Math.Cos(dir + angle + 1.2)), Math.Round(ay + far * Math.Sin(dir + angle + 1.2)) });
            pts.Add(new[] { Math.Round(ax + far * Math.Cos(dir + Math.PI)), Math.Round(ay + far * Math.Sin(dir + Math.PI)) });
            pts.Add(new[] { Math.Round(ax + far * Math.Cos(dir - 1.2)), Math.Round(ay + far * Math.Sin(dir - 1.2)) });
            var input = new Mesh2Input { X = pts.Select(p => p[0]).ToArray(), Y = pts.Select(p => p[1]).ToArray() };
            // the wedge between A-B and A-C is outside (ring A, C, ..., B) or the domain is the wedge side (ring reversed)
            var ring = seed % 2 == 0 ? new[] { 0, 2, 3, 4, 5, 1 } : new[] { 0, 1, 5, 4, 3, 2 };
            input.Rings.Add(new RingInput(ring, false, 1));
            if (seed % 3 == 0) input.Segments.Add(new SegmentInput(0, 3, 2));
            input.MinAngleDeg = new[] { 0, 20, 30 }[seed % 3];
            input.SteinerLimit = 30000;
            return input;
        }

        /// <summary>
        /// The tag check (tags against domain membership from scratch, after every operation) on the catalogue rows. On a hull domain a
        /// hull edge whose split point rounds inwards leaves a sliver between its pieces and the old, now unconstrained hull edge: the
        /// tags put it outside the constrained hull, and so must the check (F-35 and F-3/c failed it; the check reached them only when another test had switched it on in parallel).
        /// Only the M3 rows reach the refiner and its check, so only they run; they run in parallel, the per-thread switch set on each
        /// worker (serially over all covered rows this one test took 951 s on net10.0, the longest stretch of the suite).
        /// </summary>
        [Fact]
        public void TagCheck_HoldsOnTheCoveredCatalogueRows()
        {
            var rows = Catalogue.Rows().Where(r => r.Case != null && r.State == CaseState.Covered && !r.Slow && r.Case.Milestone == Milestone.M3).ToList();
            Assert.True(rows.Count > 20, rows.Count + " M3 rows");
            var wrong = new System.Collections.Concurrent.ConcurrentBag<string>();
            Parallel.ForEach(rows, row => {
                QualityMesh2.Refiner.CheckTagsForTests = true;
                try { CandidateRegistry.For(Milestone.M3).Run(row.Case.Input); }
                catch (InvalidOperationException e) { wrong.Add(row.Id + ": " + e.Message); }   // a wrong tag
                finally { QualityMesh2.Refiner.CheckTagsForTests = false; }
            });
            Assert.True(wrong.IsEmpty, string.Join("\n", wrong.OrderBy(w => w, StringComparer.Ordinal)));
        }

        /// <summary>
        /// The switch of the slow tag check is per thread: a test that turns it on must not reach meshers other tests run in parallel
        /// (master CI failed F-35 in Meshing2OracleModesTests intermittently while Fuzz_NarrowWedges had it on).
        /// </summary>
        [Fact]
        public void TagCheckSwitch_DoesNotReachOtherThreads()
        {
            QualityMesh2.Refiner.CheckTagsForTests = true;
            try {
                bool seen = true;
                var thread = new Thread(() => seen = QualityMesh2.Refiner.CheckTagsForTests);
                thread.Start();
                thread.Join();
                Assert.False(seen);
                Assert.True(QualityMesh2.Refiner.CheckTagsForTests);
            } finally { QualityMesh2.Refiner.CheckTagsForTests = false; }
        }

        /// <summary>
        /// D13: on a hull domain the hull is the boundary, so a segment from a hull vertex at a small angle to a hull edge is a small input
        /// angle like two segments. Refinement must stop at it (Shewchuk 2002) instead of cascading into the apex until the merge tolerance
        /// stops it, leaving triangles below the bound that nothing excuses (found with CDT's issue-211 in the reference comparison: a
        /// segment at 0.096 degrees to a hull edge; 7 triangles below 20 degrees, and the Steiner limit at 30 degrees).
        /// </summary>
        [Theory]
        [InlineData(20.0, 0.0134)]   // 0.096 degrees, as in issue-211
        [InlineData(30.0, 0.0134)]
        [InlineData(20.0, 0.25)]     // 1.8 degrees
        [InlineData(20.0, -2.0)]     // 0.096 degrees, with an input point at (2, 0) on the hull edge (its hull sources are split there)
        public void SmallAngle_BetweenASegmentAndTheHull_IsAnInputAngle(double angle, double rise)
        {
            // a point set (hull domain): the segment from the hull vertex (0, 0) to (8, rise), just above the hull edge to (10, 0)
            bool collinear = rise < 0;
            if (collinear) rise = 0.0134;
            var input = new Mesh2Input { X = new[] { 0.0, 10, 10, 0, 8, 3, collinear ? 2 : 3 }, Y = new[] { 0, 0, 10, 10, rise, 6, collinear ? 0 : 6 }, MinAngleDeg = angle, SteinerLimit = 20000 };
            input.Segments.Add(new SegmentInput(0, 4));
            var report = Judge(input, out var output);
            Assert.Equal(Mesh2Status.Success, output.Status);
            Assert.False(output.SteinerLimitReached, "refinement cascaded into the apex");
            Assert.True(report.Ok, report.ToString());
        }

