using System;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// SnapGrid's double filters against their exact tests. Pixel against the exact quotient (PixelExact): the same index for
    /// every x, on pixel boundaries (x a half-integer multiple of w, and its neighbouring doubles), at random, for decimal and binary widths, near 2^50 pixels and
    /// beyond, and for zero, subnormal and huge values. CrossesInterior's filter against CrossesInteriorExact: where the filter
    /// decides it agrees, on segments through pixel corners, along pixel sides, ending on them, and at random, in frames 2^k
    /// </summary>
    public class SnapGridPixelFilterTests
    {
        static double Up(double x) => BitConverter.Int64BitsToDouble(BitConverter.DoubleToInt64Bits(x) + (x >= 0 ? 1 : -1));
        static double Down(double x) => x == 0 ? -double.Epsilon : BitConverter.Int64BitsToDouble(BitConverter.DoubleToInt64Bits(x) - (x > 0 ? 1 : -1));

        /// <summary>Z3Pilot's SAT witness for the test-local f &lt;= r mutant. The
        /// exact input is the binary64 immediately below 1/2, W=1: the rounded
        /// sum is 1 but the exact pixel is 0. Replayed through the actual code.</summary>
        [Fact]
        public void SmtWitness_IntegralRoundedSumMustTakeTheExactPath()
        {
            double x = BitConverter.Int64BitsToDouble(4602678819172646911L);
            foreach (int exponent in new[] { -500, -10, 0, 10, 500 }) {
                double width = Math.Pow(2, exponent);
                double input = x * width;
                var grid = new SnapGrid(width);
                Assert.Equal(0, grid.PixelExact(input));
                Assert.Equal(0, grid.Pixel(input));
                // Controlled fault, no production mutation: accept f == r too.
                double r = input / width + 0.5;
                Assert.Equal(1, (long)Math.Floor(r));
            }
        }

        [Fact]
        public void Filter_AgreesWithTheExactQuotient()
        {
            var rnd = new Random(20261104);
            // (negative, zero-like and extreme widths too: the filter steps aside where w &lt;= 0, and x / w may underflow or overflow)
            double[] widths = { 0.01, 0.25, 0.3, 1.0 / 3, 1, 1e-3, 7.5, 1e-9, 0.1 * 3, 2.5e6, -0.3, -1, 5e-324, 1e-310, 1e300 };
            int checkedValues = 0, onBoundary = 0;
            foreach (double w in widths) {
                var grid = new SnapGrid(w);
                void Check(double x)
                {
                    if (double.IsNaN(x) || double.IsInfinity(x)) return;
                    ++checkedValues;
                    long exact;
                    try { exact = grid.PixelExact(x); } catch (OverflowException) { return; }   // (beyond a long: as before)
                    Assert.True(grid.Pixel(x) == exact, "w " + w.ToString("R") + ", x " + x.ToString("R"));
                }
                Check(0); Check(-0.0); Check(double.Epsilon); Check(-double.Epsilon); Check(1e-300); Check(-1e-300); Check(1e300); Check(-1e300);
                // r = -2^52 + 1/2 and its neighbours (f = -2^52: f - 1/2 is a tie)
                foreach (double t in new[] { -4503599627370495.5, -4503599627370496.0, -4503599627370494.5, 4503599627370495.5 }) { Check(t * w); Check(Up(t * w)); Check(Down(t * w)); }
                for (int n = 0; n < 4000; ++n) {
                    // around a pixel boundary (k + 1/2) w, as close as the doubles go, at magnitudes up to and past 2^50 pixels
                    long k = (long)((rnd.NextDouble() - 0.5) * Math.Pow(2, rnd.Next(0, 53)));
                    double b = (k + 0.5) * w;
                    if ((b / w) == k + 0.5) ++onBoundary;
                    Check(b); Check(Up(b)); Check(Down(b)); Check(Up(Up(b))); Check(Down(Down(b)));
                    Check(k * w);
                    // anywhere
                    Check((rnd.NextDouble() - 0.5) * w * Math.Pow(10, rnd.Next(0, 16)));
                }
            }
            Assert.True(checkedValues > 200000 && onBoundary > 1000, checkedValues + " values, " + onBoundary + " on a boundary in doubles");
        }

        [Fact]
        public void CrossesInteriorFilter_AgreesWithTheExactTest()
        {
            var rnd = new Random(7);
            double[] widths = { 0.01, 0.25, 0.3, 1.0 / 3, 1, 7.5, 1e-6 };
            int[] frames = { -520, -470, -200, -30, 0, 30, 200, 440 };
            int decided = 0, undecided = 0, crossing = 0;
            foreach (double w0 in widths)
                foreach (int k in frames) {
                    double f = Math.Pow(2, k), w = w0 * f;
                    var grid = new SnapGrid(w);
                    for (int n = 0; n < 3000; ++n) {
                        long kx = rnd.Next(-50, 50) + (rnd.Next(4) == 0 ? (long)1 << rnd.Next(20, 50) : 0), ky = rnd.Next(-50, 50);
                        // pixel indices from 2^52 up, where k -+ 1/2 is no double (the filter leaves them to the exact test)
                        if (rnd.Next(10) == 0) kx = ((long)1 << rnd.Next(52, 58)) + rnd.Next(0, 4);
                        double cx = kx * w, cy = ky * w, h = w / 2;
                        // endpoints: on corners, on sides, near them by a few ulps, or anywhere nearby
                        Vector2d Pick()
                        {
                            switch (rnd.Next(5)) {
                                case 0: return new Vector2d(cx + (rnd.Next(2) * 2 - 1) * h, cy + (rnd.Next(2) * 2 - 1) * h);
                                case 1: return new Vector2d(cx + (rnd.Next(2) * 2 - 1) * h, cy + (rnd.NextDouble() - 0.5) * 3 * w);
                                case 2: { var c = new Vector2d(cx + h, cy - h); return new Vector2d(Up(c.x), Down(c.y)); }
                                case 3: return new Vector2d(cx + (rnd.NextDouble() - 0.5) * 4 * w, cy + h);
                                default: return new Vector2d(cx + (rnd.NextDouble() - 0.5) * 4 * w, cy + (rnd.NextDouble() - 0.5) * 4 * w);
                            }
                        }
                        var a = Pick(); var b = rnd.Next(8) == 0 ? a : Pick();
                        bool exact = grid.CrossesInteriorExact(a, b, kx, ky);
                        int filter = grid.CrossesInteriorFilter(a, b, kx, ky);
                        if (filter == 0) ++undecided;
                        else {
                            ++decided;
                            Assert.True((filter > 0) == exact, "w " + w.ToString("R") + ", pixel " + kx + " " + ky + ", a " + a.x.ToString("R") + " " + a.y.ToString("R") + ", b " + b.x.ToString("R") + " " + b.y.ToString("R"));
                        }
                        if (exact) ++crossing;
                        Assert.Equal(exact, grid.CrossesInterior(a, b, kx, ky));
                    }
                }
            // at the guards' edges (magnitudes around 1e-140 and 1e140), mixed exponents (a tiny, b huge), the extreme pixel index and
            // widths the filter leaves alone (w <= 0)
            foreach (double w in new[] { 1e-141, 3e-140, 1e139, 7e139, 0.3, -0.25 }) {
                var grid = new SnapGrid(w);
                foreach (long kx in new[] { 0L, 1L, -3L, long.MinValue, long.MaxValue })
                    foreach (var (a, b) in new[] {
                        (new Vector2d(-w, 0), new Vector2d(w, 0)), (new Vector2d(1e-150, 1e-150), new Vector2d(1e150, w)),
                        (new Vector2d(kx * w - w, -w), new Vector2d(kx * w + w, w)), (new Vector2d(0.4 * w, 0.4 * w), new Vector2d(0.4 * w, 0.4 * w)),
                        (new Vector2d(-1e-300, 2e-300), new Vector2d(3 * w, -2 * w)) }) {
                        bool exact = grid.CrossesInteriorExact(a, b, kx, 0);
                        int filter = grid.CrossesInteriorFilter(a, b, kx, 0);
                        Assert.True(filter == 0 || (filter > 0) == exact, "w " + w.ToString("R") + ", pixel " + kx + ", a " + a + ", b " + b);
                        Assert.Equal(exact, grid.CrossesInterior(a, b, kx, 0));
                    }
            }
            // the filter decides many cases, both ways, and leaves the touching ones (most of these picks, by design) to the exact test
            Assert.True(decided > 20000 && crossing > 10000 && undecided > 1000, decided + " decided, " + undecided + " undecided, " + crossing + " crossing");
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using Meshing2Acceptance;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Snap rounding with restore at an explicit tolerance (D14, comp_geom/SnapRounding2.cs). The properties are checked exactly, with the
    /// oracle's rationals: every input point on the centre of its half-open pixel of a grid anchored at the origin; no output vertex in the
    /// open pixel of an edge not incident to it (SRR's minimum distance); no two output edges crossing; every chain within half a pixel
    /// per axis of its input segment (SR's geometric similarity).
    /// </summary>
    public class SnapRounding2Tests
    {
        static ConstrainedMesh2Input Segments(params double[] xy)
        {
            var input = new ConstrainedMesh2Input();
            for (int i = 0; i + 3 < xy.Length; i += 4) {
                input.Points.Add(new Vector2d(xy[i], xy[i + 1])); input.Points.Add(new Vector2d(xy[i + 2], xy[i + 3]));
                input.Segments.Add(new Mesh2Segment(input.Points.Count - 2, input.Points.Count - 1));
            }
            return input;
        }

        static Q PixelCentre(double v, double w)
        {
            // floor(v / w + 1/2) * w, exactly
            Q t = Q.FromDouble(v) / Q.FromDouble(w) + new Q(1, 2);
            var f = System.Numerics.BigInteger.Divide(t.N, t.D);
            if (t.N.Sign < 0 && f * t.D != t.N) f -= 1;
            return new Q(f, 1) * Q.FromDouble(w);
        }

        /// <summary> does segment ab meet the open square of half-width h around c </summary>
        static bool CrossesOpenSquare(Pt a, Pt b, Pt c, Q h)
        {
            Q x0 = c.Qx - h, x1 = c.Qx + h, y0 = c.Qy - h, y1 = c.Qy + h;
            if (Q.Max(a.Qx, b.Qx) <= x0 || Q.Min(a.Qx, b.Qx) >= x1 || Q.Max(a.Qy, b.Qy) <= y0 || Q.Min(a.Qy, b.Qy) >= y1) return false;
            int pos = 0, neg = 0;
            foreach (var p in new[] { new Pt(x0, y0), new Pt(x1, y0), new Pt(x1, y1), new Pt(x0, y1) }) {
                int o = Exact.Orient(a, b, p);
                if (o > 0) ++pos; else if (o < 0) ++neg;
            }
            return pos > 0 && neg > 0;
        }

        /// <summary>
        /// where segment ab meets Hobby's half-open pixel around centre c (half-width h): the parameters of the piece of ab in the closed
        /// square, by clipping (Liang and Barsky), or null if there is none or it lies only on the open top or right side. An independent
        /// formulation of the routine's contact test (which uses separating axes).
        /// </summary>
        static (Q t0, Q t1)? HalfOpenContact(Pt a, Pt b, Pt c, Q h)
        {
            Q t0 = Q.Zero, t1 = Q.One;
            Q x0 = c.Qx - h, x1 = c.Qx + h, y0 = c.Qy - h, y1 = c.Qy + h;
            foreach (var (p, d, lo, hi) in new[] { (a.Qx, b.Qx - a.Qx, x0, x1), (a.Qy, b.Qy - a.Qy, y0, y1) }) {
                if (d.Sign == 0) { if (p < lo || p > hi) return null; continue; }
                Q u = (lo - p) / d, v = (hi - p) / d;
                if (u > v) (u, v) = (v, u);
                if (u > t0) t0 = u;
                if (v < t1) t1 = v;
            }
            if (t0 > t1) return null;
            Pt P(Q t) => new Pt(a.Qx + (b.Qx - a.Qx) * t, a.Qy + (b.Qy - a.Qy) * t);
            Pt p0 = P(t0), p1 = P(t1);
            if (p0.Qx == x1 && p1.Qx == x1) return null;
            if (p0.Qy == y1 && p1.Qy == y1) return null;
            return (t0, t1);
        }

        /// <summary> the four properties of the class summary; returns the restore counts for the callers' statistics </summary>
        static SnapRounding2 Check(ConstrainedMesh2Input input, double w)
        {
            var snap = SnapRounding2.Apply(input, w);
            var r = snap.Result;
            // exactly half a pixel on the exact centres; the centres are rounded to doubles (D1), which for a pixel width that is no
            // power of two moves an edge by a few units in the last place of the coordinates, so the check on the doubles allows that much
            double big = r.Points.Max(p => Math.Max(Math.Abs(p.x), Math.Abs(p.y)));
            Q h = Q.FromDouble(w) / 2 - Q.FromDouble(big) * new Q(4, 1L << 52);
            var pts = r.Points.Select(p => Pt.FromDoubles(p.x, p.y)).ToArray();
            for (int i = 0; i < input.Points.Count; ++i) {
                // exactly the centre up to its rounding to doubles
                Assert.True(Q.Abs(pts[i].Qx - PixelCentre(input.Points[i].x, w)) <= Q.Abs(PixelCentre(input.Points[i].x, w)) * new Q(1, 1L << 52) + new Q(1, 1L << 60),
                    "input " + i + " is not at its pixel centre");
                Assert.True(Q.Abs(pts[i].Qy - PixelCentre(input.Points[i].y, w)) <= Q.Abs(PixelCentre(input.Points[i].y, w)) * new Q(1, 1L << 52) + new Q(1, 1L << 60),
                    "input " + i + " is not at its pixel centre");
            }
            var edges = r.Segments.Select(s => (s.A, s.B)).Concat(r.Rings.SelectMany(g => g.Vertices.Select((v, i) => (v, g.Vertices[(i + 1) % g.Vertices.Length]))))
                .Where(e => !pts[e.Item1].Equals(pts[e.Item2])).ToList();
            var distinct = pts.Distinct().ToList();
            foreach (var (a, b) in edges) {
                foreach (var p in distinct)
                    if (!p.Equals(pts[a]) && !p.Equals(pts[b]))
                        Assert.False(CrossesOpenSquare(pts[a], pts[b], p, h), "vertex " + p + " lies in the pixel of edge " + pts[a] + " - " + pts[b]);
            }
            for (int i = 0; i < edges.Count; ++i)
                for (int j = i + 1; j < edges.Count; ++j)
                    Assert.False(Exact.ProperCross(pts[edges[i].Item1], pts[edges[i].Item2], pts[edges[j].Item1], pts[edges[j].Item2]), "two output edges cross");
            // every chain is snap rounding on the final hot pixels (SRR's Proposition 4.14): the centres of exactly the hot pixels its
            // input segment touches, in order along it (entry, then exit); every output point is a hot pixel centre
            Q hw = Q.FromDouble(w) / 2;
            foreach (var g in input.Segments) {
                if (g.A == g.B) continue;
                Pt a = Pt.FromDoubles(input.Points[g.A].x, input.Points[g.A].y), b = Pt.FromDoubles(input.Points[g.B].x, input.Points[g.B].y);
                var touched = new List<(Q t0, Q t1, Pt c)>();
                foreach (var c in distinct) {
                    var exactCentre = new Pt(PixelCentre(r.Points[Array.IndexOf(pts, c)].x, w), PixelCentre(r.Points[Array.IndexOf(pts, c)].y, w));
                    var hit = HalfOpenContact(a, b, exactCentre, hw);
                    if (hit != null) touched.Add((hit.Value.t0, hit.Value.t1, c));
                }
                touched.Sort((u, v) => u.t0 != v.t0 ? u.t0.CompareTo(v.t0) : u.t1 != v.t1 ? u.t1.CompareTo(v.t1) : 0);
                var expected = touched.Select(x => x.c).ToList();
                var chain = snap.ChainPoints(g.A, g.B).Select(p => Pt.FromDoubles(p.x, p.y)).ToList();
                Assert.True(expected.SequenceEqual(chain), "the chain of " + a + " - " + b + " is " + string.Join(" ", chain) + ", the touched hot pixels " + string.Join(" ", expected));
            }
            return snap;
        }

