        /// <summary>
        /// Closed outward box [min, max] whose face at min[axis] is an n x n grid (2 n^2 triangles) and whose
        /// other faces are coarse fans, so most triangles lie on that face.
        /// </summary>
        static DMesh3 BoxWithDenseFace(Vector3d min, Vector3d max, int axis, int n)
        {
            // local (u, v, w) = cyclic permutation of (x, y, z) starting at axis, the dense face is u = 0
            Func<double, double, double, Vector3d> world = (u, v, w) => {
                double[] l = { u, v, w }, x = new double[3];
                for (int k = 0; k < 3; ++k) {
                    int a = (axis + k) % 3;
                    x[a] = min[a] + l[k] * (max[a] - min[a]);
                }
                return new Vector3d(x[0], x[1], x[2]);
            };
            Func<int, Vector3d> axisDir = k => { var d = Vector3d.Zero; d[(axis + k) % 3] = 1; return d; };
            var mesh = new DMesh3();
            var g = new int[n + 1, n + 1];
            for (int a = 0; a <= n; ++a)
                for (int b = 0; b <= n; ++b)
                    g[a, b] = mesh.AppendVertex(world(0, (double)a / n, (double)b / n));
            var f = new int[2, 2];
            for (int a = 0; a < 2; ++a)
                for (int b = 0; b < 2; ++b)
                    f[a, b] = mesh.AppendVertex(world(1, a, b));
            // orient every triangle by the outward normal of its face
            Action<int, int, int, Vector3d> tri = (i0, i1, i2, outward) => {
                Vector3d nrm = (mesh.GetVertex(i1) - mesh.GetVertex(i0)).Cross(mesh.GetVertex(i2) - mesh.GetVertex(i0));
                if (nrm.Dot(outward) > 0) mesh.AppendTriangle(i0, i1, i2);
                else mesh.AppendTriangle(i0, i2, i1);
            };
            for (int a = 0; a < n; ++a)
                for (int b = 0; b < n; ++b) {
                    tri(g[a, b], g[a + 1, b], g[a + 1, b + 1], -axisDir(0));
                    tri(g[a, b], g[a + 1, b + 1], g[a, b + 1], -axisDir(0));
                }
            tri(f[0, 0], f[1, 0], f[1, 1], axisDir(0));
            tri(f[0, 0], f[1, 1], f[0, 1], axisDir(0));
            // side faces: fan from the far corner next to the first boundary vertex
            Action<Func<int, int>, int, int, Vector3d> side = (bd, farFirst, farLast, outward) => {
                for (int k = 0; k < n; ++k)
                    tri(bd(k), bd(k + 1), farFirst, outward);
                tri(bd(n), farLast, farFirst, outward);
            };
            side(k => g[0, k], f[0, 0], f[0, 1], -axisDir(1));
            side(k => g[n, k], f[1, 0], f[1, 1], axisDir(1));
            side(k => g[k, 0], f[0, 0], f[1, 0], -axisDir(2));
            side(k => g[k, n], f[0, 1], f[1, 1], axisDir(2));
            return mesh;
        }

        [Fact]
        public void InvertedComponents_TouchingBoxesAndCavity_DoNotDependOnUnitOrPosition()
        {
            // A = [0,2]x[0,1]^2 outwards; B = inverted box touching A at x = 2; C = cavity in A (inwards =
            // correct) touching A's wall y = 0. B and C are thin slabs whose contact face is densely
            // triangulated (A's coarsely), so most of their triangles, and the best-shaped ones, lie on A's
            // surface, where the winding number of A is 0 or 1 depending on rounding. Only B is inverted.
            DMesh3 a = BoxWithDenseFace(new Vector3d(0, 0, 0), new Vector3d(2, 1, 1), 0, 1);
            DMesh3 b = BoxWithDenseFace(new Vector3d(2, 0, 0), new Vector3d(2.02, 1, 1), 0, 12);
            b.ReverseOrientation();
            DMesh3 c = BoxWithDenseFace(new Vector3d(0.5, 0, 0.25), new Vector3d(1.5, 0.02, 0.75), 1, 12);
            c.ReverseOrientation();
            foreach (DMesh3 m in new[] { a, b, c })
                Assert.True(m.IsClosed());
            Assert.True(Volume(a) > 0 && Volume(b) < 0 && Volume(c) < 0);
            DMesh3 mesh = new DMesh3(a);
            MeshEditor.Append(mesh, b);
            MeshEditor.Append(mesh, c);
            // generic rotation: the contact faces are coplanar only up to rounding, as in real meshes
            MeshTransforms.Rotate(mesh, Vector3d.Zero, new Quaterniond(new Vector3d(1, 2, 3).Normalized, 37));
            int bTris = b.TriangleCount;

            foreach (var (scale, offset) in new[] { (1.0, 0.0), (0.001, 0.0), (0.1, 0.0), (1.0, 5e6) }) {
                DMesh3 m = new DMesh3(mesh);
                MeshTransforms.Scale(m, scale);
                MeshTransforms.Translate(m, new Vector3d(offset, offset, offset));
                var inverted = MeshPostRepairCleanup.FindInvertedComponents(m);
                Assert.True(inverted.Count == 1 && inverted[0].Length == bTris,
                    $"scale {scale}, offset {offset}: {inverted.Count} inverted components");
            }
        }

        [Fact]
        public void InvertedComponents_ThinCavityTouchingWall_IsNotInverted()
        {
            // thin cavity plate (thickness 1e-4 of its size, correctly oriented inwards) touching the outer
            // wall y = 0 of [0,2]^3: sample points must not be pushed through the plate to outside the box
            foreach (double t in new[] { 1e-2, 1e-4, 2e-5 }) {
                DMesh3 mesh = new GridBox3Generator() {
                    Box = new Box3d(new Vector3d(1, 1, 1), new Vector3d(1, 1, 1)), EdgeVertices = 3 }.Generate().MakeDMesh();
                DMesh3 plate = new GridBox3Generator() {
                    Box = new Box3d(new Vector3d(1, t / 2, 1), new Vector3d(0.5, t / 2, 0.5)), EdgeVertices = 8 }.Generate().MakeDMesh();
                plate.ReverseOrientation();
                MeshEditor.Append(mesh, plate);
                Assert.True(mesh.IsClosed());
                MeshTransforms.Rotate(mesh, Vector3d.Zero, new Quaterniond(new Vector3d(1, 2, 3).Normalized, 37));
                Assert.Empty(MeshPostRepairCleanup.FindInvertedComponents(mesh));
            }
        }

        [Fact]
        public void AutoRepair_WithPostRepairCleanup_GivesCleanClosedMesh()
        {
            // sphere with a hole, a separate two-sided triangle pair and a double cone with a bowtie apex
            DMesh3 mesh = Sphere();
            mesh.RemoveTriangle(mesh.TriangleIndices().First(), false, false);
            int a = mesh.AppendVertex(new Vector3d(5, 0, 0));
            int b = mesh.AppendVertex(new Vector3d(6, 0, 0));
            int c = mesh.AppendVertex(new Vector3d(5, 1, 0));
            mesh.AppendTriangle(a, b, c);
            mesh.AppendTriangle(a, c, b);
            DMesh3 cone = MeshTestUtil.DoubleConeBowtie(8, 1);
            MeshTransforms.Translate(cone, new Vector3d(-5, 0, 0));
            MeshEditor.Append(mesh, cone);
            Assert.False(mesh.IsClosed());

            var repair = new MeshAutoRepair(mesh) { PostRepairCleanup = true };
            Assert.True(repair.Apply());
            DMesh3 result = repair.Mesh;

            Assert.True(result.IsClosed());
            Assert.Empty(MeshIterators.BowtieVertices(result));
            Assert.Equal(0, DegenerateCount(result));
            Assert.Empty(MeshPostRepairCleanup.FindInvertedComponents(result));
            Assert.True(Volume(result) > 0);
            Assert.True(result.CheckValidity(false, FailMode.ReturnOnly));
        }

        static DMesh3 Cube(Vector3d min, double size)
        {
            return new TrivialBox3Generator() { Box = new Box3d(min + 0.5 * size * Vector3d.One, 0.5 * size * Vector3d.One) }.Generate().MakeDMesh();
        }

        [Fact]
        public void ManyComponents_InsideOutOneFound()
        {
            // 600 hollow cubes (each with a cavity, oriented inwards) in a grid, plus one inside-out cube and one hollow
            // cube with an outward cavity: with more than 500 closed components nothing was checked, so NotCleanReason
            // called such a mesh clean
            DMesh3 mesh = new DMesh3();
            for (int i = 0; i < 600; ++i) {
                Vector3d p = new Vector3d(3 * (i % 30), 3 * (i / 30), 0);
                MeshEditor.Append(mesh, Cube(p, 2));
                DMesh3 cavity = Cube(p + 0.5 * Vector3d.One, 1);
                cavity.ReverseOrientation();
                MeshEditor.Append(mesh, cavity);
            }
            Assert.Empty(MeshPostRepairCleanup.FindInvertedComponents(mesh));
            Assert.Equal("", MeshRobustRepair.NotCleanReason(mesh, false));

            DMesh3 inverted = Cube(new Vector3d(0, -5, 0), 2);
            inverted.ReverseOrientation();
            MeshEditor.Append(mesh, inverted);
            MeshEditor.Append(mesh, Cube(new Vector3d(5, -5, 0), 2));
            MeshEditor.Append(mesh, Cube(new Vector3d(5.5, -4.5, 0.5), 1));      // a cavity facing outwards
            var found = MeshPostRepairCleanup.FindInvertedComponents(mesh);
            Assert.Equal(2, found.Count);
            Assert.Equal("inside-out components", MeshRobustRepair.NotCleanReason(mesh, false));

            var cleanup = new MeshPostRepairCleanup(mesh);
            cleanup.Apply();
            Assert.Equal(2, cleanup.FlippedComponents);
            Assert.Equal("", MeshRobustRepair.NotCleanReason(mesh, false));
        }

        static DMesh3 FlatBox(double degrees)
        {
            DMesh3 box = new GridBox3Generator() {
                Box = new Box3d(Vector3d.Zero, new Vector3d(2, 2, 0.2)), EdgeVertices = 4 }.Generate().MakeDMesh();
            MeshTransforms.Rotate(box, Vector3d.Zero, new Quaterniond(Vector3d.AxisY, degrees));
            return box;
        }

        [Theory]
        [InlineData(3.0)]
        [InlineData(10.0)]
        [InlineData(30.0)]
        public void CrossingComponents_KeepTheirOrientation(double degrees)
        {
            // finding R1: two outward flat boxes, the second rotated about an axis through the middle, so their large
            // faces cross at a small angle and most of the second's interior lies inside the first. They cross, neither
            // encloses the other: no cavity, nothing inside-out (also on the old code: the samples of the first, whose box
            // lies in the second's, give no majority; CubeCrossingASphere_IsNotACavity is the direct case)
            DMesh3 mesh = FlatBox(0);
            MeshEditor.Append(mesh, FlatBox(degrees));
            Assert.True(mesh.IsClosed() && Volume(mesh) > 0);
            foreach (Similarity sim in Similarity.All())
                Assert.Empty(MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh, sim)));

            // an inside-out crossing box whose box does not lie in the other's is a top-level shell, inside-out, as on
            // the old code: flagged (flipped, the two give the union)
            DMesh3 b = FlatBox(degrees);
            b.ReverseOrientation();
            DMesh3 mesh2 = FlatBox(0);
            MeshEditor.Append(mesh2, b);
            foreach (Similarity sim in Similarity.All()) {
                var found = MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh2, sim));
                Assert.True(found.Count == 1 && found[0].Length == b.TriangleCount && found[0].Min() == b.TriangleCount,
                    $"{sim.Name}: {found.Count}");
            }
        }

        [Theory]
        [InlineData(0.62)]
        [InlineData(0.7)]
        public void CubeCrossingASphere_IsNotACavity(double half)
        {
            // finding R1, direct: an outward cube whose corners poke out of an outward unit sphere (its box lies in the
            // sphere's, most of its interior inside the sphere). The surfaces cross: not nested, so not an outward
            // cavity to flag. (Counted as nested, it was flagged, and the repair flipped it: sphere minus cube.)
            DMesh3 mesh = Sphere(1);
            DMesh3 cube = Cube(-half * Vector3d.One, 2 * half);
            MeshEditor.Append(mesh, cube);
            Assert.True(mesh.IsClosed() && Volume(cube) > 0);
            foreach (Similarity sim in Similarity.All())
                Assert.Empty(MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh, sim)));
            // a cube strictly inside the sphere (corners at 0.95) still is a cavity facing outwards: flagged
            DMesh3 mesh2 = Sphere(1);
            MeshEditor.Append(mesh2, Cube(-0.55 * Vector3d.One, 1.1));
            foreach (Similarity sim in Similarity.All())
                Assert.Single(MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh2, sim)));
        }

        [Fact]
        public void CavitySharingAVertexWithItsShell_IsNested()
        {
            // a tetrahedral cavity whose apex is a corner vertex of the outer cube (the same vertex, a bowtie): the
            // surfaces share only that vertex, which is not a meeting, so the cavity is nested: inward it is correct,
            // outward it is flagged
            foreach (bool inwards in new[] { true, false }) {
                DMesh3 mesh = Cube(Vector3d.Zero, 4);
                int apex = mesh.VertexIndices().First(v => mesh.GetVertex(v) == Vector3d.Zero);
                int a = mesh.AppendVertex(new Vector3d(1, 1, 0.5)), b = mesh.AppendVertex(new Vector3d(1, 0.5, 1));
                int c = mesh.AppendVertex(new Vector3d(0.5, 1, 1));
                var tets = new[] { new Index3i(apex, a, b), new Index3i(apex, b, c), new Index3i(apex, c, a), new Index3i(a, c, b) };
                var tids = tets.Select(t => mesh.AppendTriangle(t)).ToArray();
                double vol = MeshMeasurements.VolumeArea(mesh, tids, mesh.GetVertex).x;
                if ((vol < 0) != inwards)
                    foreach (int t in tids) mesh.ReverseTriOrientation(t);
                Assert.True(mesh.IsClosed());
                foreach (Similarity sim in Similarity.All()) {
                    var found = MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh, sim));
                    if (inwards)
                        Assert.Empty(found);
                    else
                        Assert.True(found.Count == 1 && found[0].OrderBy(t => t).SequenceEqual(tids), $"{sim.Name}: {found.Count}");
                }
            }
        }

        [Fact]
        public void CrossingPairInAShell_KeepsItsOrientation()
        {
            // an outward shell, a spherical cavity in it (inward) and a cube whose corners poke out of the cavity: the
            // cube's samples lie in the shell and the sphere (2 enclosing), but it crosses the sphere: it has no nesting
            // and keeps its orientation, whichever way it faces (on the old code the inward cube was flagged). The
            // crossing pair is not just dropped from the count (that would make the cube a cavity of the shell, and
            // flag the outward one): both readings are possible, the input's orientation decides.
            foreach (bool cubeInwards in new[] { true, false }) {
                DMesh3 mesh = Cube(-5 * Vector3d.One, 10);
                DMesh3 sphere = Sphere(1);
                sphere.ReverseOrientation();
                MeshEditor.Append(mesh, sphere);
                DMesh3 cube = Cube(-0.62 * Vector3d.One, 1.24);
                if (cubeInwards) cube.ReverseOrientation();
                MeshEditor.Append(mesh, cube);
                foreach (Similarity sim in Similarity.All()) {
                    int n = MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh, sim)).Count;
                    Assert.True(n == 0, $"cube inwards {cubeInwards}, {sim.Name}: {n} flagged");
                }
            }
            // the sphere itself is nested in the shell only: facing outwards, it is flagged
            DMesh3 mesh2 = Cube(-5 * Vector3d.One, 10);
            MeshEditor.Append(mesh2, Sphere(1));
            MeshEditor.Append(mesh2, Cube(-0.62 * Vector3d.One, 1.24));
            foreach (Similarity sim in Similarity.All()) {
                var found = MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh2, sim));
                Assert.True(found.Count == 1 && found[0].Length == Sphere(1).TriangleCount, $"{sim.Name}: {found.Count}");
            }
        }

        [Fact]
        public void NestedComponentsNotMeeting_AreStillNested()
        {
            // the crossing rule only applies when the surfaces meet: a cavity strictly inside its shell (and a shell in
            // that cavity) is still nested, so an outward cavity is flagged and an inward one is not, at every scale
            DMesh3 outer = Cube(Vector3d.Zero, 4);
            DMesh3 cavity = Cube(Vector3d.One, 2);
            DMesh3 island = Cube(1.5 * Vector3d.One, 1);
            foreach (bool cavityInwards in new[] { true, false }) {
                DMesh3 mesh = new DMesh3(outer);
                DMesh3 c = new DMesh3(cavity);
                if (cavityInwards) c.ReverseOrientation();
                MeshEditor.Append(mesh, c);
                MeshEditor.Append(mesh, island);
                foreach (Similarity sim in Similarity.All()) {
                    var found = MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh, sim));
                    if (cavityInwards)
                        Assert.Empty(found);
                    else
                        Assert.True(found.Count == 1 && found[0].Length == cavity.TriangleCount, $"{sim.Name}: {found.Count}");
                }
            }
        }

        [Fact]
        public void CavityTouchingItsShell_KeepsItsOrientation()
        {
            // a cavity whose surface touches the outer shell (a zero wall) is not nested by the crossing rule: it keeps its
            // orientation, whichever way it faces (the correct, inward one was not flagged before either). One cavity
            // touching the wall x = 0, y = 0 or z = 0: the contact is in each axis's plane once. A rotation rounds the
            // contact into a crossing or a gap (then nested, and the outward cavity is flagged): the outward one is
            // checked only where the contact stays exactly coplanar; the inward one is correct either way.
            foreach (bool inwards in new[] { true, false })
            foreach (Vector3d min in new[] { new Vector3d(0, 1, 1), new Vector3d(1, 0, 1), new Vector3d(1, 1, 0) }) {
                DMesh3 mesh = Cube(Vector3d.Zero, 4);
                DMesh3 c = Cube(min, 2);
                if (inwards) c.ReverseOrientation();
                MeshEditor.Append(mesh, c);
                foreach (Similarity sim in Similarity.All().Where(sim => inwards || sim.IsRotated == false)) {
                    int n = MeshPostRepairCleanup.FindInvertedComponents(Invariance.Transformed(mesh, sim)).Count;
                    Assert.True(n == 0, $"inwards {inwards}, cavity at {min}, {sim.Name}: {n} flagged");
                }
            }
        }

        [Fact]
        public void ManyComponents_SideBySide_Fast()
        {
            // 20000 cubes in a row: the sweep finds no enclosing boxes without comparing all pairs
            DMesh3 mesh = new DMesh3();
            for (int i = 0; i < 20000; ++i)
                MeshEditor.Append(mesh, Cube(new Vector3d(2 * i, 0, 0), 1));
            var timer = System.Diagnostics.Stopwatch.StartNew();
            Assert.Empty(MeshPostRepairCleanup.FindInvertedComponents(mesh));
            Assert.True(timer.ElapsedMilliseconds < 20000, $"{timer.ElapsedMilliseconds} ms");
        }

        [Fact]
        public void EnclosingBoxes_SameAsAllPairs()
        {
            // random nested, overlapping, identical and equal-coordinate boxes on a coarse grid
            var rnd = new Random(3);
            for (int trial = 0; trial < 50; ++trial) {
                var boxes = new List<AxisAlignedBox3d>();
                int n = 1 + rnd.Next(60);
                for (int k = 0; k < n; ++k) {
                    if (k > 0 && rnd.Next(5) == 0) { boxes.Add(boxes[rnd.Next(k)]); continue; }
                    Func<int> c = () => rnd.Next(6);
                    int x0 = c(), y0 = c(), z0 = c();
                    boxes.Add(new AxisAlignedBox3d(new Vector3d(x0, y0, z0), new Vector3d(x0 + 1 + rnd.Next(4), y0 + 1 + rnd.Next(4), z0 + 1 + rnd.Next(4))));
                }
                var found = MeshPostRepairCleanup.enclosing_boxes(boxes);
                for (int i = 0; i < n; ++i) {
                    var expected = Enumerable.Range(0, n).Where(j => j != i && boxes[j].Contains(boxes[i])).ToList();
                    Assert.Equal(expected, found[i]);
                }
            }
        }

        [Fact]
        public void UnusedVertexFarAway_SmallTrianglesNotDegenerate()
        {
            // the degenerate area is relative to the triangles' bounds: an unused vertex 1e4 away made the triangles of
            // a sphere of radius 0.02 "degenerate", and the cleanup collapsed it
            DMesh3 mesh = Cube(Vector3d.Zero, 1);
            DMesh3 sphere = Sphere(0.02, new Vector3d(3, 0, 0));
            MeshEditor.Append(mesh, sphere);
            mesh.AppendVertex(new Vector3d(1e4, 1e4, 1e4));
            int n = mesh.TriangleCount;
            var cleanup = new MeshPostRepairCleanup(mesh);
            cleanup.Apply();
            Assert.Equal(0, cleanup.FixedDegenerate);
            Assert.Equal(n, mesh.TriangleCount);
            ResultChecks.AssertClosed(mesh);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Hard cases for mesh repair (MeshRobustRepair, MeshAutoRepair, the hole fillers) from the issue trackers of other
    /// libraries (docs/QA.md 2.11): only the failure mode, rebuilt here from simple primitives. No code, test code or
    /// meshes of these projects are used (CGAL is GPL and MeshLib source-available: only the prose of their issues was
    /// read). The issue URL is in the comment of each test.
    ///
    /// Every case checks the result itself (MeshRobustRepair.NotCleanReasons, the volume, case-specific checks). A case
    /// we fail is listed in KnownFailures with its finding (strict, as in RobustnessSweepTests: a listed case that passes
    /// fails, so a fix removes the entry).
    /// </summary>
    public class MeshRepairIssueCasesTests
    {
        /// <summary> case name -> finding; a listed case must still fail </summary>
        public static readonly Dictionary<string, string> KnownFailures = new Dictionary<string, string> {
        };

        static void Expect(string name, string failure)
        {
            if (KnownFailures.TryGetValue(name, out string finding)) {
                if (!IssueCases.Strict) return;
                Assert.True(failure != "", $"{name} passes now: remove its entry ({finding}) from KnownFailures and docs/QA.md 2.11");
            }
            else
                Assert.True(failure == "", name + ": " + failure);
        }

        // ---- primitives (doubles throughout, so the expected volumes are exact) ----

        /// <summary> an axis-aligned box, 12 triangles, outward </summary>
        internal static DMesh3 Box(Vector3d lo, Vector3d hi)
        {
            var m = new DMesh3();
            for (int i = 0; i < 8; ++i)
                m.AppendVertex(new Vector3d((i & 1) == 0 ? lo.x : hi.x, (i & 2) == 0 ? lo.y : hi.y, (i & 4) == 0 ? lo.z : hi.z));
            int[][] quads = { new[] { 0, 2, 3, 1 }, new[] { 4, 5, 7, 6 }, new[] { 0, 1, 5, 4 }, new[] { 2, 6, 7, 3 }, new[] { 0, 4, 6, 2 }, new[] { 1, 3, 7, 5 } };
            foreach (int[] q in quads) {
                m.AppendTriangle(q[0], q[1], q[2]);
                m.AppendTriangle(q[0], q[2], q[3]);
            }
            Assert.True(ResultChecks.Volume(m) > 0);
            return m;
        }

        internal static DMesh3 Sphere(Vector3d c, double r, int n = 8)
        {
            DMesh3 m = new Sphere3Generator_NormalizedCube() { Radius = r, EdgeVertices = n }.Generate().MakeDMesh();
            MeshTransforms.Translate(m, c);
            return m;
        }

        /// <summary> a closed cone: a fan of n triangles to the apex over a regular n-gon in z = 0, and a fan base </summary>
        static DMesh3 Cone(int n, double r, double h, bool withBase)
        {
            var m = new DMesh3();
            int apex = m.AppendVertex(new Vector3d(0, 0, h));
            int[] ring = Enumerable.Range(0, n).Select(i => m.AppendVertex(new Vector3d(r * Math.Cos(2 * Math.PI * i / n), r * Math.Sin(2 * Math.PI * i / n), 0))).ToArray();
            for (int i = 0; i < n; ++i)
                m.AppendTriangle(ring[i], ring[(i + 1) % n], apex);
            if (withBase)
                for (int i = 1; i + 1 < n; ++i)
                    m.AppendTriangle(ring[0], ring[i + 1], ring[i]);
            return m;
        }

        static DMesh3 Copy(DMesh3 m) => new DMesh3(m);

        static AxisAlignedBox3d Bounds(DMesh3 m)
        {
            var b = AxisAlignedBox3d.Empty;
            foreach (int t in m.TriangleIndices()) {
                Index3i tv = m.GetTriangle(t);
                b.Contain(m.GetVertex(tv.a)); b.Contain(m.GetVertex(tv.b)); b.Contain(m.GetVertex(tv.c));
            }
            return b;
        }

        static int Components(DMesh3 m)
        {
            var c = new MeshConnectedComponents(m);
            c.FindConnectedT();
            return c.Count;
        }

        /// <summary>
        /// MeshRobustRepair on a copy: "" if the result is clean (closed, manifold, oriented, no degenerate triangles, no
        /// self-intersections), its volume is within relTol of the expected one, and it stays in the input's bounds
        /// grown by grow (relative to their diagonal); otherwise the reasons
        /// </summary>
        static string RobustOutcome(DMesh3 input, double volume, double relTol, out MeshRobustRepair repair, double grow = 0.01)
        {
            repair = new MeshRobustRepair(Copy(input));
            bool ok = repair.Apply();
            string o = Outcome(ok, repair.Mesh, input, volume, relTol, grow);
            return o == "" ? "" : o + " [" + Path(repair) + "]";
        }

        /// <summary>
        /// MeshAutoRepair (with the post-repair cleanup, as in MeshRobustRepair) on a copy, checked like RobustOutcome.
        /// For holes: MeshRobustRepair compares a repair with the winding number solid of the open input, and a large
        /// hole's fill differs from that by more than its MinVolumeIoU, so it would remesh the input instead
        /// </summary>
        static string AutoOutcome(DMesh3 input, double volume, double relTol, out DMesh3 result,
            MeshAutoRepair.HoleFillModes mode = MeshAutoRepair.HoleFillModes.Minimal, DMesh3 boundsOf = null, double grow = 0.01)
        {
            var repair = new MeshAutoRepair(Copy(input)) { PostRepairCleanup = true, HoleFillMode = mode };
            bool ok = repair.Apply();
            result = repair.Mesh;
            return Outcome(ok, result, boundsOf ?? input, volume, relTol, grow);
        }

        static string Path(MeshRobustRepair r) =>
            $"exact {r.UsedExactResolve}, solidify {r.UsedSolidify}, wrap {r.UsedAlphaWrap}, input {r.UsedInput}, result '{r.ResultReason}', "
            + $"fallback '{r.FallbackReason}', exact '{r.ExactResolveReason}', IoU {r.RepairVolumeIoU}";

        static string Outcome(bool ok, DMesh3 result, DMesh3 input, double volume, double relTol, double grow)
        {
            var r = new List<string>();
            if (!ok) r.Add("Apply() false");
            if (result == null) return "no result";
            if (!result.CheckValidity(false, FailMode.ReturnOnly)) r.Add("invalid DMesh3");
            if (!result.Vertices().All(v => v.IsFinite)) r.Add("non-finite coordinates");
            string reasons = MeshRobustRepair.NotCleanReasons(result);
            if (reasons != "") r.Add(reasons);
            double vol = ResultChecks.Volume(result);
            if (!(Math.Abs(vol - volume) <= relTol * Math.Abs(volume))) r.Add($"volume {vol:R}, expected {volume:R}");
            AxisAlignedBox3d bi = Bounds(input), bo = Bounds(result);
            double g = grow * bi.DiagonalLength;
            if (!(bo.Min.x >= bi.Min.x - g && bo.Min.y >= bi.Min.y - g && bo.Min.z >= bi.Min.z - g
                && bo.Max.x <= bi.Max.x + g && bo.Max.y <= bi.Max.y + g && bo.Max.z <= bi.Max.z + g))
                r.Add($"result bounds {bo} beyond the input's {bi}");
            return string.Join("; ", r);
        }

        static double SphereVolume(DMesh3 sphere) => ResultChecks.Volume(sphere);

        [Fact]
        public void KnownFailures_NameExistingCases()
        {
            var names = new HashSet<string>(typeof(MeshRepairIssueCasesTests).GetMethods().Select(m => m.Name));
            foreach (var kv in KnownFailures) {
                // a case name is a test method, or a test method and a suffix for one of its parts
                Assert.True(names.Any(n => kv.Key == n || kv.Key.StartsWith(n + "_")), kv.Key + ": no such case");
                Assert.False(string.IsNullOrWhiteSpace(kv.Value));
            }
        }

        // ---------------------------------------------------------------------------------------------------------------
        // holes

        [Fact]
        public void HoleOfOneTriangle_FilledWithoutAMirroredShell()
        {
            // https://github.com/CGAL/cgal/issues/937: a hole that is exactly one triangle was filled with that triangle
            // and a mirrored copy, a closed two-triangle shell of zero volume. Correct: the hole is closed by one triangle.
            DMesh3 sphere = Sphere(Vector3d.Zero, 1), input = Copy(sphere);
            int tid = input.TriangleIndices().First();
            input.RemoveTriangle(tid, false);
            Expect(nameof(HoleOfOneTriangle_FilledWithoutAMirroredShell), RobustOutcome(input, SphereVolume(sphere), 1e-9, out var rr));
            Assert.Equal(sphere.TriangleCount, rr.Mesh.TriangleCount);
            Assert.Equal(1, Components(rr.Mesh));
        }

        [Fact]
        public void PlanarSquareHole_FilledExactly()
        {
            // https://github.com/CGAL/cgal/issues/937: a planar square hole (a box missing one face): with one choice of
            // diagonal nothing was filled, yet success was reported. Rebuilt for each of the six faces (their
            // triangulations have both diagonal directions). Correct: two triangles, the box's exact volume.
            for (int face = 0; face < 6; ++face) {
                DMesh3 input = Box(new Vector3d(-1, -2, -3), new Vector3d(4, 5, 6));
                input.RemoveTriangle(2 * face, false);
                input.RemoveTriangle(2 * face + 1, false);
                string name = nameof(PlanarSquareHole_FilledExactly);
                Expect(name, RobustOutcome(input, 5 * 7 * 9, 1e-12, out var rr));
                Assert.Equal(12, rr.Mesh.TriangleCount);
                Assert.Equal(8, rr.Mesh.VertexCount);
            }
        }

        [Fact]
        public void QuadHoleWhoseDiagonalIsAnExistingEdge()
        {
            // https://github.com/pmp-library/pmp-library/issues/181: the triangulation of a hole created an edge that
            // already existed in the mesh, so adding the face failed and the filler left a broken state. Rebuilt: a
            // tetrahedron without the two faces on edge bd. The hole a-b-c-d has the diagonal ac as an existing interior
            // edge, so only the diagonal bd closes it.
            var a = new Vector3d(0, 0, 0); var b = new Vector3d(3, 0, 0); var c = new Vector3d(1, 2, 0); var d = new Vector3d(1, 1, 2);
            var tet = new DMesh3();
            foreach (Vector3d v in new[] { a, b, c, d }) tet.AppendVertex(v);
            int abc = tet.AppendTriangle(0, 2, 1), abd = tet.AppendTriangle(0, 1, 3), bcd = tet.AppendTriangle(1, 2, 3), acd = tet.AppendTriangle(0, 3, 2);
            Assert.True(abc >= 0 && abd >= 0 && bcd >= 0 && acd >= 0);
            double volume = ResultChecks.Volume(tet);
            Assert.True(volume > 0);
            DMesh3 input = Copy(tet);
            input.RemoveTriangle(abd, false);
            input.RemoveTriangle(bcd, false);
            Expect(nameof(QuadHoleWhoseDiagonalIsAnExistingEdge), AutoOutcome(input, volume, 1e-12, out DMesh3 repaired));
            Assert.Equal(4, repaired.TriangleCount);
            Assert.Equal(4, repaired.VertexCount);

            // the minimal hole filler alone, on the same hole
            DMesh3 m = Copy(input);
            var loops = new MeshBoundaryLoops(m);
            Assert.Single(loops.Loops);
            var fill = new MinimalHoleFill(m, loops.Loops[0]);
            bool filled = fill.Apply();
            string why = filled ? "" : "MinimalHoleFill.Apply() false";
            if (filled) {
                if (!m.CheckValidity(false, FailMode.ReturnOnly)) why = "invalid after the fill";
                else if (!m.IsClosed()) why = "not closed after the fill";
                else if (Math.Abs(ResultChecks.Volume(m) - volume) > 1e-12 * volume) why = $"volume {ResultChecks.Volume(m)}";
            }
            Expect(nameof(QuadHoleWhoseDiagonalIsAnExistingEdge) + "_MinimalHoleFill", why);
        }

        // the tetrahedron of QuadHoleWhoseDiagonalIsAnExistingEdge without its faces abd and bcd, transformed
        static DMesh3 TetraWithQuadHole(Similarity s)
        {
            var m = new DMesh3();
            foreach (Vector3d v in new[] { new Vector3d(0, 0, 0), new Vector3d(3, 0, 0), new Vector3d(1, 2, 0), new Vector3d(1, 1, 2) })
                m.AppendVertex(s.Apply(v));
            m.AppendTriangle(0, 2, 1);
            m.AppendTriangle(0, 3, 2);
            return m;
        }

        public static IEnumerable<object[]> Similarities() => Similarity.Names();

        [Theory]
        [MemberData(nameof(Similarities))]
        public void MinimalHoleFill_ExistingDiagonal_UnderSimilarity(string similarity)
        {
            // the fix of QuadHoleWhoseDiagonalIsAnExistingEdge under Similarity.All(): the same two triangles (the new
            // diagonal bd), no new vertex; and a sphere's cap hole filled the same way, bit for bit under 2^k scales
            Similarity s = Similarity.ByName(similarity);
            DMesh3 m = TetraWithQuadHole(s);
            var fill = new MinimalHoleFill(m, new MeshBoundaryLoops(m).Loops[0]);
            Assert.True(fill.Apply());
            ResultChecks.AssertClosed(m, similarity);
            Assert.Equal(4, m.VertexCount);
            Assert.Equal(4, m.TriangleCount);
            Assert.Empty(fill.FillVertices);
            Assert.True(m.FindEdge(1, 3) >= 0, similarity + ": diagonal bd missing");
            Assert.Equal("", MeshRobustRepair.NotCleanReasons(m));

            DMesh3 reference = null;
            foreach (Similarity t in new[] { Similarity.Identity, s }) {
                DMesh3 sphere = Invariance.Transformed(Sphere(Vector3d.Zero, 1, 8), t);
                foreach (int tid in sphere.TriangleIndices().ToArray())
                    if (t.Inverse(sphere.GetTriCentroid(tid)).Normalized.z > 0.8)
                        sphere.RemoveTriangle(tid, true);
                var f = new MinimalHoleFill(sphere, new MeshBoundaryLoops(sphere).Loops[0]);
                Assert.True(f.Apply());
                ResultChecks.AssertClosed(sphere, similarity);
                DMesh3 back = Invariance.MappedBack(sphere, t);
                if (reference == null) { reference = back; continue; }
                if (s.IsExact)
                    Assert.Equal("", Invariance.Difference(reference, back));
                else {
                    Assert.Equal(reference.TriangleCount, back.TriangleCount);
                    Assert.True(Invariance.VertexDistance(reference, back) <= 1e-6, similarity + ": " + Invariance.VertexDistance(reference, back));
                }
            }
        }

        [Fact]
        public void SeveralHoles_AllFilled()
        {
            // https://github.com/pmp-library/pmp-library/issues/98: of a mesh with two holes, only the first boundary
            // was filled. Rebuilt with more: a sphere with four separate holes of one to a few triangles.
            DMesh3 sphere = Sphere(Vector3d.Zero, 2, 10), input = Copy(sphere);
            var rand = new Random(98);
            var removed = new HashSet<int>();
            foreach (Vector3d dir in new[] { Vector3d.AxisX, -Vector3d.AxisX, Vector3d.AxisY, Vector3d.AxisZ }) {
                // the triangles of a small cap around dir
                foreach (int t in sphere.TriangleIndices())
                    if (sphere.GetTriCentroid(t).Normalized.Dot(dir) > 0.985)
                        removed.Add(t);
            }
            foreach (int t in removed) input.RemoveTriangle(t, false);
            Assert.Equal(4, new MeshBoundaryLoops(input).Count);
            Expect(nameof(SeveralHoles_AllFilled), RobustOutcome(input, SphereVolume(sphere), 1e-3, out var rr));
            Assert.Equal(1, Components(rr.Mesh));
        }

        [Fact]
        public void ConeWithoutItsBase_FilledFlat()
        {
            // https://github.com/pmp-library/pmp-library/issues/64: filling the open base of a cone (a large planar
            // loop) gave a non-smooth patch out of the plane. Correct: a flat patch, the cone's exact volume.
            foreach (int n in new[] { 7, 32, 101 }) {
                DMesh3 cone = Cone(n, 10, 3, true), input = Cone(n, 10, 3, false);
                Expect(nameof(ConeWithoutItsBase_FilledFlat), RobustOutcome(input, ResultChecks.Volume(cone), 1e-9, out var rr));
                // every vertex of the fill lies in the base plane, or is the apex
                foreach (Vector3d v in rr.Mesh.Vertices())
