            DMesh3 n = new DMesh3();
            s = n.AppendVertex(Vector3d.Zero);
            a = n.AppendVertex(new Vector3d(2, 0, 0)); b = n.AppendVertex(new Vector3d(0, 2, 0));
            c = n.AppendVertex(new Vector3d(-1, 0.2, 1)); d = n.AppendVertex(new Vector3d(0.2, -1, 1));
