using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;
using Family = geometry3Sharp.Tests.SafeRoundingDegenerateInputTests.Family;
using Ops = g3.ExactMeshBoolean.Operations;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// MeshRoundingRepair keeps the smallest vertex id per position (canonical ids, SharedPositionsTouch) and searches
    /// the intersecting pairs again only for the triangles changed since the last search. With
    /// MeshRoundingRepair.CheckOnThisThread every search is compared with a full one and every canonical id with the
    /// dictionary of positions (it throws if they differ); the results are the same bit for bit, serial or parallel.
    /// </summary>
    public class MeshRoundingRepairIncrementalTests
    {
        readonly Xunit.Abstractions.ITestOutputHelper output;
        public MeshRoundingRepairIncrementalTests(Xunit.Abstractions.ITestOutputHelper output) { this.output = output; }

        // rotated, scaled by 1e-3 and moved to UTM coordinates (as SafeRoundingBoundTests.UtmCases): the rounding
        // moves vertices, flips, contracts edges and removes vertices, with intersecting pairs among the edited triangles
        static DMesh3 Utm(Family f, int k, int count, int seed) =>
            Invariance.Transformed(SafeRoundingDegenerateInputTests.Make(f, k, seed, count), Similarity.ByName("rotated, scale 1e-3, utm"));

        // the sphere with collinear caps (flips) and a flat tetrahedron through its surface (its apex on the middle of
        // a base edge: zero volume, a degenerate face, faces overlapping the base): removed as a tiny component, its
        // intersecting pairs with the sphere go with it
        static DMesh3 SphereWithFlatTetrahedron()
        {
            DMesh3 m = SafeRoundingDegenerateInputTests.Make(Family.Collinear, 30, 1);
            Vector3d a = new Vector3d(0.6, -0.3, -0.2), b = new Vector3d(1.3, 0.1, 0.05), c = new Vector3d(0.7, 0.35, 0.3);
            int ia = m.AppendVertex(a), ib = m.AppendVertex(b), ic = m.AppendVertex(c), id = m.AppendVertex((a + b) / 2);
            m.AppendTriangle(ia, ic, ib); m.AppendTriangle(ia, ib, id); m.AppendTriangle(ib, ic, id); m.AppendTriangle(ic, ia, id);
            return m;
        }

        public static IEnumerable<object[]> Cases()
        {
            yield return new object[] { "utm Cluster 0 4 0" };
            yield return new object[] { "utm Cluster 36 4 0" };
            yield return new object[] { "utm FoldedCluster 30 4 0" };
            yield return new object[] { "utm Cluster 0 2 0" };
            // (in PastTheLimit_SameAsProposingInFull, with MaxPairTests 5000: its SmallestRejectedDrift comes from a move
            // past the limit)
            yield return new object[] { "utm Cluster 0 9 1" };
            foreach (Family f in new[] { Family.Sliver, Family.ShortEdge, Family.Coincident, Family.Collinear, Family.Cluster, Family.FoldedCluster })
                yield return new object[] { f.ToString() };
        }

        internal static Func<ExactMeshBoolean> Case(string name)
        {
            DMesh3 m;
            if (name.StartsWith("utm ")) {
                string[] w = name.Split(' ');
                m = Utm((Family)Enum.Parse(typeof(Family), w[1]), int.Parse(w[2]), int.Parse(w[3]), int.Parse(w[4]));
            } else {
                Family f = (Family)Enum.Parse(typeof(Family), name);
                m = SafeRoundingDegenerateInputTests.Make(f, f == Family.Cluster || f == Family.FoldedCluster ? 36 : 30, 1);
            }
            return () => new ExactMeshBoolean(new DMesh3(m), new DMesh3(), Ops.Union);
        }

        static ExactMeshBoolean Run(Func<ExactMeshBoolean> make, bool check = false, bool serial = false)
        {
            MeshRoundingRepair.CheckOnThisThread = check;
            gParallel.SerialOnThisThread = serial;
            try {
                ExactMeshBoolean b = make();
                Assert.True(b.Compute(), b.Error);
                return b;
            } finally {
                MeshRoundingRepair.CheckOnThisThread = false;
                gParallel.SerialOnThisThread = false;
            }
        }

        static string Print(DMesh3 m)
        {
            var sb = new System.Text.StringBuilder();
            foreach (int v in m.VertexIndices()) {
                Vector3d p = m.GetVertex(v);
                sb.Append(v).Append(':').Append(BitConverter.DoubleToInt64Bits(p.x)).Append(',')
                    .Append(BitConverter.DoubleToInt64Bits(p.y)).Append(',').Append(BitConverter.DoubleToInt64Bits(p.z)).Append(';');
            }
            foreach (int t in m.TriangleIndices())
                sb.Append(t).Append(':').Append(m.GetTriangle(t)).Append(';');
            return sb.ToString();
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void Checked_SameResultAsUnchecked(string name)
        {
            // the checks throw if an incremental search or a canonical id differs; the result is the one without them
            ExactMeshBoolean plain = Run(Case(name));
            ExactMeshBoolean checkedRun = Run(Case(name), check: true);
            Assert.Equal(Print(plain.Result), Print(checkedRun.Result));
            Assert.Equal(plain.RoundingClean, checkedRun.RoundingClean);
            MeshRoundingRepair r = checkedRun.Rounding;
            Assert.NotNull(r);
            Assert.True(r.FullPairSearches >= 1);
        }

        [Fact]
        public void Searches_IncrementalAfterEdits()
        {
            // the repairs edit (and search again): over the cases, searches of the changed triangles and searches
            // skipped because nothing changed both happen, and every result is clean
            int incremental = 0, unchanged = 0;
            foreach (object[] c in Cases()) {
                ExactMeshBoolean b = Run(Case((string)c[0]), check: true);
                MeshRoundingRepair r = b.Rounding;
                incremental += r.IncrementalPairSearches;
                unchanged += r.UnchangedPairSearches;
                // (folded clusters are left unclean, see SafeRoundingDegenerateInputTests, and so is the UTM cluster with
                // every 9th triangle)
                if (((string)c[0]).Contains("FoldedCluster") == false && (string)c[0] != "utm Cluster 0 9 1") {
                    Assert.True(r.IsClean, (string)c[0]);
                    Assert.Equal("", MeshRobustRepair.NotCleanReason(b.Result));
                }
            }
            Assert.True(incremental > 0, "no incremental search");
            Assert.True(unchanged > 0, "no search skipped");
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void SerialEqualsParallel_BitIdentical(string name)
        {
            string serial = Print(Run(Case(name), serial: true).Result);
            for (int run = 0; run < 3; ++run)
                Assert.True(serial == Print(Run(Case(name)).Result), $"parallel run {run} differs from the serial run");
        }

        [Fact]
        public void ReusedInstance_MeshEditedBetween_EqualsFreshInstance()
        {
            // Apply, then a vertex pushed through the sphere to beyond its far side (new intersecting pairs, no edit of the repair marks
            // them), then Apply again on the same instance: the pairs of the last Apply must not be reused
            DMesh3 m = SafeRoundingDegenerateInputTests.Make(Family.Sliver, 30, 1);
            var reused = new MeshRoundingRepair(m) { SharedPositionsTouch = true };
            Assert.True(reused.Apply());
            int v = m.VertexIndices().First();
            m.SetVertex(v, -1.5 * m.GetVertex(v));
            DMesh3 copy = new DMesh3(m);
            MeshRoundingRepair.CheckOnThisThread = true;
            try {
                reused.Apply();
            } finally {
                MeshRoundingRepair.CheckOnThisThread = false;
            }
            var fresh = new MeshRoundingRepair(copy) { SharedPositionsTouch = true };
            fresh.Apply();
            Assert.True(fresh.InitialIntersections > 0);
            Assert.Equal(fresh.InitialIntersections, reused.InitialIntersections);
            Assert.Equal(fresh.RemainingIntersections, reused.RemainingIntersections);
            Assert.Equal(Print(copy), Print(m));
        }

        [Fact]
        public void TinyComponentRemoved_ItsPairsGone()
        {
            DMesh3 m = SphereWithFlatTetrahedron();
            MeshRoundingRepair.CheckOnThisThread = true;
            try {
                var r = new MeshRoundingRepair(m) { SharedPositionsTouch = true };
                Assert.True(r.Apply());
                Assert.True(r.InitialIntersections > 0);
                Assert.Equal(1, r.RemovedComponents);
                Assert.Equal(4, r.RemovedTriangles);
                Assert.Equal(0, r.RemainingIntersections);
                Assert.Equal("", MeshRobustRepair.NotCleanReason(m));
            } finally {
                MeshRoundingRepair.CheckOnThisThread = false;
            }
        }

        [Fact]
        public void Utm_PowerOfTwoScales_SameResultScaled()
        {
            // the incremental searches under the exact similarities (2^k scales): the same mesh, mapped back, bit for bit
            DMesh3 input = Utm(Family.Cluster, 0, 4, 0);
            ExactMeshBoolean b0 = Run(() => new ExactMeshBoolean(new DMesh3(input), new DMesh3(), Ops.Union), check: true);
            Assert.True(b0.Rounding.IncrementalPairSearches > 0);
            foreach (Similarity sim in Similarity.All().Where(s => s.IsExact)) {
                DMesh3 scaled = Invariance.Transformed(input, sim);
                ExactMeshBoolean b = Run(() => new ExactMeshBoolean(scaled, new DMesh3(), Ops.Union), check: true);
                Assert.True(Invariance.Difference(b0.Result, Invariance.MappedBack(b.Result, sim)) == "", sim.ToString());
                Assert.Equal(b0.Rounding.MaxDrift * sim.Scale, b.Rounding.MaxDrift);
                Assert.Equal(b0.Rounding.IncrementalPairSearches, b.Rounding.IncrementalPairSearches);
            }
        }

        static DMesh3 Input(string name)
        {
            if (name.StartsWith("utm ")) {
                string[] w = name.Split(' ');
                return Utm((Family)Enum.Parse(typeof(Family), w[1]), int.Parse(w[2]), int.Parse(w[3]), int.Parse(w[4]));
            }
            Family f = (Family)Enum.Parse(typeof(Family), name);
            return SafeRoundingDegenerateInputTests.Make(f, f == Family.Cluster || f == Family.FoldedCluster ? 36 : 30, 1);
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void PastTheLimit_SameAsProposingInFull(string name)
        {
            // past the evaluation limit try_move only computes the drift of the move (the checked run proposes it in
            // full, through improves): the same result, counts and SmallestRejectedDrift
            int reached = 0;
            foreach (long limit in new long[] { 200, 2000, 5000, 20000 }) {
                DMesh3 fast = Input(name), full = new DMesh3(fast);
                var rf = new MeshRoundingRepair(fast) { SharedPositionsTouch = true, MaxPairTests = limit };
                rf.Apply();
                var rc = new MeshRoundingRepair(full) { SharedPositionsTouch = true, MaxPairTests = limit };
                MeshRoundingRepair.CheckOnThisThread = true;
                try {
                    rc.Apply();
                } finally {
                    MeshRoundingRepair.CheckOnThisThread = false;
                }
                Assert.Equal(rc.EvaluationLimitReached, rf.EvaluationLimitReached);
                // (the checked run proposes in full, the other takes the shortcut)
                Assert.Equal(0, rc.MovesPastTheLimit);
                if (rf.EvaluationLimitReached)
                    reached++;
                Assert.Equal(BitConverter.DoubleToInt64Bits(rc.SmallestRejectedDrift), BitConverter.DoubleToInt64Bits(rf.SmallestRejectedDrift));
                Assert.Equal(rc.Moves + rc.Flips + rc.Collapses + rc.Zips + rc.VertexRemovals, rf.Moves + rf.Flips + rf.Collapses + rf.Zips + rf.VertexRemovals);
                Assert.Equal(rc.RemainingIntersections, rf.RemainingIntersections);
                Assert.Equal(Print(full), Print(fast));
                output.WriteLine($"{name} limit {limit}: reached {rf.EvaluationLimitReached}, moves past it {rf.MovesPastTheLimit}, smallest rejected {rf.SmallestRejectedDrift:R}, bound {rf.MaxLength:R}");
                if (name == "utm Cluster 0 9 1" && limit == 5000) {
                    // the smallest rejected drift from a move past the limit: without those moves it is larger
                    Assert.True(rf.EvaluationLimitReached && rf.MovesPastTheLimit > 0);
                    var none = new MeshRoundingRepair(Input(name)) { SharedPositionsTouch = true, MaxPairTests = limit };
                    none.SkipMovesPastTheLimit = true;
                    none.Apply();
                    Assert.True(none.SmallestRejectedDrift > rf.SmallestRejectedDrift);
                }
            }
            if (name.Contains("Cluster"))
                Assert.True(reached > 0, "the limit is never reached");
        }

        [Fact]
        public void PastTheLimit_ReusedInstance_EqualsFreshInstance()
        {
            // past the limit, the drift of the moves' neighbourhoods is kept per vertex: a reused instance starts again
            var reused = new MeshRoundingRepair(Input("utm Cluster 0 4 0")) { SharedPositionsTouch = true, MaxPairTests = 5000 };
            reused.Apply();
            Assert.True(reused.EvaluationLimitReached);
            DMesh3 m = Input("utm Cluster 0 9 1"), copy = new DMesh3(m);
            reused.Mesh = m;
            reused.Apply();
            var fresh = new MeshRoundingRepair(copy) { SharedPositionsTouch = true, MaxPairTests = 5000 };
            fresh.Apply();
            Assert.True(fresh.EvaluationLimitReached);
            Assert.True(fresh.SmallestRejectedDrift < double.PositiveInfinity);
            Assert.Equal(BitConverter.DoubleToInt64Bits(fresh.SmallestRejectedDrift), BitConverter.DoubleToInt64Bits(reused.SmallestRejectedDrift));
            Assert.Equal(Print(copy), Print(m));
        }

        [Theory]
        [MemberData(nameof(Cases))]
        public void SharedByIdOnly_SameResultChecked(string name)
        {
            // without SharedPositionsTouch (shared vertices by id, no canonical ids): the incremental searches checked
            DMesh3 plain = Input(name), checkedMesh = new DMesh3(plain);
            var rp = new MeshRoundingRepair(plain);
            rp.Apply();
            var rc = new MeshRoundingRepair(checkedMesh);
            MeshRoundingRepair.CheckOnThisThread = true;
            try {
                rc.Apply();
            } finally {
                MeshRoundingRepair.CheckOnThisThread = false;
            }
            Assert.Equal(Print(plain), Print(checkedMesh));
            Assert.Equal(rp.RemainingIntersections, rc.RemainingIntersections);
        }
    }
}

using System;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Each edit of MeshRoundingRepair on its own, on hand-built meshes where only that edit can fix the defect: the
    /// counts, the resulting topology and positions, not only a clean result. Found with the mutation tests
    /// (tests/mutation, stryker-mesh-rounding.json): the tests of the whole repair passed with the flip, the zip or the
    /// move of a cap's apex broken, because another edit or a later pass fixed the mesh as well.
    /// </summary>
    public class MeshRoundingRepairStrategyTests
    {
        static double AreaEps(DMesh3 m)
        {
            double diag = MeshRepairMetrics.TriangleBounds(m).DiagonalLength;
            return 1e-12 * diag * diag;
        }

        static int Degenerate(DMesh3 m)
        {
            double eps = AreaEps(m);
            return m.TriangleIndices().Count(t => m.GetTriArea(t) < eps);
        }

        static void AssertCounts(MeshRoundingRepair r, int collapses, int flips, int moves, int zips)
        {
            Assert.Equal(collapses, r.Collapses);
            Assert.Equal(flips, r.Flips);
            Assert.Equal(moves, r.Moves);
            Assert.Equal(zips, r.Zips);
            Assert.Equal(0, r.RemovedComponents);
        }

        [Fact]
        public void Cap_FlippedAcrossItsLongestEdge()
        {
            // T = (a, b, c) with c on the segment (a, b), U = (b, a, d) across it; all edges far longer than the
            // contraction limit, so the cap is fixed by flipping (a, b): (c, d, b) and (d, c, a)
            var m = new DMesh3();
            int a = m.AppendVertex(new Vector3d(0, 0, 0)), b = m.AppendVertex(new Vector3d(2, 0, 0));
            int c = m.AppendVertex(new Vector3d(1, 0, 0)), d = m.AppendVertex(new Vector3d(1, -1, 0));
            m.AppendTriangle(a, b, c);
            m.AppendTriangle(b, a, d);
            Assert.Equal(1, Degenerate(m));
            var r = new MeshRoundingRepair(m);
            Assert.True(r.Apply());
            AssertCounts(r, 0, 1, 0, 0);
            Assert.Equal(1, r.InitialDegenerate);
            Assert.Equal(0, r.RemainingDegenerate);
            Assert.True(m.FindEdge(a, b) < 0);
            Assert.True(m.FindEdge(c, d) >= 0);
            Assert.Equal(2, m.TriangleCount);
            Assert.Equal(0, Degenerate(m));
            Assert.True(m.CheckValidity(true, FailMode.ReturnOnly));
            // the vertices stay where they were
            Assert.Equal(new Vector3d(1, 0, 0), m.GetVertex(c));
        }

        // Two caps on both sides of (a, b), T = (a, b, c) and U = (b, a, d), apexes at 1/4 and 3/4 of the edge (in
        // either order): a flip gives two caps again, so the two sides are zipped together. N1 is the neighbour of T
        // and N2 that of U along the edge, x and y their third corners.
        static DMesh3 TwoCaps(bool cFirst, out int a, out int b, out int c, out int d, out int x, out int y)
        {
            var m = new DMesh3();
            a = m.AppendVertex(new Vector3d(0, 0, 0));
            b = m.AppendVertex(new Vector3d(4, 0, 0));
            c = m.AppendVertex(new Vector3d(cFirst ? 1 : 3, 0, 0));
            d = m.AppendVertex(new Vector3d(cFirst ? 3 : 1, 0, 0));
            x = m.AppendVertex(new Vector3d(2, 1, 0));
            y = m.AppendVertex(new Vector3d(2, -1, 0));
            m.AppendTriangle(a, b, c);
            m.AppendTriangle(b, a, d);
            if (cFirst) {
                // order a, c, d, b: N1 = (c, b, x) across (b, c), N2 = (d, a, y) across (a, d)
                m.AppendTriangle(c, b, x);
                m.AppendTriangle(d, a, y);
            } else {
                // order a, d, c, b: N1 = (a, c, x) across (c, a), N2 = (b, d, y) across (d, b)
                m.AppendTriangle(a, c, x);
                m.AppendTriangle(b, d, y);
            }
            return m;
        }

        [Theory]
        [InlineData(true)]
        [InlineData(false)]
        public void TwoCaps_Zipped(bool cFirst)
        {
            int a, b, c, d, x, y;
            DMesh3 m = TwoCaps(cFirst, out a, out b, out c, out d, out x, out y);
            Assert.Equal(2, Degenerate(m));
            Assert.True(m.CheckValidity(true, FailMode.ReturnOnly));
            var r = new MeshRoundingRepair(m);
            Assert.True(r.Apply());
            AssertCounts(r, 0, 0, 0, 1);
            Assert.Equal(2, r.InitialDegenerate);
            Assert.Equal(0, r.RemainingDegenerate);
            // the caps and their neighbours are replaced by four triangles: (a, b) is gone, the apexes are joined,
            // and x and y are joined to the apex they were not joined to (d and c)
            Assert.Equal(4, m.TriangleCount);
            Assert.True(m.FindEdge(a, b) < 0);
            Assert.True(m.FindEdge(c, d) >= 0);
            Assert.True(m.FindEdge(d, x) >= 0 && m.FindEdge(c, y) >= 0);
            Assert.True(m.FindEdge(c, x) >= 0 && m.FindEdge(d, y) >= 0);
            Assert.Equal(0, Degenerate(m));
            Assert.True(m.CheckValidity(true, FailMode.ReturnOnly));
            // all triangles keep the orientation of the input (normal +z), and they cover what N1 and N2 covered
            foreach (int t in m.TriangleIndices())
                Assert.True(m.GetTriNormal(t).z > 0.999, $"triangle {t} turned over");
            Assert.Equal(3.0, m.TriangleIndices().Sum(t => m.GetTriArea(t)), 12);
        }

        // A cap T = (a, b, c) on the boundary edge (a, b) of a fan around its apex c, so that neither a flip nor a
        // zip can fix it: the apex is moved off the edge, by twice the height that gives the degenerate area. The
        // edge does not pass through the origin, and the other neighbour is off-centre, so that the direction of the
        // move depends on every term.
        static DMesh3 FanWithCap(double apexOffset, out int a, out int b, out int c, out int x)
        {
            var m = new DMesh3();
            Vector3d o = new Vector3d(0.5, 3, -2);
            a = m.AppendVertex(o + new Vector3d(0, 0, 0));
            b = m.AppendVertex(o + new Vector3d(2, 0, 0));
            c = m.AppendVertex(o + new Vector3d(1, apexOffset, 0));
            x = m.AppendVertex(o + new Vector3d(1.5, 1, 0.5));
            m.AppendTriangle(a, b, c);
            m.AppendTriangle(c, b, x);
            m.AppendTriangle(a, c, x);
            return m;
        }

        [Fact]
        public void Cap_ApexOnTheEdge_MovedTowardsItsNeighbours()
        {
            int a, b, c, x;
            DMesh3 m = FanWithCap(0, out a, out b, out c, out x);
            Assert.False(m.IsBoundaryVertex(c));
            Assert.Equal(1, Degenerate(m));
            Vector3d pa = m.GetVertex(a), pb = m.GetVertex(b), pc = m.GetVertex(c), px = m.GetVertex(x);
            double areaEps = AreaEps(m);
            var r = new MeshRoundingRepair(m);
            Assert.True(r.Apply());
            AssertCounts(r, 0, 0, 1, 0);
            Assert.Equal(pa, m.GetVertex(a));
            Assert.Equal(pb, m.GetVertex(b));
            Assert.Equal(px, m.GetVertex(x));
            // towards the centroid of a, b and x, perpendicular to (a, b), by twice the height h of the degenerate area
            Vector3d dir = (pb - pa).Normalized;
            Vector3d off = (pa + pb + px) / 3 - pc;
            off = (off - off.Dot(dir) * dir).Normalized;
            Vector3d moved = m.GetVertex(c) - pc;
            double h = 2 * areaEps / pa.Distance(pb);
            Assert.Equal(2 * h, moved.Length, 2 * h * 1e-3);
            Assert.True(moved.Normalized.Distance(off) < 1e-6, $"moved along {moved.Normalized}, expected {off}");
            Assert.Equal(0, Degenerate(m));
        }

        [Fact]
        public void Cap_ApexOffTheEdge_MovedAwayFromIt()
        {
            // the apex 1e-13 above the edge (area 1e-13, below the degenerate area of about 5e-12): moved further
            // in the same direction, perpendicular to the edge
            int a, b, c, x;
            DMesh3 m = FanWithCap(1e-13, out a, out b, out c, out x);
            Assert.Equal(1, Degenerate(m));
            Vector3d pa = m.GetVertex(a), pb = m.GetVertex(b), pc = m.GetVertex(c);
            double areaEps = AreaEps(m);
            var r = new MeshRoundingRepair(m);
            Assert.True(r.Apply());
            AssertCounts(r, 0, 0, 1, 0);
            Vector3d q = m.GetVertex(c);
            Assert.Equal(pc.x, q.x);
            Assert.Equal(pc.z, q.z);
            double h = 2 * areaEps / pa.Distance(pb);
            Assert.Equal(pc.y + 2 * h, q.y, 2 * h * 1e-3);
            Assert.Equal(0, Degenerate(m));
        }

        // A closed box of size 1 x 1 x t with a needle (an edge split 1e-12 from its end), far from a unit sphere. Once
        // the needle is contracted the box is an edited component; it is removed if it is thinner than the
        // displacement limit (2 V / A below MaxDisplacement times the diagonal), else kept. open removes one of its
        // triangles (away from the needle): an open component is never removed.
        static DMesh3 SphereAndSlab(double t, bool open, out int sphereTriangles, out double maxLength)
        {
            DMesh3 m = new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = 6 }.Generate().MakeDMesh();
            MeshTransforms.Translate(m, new Vector3d(3, 0, 0));
            sphereTriangles = m.TriangleCount;
            DMesh3 slab = new TrivialBox3Generator() { Box = new Box3d(new Vector3d(0.5, 0.5, t / 2), new Vector3d(0.5, 0.5, t / 2)) }.Generate().MakeDMesh();
            int eid = slab.EdgeIndices().First(e => {
                Index2i v = slab.GetEdgeV(e);
                return Math.Abs(slab.GetVertex(v.a).z - slab.GetVertex(v.b).z) < 1e-30;
            });
            Index2i ev = slab.GetEdgeV(eid);
            Vector3d pa = slab.GetVertex(ev.a), pb = slab.GetVertex(ev.b);
            DMesh3.EdgeSplitInfo split;
            Assert.Equal(MeshResult.Ok, slab.SplitEdge(eid, out split));
            slab.SetVertex(split.vNew, pa + 1e-12 * (pb - pa).Normalized);
            if (open) {
                Vector3d pn = slab.GetVertex(split.vNew);
                int far = slab.TriangleIndices().OrderByDescending(tid => slab.GetTriCentroid(tid).Distance(pn)).First();
                slab.RemoveTriangle(far, true, false);
            }
            new MeshEditor(m).AppendMesh(slab);
            maxLength = 1e-5 * MeshRepairMetrics.TriangleBounds(m).DiagonalLength;
            return m;
        }

        [Theory]
        [InlineData(2e-5, false, true)]     // thinner than the limit (about 4.9e-5): removed
        [InlineData(1e-3, false, false)]    // thicker: kept
        [InlineData(2e-5, true, false)]     // thin but open: kept
        public void ThinComponent_RemovedOnlyIfClosedAndThin(double t, bool open, bool removed)
        {
            int n;
            double maxLength;
            DMesh3 m = SphereAndSlab(t, open, out n, out maxLength);
            // thickness 2 V / A of the closed slab: t / (1 + 2 t), against the limit
            Assert.True((t < maxLength) == removed || open);
            int before = m.TriangleCount;
            var r = new MeshRoundingRepair(m);
            r.Apply();
            Assert.Equal(1, r.Collapses);
            Assert.Equal(0, r.RemainingDegenerate);
            if (removed) {
                Assert.Equal(1, r.RemovedComponents);
                Assert.Equal(n, m.TriangleCount);
                Assert.Equal(before - 2 - n, r.RemovedTriangles);
                Assert.True(m.IsClosed());
            } else {
                Assert.Equal(0, r.RemovedComponents);
                Assert.Equal(0, r.RemovedTriangles);
                Assert.Equal(before - 2, m.TriangleCount);
            }
        }

        [Fact]
        public void Apply_Twice_CountsOnlyTheSecondRun()
        {
            int a, b, c, d, x, y;
            DMesh3 m = TwoCaps(true, out a, out b, out c, out d, out x, out y);
            var r = new MeshRoundingRepair(m);
            Assert.True(r.Apply());
            Assert.Equal(1, r.Zips);
            // nothing left to do: all counts are reset
            Assert.True(r.Apply());
            AssertCounts(r, 0, 0, 0, 0);
            Assert.Equal(0, r.InitialDegenerate);
            Assert.Equal(4, m.TriangleCount);
        }
    }
}

using System;
using System.Linq;
using g3;
using gs;
using Xunit;
using Ops = g3.ExactMeshBoolean.Operations;

namespace geometry3Sharp.Tests
{
    // Rounding the exact output of ExactMeshBoolean to double without new self-intersections or degenerate
    // slivers (ExactMeshBoolean.SafeRounding, MeshRoundingRepair), and the exact output coordinates.
    public class MeshRoundingRepairTests
    {
        static double Volume(DMesh3 mesh)
        {
            return MeshMeasurements.VolumeArea(mesh, mesh.TriangleIndices(), mesh.GetVertex).x;
        }

        // [-1, 1]^3 and a copy rotated about axis by angle (radians) and shifted by shift
        static DMesh3[] NearlyCoincident(DMesh3 a, Vector3d axis, double angle, Vector3d shift)
        {
            DMesh3 b = new DMesh3(a);
            MeshTransforms.Rotate(b, Vector3d.Zero, new Quaterniond(axis.Normalized, angle * MathUtil.Rad2Deg));
            MeshTransforms.Translate(b, shift);
            return new[] { a, b };
        }

        static DMesh3 Cube()
        {
            return new TrivialBox3Generator() { Box = new Box3d(Vector3d.Zero, Vector3d.One) }.Generate().MakeDMesh();
        }

        static DMesh3 Sphere(int edgeVertices)
        {
            return new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = edgeVertices }.Generate().MakeDMesh();
        }

        static int Degenerate(DMesh3 m)
        {
            double diag = m.CachedBounds.DiagonalLength;
            return m.TriangleIndices().Count(t => m.GetTriArea(t) < 1e-12 * diag * diag);
        }

        static ExactMeshBoolean Run(DMesh3[] ab, Ops op, bool safe)
        {
            var b = new ExactMeshBoolean(ab[0], ab[1], op) { SafeRounding = safe };
            Assert.True(b.Compute(), b.Error);
            Assert.True(b.Result.CheckValidity(true, FailMode.ReturnOnly));
            return b;
        }

        // the result is clean (closed, no bowties, no degenerate triangles, no inside-out components, no
        // self-intersections), checked independently of MeshRoundingRepair's own counts
        static void AssertClean(ExactMeshBoolean b)
        {
            Assert.True(b.RoundingClean, $"remaining {b.Rounding.RemainingIntersections} intersections, {b.Rounding.RemainingDegenerate} degenerate");
            Assert.Equal("", MeshRobustRepair.NotCleanReason(b.Result, true));
            Assert.Equal(0, MeshRepairMetrics.SelfIntersections(b.Result));
            Assert.Equal(0, Degenerate(b.Result));
        }


        [Fact]
        public void NearlyCoincidentBoxes_Intersection_RoundingMadeSelfIntersections()
        {
            // the cube and a copy turned by 1e-10: intersection points 1e-10 apart and closer
            var ab = NearlyCoincident(Cube(), new Vector3d(0.19758121236114823, 0.3649866608274107, -0.30151001680712686), 1e-10,
                1e-10 * new Vector3d(0.5604903733173806, 0.1805782146661441, 0.2501971587772468));
            var plain = Run(ab, Ops.Intersection, false);
            // without the repair: rounding left self-intersections and slivers
            Assert.True(MeshRepairMetrics.SelfIntersections(plain.Result) > 0);
            Assert.True(Degenerate(plain.Result) > 0);
            Assert.Null(plain.Rounding);

            var safe = Run(ab, Ops.Intersection, true);
            AssertClean(safe);
            Assert.True(safe.Rounding.InitialIntersections > 0);
            Assert.Equal(8.0, Volume(safe.Result), 6);
        }

        [Theory]
        [InlineData(1e-9)]
        [InlineData(1e-11)]
        [InlineData(1e-13)]
        public void NearlyCoincidentBoxes_UnionIntersection_NoSlivers(double eps)
        {
            var ab = NearlyCoincident(Cube(), new Vector3d(0.3, 0.5, 0.8), eps, eps * new Vector3d(0.7, 0.2, 0.4));
            foreach (Ops op in new[] { Ops.Union, Ops.Intersection }) {
                Assert.True(Degenerate(Run(ab, op, false).Result) > 0);
                var safe = Run(ab, op, true);
                AssertClean(safe);
                Assert.Equal(8.0, Volume(safe.Result), 6);
            }
        }

        [Fact]
        public void NearlyCoincidentSpheres_UnionIntersection_Clean()
        {
            // intersection curves that cross each other everywhere, at 1e-14
            var ab = NearlyCoincident(Sphere(4), new Vector3d(-0.14007338678467712, -0.23429536387990013, 0.3179190721446271), 1e-14,
                1e-14 * new Vector3d(0.5500672480790257, 0.4904806467194486, 0.45565309583007035));
            foreach (Ops op in new[] { Ops.Union, Ops.Intersection }) {
                var plain = Run(ab, op, false);
                Assert.True(MeshRepairMetrics.SelfIntersections(plain.Result) > 0);
                var safe = Run(ab, op, true);
                AssertClean(safe);
                Assert.Equal(Volume(plain.Result), Volume(safe.Result), 6);
            }
        }

        [Fact]
        public void NearlyCoincidentSpheres_Difference_ThinSliversRemoved()
        {
            // the difference of nearly coincident solids is a set of slivers thinner than 1e-10: removed as
            // components thinner than MaxDisplacement (their volume is below 1e-9)
            foreach (double eps in new[] { 1e-8, 1e-10, 1e-12 }) {
                var ab = NearlyCoincident(Sphere(10), new Vector3d(0.6, 0.3, 0.1), eps, eps * new Vector3d(0.2, 0.9, 0.5));
                var plain = Run(ab, Ops.Difference, false);
                Assert.True(Degenerate(plain.Result) > 0);
                Assert.True(Math.Abs(Volume(plain.Result)) < 1e-6);
                var safe = Run(ab, Ops.Difference, true);
                Assert.True(safe.RoundingClean);
                Assert.Equal(0, MeshRepairMetrics.SelfIntersections(safe.Result));
                Assert.Equal(0, Degenerate(safe.Result));
