using System;
using System.Linq;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The options of Reducer.PreventFoldOver (BoundaryTriangleMinNormalDot, ReferenceNormalMinLength, off). The
    /// behaviour with the defaults is in ReducerFoldOverTests, which also compiles against upstream.
    /// </summary>
    public class ReducerFoldOverOptionsTests
    {
        /// <summary> an open height field over [0,nx] x [0,ny] (unit cells, two triangles each, normals +z) </summary>
        static DMesh3 Grid(int nx, int ny, Func<int, int, double> z)
        {
            var m = new DMesh3();
            int[,] vid = new int[nx + 1, ny + 1];
            for (int j = 0; j <= ny; ++j)
                for (int i = 0; i <= nx; ++i)
                    vid[i, j] = m.AppendVertex(new Vector3d(i, j, z(i, j)));
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < nx; ++i) {
                    m.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    m.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            return m;
        }

        /// <summary> x rounded to a multiple of 2^-30 (the same input on net48 and net10 despite Math.Sin) </summary>
        static double R(double x) => Math.Round(x * (1 << 30)) / (1 << 30);

        // a 40 x 40 hill (amplitude 3) with noise of +-noise/2, all normals up
        static DMesh3 NoisyTerrain(int seed, double noise = 0.8)
        {
            var rnd = new Random(seed);
            return Grid(40, 40, (i, j) => R(3 * Math.Sin(0.2 * i) * Math.Cos(0.15 * j) + noise * (rnd.NextDouble() - 0.5)));
        }

        /// <summary> triangles whose normal does not point up: folded over, or standing on edge (a wall) </summary>
        static int NotUp(DMesh3 m) => m.TriangleIndices().Count(t => !(m.GetTriNormal(t).z > 0));

        static void AssertValid(DMesh3 m)
        {
            Assert.True(m.CheckValidity(false, FailMode.ReturnOnly));
            Assert.True(Invariance.AllFinite(m));
        }

        [Fact]
        public void BoundaryTriangleMinNormalDot_ControlsTheWalls()
        {
            // the walls: with only the sign test (BoundaryTriangleMinNormalDot 0) some stay, the default removes them;
            // without PreventFoldOver also folds stay
            int walls(DMesh3 m) => m.TriangleIndices().Count(t => m.GetTriNormal(t).z == 0);
            int signOnly = 0, byDefault = 0, off = 0;
            for (int seed = 1; seed <= 3; ++seed) {
                DMesh3 input = NoisyTerrain(seed);
                DMesh3 a = new DMesh3(input), b = new DMesh3(input), c = new DMesh3(input);
                new Reducer(a) { BoundaryTriangleMinNormalDot = 0 }.ReduceToTriangleCount(input.TriangleCount / 5);
                new Reducer(b).ReduceToTriangleCount(input.TriangleCount / 5);
                new Reducer(c) { PreventFoldOver = false }.ReduceToTriangleCount(input.TriangleCount / 5);
                signOnly += walls(a); byDefault += NotUp(b); off += NotUp(c);
            }
            Assert.True(signOnly > 0, "the sign test alone leaves walls on these inputs");
            Assert.Equal(0, byDefault);
            Assert.True(off > byDefault, "without PreventFoldOver the folds stay");
        }

        [Theory]
        [InlineData(0.005, 30)]
        [InlineData(0.0001, 40)]
        public void ThinPlate_ReachesTheTarget(double thickness, int edgeVertices)
        {
            // on the rim of a thin plate the absorbed normals of both sides cancel: the reference says nothing there and
            // the collapse is not rejected for it (otherwise the plate stops far above its target)
            DMesh3 plate = new GridBox3Generator() {
                Box = new Box3d(Vector3d.Zero, new Vector3d(1, 1, thickness)), EdgeVertices = edgeVertices }.Generate().MakeDMesh();
            DMesh3 off = new DMesh3(plate);
            new Reducer(plate).ReduceToTriangleCount(12);
            new Reducer(off) { PreventFoldOver = false }.ReduceToTriangleCount(12);
            AssertValid(plate);
            Assert.True(plate.IsClosed());
            Assert.Equal(off.TriangleCount, plate.TriangleCount);
        }

        [Fact]
        public void BoxesTouchingAtAFace_CancellingNormalsAreNoReference()
        {
            // two closed boxes sharing the region of a face (PreventSelfIntersections keeps it): at the shared face the
            // absorbed normals of both boxes cancel. Taken as a reference anyway (ReferenceNormalMinLength 0), it blocks
            // collapses there (558 triangles instead of 540, the count without PreventFoldOver)
            DMesh3 a = new GridBox3Generator() { EdgeVertices = 10, Box = new Box3d(Vector3d.Zero, new Vector3d(10, 10, 10)) }.Generate().MakeDMesh();
            DMesh3 b = new DMesh3(a);
            MeshTransforms.Translate(b, new Vector3d(20, 0, 0));
            new MeshEditor(a).AppendMesh(b);
            DMesh3 guarded = new DMesh3(a), unguarded = new DMesh3(a), off = new DMesh3(a);
            new Reducer(guarded) { PreventSelfIntersections = true }.ReduceToTriangleCount(194);
            new Reducer(unguarded) { PreventSelfIntersections = true, ReferenceNormalMinLength = 0 }.ReduceToTriangleCount(194);
            new Reducer(off) { PreventSelfIntersections = true, PreventFoldOver = false }.ReduceToTriangleCount(194);
            Assert.Equal(off.TriangleCount, guarded.TriangleCount);
            Assert.True(unguarded.TriangleCount > guarded.TriangleCount, $"{unguarded.TriangleCount} vs {guarded.TriangleCount}");
        }

        [Theory]
        [InlineData(1)]
        [InlineData(2)]
        public void NoisyTerrain_BoundaryNotPreserved_NoTriangleTurnsDown(int seed)
        {
            // without PreserveBoundaryShape boundary vertices move and an interior vertex can be kept where a boundary
            // vertex was removed: the boundary rule reads the boundary edges of the current mesh, not those of the start.
            // Without PreventFoldOver: seed 1 an interior fold, seed 2 a wall with two boundary edges. (Seed 3 leaves an
            // interior sliver standing nearly vertical, n.z = -0.02, within 90 degrees of its reference: the documented
            // limit of the check.)
            DMesh3 input = NoisyTerrain(seed);
            DMesh3 m = new DMesh3(input);
            new Reducer(m) { PreserveBoundaryShape = false }.ReduceToTriangleCount(input.TriangleCount / 5);
            AssertValid(m);
            Assert.Equal(0, NotUp(m));
        }

        [Fact]
        public void OpenBandsAndStrips_ReachAsWithoutTheCheck()
        {
            // every triangle of a band one cell wide has all three corners on the boundary, so the boundary rule applies
            // to all of them, not only to walls on a straight border: a curved band and a twisted strip must still reach
            // what they reach without PreventFoldOver
            DMesh3 band = new OpenCylinderGenerator() { BaseRadius = 1, TopRadius = 1, Height = 0.3f, Slices = 64 }.Generate().MakeDMesh();
            DMesh3 tall = new OpenCylinderGenerator() { BaseRadius = 1, TopRadius = 1, Height = 3, Slices = 64 }.Generate().MakeDMesh();
            DMesh3 strip = Grid(60, 1, (i, j) => 0);
            foreach (int v in strip.VertexIndices().ToList()) {
                // a quarter turn about the x axis along the strip, and a bend in the xy plane
                Vector3d p = strip.GetVertex(v);
                double t = p.x / 60 * Math.PI / 2, y = p.y - 0.5;
                strip.SetVertex(v, new Vector3d(p.x, 5 * Math.Sin(p.x / 20) + y * Math.Cos(t), y * Math.Sin(t)));
            }
            foreach (var (name, mesh, target) in new[] { ("band", band, 8), ("tall band", tall, 16), ("strip", strip, 8) }) {
                DMesh3 on = new DMesh3(mesh), off = new DMesh3(mesh);
                new Reducer(on).ReduceToTriangleCount(target);
                new Reducer(off) { PreventFoldOver = false }.ReduceToTriangleCount(target);
                AssertValid(on);
                Assert.True(on.TriangleCount <= off.TriangleCount, $"{name}: {on.TriangleCount} triangles, {off.TriangleCount} without the check");
            }
        }

        [Fact]
        public void HugeCoordinates_NoReference_SameReductionAsWithoutTheCheck()
        {
            // at coordinates of 2^540 the cross products overflow: the references and the new normals are infinite, which
            // says nothing, so only the usual check applies (taken as a reference, every collapse would be refused)
            DMesh3 sphere = new Sphere3Generator_NormalizedCube() { EdgeVertices = 12, Radius = 1 }.Generate().MakeDMesh();
            MeshTransforms.Scale(sphere, Math.Pow(2, 540));
            DMesh3 on = new DMesh3(sphere), off = new DMesh3(sphere);
            new Reducer(on).ReduceToTriangleCount(100);
            new Reducer(off) { PreventFoldOver = false }.ReduceToTriangleCount(100);
            Assert.True(off.TriangleCount < sphere.TriangleCount, "the usual check reduces at this scale");
            Assert.Equal("", Invariance.Difference(off, on));
        }

        [Fact]
        public void FusedPass_SameReductionsAsTwoPasses()
        {
            // the flip test and the PreventFoldOver test in one pass over each one-ring (FusedFoldCheck, the default)
            // decide as the two passes did: the same meshes, bit for bit, over terrains, a noisy sphere and the settings
            // of MeshRobustRepair.SimplifyWithin, without preserved boundary and in FastCollapsePass
            var inputs = new System.Collections.Generic.List<(string, DMesh3)>();
            for (int seed = 1; seed <= 4; ++seed)
                foreach (double noise in new[] { 0.4, 0.8, 1.6 }) {
                    var rnd = new Random(seed);
                    inputs.Add(($"terrain {seed} {noise}", Grid(40, 40, (i, j) => R(3 * Math.Sin(0.2 * i) * Math.Cos(0.15 * j) + noise * (rnd.NextDouble() - 0.5)))));
                }
            DMesh3 sphere = new Sphere3Generator_NormalizedCube() { EdgeVertices = 30, Radius = 1 }.Generate().MakeDMesh();
            var srnd = new Random(7);
            foreach (int v in sphere.VertexIndices().ToList())
                sphere.SetVertex(v, sphere.GetVertex(v) * (1 + 0.05 * (srnd.NextDouble() - 0.5)));
            inputs.Add(("noisy sphere", sphere));
            var settings = new (string, Action<Reducer, DMesh3>)[] {
                ("to 20 %", (r, m) => r.ReduceToTriangleCount(m.TriangleCount / 5)),
                ("to 2 %", (r, m) => r.ReduceToTriangleCount(m.TriangleCount / 50)),
                ("SimplifyWithin settings", (r, m) => {
                    r.AreaWeightedQuadrics = false; r.MinCollapseTriangleQuality = 0.05; r.EdgeFlipTolerance = Math.Cos(60 * MathUtil.Deg2Rad);
                    r.ReduceToTriangleCount(m.TriangleCount / 10); }),
                ("boundary not preserved", (r, m) => { r.PreserveBoundaryShape = false; r.ReduceToTriangleCount(m.TriangleCount / 10); }),
                ("fast collapse pass", (r, m) => r.FastCollapsePass(1.5, 3)) };
            foreach (var (name, input) in inputs)
                foreach (var (label, run) in settings) {
                    DMesh3 fused = new DMesh3(input), two = new DMesh3(input);
                    run(new Reducer(fused), input);
                    run(new Reducer(two) { FusedFoldCheck = false }, input);
                    Assert.True(fused.TriangleCount < input.TriangleCount, $"{name}, {label}: nothing collapsed");
                    Assert.True(Invariance.Difference(two, fused) == "", $"{name}, {label}: {Invariance.Difference(two, fused)}");
                }
        }
    }
}

using System;
using System.Linq;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Reducer.PreventFoldOver (finding S1, docs/ISSUE_CASE_FINDINGS.md): the new triangles of a collapse are checked
    /// against the input normals their corners have absorbed, not only against the current triangles, so chains of
    /// collapses do not fold a height field over, and no triangle stands up as a wall along a straight border.
    /// </summary>
    public class ReducerFoldOverTests
    {
        /// <summary> an open height field over [0,nx] x [0,ny] (unit cells, two triangles each, normals +z) </summary>
        static DMesh3 Grid(int nx, int ny, Func<int, int, double> z)
        {
            var m = new DMesh3();
            int[,] vid = new int[nx + 1, ny + 1];
            for (int j = 0; j <= ny; ++j)
                for (int i = 0; i <= nx; ++i)
                    vid[i, j] = m.AppendVertex(new Vector3d(i, j, z(i, j)));
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < nx; ++i) {
                    m.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    m.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            return m;
        }

        /// <summary> x rounded to a multiple of 2^-30 (the same input on net48 and net10 despite Math.Sin) </summary>
        static double R(double x) => Math.Round(x * (1 << 30)) / (1 << 30);

        // a 40 x 40 hill (amplitude 3) with noise of +-noise/2, all normals up
        static DMesh3 NoisyTerrain(int seed, double noise = 0.8)
        {
            var rnd = new Random(seed);
            return Grid(40, 40, (i, j) => R(3 * Math.Sin(0.2 * i) * Math.Cos(0.15 * j) + noise * (rnd.NextDouble() - 0.5)));
        }

        /// <summary> triangles whose normal does not point up: folded over, or standing on edge (a wall) </summary>
        static int NotUp(DMesh3 m) => m.TriangleIndices().Count(t => !(m.GetTriNormal(t).z > 0));

        static void AssertValid(DMesh3 m)
        {
            Assert.True(m.CheckValidity(false, FailMode.ReturnOnly));
            Assert.True(Invariance.AllFinite(m));
        }

        [Theory]
        [InlineData(1)]
        [InlineData(2)]
        [InlineData(3)]
        public void NoisyTerrain_ReducedTo20Percent_NoTriangleTurnsDown(int seed)
        {
            // https://github.com/zeux/meshoptimizer/issues/346: a chain of collapses, each passing the 90 degree flip test
            // against the current triangle, turned triangles of a terrain over (1, 4 and 2 of them for these seeds), and
            // collapses of interior vertices onto the border left vertical walls along it
            DMesh3 input = NoisyTerrain(seed);
            Assert.Equal(0, NotUp(input));
            DMesh3 m = new DMesh3(input);
            new Reducer(m).ReduceToTriangleCount(input.TriangleCount / 5);
            AssertValid(m);
            Assert.True(m.TriangleCount <= input.TriangleCount / 5 + 2, $"{m.TriangleCount} triangles");
            Assert.Equal(0, NotUp(m));
        }

        [Theory]
        [InlineData(1)]
        [InlineData(2)]
        [InlineData(3)]
        public void SmallPatch_ReducedTo10_NoWallOnTheBorder(int seed)
        {
            // https://github.com/zeux/meshoptimizer/issues/699 setting: a 4 x 3 grid with random heights (24 triangles)
            // reduced to 10. With seed 2, a triangle on three consecutive border vertices of y = 0 stood vertical
            // (the reference of the border vertices tilts towards the border, so a sign test passes it)
            var rnd = new Random(seed);
            DMesh3 input = Grid(4, 3, (i, j) => 0.3 * rnd.NextDouble());
            DMesh3 m = new DMesh3(input);
            new Reducer(m).ReduceToTriangleCount(10);
            AssertValid(m);
            Assert.True(m.TriangleCount <= 10, $"{m.TriangleCount} triangles");
            Assert.Equal(0, NotUp(m));
            foreach (int corner in new[] { 0, 4, 15, 19 })
                Assert.True(m.IsVertex(corner) && m.GetVertex(corner) == input.GetVertex(corner), $"corner {corner}");
        }

        [Fact]
        public void SharpShapes_ReachTheTarget()
        {
            // creases of 90 degrees (box, cylinder caps) and a smooth closed surface lose no reach
            DMesh3 box = new GridBox3Generator() { Box = new Box3d(Vector3d.Zero, new Vector3d(1, 2, 3)), EdgeVertices = 20 }.Generate().MakeDMesh();
            DMesh3 rod = new GridBox3Generator() { Box = new Box3d(Vector3d.Zero, new Vector3d(1, 0.01, 0.01)), EdgeVertices = 30 }.Generate().MakeDMesh();
            DMesh3 cyl = new CappedCylinderGenerator() { BaseRadius = 1, TopRadius = 1, Height = 3, Slices = 64 }.Generate().MakeDMesh();
            DMesh3 sphere = new Sphere3Generator_NormalizedCube() { EdgeVertices = 30, Radius = 1 }.Generate().MakeDMesh();
            foreach (var (mesh, target) in new[] { (box, 12), (rod, 12), (cyl, 20), (sphere, 20) }) {
                new Reducer(mesh).ReduceToTriangleCount(target);
                AssertValid(mesh);
                Assert.True(mesh.IsClosed());
                Assert.Equal(target, mesh.TriangleCount);
            }
        }

        [Fact]
        public void NoisyTerrain_InEveryFrame()
        {
            // the test compares unit vectors (scaled by their largest coordinate first): the 2^k scales and exact
            // translations give the same reduction bit for bit, the others no fold either (in the mesh mapped back)
            DMesh3 input = NoisyTerrain(2);
            DMesh3 reference = new DMesh3(input);
            new Reducer(reference).ReduceToTriangleCount(input.TriangleCount / 5);
            Assert.Equal(0, NotUp(reference));
            foreach (Similarity s in Similarity.All()) {
                DMesh3 mesh = Invariance.Transformed(input, s);
                new Reducer(mesh).ReduceToTriangleCount(input.TriangleCount / 5);
                DMesh3 back = Invariance.MappedBack(mesh, s);
                AssertValid(back);
                Assert.True(NotUp(back) == 0, $"{s.Name}: {NotUp(back)} triangles not up");
                if (s.IsExact)
                    Assert.Equal("", Invariance.Difference(reference, back));
            }
        }

        [Fact]
        public void RepeatedReductions_NoFold_AndRepeatedRunsAgree()
        {
            // reduced in steps with one instance (each step takes the references from its start): no fold either, and
            // two runs give the same mesh
            DMesh3 first = null;
            for (int run = 0; run < 2; ++run) {
                DMesh3 m = NoisyTerrain(2);
                var reducer = new Reducer(m);
                foreach (int target in new[] { 2400, 1200, 640 }) {
                    reducer.ReduceToTriangleCount(target);
                    Assert.Equal(0, NotUp(m));
                }
                AssertValid(m);
                if (first == null) first = m;
                else Assert.Equal("", Invariance.Difference(first, m));
            }
        }

        [Fact]
        public void MeshChangedBetweenReductions_ReferenceTakenAgain()
        {
            // a reducer used on a mesh that was changed in between (here: flipped upside down) uses the references of
            // the changed mesh: the old ones would point the wrong way and block every collapse
            DMesh3 m = NoisyTerrain(1);
            var reducer = new Reducer(m);
            reducer.ReduceToTriangleCount(2400);
            m.ReverseOrientation();
            reducer.ReduceToTriangleCount(640);
            AssertValid(m);
            Assert.True(m.TriangleCount <= 642, $"{m.TriangleCount} triangles");
            Assert.Equal(0, m.TriangleIndices().Count(t => !(m.GetTriNormal(t).z < 0)));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Hard cases for simplification (Reducer) from the issue trackers of other libraries (docs/QA.md 2.11): only the
    /// failure mode, rebuilt here from simple primitives. No code, test code or meshes of these projects are used (CGAL
    /// is GPL: only the prose of its issues was read). The issue URL is in the comment of each test.
    ///
    /// Every case checks the result itself (valid DMesh3, finite, closed where the input is, no folds, bounds, volume,
    /// topology). A case we fail is listed in KnownFailures with its finding (strict: a listed case that passes fails,
    /// so a fix removes the entry; while listed, the test also checks which failure it is).
    /// </summary>
    public class ReducerIssueCasesTests
    {
        /// <summary>
        /// case name -> (finding, the exact failure while listed: the problems joined by "; ", in the order the test
        /// reports them)
        /// </summary>
        public static readonly Dictionary<string, (string Finding, string Pinned)> KnownFailures = new Dictionary<string, (string, string)> {
        };

        static void Expect(string name, List<string> problems)
        {
            string failure = string.Join("; ", problems);
            if (KnownFailures.TryGetValue(name, out var known)) {
                if (!IssueCases.Strict) return;
                Assert.True(failure != "", $"{name} passes now: remove its entry ({known.Finding}) from KnownFailures and docs/QA.md 2.11");
                Assert.True(failure == known.Pinned, $"{name} fails differently than pinned ('{known.Pinned}'): {failure}");
            } else
                Assert.True(failure == "", name + ": " + failure);
        }

        [Fact]
        public void KnownFailures_NameExistingCases()
        {
            var names = new HashSet<string>(typeof(ReducerIssueCasesTests).GetMethods().Select(m => m.Name));
            foreach (var kv in KnownFailures) {
                Assert.True(names.Any(n => kv.Key == n || kv.Key.StartsWith(n + "_")), kv.Key + ": no such case");
                Assert.False(string.IsNullOrWhiteSpace(kv.Value.Finding));
                Assert.False(string.IsNullOrWhiteSpace(kv.Value.Pinned));
            }
        }

        /// <summary>
        /// x rounded to a multiple of 2^-30: inputs built with Math.Sin / Cos (whose last bit may differ between net48 and
        /// net10) are then the same on both, so a pinned failure is the same too
        /// </summary>
        internal static double R(double x) => Math.Round(x * (1 << 30)) / (1 << 30);

        // ---- inputs (procedural) ----

        /// <summary> an open height field over [0,nx] x [0,ny] (unit cells, two triangles each, normals +z) </summary>
        internal static DMesh3 Grid(int nx, int ny, Func<int, int, double> z, Vector3d offset = default)
        {
            var m = new DMesh3();
            int[,] vid = new int[nx + 1, ny + 1];
            for (int j = 0; j <= ny; ++j)
                for (int i = 0; i <= nx; ++i)
                    vid[i, j] = m.AppendVertex(offset + new Vector3d(i, j, z(i, j)));
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < nx; ++i) {
                    m.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    m.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            return m;
        }

        /// <summary> a closed torus around the z axis: major radius R, minor r, nu x nv segments, outward </summary>
        internal static DMesh3 Torus(double R, double r, int nu, int nv)
        {
            var m = new DMesh3();
            int[,] vid = new int[nu, nv];
            for (int i = 0; i < nu; ++i)
                for (int j = 0; j < nv; ++j) {
                    double u = 2 * Math.PI * i / nu, v = 2 * Math.PI * j / nv;
                    vid[i, j] = m.AppendVertex(new Vector3d((R + r * Math.Cos(v)) * Math.Cos(u), (R + r * Math.Cos(v)) * Math.Sin(u), r * Math.Sin(v)));
                }
            for (int i = 0; i < nu; ++i)
                for (int j = 0; j < nv; ++j) {
                    int i1 = (i + 1) % nu, j1 = (j + 1) % nv;
                    m.AppendTriangle(vid[i, j], vid[i1, j], vid[i1, j1]);
                    m.AppendTriangle(vid[i, j], vid[i1, j1], vid[i, j1]);
                }
            Assert.True(ResultChecks.Volume(m) > 0);
            return m;
        }

        /// <summary> an axis-aligned box, 12 triangles, outward </summary>
        internal static DMesh3 Box(Vector3d lo, Vector3d hi)
        {
            var m = new DMesh3();
            for (int i = 0; i < 8; ++i)
                m.AppendVertex(new Vector3d((i & 1) == 0 ? lo.x : hi.x, (i & 2) == 0 ? lo.y : hi.y, (i & 4) == 0 ? lo.z : hi.z));
            int[][] quads = { new[] { 0, 2, 3, 1 }, new[] { 4, 5, 7, 6 }, new[] { 0, 1, 5, 4 }, new[] { 2, 6, 7, 3 }, new[] { 0, 4, 6, 2 }, new[] { 1, 3, 7, 5 } };
            foreach (int[] q in quads) {
                m.AppendTriangle(q[0], q[1], q[2]);
                m.AppendTriangle(q[0], q[2], q[3]);
            }
            Assert.True(ResultChecks.Volume(m) > 0);
            return m;
        }

        internal static DMesh3 Sphere(Vector3d c, double r, int n)
        {
            DMesh3 m = new Sphere3Generator_NormalizedCube() { Radius = r, EdgeVertices = n }.Generate().MakeDMesh();
            MeshTransforms.Translate(m, c);
            return m;
        }

        static DMesh3 GridBox(Vector3d lo, Vector3d hi, int edgeVertices)
        {
            DMesh3 m = new GridBox3Generator() { Box = new Box3d(0.5 * (lo + hi), 0.5 * (hi - lo)), EdgeVertices = edgeVertices, NoSharedVertices = false }.Generate().MakeDMesh();
            Assert.True(m.IsClosed() && ResultChecks.Volume(m) > 0);
            return m;
        }

        static DMesh3 Cylinder(Vector3d c, double r, double h, int slices)
        {
            DMesh3 m = new CappedCylinderGenerator() { BaseRadius = (float)r, TopRadius = (float)r, Height = (float)h, Slices = slices, NoSharedVertices = false }.Generate().MakeDMesh();
            MeshTransforms.Translate(m, c);
            return m;
        }

        static DMesh3 Append(params DMesh3[] meshes)
        {
            var m = new DMesh3();
            foreach (DMesh3 x in meshes) new MeshEditor(m).AppendMesh(x);
            return m;
        }

        // ---- checks ----

        static DMesh3 Reduced(DMesh3 input, Action<Reducer> reduce)
        {
            DMesh3 m = new DMesh3(input);
            reduce(new Reducer(m));
            return m;
        }

        /// <summary> valid (bowties allowed if allowBowties), finite, closed if the input was </summary>
        static void CheckBasic(DMesh3 result, DMesh3 input, List<string> r, bool allowBowties = false)
        {
            if (!result.CheckValidity(allowBowties, FailMode.ReturnOnly)) r.Add("invalid DMesh3");
            if (!result.Vertices().All(v => v.IsFinite)) r.Add("non-finite coordinates");
            if (result.TriangleCount == 0) r.Add("empty result");
            if (input.IsClosed() && !result.IsClosed()) r.Add("not closed");
            int dup = DuplicateTriangles(result);
            if (dup > 0) r.Add($"{dup} duplicate triangles");
        }

        /// <summary> pairs of triangles on the same three vertices (either winding) </summary>
        static int DuplicateTriangles(DMesh3 m)
        {
            var seen = new HashSet<(int, int, int)>();
            int n = 0;
            foreach (int t in m.TriangleIndices()) {
                Index3i tv = m.GetTriangle(t);
                int[] s = { tv.a, tv.b, tv.c };
                Array.Sort(s);
                if (!seen.Add((s[0], s[1], s[2]))) n++;
            }
            return n;
        }

        /// <summary> triangles of a height field whose normal does not point up (folded over, or flat on edge) </summary>
        static int DownwardTriangles(DMesh3 m) => m.TriangleIndices().Count(t => !(m.GetTriNormal(t).z > 0));

        static void CheckInBounds(DMesh3 result, AxisAlignedBox3d b, double grow, List<string> r)
        {
            double g = grow * b.DiagonalLength;
            foreach (Vector3d v in result.Vertices())
                if (!(v.x >= b.Min.x - g && v.y >= b.Min.y - g && v.z >= b.Min.z - g && v.x <= b.Max.x + g && v.y <= b.Max.y + g && v.z <= b.Max.z + g)) {
                    r.Add($"vertex {v} outside the input bounds {b}");
                    return;
                }
        }

        static int EulerCharacteristic(DMesh3 m) => m.VertexCount - m.EdgeCount + m.TriangleCount;

        static int Components(DMesh3 m)
        {
            var c = new MeshConnectedComponents(m);
            c.FindConnectedT();
            return c.Count;
        }

        // ---------------------------------------------------------------------------------------------------------------
        // folds and flips

        [Theory]
        [InlineData(1)]
        [InlineData(2)]
        [InlineData(3)]
        public void NoisyTerrain_ReducedTo20Percent_NoFoldOver(int seed)
        {
            // https://github.com/zeux/meshoptimizer/issues/346: a noisy grid terrain reduced to 20%: a chain of
            // collapses flipped triangles although each one passed a 90 degree normal test (each compares with the
            // current neighbours only, so the normal can turn by up to 90 degrees per step). Rebuilt: a 40 x 40 unit
            // grid with a smooth hill and noise of +-0.4. Correct: the reduced height field has no triangle whose normal
            // points down or lies flat (a fold-over relative to the original, whose normals all point up); vertices
            // within the bounds grown by 1% of the diagonal.
            var rnd = new Random(seed);
            DMesh3 input = Grid(40, 40, (i, j) => R(3 * Math.Sin(0.2 * i) * Math.Cos(0.15 * j) + 0.8 * (rnd.NextDouble() - 0.5)));
            Assert.Equal(0, DownwardTriangles(input));
            DMesh3 result = Reduced(input, rd => rd.ReduceToTriangleCount(input.TriangleCount / 5));
            var r = new List<string>();
            CheckBasic(result, input, r);
            if (result.TriangleCount > input.TriangleCount / 5 + 2) r.Add($"{result.TriangleCount} triangles, target {input.TriangleCount / 5}");
            int down = DownwardTriangles(result);
            if (down > 0) r.Add($"{down} folded triangles");
            CheckInBounds(result, input.CachedBounds, 0.01, r);
            Expect(nameof(NoisyTerrain_ReducedTo20Percent_NoFoldOver) + "_" + seed, r);
        }

        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        [InlineData(2)]
        public void SmallPatch_ReducedTo10_NoDuplicateTriangles(int seed)
        {
            // https://github.com/zeux/meshoptimizer/issues/699: a 24-triangle patch reduced to 10 triangles gave two
            // copies of a triangle with opposite winding (a non-manifold edge). Rebuilt: a 4 x 3 grid (24 triangles),
            // flat (seed 0) or with random heights. Correct: valid, no two triangles on the same three vertices, every
            // normal still up, the four corners kept, the area of a flat patch exact.
            var rnd = new Random(seed);
            DMesh3 input = Grid(4, 3, (i, j) => seed == 0 ? 0 : 0.3 * rnd.NextDouble());
            Assert.Equal(24, input.TriangleCount);
            DMesh3 result = Reduced(input, rd => rd.ReduceToTriangleCount(10));
            var r = new List<string>();
            CheckBasic(result, input, r);
            if (result.TriangleCount > 10) r.Add($"{result.TriangleCount} triangles, target 10");
            int down = DownwardTriangles(result);
            if (down > 0) r.Add($"{down} folded triangles");
            if (Components(result) != 1) r.Add($"{Components(result)} components");
            foreach (int corner in new[] { 0, 4, 15, 19 })
                if (!result.IsVertex(corner) || result.GetVertex(corner) != input.GetVertex(corner)) r.Add($"corner {corner} lost");
            if (seed == 0 && Math.Abs(Invariance.Area(result) - 12) > 1e-12) r.Add($"area {Invariance.Area(result)}, expected 12");
            Expect(nameof(SmallPatch_ReducedTo10_NoDuplicateTriangles) + "_" + seed, r);
        }

        [Theory]
        [InlineData(1e-6)]
        [InlineData(1e-12)]
        [InlineData(0)]
        public void AlmostFlatGrid_SingularQuadric_NoFlipNoEscape(double zRange)
        {
            // (beyond ReducerRobustnessTests.NoisyFlatSurface_NoSpikes, an 81 x 81 grid checked for spikes: tiny grids
            // reduced as far as possible, z ranges down to exactly 0, and the fold check)
            // https://github.com/libigl/libigl/issues/738: an almost flat 12-triangle grid (z in a tiny range): the
            // quadric is nearly singular in the plane, the optimal point slid past the ends of the edge and a triangle
            // flipped. Rebuilt: a 3 x 2 grid (12 triangles) and a 6 x 6 grid with random z in [0, zRange], reduced as far
