        public void TwoConesJoinedAtTheTip_UnderSimilarity(string similarity)
        {
            // the bowtie guard of TwoConesJoinedAtTheTip_NotMerged under Similarity.All(): the shared apex stays where it
            // is (it is the transformed origin), the cones stay separate; bit for bit the same as untransformed under 2^k
            // scales, and about the same triangle count otherwise
            Similarity s = Similarity.ByName(similarity);
            DMesh3 source = DoubleCone(32, 4);
            DMesh3 reference = Reduced(source, rd => rd.ReduceToTriangleCount(60));
            DMesh3 mesh = Reduced(Invariance.Transformed(source, s), rd => rd.ReduceToTriangleCount(60));
            Assert.True(mesh.CheckValidity(true, FailMode.ReturnOnly));
            Assert.True(mesh.IsClosed() && Invariance.AllFinite(mesh));
            Assert.True(mesh.IsVertex(0) && mesh.IsBowtieVertex(0));
            Assert.Equal(s.Apply(Vector3d.Zero), mesh.GetVertex(0));
            DMesh3 back = Invariance.MappedBack(mesh, s);
            foreach (int e in back.EdgeIndices()) {
                Index2i ev = back.GetEdgeV(e);
                Assert.False(back.GetVertex(ev.a).z * back.GetVertex(ev.b).z < -1e-6, "an edge joins the two cones");
            }
            if (s.IsExact)
                Assert.Equal("", Invariance.Difference(reference, back));
            else
                Assert.InRange(mesh.TriangleCount, reference.TriangleCount - 8, reference.TriangleCount + 8);
        }
    }
}

using System;
using System.Collections.Generic;
using g3;
using Xunit;
using Xunit.Abstractions;

namespace geometry3Sharp.Tests
{
    public class ReducerQuadricBudgetTests
    {
        readonly ITestOutputHelper output;
        public ReducerQuadricBudgetTests(ITestOutputHelper output) { this.output = output; }

        sealed class RecordingReducer : Reducer
        {
            public double MinimumInitialError = double.PositiveInfinity;
            public double MinimumEndpointError = double.PositiveInfinity;
            public int RestrictToVertex = -1;
            public readonly List<double> AcceptedErrors = new List<double>();
            public RecordingReducer(DMesh3 mesh) : base(mesh) { }

            protected override void InitializeQueue()
            {
                base.InitializeQueue();
                MinimumInitialError = MinimumEndpointError = double.PositiveInfinity;
                foreach (int eid in Mesh.EdgeIndices()) {
                    QEdge edge = EdgeQuadrics[eid];
                    MinimumInitialError = Math.Min(MinimumInitialError, evaluate(ref edge.q, edge.collapse_pt));
                    Index2i ev = Mesh.GetEdgeV(eid);
                    MinimumEndpointError = Math.Min(MinimumEndpointError,
                        Math.Min(evaluate(ref edge.q, Mesh.GetVertex(ev.a)), evaluate(ref edge.q, Mesh.GetVertex(ev.b))));
                }
                if (RestrictToVertex >= 0) {
                    EdgeQueue.Clear(false);
                    foreach (int eid in Mesh.VtxEdgesItr(RestrictToVertex)) {
                        QEdge edge = EdgeQuadrics[eid];
                        EdgeQueue.Insert(eid, (float)evaluate(ref edge.q, edge.collapse_pt));
                    }
                }
            }

            protected override void OnEdgeCollapse(int edgeID, int va, int vb, DMesh3.EdgeCollapseInfo collapseInfo)
            {
                QEdge edge = EdgeQuadrics[edgeID];
                AcceptedErrors.Add(evaluate(ref edge.q, Mesh.GetVertex(va)));
                base.OnEdgeCollapse(edgeID, va, vb, collapseInfo);
            }
        }

        // Constant quadrics isolate queue rounding from geometric cost evaluation; collapses still use the real mesh.
        sealed class ConstantCostReducer : Reducer
        {
            readonly double firstCost, otherCost;
            public readonly List<double> AcceptedErrors = new List<double>();
            public ConstantCostReducer(DMesh3 mesh, double firstCost, double otherCost) : base(mesh)
            {
                this.firstCost = firstCost; this.otherCost = otherCost;
            }
            protected override void InitializeQueue()
            {
                EdgeQuadrics = new QEdge[Mesh.MaxEdgeID];
                EdgeQueue = new IndexPriorityQueue(Mesh.MaxEdgeID);
                // Equal priorities move up in this heap; insert the expensive half last so it is examined first.
                for (int eid = Mesh.MaxEdgeID - 1; eid >= 0; --eid) {
                    if (!Mesh.IsEdge(eid)) continue;
                    var q = new QuadricError { c = eid < Mesh.MaxEdgeID / 2 ? firstCost : otherCost };
                    Index2i ev = Mesh.GetEdgeV(eid);
                    Vector3d midpoint = (Mesh.GetVertex(ev.a) + Mesh.GetVertex(ev.b)) * 0.5;
                    EdgeQuadrics[eid] = new QEdge(eid, ref q, ref midpoint);
                    EdgeQueue.Insert(eid, (float)q.c);
                }
                Assert.Equal(firstCost, EdgeQuadrics[EdgeQueue.First].q.c);
            }
            protected override void UpdateNeighbours(int vid) { }
            protected override void OnEdgeCollapse(int edgeID, int va, int vb, DMesh3.EdgeCollapseInfo info)
            {
                AcceptedErrors.Add(evaluate(ref EdgeQuadrics[edgeID].q, Mesh.GetVertex(va)));
            }
        }

        static DMesh3 Sphere() => new Sphere3Generator_NormalizedCube { Radius = 1, EdgeVertices = 4 }.Generate().MakeDMesh();

        static void AssertClean(DMesh3 mesh)
        {
            Assert.True(mesh.CheckValidity(false, FailMode.ReturnOnly));
            Assert.True(mesh.IsClosed());
            Assert.True(Invariance.AllFinite(mesh));
            Assert.All(mesh.TriangleIndices(), tid => Assert.True(mesh.GetTriArea(tid) > 0));
        }

        [Fact]
        public void RoundedUpPriority_StillAcceptsErrorEqualToDoubleBudget()
        {
            double cost = 1 + 3 * Math.Pow(2, -25);
            Assert.True((float)cost > cost);
            DMesh3 mesh = Sphere();
            var reducer = new ConstantCostReducer(mesh, cost, cost);
            reducer.ReduceToMaxQuadricError(cost);
            Assert.NotEmpty(reducer.AcceptedErrors);
            Assert.All(reducer.AcceptedErrors, error => Assert.Equal(cost, error));
            AssertClean(mesh);
        }

        [Fact]
        public void RoundedTie_OverBudgetCandidateDoesNotHideAffordableCandidates()
        {
            double high = 1 + Math.Pow(2, -25);
            Assert.Equal(1f, (float)high);
            DMesh3 mesh = Sphere();
            var reducer = new ConstantCostReducer(mesh, high, 1);
            reducer.ReduceToMaxQuadricError(1);
            Assert.NotEmpty(reducer.AcceptedErrors);
            Assert.All(reducer.AcceptedErrors, error => Assert.Equal(1, error));
            AssertClean(mesh);
        }

        [Fact]
        public void FixedVertices_CheckActualEndpointRatherThanQueuedOptimum()
        {
            DMesh3 mesh = Sphere();
            var reducer = new RecordingReducer(mesh) { AreaWeightedQuadrics = false };
            reducer.ReduceToTriangleCount(mesh.TriangleCount);
            Assert.True(reducer.MinimumEndpointError > reducer.MinimumInitialError);
            double budget = (reducer.MinimumInitialError + reducer.MinimumEndpointError) * 0.5;
            var constraints = new MeshConstraints();
            constraints.SetOrUpdateVertexConstraint(0, new VertexConstraint(true, 0));
            reducer.SetExternalConstraints(constraints);
            reducer.RestrictToVertex = 0;
            DMesh3 before = new DMesh3(mesh);
            reducer.ReduceToMaxQuadricError(budget);
            Assert.Empty(reducer.AcceptedErrors);
            Assert.Equal("", Invariance.Difference(before, mesh));
            AssertClean(mesh);
        }

        [Fact]
        public void BudgetRejection_IsInvariantUnderSimilarities()
        {
            DMesh3 source = Sphere();
            var inspect = new RecordingReducer(new DMesh3(source)) { AreaWeightedQuadrics = false };
            inspect.ReduceToTriangleCount(source.TriangleCount);
            // between the cheapest queued optimum and the cheapest endpoint: passes the queue, fails the check of the kept position
            double fixedBudget = (inspect.MinimumInitialError + inspect.MinimumEndpointError) * 0.5;
            DMesh3 reduced = new DMesh3(source);
            new Reducer(reduced) { AreaWeightedQuadrics = false }.ReduceToMaxQuadricError(0.05);
            Assert.True(reduced.TriangleCount < source.TriangleCount);
            foreach (Similarity s in Similarity.All()) {
                DMesh3 mesh = Invariance.Transformed(source, s);
                var reducer = new RecordingReducer(mesh) { AreaWeightedQuadrics = false };
                reducer.ReduceToMaxQuadricError(0.05 * s.Scale * s.Scale);
                Assert.NotEmpty(reducer.AcceptedErrors);
                if (s.IsExact)
                    Assert.Equal("", Invariance.Difference(reduced, Invariance.MappedBack(mesh, s)));
                AssertClean(mesh);

                mesh = Invariance.Transformed(source, s);
                DMesh3 before = new DMesh3(mesh);
                var constraints = new MeshConstraints();
                constraints.SetOrUpdateVertexConstraint(0, new VertexConstraint(true, 0));
                reducer = new RecordingReducer(mesh) { AreaWeightedQuadrics = false, RestrictToVertex = 0 };
                reducer.SetExternalConstraints(constraints);
                reducer.ReduceToMaxQuadricError(fixedBudget * s.Scale * s.Scale);
                Assert.Empty(reducer.AcceptedErrors);
                Assert.Equal("", Invariance.Difference(before, mesh));
            }
        }

        [Theory]
        [InlineData(false)]
        [InlineData(true)]
        public void BudgetMode_DoesNotLeakIntoOtherReductionModes(bool fast)
        {
            DMesh3 mesh = Sphere(), fresh = new DMesh3(mesh);
            var reused = new Reducer(mesh);
            // (NaN: every collapse reaches the budget check and is rejected; 0 would stop before it)
            reused.ReduceToMaxQuadricError(double.NaN);
            Assert.Equal("", Invariance.Difference(fresh, mesh));
            if (fast) {
                reused.FastCollapsePass(1);
                new Reducer(fresh).FastCollapsePass(1);
            } else {
                reused.ReduceToTriangleCount(50);
                new Reducer(fresh).ReduceToTriangleCount(50);
            }
            Assert.True(mesh.TriangleCount < Sphere().TriangleCount);
            Assert.Equal("", Invariance.Difference(fresh, mesh));
            AssertClean(mesh);
        }

        [Fact]
        public void RepeatedBudgetCalls_MatchFreshInstance_AndRepeatedRuns()
        {
            DMesh3 firstRun = null;
            for (int run = 0; run < 3; ++run) {
                DMesh3 mesh = Sphere();
                var reducer = new RecordingReducer(mesh) { AreaWeightedQuadrics = false };
                reducer.ReduceToMaxQuadricError(0.05);
                Assert.NotEmpty(reducer.AcceptedErrors);
                Assert.All(reducer.AcceptedErrors, error => Assert.True(error <= 0.05));
                DMesh3 fresh = new DMesh3(mesh);
                reducer.AcceptedErrors.Clear();
                reducer.ReduceToMaxQuadricError(0.1);
                new Reducer(fresh) { AreaWeightedQuadrics = false }.ReduceToMaxQuadricError(0.1);
                Assert.All(reducer.AcceptedErrors, error => Assert.True(error <= 0.1));
                Assert.Equal("", Invariance.Difference(fresh, mesh));
                if (firstRun != null) Assert.Equal("", Invariance.Difference(firstRun, mesh));
                firstRun = new DMesh3(mesh);
                AssertClean(mesh);
            }
        }

        sealed class ThrowOnceReducer : Reducer
        {
            bool throwOnce = true;
            public ThrowOnceReducer(DMesh3 mesh) : base(mesh) { }
            protected override ProcessResult CollapseEdge(int eid, Vector3d point, out int kept)
            {
                if (throwOnce) {
                    throwOnce = false;
                    throw new InvalidOperationException("test interruption");
                }
                return base.CollapseEdge(eid, point, out kept);
            }
        }

        [Fact]
        public void InterruptedBudgetCall_DoesNotLeakBudgetIntoFastCollapsePass()
        {
            DMesh3 mesh = Sphere(), fresh = new DMesh3(mesh);
            var reducer = new ThrowOnceReducer(mesh);
            Assert.Throws<InvalidOperationException>(() => reducer.ReduceToMaxQuadricError(double.NaN));
            reducer.FastCollapsePass(1);
            new Reducer(fresh).FastCollapsePass(1);
            Assert.True(mesh.TriangleCount < Sphere().TriangleCount);
            Assert.Equal("", Invariance.Difference(fresh, mesh));
            AssertClean(mesh);
        }

        [Fact]
        public void NaNBudget_DoesNotAcceptAnyCollapse()
        {
            DMesh3 mesh = Sphere(), before = new DMesh3(mesh);
            new Reducer(mesh).ReduceToMaxQuadricError(double.NaN);
            Assert.Equal("", Invariance.Difference(before, mesh));
            AssertClean(mesh);
        }

        [Fact]
        public void MaxQuadricError_DoubleBudgetBelowFirstError_DoesNotAcceptRoundedDownPriority()
        {
            DMesh3 witness = null;
            double minimum = 0, budget = 0;
            // Select a fixed procedural witness by the rounding condition, not by whether reduction fails.
            foreach (double radius in new[] { 1.0, 1.1, 1.3, 1.7, 2.1, 2.9, 3.7, 4.3 }) {
                var mesh = new Sphere3Generator_NormalizedCube { Radius = radius, EdgeVertices = 4 }.Generate().MakeDMesh();
                var inspect = new RecordingReducer(mesh) { AreaWeightedQuadrics = false };
                inspect.ReduceToTriangleCount(mesh.TriangleCount);
                minimum = inspect.MinimumInitialError;
                double queued = (float)minimum;
                if (queued > 0 && queued < minimum) {
                    witness = mesh;
                    budget = queued + 0.5 * (minimum - queued);
                    output.WriteLine("radius={0:R}; exactMinimum={1:R}; queuedMinimum={2:R}; budget={3:R}", radius, minimum, queued, budget);
                    break;
                }
            }
            Assert.NotNull(witness);
            int trianglesBefore = witness.TriangleCount;
            var reducer = new RecordingReducer(witness) { AreaWeightedQuadrics = false };
            reducer.ReduceToMaxQuadricError(budget);
            foreach (double error in reducer.AcceptedErrors) output.WriteLine("acceptedError={0:R}; budget={1:R}", error, budget);
            Assert.True(witness.CheckValidity(false, FailMode.ReturnOnly));
            Assert.True(witness.IsClosed());
            Assert.All(reducer.AcceptedErrors, error => Assert.True(error <= budget,
                string.Format(System.Globalization.CultureInfo.InvariantCulture, "Actual accepted error {0:R} exceeds budget {1:R}", error, budget)));
            Assert.Equal(trianglesBefore, witness.TriangleCount);
        }
    }
}

using System;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Reducing must not create degenerate triangles or folds. Solidify output (dual contouring of
    /// shapes with sharp creases at arbitrary angles) followed by reduction triggered both.
    /// </summary>
    public class ReducerQualityTests
    {
        [Fact]
        public void TriangleQuality_DoesNotDependOnTheScale()
        {
            // the quality has no units: a small triangle (eg of a mesh in metres with millimetre detail, or
            // a solidify of a small part) is not degenerate (it used to be 0 below edge lengths of about 1e-4)
            Vector3d a = new Vector3d(0, 0, 0), b = new Vector3d(1, 0.1, 0), c = new Vector3d(0.3, 0.8, 0.2);
            double q = MeshRefinerBase.TriangleQuality(ref a, ref b, ref c);
            Assert.True(q > 0.5);
            foreach (double scale in new[] { Math.Pow(2, -20), Math.Pow(2, -10), Math.Pow(2, 10) }) {
                Vector3d sa = scale * a, sb = scale * b, sc = scale * c;
                Assert.Equal(q, MeshRefinerBase.TriangleQuality(ref sa, ref sb, ref sc));     // exact: 2^k scaling
            }
            Assert.Equal(0, MeshRefinerBase.TriangleQuality(ref a, ref a, ref a));
        }

        class FlipMetricProbe : MeshRefinerBase
        {
            public FlipMetricProbe() : base(new DMesh3()) { EdgeFlipTolerance = 0.5; }
            public double Metric(Vector3d n0, Vector3d n1) => edge_flip_metric(ref n0, ref n1);
        }

        [Fact]
        public void EdgeFlipMetric_DoesNotDependOnTheScale()
        {
            // the normals are unnormalized cross products (squared lengths): a tiny triangle's normal is not
            // zero (Normalized used to treat lengths below 2.2e-16 as zero, so every collapse there was a 'flip')
            var p = new FlipMetricProbe();
            Vector3d n0 = new Vector3d(0.2, 0.1, 1), n1 = new Vector3d(-0.1, 0.3, 0.9);
            double m = p.Metric(n0, n1);
            Assert.True(m > 0.9);
            foreach (double area in new[] { Math.Pow(2, -60), Math.Pow(2, -20), Math.Pow(2, 40) })
                Assert.Equal(m, p.Metric(area * n0, area * n1), 15);
            Assert.Equal(0, p.Metric(Vector3d.Zero, n1));
        }

        static DMesh3 Box(double size, Vector3d center)
        {
            return new TrivialBox3Generator() { Box = new Box3d(center, size * 0.5 * Vector3d.One) }.Generate().MakeDMesh();
        }
        static DMesh3 Sphere(double r, Vector3d c)
        {
            DMesh3 m = new Sphere3Generator_NormalizedCube() { EdgeVertices = 24, Radius = r }.Generate().MakeDMesh();
            MeshTransforms.Translate(m, c);
            return m;
        }
        static DMesh3 Cylinder(double r, double h)
        {
            DMesh3 m = new CappedCylinderGenerator() { BaseRadius = (float)r, TopRadius = (float)r, Height = (float)h, Slices = 40 }.Generate().MakeDMesh();
            return m;
        }
        static DMesh3 Rotated(DMesh3 m)
        {
            MeshTransforms.Rotate(m, Vector3d.Zero, Quaterniond.AxisAngleD(new Vector3d(1, 2, 3).Normalized, 33));
            return m;
        }
        static DMesh3 Union(DMesh3 a, DMesh3 b)
        {
            MeshEditor.Append(a, b);
            return a;
        }

        static DMesh3 Shape(string name)
        {
            switch (name) {
                case "rotated box": return Rotated(Box(10, Vector3d.Zero));
                case "box + sphere": return Union(Box(10, Vector3d.Zero), Sphere(4, new Vector3d(5, 3, 2)));
                case "cylinder + box": return Union(Cylinder(3, 10), Rotated(Box(6, new Vector3d(0, 5, 0))));
                default: return Union(Rotated(Box(8, Vector3d.Zero)), Box(8, new Vector3d(3, 3, 3)));
            }
        }

        [Theory]
        [InlineData("rotated box")]
        [InlineData("box + sphere")]
        [InlineData("cylinder + box")]
        [InlineData("two boxes")]
        public void SolidifyAndReduce_NoDegenerateTrianglesOrFolds(string shape)
        {
            DMesh3 input = Shape(shape);
            var solid = new MeshWindingNumberSolidify(input) { GridResolution = 96, Adaptive = true };
            Assert.True(solid.Compute());
            DMesh3 mesh = solid.Result;

            double diag2 = mesh.CachedBounds.DiagonalLength * mesh.CachedBounds.DiagonalLength;
            double foldCos = Math.Cos(175 * MathUtil.Deg2Rad);
            int degenerate = mesh.TriangleIndices().Count(t => mesh.GetTriArea(t) < 1e-12 * diag2);
            int folds = mesh.EdgeIndices().Count(e => {
                Index2i et = mesh.GetEdgeT(e);
                return et.b >= 0 && mesh.GetTriNormal(et.a).Dot(mesh.GetTriNormal(et.b)) < foldCos;
            });
            Assert.Equal(0, degenerate);
            Assert.Equal(0, folds);
            Assert.True(mesh.IsClosed());
            // and the reduction still does its job
            Assert.True(mesh.TriangleCount < 6000, $"{mesh.TriangleCount} triangles");
        }
    }
}

using System;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The Reducer must not depend on where the mesh is (UTM coordinates) or on its units, and must stay
    /// stable on noisy, nearly flat data. Deviation is measured with the certified Hausdorff distance.
    /// </summary>
    public class ReducerRobustnessTests
    {
        static DMesh3 Terrain(int n = 101, double noise = 0, int seed = 1)
        {
            var rnd = new Random(seed);
            DMesh3 mesh = new DMesh3();
            int[,] vid = new int[n, n];
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    double x = -50 + 100.0 * i / (n - 1), y = -50 + 100.0 * j / (n - 1);
                    double z = 3 * Math.Sin(0.1 * x) * Math.Cos(0.13 * y) + noise * (2 * rnd.NextDouble() - 1);
                    vid[i, j] = mesh.AppendVertex(new Vector3d(x, y, z));
                }
            for (int j = 0; j + 1 < n; ++j)
                for (int i = 0; i + 1 < n; ++i) {
                    mesh.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    mesh.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            return mesh;
        }

        static DMesh3 Reduce(DMesh3 mesh, int triangles)
        {
            DMesh3 r = new DMesh3(mesh);
            new Reducer(r).ReduceToTriangleCount(triangles);
            return r;
        }

        static double RelativeHausdorff(DMesh3 a, DMesh3 b)
        {
            var h = new MeshHausdorffDistance(a, b) { RelativeTolerance = 1e-5 };
            Assert.True(h.Compute());
            return h.UpperBound / a.CachedBounds.DiagonalLength;
        }

        [Fact]
        public void UtmCoordinates_SameQualityAsAtOrigin()
        {
            DMesh3 local = Terrain();
            DMesh3 utm = new DMesh3(local);
            MeshTransforms.Translate(utm, new Vector3d(632000, 5712000, 100));
            double hLocal = RelativeHausdorff(local, Reduce(local, 2000));
            double hUtm = RelativeHausdorff(utm, Reduce(utm, 2000));
            Assert.True(Math.Abs(hUtm - hLocal) <= 0.05 * hLocal, $"deviation {hUtm:E3} at UTM vs {hLocal:E3} at the origin");
        }

        [Theory]
        [InlineData(1e-3)]
        [InlineData(1e3)]
        public void Units_SameQuality(double scale)
        {
            DMesh3 mesh = Terrain();
            DMesh3 scaled = new DMesh3(mesh);
            MeshTransforms.Scale(scaled, scale);
            double h = RelativeHausdorff(mesh, Reduce(mesh, 2000));
            double hs = RelativeHausdorff(scaled, Reduce(scaled, 2000));
            Assert.True(Math.Abs(hs - h) <= 0.05 * h, $"deviation {hs:E3} at scale {scale} vs {h:E3}");
        }

        [Theory]
        [InlineData(0.05)]
        [InlineData(0.2)]
        public void MaxDeviation_ReducedSurfaceStaysWithinTolerance(double eps)
        {
            // without the limit, reducing to 300 triangles deviates by ~2 m
            DMesh3 mesh = Terrain(61);
            DMesh3 reduced = new DMesh3(mesh);
            var reducer = new Reducer(reduced) { MaxDeviation = eps };
            reducer.ReduceToTriangleCount(300);
            var h = new MeshHausdorffDistance(reduced, mesh) { Symmetric = false, Tolerance = 1e-4 };
            Assert.True(h.Compute());
            Assert.True(h.UpperBound <= eps + 1e-4, $"deviation {h.UpperBound} > {eps}");
            // and it still reduces as far as the tolerance allows
            Assert.True(reduced.TriangleCount < 0.5 * mesh.TriangleCount, $"{reduced.TriangleCount} triangles");
            DMesh3 free = Reduce(mesh, 300);
            var hf = new MeshHausdorffDistance(free, mesh) { Symmetric = false, Tolerance = 1e-4 };
            hf.Compute();
            Assert.True(hf.LowerBound > eps, "test does not exercise the limit");
        }

        [Fact]
        public void MaxDeviation_RepeatedReductions_StayWithinToleranceOfTheOriginal()
        {
            DMesh3 mesh = Terrain(61);
            DMesh3 reduced = new DMesh3(mesh);
            var reducer = new Reducer(reduced) { MaxDeviation = 0.1 };
            reducer.ReduceToTriangleCount(3000);
            reducer.ReduceToTriangleCount(1000);
            reducer.ReduceToTriangleCount(300);
            var h = new MeshHausdorffDistance(reduced, mesh) { Symmetric = false, Tolerance = 1e-4 };
            Assert.True(h.Compute());
            Assert.True(h.UpperBound <= 0.1 + 1e-4, $"deviation {h.UpperBound}");
        }

        [Fact]
        public void MaxDeviation_FastCollapsePass()
        {
            DMesh3 mesh = Terrain(61);
            DMesh3 reduced = new DMesh3(mesh);
            var reducer = new Reducer(reduced) { MaxDeviation = 0.05 };
            reducer.FastCollapsePass(4.0, 3);
            Assert.True(reduced.TriangleCount < mesh.TriangleCount);
            var h = new MeshHausdorffDistance(reduced, mesh) { Symmetric = false, Tolerance = 1e-4 };
            Assert.True(h.Compute());
            Assert.True(h.UpperBound <= 0.05 + 1e-4, $"deviation {h.UpperBound}");
        }

        [Fact]
        public void MaxDeviation_ExplicitReference()
        {
            DMesh3 mesh = Terrain(61);
            DMesh3 work = new DMesh3(mesh);
            new Reducer(work).ReduceToTriangleCount(4000);       // pre-reduced without a limit
            var reducer = new Reducer(work) { MaxDeviation = 0.3 };
            reducer.SetDeviationReference(mesh);
            reducer.ReduceToTriangleCount(200);
            var h = new MeshHausdorffDistance(work, mesh) { Symmetric = false, Tolerance = 1e-4 };
            Assert.True(h.Compute());
            Assert.True(h.UpperBound <= 0.3 + 1e-4, $"deviation {h.UpperBound}");
        }

        [Fact]
        public void NoisyFlatSurface_NoSpikes()
        {
            // nearly flat: plane quadrics are nearly singular in the plane directions
            DMesh3 mesh = Terrain(81, 0.001);
            foreach (int vid in mesh.VertexIndices().ToArray()) {
                Vector3d v = mesh.GetVertex(vid);
                mesh.SetVertex(vid, new Vector3d(v.x, v.y, 0.001 * v.z));
            }
            DMesh3 reduced = Reduce(mesh, 400);
            AxisAlignedBox3d b = mesh.CachedBounds;
            foreach (int vid in reduced.VertexIndices()) {
                Vector3d v = reduced.GetVertex(vid);
                Assert.True(b.Contains(v) || b.Distance(v) < 1e-3, $"vertex {v} left the bounds");
            }
            Assert.True(RelativeHausdorff(mesh, reduced) < 1e-4);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Reducer.ShareDeviationQueries: the tree queries of one collapse's MaxDeviation check are shared through a
    /// TriangleDeviationBounds.QueryCache. The answers must not change: reductions with and without sharing give the
    /// same mesh bit for bit, IsWithin with a cache equals IsWithin without one, and a cache of another distance is
    /// not used.
    /// </summary>
    public class ReducerSharedDeviationQueriesTests
    {
        static DMesh3 Bumpy(int n)
        {
            DMesh3 m = new Sphere3Generator_NormalizedCube() { Radius = 1, EdgeVertices = n }.Generate().MakeDMesh();
            foreach (int v in m.VertexIndices()) {
                Vector3d p = m.GetVertex(v);
                m.SetVertex(v, p * (1 + 0.1 * Math.Sin(5 * p.x + 1) * Math.Cos(4 * p.y - 0.5) + 0.05 * Math.Sin(9 * p.z)));
            }
            return m;
        }

        static DMesh3 Terrain(int n)
        {
            var m = new DMesh3();
            int[,] ids = new int[n + 1, n + 1];
            for (int j = 0; j <= n; ++j)
                for (int i = 0; i <= n; ++i) {
                    double x = (double)i / n, y = (double)j / n;
                    ids[i, j] = m.AppendVertex(new Vector3d(x, y, 0.08 * Math.Sin(6 * x) * Math.Cos(5 * y) + 0.01 * Math.Sin(40 * x + 13 * y)));
                }
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    m.AppendTriangle(ids[i, j], ids[i + 1, j], ids[i + 1, j + 1]);
                    m.AppendTriangle(ids[i, j], ids[i + 1, j + 1], ids[i, j + 1]);
                }
            return m;
        }

        static void AssertSame(DMesh3 a, DMesh3 b)
        {
            Assert.Equal(a.TriangleCount, b.TriangleCount);
            Assert.Equal(a.MaxVertexID, b.MaxVertexID);
            foreach (int v in a.VertexIndices()) {
                Assert.True(b.IsVertex(v));
                Assert.Equal(a.GetVertex(v), b.GetVertex(v));
            }
            foreach (int t in a.TriangleIndices()) Assert.Equal(a.GetTriangle(t), b.GetTriangle(t));
        }

        static DMesh3 Reduce(DMesh3 input, double tol, bool share, int target = 4) { return Reduce(input, tol, share, out Reducer _, target); }

        static DMesh3 Reduce(DMesh3 input, double tol, bool share, out Reducer reducer, int target = 4)
        {
            var m = new DMesh3(input);
            reducer = new Reducer(m) { MaxDeviation = tol, ShareDeviationQueries = share };
            reducer.ReduceToTriangleCount(target);
            return m;
        }

        /// <summary> the same reduction with and without sharing, at three tolerances, on two meshes, twice </summary>
        [Fact]
        public void Reduction_SameWithAndWithoutSharing()
        {
            foreach (DMesh3 input in new[] { Bumpy(20), Terrain(40) }) {
                double diag = input.CachedBounds.DiagonalLength;
                foreach (double rel in new[] { 1e-3, 3e-3, 1e-2 }) {
                    DMesh3 without = Reduce(input, rel * diag, false, out Reducer r0), with = Reduce(input, rel * diag, true, out Reducer r1);
                    // the cache is used: by the samples (lookups), and IsWithin finds shared points in it
                    Assert.Equal(0, r0.DeviationCacheLookups);
                    Assert.Equal(0, r0.DeviationCacheSampleLookups);
                    Assert.True(r1.DeviationCacheSampleLookups > 0 && r1.DeviationCacheIsWithinHits > 0, $"sample lookups {r1.DeviationCacheSampleLookups}, IsWithin hits {r1.DeviationCacheIsWithinHits}");
                    Assert.True(with.TriangleCount < 0.9 * input.TriangleCount && with.TriangleCount > 4, $"{with.TriangleCount} of {input.TriangleCount}: the check both allowed and stopped collapses");
                    AssertSame(without, with);
                    AssertSame(with, Reduce(input, rel * diag, true));     // repeated: deterministic
                    Assert.True(MeshDeviationCheck(with, input, rel * diag), "within the tolerance");
                }
            }
        }

        // the centroid of every triangle of the reduced mesh within tol of the input
        static bool MeshDeviationCheck(DMesh3 reduced, DMesh3 input, double tol)
        {
            var tree = new DMeshAABBTree3(input, true);
            foreach (int t in reduced.TriangleIndices()) {
                Vector3d c = reduced.GetTriCentroid(t);
                if (Math.Sqrt(MeshQueries.TriDistanceSqr(input, tree.FindNearestTriangle(c), c)) > tol * (1 + 1e-9)) return false;
            }
            return true;
        }

        /// <summary>
        /// IsWithin with a cache, shared by triangles with common corners and edges (a fan, as a collapse makes),
        /// equals IsWithin without one; a cache of another distance is ignored; NearestWithin equals the tree query
        /// </summary>
        [Fact]
        public void IsWithin_CacheGivesTheSameAnswers()
        {
            DMesh3 target = Bumpy(16);
            var tree = new DMeshAABBTree3(target, true);
            var bounds = new TriangleDeviationBounds(target);
            var rand = new Random(3);
            int yes = 0, no = 0;
            int tight = 0;
            foreach (double eps0 in new[] { 0.003, 0.01, 0.03, -1 }) {
                for (int k = 0; k < 150; ++k) {
                    double eps = eps0;
                    // a fan of 6 triangles around a centre near the surface
                    Vector3d c = target.GetVertex(rand.Next(target.VertexCount)) * (1 + (rand.NextDouble() - 0.5) * eps);
                    double r = 0.02 + 0.1 * rand.NextDouble();
                    Vector3d n = c.Normalized, u = n.Cross(Vector3d.AxisZ).Normalized, w = n.Cross(u);
                    var ring = Enumerable.Range(0, 6).Select(i => c + r * (Math.Cos(i * Math.PI / 3) * u + Math.Sin(i * Math.PI / 3) * w)).ToArray();
                    if (eps0 < 0) {
                        // tight: eps just above the largest corner distance, so the answers hinge on the distances
                        double dmax = ring.Concat(new[] { c }).Max(q => Math.Sqrt(MeshQueries.TriDistanceSqr(target, tree.FindNearestTriangle(q), q)));
                        eps = dmax * (1 + 1e-9) + 1e-12;
                        tight++;
                    }
                    var cache = new TriangleDeviationBounds.QueryCache(tree, eps);
                    var other = new TriangleDeviationBounds.QueryCache(tree, eps * 2);
                    var otherTree = new TriangleDeviationBounds.QueryCache(new DMeshAABBTree3(target, true), eps);
                    for (int i = 0; i < 6; ++i) {
                        Vector3d a = ring[i], b = ring[(i + 1) % 6];
                        bool plain = bounds.IsWithin(tree, c, a, b, eps);
                        Assert.Equal(plain, bounds.IsWithin(tree, c, a, b, eps, 10, cache));
                        bounds.IsWithin(tree, c, a, b, eps, 10, other);
                        bounds.IsWithin(tree, c, a, b, eps, 10, otherTree);
                        if (plain) yes++; else no++;
                    }
                    Assert.True(cache.IsWithinHits > 0, "the fan's shared corners are found in the cache");
                    Assert.Empty(other.Results);        // another distance: not used
                    Assert.Empty(otherTree.Results);    // another tree: not used
                    // every cached result, read back through the cache (a hit), equals the tree search bit for bit
                    int hits = cache.Hits;
                    foreach (Vector3d q in cache.Results.Keys.ToList()) {
                        int tid = bounds.NearestWithin(tree, q, cache, out double d);
                        int t2 = tree.FindNearestTriangle(q, out double dsq, eps);
                        Assert.Equal(t2, tid);
                        Assert.Equal(t2 >= 0 ? Math.Sqrt(dsq) : double.MaxValue, d);
                    }
                    Assert.Equal(hits + cache.Results.Count, cache.Hits);
                }
            }
            Assert.True(yes > 100 && no > 100 && tight == 150, $"{yes} within, {no} not");
        }

        /// <summary>
        /// the collapse's IsWithin calls run in parallel and share the cache: parallel equals serial
        /// (gParallel.SerialOnThisThread), and other entry points (ReduceToEdgeLength) are unchanged by sharing
        /// </summary>
        [Fact]
        public void Reduction_ParallelEqualsSerial_OtherEntryPoints()
        {
            DMesh3 input = Bumpy(20);
            double tol = 3e-3 * input.CachedBounds.DiagonalLength;
            DMesh3 parallel = Reduce(input, tol, true), serial;
            gParallel.SerialOnThisThread = true;
            try { serial = Reduce(input, tol, true); } finally { gParallel.SerialOnThisThread = false; }
            AssertSame(parallel, serial);

            double len = 0.1 * input.CachedBounds.DiagonalLength;     // longer than the input edges
            var a = new DMesh3(input); new Reducer(a) { MaxDeviation = tol, ShareDeviationQueries = false }.ReduceToEdgeLength(len);
            var b = new DMesh3(input); new Reducer(b) { MaxDeviation = tol, ShareDeviationQueries = true }.ReduceToEdgeLength(len);
            Assert.True(b.TriangleCount < input.TriangleCount);
            AssertSame(a, b);
        }

        /// <summary> invariance: 2^k scales give the same reduction, scaled, with sharing </summary>
        [Fact]
        public void Reduction_Invariance_Pow2()
        {
            DMesh3 input = Terrain(16);
            double tol = 3e-3 * input.CachedBounds.DiagonalLength;
            DMesh3 baseRes = Reduce(input, tol, true);
            foreach (Similarity sim in Similarity.All().Where(s => s.IsExact)) {
                DMesh3 scaled = new DMesh3(input);
                foreach (int v in scaled.VertexIndices()) scaled.SetVertex(v, sim.Apply(scaled.GetVertex(v)));
                DMesh3 r = Reduce(scaled, sim.ApplyLength(tol), true);
                Assert.Equal(baseRes.TriangleCount, r.TriangleCount);
                foreach (int v in baseRes.VertexIndices()) Assert.Equal(sim.Apply(baseRes.GetVertex(v)), r.GetVertex(v));
            }
        }
    }
}

