                int[] expected = Ranked(items.Length, id => distance(p, items[id]), 9, max);
                tree.NearestK(p, 9, result, max);
                Assert.Equal(expected, result.ToArray());
                Assert.Equal(expected.Length == 0 ? -1 : expected[0], tree.Nearest(p, max));
            }
        }

