        [Theory]
        [InlineData(-10, false)]
        [InlineData(0, false)]
        [InlineData(10, false)]
        [InlineData(-10, true)]
        [InlineData(0, true)]
        [InlineData(10, true)]
        public void HeightDoesNotLoseTinyQueryOffset(int exponent, bool translated)
        {
            double length = Math.Pow(2, 1000 + exponent), q = Math.Pow(2, -100 + exponent);
            double offset = translated ? 8 * q : 0;
            var triangle = new Triangle3d(new Vector3d(offset, offset, q / 2),
                new Vector3d(length, offset, q / 2), new Vector3d(offset, length, length));
            var tree = new TriangleQuadtree2d(new[] { triangle });
            for (int repeat = 0; repeat < 3; ++repeat) {
                Assert.True(tree.TryGetHeight(new Vector2d(offset, offset + q), out double height, 0));
                Assert.False(double.IsNaN(height) || double.IsInfinity(height));
                Assert.Equal(1.5 * q, height);
            }
        }

        [Theory]
        [InlineData(-10)]
        [InlineData(0)]
        [InlineData(10)]
        public void HeightInsideATriangle_SurvivesProductsThatUnderflow(int exponent)
        {
            // Near a tiny corner: both terms of a barycentric numerator underflow, though the weight q itself is fine.
            double q = Math.Pow(2, -600), z = Math.Pow(2, 1000), scale = Math.Pow(2, exponent);
            var tree = new TriangleQuadtree2d(new[] { new Triangle3d(new Vector3d(0, 0, 0), scale * new Vector3d(1, 0, z), scale * new Vector3d(q, q, 0)) });
            Assert.True(tree.TryGetHeight(new Vector2d(1.5 * q * scale, 0.5 * q * scale), out double height, 0));
            Assert.Equal(Math.Pow(2, 400 + exponent), height);

            // With a height at the first vertex, a lost weight gives a plausible value, which no later check questions.
            tree = new TriangleQuadtree2d(new[] { new Triangle3d(new Vector3d(0, 0, 1), scale * new Vector3d(1, 0, z), new Vector3d(q * scale, q * scale, 1)) });
            Assert.True(tree.TryGetHeight(new Vector2d(1.5 * q * scale, 0.5 * q * scale), out height, 0));
            Assert.Equal(Math.Pow(2, 400 + exponent), height);
        }

        [Theory]
        [InlineData(-10)]
        [InlineData(0)]
        [InlineData(10)]
        public void HeightDoesNotLoseProductsOfRepresentableScaledComponents(int exponent)
        {
            // A weight of q^2, inside the triangle, times a huge z difference: neither may be lost in the products.
            double q = Math.Pow(2, -400), z = Math.Pow(2, 1000), scale = Math.Pow(2, exponent);
            var triangle = new Triangle3d(scale * new Vector3d(0, 0, q / 2),
                scale * new Vector3d(1, 0, z), scale * new Vector3d(q, 1, q / 2));
            var tree = new TriangleQuadtree2d(new[] { triangle });
            for (int repeat = 0; repeat < 3; ++repeat) {
                Assert.True(tree.TryGetHeight(new Vector2d(2 * q * q * scale, q * scale), out double height, 0));
                Assert.Equal(Math.Pow(2, 200 + exponent), height);
                // Beside it, by a tiny distance: the height on the edge from V0 to V2, not the plane.
                Assert.True(tree.TryGetHeight(new Vector2d(0, q * scale), out height, q * scale));
                Assert.Equal(q / 2 * scale, height);
            }
        }

        [Theory]
        [InlineData(1, 1, 1, 1)]
        [InlineData(1, 1, 2, 1)]
        [InlineData(1, 1, 3, 2)]
        [InlineData(3, 1, 1, 0)]
        public void SubnormalSegmentDistanceRoundsToNearestUnit(int dx, int dy, int units, int roundedUnits)
        {
            var direction = new Vector3d(dx, dy, 0).Normalized;
            double extent = Math.Pow(2, 999);
            var segment = new Segment3d(extent * direction, direction, extent);
            var tree = new SegmentQuadtree2d(new[] { segment });
            var p = new Vector2d(units * double.Epsilon, 0);
            var ids = new List<int>();
            for (int repeat = 0; repeat < 3; ++repeat) {
                Assert.Equal(0, tree.FindNearest(p, roundedUnits * double.Epsilon));
                tree.FindNearestK(p, 1, ids, roundedUnits * double.Epsilon);
                Assert.Equal(new[] { 0 }, ids);
                if (roundedUnits > 0) {
                    Assert.Equal(-1, tree.FindNearest(p, (roundedUnits - 1) * double.Epsilon));
                    tree.FindNearestK(p, 1, ids, (roundedUnits - 1) * double.Epsilon);
                    Assert.Empty(ids);
                }
            }
        }

        [Fact]
        public void HeightDoesNotRoundAwayCoefficientsBeforeMultiplyingHeights()
        {
            double baseline = Math.Pow(2, -100), z = Math.Pow(2, 1000);
            var triangle = new Triangle3d(new Vector3d(0, 0, baseline),
                new Vector3d(1, 1, z), new Vector3d(-1, 1, z));
            var tree = new TriangleQuadtree2d(new[] { triangle });
            for (int repeat = 0; repeat < 3; ++repeat) {
                Assert.True(tree.TryGetHeight(new Vector2d(0, double.Epsilon), out double height, 0));
                Assert.Equal(Math.Pow(2, -74) + baseline, height);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using g3;
using Xunit;

namespace geometry3Sharp.Tests.Spatial
{
    public class QuadtreeQueryOptimizationTests
    {
        struct Regions : IQuadtreeVisitor2d
        {
            public List<AxisAlignedBox2d> Bounds;
            public bool TestRegion(AxisAlignedBox2d region) { Bounds.Add(region); return true; }
            public bool Visit(int id) { return false; }
        }

        static bool Overlap(AxisAlignedBox2d a, AxisAlignedBox2d b)
        {
            return a.Min.x <= b.Max.x && a.Max.x >= b.Min.x && a.Min.y <= b.Max.y && a.Max.y >= b.Min.y;
        }

        static List<AxisAlignedBox2d> VisitRegions(LooseQuadtree2d tree)
        {
            var visitor = new Regions { Bounds = new List<AxisAlignedBox2d>() };
            tree.Traverse(ref visitor);
            return visitor.Bounds;
        }

        // Regions are the bounds of what a part of the tree holds. The extent keeps removed items as well, so it can be larger.
        static void AssertRootHoldsTheItems(LooseQuadtree2d tree)
        {
            AxisAlignedBox2d root = VisitRegions(tree)[0], extent = tree.Extent;
            Assert.True(extent.Min.x <= root.Min.x && extent.Min.y <= root.Min.y && extent.Max.x >= root.Max.x && extent.Max.y >= root.Max.y);
            var all = new List<int>();
            tree.QueryRectangle(root, all);
            Assert.Equal(tree.Count, all.Count);
        }

        [Fact]
        public void RegionsHoldTheirContentAfterSplitRemovalAndExtentRebuild()
        {
            var tree = new LooseQuadtree2d(new[] { new AxisAlignedBox2d(0, 0, 8, 8) }, false);
            AssertRootHoldsTheItems(tree);
            for (int i = 0; i < 80; ++i)
                tree.Insert(new AxisAlignedBox2d(i % 8, i / 8, i % 8 + 0.5, i / 8 + 0.5));
            Assert.True(VisitRegions(tree).Count > 1);
            AssertRootHoldsTheItems(tree);
            Assert.True(tree.Remove(0));
            var before = VisitRegions(tree);
            tree.Insert(new AxisAlignedBox2d(new Vector2d(1, 1)));
            Assert.Empty(before.Except(VisitRegions(tree))); // an insert inside may split a full cell, but moves none
            tree.Insert(new AxisAlignedBox2d(new Vector2d(-1000, 2000)));
            AssertRootHoldsTheItems(tree);
            tree.Insert(new AxisAlignedBox2d(new Vector2d(-double.MaxValue, -double.MaxValue)));
            tree.Insert(new AxisAlignedBox2d(new Vector2d(double.MaxValue, double.MaxValue)));
            AssertRootHoldsTheItems(tree);
            var result = new List<int>();
            foreach (var p in new[] { new Vector2d(-1000, 2000), new Vector2d(-double.MaxValue, -double.MaxValue), new Vector2d(double.MaxValue, double.MaxValue) }) {
                tree.QueryRectangle(new AxisAlignedBox2d(p), result);
                Assert.NotEmpty(result);
                Assert.All(result, id => Assert.True(Overlap(tree.GetBounds(id), new AxisAlignedBox2d(p))));
            }
        }

