        // ---- an index over the caller's array

        [Fact]
        public void IndexOverAnArray_AnswersLikeOneWithACopy()
        {
            Triangle3d[] triangles = Triangles(JitteredGrid(24, 7.07, 3)).ToArray();
            var copied = new TriangleQuadtree2d(triangles);
            TriangleQuadtree2d shared = TriangleQuadtree2d.Over(triangles);
            var random = new Random(23);
            var a = new List<QuadtreeHeightHit2d>();
            var b = new List<QuadtreeHeightHit2d>();
            for (int q = 0; q < 300; ++q) {
                var p = new Vector2d(UtmX + random.NextDouble() * 170, UtmY + random.NextDouble() * 170);
                copied.QueryHeights(p, a);
                shared.QueryHeights(p, b);
                Assert.Equal(a.OrderBy(h => h.Id).Select(h => h.Height), b.OrderBy(h => h.Id).Select(h => h.Height));
                Assert.Equal(copied.FindNearest(p), shared.FindNearest(p));
            }
            Assert.Equal(triangles.Length, shared.Count);
            Assert.Equal(copied.Extent, shared.Extent);
        }

        [Fact]
        public void IndexOverAnArray_DoesNotCopy_AndInsertLeavesTheArrayAlone()
        {
            var triangle = new Triangle3d(new Vector3d(0, 0, 1), new Vector3d(4, 0, 1), new Vector3d(0, 4, 1));
            var other = new Triangle3d(new Vector3d(9, 9, 2), new Vector3d(12, 9, 2), new Vector3d(9, 12, 2));
            var array = new[] { triangle, triangle };
            TriangleQuadtree2d tree = TriangleQuadtree2d.Over(array);
            var copy = new TriangleQuadtree2d(array);

            // It reads the caller's array, unlike the copy. That is the promise the caller has to keep.
            array[1] = new Triangle3d(new Vector3d(0, 0, 7), new Vector3d(4, 0, 7), new Vector3d(0, 4, 7));
            Assert.Equal(7, tree.GetItem(1).V0.z);
            Assert.Equal(1, copy.GetItem(1).V0.z);

            int id = tree.Insert(other);
            Assert.Equal(2, id);
            Assert.Equal(2, array.Length);
            Assert.Equal(other.V0, tree.GetItem(id).V0);
            Assert.Equal(7, tree.GetItem(1).V0.z);
            // After the move to its own copy it no longer sees the array.
            array[0] = other;
            Assert.Equal(triangle.V0, tree.GetItem(0).V0);
            Assert.True(tree.TryGetHeight(new Vector2d(10, 10), out double height, 0));
            Assert.Equal(2, height);
            for (int i = 0; i < 40; ++i) tree.Insert(other);
            Assert.Equal(43, tree.Count);

            Assert.Throws<ArgumentNullException>(() => TriangleQuadtree2d.Over(null));
            Assert.Throws<ArgumentException>(() => TriangleQuadtree2d.Over(new[] { new Triangle3d(new Vector3d(double.NaN, 0, 0), Vector3d.Zero, Vector3d.AxisX) }));
            TriangleQuadtree2d empty = TriangleQuadtree2d.Over(new Triangle3d[0]);
            Assert.Equal(0, empty.Insert(triangle));
        }

        [Fact]
        public void AFailedInsert_LeavesTheNextIdFree_AfterRemovals()
        {
            var triangle = new Triangle3d(new Vector3d(0, 0, 1), new Vector3d(4, 0, 1), new Vector3d(0, 4, 1));
            var tree = new TriangleQuadtree2d(new[] { triangle, triangle, triangle });
            Assert.True(tree.Remove(0));
            Assert.Throws<ArgumentException>(() => tree.Insert(new Triangle3d(new Vector3d(double.NaN, 0, 0), Vector3d.Zero, Vector3d.AxisX)));
            Assert.Equal(3, tree.Insert(triangle));
            Assert.Equal(triangle.V1, tree.GetItem(3).V1);
        }

        // ---- edit cycles

        static IEnumerable<int> EveryThird(int count) { return Enumerable.Range(0, count).Where(i => i % 3 == 0); }

        [Theory]
        [InlineData(0.0, 0.0)]
        [InlineData(UtmX, UtmY)]
        public void RemoveReinsertRemove_OnEveryAdapter_MatchesAScan(double x, double y)
        {
            var random = new Random(11);
            Vector3d[] points = Enumerable.Range(0, 900).Select(i => new Vector3d(x + random.NextDouble() * 500, y + random.NextDouble() * 500, random.NextDouble())).ToArray();
            Vector3d[][] edges = Enumerable.Range(0, 900).Select(i => new[] { points[i], points[i] + new Vector3d(random.NextDouble() * 10, random.NextDouble() * 10, 1) }).ToArray();
            Vector3d[][] corners = Enumerable.Range(0, 900).Select(i => new[] { points[i], points[i] + new Vector3d(random.NextDouble() * 10, 0, 1), points[i] + new Vector3d(0, random.NextDouble() * 10 + 0.1, 2) }).ToArray();

            var pointTree = new PointQuadtree2d(points);
            var segmentTree = new SegmentQuadtree2d(new Vector3d[0], new Index2i[0]);
            foreach (Vector3d[] e in edges) segmentTree.Insert(e[0], e[1]);
            var triangleTree = new TriangleQuadtree2d(corners.Select(c => new Triangle3d(c[0], c[1], c[2])).ToArray());

            // Live items per adapter, by ID. All three see the same edits.
            var live = new Dictionary<int, int>();
            for (int i = 0; i < 900; ++i) live[i] = i;
            var check = new Action<string>(stage => {
                Assert.Equal(live.Count, pointTree.Count);
                Assert.Equal(live.Count, segmentTree.Count);
                Assert.Equal(live.Count, triangleTree.Count);
                var found = new List<int>();
                for (int q = 0; q < 40; ++q) {
                    double qx = x + random.NextDouble() * 500, qy = y + random.NextDouble() * 500;
                    var query = new AxisAlignedBox2d(qx, qy, qx + 30, qy + 30);
                    pointTree.QueryRectangle(query, found);
                    Assert.Equal(live.Where(e => Overlap(Box(points[e.Value]), query)).Select(e => e.Key).OrderBy(i => i), found.OrderBy(i => i));
                    segmentTree.QueryRectangle(query, found);
                    Assert.Equal(live.Where(e => Overlap(Box(edges[e.Value]), query)).Select(e => e.Key).OrderBy(i => i), found.OrderBy(i => i));
                    triangleTree.QueryRectangle(query, found);
                    Assert.Equal(live.Where(e => Overlap(Box(corners[e.Value]), query)).Select(e => e.Key).OrderBy(i => i), found.OrderBy(i => i));
                }
            });

            check("built");
            foreach (int i in EveryThird(900)) {
                Assert.True(pointTree.Remove(points[i]));
                Assert.True(segmentTree.Remove(edges[i][0], edges[i][1]));
                Assert.True(triangleTree.Remove(new Triangle3d(corners[i][0], corners[i][1], corners[i][2])));
                live.Remove(i);
            }
            check("removed");
            var reinserted = new List<int>();
            foreach (int i in EveryThird(900)) {
                int id = pointTree.Insert(points[i]);
                Assert.Equal(id, segmentTree.Insert(edges[i][0], edges[i][1]));
                Assert.Equal(id, triangleTree.Insert(new Triangle3d(corners[i][0], corners[i][1], corners[i][2])));
                live[id] = i;
                reinserted.Add(id);
            }
            check("reinserted");
            foreach (int i in EveryThird(900)) {
                Assert.True(pointTree.Remove(points[i]));
                Assert.True(segmentTree.Remove(edges[i][0], edges[i][1]));
                Assert.True(triangleTree.Remove(new Triangle3d(corners[i][0], corners[i][1], corners[i][2])));
                Assert.False(pointTree.Remove(points[i]));
                Assert.False(segmentTree.Remove(edges[i][0], edges[i][1]));
                Assert.False(triangleTree.Remove(new Triangle3d(corners[i][0], corners[i][1], corners[i][2])));
            }
            foreach (int id in reinserted) live.Remove(id);
            check("removed again");
        }

        // ---- a whole TIN

        static Vector3d[,] JitteredGrid(int cells, double step, int seed, Func<double, double, double> z = null)
        {
            var random = new Random(seed);
            var grid = new Vector3d[cells + 1, cells + 1];
            for (int j = 0; j <= cells; ++j)
                for (int i = 0; i <= cells; ++i) {
                    double x = UtmX + i * step + (i > 0 && i < cells ? (random.NextDouble() - 0.5) * 0.3 * step : 0);
                    double y = UtmY + j * step + (j > 0 && j < cells ? (random.NextDouble() - 0.5) * 0.3 * step : 0);
                    grid[i, j] = new Vector3d(x, y, z != null ? z(x, y) : random.NextDouble() * 100);
                }
            return grid;
        }

        static List<Triangle3d> Triangles(Vector3d[,] grid)
        {
            var result = new List<Triangle3d>();
            for (int j = 0; j + 1 < grid.GetLength(1); ++j)
                for (int i = 0; i + 1 < grid.GetLength(0); ++i) {
                    result.Add(new Triangle3d(grid[i, j], grid[i + 1, j], grid[i + 1, j + 1]));
                    result.Add(new Triangle3d(grid[i, j], grid[i + 1, j + 1], grid[i, j + 1]));
                }
            return result;
        }

        static bool ExactlyInside(Triangle3d t, Vector2d p)
        {
            int orientation = ExactPredicates.Orient2d(XY(t.V0), XY(t.V1), XY(t.V2));
            return orientation != 0 && ExactPredicates.Orient2d(XY(t.V0), XY(t.V1), p) * orientation >= 0
                && ExactPredicates.Orient2d(XY(t.V1), XY(t.V2), p) * orientation >= 0
                && ExactPredicates.Orient2d(XY(t.V2), XY(t.V0), p) * orientation >= 0;
        }

        [Fact]
        public void EveryVertexOfATin_GivesAllItsTriangles_WithTheVertexHeight()
        {
            Vector3d[,] grid = JitteredGrid(24, 7.07, 3);
            List<Triangle3d> triangles = Triangles(grid);
            var tree = new TriangleQuadtree2d(triangles);
            var hits = new List<QuadtreeHeightHit2d>();
            foreach (Vector3d vertex in grid) {
                tree.QueryHeights(XY(vertex), hits, 0);
                int[] expected = Enumerable.Range(0, triangles.Count).Where(i => ExactlyInside(triangles[i], XY(vertex))).ToArray();
                Assert.Equal(expected, hits.Select(h => h.Id).OrderBy(i => i));
                Assert.All(hits, hit => Assert.Equal(vertex.z, hit.Height));
                Assert.True(tree.TryGetHeight(XY(vertex), out double height, 0));
                Assert.Equal(vertex.z, height);
            }
        }

        [Fact]
        public void PointsOfATin_GiveExactlyTheTrianglesThatHoldThem()
        {
            Vector3d[,] grid = JitteredGrid(24, 7.07, 4);
            List<Triangle3d> triangles = Triangles(grid);
            var tree = new TriangleQuadtree2d(triangles);
            var hits = new List<QuadtreeHeightHit2d>();
            var random = new Random(8);
            for (int q = 0; q < 800; ++q) {
                Triangle3d t = triangles[random.Next(triangles.Count)];
                // On an edge up to rounding, or inside.
                double u = random.NextDouble(), v = q % 2 == 0 ? 0 : random.NextDouble() * (1 - u);
                Vector2d p = XY(t.V0) * (1 - u - v) + XY(t.V1) * u + XY(t.V2) * v;
                tree.QueryHeights(p, hits, 0);
                int[] expected = Enumerable.Range(0, triangles.Count).Where(i => ExactlyInside(triangles[i], p)).ToArray();
                Assert.Equal(expected, hits.Select(h => h.Id).OrderBy(i => i));
                foreach (QuadtreeHeightHit2d hit in hits) {
                    Triangle3d holder = triangles[hit.Id];
                    Assert.Equal(Height(holder.V0, holder.V1, holder.V2, p), hit.Height, 6);
                }
            }
            // A point on a shared edge has two exact hits, and heights that agree up to rounding.
            Triangle3d first = triangles[0];
            Vector2d onDiagonal = (XY(first.V0) + XY(first.V2)) * 0.5;
            tree.QueryHeights(onDiagonal, hits, 0);
            Assert.NotEmpty(hits);
            foreach (QuadtreeHeightHit2d hit in hits) Assert.Equal(hits[0].Height, hit.Height, 9);
        }

        [Fact]
        public void TwoStackedSurfaces_GiveTwoHeights_AndExactHitsWinOverTolerance()
        {
            Vector3d[,] lower = JitteredGrid(12, 10, 5, (x, y) => 10 + (x - UtmX) * 0.01);
            Vector3d[,] upper = JitteredGrid(12, 10, 6, (x, y) => 50 + (y - UtmY) * 0.01);
            List<Triangle3d> both = Triangles(lower).Concat(Triangles(upper)).ToList();
            var tree = new TriangleQuadtree2d(both);
            var hits = new List<QuadtreeHeightHit2d>();
            var random = new Random(13);
            for (int q = 0; q < 300; ++q) {
                var p = new Vector2d(UtmX + 10 + random.NextDouble() * 100, UtmY + 10 + random.NextDouble() * 100);
                tree.QueryHeights(p, hits, 0.01);
                int exact = both.Count(t => ExactlyInside(t, p));
                Assert.Equal(exact, hits.Count);
                Assert.True(hits.Count >= 2);
                Assert.Contains(hits, h => Math.Abs(h.Height - (10 + (p.x - UtmX) * 0.01)) < 1e-6);
                Assert.Contains(hits, h => Math.Abs(h.Height - (50 + (p.y - UtmY) * 0.01)) < 1e-6);
            }

            // Just outside one surface and inside the other: only the exact hit.
            var inner = new Triangle3d(new Vector3d(0, 0, 1), new Vector3d(10, 0, 1), new Vector3d(0, 10, 1));
            var cover = new Triangle3d(new Vector3d(-5, -5, 2), new Vector3d(15, -5, 2), new Vector3d(-5, 15, 2));
            var mixed = new TriangleQuadtree2d(new[] { inner, cover });
            mixed.QueryHeights(new Vector2d(3, -0.005), hits, 0.01);
            Assert.Equal(new[] { 1 }, hits.Select(h => h.Id));
            Assert.Equal(2, hits[0].Height);
        }

        // ---- points on few positions

        [Fact]
        public void AQuarterOfThePointsOnFewPositions_NearbyMatchesAScan()
        {
            var random = new Random(21);
            Vector2d[] heavy = Enumerable.Range(0, 5).Select(i => new Vector2d(UtmX + i * 100, UtmY + i * 50)).ToArray();
            Vector3d[] points = Enumerable.Range(0, 40000).Select(i => {
                if (i % 4 == 0) { Vector2d h = heavy[random.Next(heavy.Length)]; return new Vector3d(h.x, h.y, i); }
                return new Vector3d(UtmX + random.NextDouble() * 1000, UtmY + random.NextDouble() * 1000, i);
            }).ToArray();
            var tree = new PointQuadtree2d(points);
            var found = new List<int>();
            for (int q = 0; q < 60; ++q) {
                Vector2d p = q % 3 == 0 ? heavy[q % heavy.Length] : new Vector2d(UtmX + random.NextDouble() * 1000, UtmY + random.NextDouble() * 1000);
                double tolerance = q % 2 == 0 ? 2.5 : 0.001;
                tree.QueryNearby(p, tolerance, found);
                int[] expected = Enumerable.Range(0, points.Length).Where(i => XY(points[i]).Distance(p) <= tolerance).ToArray();
                Assert.Equal(expected, found.OrderBy(i => i));
            }
        }

        // ---- the worked example of section 2.3, as far as the library has its queries

        [Fact]
        public void WorkedEdgeExample()
        {
            Vector3d[] vertices = {
                new Vector3d(0, 0, 0), new Vector3d(10, 0, 10), new Vector3d(5, -5, 100), new Vector3d(5, 5, 200), new Vector3d(10, 10, 20),
                new Vector3d(3, -2, 50), new Vector3d(3, 0.0005, 60), new Vector3d(20, 20, 0), new Vector3d(21, 21, 0) };
            Index2i[] edges = { new Index2i(0, 1), new Index2i(2, 3), new Index2i(1, 4), new Index2i(5, 6), new Index2i(1, 0), new Index2i(7, 8) };
            const int A = 0, B = 1, C = 2, D = 3, E = 4;
            var tree = new SegmentQuadtree2d(vertices, edges);
            var found = new List<int>();

            tree.QueryPoint(new Vector2d(5, 0), 0.001, found, excludeEndpoints: true);
            Assert.Equal(new[] { A, B, E }, found.OrderBy(i => i));
            tree.QueryPoint(new Vector2d(10, 0), 0.001, found, excludeEndpoints: true);
            Assert.Empty(found);
            tree.QueryPoint(new Vector2d(100, 100), 0.001, found, excludeEndpoints: true);
            Assert.Empty(found);
            tree.QueryPoint(new Vector2d(5, 0.0004), 0.001, found, excludeEndpoints: true);
            Assert.Equal(new[] { A, B, E }, found.OrderBy(i => i));
            tree.QueryPoint(new Vector2d(5, 0.01), 0.001, found, excludeEndpoints: true);
            Assert.Equal(new[] { B }, found);

            // Section 8: touching and duplicates count, there is no tolerance. D ends 0.0005 above A, so it crosses it. F is far.
            tree.QueryIntersections(new Vector2d(0, 0), new Vector2d(10, 0), found);
            Assert.Equal(new[] { A, B, C, D, E }, found.OrderBy(i => i));
        }

        [Fact]
        public void WorkedPointExample()
        {
            var tree = new PointQuadtree2d(new[] { new Vector3d(1, 1, 0), new Vector3d(1.0005, 1, 0), new Vector3d(1, 1, 0), new Vector3d(5, 5, 0), new Vector3d(1.01, 1, 0) });
            var found = new List<int>();
            tree.QueryNearby(new Vector2d(1, 1), 0.001, found);
            Assert.Equal(new[] { 0, 1, 2 }, found.OrderBy(i => i));
            tree.QueryNearby(new Vector2d(3, 3), 0.001, found);
            Assert.Empty(found);
        }
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using g3;
using geometry3Sharp.Tests;
using Xunit;

[CollectionDefinition("StrtreeComparison.Console", DisableParallelization = true)]
public class StrtreeComparisonConsoleCollection { }

[Collection("StrtreeComparison.Console")]
public class StrtreeComparisonTests
{
    [Fact]
    public void ProceduralQueriesMatchBothIndexesAndReuseBuffers()
    {
        Triangle3d[] triangles = Program.Generate(8);
        AxisAlignedBox2d[] boxes = triangles.Select(Program.Bounds).ToArray();
        var packed = new StrtreeComparison(boxes, triangles);
        var quad = new LooseQuadtree2d(boxes);
        var heights = new TriangleQuadtree2d(triangles);
        var expected = new List<int>();
        var actual = new List<int>();
        var other = new List<int>();
        var random = new Random(7);
        for (int repeat = 0; repeat < 2; ++repeat) {
            random = new Random(7);
            for (int i = 0; i < 40; ++i) {
                var p = new Vector2d(2539000 + random.NextDouble() * 8 * 7.07, 5640000 + random.NextDouble() * 8 * 7.07);
                var end = p + new Vector2d(200 * random.NextDouble() - 100, 200 * random.NextDouble() - 100);
                var rectangle = new AxisAlignedBox2d(p, p + new Vector2d(20, 20));
                Program.BruteRectangle(boxes, rectangle, expected);
                packed.QueryRectangle(rectangle, actual);
                Program.EqualSets(expected, actual, "packed rectangle");
                quad.QueryRectangle(rectangle, other);
                Program.EqualSets(expected, other, "quad rectangle");
                Program.BruteSegment(boxes, p, end, expected);
                packed.QuerySegment(p, end, actual);
                Program.EqualSets(expected, actual, "packed segment");
                quad.QuerySegment(p, end, other);
                Program.EqualSets(expected, other, "quad segment");
                Assert.Equal(Program.BruteNearest(boxes, p), packed.FindNearest(p));
                Assert.Equal(quad.FindNearest(p), packed.FindNearest(p));
                bool found = Program.BruteHeight(triangles, p, out double height);
                Assert.Equal(found, packed.TryGetHeight(p, out double indexed));
                Assert.Equal(height, indexed);
                Assert.Equal(found, heights.TryGetHeight(p, out double qheight, 0));
                if (found) Assert.True(Math.Abs(height - qheight) < 1e-8);
                Assert.False(double.IsNaN(indexed) || double.IsInfinity(indexed));
            }
        }
    }

    [Fact]
    public void TransformedInputsMatchOracleOverAllSimilarities()
    {
        var triangle = new Triangle3d(new Vector3d(0, 0, 2), new Vector3d(8, 0, 4), new Vector3d(0, 8, 6));
        var results = new List<int>();
        var expected = new List<int>();
        foreach (Similarity s in Similarity.All()) {
            var transformed = new Triangle3d(s.Apply(triangle.V0), s.Apply(triangle.V1), s.Apply(triangle.V2));
            var boxes = new[] { Program.Bounds(transformed) };
            var index = new StrtreeComparison(boxes, new[] { transformed });
            Vector3d inside = s.Apply(new Vector3d(2, 2, 3.5));
            var point = new Vector2d(inside.x, inside.y);
            var rectangle = new AxisAlignedBox2d(point, point);
            Program.BruteRectangle(boxes, rectangle, expected);
            index.QueryRectangle(rectangle, results);
            Program.EqualSets(expected, results, s.Name);
            Assert.Equal(new[] { 0 }, results);
            Vector3d outside = s.Apply(new Vector3d(20, 20, 2));
            var end = new Vector2d(outside.x, outside.y);
            Program.BruteSegment(boxes, point, end, expected);
            index.QuerySegment(point, end, results);
            Program.EqualSets(expected, results, s.Name);
            Assert.Equal(0, index.FindNearest(end));
            Assert.True(Program.BruteHeight(new[] { transformed }, point, out double reference));
            Assert.True(index.TryGetHeight(point, out double height));
            Assert.Equal(reference, height);
            double mappedHeight = s.Inverse(new Vector3d(point.x, point.y, height)).z;
            if (s.IsExact) Assert.Equal(3.5, mappedHeight);
            else Assert.True(Math.Abs(mappedHeight - 3.5) <= 64 * s.Resolution(20), s.Name);
        }
    }

    [Fact]
    public void NearestUsesStableIdTiesAndRepeatedBuilds()
    {
        var boxes = new AxisAlignedBox2d[40];
        for (int i = 0; i < boxes.Length; ++i) {
            double x = i % 2 == 0 ? -2 : 1;
            boxes[i] = new AxisAlignedBox2d(x, -1, x + 1, 1);
        }
        foreach (Vector2d p in new[] { Vector2d.Zero, new Vector2d(0, 10), new Vector2d(-1, 0) })
            for (int repeat = 0; repeat < 3; ++repeat) {
                var index = new StrtreeComparison(boxes);
                for (int reuse = 0; reuse < 3; ++reuse)
                    Assert.Equal(Program.BruteNearest(boxes, p), index.FindNearest(p));
            }
        Assert.Equal(-1, new StrtreeComparison(new AxisAlignedBox2d[0]).FindNearest(Vector2d.Zero));
    }

    [Fact]
    public void ClosedSegmentsFilterBroadPhaseAndKeepToleranceHits()
    {
        var boxes = new[] { new AxisAlignedBox2d(0, 0, 1, 1), new AxisAlignedBox2d(0, 4, 1, 5),
            new AxisAlignedBox2d(2, 2, 2, 2) };
        var index = new StrtreeComparison(boxes);
        var expected = new List<int>();
        var actual = new List<int>();
        var starts = new[] { new Vector2d(-1, 1.0001), new Vector2d(2, 2), new Vector2d(-1, -1) };
        var ends = new[] { new Vector2d(2, 1.0001), new Vector2d(2, 2), new Vector2d(5, 5) };
        for (int i = 0; i < starts.Length; ++i) {
            Program.BruteSegment(boxes, starts[i], ends[i], expected);
            index.QuerySegment(starts[i], ends[i], actual);
            Program.EqualSets(expected, actual, "closed segment");
            Assert.NotEmpty(actual);
            Assert.DoesNotContain(1, actual);
        }
    }

    [Fact]
    public void HeightUsesFirstIdAndRejectsDegenerateOrOutsideTriangles()
    {
        var t = new Triangle3d(new Vector3d(0, 0, 10), new Vector3d(4, 0, 10), new Vector3d(0, 4, 10));
        var triangles = new[] { new Triangle3d(Vector3d.Zero, Vector3d.Zero, Vector3d.Zero), t,
            new Triangle3d(new Vector3d(0, 0, 20), new Vector3d(4, 0, 20), new Vector3d(0, 4, 20)) };
        var index = new StrtreeComparison(triangles.Select(Program.Bounds).ToArray(), triangles);
        foreach (Vector2d p in new[] { Vector2d.Zero, new Vector2d(2, 2), new Vector2d(3, 3), new Vector2d(50, 50) }) {
            bool found = Program.BruteHeight(triangles, p, out double expected);
            Assert.Equal(found, index.TryGetHeight(p, out double actual));
            Assert.Equal(expected, actual);
        }
        Assert.Throws<InvalidOperationException>(() => new StrtreeComparison(new AxisAlignedBox2d[0]).TryGetHeight(Vector2d.Zero, out _));
    }

    [Fact]
    public void ResultCheckingRejectsWrongCountAndWrongIds()
    {
        Assert.Throws<Exception>(() => Program.EqualSets(new List<int> { 1 }, new List<int>(), "count"));
        Assert.Throws<Exception>(() => Program.EqualSets(new List<int> { 1 }, new List<int> { 2 }, "ids"));
    }

    [Fact]
    public void CliIncludesFullAndPrefixRowsAndIsRepeatable()
    {
        TextWriter original = Console.Out;
        try {
            string prior = null;
            for (int repeat = 0; repeat < 2; ++repeat) {
                var text = new StringWriter();
                Console.SetOut(text);
                Assert.Equal(0, Program.Main(new[] { "4", "12", "6" }));
                string output = text.ToString();
                Assert.Contains("current_thread_allocated_bytes_per_call", output);
                Assert.Contains("build,strtree,1,", output);
                foreach (string operation in new[] { "rectangle", "segment", "nearest", "height" }) {
                    Assert.Contains(operation + ",strtree,12,", output);
                    Assert.Contains(operation + ",strtree_prefix,6,", output);
                    Assert.Contains(operation + ",quadtree_prefix,6,", output);
                }
                string validation = output.Split('\n').Single(line => line.StartsWith("validated_queries="));
                if (prior != null) Assert.Equal(prior, validation);
                prior = validation;
            }
        } finally { Console.SetOut(original); }
    }
}

