        [Fact]
        public void PointCloud_SmallPointRadiusOverALargeArea()
        {
            // 65 km across with PointRadius = 1 m: 4e9 bins of the point radius overflowed (OverflowException)
            var points = PitPoints(2.0, 0, Vector3d.Zero);
            points.Add(new Vector3d(65535, 65535, 0));
            var far = new TerrainDualContouring(points) { PointRadius = 1, GridResolution = 64 };
            far.Compute();      // the pit is smaller than a cell: no result, but no exception

            // more bins of the point radius than 4x the points: larger bins, the same samples. Plane z = 0.1 x
            // + 0.05 y sampled every 2 m, PointRadius 0.9 (fitted within up to 4 x 0.9 m)
            var plane = new List<Vector3d>();
            for (int i = 0; i <= 50; ++i)
                for (int j = 0; j <= 50; ++j)
                    plane.Add(new Vector3d(2 * i, 2 * j, 0.1 * 2 * i + 0.05 * 2 * j));
            var tdc = new TerrainDualContouring(plane) { PointRadius = 0.9, CellSize = 4 };
            Assert.True(tdc.Compute());
            // the whole cloud is sampled (up to about a cell at its border)
            AxisAlignedBox3d rb = tdc.Result.CachedBounds;
            Assert.True(rb.Min.x < 5 && rb.Min.y < 5 && rb.Max.x > 95 && rb.Max.y > 95, rb.ToString());
            double areaXY = tdc.Result.TriangleIndices().Sum(tid => Math.Abs(tdc.Result.GetTriNormal(tid).z) * tdc.Result.GetTriArea(tid));
            Assert.True(areaXY > 0.9 * 100 * 100, $"{areaXY} m^2 covered");
            foreach (int vid in tdc.Result.VertexIndices()) {
                Vector3d v = tdc.Result.GetVertex(vid);
                Assert.Equal(0.1 * v.x + 0.05 * v.y, v.z, 6);
            }
        }

        static List<Vector3d> PitPoints(double spacing, double noise, Vector3d offset, int seed = 1)
        {
            var rnd = new Random(seed);
            var pts = new List<Vector3d>();
            for (double x = -100; x <= 100; x += spacing)
                for (double y = -100; y <= 100; y += spacing) {
                    double px = x + (rnd.NextDouble() - 0.5) * spacing, py = y + (rnd.NextDouble() - 0.5) * spacing;
                    pts.Add(offset + new Vector3d(px, py, Pit(px, py) + noise * (rnd.NextDouble() - 0.5)));
                }
            return pts;
        }

        static (double rms, double p99) ErrorToPit(DMesh3 result, Vector3d offset)
        {
            var spatial = new DMeshAABBTree3(result, true);
            var rnd = new Random(3);
            var errs = new List<double>();
            for (int i = 0; i < 20000; ++i) {
                double x = rnd.NextDouble() * 180 - 90, y = rnd.NextDouble() * 180 - 90;
                double z = HeightAt(spatial, offset.x + x, offset.y + y);
                Assert.False(double.IsNaN(z));
                errs.Add(Math.Abs(z - offset.z - Pit(x, y)));
            }
            errs.Sort();
            return (Math.Sqrt(errs.Average(e => e * e)), errs[(int)(0.99 * errs.Count)]);
        }

        [Fact]
        public void PointCloud_OpenPit_BreakLinesStaySharp()
        {
            List<Vector3d> points = PitPoints(0.5, 0.02, Vector3d.Zero);
            Func<bool, (double, double, int)> run = (qef) => {
                var tdc = new TerrainDualContouring(points) { GridResolution = 100, UseQEF = qef };
                Assert.True(tdc.Compute());
                AssertCleanTerrain(tdc.Result);
                var e = ErrorToPit(tdc.Result, Vector3d.Zero);
                return (e.Item1, e.Item2, tdc.Result.TriangleCount);
            };
            var dc = run(true);
            var plain = run(false);
            Assert.True(dc.Item1 < 0.5 * plain.Item1, $"rms {dc.Item1:F3} vs {plain.Item1:F3} without QEF");
            Assert.True(dc.Item2 < 0.5, $"p99 error {dc.Item2:F3} m");
            Assert.True(dc.Item3 < 0.1 * points.Count, $"{dc.Item3} triangles for {points.Count} points");
        }

        [Fact]
        public void PointCloud_UtmCoordinates()
        {
            Vector3d offset = new Vector3d(632000, 5712000, 100);
            var tdc = new TerrainDualContouring(PitPoints(0.5, 0.02, offset)) { GridResolution = 100 };
            Assert.True(tdc.Compute());
            AssertCleanTerrain(tdc.Result);
            double rms = ErrorToPit(tdc.Result, offset).Item1;
            Assert.True(rms < 0.1);
            // the same points at the origin: the same result (rms 0.02 m both)
            var tdc0 = new TerrainDualContouring(PitPoints(0.5, 0.02, Vector3d.Zero)) { GridResolution = 100 };
            Assert.True(tdc0.Compute());
            Assert.Equal(tdc0.Result.TriangleCount, tdc.Result.TriangleCount);
            Assert.True(Math.Abs(rms - ErrorToPit(tdc0.Result, Vector3d.Zero).Item1) < 1e-6);
        }

        [Fact]
        public void PointCloud_GroundFilterThenTerrain()
        {
            // LiDAR survey of the pit with trucks on the floor: filter the ground, then build the terrain
            List<Vector3d> points = PitPoints(0.5, 0.02, Vector3d.Zero, 5);
            var rnd = new Random(9);
            for (int t = 0; t < 4; ++t) {
                double cx = -20 + 12 * t, cy = rnd.NextDouble() * 10 - 5;      // on the pit floor (|u|<30, |v|<15)
                for (double x = cx - 3; x <= cx + 3; x += 0.5)
                    for (double y = cy - 2; y <= cy + 2; y += 0.5)
                        points.Add(new Vector3d(x, y, Pit(x, y) + 4));
            }
            var csf = new ClothSimulationFilter(points) { ClothResolution = 1.0 };
            Assert.True(csf.Compute());
            var ground = points.Where((p, i) => csf.IsGround[i]).ToList();
            var tdc = new TerrainDualContouring(ground) { GridResolution = 100 };
            Assert.True(tdc.Compute());
            AssertCleanTerrain(tdc.Result);
            Assert.True(ErrorToPit(tdc.Result, Vector3d.Zero).Item2 < 0.5, "trucks left in the terrain");
        }

        [Fact]
        public void UtmCoordinates_SameAccuracy()
        {
            Vector3d offset = new Vector3d(632000, 5712000, 100);
            DMesh3 input = Heightfield((x, y) => Pit(x, y) + offset.z, offset.x - 100, offset.y - 100, offset.x + 100, offset.y + 100, 201);
            // Pit is centred at the origin: evaluate it in local coordinates
            foreach (int vid in input.VertexIndices()) {
                Vector3d v = input.GetVertex(vid);
                input.SetVertex(vid, new Vector3d(v.x, v.y, Pit(v.x - offset.x, v.y - offset.y) + offset.z));
            }
            var tdc = new TerrainDualContouring(input) { GridResolution = 100 };
            Assert.True(tdc.Compute());
            DMesh3 result = tdc.Result;
            AssertCleanTerrain(result);
            // the same input at the origin gives the same result: an absolute bound against the input (0.5 m,
            // it is 0.26 m) would hide a UTM-only loss of precision
            DMesh3 local = new DMesh3(input);
            MeshTransforms.Translate(local, -offset);
            var tdc0 = new TerrainDualContouring(local) { GridResolution = 100 };
            Assert.True(tdc0.Compute());
            Assert.Equal(tdc0.Result.TriangleCount, result.TriangleCount);
            var spatial = new DMeshAABBTree3(result, true);
            var spatial0 = new DMeshAABBTree3(tdc0.Result, true);
            var inputSpatial = new DMeshAABBTree3(input, true);
            var rnd = new Random(9);
            double max = 0, maxDiff = 0;
            for (int i = 0; i < 5000; ++i) {
                double x = rnd.NextDouble() * 190 - 95, y = rnd.NextDouble() * 190 - 95;
                double z = HeightAt(spatial, offset.x + x, offset.y + y);
                max = Math.Max(max, Math.Abs(z - HeightAt(inputSpatial, offset.x + x, offset.y + y)));
                maxDiff = Math.Max(maxDiff, Math.Abs(z - offset.z - HeightAt(spatial0, x, y)));
            }
            Assert.True(max < 0.5, $"max error {max:F3} m");
            Assert.True(maxDiff < 1e-6, $"{maxDiff} m between the UTM and the origin result");
        }
        [Fact]
        public void MergedCells_NoOverlappingTrianglesInXY()
        {
            // rough polyhedral terrain (random planes, 17 cm noise): a merged cell's vertex sat far from
            // the corners its dual triangles fan around and covered a neighbour's vertex. 5 overlapping
            // triangle pairs here, 24 on 12 km^2 of a real open pit: not a height field, so
            // TerrainVolumeDifference refused the result
            var rnd = new Random(167);
            var planes2 = Enumerable.Range(0, 15).Select(_ => new Vector3d(rnd.NextDouble() * 1.6 - 0.8, rnd.NextDouble() * 1.6 - 0.8, rnd.NextDouble() * 40)).ToList();
            var planes = Enumerable.Range(0, 25).Select(_ => new Vector3d(rnd.NextDouble() * 1.2 - 0.6, rnd.NextDouble() * 1.2 - 0.6, rnd.NextDouble() * 40)).ToList();
            double noise = rnd.NextDouble() * 0.4;
            DMesh3 mesh = Heightfield((x, y) => planes.Max(p => p.x * (x - 60) + p.y * (y - 60) + p.z) + planes2.Min(p => p.x * (x - 60) + p.y * (y - 60) + p.z)
                + noise * (rnd.NextDouble() - 0.5), 0, 0, 120, 120, 121);

            var tdc = new TerrainDualContouring(mesh) { CellSize = 1, Tolerance = 0.2 };
            Assert.True(tdc.Compute());
            Assert.Equal(0, TerrainVolumeDifference.XYOverlaps(tdc.Result));
            Assert.True(tdc.SplitLeaves > 0);
            Assert.True(tdc.Result.TriangleCount < mesh.TriangleCount / 2);
            // usable for volumes against the input
            var vd = new TerrainVolumeDifference(mesh, tdc.Result);
            Assert.True(vd.Compute());
            // no bias: the net volume is 0.15 mm times the area here
            Assert.True(Math.Abs(vd.NetVolume) < 0.002 * vd.OverlapArea, $"net {vd.NetVolume} over {vd.OverlapArea}");
        }
    }
}

using System;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// TIN from a height grid by greedy insertion (Garland and Heckbert): guaranteed maximum vertical
    /// error at every grid node, a height field by construction.
    /// </summary>
    public class TerrainGreedyTINTests
    {
        static double[] Grid(int nx, int ny, Func<int, int, double> h)
        {
            var z = new double[nx * ny];
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < nx; ++i) z[i + nx * j] = h(i, j);
            return z;
        }

        // vertical distance of every grid node from the TIN (vertical rays), and the triangles' XY area
        static double MaxNodeError(TerrainGreedyTIN g)
        {
            var tree = new DMeshAABBTree3(g.Result, true);
            double top = g.Result.CachedBounds.Max.z + 10, max = 0;
            for (int j = 0; j < g.NY; ++j)
                for (int i = 0; i < g.NX; ++i) {
                    var ray = new Ray3d(new Vector3d(g.X0 + i * g.CellSize, g.Y0 + j * g.CellSize, top), -Vector3d.AxisZ);
                    int tid = tree.FindNearestHitTriangle(ray);
                    Assert.True(tid >= 0, $"node {i},{j} not covered");
                    var intr = MeshQueries.TriangleIntersection(g.Result, tid, ray);
                    Assert.True(intr.Find());
                    max = Math.Max(max, Math.Abs(ray.PointAt(intr.RayParameter).z - g.Z[i + g.NX * j]));
                }
            return max;
        }

        [Fact]
        public void Plane_TwoTriangles()
        {
            var g = new TerrainGreedyTIN(Grid(51, 31, (i, j) => 0.3 * i - 0.2 * j + 5), 51, 31, 1000, 2000, 1) { MaxError = 1e-9 };
            Assert.True(g.Compute());
            Assert.Equal(2, g.Result.TriangleCount);
            Assert.True(g.AchievedError < 1e-9);
        }

        [Theory]
        [InlineData(0.5, false)]
        [InlineData(0.1, false)]
        [InlineData(0.02, false)]
        [InlineData(0.5, true)]
        [InlineData(0.1, true)]
        [InlineData(0.02, true)]
        public void WavyTerrain_MaxErrorAtEveryNode_HeightField(double maxError, bool removeVertices)
        {
            var rnd = new Random(3);
            int nx = 121, ny = 97;
            var z = Grid(nx, ny, (i, j) => 5 * Math.Sin(i / 9.0) * Math.Cos(j / 13.0) + 0.05 * rnd.NextDouble());
            // UTM-like origin
            var g = new TerrainGreedyTIN(z, nx, ny, 326000.5, 5641000.5, 1) { MaxError = maxError, RemoveVertices = removeVertices };
            Assert.True(g.Compute());
            g.Result.CheckValidity();
            Assert.True(g.AchievedError <= maxError);
            Assert.True(MaxNodeError(g) <= maxError + 1e-9);
            Assert.Equal(0, TerrainVolumeDifference.XYOverlaps(g.Result));
            Assert.True(g.Result.TriangleCount < 2 * (nx - 1) * (ny - 1));
            // footprint: the whole rectangle, facing up
            double area = g.Result.TriangleIndices().Sum(t => { var n = g.Result.GetTriNormal(t); Assert.True(n.z > 0); return g.Result.GetTriArea(t) * n.z; });
            Assert.Equal((nx - 1) * (ny - 1), area, 6);
        }

        [Theory]
        [InlineData(false)]
        [InlineData(true)]
        public void Benches_BreakLinesKeptWithinTheError(bool removeVertices)
        {
            // open-pit benches at 31 degrees: 8 m faces rising 6 m, 4 m berms
            double c = Math.Cos(31 * MathUtil.Deg2Rad), s = Math.Sin(31 * MathUtil.Deg2Rad);
            int n = 151;
            var z = Grid(n, n, (i, j) => {
                double u = c * i + s * j, k = Math.Floor(u / 12), f = u - 12 * k;
                return 6 * k + (f < 8 ? 6 * f / 8 : 6);
            });
            var g = new TerrainGreedyTIN(z, n, n, 0, 0, 1) { MaxError = 0.05, RemoveVertices = removeVertices };
            Assert.True(g.Compute());
            g.Result.CheckValidity();
            Assert.True(MaxNodeError(g) <= 0.05 + 1e-9);
            Assert.Equal(0, TerrainVolumeDifference.XYOverlaps(g.Result));
            // far fewer triangles than the grid (planar faces and berms)
            Assert.True(g.Result.TriangleCount < 0.2 * 2 * (n - 1) * (n - 1), $"{g.Result.TriangleCount} triangles");
        }

        [Fact]
        public void RemoveVertices_FarFewerTrianglesOnBenches()
        {
            // the planar faces and berms need only the vertices on the break lines; greedy insertion places
            // many more on the way (3909 triangles here, 249 after the removal)
            double c = Math.Cos(31 * MathUtil.Deg2Rad), s = Math.Sin(31 * MathUtil.Deg2Rad);
            int n = 151;
            var z = Grid(n, n, (i, j) => {
                double u = c * i + s * j, k = Math.Floor(u / 12), f = u - 12 * k;
                return 6 * k + (f < 8 ? 6 * f / 8 : 6);
            });
            var plain = new TerrainGreedyTIN(z, n, n, 0, 0, 1) { MaxError = 0.05 };
            var removed = new TerrainGreedyTIN(z, n, n, 0, 0, 1) { MaxError = 0.05, RemoveVertices = true };
            Assert.True(plain.Compute() && removed.Compute());
            Assert.True(MaxNodeError(removed) <= 0.05 + 1e-9);
            Assert.True(removed.RemovedVertices > 0);
            Assert.True(removed.Result.TriangleCount < 0.2 * plain.Result.TriangleCount, $"{plain.Result.TriangleCount} -> {removed.Result.TriangleCount}");
        }

        [Fact]
        public void MaxVertices_StopsEarly_ReportsTheError()
        {
            var z = Grid(64, 64, (i, j) => Math.Sin(i / 5.0) * Math.Sin(j / 7.0));
            var g = new TerrainGreedyTIN(z, 64, 64, 0, 0, 1) { MaxError = 0, MaxVertices = 50 };
            Assert.True(g.Compute());
            Assert.Equal(50, g.Result.VertexCount);
            Assert.Equal(MaxNodeError(g), g.AchievedError, 9);
        }

        [Fact]
        public void InvalidInput_Fails()
        {
            Assert.False(new TerrainGreedyTIN(new double[4], 1, 4, 0, 0, 1).Compute());
            Assert.False(new TerrainGreedyTIN(new double[] { 0, 0, double.NaN, 0 }, 2, 2, 0, 0, 1).Compute());
            Assert.False(new TerrainGreedyTIN(new double[4], 2, 2, 0, 0, 0).Compute());
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Offset surfaces of a terrain at a perpendicular distance (safety layers, minimum cover).
    /// </summary>
    public class TerrainOffsetTests
    {
        static DMesh3 Grid(double x0, double y0, double x1, double y1, int n, Func<double, double, double> h)
        {
            DMesh3 mesh = new DMesh3();
            int[,] vid = new int[n, n];
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    double x = x0 + (x1 - x0) * i / (n - 1), y = y0 + (y1 - y0) * j / (n - 1);
                    vid[i, j] = mesh.AppendVertex(new Vector3d(x, y, h(x, y)));
                }
            for (int j = 0; j + 1 < n; ++j)
                for (int i = 0; i + 1 < n; ++i) {
                    mesh.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    mesh.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            return mesh;
        }

        static double Distance(DMeshAABBTree3 s, Vector3d p) { int t = s.FindNearestTriangle(p); return Math.Sqrt(MeshQueries.TriDistanceSqr(s.Mesh, t, p)); }

        [Fact]
        public void TiltedPlane_OffsetIsParallelPlane()
        {
            Func<double, double, double> h = (x, y) => 0.3 * x - 0.2 * y;
            DMesh3 terrain = Grid(0, 0, 100, 100, 21, h);
            var off = new TerrainOffset(terrain, -5) { GridResolution = 50 };
            Assert.True(off.Compute());
            double shift = 5 * Math.Sqrt(1 + 0.3 * 0.3 + 0.2 * 0.2);     // perpendicular 5 m = vertical 5 * |n|/n_z
            foreach (int vid in off.Result.VertexIndices()) {
                Vector3d v = off.Result.GetVertex(vid);
                if (v.x < 10 || v.x > 90 || v.y < 10 || v.y > 90) continue;      // away from the terrain border
                Assert.True(Math.Abs(v.z - (h(v.x, v.y) - shift)) < 1e-6, $"{v}: {v.z} vs {h(v.x, v.y) - shift}");
            }
        }

        [Theory]
        [InlineData(5)]
        [InlineData(-5)]
        public void FlatSquare_FootprintIsKept(double d)
        {
            // the result ended where the cells did, up to a cell inside the terrain (x from 0.98 to 99.98,
            // y from 0.71 to 99.71 with 2 m cells); the terrain's boundary lines are kept now
            DMesh3 terrain = Grid(0, 0, 100, 100, 11, (x, y) => 0);
            var off = new TerrainOffset(terrain, d) { GridResolution = 50 };
            Assert.True(off.Compute());
            AxisAlignedBox3d b = off.Result.CachedBounds;
            Assert.Equal(0, b.Min.x, 6); Assert.Equal(0, b.Min.y, 6);
            Assert.Equal(100, b.Max.x, 6); Assert.Equal(100, b.Max.y, 6);
            foreach (int vid in off.Result.VertexIndices())     // (the bisection stops at 1e-6 (1 + |d|))
                Assert.True(Math.Abs(off.Result.GetVertex(vid).z - d) < 1e-5);
            double areaXY = off.Result.TriangleIndices().Sum(tid => Math.Abs(off.Result.GetTriNormal(tid).z) * off.Result.GetTriArea(tid));
            Assert.Equal(100 * 100, areaXY, 3);
        }

        [Fact]
        public void FootprintBoundary_WithoutSample_NoFootprintHeights()
        {
            // a sampled surface at z = 7 over the footprint of a flat square at z = 0, which cannot be sampled
            // along the lower edge (y < 0.01) for x > 50, nor in the last cell column (x > 99.7) for y < 50
            // (eg the offset's stepping gives up there). Boundary vertices there kept the height of the
            // footprint's boundary edge (0) instead of the sampled surface; now they use the cell's samples,
            // and boundary cells without any sample are left out
            DMesh3 square = Grid(0, 0, 100, 100, 2, (x, y) => 0);
            TerrainDualContouring.HeightSampleFunc f = (double x, double y, out double z, out Vector3d n) => {
                z = 7; n = Vector3d.AxisZ;
                return x >= 0 && y >= 0 && x <= 100 && y <= 100 && (y >= 0.01 || x <= 50) && (x <= 99.7 || y >= 50);
            };
            var tdc = new TerrainDualContouring() {
                SampleF = f, SampleBounds = new AxisAlignedBox3d(new Vector3d(0, 0, 0), new Vector3d(100, 100, 7)),
                FootprintMesh = square, GridResolution = 50
            };
            Assert.True(tdc.Compute());
            Assert.True(tdc.BoundaryFallbacks > 0);
            foreach (int vid in tdc.Result.VertexIndices())
                Assert.Equal(7, tdc.Result.GetVertex(vid).z, 9);
            // the rest of the boundary is still kept
            Assert.Equal(0, tdc.Result.CachedBounds.Min.x, 6);
            Assert.Equal(0, tdc.Result.CachedBounds.Min.y, 6);
        }

        [Fact]
        public void UtmCoordinates_SameResultAsAtTheOrigin()
        {
            // the same terrain at the origin and at UTM coordinates: the same offset surface (up to rounding)
            Vector3d utm = new Vector3d(632000, 5712000, 100);
            Func<double, double, double> h = (x, y) => Pit(x, y);
            DMesh3 local = Grid(-100, -100, 100, 100, 101, h);
            DMesh3 far = new DMesh3(local);
            MeshTransforms.Translate(far, utm);
            var a = new TerrainOffset(local, -5) { GridResolution = 50 };
            var b = new TerrainOffset(far, -5) { GridResolution = 50 };
            Assert.True(a.Compute() && b.Compute());
            var sa = new DMeshAABBTree3(a.Result, true);
            var sb = new DMeshAABBTree3(b.Result, true);
            var rnd = new Random(2);
            double maxDiff = 0;
            for (int i = 0; i < 2000; ++i) {
                double x = rnd.NextDouble() * 190 - 95, y = rnd.NextDouble() * 190 - 95;
                double za = HeightAt(sa, x, y), zb = HeightAt(sb, x + utm.x, y + utm.y) - utm.z;
                Assert.False(double.IsNaN(za) || double.IsNaN(zb), $"{x}, {y}");
                maxDiff = Math.Max(maxDiff, Math.Abs(za - zb));
            }
            Assert.True(maxDiff < 1e-3, $"{maxDiff} m between the origin and UTM results");
        }

        static double HeightAt(DMeshAABBTree3 s, double x, double y)
        {
            Ray3d ray = new Ray3d(new Vector3d(x, y, s.Mesh.CachedBounds.Max.z + 10), -Vector3d.AxisZ);
            int tid = s.FindNearestHitTriangle(ray);
            if (tid < 0) return double.NaN;
            var intr = MeshQueries.TriangleIntersection(s.Mesh, tid, ray);
            return intr.Find() ? ray.PointAt(intr.RayParameter).z : double.NaN;
        }

        [Theory]
        [InlineData(-5)]
        [InlineData(3)]
        public void OpenPit_OffsetAtDistance(double d)
        {
            DMesh3 terrain = Grid(-100, -100, 100, 100, 201, (x, y) => Pit(x, y));
            var off = new TerrainOffset(terrain, d) { GridResolution = 100 };
            Assert.True(off.Compute());
            DMesh3 result = off.Result;
            Assert.True(result.CheckValidity(false, FailMode.ReturnOnly));
            foreach (int tid in result.TriangleIndices())
                Assert.True(result.GetTriNormal(tid).z > 0);
            var ts = new DMeshAABBTree3(terrain, true);
            var rs = new DMeshAABBTree3(result, true);
            var rnd = new Random(1);
            int n = 0;
            for (int i = 0; i < 5000; ++i) {
                double x = rnd.NextDouble() * 160 - 80, y = rnd.NextDouble() * 160 - 80;
                Ray3d ray = new Ray3d(new Vector3d(x, y, 100), -Vector3d.AxisZ);
                int tid = rs.FindNearestHitTriangle(ray);
                Assert.True(tid >= 0);
                var intr = MeshQueries.TriangleIntersection(result, tid, ray);
                Assert.True(intr.Find());
                Vector3d p = ray.PointAt(intr.RayParameter);
                // on the right side of the terrain, at the distance. Around convex break lines the offset is
                // an arc of radius |d|, approximated by facets of the cell size: their chords lie up to
                // cell^2 / (8 |d|) inside it (2 m cells)
                Assert.True(Math.Sign(p.z - Pit(x, y)) == Math.Sign(d), $"{p} on the wrong side");
                double chord = 2.0 * 2.0 / (8 * Math.Abs(d));
                Assert.True(Math.Abs(Distance(ts, p) - Math.Abs(d)) < 0.02 * Math.Abs(d) + chord + 0.05, $"{p}: distance {Distance(ts, p)} instead of {Math.Abs(d)}");
                n++;
            }
            Assert.Equal(5000, n);
        }

        [Theory]
        [InlineData(0.1)]
        [InlineData(-0.1)]
        public void HighWall_SmallDistance_NoHoles(double d)
        {
            // a 20 m wall (one 1 m grid step): next to it the exit from the band is up to 20 m away
            DMesh3 terrain = Grid(0, 0, 100, 100, 101, (x, y) => x < 50 ? 0 : 20);
            var off = new TerrainOffset(terrain, d) { GridResolution = 100 };
            Assert.True(off.Compute());
            var loops = new MeshBoundaryLoops(off.Result);
            Assert.Single(loops.Loops);
            var rs = new DMeshAABBTree3(off.Result, true);
            for (double x = 2; x < 98; x += 0.7)
                for (double y = 5; y < 95; y += 9) {
                    Ray3d ray = new Ray3d(new Vector3d(x, y, 100), -Vector3d.AxisZ);
                    Assert.True(rs.FindNearestHitTriangle(ray) >= 0, $"hole at {x}, {y}");
                }
        }

        static double Pit(double x, double y)
        {
            double c = Math.Cos(17 * MathUtil.Deg2Rad), s = Math.Sin(17 * MathUtil.Deg2Rad);
            double u = c * x + s * y, v = -s * x + c * y;
            double r = Math.Max(Math.Abs(u) - 30, Math.Abs(v) - 15);
            double z = -40;
            for (int bench = 0; bench < 4; ++bench) {
                if (r <= 0) return z;
                double face = Math.Min(r, 8);
                z += 10 * face / 8;
                r -= 8;
                if (r <= 0) return z;
                r -= 6;
            }
            return z;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Defects and limits found in the quality review of the terrain classes (safety lines, point cloud
    /// contouring, volumes, ground filter).
    /// </summary>
    public class TerrainReviewTests
    {
        static DMesh3 Grid(Func<double, double, double> h, double x0, double y0, double x1, double y1, int nx, int ny = -1)
        {
            if (ny < 0) ny = nx;
            DMesh3 mesh = new DMesh3();
            int[,] vid = new int[nx, ny];
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < nx; ++i) {
                    double x = x0 + (x1 - x0) * i / (nx - 1), y = y0 + (y1 - y0) * j / (ny - 1);
                    vid[i, j] = mesh.AppendVertex(new Vector3d(x, y, h(x, y)));
                }
            for (int j = 0; j + 1 < ny; ++j)
                for (int i = 0; i + 1 < nx; ++i) {
                    mesh.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    mesh.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            return mesh;
        }

        static double R(double x, double y)
        {
            double c = Math.Cos(17 * MathUtil.Deg2Rad), s = Math.Sin(17 * MathUtil.Deg2Rad);
            double u = c * x + s * y, v = -s * x + c * y;
            return Math.Max(Math.Abs(u) - 30, Math.Abs(v) - 15);
        }
        static double Pit(double x, double y, double face = 8, double berm = 6)
        {
            double r = R(x, y), z = -40;
            for (int bench = 0; bench < 4; ++bench) {
                if (r <= 0) return z;
                z += 10 * Math.Min(r, face) / face;
                r -= face;
                if (r <= 0) return z;
                r -= berm;
            }
            return z;
        }

        static double HeightAt(DMeshAABBTree3 spatial, double x, double y)
        {
            AxisAlignedBox3d b = spatial.Mesh.CachedBounds;
            Ray3d ray = new Ray3d(new Vector3d(x, y, b.Max.z + 1), -Vector3d.AxisZ);
            int tid = spatial.FindNearestHitTriangle(ray);
            if (tid < 0) return double.NaN;
            IntrRay3Triangle3 intr = MeshQueries.TriangleIntersection(spatial.Mesh, tid, ray);
            return intr.Find() ? ray.PointAt(intr.RayParameter).z : double.NaN;
        }

        // the iso line had junctions (inner corners) where the chaining dropped edges: gaps in the line
        [Fact]
        public void SafetyLinesHorizontal_NoGapsInTheLine()
        {
            var pit = Grid((x, y) => Pit(x, y, 2.68), -100, -100, 100, 100, 201);
            var src = new List<Vector3d> { new Vector3d(-60, -40, 0), new Vector3d(60, -40, 0), new Vector3d(60, 40, 0) };
            double D = 7.5;
            var sl = new TerrainSafetyLines(pit, new[] { src }, D) { Tolerance = 0.01 };
            Assert.True(sl.Compute());
            var ls = sl.Lines.SelectMany(l => Enumerable.Range(0, l.Count - 1).Select(i => new Segment2d(l[i].xy, l[i + 1].xy))).ToList();
            double worst = 0;
            for (double a = -90; a <= 0; a += 0.25) {
                var q = new Vector2d(60, -40) + D * new Vector2d(Math.Cos(a * MathUtil.Deg2Rad), Math.Sin(a * MathUtil.Deg2Rad));
                worst = Math.Max(worst, ls.Min(s => Math.Sqrt(s.DistanceSquared(q))));
            }
            Assert.True(worst < 0.02, $"gap {worst:F3} m");
            // and every iso edge is in exactly one line
            int edges = sl.Lines.Sum(l => l.Count - 1);
            Assert.True(edges > 0);
        }

        // merged leaves next to the edge of a point cloud lost the triangles to the boundary
        [Fact]
        public void PointCloudDC_FlatSquare_NoLostArea()
        {
            var pts = new List<Vector3d>();
            for (double x = 0; x <= 100; x += 0.3)
                for (double y = 0; y <= 100; y += 0.3)
                    pts.Add(new Vector3d(x, y, 0.01 * x));
            var tdc = new TerrainDualContouring(pts) { CellSize = 1.0 };
            Assert.True(tdc.Compute());
            var sp = new DMeshAABBTree3(tdc.Result, true);
            int miss = 0, n = 0;
            for (double x = 2; x < 98; x += 0.5)
                for (double y = 2; y < 98; y += 0.5) {
                    n++;
                    if (double.IsNaN(HeightAt(sp, x, y))) miss++;
                }
            Assert.True(miss == 0, $"{100.0 * miss / n:F1}% not covered");
            Assert.True(tdc.LeafCells < 0.5 * tdc.FinestCells, "still adaptive inside");
        }

        // the same with a gap in the cloud (eg water without returns)
        [Fact]
        public void PointCloudDC_GapInTheCloud_AreaKeptAroundIt()
        {
            var pts = new List<Vector3d>();
            for (double x = 0; x <= 100; x += 0.3)
                for (double y = 0; y <= 100; y += 0.3)
                    if (Math.Abs(x - 50) > 6 || Math.Abs(y - 50) > 6) pts.Add(new Vector3d(x, y, 0.01 * x));
            var tdc = new TerrainDualContouring(pts) { CellSize = 1.0 };
            Assert.True(tdc.Compute());
            var sp = new DMeshAABBTree3(tdc.Result, true);
            int miss = 0, n = 0;
            for (double x = 2; x < 98; x += 0.5)
                for (double y = 2; y < 98; y += 0.5) {
                    if (Math.Abs(x - 50) < 8 && Math.Abs(y - 50) < 8) continue;
                    n++;
                    if (double.IsNaN(HeightAt(sp, x, y))) miss++;
                }
            Assert.True(miss == 0, $"{100.0 * miss / n:F1}% not covered");
            Assert.True(double.IsNaN(HeightAt(sp, 50, 50)), "the gap is not filled");
        }

        // two survey files merged with an overlap: the overlap would be counted twice
        [Fact]
        public void Volume_OverlappingTriangles_AreRejected()
        {
            DMesh3 before = Grid((x, y) => 0, 0, 0, 10, 10, 11);
            DMesh3 after = Grid((x, y) => -2, 0, 0, 10, 10, 11);
            MeshEditor.Append(after, Grid((x, y) => -2, 5, 0, 10, 10, 6));     // a second file, half overlapping
            var v = new TerrainVolumeDifference(before, after);
            Assert.False(v.Compute());
            Assert.True(v.AfterOverlaps > 0);
            Assert.Equal(0, v.BeforeOverlaps);
            // a clean pair passes, neighbours sharing edges (and soups) are not overlaps
            var ok = new TerrainVolumeDifference(before, Grid((x, y) => -2, 0, 0, 10, 10, 7));
            Assert.True(ok.Compute());
            Assert.Equal(200, ok.CutVolume, 6);
            Assert.Equal(0, TerrainVolumeDifference.XYOverlaps(Grid((x, y) => Math.Sin(x) * y, -50, -50, 50, 50, 41)));
        }

        // along the surface, the heat distance overestimates near the crest, so the line was closer to the
        // crest than the true distance (the unsafe side)
        [Theory]
        [InlineData(15.0)]
        [InlineData(5.0)]
        public void SafetyLineAlongSurface_NotCloserThanTheTrueDistance(double D)
        {
            // crest at x = 0, a 75 degree face 10 m high, then a berm
            double fw = 10 / Math.Tan(75 * MathUtil.Deg2Rad);
            Func<double, double, double> h = (x, y) => x <= 0 ? 0 : (x >= fw ? -10 : -10 * x / fw);
            DMesh3 t = new DMesh3();
            double[] xs = Enumerable.Range(0, 41).Select(i => -10 + 0.5 * i).Where(x => x < 0).Concat(new[] { 0.0, fw / 2, fw })
                .Concat(Enumerable.Range(0, 60).Select(i => fw + 0.5 * (i + 1))).ToArray();
            int ny = 81;
            int[,] vid = new int[xs.Length, ny];
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < xs.Length; ++i) vid[i, j] = t.AppendVertex(new Vector3d(xs[i], -20 + 0.5 * j, h(xs[i], 0)));
            for (int j = 0; j + 1 < ny; ++j)
                for (int i = 0; i + 1 < xs.Length; ++i) {
                    t.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    t.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            var crest = new List<Vector3d> { new Vector3d(0, -20, 0), new Vector3d(0, 20, 0) };
            var sl = new TerrainSafetyLines(t, new[] { crest }, D) { Mode = TerrainSafetyLines.Modes.AlongSurface };
            Assert.True(sl.Compute());
            // the remeshed band has no zero-area triangles (along the break lines and the band boundary)
            double edge = D / 8;
            Assert.Equal(0, sl.RemeshedTerrain.TriangleIndices().Count(tid => sl.RemeshedTerrain.GetTriArea(tid) < 1e-9 * edge * edge));
            double faceLen = Math.Sqrt(fw * fw + 100);
            double exact = (D <= faceLen) ? D * fw / faceLen : fw + (D - faceLen);
            int n = 0;
            foreach (var line in sl.Lines)
                foreach (Vector3d p in line) {
                    if (p.x < 0.5 || Math.Abs(p.y) > 12) continue;
                    Assert.True(p.x >= exact - 0.02, $"{p}: {exact - p.x:F3} m closer to the crest than {D} m along the surface");
                    Assert.True(p.x <= exact + 0.05 * D + 0.5, $"{p}: too far ({p.x - exact:F3} m)");
                    n++;
                }
            Assert.True(n > 20);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// TerrainSafetyLines.AlongSurface (band remeshed in parallel passes, heat method geodesic, iso line): the result
    /// must not depend on the frame, the run or the thread timing, and the line must keep the exact distance along
    /// the surface. A pit edge with a plateau (z = 0 for y &lt;= 40) and a 35 degree slope down, crest along y = 40,
    /// where the distance along the surface is known. Under 2^k scales the lines are the same bits only since the
    /// heat source of MeshGeodesicDistance scales with the mesh.
    /// </summary>
    public class TerrainSafetyAlongSurfaceInvarianceTests
    {
        const double D = 5;
        static readonly double Slope = 35 * MathUtil.Deg2Rad;
        const double H = D / 8;     // TerrainSafetyLines.EdgeLength default

        static double Height(double x, double y) => (y > 40) ? -(y - 40) * Math.Tan(Slope) : 0;

        // 80 x 80 m on a 1 m grid
        static DMesh3 Pit()
        {
            var m = new DMesh3();
            int[,] vid = new int[81, 81];
            for (int j = 0; j <= 80; ++j)
                for (int i = 0; i <= 80; ++i)
                    vid[i, j] = m.AppendVertex(new Vector3d(i, j, Height(i, j)));
            for (int j = 0; j < 80; ++j)
                for (int i = 0; i < 80; ++i) {
                    m.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    m.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            return m;
        }

        static List<Vector3d> Crest() => new List<Vector3d>() { new Vector3d(0, 40, 0), new Vector3d(80, 40, 0) };

        // exact distance along the surface to the crest (the slope unfolds onto the plateau)
        static double Exact(Vector3d p) => (p.y <= 40) ? 40 - p.y : (p.y - 40) / Math.Cos(Slope);

        static TerrainSafetyLines Compute(Similarity s)
        {
            DMesh3 terrain = Invariance.Transformed(Pit(), s);
            var crest = Crest().Select(s.Apply).ToList();
            var sl = new TerrainSafetyLines(terrain, new[] { crest }, s.ApplyLength(D)) { Mode = TerrainSafetyLines.Modes.AlongSurface };
            Assert.True(sl.Compute());
            return sl;
        }

        // terrain is z-up (the band is cut by horizontal distance): a rotated frame is rotated about z only
        static Similarity ZUp(Similarity s)
        {
            return s.IsRotated ? new Similarity(s.Name + " (about z)", s.Scale, Matrix3d.AxisAngleD(Vector3d.AxisZ, 31), s.Translation) : s;
        }

        static List<List<Vector3d>> LinesBack(TerrainSafetyLines sl, Similarity s) =>
            sl.Lines.Select(l => l.Select(s.Inverse).ToList()).ToList();

        static string LinesDifference(List<List<Vector3d>> a, List<List<Vector3d>> b)
        {
            if (a.Count != b.Count) return $"{a.Count} vs {b.Count} lines";
            for (int i = 0; i < a.Count; ++i) {
                if (a[i].Count != b[i].Count) return $"line {i}: {a[i].Count} vs {b[i].Count} points";
                for (int k = 0; k < a[i].Count; ++k)
                    if (a[i][k] != b[i][k]) return $"line {i} point {k}: {a[i][k]} vs {b[i][k]}";
            }
            return "";
        }

        // the largest distance from a point of a to the polylines b
        static double MaxDistance(List<List<Vector3d>> a, List<List<Vector3d>> b)
        {
            double max = 0;
            foreach (var line in a)
                foreach (Vector3d p in line) {
                    double best = double.MaxValue;
                    foreach (var other in b)
                        for (int k = 0; k + 1 < other.Count; ++k)
                            best = Math.Min(best, Math.Sqrt(new Segment3d(other[k], other[k + 1]).DistanceSquared(p)));
                    max = Math.Max(max, best);
                }
            return max;
        }

        static double Length(List<Vector3d> l) { double s = 0; for (int i = 1; i < l.Count; ++i) s += l[i].Distance(l[i - 1]); return s; }

        // the remeshed band is one clean piece and the line (in the original frame) is safe and close to the distance
        static void AssertResult(TerrainSafetyLines sl, Similarity s)
        {
            DMesh3 band = sl.RemeshedTerrain;
            Assert.True(band.TriangleCount > 0);
            var comps = new MeshConnectedComponents(band);
            comps.FindConnectedT();
            Assert.Equal(1, comps.Count);
            Assert.Empty(MeshIterators.BowtieVertices(band));
            Assert.True(band.Vertices().All(v => v.IsFinite));
            double h = s.ApplyLength(H);
            int degenerate = band.TriangleIndices().Count(tid => band.GetTriArea(tid) < 1e-6 * h * h);
            Assert.True(degenerate == 0, $"{s.Name}: {degenerate} degenerate triangles in the band");
            foreach (int vid in band.VertexIndices())
                Assert.False(double.IsNaN(sl.Geodesic.Distance[vid]));
            var lines = LinesBack(sl, s);
            Assert.Equal(2, lines.Count);       // both sides of the crest
            int n = 0;
            foreach (var line in lines)
                foreach (Vector3d p in line) {
                    if (p.x < 2 * D || p.x > 80 - 2 * D) continue;      // away from the crest ends
                    double e = Exact(p);
                    Assert.True(e >= D, $"{s.Name}: {p} only {e:F3} m from the crest along the surface");
                    Assert.True(e <= D + 0.35 * H + 0.3, $"{s.Name}: {p} {e:F3} m from the crest, too far");
                    n++;
                }
            Assert.True(n > 100, $"{s.Name}: {n} line points checked");
        }

        [Theory]
        [MemberData(nameof(Similarity.Names), MemberType = typeof(Similarity))]
        public void AlongSurface_SameResultUnderSimilarity(string name)
        {
            var reference = Compute(Similarity.Identity);
            AssertResult(reference, Similarity.Identity);
            Similarity s = ZUp(Similarity.ByName(name));
            var sl = Compute(s);
            AssertResult(sl, s);
            if (s.IsExact) {
                // scaling by 2^k is exact: the same band and lines, scaled, bit for bit
                Assert.Equal("", Invariance.Difference(reference.RemeshedTerrain, Invariance.MappedBack(sl.RemeshedTerrain, s)));
                Assert.Equal("", LinesDifference(LinesBack(reference, Similarity.Identity), LinesBack(sl, s)));
            } else {
                // rounding differs: the same band up to rounding, but a crest point equally far from two band
                // vertices may be mapped to the other one (eg at scale 1e3: 141 instead of 140 source vertices),
                // which moves the line there by up to about 0.3 h
                var back = LinesBack(sl, s);
                double l0 = reference.Lines.Sum(Length), l1 = back.Sum(Length);
                Assert.True(Math.Abs(l1 - l0) < 0.01 * l0, $"{s.Name}: line length {l1} vs {l0}");
                double dev = Math.Max(MaxDistance(back, reference.Lines), MaxDistance(reference.Lines, back));
                Assert.True(dev < 0.5 * H, $"{s.Name}: lines {dev} m apart");
            }
        }

        [Fact]
        public void AlongSurface_RepeatedAndConcurrentRuns_BitIdentical()
        {
            // the band is smoothed in parallel: the result must not depend on the thread timing (runs one after
            // another, and several at once)
            var reference = Compute(Similarity.Identity);
            var runs = new List<TerrainSafetyLines>();
            for (int k = 0; k < 2; ++k)
                runs.Add(Compute(Similarity.Identity));
            var concurrent = new TerrainSafetyLines[4];
            Parallel.For(0, concurrent.Length, k => concurrent[k] = Compute(Similarity.Identity));
            runs.AddRange(concurrent);
            foreach (var sl in runs) {
                Assert.Equal("", Invariance.Difference(reference.RemeshedTerrain, sl.RemeshedTerrain));
                Assert.Equal("", LinesDifference(reference.Lines, sl.Lines));
            }
        }

        [Fact]
        public void AlongSurface_ComputeTwiceOnOneInstance_SameResult()
        {
            var sl = Compute(Similarity.Identity);
            DMesh3 band = sl.RemeshedTerrain;
            var lines = sl.Lines.Select(l => l.ToList()).ToList();
            Assert.True(sl.Compute());
            Assert.Equal("", Invariance.Difference(band, sl.RemeshedTerrain));
            Assert.Equal("", LinesDifference(lines, sl.Lines));
            AssertResult(sl, Similarity.Identity);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The NoData guard of TerrainSafetyLines (ROADMAP, terrain 1a; ROBUSTNESS_SWEEP S26): a single vertex at a nodata
    /// value next to a source refined until memory ran out. Outliers near the sources are refused with a status, and the
    /// refinement limit counts the band's 3D area.
    /// </summary>
    public class TerrainSafetyNoDataTests
    {
        // n x n cells of 1 m, two triangles each
        static DMesh3 Grid(int n, Func<int, int, double> h)
        {
            var m = new DMesh3();
            for (int j = 0; j <= n; ++j)
                for (int i = 0; i <= n; ++i) m.AppendVertex(new Vector3d(i, j, h(i, j)));
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    int a = i + (n + 1) * j, b = a + 1, c = a + n + 1, d = c + 1;
                    m.AppendTriangle(a, b, d); m.AppendTriangle(a, d, c);
                }
            return m;
        }

        static List<List<Vector3d>> Crest() =>
            new List<List<Vector3d>> { new List<Vector3d> { new Vector3d(20, 5, 0), new Vector3d(20, 35, 0) } };

        const int SpikeId = 22 + 41 * 20;     // vertex (22, 20), 2 m from the source line

        [Theory]
        [InlineData(TerrainSafetyLines.Modes.Horizontal)]
        [InlineData(TerrainSafetyLines.Modes.Guaranteed)]
        [InlineData(TerrainSafetyLines.Modes.AlongSurface)]
        public void NoDataSpike_NearSource_IsRefusedFast(TerrainSafetyLines.Modes mode)
        {
            // the scenario that ran out of memory: z = -9999 at one vertex next to the crest
            DMesh3 m = Grid(40, (i, j) => (i == 22 && j == 20) ? -9999 : 0);
            Assert.Equal(-9999, m.GetVertex(SpikeId).z);
            var sw = Stopwatch.StartNew();
            var sl = new TerrainSafetyLines(m, Crest(), 5) { Mode = mode };
            Assert.False(sl.Compute());
            Assert.True(sw.ElapsedMilliseconds < 5000, sw.ElapsedMilliseconds + " ms");
            Assert.Equal(TerrainSafetyLines.Statuses.OutlierVertex, sl.Status);
            Assert.Equal(new[] { SpikeId }, sl.OutlierVertices);
            Assert.Null(sl.RefinedTerrain);
            Assert.Empty(sl.Lines);
            // named as nodata: its own status
            sl.NoDataValue = -9999;
            Assert.False(sl.Compute());
            Assert.Equal(TerrainSafetyLines.Statuses.NoDataVertex, sl.Status);
            Assert.Equal(new[] { SpikeId }, sl.OutlierVertices);
        }

        [Fact]
        public void Outliers_FarFromTheSources_DoNotMatter_AndRealSlopesPass()
        {
            // a spike 15 m from the crest (reach 5 m) and a wall of slope 50 near it
            DMesh3 m = Grid(40, (i, j) => (i == 37 && j == 20) ? -9999 : (i >= 23 && i <= 24 ? 50 * (i - 23) : (i > 24 ? 50 : 0)));
            var sl = new TerrainSafetyLines(m, Crest(), 5) { NoDataValue = -9999 };
            Assert.True(sl.Compute());
            Assert.Equal(TerrainSafetyLines.Statuses.Success, sl.Status);
            Assert.Empty(sl.OutlierVertices);
            Assert.NotEmpty(sl.Lines);
            // the same wall steeper than the limit is an outlier (its upper or lower end)
            sl.MaxTerrainSlope = 40;
            Assert.False(sl.Compute());
            Assert.Equal(TerrainSafetyLines.Statuses.OutlierVertex, sl.Status);
            Assert.NotEmpty(sl.OutlierVertices);
            Assert.All(sl.OutlierVertices, v => Assert.InRange(m.GetVertex(v).x, 23, 24));
            // no check
            sl.MaxTerrainSlope = double.PositiveInfinity;
            Assert.True(sl.Compute());
            // invalid limits
            foreach (double bad in new[] { 0.0, -1, double.NaN }) {
                sl.MaxTerrainSlope = bad;
                Assert.False(sl.Compute());
                Assert.Equal(TerrainSafetyLines.Statuses.InvalidInput, sl.Status);
            }
        }

        // the limit counts the 3D area of the band: on a plane of slope 20 the estimate is about sqrt(401) = 20 times the
        // flat one, and the real count of refined triangles within 10 times of it (it was 187 times with the horizontal band)
        [Fact]
        public void SteepTerrain_EstimateCountsThe3DArea()
        {
            DMesh3 flat = Grid(40, (i, j) => 0), steep = Grid(40, (i, j) => 20.0 * i);
            var f = new TerrainSafetyLines(flat, Crest(), 5);
            var st = new TerrainSafetyLines(steep, Crest(), 5);
            double edge = Math.Min(Math.Sqrt(8 * 5 * 0.01), 5);
            double ef = f.expected_refined_triangles(5, edge), es = st.expected_refined_triangles(5, edge);
            Assert.InRange(es / ef, 19.9, 20.1);
            Assert.True(st.Compute());
            double real = st.RefinedTerrain.TriangleCount;
            Assert.InRange(real / es, 1, 10);
        }

        [Fact]
        public void Status_OfTheOtherFailures()
        {
            DMesh3 m = Grid(10, (i, j) => 0);
            var sl = new TerrainSafetyLines(m, new List<List<Vector3d>> { new List<Vector3d> { new Vector3d(5, 2, 0), new Vector3d(5, 8, 0) } }, 2);
            Assert.True(sl.Compute());
            Assert.Equal(TerrainSafetyLines.Statuses.Success, sl.Status);
            sl.SafetyDistance = double.NaN;
            Assert.False(sl.Compute());
            Assert.Equal(TerrainSafetyLines.Statuses.InvalidInput, sl.Status);
            // a tolerance so small that the refinement exceeds MaxRefinedTriangles
            sl.SafetyDistance = 2;
            sl.Tolerance = 1e-12;
            Assert.False(sl.Compute());
            Assert.Equal(TerrainSafetyLines.Statuses.TooLarge, sl.Status);
        }

        // review: an exception in Compute must not leave the status of an earlier success
        [Fact]
        public void Status_AfterAnException_IsNotStale()
        {
            DMesh3 m = Grid(10, (i, j) => 0);
            var sl = new TerrainSafetyLines(m, new List<List<Vector3d>> { new List<Vector3d> { new Vector3d(5, 2, 0), new Vector3d(5, 8, 0) } }, 2) { Mode = TerrainSafetyLines.Modes.Guaranteed };
            Assert.True(sl.Compute());
            Assert.Equal(TerrainSafetyLines.Statuses.Success, sl.Status);
            sl.SteinerPoints = int.MaxValue / 2; sl.MaxSteinerPoints = int.MaxValue / 2;
            Assert.ThrowsAny<Exception>(() => sl.Compute());
            Assert.NotEqual(TerrainSafetyLines.Statuses.Success, sl.Status);
            Assert.False(sl.Certified);
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Break lines (crests and toes of the benches) and safety lines at a distance from them along the
    /// terrain, on an open pit built with TerrainDualContouring (break lines on mesh edges).
    /// </summary>
    public class TerrainSafetyTests
    {
        const double Angle = 17;

        // pit as in the other terrain tests; r = distance out of the bottom rectangle (30 x 15 half sizes)
        static double R(double x, double y)
        {
            double c = Math.Cos(Angle * MathUtil.Deg2Rad), s = Math.Sin(Angle * MathUtil.Deg2Rad);
            double u = c * x + s * y, v = -s * x + c * y;
            return Math.Max(Math.Abs(u) - 30, Math.Abs(v) - 15);
        }
        static double Pit(double x, double y)
        {
            double r = R(x, y), z = -40;
            for (int bench = 0; bench < 4; ++bench) {
                if (r <= 0) return z;
                z += 10 * Math.Min(r, 8) / 8;
                r -= 8;
                if (r <= 0) return z;
                r -= 6;
            }
            return z;
        }

        static DMesh3 PitTerrain()
        {
            int n = 401;
            DMesh3 mesh = new DMesh3();
            int[,] vid = new int[n, n];
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    double x = -100 + 200.0 * i / (n - 1), y = -100 + 200.0 * j / (n - 1);
                    vid[i, j] = mesh.AppendVertex(new Vector3d(x, y, Pit(x, y)));
                }
            for (int j = 0; j + 1 < n; ++j)
                for (int i = 0; i + 1 < n; ++i) {
                    mesh.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    mesh.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            var tdc = new TerrainDualContouring(mesh) { GridResolution = 200 };
            Assert.True(tdc.Compute());
            return tdc.Result;
        }

        static double Length(List<Vector3d> l) { double s = 0; for (int i = 1; i < l.Count; ++i) s += l[i].Distance(l[i - 1]); return s; }

        static double RectanglePerimeter(double r) { return 2 * (2 * (30 + r) + 2 * (15 + r)); }

        [Fact]
        public void BreakLines_CrestsAndToesOfTheBenches()
        {
            DMesh3 terrain = PitTerrain();
            var bl = new TerrainBreakLines(terrain);
            Assert.True(bl.Compute());
            // crests at r = 8, 22, 36, 50; toes at r = 0, 14, 28, 42 (plus the concave corner diagonals)
            double[] crests = { 8, 22, 36, 50 }, toes = { 0, 14, 28, 42 };
            foreach (var line in bl.Crests)
                foreach (Vector3d p in line)
                    // within a cell (1 m) of the true crest: where a crest only clips a cell, its vertex lies
                    // on one plane and the crest runs through a triangle
                    Assert.True(crests.Min(c => Math.Abs(R(p.x, p.y) - c)) < 1.0, $"crest point {p} at r = {R(p.x, p.y)}");
            double crestLength = bl.Crests.Sum(Length);
            double expected = crests.Sum(c => RectanglePerimeter(c));
            Assert.InRange(crestLength, 0.8 * expected, 1.1 * expected);
            Assert.True(bl.Toes.Sum(Length) > 0.8 * toes.Sum(c => RectanglePerimeter(c)));
        }

        [Fact]
        public void BreakLines_VerticalRiser_CrestAndToe()
        {
            // a 1 m step with a vertical riser (duplicate xy, as surveyed walls are): x = 1 at z = 0 and 1
            DMesh3 m = new DMesh3();
            double[] xs = { 0, 1, 1, 2 }, zs = { 0, 0, 1, 1 };
            int ny = 11;
            int[,] vid = new int[4, ny];
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < 4; ++i) vid[i, j] = m.AppendVertex(new Vector3d(xs[i], j, zs[i]));
            for (int j = 0; j + 1 < ny; ++j)
                for (int i = 0; i < 3; ++i) {
                    m.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                    m.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                }
            Assert.True(m.GetTriNormal(0).z > 0, "test mesh faces up");
            var bl = new TerrainBreakLines(m) { MinLineLength = 2 };
            Assert.True(bl.Compute());
            Assert.Single(bl.Crests);
            Assert.Single(bl.Toes);
            Assert.All(bl.Crests[0], p => Assert.True(p.x == 1 && p.z == 1, $"crest {p}"));
            Assert.All(bl.Toes[0], p => Assert.True(p.x == 1 && p.z == 0, $"toe {p}"));
            Assert.Equal(10, Length(bl.Crests[0]), 9);
            // the same mesh facing down (reversed orientation) gives the same lines
            m.ReverseOrientation();
            var bl2 = new TerrainBreakLines(m) { MinLineLength = 2 };
            Assert.True(bl2.Compute());
            Assert.All(bl2.Crests.SelectMany(l => l), p => Assert.True(p.z == 1));
            Assert.All(bl2.Toes.SelectMany(l => l), p => Assert.True(p.z == 0));
        }

        // the top crest: the rectangle r = 50 (u = +-80, v = +-65 in the rotated frame)
        static List<Vector3d> TopCrest()
        {
            double c = Math.Cos(Angle * MathUtil.Deg2Rad), s = Math.Sin(Angle * MathUtil.Deg2Rad);
            Func<double, double, Vector3d> P = (u, v) => new Vector3d(c * u - s * v, s * u + c * v, 0);
            var l = new List<Vector3d>() { P(-80, -65), P(80, -65), P(80, 65), P(-80, 65), P(-80, -65) };
            return l;
        }

        // horizontal: exact (bisection on the terrain edges); along the surface: on flat ground the same,
        // within about 2% plus half an edge (edges 1 m: 0.6 m, plus margin). Sources: the surveyed (exact)
        // crest polyline; detected break lines can have gaps and are not meant as sources for safety lines
        [Theory]
        [InlineData(TerrainSafetyLines.Modes.Horizontal, 0.01)]
        [InlineData(TerrainSafetyLines.Modes.AlongSurface, 0.7)]
        public void SafetyLine_FiveMetresBehindTheTopCrest(TerrainSafetyLines.Modes mode, double tolerance)
        {
            DMesh3 terrain = PitTerrain();
            var safety = new TerrainSafetyLines(terrain, new[] { TopCrest() }, 5.0) { Mode = mode };
            Assert.True(safety.Compute());
            Assert.NotEmpty(safety.Lines);
            // the line on the ground outside the pit (r > 50): 5 m from the crest rectangle
            int checkedPoints = 0;
            foreach (var line in safety.Lines)
                foreach (Vector3d p in line) {
                    if (R(p.x, p.y) < 50) continue;
                    double d = R(p.x, p.y) - 50;    // Chebyshev-like: exact away from the corners
                    if (Math.Abs(Math.Abs(UV(p).x) - 30 - 50) < 6 && Math.Abs(Math.Abs(UV(p).y) - 15 - 50) < 6) continue;   // round corners
                    Assert.True(Math.Abs(d - 5) < tolerance, $"{p}: {d} m from the crest");
                    checkedPoints++;
                }
            Assert.True(checkedPoints > 50, $"{checkedPoints} points checked");
        }

        // coarse survey TIN: a 100 x 100 square of two triangles, no vertex near the source
        static DMesh3 CoarseSquare()
        {
            DMesh3 m = new DMesh3();
            int a = m.AppendVertex(new Vector3d(0, 0, 0)), b = m.AppendVertex(new Vector3d(100, 0, 0));
            int c = m.AppendVertex(new Vector3d(100, 100, 0)), d = m.AppendVertex(new Vector3d(0, 100, 0));
            m.AppendTriangle(a, b, c); m.AppendTriangle(a, c, d);
            return m;
        }

        [Theory]
        [InlineData(TerrainSafetyLines.Modes.Horizontal, 0.02)]
        [InlineData(TerrainSafetyLines.Modes.AlongSurface, 1.2)]
        public void SafetyLine_CoarseTin_CircleAroundAPoint(TerrainSafetyLines.Modes mode, double tolerance)
        {
            Vector3d src = new Vector3d(50, 50, 0);
            var safety = new TerrainSafetyLines(CoarseSquare(), new[] { new List<Vector3d>() { src } }, 10) { Mode = mode };
            Assert.True(safety.Compute());
            Assert.Single(safety.Lines);
            var line = safety.Lines[0];
            Assert.True(line[0].Distance(line[line.Count - 1]) < 1e-9, "not closed");
            // along the surface the line is drawn with a safety margin (outwards), the heat distance error
            // is within the tolerance of that
            double offset = (mode == TerrainSafetyLines.Modes.Horizontal) ? 0 : 0.35 * 10.0 / 8;
            foreach (Vector3d p in line)
                Assert.True(Math.Abs(p.Distance(src) - 10 - offset) < tolerance, $"{p}: {p.Distance(src)}");
            // along the surface the iso line of the heat distance wiggles a little
            double r = 10 + offset;
            Assert.InRange(Length(line), 0.98 * 2 * Math.PI * r, (mode == TerrainSafetyLines.Modes.Horizontal ? 1.01 : 1.05) * 2 * Math.PI * (r + 1));
        }

        [Theory]
        [InlineData(0, 0, 0)]
        [InlineData(632000, 5712000, 100)]     // UTM
        public void SafetyLine_AlongSurface_BandIsOneCleanPiece(double ox, double oy, double oz)
        {
            // the band cut out of the refined square used to fall apart into islands joined at bowtie vertices;
            // the heat distance on an island without a source is arbitrary and made a second line at UTM
            Vector3d off = new Vector3d(ox, oy, oz);
            DMesh3 square = CoarseSquare();
            MeshTransforms.Translate(square, off);
            Vector3d src = off + new Vector3d(50, 50, 0);
            var safety = new TerrainSafetyLines(square, new[] { new List<Vector3d>() { src } }, 10) { Mode = TerrainSafetyLines.Modes.AlongSurface };
            Assert.True(safety.Compute());
            Assert.Single(safety.Lines);
            DMesh3 band = safety.RemeshedTerrain;
            var comps = new MeshConnectedComponents(band);
            comps.FindConnectedT();
            Assert.Equal(1, comps.Count);
            Assert.Empty(MeshIterators.BowtieVertices(band));
            // no zero-area ears on straight parts of the band boundary (the remesher could not collapse them;
            // their tip got no distance)
            Assert.Equal(0, band.TriangleIndices().Count(tid => band.GetTriArea(tid) < 1e-6));
            foreach (int vid in band.VertexIndices())
                Assert.False(double.IsNaN(safety.Geodesic.Distance[vid]));
            foreach (Vector3d p in safety.Lines[0])
                Assert.True(Math.Abs(p.Distance(src) - 10 - 0.35 * 10.0 / 8) < 1.2, $"{p - off}: {p.Distance(src)}");
        }

        [Theory]
        [InlineData(0, 0, 0)]
        [InlineData(632000, 5712000, 100)]     // UTM
        public void SafetyLine_AlongSurface_IgnoresTerrainOnlyNearInSpace(double ox, double oy, double oz)
        {
            // U-shaped flat terrain: arms x in [0,40] and [45,100] joined at y < 10. Seen from a source at
            // (35, 80) the other arm is 10 away in space but 80 along the terrain: the band cut around the
            // source contains a piece of it, unconnected to the source, where the heat distance is arbitrary
            Vector3d off = new Vector3d(ox, oy, oz);
            DMesh3 u = new DMesh3();
            var ids = new int[21, 21];
            for (int i = 0; i <= 20; ++i)
                for (int j = 0; j <= 20; ++j)
                    ids[i, j] = u.AppendVertex(off + new Vector3d(5 * i, 5 * j, 0));
            for (int i = 0; i < 20; ++i)
                for (int j = 0; j < 20; ++j) {
                    if (i == 8 && j >= 2) continue;         // the slot x in [40, 45], y >= 10
                    u.AppendTriangle(ids[i, j], ids[i + 1, j], ids[i + 1, j + 1]);
                    u.AppendTriangle(ids[i, j], ids[i + 1, j + 1], ids[i, j + 1]);
                }
            Vector3d src = off + new Vector3d(35, 80, 0);
            var safety = new TerrainSafetyLines(u, new[] { new List<Vector3d>() { src } }, 10) { Mode = TerrainSafetyLines.Modes.AlongSurface };
            Assert.True(safety.Compute());
            DMesh3 band = safety.RemeshedTerrain;
            var comps = new MeshConnectedComponents(band);
            comps.FindConnectedT();
            Assert.Equal(1, comps.Count);
            Assert.True(band.CachedBounds.Max.x - off.x <= 40 + 1e-6, "the band stays on the source's arm");
            // the line is the circle around the source, cut off by the slot edge at x = 40
            Assert.NotEmpty(safety.Lines);
            foreach (var line in safety.Lines)
                foreach (Vector3d p in line) {
                    Assert.True(p.x - off.x <= 40 + 1e-6, $"{p - off}");
                    Assert.True(Math.Abs(p.Distance(src) - 10 - 0.35 * 10.0 / 8) < 1.2, $"{p - off}: {p.Distance(src)}");
                }
        }

        [Fact]
        public void SafetyLine_Horizontal_NeverInsideTheDistanceByMoreThanTheTolerance()
        {
            // a crest with a convex corner: the line around the corner is an arc, approximated by chords
            var crest = new List<Vector3d>() { new Vector3d(20, 20, 0), new Vector3d(60, 20, 0), new Vector3d(60, 70, 0) };
            var safety = new TerrainSafetyLines(CoarseSquare(), new[] { crest }, 8) { Tolerance = 0.005 };
            Assert.True(safety.Compute());
            var segs = new List<Segment2d>() { new Segment2d(crest[0].xy, crest[1].xy), new Segment2d(crest[1].xy, crest[2].xy) };
            Func<Vector2d, double> dist = (q) => segs.Min(s => Math.Sqrt(s.DistanceSquared(q)));
            int n = 0;
            foreach (var line in safety.Lines)
                for (int i = 0; i + 1 < line.Count; ++i)
                    for (double t = 0; t <= 1; t += 0.25) {
                        Vector2d q = Vector2d.Lerp(line[i].xy, line[i + 1].xy, t);
                        // inside the arcs at most the tolerance; across the corner on the concave side the chords
                        // lie farther away (on the safe side)
                        Assert.True(dist(q) > 8 - 0.005 - 1e-6 && dist(q) < 8 + 0.5, $"{q}: {dist(q)}");
                        n++;
                    }
            Assert.True(n > 100);
        }

        [Theory]
        [InlineData(TerrainSafetyLines.Modes.Horizontal)]
        [InlineData(TerrainSafetyLines.Modes.AlongSurface)]
        [InlineData(TerrainSafetyLines.Modes.Guaranteed)]
        public void SafetyLine_SourcesOutsideTheTerrain_NoLines(TerrainSafetyLines.Modes mode)
        {
            var outside = new List<Vector3d>() { new Vector3d(-30, 0, 0), new Vector3d(-30, 100, 0) };
            var safety = new TerrainSafetyLines(CoarseSquare(), new[] { outside }, 10) { Mode = mode };
            Assert.True(safety.Compute());
            Assert.Empty(safety.Lines);
