using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// A replaced terrain triangle with nodes inside an edge whose neighbour has no region face (docs/design/TERRAIN.md
    /// §11): an open toe along a terrain edge that ends inside it, a lateral limit along a terrain edge, a catch point
    /// rounded onto a terrain edge. The neighbour was copied whole, so the composite had a T-junction there: a crack
    /// between two terrain triangles that the area and overlap checks do not see (TerrainSlopeCatchLineTests.TJunction
    /// now does). The neighbour is split at those nodes and replaced too.
    /// </summary>
    public class TerrainSlopeOpenToeAlongEdgeTests
    {
        // the plane z = 5 + 0.03 x on a 16 x 16 grid of [-40, 40]^2 (5 m cells); an open toe along the grid line y = -5
        // from x = x0 to x1 at z, its slope on the right (y < -5)
        internal static TerrainSlopeDesign Make(double x0, double x1, double z, TerrainSlopeDesign.Directions dir, Similarity s)
        {
            var terrain = TerrainSlopeCatchLineTests.Grid(new AxisAlignedBox2d(-40, -40, 40, 40), 16, 16, (x, y) => 5 + 0.03 * x);
            foreach (int v in terrain.VertexIndices().ToList()) terrain.SetVertex(v, s.Apply(terrain.GetVertex(v)));
            var pts = new List<Vector3d> { new Vector3d(x0, -5, z), new Vector3d(x1, -5, z) }.Select(p => s.Apply(p)).ToList();
            return new TerrainSlopeDesign() {
                Toes = { SlopeToe.Constant(pts, false, SlopeToe.Sides.Right, SlopeSpec.Degrees(30)) },
                Terrain = terrain, Tolerance = s.ApplyLength(0.05), BuildComposite = true, Direction = dir, SlopeMargin = 1e-4
            };
        }

        static void AssertGood(TerrainSlopeDesign d)
        {
            Assert.True(d.Compute(), d.Status + " " + d.Message);
            Assert.Equal(TerrainSlopeDesign.Statuses.Success, d.Status);
            if (d.Direction == TerrainSlopeDesign.Directions.Auto) TerrainSlopeMixedTests.AssertMixed(d);
            else TerrainSlopeCatchLineTests.AssertComposite(d, d.Direction == TerrainSlopeDesign.Directions.Fill);
            Assert.True(d.Composite.CheckValidity(true, FailMode.ReturnOnly));
        }

        // the toe's ends inside terrain edges (x0 -12 and -12.5, x1 12), in cut, in fill, and in a mixed run whose
        // crossing is inside the edge too (z 4.9: x = -3.3), also with the fill end (x0 -4) in the terrain triangle that
        // both runs replace at the crossing (the point inside the edge is the fill run's); the ends on terrain vertices
        // (-10, 10), where the lateral limits run along the terrain edges x = -10 and 10 and the catch points on them
        // are inside those edges
        [Theory]
        [InlineData(-12.0, 12.0, 3.0, TerrainSlopeDesign.Directions.Cut)]
        [InlineData(-12.5, 12.0, 3.0, TerrainSlopeDesign.Directions.Cut)]
        [InlineData(-12.0, 12.0, 7.0, TerrainSlopeDesign.Directions.Fill)]
        [InlineData(-12.0, 12.0, 4.9, TerrainSlopeDesign.Directions.Auto)]
        [InlineData(-4.0, 12.0, 4.9, TerrainSlopeDesign.Directions.Auto)]
        [InlineData(-10.0, 10.0, 3.0, TerrainSlopeDesign.Directions.Cut)]
        public void ToeAlongATerrainEdge_EndsInsideIt(double x0, double x1, double z, TerrainSlopeDesign.Directions dir)
        {
            var d = Make(x0, x1, z, dir, Similarity.Identity);
            AssertGood(d);
            // (the terrain triangle across the toe's line beyond its start has no region face: it is split and replaced)
            if (x0 != -10) {
                int beyond = d.Terrain.TriangleIndices().First(t => {
                    Index3i v = d.Terrain.GetTriangle(t);
                    Vector2d pa = d.Terrain.GetVertex(v.a).xy, pb = d.Terrain.GetVertex(v.b).xy, pc = d.Terrain.GetVertex(v.c).xy, x = new Vector2d(x0 - 0.25, -4.9);
                    int o1 = ExactPredicates.Orient2d(pa, pb, x), o2 = ExactPredicates.Orient2d(pb, pc, x), o3 = ExactPredicates.Orient2d(pc, pa, x);
                    return (o1 > 0 && o2 > 0 && o3 > 0) || (o1 < 0 && o2 < 0 && o3 < 0);
                });
                Assert.Contains(beyond, d.ReplacedTerrainTriangles);
            }
        }

        // the T-junction check of the tests itself: a vertex inside a boundary edge with a triangle of the edge's group,
        // or at the edge's height, is a crack; one at another height in another group (a step) is not, nor one off the
        // edge's line
        // (on a toe, onStep: a step between slope and terrain at the same height is not a crack, between two slope pieces
        // it is; terrain group 2)
        [Theory]
        [InlineData(0, 0.0, 0.0, false, true)]
        [InlineData(1, 0.0, 0.0, false, true)]
        [InlineData(1, 1e-3, 0.0, false, false)]
        [InlineData(0, 0.0, 1e-12, false, false)]
        [InlineData(2, 0.0, 0.0, true, false)]
        [InlineData(1, 0.0, 0.0, true, true)]
        public void TJunctionCheck(int lowerGroup, double dz, double dy, bool onToe, bool crack)
        {
            var m = new DMesh3(false, false, false, true);
            int a = m.AppendVertex(new Vector3d(0, 0, 1)), b = m.AppendVertex(new Vector3d(2, 0, 1)), c = m.AppendVertex(new Vector3d(1, 1, 1));
            int p = m.AppendVertex(new Vector3d(1, dy, 1 + dz)), q = m.AppendVertex(new Vector3d(1, -1, 1));
            int a2 = m.AppendVertex(new Vector3d(0, 0, 1 + dz)), b2 = m.AppendVertex(new Vector3d(2, 0, 1 + dz));
            m.AppendTriangle(a, b, c, 0);
            m.AppendTriangle(a2, q, p, lowerGroup);
            m.AppendTriangle(p, q, b2, lowerGroup);
            string r = TerrainSlopeCatchLineTests.TJunction(m, onToe ? (Func<Vector2d, bool>)(x => true) : null, 2);
            Assert.True(crack ? r != "" : r == "", r);
        }

        // the replacement and the terrain triangles it does not replace, joined by position: no T-junction there either
        [Theory]
        [InlineData(TerrainSlopeDesign.Directions.Cut, 3.0)]
        [InlineData(TerrainSlopeDesign.Directions.Auto, 4.9)]
        public void Replacement_JoinsTheTerrainWithoutAT(TerrainSlopeDesign.Directions dir, double z)
        {
            var d = Make(-12, 12, z, dir, Similarity.Identity);
            d.CompositeKind = TerrainSlopeDesign.CompositeKinds.Replacement;
            Assert.True(d.Compute(), d.Status + " " + d.Message);
            var whole = new DMesh3(false, false, false, true);
            var at = new Dictionary<Vector3d, int>();
            Func<Vector3d, int> vertex = (p) => {
                p.x += 0.0; p.y += 0.0; p.z += 0.0;
                int id;
                if (at.TryGetValue(p, out id) == false) { id = whole.AppendVertex(p); at[p] = id; }
                return id;
            };
            foreach (int t in d.Replacement.TriangleIndices()) {
                Index3i v = d.Replacement.GetTriangle(t);
                Assert.True(whole.AppendTriangle(vertex(d.Replacement.GetVertex(v.a)), vertex(d.Replacement.GetVertex(v.b)), vertex(d.Replacement.GetVertex(v.c)), d.Replacement.GetTriangleGroup(t)) >= 0);
            }
            var replaced = new HashSet<int>(d.ReplacedTerrainTriangles);
            foreach (int t in d.Terrain.TriangleIndices()) {
                if (replaced.Contains(t)) continue;
                Index3i v = d.Terrain.GetTriangle(t);
                Assert.True(whole.AppendTriangle(vertex(d.Terrain.GetVertex(v.a)), vertex(d.Terrain.GetVertex(v.b)), vertex(d.Terrain.GetVertex(v.c)), d.Pieces.Count) >= 0);
            }
            Assert.Equal(0, TerrainVolumeDifference.XYOverlaps(whole));
            string tj = TerrainSlopeCatchLineTests.TJunction(whole);
            Assert.True(tj == "", tj);
        }

        static readonly Lazy<TerrainSlopeDesign> reference = new Lazy<TerrainSlopeDesign>(() => {
            var d = Make(-12.5, 12, 3, TerrainSlopeDesign.Directions.Cut, Similarity.Identity);
            Assert.True(d.Compute(), d.Status + " " + d.Message);
            return d;
        });

        // every frame; the 2^k frames give the identity's result scaled, bit for bit (rotated, the toe's end is not
        // exactly on the terrain edge's line any more, so nothing is split there)
        [Theory]
        [MemberData(nameof(Similarity.Names), MemberType = typeof(Similarity))]
        public void Similarities(string name)
        {
            Similarity s = Similarity.ByName(name);
            if (s.IsRotated) s = new Similarity(s.Name + " (about z)", s.Scale, Matrix3d.AxisAngleD(Vector3d.AxisZ, 31), s.Translation);
            var d = Make(-12.5, 12, 3, TerrainSlopeDesign.Directions.Cut, s);
            AssertGood(d);
            if (s.IsExact) {
                var r = reference.Value;
                Assert.Equal("", Invariance.Difference(r.Composite, Invariance.MappedBack(d.Composite, s)));
                Assert.Equal("", Invariance.Difference(r.SlopeRegion, Invariance.MappedBack(d.SlopeRegion, s)));
                Assert.Equal(r.ReplacedTerrainTriangles, d.ReplacedTerrainTriangles);
            }
        }

        [Fact]
        public void Reuse()
        {
            var d = Make(-12, 12, 3, TerrainSlopeDesign.Directions.Cut, Similarity.Identity);
            AssertGood(d);
            var c1 = new DMesh3(d.Composite);
            var r1 = new List<int>(d.ReplacedTerrainTriangles);
            AssertGood(d);
            Assert.Equal("", Invariance.Difference(c1, d.Composite));
            Assert.Equal(r1, d.ReplacedTerrainTriangles);
        }
    }
}

using System;
using System.Linq;
using System.Numerics;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The "never steeper" oracle (docs/design/TERRAIN.md 5.4, 7 "oracle tests"): Slope.IsNotSteeper and
    /// Slope.IsSupportedBy against hand-computed cases and against an independent rational reference.
    /// </summary>
    public class TerrainSlopeOracleTests
    {
        // ---- independent reference: exact rationals as (numerator, denominator) BigIntegers ----

        struct Q
        {
            public BigInteger N, D;    // D > 0
            public Q(BigInteger n, BigInteger d) { if (d.Sign < 0) { n = -n; d = -d; } N = n; D = d; }
            public static Q Of(double x)
            {
                if (x == 0) return new Q(0, 1);
                long bits = BitConverter.DoubleToInt64Bits(x);
                int exp = (int)((bits >> 52) & 0x7FF);
                long frac = bits & 0xFFFFFFFFFFFFFL;
                if (exp == 0) exp = 1; else frac |= 1L << 52;
                BigInteger m = bits < 0 ? -frac : frac;
                int e = exp - 1075;
                return e >= 0 ? new Q(m << e, 1) : new Q(m, BigInteger.One << -e);
            }
            public static Q operator +(Q a, Q b) => new Q(a.N * b.D + b.N * a.D, a.D * b.D);
            public static Q operator -(Q a, Q b) => new Q(a.N * b.D - b.N * a.D, a.D * b.D);
            public static Q operator *(Q a, Q b) => new Q(a.N * b.N, a.D * b.D);
            public int Sign => N.Sign;
        }

        // reference: slope^2 <= limit^2, limit = num / den given as rationals
        static bool RefNotSteeper(Vector3d a, Vector3d b, Vector3d c, Q limit)
        {
            Q ux = Q.Of(b.x) - Q.Of(a.x), uy = Q.Of(b.y) - Q.Of(a.y), uz = Q.Of(b.z) - Q.Of(a.z);
            Q vx = Q.Of(c.x) - Q.Of(a.x), vy = Q.Of(c.y) - Q.Of(a.y), vz = Q.Of(c.z) - Q.Of(a.z);
            Q nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
            if (nz.Sign == 0) return false;
            return (limit * limit * nz * nz - (nx * nx + ny * ny)).Sign >= 0;
        }

        static Q RefLimit(SlopeSpec spec)
        {
            switch (spec.Kind) {
                case SlopeSpec.Kinds.Ratio: { Q n = Q.Of(spec.Value); return new Q(n.D, n.N); }
                case SlopeSpec.Kinds.Percent: { Q p = Q.Of(spec.Value); return new Q(p.N, p.D * 100); }
                default: return Q.Of(spec.S);
            }
        }

        static double NextUp(double x)
        {
            if (x == 0) return double.Epsilon;
            long b = BitConverter.DoubleToInt64Bits(x);
            return BitConverter.Int64BitsToDouble(x > 0 ? b + 1 : b - 1);
        }
        static double NextDown(double x) => -NextUp(-x);
        static Vector3d Up(Vector3d p) => new Vector3d(p.x, p.y, NextUp(p.z));
        static Vector3d Down(Vector3d p) => new Vector3d(p.x, p.y, NextDown(p.z));
        static void Tri(DMesh3 m, int t, out Vector3d a, out Vector3d b, out Vector3d c)
        {
            a = b = c = Vector3d.Zero;
            m.GetTriVertices(t, ref a, ref b, ref c);
        }

        // ---- hand-computed cases ----

        [Fact]
        public void Ratio_ExactlyAtTheSlope_AndOneUlpSteeper()
        {
            // rises 1 over a run of 3: exactly 1:3
            Vector3d a = new Vector3d(0, 0, 0), b = new Vector3d(3, 0, 0), c = new Vector3d(0, 3, 1);
            Assert.True(Slope.IsNotSteeper(a, b, c, SlopeSpec.Ratio(3)));
            Assert.False(Slope.IsNotSteeper(a, b, Up(c), SlopeSpec.Ratio(3)));
            Assert.True(Slope.IsNotSteeper(a, b, Down(c), SlopeSpec.Ratio(3)));
            // the double S of 1:3 is below 1/3, so Rise(S) rejects the exact 1:3 triangle: the ratio is checked as entered
            double s = SlopeSpec.Ratio(3).S;
            Assert.True((RefLimit(SlopeSpec.Ratio(3)) - Q.Of(s)).Sign > 0);   // 1/3 is not a double
            Assert.False(Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(s)));
            // orientation does not matter
            Assert.True(Slope.IsNotSteeper(a, c, b, SlopeSpec.Ratio(3)));
            Assert.True(Slope.IsNotSteeper(c, b, a, SlopeSpec.Ratio(3)));
        }

        [Fact]
        public void Percent_ExactlyAtTheSlope()
        {
            Vector3d a = new Vector3d(10, 20, 5), b = new Vector3d(12, 20, 5), c = new Vector3d(10, 22, 6);   // 50 %
            Assert.True(Slope.IsNotSteeper(a, b, c, SlopeSpec.Percent(50)));
            Assert.False(Slope.IsNotSteeper(a, b, Up(c), SlopeSpec.Percent(50)));
            Assert.False(Slope.IsNotSteeper(a, b, c, SlopeSpec.Percent(49.999999999)));
            // 0.1 % is not a double ratio: the check is against p as entered
            Vector3d d = new Vector3d(0, 0, 0), e = new Vector3d(1000, 0, 0), f = new Vector3d(0, 1000, 1);
            Assert.True(Slope.IsNotSteeper(d, e, f, SlopeSpec.Percent(0.1)));
            Assert.Equal(RefNotSteeper(d, e, Up(f), RefLimit(SlopeSpec.Percent(0.1))), Slope.IsNotSteeper(d, e, Up(f), SlopeSpec.Percent(0.1)));
        }

        [Fact]
        public void Degrees_AgainstTheDoubleTangent()
        {
            Assert.False(SlopeSpec.Degrees(45).ExactlyCheckable);
            Assert.True(SlopeSpec.Ratio(1).ExactlyCheckable && SlopeSpec.Percent(100).ExactlyCheckable);
            // slope exactly 1: tan(45 deg) in doubles is 0.9999999999999999, so the check against the double fails
            Vector3d a = new Vector3d(0, 0, 0), b = new Vector3d(1, 0, 0), c = new Vector3d(0, 1, 1);
            Assert.Equal(SlopeSpec.Degrees(45).S >= 1, Slope.IsNotSteeper(a, b, c, SlopeSpec.Degrees(45)));
            Assert.True(Slope.IsNotSteeper(a, b, c, SlopeSpec.Ratio(1)));
        }

        [Fact]
        public void Gradient_IsTheFallLine_InAnyDirection()
        {
            // plane z = 0.3 x + 0.4 y has slope 0.5 whatever the triangle
            Func<double, double, Vector3d> p = (x, y) => new Vector3d(x, y, 0.3 * x + 0.4 * y);
            Vector3d a = p(0, 0), b = p(10, 0), c = p(0, 10);
            Assert.True(Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(0.5000001)));
            Assert.False(Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(0.4999999)));
            Assert.False(Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(0.4)));     // steeper than its steepest axis component
        }

        [Fact]
        public void Degenerate_And_Invalid_AreRejected()
        {
            Vector3d a = new Vector3d(0, 0, 0), b = new Vector3d(1, 1, 0), c = new Vector3d(2, 2, 0);
            Assert.False(Slope.IsNotSteeper(a, b, c, SlopeSpec.Ratio(1)));      // collinear in XY, even if flat
            Assert.False(Slope.IsNotSteeper(a, a, a, SlopeSpec.Ratio(1)));
            Vector3d d = new Vector3d(1, 0, 0), e = new Vector3d(0, 1, 0);
            Assert.True(Slope.IsNotSteeper(a, d, e, SlopeSpec.Ratio(1)));        // flat
            foreach (var bad in new[] { SlopeSpec.Ratio(0), SlopeSpec.Ratio(-1), SlopeSpec.Ratio(double.NaN), SlopeSpec.Rise(double.PositiveInfinity), SlopeSpec.Degrees(90) }) {
                Assert.False(bad.IsValid);
                Assert.True(double.IsNaN(bad.S));
                Assert.False(Slope.IsNotSteeper(a, d, e, bad));
            }
            Assert.False(Slope.IsNotSteeper(a, d, new Vector3d(0, 1, double.NaN), SlopeSpec.Ratio(1)));
        }

        [Fact]
        public void S_IsNeverSteeperThanTheSpec()
        {
            var rnd = new Random(5);
            for (int i = 0; i < 2000; ++i) {
                double n = Math.Exp(rnd.NextDouble() * 10 - 5), p = Math.Exp(rnd.NextDouble() * 10 - 3);
                Assert.True(new Q(1, 1).Sign > 0);
                Q sr = Q.Of(SlopeSpec.Ratio(n).S), lr = RefLimit(SlopeSpec.Ratio(n));
                Assert.True((lr - sr).Sign >= 0);
                Assert.True((lr - Q.Of(NextUp(SlopeSpec.Ratio(n).S))).Sign < 0);    // the largest such double
                Q sp = Q.Of(SlopeSpec.Percent(p).S), lp = RefLimit(SlopeSpec.Percent(p));
                Assert.True((lp - sp).Sign >= 0);
                Assert.True((lp - Q.Of(NextUp(SlopeSpec.Percent(p).S))).Sign < 0);
            }
        }

        // ---- against the rational reference ----

        // triangles near their limit (a plane with gradient of magnitude about s), perturbed by a few ulp, at many
        // magnitudes: the oracle agrees with the reference on every one
        [Theory]
        [InlineData(1.0, 0.0)]
        [InlineData(1.0, 632117.25)]
        [InlineData(1e-3, 5712043.5)]
        [InlineData(1e-150, 0)]
        [InlineData(1e150, 1e160)]
        [InlineData(1e-300, 0)]       // subnormal differences
        [InlineData(1e100, 0)]        // products beyond the double range
        public void RandomNearTheLimit_AgreesWithRationals(double scale, double offset)
        {
            var rnd = new Random(11);
            var specs = new[] { SlopeSpec.Ratio(3), SlopeSpec.Ratio(1.5), SlopeSpec.Percent(70), SlopeSpec.Rise(0.731), SlopeSpec.Degrees(35) };
            int agree = 0, notSteeper = 0, steeper = 0;
            for (int i = 0; i < 3000; ++i) {
                SlopeSpec spec = specs[i % specs.Length];
                double s = spec.S, phi = rnd.NextDouble() * 2 * Math.PI;
                double gx = s * Math.Cos(phi), gy = s * Math.Sin(phi);
                Func<double, double, Vector3d> p = (x, y) => new Vector3d(offset + scale * x, offset + scale * y, scale * (gx * x + gy * y));
                Vector3d a = p(rnd.NextDouble(), rnd.NextDouble()), b = p(rnd.NextDouble(), rnd.NextDouble()), c = p(rnd.NextDouble(), rnd.NextDouble());
                int k = rnd.Next(-3, 4);
                for (int j = 0; j < Math.Abs(k); ++j) c = k > 0 ? Up(c) : Down(c);
                bool r = RefNotSteeper(a, b, c, RefLimit(spec));
                Assert.Equal(r, Slope.IsNotSteeper(a, b, c, spec));
                agree++;
                if (r) notSteeper++; else steeper++;
            }
            // both answers occur, so the cases are near the limit
            Assert.True(notSteeper > 100 && steeper > 100, $"{notSteeper} / {steeper}");
        }

        [Fact]
        public void IsSupportedBy_HandCases()
        {
            // toe from (0,0,10) to (10,0,10), slope 1:2 rising in +y: the plane z = 10 + y / 2
            Vector3d p0 = new Vector3d(0, 0, 10), p1 = new Vector3d(10, 0, 10);
            Vector3d a = new Vector3d(0, 4, 12), b = new Vector3d(10, 4, 12), c = new Vector3d(5, 8, 14);
            Assert.True(Slope.IsSupportedBy(a, b, c, p0, p1, SlopeSpec.Ratio(2)));
            // the same triangle 1 ulp higher: its plane passes above the toe
            Assert.False(Slope.IsSupportedBy(Up(a), Up(b), Up(c), p0, p1, SlopeSpec.Ratio(2)));
            // lowered: still supported (below the cones)
            Assert.True(Slope.IsSupportedBy(Down(a), Down(b), Down(c), p0, p1, SlopeSpec.Ratio(2)));
            // not steeper, but far above the toe: not supported
            Vector3d off = new Vector3d(0, 0, 1);
            Assert.True(Slope.IsNotSteeper(a + off, b + off, c + off, SlopeSpec.Ratio(2)));
            Assert.False(Slope.IsSupportedBy(a + off, b + off, c + off, p0, p1, SlopeSpec.Ratio(2)));
            // on the toe: the toe triangle itself
            Assert.True(Slope.IsSupportedBy(p0, p1, c, p0, p1, SlopeSpec.Ratio(2)));
            // a single apex (p0 = p1): a cone tangent plane through (0,0,10) in direction (1,1)/sqrt 2
            Vector3d q = new Vector3d(0, 0, 10);
            Assert.True(Slope.IsSupportedBy(q, new Vector3d(-5, 5, 10), new Vector3d(4, 4, 10 + 0.5 * Math.Sqrt(32) * 0.999), q, q, SlopeSpec.Ratio(2)));
        }

        [Fact]
        public void IsSupportedBy_MatchesTheDefinition_Random()
        {
            // the reference: slope by rationals, plane at the toe points by rationals
            var rnd = new Random(17);
            int both = 0;
            for (int i = 0; i < 2000; ++i) {
                Vector3d p0 = new Vector3d(rnd.NextDouble(), rnd.NextDouble(), rnd.NextDouble());
                Vector3d p1 = new Vector3d(rnd.NextDouble(), rnd.NextDouble(), rnd.NextDouble());
                Func<Vector3d> r = () => new Vector3d(rnd.NextDouble() * 3, rnd.NextDouble() * 3, rnd.NextDouble() * 3);
                Vector3d a = r(), b = r(), c = r();
                var spec = SlopeSpec.Rise(1 + rnd.NextDouble() * 3);
                bool slope = RefNotSteeper(a, b, c, RefLimit(spec));
                bool below = RefPlaneBelow(a, b, c, p0) && RefPlaneBelow(a, b, c, p1);
                Assert.Equal(slope && below, Slope.IsSupportedBy(a, b, c, p0, p1, spec));
                if (slope && below) both++;
            }
            Assert.True(both > 50);
        }

        // plane of (a, b, c) at p's XY <= p.z, by rationals: z = a.z - (nx (x - ax) + ny (y - ay)) / nz
        static bool RefPlaneBelow(Vector3d a, Vector3d b, Vector3d c, Vector3d p)
        {
            Q ux = Q.Of(b.x) - Q.Of(a.x), uy = Q.Of(b.y) - Q.Of(a.y), uz = Q.Of(b.z) - Q.Of(a.z);
            Q vx = Q.Of(c.x) - Q.Of(a.x), vy = Q.Of(c.y) - Q.Of(a.y), vz = Q.Of(c.z) - Q.Of(a.z);
            Q nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
            if (nz.Sign == 0) return false;
            // p.z - plane(p) = ((p.z - a.z) nz + nx (px - ax) + ny (py - ay)) / nz
            Q t = (Q.Of(p.z) - Q.Of(a.z)) * nz + nx * (Q.Of(p.x) - Q.Of(a.x)) + ny * (Q.Of(p.y) - Q.Of(a.y));
            return t.Sign * nz.Sign >= 0;
        }

        // ---- on existing results: TerrainGreedyTIN ----

        // On every triangle of a greedy TIN of a wavy terrain at UTM, the oracle at the triangle's own slope (as a
        // double, rounded up and down) agrees with the rational reference, and the steepest triangle is found.
        [Fact]
        public void GreedyTIN_EveryTriangle_AgreesWithRationals()
        {
            int nx = 61, ny = 47;
            var z = new double[nx * ny];
            for (int j = 0; j < ny; ++j)
                for (int i = 0; i < nx; ++i) z[i + nx * j] = 8 * Math.Sin(i / 7.0) * Math.Cos(j / 5.0) + 0.3 * i;
            var g = new TerrainGreedyTIN(z, nx, ny, 326000.5, 5641000.5, 1) { MaxError = 0.05 };
            Assert.True(g.Compute());
            DMesh3 tin = g.Result;
            double steepest = 0;
            int checks = 0;
            foreach (int tid in tin.TriangleIndices()) {
                Vector3d a, b, c;
                Tri(tin, tid, out a, out b, out c);
                Vector3d n = (b - a).Cross(c - a);
                double s = Math.Sqrt(n.x * n.x + n.y * n.y) / Math.Abs(n.z);
                steepest = Math.Max(steepest, s);
                foreach (double lim in new[] { s, NextUp(s), NextDown(s), s * (1 + 1e-12), s * (1 - 1e-12) }) {
                    Assert.Equal(RefNotSteeper(a, b, c, Q.Of(lim)), Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(lim)));
                    checks++;
                }
                Assert.True(Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(s * (1 + 1e-12))));
                Assert.False(Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(s * (1 - 1e-12))));
            }
            // the whole TIN against its steepest triangle: not steeper than that, steeper than slightly less
            Assert.True(tin.TriangleIndices().All(t => { Vector3d a, b, c; Tri(tin, t, out a, out b, out c); return Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(steepest * (1 + 1e-12))); }));
            Assert.False(tin.TriangleIndices().All(t => { Vector3d a, b, c; Tri(tin, t, out a, out b, out c); return Slope.IsNotSteeper(a, b, c, SlopeSpec.Rise(steepest * (1 - 1e-12))); }));
            Assert.True(checks > 1000);
        }

        [Fact]
        public void SlopeSpec_Edges()
        {
            // exact where the value is a double: 1:2, 1:4, 50 %
            Assert.Equal(0.5, SlopeSpec.Ratio(2).S);
            Assert.Equal(0.25, SlopeSpec.Ratio(4).S);
            Assert.Equal(0.5, SlopeSpec.Percent(50).S);
            Assert.Equal(1.0, SlopeSpec.Degrees(45).S, 15);
            Assert.Equal(Math.Tan(Math.PI / 6), SlopeSpec.Degrees(30).S);
            // validity: positive, finite, S at least the smallest normal double
            Assert.True(SlopeSpec.Rise(2.2250738585072014E-308).IsValid);
            Assert.False(SlopeSpec.Rise(2.2250738585072009E-308).IsValid);
            Assert.False(SlopeSpec.Rise(0).IsValid);
            Assert.False(SlopeSpec.Ratio(double.PositiveInfinity).IsValid);
            Assert.False(SlopeSpec.Percent(double.PositiveInfinity).IsValid);
            Assert.False(SlopeSpec.Percent(4.9e-324).IsValid);
            Assert.False(SlopeSpec.Ratio(0).IsValid);
            Assert.False(SlopeSpec.Degrees(-1).IsValid);
            Assert.Equal("1:1.5", SlopeSpec.Ratio(1.5).ToString());
            Assert.Equal("50 %", SlopeSpec.Percent(50).ToString());
            Assert.Equal("30 deg", SlopeSpec.Degrees(30).ToString());
            Assert.Equal("s = 0.25", SlopeSpec.Rise(0.25).ToString());
        }

        [Fact]
        public void NonFinite_And_DegenerateSupport_AreRejected()
        {
            Vector3d a = new Vector3d(0, 0, 0), b = new Vector3d(1, 0, 0), c = new Vector3d(0, 1, 0);
            var spec = SlopeSpec.Ratio(1);
            Assert.True(Slope.IsSupportedBy(a, b, c, new Vector3d(5, 5, 1), new Vector3d(6, 5, 1), spec));
            foreach (var bad in new[] { new Vector3d(double.NaN, 5, 1), new Vector3d(5, double.NaN, 1), new Vector3d(5, 5, double.NaN), new Vector3d(5, 5, double.PositiveInfinity) }) {
                Assert.False(Slope.IsSupportedBy(a, b, c, bad, new Vector3d(6, 5, 1), spec));
                Assert.False(Slope.IsSupportedBy(a, b, c, new Vector3d(6, 5, 1), bad, spec));
                Assert.False(Slope.IsNotSteeper(bad, b, c, spec));
                Assert.False(Slope.IsNotSteeper(a, bad, c, spec));
                Assert.False(Slope.IsNotSteeper(a, b, bad, spec));
            }
            // a triangle that is degenerate in XY has no plane over the toe
            Assert.False(Slope.IsPlaneOnOrBelow(a, new Vector3d(1, 1, 0), new Vector3d(2, 2, 5), new Vector3d(0, 0, 10)));
            // below / above with a clockwise triangle
            Assert.True(Slope.IsPlaneOnOrBelow(a, c, b, new Vector3d(3, 3, 0)));
            Assert.False(Slope.IsPlaneOnOrBelow(a, c, b, new Vector3d(3, 3, -1e-300)));
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The repairs of the realization of the slope surface (Terrain 1c): needle flips within their deviation share, and
    /// the stitching of dropped triangles (faces narrower than the rounding) without cracks.
    /// </summary>
    public class TerrainSlopeRepairTests
    {
        // a needle (a, b, c), 1e-9 thin, on the long edge ab of a fat triangle (b, a, d); c is 'zc' above the line ab
        static DMesh3 Needle(double zc)
        {
            var m = new DMesh3(false, false, false, true);
            int a = m.AppendVertex(new Vector3d(0, 0, 0)), b = m.AppendVertex(new Vector3d(10, 0, 0));
            int c = m.AppendVertex(new Vector3d(5, 1e-9, zc)), d = m.AppendVertex(new Vector3d(5, -3, 0));
            m.AppendTriangle(a, b, c, 1);
            m.AppendTriangle(b, a, d, 2);
            return m;
        }

        [Fact]
        public void NeedleFlip_WithinItsShare()
        {
            // the flip changes the surface at the crossing of the diagonals by about zc: made within the share, not beyond
            var m = Needle(1e-3);
            Assert.Equal(1, SlopeMap.FlipNeedles(m, 1e-6, 2e-3));
            Assert.All(m.TriangleIndices(), t => Assert.Equal(2, m.GetTriangleGroup(t)));    // the thicker one's piece
            foreach (int t in m.TriangleIndices()) {
                Index3i tv = m.GetTriangle(t);
                Assert.True(ExactPredicates.Orient2d(m.GetVertex(tv.a).xy, m.GetVertex(tv.b).xy, m.GetVertex(tv.c).xy) > 0);
            }
            var m2 = Needle(1e-3);
            Assert.Equal(0, SlopeMap.FlipNeedles(m2, 1e-6, 5e-4));
            // and not a fat triangle
            var m3 = Needle(1e-3);
            Assert.Equal(0, SlopeMap.FlipNeedles(m3, 1e-12, 1));
        }

        [Fact]
        public void Stitch_SplitsTheLongEdgeAtTheMiddleCorner()
        {
            // the triangle (e0, m, e1) with m exactly on e0 e1 was dropped; the other side (e1, e0, x) is split at m
            var mesh = new DMesh3(false, false, false, true);
            int e0 = mesh.AppendVertex(new Vector3d(0, 0, 0)), e1 = mesh.AppendVertex(new Vector3d(4, 0, 0)), mid = mesh.AppendVertex(new Vector3d(1, 0, 0));
            int x = mesh.AppendVertex(new Vector3d(2, -2, 0)), y = mesh.AppendVertex(new Vector3d(0.5, 1, 0)), z = mesh.AppendVertex(new Vector3d(2.5, 1, 0));
            mesh.AppendTriangle(e1, e0, x, 7);
            mesh.AppendTriangle(e0, mid, y, 3); mesh.AppendTriangle(mid, z, y, 3); mesh.AppendTriangle(mid, e1, z, 3);
            Assert.Equal(1, mesh.EdgeIndices().Count(e => mesh.IsBoundaryEdge(e) && mesh.GetEdgeV(e).a + mesh.GetEdgeV(e).b == e0 + e1
                                                                                  && (mesh.GetEdgeV(e).a == e0 || mesh.GetEdgeV(e).b == e0)));
            SlopeMap.stitch(mesh, new List<Index3i> { new Index3i(e0, mid, e1) });
            // no edge e0 e1 left, the two halves meet the upper side at m: the only boundary is the outer one
            Assert.True(mesh.FindEdge(e0, e1) < 0);
            Assert.True(mesh.FindEdge(mid, x) >= 0);
            Assert.False(mesh.IsBoundaryEdge(mesh.FindEdge(e0, mid)));
            Assert.False(mesh.IsBoundaryEdge(mesh.FindEdge(mid, e1)));
            Assert.Equal(5, mesh.TriangleCount);
            Assert.Equal(7, mesh.GetTriangleGroup(mesh.GetEdgeT(mesh.FindEdge(mid, x)).a));
            foreach (int t in mesh.TriangleIndices()) {
                Index3i tv = mesh.GetTriangle(t);
                Assert.True(ExactPredicates.Orient2d(mesh.GetVertex(tv.a).xy, mesh.GetVertex(tv.b).xy, mesh.GetVertex(tv.c).xy) > 0);
            }
        }

        [Fact]
        public void Realize_DropsAFaceNarrowerThanTheRounding_NoGapNoOverlap()
        {
            // At UTM magnitude (ulp(y) = 2^-30) two creases through a, ab and a line rising one ulp per 1000 m, bound a
            // sliver face S = (a, b, c) whose apex c (on the vertical x = x0 + 5) is 0.005 ulps above ab: exactly
            // counter-clockwise, collinear once rounded. Below it G = (a, d, b), above it K = (c, b, e, a).
            double x0 = 328375.25, y0 = 5642875.5, ulp = Math.Pow(2, -30);
            Assert.Equal(y0 + ulp, BitConverter.Int64BitsToDouble(BitConverter.DoubleToInt64Bits(y0) + 1));
            var K = new ExactSlopeKernel();
            int a = K.PointVertex(new Vector2d(x0, y0)), b = K.PointVertex(new Vector2d(x0 + 10, y0));
            int d = K.PointVertex(new Vector2d(x0 + 5, y0 - 5)), e = K.PointVertex(new Vector2d(x0 + 5, y0 + 5));
            int rising = K.PointLine(new Vector2d(x0, y0), new Vector2d(x0 + 1000, y0 + ulp));
            int vertical = K.PointLine(new Vector2d(x0 + 5, y0 - 1), new Vector2d(x0 + 5, y0 + 1));
            int c = K.Crossing(rising, vertical);
            Assert.True(K.Orient(a, b, c) > 0);
            Assert.Equal(new Vector2d(x0 + 5, y0), K.Rounded(c));

            var mesh = new DMesh3(false, false, false, true);
            var ids = new Dictionary<Vector2d, int>();
            Func<int, int> outVertex = (v) => {
                Vector2d r = K.Rounded(v);
                int o;
                if (ids.TryGetValue(r, out o) == false) { o = mesh.AppendVertex(new Vector3d(r.x, r.y, 0)); ids[r] = o; }
                return o;
            };
            // a fan from the first corner, at the exact corners (as the map triangulates: no triangle across collinear ones)
            Func<List<int>, List<Index3i>> fan = (v) => {
                var tris = new List<Index3i>();
                for (int i = 1; i + 1 < v.Count; ++i)
                    if (K.Orient(v[0], v[i], v[i + 1]) != 0) tris.Add(new Index3i(v[0], v[i], v[i + 1]));
                return tris;
            };
            var faces = new List<KeyValuePair<int, List<int>>> {
                new KeyValuePair<int, List<int>>(1, new List<int> { a, d, b }),
                new KeyValuePair<int, List<int>>(2, new List<int> { a, b, c }),
                new KeyValuePair<int, List<int>>(3, new List<int> { c, b, e, a }),
            };
            Assert.Equal(1, SlopeMap.append_faces(mesh, faces, fan, outVertex));

            // no overlap: every triangle strictly counter-clockwise (a kept sliver is a zero-area fold over G and K);
            // no gap: the areas sum to the outer quadrilateral's 50 m^2 (exact here: offsets from a are multiples of
            // 2^-30 below 16), and the only boundary is its four edges (a crack would leave ab or ac, cb open)
            double area2 = 0;
            foreach (int t in mesh.TriangleIndices()) {
                Index3i tv = mesh.GetTriangle(t);
                Vector2d p = mesh.GetVertex(tv.a).xy, q = mesh.GetVertex(tv.b).xy, r = mesh.GetVertex(tv.c).xy;
                Assert.True(ExactPredicates.Orient2d(p, q, r) > 0);
                area2 += (q.x - p.x) * (r.y - p.y) - (q.y - p.y) * (r.x - p.x);
            }
            Assert.Equal(100.0, area2);
            var outer = new HashSet<Index2i> {
                ordered(outVertex(a), outVertex(d)), ordered(outVertex(d), outVertex(b)),
                ordered(outVertex(b), outVertex(e)), ordered(outVertex(e), outVertex(a)) };
            var boundary = mesh.EdgeIndices().Where(mesh.IsBoundaryEdge).Select(x => ordered(mesh.GetEdgeV(x).a, mesh.GetEdgeV(x).b)).ToList();
            Assert.Equal(4, boundary.Count);
            Assert.True(outer.SetEquals(boundary));
            // G was split at c (two triangles of group 1), K kept its two
            Assert.Equal(2, mesh.TriangleIndices().Count(x => mesh.GetTriangleGroup(x) == 1));
            Assert.Equal(4, mesh.TriangleCount);
        }

        [Fact]
        public void DiagonalChange_IsAnUpperBound_AtNearlyParallelDiagonals()
        {
            // two needles on a 10 m edge ab at UTM magnitude, their apexes c and d 1e-9 to 1e-6 m either side: the
            // diagonals ab and cd cross at an angle of 1e-10 to 1e-7, where the crossing in doubles is off by far more
            // than ulps of z. The bound must be at least the exact change |z on ab - z on cd| at the exact crossing.
            var rng = new Random(5);
            int violations = 0, tested = 0;
            for (int it = 0; it < 2000; ++it) {
                double x0 = 328375.25 + rng.NextDouble() * 100, y0 = 5642875.5 + rng.NextDouble() * 100;
                double phi = rng.NextDouble() * 2 * Math.PI, off = Math.Pow(10, -9 + 3 * rng.NextDouble());
                Vector2d dir = new Vector2d(Math.Cos(phi), Math.Sin(phi)), nrm = dir.Perp;
                Func<double, double, double, Vector3d> at = (s, o, dz) => {
                    Vector2d p = new Vector2d(x0, y0) + s * dir + o * nrm;
                    return new Vector3d(p.x, p.y, -100 + s * 1.5 + dz);
                };
                Vector3d a = at(0, 0, 0), b = at(10, 0, 0);
                Vector3d c = at(2 + rng.NextDouble(), -off, (rng.NextDouble() - 0.5) * 1e-6);
                Vector3d d = at(7 + rng.NextDouble(), off, (rng.NextDouble() - 0.5) * 1e-6);
                if (ExactPredicates.Orient2d(a.xy, b.xy, c.xy) * ExactPredicates.Orient2d(a.xy, b.xy, d.xy) >= 0) continue;
                if (ExactPredicates.Orient2d(c.xy, d.xy, a.xy) * ExactPredicates.Orient2d(c.xy, d.xy, b.xy) >= 0) continue;
                double ch = SlopeMap.diagonal_change(a, b, c, d);
                // exact: z1 - z2 = N / den, den = u x w, N = (a.z - c.z) den + (r x w)(b.z - a.z) - (r x u)(d.z - c.z)
                Func<double, ExactDyadic> E = ExactDyadic.Of;
                ExactDyadic ux = E(b.x) - E(a.x), uy = E(b.y) - E(a.y), wx = E(d.x) - E(c.x), wy = E(d.y) - E(c.y);
                ExactDyadic rx = E(c.x) - E(a.x), ry = E(c.y) - E(a.y);
                ExactDyadic den = ux * wy - uy * wx;
                ExactDyadic N = (E(a.z) - E(c.z)) * den + (rx * wy - ry * wx) * (E(b.z) - E(a.z)) - (rx * uy - ry * ux) * (E(d.z) - E(c.z));
                ExactDyadic absN = N.Sign < 0 ? -N : N, absDen = den.Sign < 0 ? -den : den;
                if ((E(ch) * absDen - absN).Sign < 0) violations++;
                tested++;
            }
            Assert.True(tested > 1500);
            Assert.Equal(0, violations);
        }

        static Index2i ordered(int u, int v) { return u < v ? new Index2i(u, v) : new Index2i(v, u); }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// TerrainSlopeDesign.CompositeKinds.Replacement: only the part of the composite that replaces terrain triangles,
    /// with the replaced triangles and the terrain vertex of each of its vertices. With the other terrain triangles it is
    /// exactly the Full composite (the same triangles and vertices, as sets); invariance over Similarity.All(); reuse.
    /// </summary>
    public class TerrainSlopeReplacementTests
    {
        // a triangle by its corner positions, counter-clockwise in XY, starting at the smallest corner
        static string key(Vector3d a, Vector3d b, Vector3d c)
        {
            if (ExactPredicates.Orient2d(a.xy, b.xy, c.xy) < 0) { Vector3d x = b; b = c; c = x; }
            var v = new[] { a, b, c };
            int m = 0;
            for (int i = 1; i < 3; ++i) if (less(v[i], v[m])) m = i;
            return string.Join(";", Enumerable.Range(0, 3).Select(i => pos(v[(m + i) % 3])));
        }

        static bool less(Vector3d p, Vector3d q) => p.x != q.x ? p.x < q.x : p.y != q.y ? p.y < q.y : p.z < q.z;
        // (-0 as +0, as the composite takes the terrain's vertices where it cuts them)
        static string pos(Vector3d p) => $"{p.x + 0.0:R},{p.y + 0.0:R},{p.z + 0.0:R}";

        static List<string> triangles(DMesh3 m) => m.TriangleIndices().Select(t => {
            Index3i tv = m.GetTriangle(t);
            return key(m.GetVertex(tv.a), m.GetVertex(tv.b), m.GetVertex(tv.c));
        }).OrderBy(x => x, StringComparer.Ordinal).ToList();

        /// <summary> Replacement plus the terrain triangles not replaced, joined by CompositeTerrainVertices, is Full </summary>
        internal static void AssertReplacementIsFull(TerrainSlopeDesign full, TerrainSlopeDesign repl)
        {
            Assert.Equal(full.Status, repl.Status);
            Assert.Null(repl.Composite);
            if (full.Composite == null) { Assert.Null(repl.Replacement); return; }
            DMesh3 terrain = full.Terrain, r = repl.Replacement;
            Assert.NotNull(r);
            Assert.Equal(full.ReplacedTerrainTriangles, repl.ReplacedTerrainTriangles);
            Assert.Equal(full.ReplacedTerrainTriangles.OrderBy(x => x).Distinct(), full.ReplacedTerrainTriangles);
            Assert.Equal("", Invariance.Difference(full.SlopeRegion, repl.SlopeRegion));
            var replaced = new HashSet<int>(repl.ReplacedTerrainTriangles);
            var kept = terrain.TriangleIndices().Where(t => replaced.Contains(t) == false).ToList();
            // the same triangles
            var joined = triangles(r);
            foreach (int t in kept) {
                Index3i tv = terrain.GetTriangle(t);
                joined.Add(key(terrain.GetVertex(tv.a), terrain.GetVertex(tv.b), terrain.GetVertex(tv.c)));
            }
            joined.Sort(StringComparer.Ordinal);
            Assert.Equal(triangles(full.Composite), joined);
            // the same vertices
            var keptVerts = new HashSet<int>(kept.SelectMany(t => { Index3i tv = terrain.GetTriangle(t); return new[] { tv.a, tv.b, tv.c }; }));
            // (as sets; the counts with their multiplicity below)
            var fullPos = full.Composite.Vertices().Select(pos).Distinct().OrderBy(x => x, StringComparer.Ordinal).ToList();
            var joinedPos = r.Vertices().Select(pos).Concat(keptVerts.Select(v => pos(terrain.GetVertex(v)))).Distinct()
                .OrderBy(x => x, StringComparer.Ordinal).ToList();
            Assert.Equal(fullPos, joinedPos);
            // the join: a vertex of the replacement names the terrain vertex at its position, and every kept terrain
            // vertex at a replacement vertex is named (so joining by the map gives the full composite's sharing)
            Assert.NotNull(repl.CompositeTerrainVertices);
            Assert.Equal(r.MaxVertexID, repl.CompositeTerrainVertices.Length);
            var named = new HashSet<int>();
            var replPos = new Dictionary<string, int>();
            foreach (int v in r.VertexIndices()) {
                replPos[pos(r.GetVertex(v))] = v;
                int tv = repl.CompositeTerrainVertices[v];
                if (tv < 0) continue;
                Assert.Equal(pos(terrain.GetVertex(tv)), pos(r.GetVertex(v)));
                named.Add(tv);
            }
            // (one terrain vertex per position: with one vertex per position every kept one there is named)
            foreach (int v in keptVerts)
                if (replPos.ContainsKey(pos(terrain.GetVertex(v))))
                    Assert.Contains(pos(terrain.GetVertex(v)), named.Select(x => pos(terrain.GetVertex(x))));
            // joined through TerrainCompositeVertices (every terrain vertex names the replacement vertex at its position,
            // also several at one position): exactly the full composite's vertices, as many as it has
            Assert.NotNull(repl.TerrainCompositeVertices);
            int joinedCount = r.VertexCount;
            foreach (int v in keptVerts) {
                int cv = repl.TerrainCompositeVertices[v];
                string pv = pos(terrain.GetVertex(v));
                // (a named one is the replacement vertex at its position; one not named is its own vertex, as in the full
                // composite, also at a replacement position: the other side of an unwelded seam stays unwelded)
                if (cv >= 0) Assert.Equal(replPos[pv], cv);
                else joinedCount++;
            }
            Assert.Equal(full.Composite.VertexCount, joinedCount);
            foreach (int v in terrain.VertexIndices()) {
                int cv = full.TerrainCompositeVertices[v];
                if (cv >= 0) Assert.Equal(pos(terrain.GetVertex(v)), pos(full.Composite.GetVertex(cv)));
            }
            // and the full composite names its terrain vertices too
            foreach (int v in full.Composite.VertexIndices()) {
                int tv = full.CompositeTerrainVertices[v];
                if (tv >= 0) Assert.Equal(pos(terrain.GetVertex(tv)), pos(full.Composite.GetVertex(v)));
            }
        }

        [Theory]
        [InlineData(0, false)]
        [InlineData(1, false)]
        [InlineData(2, true)]
        [InlineData(3, true)]
        public void RandomTerrains_ReplacementPlusTerrainIsFull(int seed, bool utm)
        {
            int checkedCases = 0;
            for (int it = 0; it < 6; ++it) {
                var full = TerrainSlopeCatchLineTests.RandomTerrainCase(seed, utm, it);
                var repl = TerrainSlopeCatchLineTests.RandomTerrainCase(seed, utm, it);
                repl.CompositeKind = TerrainSlopeDesign.CompositeKinds.Replacement;
                full.Compute(); repl.Compute();
                AssertReplacementIsFull(full, repl);
                if (full.Composite != null) {
                    checkedCases++;
                    // much smaller than the terrain: only the cut triangles are replaced
                    Assert.True(repl.Replacement.TriangleCount < full.Composite.TriangleCount);
                    Assert.True(repl.ReplacedTerrainTriangles.Count > 0);
                }
            }
            Assert.True(checkedCases > 0);
        }

        [Fact]
        public void Fill_ReplacementPlusTerrainIsFull()
        {
            Func<TerrainSlopeDesign> make = () => {
                var terrain = TerrainSlopeCatchLineTests.Grid(new AxisAlignedBox2d(-50, -50, 50, 50), 20, 20, (x, y) => -6 + 0.05 * x, flip: true);
                var toe = SlopeToe.Constant(TerrainSlopeDesignTests.Square(8, 0), true, SlopeToe.Sides.Outside, SlopeSpec.Ratio(3));
                toe.FillStart = toe.CutStart; toe.CutStart = null;
                return new TerrainSlopeDesign() { Toes = { toe }, Terrain = terrain, Tolerance = 0.05, Direction = TerrainSlopeDesign.Directions.Fill, BuildComposite = true };
            };
            var full = make(); var repl = make();
            repl.CompositeKind = TerrainSlopeDesign.CompositeKinds.Replacement;
            Assert.True(full.Compute(), full.Message);
            Assert.True(repl.Compute(), repl.Message);
            AssertReplacementIsFull(full, repl);
        }

        [Fact]
        public void Replacement_IsReusable()
        {
            var d = TerrainSlopeCatchLineTests.RandomTerrainCase(2, true, 0);
            d.CompositeKind = TerrainSlopeDesign.CompositeKinds.Replacement;
            d.Compute();
            Assert.NotNull(d.Replacement);
            DMesh3 first = d.Replacement;
            var replaced = d.ReplacedTerrainTriangles.ToList();
            var map = d.CompositeTerrainVertices.ToArray();
            d.Compute();
            Assert.Equal("", Invariance.Difference(first, d.Replacement));
            Assert.Equal(replaced, d.ReplacedTerrainTriangles);
            Assert.Equal(map, d.CompositeTerrainVertices);
            // and back to Full on the same instance: no replacement left over
            d.CompositeKind = TerrainSlopeDesign.CompositeKinds.Full;
            d.Compute();
            Assert.Null(d.Replacement);
            Assert.NotNull(d.Composite);
        }

        [Fact]
        public void TerrainTriangleAroundThePit_IsNotWhollyReplaced()
        {
            // two terrain triangles over 30 x 30 m at z 30, above the cap at 20: the slope surface covers both and lies
            // below the terrain everywhere, so every overlay face is in the region and every terrain corner is on the
            // slope surface. But the pit (the toe, a hole of the slope surface) lies inside them: they must not be skipped
            // as wholly replaced, the pit floor stays terrain (the area check of AssertComposite)
            var terrain = new DMesh3(false, false, false, true);
            int a = terrain.AppendVertex(new Vector3d(-15, -15, 30)), b = terrain.AppendVertex(new Vector3d(15, -15, 30));
            int c = terrain.AppendVertex(new Vector3d(15, 15, 30)), d = terrain.AppendVertex(new Vector3d(-15, 15, 30));
            terrain.AppendTriangle(a, b, c); terrain.AppendTriangle(a, c, d);
            foreach (var kind in new[] { TerrainSlopeDesign.CompositeKinds.Full, TerrainSlopeDesign.CompositeKinds.Replacement }) {
                var toe = SlopeToe.Constant(TerrainSlopeDesignTests.Square(8, 0), true, SlopeToe.Sides.Outside, SlopeSpec.Ratio(1));
                var dsg = new TerrainSlopeDesign() { Toes = { toe }, Terrain = terrain, HeightLimit = 20, Tolerance = 0.05, BuildComposite = true, CompositeKind = kind };
                dsg.Compute();
                Assert.True(dsg.Status == TerrainSlopeDesign.Statuses.NoDaylight || dsg.Status == TerrainSlopeDesign.Statuses.Success, dsg.Status + " " + dsg.Message);
                if (kind == TerrainSlopeDesign.CompositeKinds.Full) {
                    TerrainSlopeCatchLineTests.AssertComposite(dsg);
                } else {
                    // both terrain triangles are replaced, and the replacement holds the pit floor (terrain group)
                    Assert.Equal(new List<int> { 0, 1 }, dsg.ReplacedTerrainTriangles);
                    double floor = dsg.Replacement.TriangleIndices().Where(t => dsg.Replacement.GetTriangleGroup(t) == dsg.Pieces.Count)
                        .Sum(t => dsg.Replacement.GetTriArea(t));
                    Assert.True(floor > 0.99 * 16 * 16, $"pit floor {floor}");
                }
            }
        }

        [Fact]
        public void TerrainAboveTheSlopeAwayFromTheRegion_StaysTerrain()
        {
            // a pit at z 0 in flat terrain at z 3 (the region ends 3 m from the toe), and 30 m away a plateau at z 60, above
            // the slope there (about 30 m high; the cap at 50): its terrain triangles have no catch point, no boundary of
            // the slope surface and D < 0 everywhere, but they are not connected to the toe, so not in the region, and
            // stay terrain: no plateau triangle is replaced (it has no region face, so the whole-replaced test is not even
            // asked)
            Func<double, double, double> z = (x, y) => (Math.Abs(x - 30) <= 4 && Math.Abs(y) <= 4) ? 60 : 3;
            var terrain = TerrainSlopeCatchLineTests.Grid(new AxisAlignedBox2d(-50, -50, 50, 50), 100, 100, z);
            foreach (var kind in new[] { TerrainSlopeDesign.CompositeKinds.Full, TerrainSlopeDesign.CompositeKinds.Replacement }) {
                var toe = SlopeToe.Constant(TerrainSlopeDesignTests.Square(8, 0), true, SlopeToe.Sides.Outside, SlopeSpec.Ratio(1));
                var dsg = new TerrainSlopeDesign() { Toes = { toe }, Terrain = terrain, HeightLimit = 50, Tolerance = 0.05, BuildComposite = true, CompositeKind = kind };
                Assert.True(dsg.Compute(), dsg.Status + " " + dsg.Message);
                Assert.Single(dsg.CatchLines);
                if (kind == TerrainSlopeDesign.CompositeKinds.Full) {
                    TerrainSlopeCatchLineTests.AssertComposite(dsg);
                    // the volume is the region's only: the plateau, D < 0 but not connected to the toe, is not excavated
                    TerrainSlopeVolumeTests.AssertVolumesMatchComposite(dsg, false);
                }
                else {
                    // no plateau triangle is replaced
                    foreach (int t in dsg.ReplacedTerrainTriangles) {
                        Index3i tv = terrain.GetTriangle(t);
                        Assert.True(terrain.GetVertex(tv.a).x < 20, $"terrain triangle {t} replaced");
                    }
                }
            }
        }

        [Fact]
        public void UnweldedTerrain_ReplacementPlusTerrainIsFull()
        {
            // a terrain with a seam: the vertices of one grid column twice, the triangles right of it on the copies; the
            // seam runs through the pit, so the region is on both sides. Both copies of a vertex there name the one
            // replacement vertex
            Func<TerrainSlopeDesign> make = () => {
                var g = TerrainSlopeCatchLineTests.Grid(new AxisAlignedBox2d(-40, -40, 40, 40), 32, 32, (x, y) => 4 + 0.05 * x + 0.03 * y);
                var terrain = new DMesh3(false, false, false, true);
                foreach (int v in g.VertexIndices()) terrain.AppendVertex(g.GetVertex(v));
                double seam = 5;
                var copy = new Dictionary<int, int>();
                foreach (int t in g.TriangleIndices()) {
                    Index3i tv = g.GetTriangle(t);
                    var c = (g.GetVertex(tv.a) + g.GetVertex(tv.b) + g.GetVertex(tv.c)) / 3;
                    Func<int, int> map = (v) => {
                        if (c.x < seam || g.GetVertex(v).x != seam) return v;
                        int o;
                        if (copy.TryGetValue(v, out o) == false) { o = terrain.AppendVertex(g.GetVertex(v)); copy[v] = o; }
                        return o;
                    };
                    terrain.AppendTriangle(map(tv.a), map(tv.b), map(tv.c));
                }
                Assert.True(copy.Count > 10);
                var toe = SlopeToe.Constant(TerrainSlopeDesignTests.Square(8, 0), true, SlopeToe.Sides.Outside, SlopeSpec.Ratio(1));
                return new TerrainSlopeDesign() { Toes = { toe }, Terrain = terrain, HeightLimit = 30, Tolerance = 0.05, BuildComposite = true };
            };
            var full = make(); var repl = make();
            repl.CompositeKind = TerrainSlopeDesign.CompositeKinds.Replacement;
            full.Compute(); repl.Compute();
            Assert.NotNull(full.Composite);
            AssertReplacementIsFull(full, repl);
            // (the seam is in the replaced part: two terrain vertices name one replacement vertex)
            var named = repl.TerrainCompositeVertices.Where(v => v >= 0).GroupBy(v => v).Count(gr => gr.Count() > 1);
            Assert.True(named > 0, "no seam vertex in the replacement");
        }

        static Similarity ZUp(Similarity s) =>
            s.IsRotated ? new Similarity(s.Name + " (about z)", s.Scale, Matrix3d.AxisAngleD(Vector3d.AxisZ, 31), s.Translation) : s;

        static TerrainSlopeDesign Make(Similarity s, TerrainSlopeDesign.CompositeKinds kind)
        {
            var terrain = TerrainSlopeCatchLineTests.Grid(new AxisAlignedBox2d(-50, -50, 50, 50), 25, 23,
                (x, y) => 9 + 1.5 * Math.Sin(0.13 * x) * Math.Cos(0.09 * y));
            foreach (int v in terrain.VertexIndices().ToList()) terrain.SetVertex(v, s.Apply(terrain.GetVertex(v)));
            var toe = SlopeToe.Constant(TerrainSlopeCatchLineTests.Ngon(5, 9, 2, Vector2d.Zero, 0.2).Select(p => s.Apply(p)).ToList(),
                true, SlopeToe.Sides.Outside, SlopeSpec.Ratio(1.5));
            return new TerrainSlopeDesign() { Toes = { toe }, Terrain = terrain, Tolerance = s.ApplyLength(0.02), BuildComposite = true, CompositeKind = kind };
        }

        static readonly Lazy<TerrainSlopeDesign> reference = new Lazy<TerrainSlopeDesign>(() => {
            var d = Make(Similarity.Identity, TerrainSlopeDesign.CompositeKinds.Replacement);
            Assert.True(d.Compute(), d.Message);
            return d;
        });

        [Theory]
        [MemberData(nameof(Similarity.Names), MemberType = typeof(Similarity))]
        public void Similarities(string name)
        {
            // in every frame the replacement plus the terrain is the full composite; for 2^k scales the replacement,
            // the replaced triangles and the vertex map are those of the identity frame, bit for bit
            Similarity s = ZUp(Similarity.ByName(name));
            var full = Make(s, TerrainSlopeDesign.CompositeKinds.Full);
            var repl = Make(s, TerrainSlopeDesign.CompositeKinds.Replacement);
            Assert.True(full.Compute(), full.Status + " " + full.Message);
            Assert.True(repl.Compute(), repl.Status + " " + repl.Message);
            AssertReplacementIsFull(full, repl);
            if (s.IsExact) {
                var r = reference.Value;
                Assert.Equal("", Invariance.Difference(r.Replacement, Invariance.MappedBack(repl.Replacement, s)));
                Assert.Equal(r.ReplacedTerrainTriangles, repl.ReplacedTerrainTriangles);
                Assert.Equal(r.CompositeTerrainVertices, repl.CompositeTerrainVertices);
            }
        }
    }
}

