using System;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// A toe that crosses the terrain (part of it above, part below): the catch line runs from toe to toe, and the
    /// composite stays a height field where the region meets the toe at the crossings.
    /// </summary>
    public class TerrainSlopeToeCrossingTests
    {
        // a 7-gon pit at z 0 (r 11) in a plane tilted by g towards the angle rot, on a grid of 23 x 25 cells
        internal static TerrainSlopeDesign Make(double g, double c, double rot, bool fill, Similarity s)
        {
            var terrain = TerrainSlopeCatchLineTests.Grid(new AxisAlignedBox2d(-60, -60, 60, 60), 23, 25,
                (x, y) => g * (x * Math.Cos(rot) + y * Math.Sin(rot)) + c);
            foreach (int v in terrain.VertexIndices().ToList()) terrain.SetVertex(v, s.Apply(terrain.GetVertex(v)));
            var toe = SlopeToe.Constant(TerrainSlopeCatchLineTests.Ngon(7, 11, 0, Vector2d.Zero, 0.2).Select(p => s.Apply(p)).ToList(),
                true, SlopeToe.Sides.Outside, SlopeSpec.Ratio(fill ? 2 : 1.5));
            return new TerrainSlopeDesign() {
                Toes = { toe }, Terrain = terrain, Tolerance = s.ApplyLength(0.05), BuildComposite = true,
                Direction = fill ? TerrainSlopeDesign.Directions.Fill : TerrainSlopeDesign.Directions.Cut
            };
        }

        [Theory]
        [InlineData(0.15, 0.3, 0.0, false)]
        [InlineData(0.15, 0.3, 0.37, true)]
        [InlineData(0.23, -1.1, 1.3, false)]
        // the toe edge from a toe vertex to the crossing crosses terrain edges: the slope part along it took the edge as
        // one constraint, the terrain part beside it (the design side of the cut terrain triangle) its pieces at those
        // crossings, rounded off the straight line: their triangles overlapped (CompositeFailed)
        [InlineData(0.07, 0.123, 2.1, false)]
        [InlineData(0.07, 0.123, 2.1, true)]
        public void CatchLineFromToeToToe_CompositeIsAHeightField(double g, double c, double rot, bool fill)
        {
            var d = Make(g, c, rot, fill, Similarity.Identity);
            Assert.True(d.Compute(), d.Status + " " + d.Message);
            TerrainSlopeCatchLineTests.AssertCatchLines(d, fill);
            TerrainSlopeCatchLineTests.AssertComposite(d, fill);
            Assert.Single(d.CatchLines);
            Assert.False(d.CatchLines[0].Closed);
            Assert.Equal(CatchLine.EndReasons.Toe, d.CatchLines[0].StartReason);
            Assert.Equal(CatchLine.EndReasons.Toe, d.CatchLines[0].EndReason);
        }

        static readonly Lazy<TerrainSlopeDesign> reference = new Lazy<TerrainSlopeDesign>(() => {
            var d = Make(0.07, 0.123, 2.1, false, Similarity.Identity);
            Assert.True(d.Compute(), d.Message);
            return d;
        });

        [Theory]
        [MemberData(nameof(Similarity.Names), MemberType = typeof(Similarity))]
        public void Similarities(string name)
        {
            Similarity s = Similarity.ByName(name);
            if (s.IsRotated) s = new Similarity(s.Name + " (about z)", s.Scale, Matrix3d.AxisAngleD(Vector3d.AxisZ, 31), s.Translation);
            var d = Make(0.07, 0.123, 2.1, false, s);
            Assert.True(d.Compute(), d.Status + " " + d.Message);
            TerrainSlopeCatchLineTests.AssertComposite(d);
            var r = reference.Value;
            Assert.Equal(r.CatchLines.Count, d.CatchLines.Count);
            if (s.IsExact) {
                Assert.Equal("", Invariance.Difference(r.Composite, Invariance.MappedBack(d.Composite, s)));
                Assert.Equal("", Invariance.Difference(r.SlopeRegion, Invariance.MappedBack(d.SlopeRegion, s)));
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using g3;
using gs;
using Xunit;
using Xunit.Abstractions;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// TERRAIN.md 5.7: the volumes between the terrain and the slope over the region, on the overlay. Checked against the
    /// exact value of a cone envelope over flat terrain, against TerrainVolumeDifference(Terrain, Composite) (an
    /// independent integration of the composite), per piece, under Similarity.All() and on reuse.
    /// </summary>
    public class TerrainSlopeVolumeTests
    {
        readonly ITestOutputHelper output;
        public TerrainSlopeVolumeTests(ITestOutputHelper output) { this.output = output; }

        [Theory]
        [InlineData(false)]
        [InlineData(true)]
        public void SquarePit_FlatTerrain_MatchesTheCone(bool fill)
        {
            // a square toe of side 16 at z 0, slope 1:1 (s = 1), flat terrain h = 6 above (cut) or below (fill): the region
            // reaches out to d = h / s; volume = int_0^{h/s} (h - s d) (P0 + 2 pi d) dd = P0 h^2 / (2 s) + pi h^3 / (3 s^2),
            // plan area = P0 h / s + pi (h / s)^2, slope area = plan area * sqrt(1 + s^2). The facets lie at most Tolerance
            // below the exact cone (cut), so the volume is at most Tolerance * plan area more
            double h = 6, s = 1, tol = 0.02, P0 = 4 * 16;
            var terrain = TerrainSlopeCatchLineTests.Grid(new AxisAlignedBox2d(-40, -40, 40, 40), 40, 40, (x, y) => fill ? -h : h);
            var toe = SlopeToe.Constant(TerrainSlopeDesignTests.Square(8, 0), true, SlopeToe.Sides.Outside, SlopeSpec.Ratio(1 / s));
            if (fill) { toe.FillStart = toe.CutStart; toe.CutStart = null; }
            var d = new TerrainSlopeDesign() { Toes = { toe }, Terrain = terrain, Tolerance = tol, BuildComposite = true,
                                               Direction = fill ? TerrainSlopeDesign.Directions.Fill : TerrainSlopeDesign.Directions.Cut };
            Assert.True(d.Compute(), d.Status + " " + d.Message);
            double V = P0 * h * h / (2 * s) + Math.PI * h * h * h / (3 * s * s);
            double A = P0 * h / s + Math.PI * (h / s) * (h / s);
            output.WriteLine($"volume {d.Volume:R} (cone {V:R}), plan area {d.PlanArea:R} ({A:R}), slope area {d.SlopeArea:R}");
            Assert.InRange(d.Volume, V - 1e-6 * V, V + tol * A * 1.01);
            Assert.InRange(d.PlanArea, A * (1 - 1e-3), A + (tol / s) * P0 * 1.5);
            Assert.InRange(d.SlopeArea, d.PlanArea * (Math.Sqrt(2) - 1e-3), d.PlanArea * Math.Sqrt(2) * (1 + 1e-3));
            // the pieces sum up
            Assert.Equal(d.Volume, d.Pieces.Sum(p => p.Volume), 9);
            Assert.All(d.Pieces, p => Assert.True(p.Volume > 0 && p.PlanArea > 0));
            // the composite's own volume against the terrain (an independent integration)
            AssertVolumesMatchComposite(d, fill);
        }

        internal static void AssertVolumesMatchComposite(TerrainSlopeDesign d, bool fill)
        {
            var tvd = new TerrainVolumeDifference(d.Terrain, d.Composite);
            Assert.True(tvd.Compute());
            double other = fill ? tvd.FillVolume : tvd.CutVolume, wrong = fill ? tvd.CutVolume : tvd.FillVolume;
            // (the composite's catch points are snapped within MinFeatureSize: their effect is far below 1e-6)
            Assert.True(Math.Abs(other - d.Volume) <= 1e-6 * Math.Max(1, d.Volume), $"volume {d.Volume:R} vs composite {other:R}");
            Assert.True(wrong <= 1e-6 * Math.Max(1, d.Volume), $"the other direction {wrong:R}");
        }

        [Theory]
        [InlineData(0, false)]
        [InlineData(1, false)]
        [InlineData(2, true)]
        [InlineData(3, true)]
        public void RandomTerrains_MatchTheComposite(int seed, bool utm)
        {
            int n = 0;
            for (int it = 0; it < 6; ++it) {
                var d = TerrainSlopeCatchLineTests.RandomTerrainCase(seed, utm, it);
                if (d.Compute() == false && d.Status != TerrainSlopeDesign.Statuses.NoDaylight) continue;
                if (d.Composite == null) continue;
                bool fill = d.Direction == TerrainSlopeDesign.Directions.Fill;
                output.WriteLine($"{it}: fill {fill} volume {d.Volume:R} plan {d.PlanArea:R}");
                Assert.True(d.Volume > 0);
                AssertVolumesMatchComposite(d, fill);
                Assert.Equal(d.Volume, d.Pieces.Sum(p => p.Volume), 6);
                n++;
            }
            Assert.True(n > 0);
        }

        [Fact]
        public void RaisedCap_VolumeOfTheLastBuildOnly()
        {
            // the local height limit raised (the start estimate off): two builds, the first one reaching its cap; the
            // volume is the final build's (it was the sum of both), the pieces sum up to it, and it matches the composite
            var terrain = TerrainSlopeCatchLineTests.Grid(new AxisAlignedBox2d(-50, -50, 50, 50), 20, 20, (x, y) => 4 + 0.5 * x);
            var toe = SlopeToe.Constant(TerrainSlopeDesignTests.Square(8, 0), true, SlopeToe.Sides.Outside, SlopeSpec.Ratio(1));
            var d = new TerrainSlopeDesign() { Toes = { toe }, Terrain = terrain, Tolerance = 0.05, BuildComposite = true, CapEstimateRounds = 0 };
            Assert.True(d.Compute(), d.Message);
            Assert.True(d.CapRounds >= 2);
            Assert.Equal(d.Volume, d.Pieces.Sum(p => p.Volume), 9);
            AssertVolumesMatchComposite(d, false);
        }

        [Fact]
        public void Volumes_AreReusable()
        {
            var d = TerrainSlopeCatchLineTests.RandomTerrainCase(2, true, 0);
            Assert.True(d.Compute(), d.Status + " " + d.Message);
            double v = d.Volume, a = d.PlanArea, sa = d.SlopeArea;
            var per = d.Pieces.Select(p => p.Volume).ToList();
            d.Compute();
            Assert.Equal(v, d.Volume); Assert.Equal(a, d.PlanArea); Assert.Equal(sa, d.SlopeArea);
            Assert.Equal(per, d.Pieces.Select(p => p.Volume).ToList());
            // a failing run leaves none
            d.Tolerance = -1;
            Assert.False(d.Compute());
            Assert.Equal(0, d.Volume);
        }
    }
}

using System;
using System.Linq;
using g3;
using gs;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// Exact cut and fill volumes between two terrain surfaces (TINs), eg the survey before and after
    /// excavation. Both surfaces are piecewise linear, so the volumes are exact up to rounding.
    /// </summary>
    public class TerrainVolumeTests
    {
        // grid over [x0,x1] x [y0,y1] with n x n vertices, z = h(x,y); flip = other diagonal
        static DMesh3 Grid(double x0, double y0, double x1, double y1, int n, Func<double, double, double> h, bool flip = false)
        {
            DMesh3 mesh = new DMesh3();
            int[,] vid = new int[n, n];
            for (int j = 0; j < n; ++j)
                for (int i = 0; i < n; ++i) {
                    double x = x0 + (x1 - x0) * i / (n - 1), y = y0 + (y1 - y0) * j / (n - 1);
                    vid[i, j] = mesh.AppendVertex(new Vector3d(x, y, h(x, y)));
                }
            for (int j = 0; j + 1 < n; ++j)
                for (int i = 0; i + 1 < n; ++i) {
                    if (flip) {
                        mesh.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i, j + 1]);
                        mesh.AppendTriangle(vid[i + 1, j], vid[i + 1, j + 1], vid[i, j + 1]);
                    } else {
                        mesh.AppendTriangle(vid[i, j], vid[i + 1, j], vid[i + 1, j + 1]);
                        mesh.AppendTriangle(vid[i, j], vid[i + 1, j + 1], vid[i, j + 1]);
                    }
                }
            return mesh;
        }

        static TerrainVolumeDifference Run(DMesh3 before, DMesh3 after)
        {
            var v = new TerrainVolumeDifference(before, after);
            Assert.True(v.Compute());
            return v;
        }

        [Fact]
        public void ParallelSurfaces_DifferentTriangulations()
        {
            DMesh3 before = Grid(0, 0, 10, 10, 11, (x, y) => 0.1 * x + 0.05 * y);
            DMesh3 after = Grid(0, 0, 10, 10, 7, (x, y) => 0.1 * x + 0.05 * y + 2, true);
            var v = Run(before, after);
            Assert.Equal(200, v.FillVolume, 6);
            Assert.Equal(0, v.CutVolume, 6);
            Assert.Equal(100, v.OverlapArea, 6);
        }

        [Fact]
        public void CrossingSurfaces_CutAndFillSplitAtTheZeroLine()
        {
            // before z = 0, after z = x over [-1,1]^2: fill = cut = 1
            DMesh3 before = Grid(-1, -1, 1, 1, 2, (x, y) => 0);
            DMesh3 after = Grid(-1, -1, 1, 1, 5, (x, y) => x, true);
            var v = Run(before, after);
            Assert.Equal(1, v.FillVolume, 9);
            Assert.Equal(1, v.CutVolume, 9);
            Assert.Equal(0, v.NetVolume, 9);
        }

        [Fact]
        public void OpenPit_CutVolumeExact()
        {
            // after: an excavated pit (below the original ground everywhere); before: flat ground, coarse TIN
            DMesh3 after = Grid(-100, -100, 100, 100, 201, (x, y) => Pit(x, y));
            DMesh3 before = Grid(-100, -100, 100, 100, 3, (x, y) => 0);
            double expected = after.TriangleIndices().Sum(t => {
                Vector3d a = Vector3d.Zero, b = Vector3d.Zero, c = Vector3d.Zero;
                after.GetTriVertices(t, ref a, ref b, ref c);
                double area = 0.5 * Math.Abs((b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x));
                return area * -(a.z + b.z + c.z) / 3;      // exact integral of the linear depth
            });
            var v = Run(before, after);
            Assert.InRange(v.CutVolume, expected * (1 - 1e-9), expected * (1 + 1e-9));
            Assert.Equal(0, v.FillVolume, 6);
        }

        [Fact]
        public void PartialOverlap_OnlyCommonFootprintCounts()
        {
            DMesh3 before = Grid(0, 0, 10, 10, 6, (x, y) => 0);
            DMesh3 after = Grid(5, 0, 15, 10, 4, (x, y) => 1);
            var v = Run(before, after);
            Assert.Equal(50, v.OverlapArea, 6);
            Assert.Equal(50, v.FillVolume, 6);
        }

        [Fact]
        public void UtmCoordinates_SameResult()
        {
            Vector3d off = new Vector3d(632000, 5712000, 100);
            DMesh3 before = Grid(off.x - 1, off.y - 1, off.x + 1, off.y + 1, 2, (x, y) => off.z);
            DMesh3 after = Grid(off.x - 1, off.y - 1, off.x + 1, off.y + 1, 5, (x, y) => off.z + (x - off.x), true);
            var v = Run(before, after);
            Assert.Equal(1, v.FillVolume, 7);
            Assert.Equal(1, v.CutVolume, 7);
        }

        [Fact]
        public void TriangleSoupAndMixedOrientation()
        {
            DMesh3 before = Grid(0, 0, 10, 10, 11, (x, y) => 0);
            DMesh3 after = Grid(0, 0, 10, 10, 9, (x, y) => -3);
            // unweld and flip some triangles of after
            DMesh3 soup = new DMesh3();
            int k = 0;
            foreach (int tid in after.TriangleIndices()) {
                Index3i t = after.GetTriangle(tid);
                int a = soup.AppendVertex(after.GetVertex(t.a)), b = soup.AppendVertex(after.GetVertex(t.b)), c = soup.AppendVertex(after.GetVertex(t.c));
                if (k++ % 3 == 0) soup.AppendTriangle(a, c, b); else soup.AppendTriangle(a, b, c);
            }
            var v = Run(before, soup);
            Assert.Equal(300, v.CutVolume, 6);
        }

        // open pit as in TerrainDualContouringTests: flat bottom, four benches (10 m face over 8 m, 6 m berm)
        [Fact]
        public void IdenticalSurfaces_NoCutOrFillArea()
        {
            // eg the after survey reuses the before TIN outside the pit
            DMesh3 before = Grid(0, 0, 10, 10, 11, (x, y) => 0.1 * x + 0.05 * y);
            DMesh3 after = Grid(0, 0, 10, 10, 7, (x, y) => 0.1 * x + 0.05 * y);
            var v = Run(before, after);
            Assert.True(Math.Abs(v.CutVolume) < 1e-9 && Math.Abs(v.FillVolume) < 1e-9);
            Assert.True(v.CutArea < 1e-9 && v.FillArea < 1e-9, $"cut area {v.CutArea}, fill area {v.FillArea}");
            Assert.True(Math.Abs(v.OverlapArea - 100) < 1e-9);
        }

        [Fact]
        public void PartlyCoincident_AreasOnlyWhereTheSurfacesDiffer()
        {
            // after = before, except a hollow in x < 4 (on whole triangles of both meshes)
            DMesh3 before = Grid(0, 0, 10, 10, 11, (x, y) => 0);
            DMesh3 after = Grid(0, 0, 10, 10, 11, (x, y) => x < 3.5 ? -1 : 0);
            var v = Run(before, after);
            Assert.True(v.FillArea < 1e-9);
            // cut where after is below: x < 4 (x = 4 is the last vertex at 0, the slope runs 3 .. 4)
            Assert.True(Math.Abs(v.CutArea - 40) < 1e-9, $"cut area {v.CutArea}");
        }

        static double Pit(double x, double y)
        {
            double c = Math.Cos(17 * MathUtil.Deg2Rad), s = Math.Sin(17 * MathUtil.Deg2Rad);
            double u = c * x + s * y, v = -s * x + c * y;
            double r = Math.Max(Math.Abs(u) - 30, Math.Abs(v) - 15);
            double z = -40;
            for (int bench = 0; bench < 4; ++bench) {
                if (r <= 0) return z;
                double face = Math.Min(r, 8);
                z += 10 * face / 8;
                r -= 8;
                if (r <= 0) return z;
                r -= 6;
            }
            return z;
        }
    }
}

