using System.Collections.Generic;
using g3;
using gs;

namespace g3.Examples
{
    /// <summary>
    /// Distances: Hausdorff distance between two meshes (a certified interval) and geodesic distance on a
    /// mesh (heat method). Both leave the meshes unchanged.
    /// </summary>
    public static class DistancesExample
    {
        /// <summary> Symmetric Hausdorff distance; the exact value lies in [lower, upper]. Returns false if it failed. </summary>
        public static bool Hausdorff(DMesh3 a, DMesh3 b, out double lower, out double upper)
        {
            var hausdorff = new MeshHausdorffDistance(a, b) { Tolerance = 1e-4 };   // absolute; default: 1e-4 of the bounding box diagonal
            bool ok = hausdorff.Compute();
            lower = hausdorff.LowerBound;
            upper = hausdorff.UpperBound;    // hausdorff.WorstPoint: where it is attained
            return ok && hausdorff.Converged;
        }

        /// <summary>
        /// Geodesic distance from vertex source to every vertex (by vertex id; NaN if unreachable), or null.
        /// Accuracy about 2% plus half the mean edge length; near open boundaries 2% plus one mean edge length.
        /// </summary>
        public static double[] Geodesic(DMesh3 mesh, int source, out List<Vector3d> pathToFarthest)
        {
            var geodesic = new MeshGeodesicDistance(mesh);
            pathToFarthest = null;
            if (!geodesic.Compute(new[] { source }))
                return null;
            int farthest = source;
            foreach (int vid in mesh.VertexIndices())
                if (geodesic.Distance[vid] > geodesic.Distance[farthest])
                    farthest = vid;
            pathToFarthest = geodesic.TracePath(farthest);    // polyline back to the nearest source
            return geodesic.Distance;
        }
    }
}

using g3;

namespace g3.Examples
{
    /// <summary>
    /// Exact mesh booleans: union, intersection and difference of two closed meshes with exact arithmetic.
    /// Coplanar and touching inputs give closed results; only the output coordinates are rounded to double.
    /// </summary>
    public static class ExactMeshBooleanExample
    {
        /// <summary> Unit cube minus a box that cuts through it (coplanar faces included). Returns null and the error if Compute() fails. </summary>
        public static DMesh3 Run(ExactMeshBoolean.Operations operation, out string error)
        {
            DMesh3 cube = new TrivialBox3Generator() { Box = new Box3d(new Vector3d(0.5, 0.5, 0.5), new Vector3d(0.5, 0.5, 0.5)) }.Generate().MakeDMesh();
            // 0.5 x 0.5 x 2 bar through the cube; its top and bottom are outside, two of its sides are coplanar with the cube's
            DMesh3 bar = new TrivialBox3Generator() { Box = new Box3d(new Vector3d(0.25, 0.25, 0.5), new Vector3d(0.25, 0.25, 1)) }.Generate().MakeDMesh();

            var boolean = new ExactMeshBoolean(cube, bar, operation);   // the inputs are not modified
            if (!boolean.Compute()) {
                error = boolean.Error;                                   // why it failed (eg an input is not closed and AllowOpenMeshes = false)
                return null;
            }
            error = null;
            return boolean.Result;                                       // a new mesh

            // ExactMeshBoolean.Resolve(mesh) does the same for one self-intersecting mesh (the boundary of its solid)
        }

        /// <summary>
        /// Union of the unit cube and a copy turned by 1e-11 radians: the intersection points nearly coincide, so
        /// rounding them to double leaves slivers. SafeRounding repairs them; clean tells whether the result has no
        /// self-intersections and no degenerate triangles (checked exactly).
        /// </summary>
        public static DMesh3 NearlyCoincidentUnion(out bool clean)
        {
            DMesh3 cube = new TrivialBox3Generator() { Box = new Box3d(new Vector3d(0.5, 0.5, 0.5), new Vector3d(0.5, 0.5, 0.5)) }.Generate().MakeDMesh();
            DMesh3 turned = new DMesh3(cube);
            MeshTransforms.Rotate(turned, new Vector3d(0.5, 0.5, 0.5), new Quaterniond(new Vector3d(0.3, 0.5, 0.8).Normalized, 1e-11 * MathUtil.Rad2Deg));

            var boolean = new ExactMeshBoolean(cube, turned, ExactMeshBoolean.Operations.Union) { SafeRounding = true };   // (the default, set here to show it)
            boolean.Compute();
            clean = boolean.RoundingClean;
            return boolean.Result;
            // ComputeExactVertices = true would give the exact rational coordinates instead (ResultExactVertices)
        }

        /// <summary>
        /// Three overlapping boxes in one operation: the region inside at least two of them (a winding number
        /// predicate over all inputs). Status says why Compute() failed, if it did.
        /// </summary>
        public static DMesh3 AtLeastTwoOfThree(out ExactMeshBoolean.BooleanStatus status)
        {
            var boxes = new System.Collections.Generic.List<DMesh3>();
            foreach (double x in new[] { 0.0, 0.5, 1.0 })      // unit cubes along x, each overlapping the next by 0.5
                boxes.Add(new TrivialBox3Generator() { Box = new Box3d(new Vector3d(x + 0.5, 0.5, 0.5), new Vector3d(0.5, 0.5, 0.5)) }.Generate().MakeDMesh());

            var boolean = new ExactMeshBoolean(boxes, ExactMeshBoolean.AtLeast(2));
            // the same with any predicate on the winding numbers w[i] of the inputs, eg the symmetric difference:
            //   new ExactMeshBoolean(boxes, w => (w[0] > 0) ^ (w[1] > 0) ^ (w[2] > 0))
            // and the n-ary operations: new ExactMeshBoolean(boxes, ExactMeshBoolean.Operations.Union)
            boolean.Compute();
            status = boolean.Status;                                     // Success, InvalidInput or OpenInput
            return boolean.Result;                                       // null unless Success
        }
    }
}

using g3;
using gs;

namespace g3.Examples
{
    /// <summary>
    /// Comparing a result (repair, remesh, solidify, wrap) with its input beyond Hausdorff distance and volume IoU:
    /// F-score at a threshold, normals (reversed patches), sharp edges (lost features), the volume IoU against the
    /// solid of the input's outer faces (interior faces do not distort it), curvature, triangle quality and topology. MeshFidelityMetrics is read-only and deterministic (seeded samples); all distances are relative to
    /// the input's size.
    /// </summary>
    public static class FidelityMetricsExample
    {
        public class Report
        {
            /// <summary> F-score at 1% of the size: 1 = every part of either surface is that close to the other </summary>
            public double FScore;
            /// <summary> the same against the input's outer surface only (interior faces that a repair drops do not count) </summary>
            public double OuterFScore;
            /// <summary> share of the result's surface near the input (within 1%) whose normals point against the input's </summary>
            public double Reversed;
            /// <summary> Edge Chamfer distance (relative), and the share of the input's sharp edges kept within 0.5% </summary>
            public double EdgeChamfer, EdgeRecall;
            /// <summary> volume IoU of the result against the solid of the input's outer faces (NaN if the input encloses nothing) </summary>
            public double OuterVolumeIoU;
            /// <summary> mean difference of the mean curvature at corresponding points, times the size (2 on a sphere) </summary>
            public double MeanCurvatureError;
            /// <summary> what changed: components, handles, boundary loops </summary>
            public MeshTopologySummary.Changes TopologyChanges;
            /// <summary> the min angle that 1% of the result's triangles are below (degrees) </summary>
            public double MinAngle1Percent;
        }

        public static Report Compare(DMesh3 input, DMesh3 result)
        {
            var f = new MeshFidelityMetrics(input, result) { RelativeThresholds = new[] { 0.005, 0.01 } };
            if (f.Compute() == false)
                return null;        // an empty or non-finite mesh
            return new Report() {
                FScore = f.FScore[1],
                OuterFScore = f.OuterFScore[1],
                Reversed = f.NormalsMeshToReference.ReversedFraction,
                EdgeChamfer = f.EdgeChamfer,
                EdgeRecall = f.EdgeRecall[0],
                OuterVolumeIoU = f.OuterVolumeIoU,
                MeanCurvatureError = f.MeanCurvatureError,
                TopologyChanges = f.TopologyChanges,
                MinAngle1Percent = f.MeshQuality.MinAngle.Worst1Percent
            };
        }
    }
}

