            report.FoldedEdges = MeshRepairMetrics.FoldedEdges(mesh).Count;    // dihedral angle above 175 degrees
            report.NotCleanReason = MeshRobustRepair.NotCleanReason(mesh);     // "" = closed, manifold, no self-intersections
            return report;
